    internal static class AllflameVersion
    {
        public const string Current = "0.23.161";
    }

    public sealed class AllflameBot : IBot
    {
        private readonly TaskManager _taskManager = new TaskManager();
        private LokiCoroutine _coroutine;
        private AllflameBotGui _control;
        private bool _initialized;
        private bool _started;
        private bool _coroutineFaulted;
        private bool _coroutineFaultLogged;
        private DateTime _lastCoroutineActivityUtc = DateTime.MinValue;

        public string Name { get { return "Allflame Bot"; } }
        public string Description { get { return "Chart Area runner for PoE 3.29 Allflame/Deepwater content."; } }
        public string Author { get { return "BoTBien"; } }
        public string Version { get { return AllflameVersion.Current; } }
        public UserControl Control
        {
            get
            {
                if (_control == null)
                {
                    _control = new AllflameBotGui();
                }
                return _control;
            }
        }
        public JsonSettings Settings { get { return AllflameSettings.Instance; } }

        public void Initialize()
        {
            if (_initialized)
            {
                return;
            }

            AllflameLog.Initialize();
            AllflameSettings.LogStorageStatus();
            AllflamePrices.Initialize();
            DpbNativeApi.LogCapabilities();
            AllflameLog.Info(
                "BOT_INITIALIZE|Version=" + Version +
                "|Mode=Active");

            _taskManager.Add(new UpdateDeepwaterStateTask());
            _taskManager.Add(new ChartAreaTransitionTask());
            _taskManager.Add(new RespawnTask());
            _taskManager.Add(new UseLifeFlaskTask());
            _taskManager.Add(new UseEnduringCryTask());
            _taskManager.Add(new TravelToSovereignTask());
            _taskManager.Add(new MoveToBoatStagingTask());
            _taskManager.Add(new DebugChartStorageTask());
            _taskManager.Add(new CollectSulphurRewardTask());
            _taskManager.Add(new SecretBottleProcessingTask());
            _taskManager.Add(new StashLootTask());
            _taskManager.Add(new PreVoyageChartStashTask());
            _taskManager.Add(new EnterStartedVoyageTask());
            _taskManager.Add(new ExtractTask());
            _taskManager.Add(new WaitForBathysphereTask());
            _taskManager.Add(new UseAllflameCapsuleTask());
            _taskManager.Add(new CollectLootTask());
            _taskManager.Add(new PrepareVoyageTask());
            _taskManager.Add(new OpenChartStorageTask());
            _taskManager.Add(new OpenVoyageStashTask());
            _taskManager.Add(new IdentifyInventoryChartsTask());
            _taskManager.Add(new PlanVoyageTask());
            _taskManager.Add(new EnterBathysphereTask());
            _taskManager.Add(new ReturnToHubTask());
            _taskManager.Add(new MoveToDeepwaterChestTask());
            _taskManager.Add(new OpenDeepwaterChestsTask());
            _taskManager.Add(new LootGroundItemsTask());
            _taskManager.Add(new VisitAllflameCapsuleTask());
            _taskManager.Add(new InteractLanternTask());
            _taskManager.Add(new ExploreVoyageTask());
            _taskManager.Add(new ExploreEncounterTask());
            _taskManager.Add(new StuckRecoveryTask());
            _taskManager.Add(new ObservationFallbackTask());
            _taskManager.Freeze();

            _initialized = true;
        }

        public void Deinitialize()
        {
            Stop();
            AllflameLog.Info("BOT_DEINITIALIZE");
        }

        public void Start()
        {
            if (_started)
            {
                bool healthy = IsCoroutineHealthy();
                if (healthy)
                {
                    return;
                }

                CleanupStaleRuntimeForRestart();
                AllflameLog.Info(
                    "BOT_COROUTINE_REBUILT" +
                    "|Reason=StaleOrFaultedRuntime");
            }

            if (!_initialized)
            {
                Initialize();
            }

            AllflameContext.Reset();
            AllflameRunState.Reset();
            VoyageRunState.Reset();
            AllflameLootState.Clear();
            AllflameStopController.Reset();
            AllflameMovementCoordinator.Reset();
            AllflameProgressWatchdog.Reset();
            VoyageRunnerMetrics.Reset();
            AllflameVoyageDebug.Reset();
            AllflameSession.Start();
            EnsureProcessHook();
            EnsurePlayerMover();
            _taskManager.Start();
            _coroutine = new LokiCoroutine(new Func<Task<object>>(MainLoop));
            _coroutineFaulted = false;
            _coroutineFaultLogged = false;
            _lastCoroutineActivityUtc = DateTime.UtcNow;
            _started = true;
            AllflameNotifications.StartSessionDashboard();
            AllflameLog.Info(
                "BOT_START|Mode=Active|ChartAreaAutomation=" +
                AllflameSettings.Instance.AutoRunChartAreas +
                "|InventoryChartsOnly=" +
                AllflameSettings.Instance.RunInventoryChartsOnly +
                "|PlayerMover=" +
                (PlayerMoverManager.Current == null
                    ? "None"
                    : PlayerMoverManager.Current.Name));

            if (AllflamePrices.ShouldAutoUpdate())
            {
                Task.Run(async delegate
                {
                    await AllflamePrices.UpdateAsync(
                        AllflameSettings.Instance.PricingLeague);
                });
            }
        }

        private static void EnsurePlayerMover()
        {
            if (PlayerMoverManager.Current != null)
            {
                return;
            }

            try
            {
                IPlayerMover mover = PlayerMoverManager.PlayerMovers
                    .FirstOrDefault(x => x.Name == "Allflame Mover");
                if (mover == null)
                {
                    AllflameLog.Info(
                        "MOVER_NOT_FOUND|Expected=Allflame Mover|Chart automation cannot move.");
                    return;
                }

                PlayerMoverManager.Current = mover;
                PlayerMoverManager.Start(mover);
                AllflameLog.Info("MOVER_SELECTED|Name=" + mover.Name);
            }
            catch (Exception ex)
            {
                AllflameLog.Error("MOVER_SELECT_FAILED", ex);
            }
        }

        private static void EnsureProcessHook()
        {
            try
            {
                if (!LokiPoe.ProcessHookManager.IsEnabled)
                {
                    LokiPoe.ProcessHookManager.Enable();
                }

                AllflameLog.Info(
                    "PROCESS_HOOK|Enabled=" + LokiPoe.ProcessHookManager.IsEnabled +
                    "|State=" + LokiPoe.ProcessHookManager.State);
            }
            catch (Exception ex)
            {
                AllflameLog.Error("PROCESS_HOOK_ENABLE_FAILED", ex);
            }
        }

        public void Stop()
        {
            if (!_started)
            {
                return;
            }

            _started = false;
            string stopSource =
                AllflameStopController.StopRequested
                    ? "RecoveryStop"
                    : "UserStop";
            try
            {
                if (_coroutine != null)
                {
                    _coroutine.Dispose();
                }
            }
            catch (Exception ex)
            {
                bool cancelled = String.Equals(
                    ex.GetType().Name,
                    "CoroutineStoppedException",
                    StringComparison.Ordinal);
                AllflameLog.Info(
                    (cancelled
                        ? "BOT_COROUTINE_DISPOSE_CANCELLED"
                        : "BOT_COROUTINE_DISPOSE_FAILED") +
                    "|Type=" + ex.GetType().Name +
                    "|Source=" +
                    stopSource +
                    "|RecoveryAction=ContinueCleanup" +
                    "|Context=" + AllflameProgressWatchdog.Describe());
            }
            finally
            {
                _coroutine = null;
                _coroutineFaulted = false;
                _coroutineFaultLogged = false;
                _lastCoroutineActivityUtc = DateTime.MinValue;
            }

            string stopContext = AllflameProgressWatchdog.Describe();
            _taskManager.Stop();
            AllflameProgressWatchdog.Reset();
            VoyageRunnerMetrics.Reset();
            AllflameVoyageDebug.Reset();
            AllflameNotifications.SendStoppedSummary(stopSource);
            AllflameLog.Info(
                "BOT_STOP|Source=" + stopSource +
                "|StopReason=" +
                AllflameStopController.StopReason +
                "|StopDetail=" +
                AllflameStopController.StopDetail +
                "|Context=" + stopContext);
            CloseGameOnStop(stopSource);
        }

        private static void CloseGameOnStop(string stopSource)
        {
            if (!AllflameSettings.Instance.CloseGameOnStop)
            {
                return;
            }

            if (LokiPoe.ClientWindowHandle == IntPtr.Zero)
            {
                AllflameLog.Info(
                    "CLOSE_GAME_ON_STOP" +
                    "|Source=" + stopSource +
                    "|Result=Skipped" +
                    "|Reason=ClientWindowUnavailable");
                return;
            }

            try
            {
                var result = LokiPoe.EscapeState.ExitGame();
                AllflameLog.Info(
                    "CLOSE_GAME_ON_STOP" +
                    "|Source=" + stopSource +
                    "|Result=" + result);
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "CLOSE_GAME_ON_STOP" +
                    "|Source=" + stopSource +
                    "|Result=Exception" +
                    "|Type=" + ex.GetType().Name +
                    "|Message=" +
                    (ex.Message ?? String.Empty)
                        .Replace("|", "/"));
            }
        }

        public void Tick()
        {
            if (!_started)
            {
                return;
            }

            _taskManager.Tick();
            AllflameNotifications.Tick();
            if (_coroutine != null && !_coroutine.IsFinished)
            {
                try
                {
                    _coroutine.Resume();
                    _lastCoroutineActivityUtc = DateTime.UtcNow;
                }
                catch (Exception ex)
                {
                    bool cancelled = String.Equals(
                        ex.GetType().Name,
                        "CoroutineStoppedException",
                        StringComparison.Ordinal);
                    if (cancelled)
                    {
                        AllflameLog.Info(
                            "BOT_COROUTINE_RESUME_CANCELLED" +
                            "|Type=" + ex.GetType().Name +
                            "|Source=" +
                            (AllflameStopController.StopRequested
                                ? "RecoveryStop"
                                : "UserStop") +
                            "|Context=" +
                            AllflameProgressWatchdog.Describe());
                        return;
                    }

                    _coroutineFaulted = true;
                    if (!_coroutineFaultLogged)
                    {
                        _coroutineFaultLogged = true;
                        AllflameLog.Info(
                            "BOT_COROUTINE_FAULT" +
                            "|Type=" + ex.GetType().Name +
                            "|Message=" +
                            (ex.Message ?? String.Empty).Replace("|", "/") +
                            "|Context=" +
                            AllflameProgressWatchdog.Describe());
                    }
                    // Rebuild the runtime in place. A transient DPB/GUI fault
                    // must not stop the bot or leave the failed coroutine hot.
                    AllflameLog.Info(
                        "BOT_COROUTINE_RECOVERY" +
                        "|Action=RebuildRuntime" +
                        "|Type=" + ex.GetType().Name);
                    if (!_started || AllflameStopController.StopRequested)
                    {
                        return;
                    }
                    try
                    {
                        CleanupStaleRuntimeForRestart();
                        Start();
                    }
                    catch (Exception recoveryException)
                    {
                        AllflameLog.Error(
                            "BOT_COROUTINE_RECOVERY_FAILED",
                            recoveryException);
                    }
                }
            }
        }

        private bool IsCoroutineHealthy()
        {
            if (_coroutine == null || _coroutineFaulted)
            {
                return false;
            }

            try
            {
                if (_coroutine.IsFinished)
                {
                    return false;
                }
            }
            catch
            {
                return false;
            }

            return _lastCoroutineActivityUtc != DateTime.MinValue &&
                   DateTime.UtcNow - _lastCoroutineActivityUtc <
                   TimeSpan.FromSeconds(10);
        }

        private void CleanupStaleRuntimeForRestart()
        {
            _started = false;
            try
            {
                if (_coroutine != null)
                {
                    _coroutine.Dispose();
                }
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "BOT_COROUTINE_REBUILD_DISPOSE" +
                    "|Type=" + ex.GetType().Name +
                    "|Action=ContinueCleanup" +
                    "|Context=" +
                    AllflameProgressWatchdog.Describe());
            }
            finally
            {
                _coroutine = null;
                _coroutineFaulted = false;
                _coroutineFaultLogged = false;
                _lastCoroutineActivityUtc = DateTime.MinValue;
            }

            try
            {
                _taskManager.Stop();
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "BOT_TASK_MANAGER_REBUILD_STOP" +
                    "|Type=" + ex.GetType().Name);
            }

            try
            {
                LokiPoe.ProcessHookManager.ClearAllKeyStates();
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "BOT_REBUILD_INPUT_CLEANUP_FAILED" +
                    "|Type=" + ex.GetType().Name);
            }
        }

        public Task<LogicResult> Logic(Logic logic)
        {
            return _taskManager.ProvideLogic(
                TaskGroup.Enabled,
                RunBehavior.UntilHandled,
                logic);
        }

        public MessageResult Message(Message message)
        {
            if (message != null &&
                String.Equals(message.Id, "allflame_bot.snapshot", StringComparison.OrdinalIgnoreCase))
            {
                AllflameContext.RequestManualSnapshot();
                AllflameLog.Info(
                    "MANUAL_SNAPSHOT_QUEUED|Action=ProcessOnMainTaskCycle");
                return MessageResult.Processed;
            }

            return _taskManager.SendMessage(TaskGroup.Enabled, message);
        }

        private async Task<object> MainLoop()
        {
            while (_started)
            {
                try
                {
                    Stopwatch cycleTimer = Stopwatch.StartNew();
                    AllflameLog.Throttled(
                        "task_manager_run_begin",
                        TimeSpan.FromSeconds(2),
                        "TASK_MANAGER_RUN_BEGIN|" +
                        AllflameProgressWatchdog.Describe());
                    await _taskManager.Run(
                        TaskGroup.Enabled,
                        RunBehavior.UntilHandled);
                    cycleTimer.Stop();
                    if (cycleTimer.ElapsedMilliseconds >= 250)
                    {
                        AllflameLog.Throttled(
                            "task_cycle_slow",
                            TimeSpan.FromSeconds(1),
                            "TASK_CYCLE_SLOW" +
                            "|ElapsedMs=" +
                            cycleTimer.ElapsedMilliseconds +
                            "|" +
                            AllflameProgressWatchdog.Describe());
                    }
                }
                catch (Exception ex)
                {
                    AllflameLog.Error("MAIN_LOOP_FAILED", ex);
                    AllflameContext.RequestRefresh(
                        "MainLoopExceptionRecovered");
                    AllflameProgressWatchdog.MarkProgress(
                        "MainLoopExceptionRecovered");
                }

                await LokiCoroutine.Yield();
            }

            return null;
        }
    }

