        private static bool _manualSnapshotRequested;
        private static int _forceRefreshRequests;
        private static string _lastStateSignature = String.Empty;
        private static string _lastPlayerPosition = String.Empty;
        private static DateTime _positionChangedUtc = DateTime.UtcNow;
        private static bool _previousCallBathysphereVisible;
        private static bool _coverageAuraObserved;
        private static bool _previousCoverageAura;
        private static DateTime _lastCoverageTransitionUtc = DateTime.MinValue;
        private static int _coverageOscillationCount;
        private static bool _coverageOscillationWarned;

