    internal sealed class ChartAreaTransitionTask : ObserverTask
    {
        public ChartAreaTransitionTask()
            : base(
                "ChartAreaTransitionTask",
                "Quarantines DPB reads while a Chart portal changes areas.") { }

        public override async Task<bool> Run()
        {
            if (!AllflameAreaTransitionGuard.Pending)
            {
                return false;
            }

            if (AllflameStopController.StopRequested)
            {
                return true;
            }

            if (!AllflameAreaTransitionGuard.CanRetry(
                    AllflameContext.AreaHash))
            {
                AllflameAreaTransitionGuard.LogInteractionSuppressed(
                    AllflameContext.AreaHash);
                return true;
            }

            NetworkObject portal = AllflameContext.BathysphereObject;
            if (portal == null ||
                portal.Id != AllflameAreaTransitionGuard.PortalId)
            {
                AllflameLog.Info(
                    "CHART_PORTAL_INTERACTION_SUPPRESSED" +
                    "|Reason=OriginalPortalUnavailable" +
                    "|ExpectedPortalId=" +
                    AllflameAreaTransitionGuard.PortalId +
                    "|CurrentAreaHash=" + AllflameContext.AreaHash);
                return true;
            }

            int interaction = AllflameAreaTransitionGuard.RegisterRetry();
            await FinishMovementBeforeInteraction(
                "Chart Bathysphere Portal Retry");
            bool entered = await InteractWithRecovery(portal);
            AllflameLog.Info(
                "BATHYSPHERE_ENTER" +
                "|Id=" + portal.Id +
                "|Name=" + portal.Name +
                "|Distance=" + portal.Distance.ToString("0.0") +
                "|Mode=BoundedTransitionRetry" +
                "|Interaction=" + interaction +
                "|Success=" + entered);
            return true;
        }
    }

    internal static class RespawnVisualFallback
    {
        private const int TemplateWidth = 47;
        private const int TemplateHeight = 8;
        private const int ReferenceButtonWidth = 187;
        private const int ReferenceButtonHeight = 29;
        private const string CheckpointTemplateBase64 =
            "";
        // Downsampled grayscale template generated from the supplied
        // 187x29 RESURRECT AT CHECKPOINT crop.
        private const string AdaptiveCheckpointTemplateBase64 =
            "";
        private const string CompactCheckpointTemplateBase64 =
            "";
        private const string Checkpoint800TemplateBase64 =
            "";
        private static readonly byte[] CheckpointTemplate =
            Convert.FromBase64String(
                CompactCheckpointTemplateBase64);
        private static readonly byte[] Checkpoint800Template =
            Convert.FromBase64String(
                Checkpoint800TemplateBase64);
        private static readonly double TemplateMean =
            CheckpointTemplate.Average(value => (double)value);
        private static readonly double TemplateEnergy =
            CheckpointTemplate.Sum(
                value =>
                    (value - TemplateMean) *
                    (value - TemplateMean));
        private static readonly double Template800Mean =
            Checkpoint800Template.Average(value => (double)value);
        private static readonly double Template800Energy =
            Checkpoint800Template.Sum(
                value =>
                    (value - Template800Mean) *
                    (value - Template800Mean));

        public static bool TryFindCheckpoint(
            double requiredCorrelation,
            out Vector2i clientLocation,
            out double bestCorrelation)
        {
            clientLocation = new Vector2i();
            bestCorrelation = -1.0;
            requiredCorrelation =
                Math.Max(
                    0.40,
                    Math.Min(0.60, requiredCorrelation));

            if (CheckpointTemplate.Length !=
                    TemplateWidth * TemplateHeight ||
                Checkpoint800Template.Length !=
                    TemplateWidth * TemplateHeight)
            {
                AllflameLog.Throttled(
                    "respawn_visual_invalid_template",
                    TimeSpan.FromSeconds(10),
                    "RESPAWN_VISUAL|Found=False" +
                    "|Reason=InvalidTemplateLength" +
                    "|Actual=" + CheckpointTemplate.Length +
                    "|Actual800=" + Checkpoint800Template.Length +
                    "|Expected=" +
                    (TemplateWidth * TemplateHeight));
                return false;
            }

            try
            {
                var client = LokiPoe.ClientWindowInfo.Client;
                int width = client.Right - client.Left;
                int height = client.Bottom - client.Top;
                if (width < 800 || height < 500)
                {
                    return false;
                }

                using (var screenshot =
                    new System.Drawing.Bitmap(
                        width,
                        height,
                        System.Drawing.Imaging.PixelFormat
                            .Format24bppRgb))
                {
                    using (System.Drawing.Graphics graphics =
                        System.Drawing.Graphics.FromImage(
                            screenshot))
                    {
                        graphics.CopyFromScreen(
                            client.Left,
                            client.Top,
                            0,
                            0,
                            new System.Drawing.Size(width, height),
                            System.Drawing.CopyPixelOperation.SourceCopy);
                    }

                    var rectangle =
                        new System.Drawing.Rectangle(
                            0,
                            0,
                            width,
                            height);
                    System.Drawing.Imaging.BitmapData data =
                        screenshot.LockBits(
                            rectangle,
                            System.Drawing.Imaging.ImageLockMode
                                .ReadOnly,
                            System.Drawing.Imaging.PixelFormat
                                .Format24bppRgb);
                    try
                    {
                        int stride = Math.Abs(data.Stride);
                        byte[] pixels = new byte[stride * height];
                        System.Runtime.InteropServices.Marshal.Copy(
                            data.Scan0,
                            pixels,
                            0,
                            pixels.Length);

                        int expectedX = width / 2;
                        int expectedY =
                            (int)Math.Round(height * 0.294);
                        int radiusX = Math.Max(55, width / 16);
                        int radiusY = Math.Max(45, height / 14);
                        double referenceScale =
                            Math.Min(
                                width / 1280.0,
                                height / 800.0);
                        double[] scales =
                            { 0.82, 0.90, 1.0, 1.10, 1.20 };
                        int bestX = expectedX;
                        int bestY = expectedY;
                        int bestWidth = ReferenceButtonWidth;
                        int bestHeight = ReferenceButtonHeight;

                        foreach (double scale in scales)
                        {
                            int candidateWidth = Math.Max(
                                120,
                                (int)Math.Round(
                                    ReferenceButtonWidth *
                                    referenceScale *
                                    scale));
                            int candidateHeight = Math.Max(
                                15,
                                (int)Math.Round(
                                    ReferenceButtonHeight *
                                    referenceScale *
                                    scale));
                            int scaleBestX = expectedX;
                            int scaleBestY = expectedY;
                            int scaleBestWidth = candidateWidth;
                            int scaleBestHeight = candidateHeight;
                            double scaleBestCorrelation = -1.0;
                            ScanRegion(
                                pixels,
                                stride,
                                width,
                                height,
                                expectedX - radiusX,
                                expectedX + radiusX,
                                expectedY - radiusY,
                                expectedY + radiusY,
                                3,
                                candidateWidth,
                                candidateHeight,
                                ref scaleBestX,
                                ref scaleBestY,
                                ref scaleBestWidth,
                                ref scaleBestHeight,
                                ref scaleBestCorrelation);

                            // Refine every scale independently. Otherwise a
                            // nearby wrong scale can win the coarse pass and
                            // prevent the true scale from receiving its
                            // required one-pixel alignment.
                            ScanRegion(
                                pixels,
                                stride,
                                width,
                                height,
                                scaleBestX - 4,
                                scaleBestX + 4,
                                scaleBestY - 4,
                                scaleBestY + 4,
                                1,
                                candidateWidth,
                                candidateHeight,
                                ref scaleBestX,
                                ref scaleBestY,
                                ref scaleBestWidth,
                                ref scaleBestHeight,
                                ref scaleBestCorrelation);
                            if (scaleBestCorrelation >
                                bestCorrelation)
                            {
                                bestCorrelation =
                                    scaleBestCorrelation;
                                bestX = scaleBestX;
                                bestY = scaleBestY;
                                bestWidth = scaleBestWidth;
                                bestHeight = scaleBestHeight;
                            }
                        }

                        clientLocation =
                            new Vector2i(bestX, bestY);
                        bool found =
                            bestCorrelation >=
                            requiredCorrelation;
                        AllflameLog.Throttled(
                            found
                                ? "respawn_visual_found"
                                : "respawn_visual_not_found",
                            TimeSpan.FromSeconds(2),
                            "RESPAWN_VISUAL|Found=" + found +
                            "|Correlation=" +
                            bestCorrelation.ToString("0.000") +
                            "|Required=" +
                            requiredCorrelation.ToString("0.00") +
                            "|ClientLocation=" +
                            clientLocation +
                            "|Client=" + width + "x" + height);
                        return found;
                    }
                    finally
                    {
                        screenshot.UnlockBits(data);
                    }
                }
            }
            catch (Exception exception)
            {
                AllflameLog.Throttled(
                    "respawn_visual_error",
                    TimeSpan.FromSeconds(3),
                    "RESPAWN_VISUAL|Found=False" +
                    "|Error=" +
                    exception.GetType().Name +
                    "|Message=" + exception.Message);
                return false;
            }
        }

        public static bool ClickCheckpoint(Vector2i location)
        {
            try
            {
                LokiPoe.ProcessHookManager.ClearAllKeyStates();
                DreamPoeBot.BotFramework.MouseManager
                    .SetMousePosition(location, false);
                DreamPoeBot.BotFramework.MouseManager
                    .ClickLMB(0, 0);
                return true;
            }
            catch (Exception exception)
            {
                AllflameLog.Info(
                    "RESPAWN_VISUAL_CLICK_FAILED" +
                    "|ClientLocation=" + location +
                    "|Error=" +
                    exception.GetType().Name +
                    "|Message=" + exception.Message);
                return false;
            }
        }

        private static void ScanRegion(
            byte[] pixels,
            int stride,
            int imageWidth,
            int imageHeight,
            int minCenterX,
            int maxCenterX,
            int minCenterY,
            int maxCenterY,
            int step,
            int candidateWidth,
            int candidateHeight,
            ref int bestCenterX,
            ref int bestCenterY,
            ref int bestWidth,
            ref int bestHeight,
            ref double bestCorrelation)
        {
            int halfWidth = candidateWidth / 2;
            int halfHeight = candidateHeight / 2;
            minCenterX = Math.Max(halfWidth, minCenterX);
            maxCenterX = Math.Min(
                imageWidth - (candidateWidth - halfWidth),
                maxCenterX);
            minCenterY = Math.Max(halfHeight, minCenterY);
            maxCenterY = Math.Min(
                imageHeight - (candidateHeight - halfHeight),
                maxCenterY);

            for (int centerY = minCenterY;
                 centerY <= maxCenterY;
                 centerY += step)
            {
                for (int centerX = minCenterX;
                     centerX <= maxCenterX;
                     centerX += step)
                {
                    double correlation = CalculateCorrelation(
                        pixels,
                        stride,
                        imageWidth,
                        imageHeight,
                        centerX - halfWidth,
                        centerY - halfHeight,
                        candidateWidth,
                        candidateHeight);
                    if (correlation > bestCorrelation)
                    {
                        bestCorrelation = correlation;
                        bestCenterX = centerX;
                        bestCenterY = centerY;
                        bestWidth = candidateWidth;
                        bestHeight = candidateHeight;
                    }
                }
            }
        }

        private static double CalculateCorrelation(
            byte[] pixels,
            int stride,
            int imageWidth,
            int imageHeight,
            int candidateLeft,
            int candidateTop,
            int candidateWidth,
            int candidateHeight)
        {
            return Math.Max(
                CalculateCorrelationForTemplate(
                    pixels,
                    stride,
                    imageWidth,
                    imageHeight,
                    candidateLeft,
                    candidateTop,
                    candidateWidth,
                    candidateHeight,
                    CheckpointTemplate,
                    TemplateMean,
                    TemplateEnergy),
                CalculateCorrelationForTemplate(
                    pixels,
                    stride,
                    imageWidth,
                    imageHeight,
                    candidateLeft,
                    candidateTop,
                    candidateWidth,
                    candidateHeight,
                    Checkpoint800Template,
                    Template800Mean,
                    Template800Energy));
        }

        private static double CalculateCorrelationForTemplate(
            byte[] pixels,
            int stride,
            int imageWidth,
            int imageHeight,
            int candidateLeft,
            int candidateTop,
            int candidateWidth,
            int candidateHeight,
            byte[] template,
            double templateMean,
            double templateEnergy)
        {
            double sum = 0.0;
            double sumSquares = 0.0;
            double cross = 0.0;
            int count = template.Length;

            for (int templateY = 0;
                 templateY < TemplateHeight;
                 templateY++)
            {
                int sourceY = candidateTop +
                    templateY * (candidateHeight - 1) /
                    (TemplateHeight - 1);
                if (sourceY < 0 || sourceY >= imageHeight)
                {
                    return -1.0;
                }

                int row = sourceY * stride;
                for (int templateX = 0;
                     templateX < TemplateWidth;
                     templateX++)
                {
                    int sourceX = candidateLeft +
                        templateX * (candidateWidth - 1) /
                        (TemplateWidth - 1);
                    if (sourceX < 0 || sourceX >= imageWidth)
                    {
                        return -1.0;
                    }

                    int pixel = row + sourceX * 3;
                    double gray =
                        (pixels[pixel + 2] * 77 +
                         pixels[pixel + 1] * 150 +
                         pixels[pixel] * 29) / 256.0;
                    double templateCentered =
                        template[
                            templateY * TemplateWidth +
                            templateX] -
                        templateMean;
                    sum += gray;
                    sumSquares += gray * gray;
                    cross += gray * templateCentered;
                }
            }

            double candidateEnergy =
                sumSquares - sum * sum / count;
            if (candidateEnergy <= 0.001 ||
                templateEnergy <= 0.001)
            {
                return -1.0;
            }

            return cross /
                Math.Sqrt(candidateEnergy * templateEnergy);
        }
    }

    internal sealed class RespawnTask : ObserverTask
    {
        private int _visualDetectionAttempts;
        private int _visualClickAttempts;
        private DateTime _nextAttemptUtc = DateTime.MinValue;
        private bool _deathObserved;
        private bool _chartDeath;
        private bool _voyageDeath;
        private DateTime _nextBoatCommandUtc = DateTime.MinValue;
        private DateTime _deathObservedUtc = DateTime.MinValue;
        private int _apiAttempts;
        private bool _apiAwaitingConfirmation;
        private bool _visualFallbackActive;
        private DateTime _apiFirstAttemptUtc = DateTime.MinValue;
        private DateTime _apiAttemptIssuedUtc = DateTime.MinValue;
        private uint _apiAttemptAreaHash;
        private bool _visualAwaitingConfirmation;
        private DateTime _visualClickIssuedUtc = DateTime.MinValue;
        private const int MaximumVisualClickAttempts = 6;
        private const int MaximumApiAttempts = 3;

        public RespawnTask()
            : base(
                "RespawnTask",
                "Respawns and abandons a one-entry Chart after death.") { }

        public override void Start()
        {
            ResetTaskState();
        }

        public override void Stop()
        {
            ResetTaskState();
        }

        public override async Task<bool> Run()
        {
            if (!LokiPoe.IsInGame || LokiPoe.Me == null)
            {
                return false;
            }

            if (!LokiPoe.Me.IsDead)
            {
                if (_deathObserved)
                {
                    if (_apiAttempts > 0 && !_visualFallbackActive)
                    {
                        bool panelOpened = SafeResurrectPanelOpened();
                        AllflameLog.Info(
                            "RESPAWN_API_CONFIRMED" +
                            "|Alive=True" +
                            "|PanelOpened=" + panelOpened +
                            "|AreaChanged=" +
                            (_apiAttemptAreaHash != 0 &&
                             _apiAttemptAreaHash != AllflameContext.AreaHash) +
                            "|ElapsedMilliseconds=" +
                            (_apiFirstAttemptUtc == DateTime.MinValue
                                ? 0
                                : Math.Max(
                                    0,
                                    (int)(DateTime.UtcNow -
                                        _apiFirstAttemptUtc)
                                        .TotalMilliseconds)) +
                            "|Attempts=" + _apiAttempts);
                        ResetApiRespawnState();
                    }
                    bool stillInsideFailedEncounter =
                        (_chartDeath &&
                         AllflameContext.Phase ==
                             AllflamePhase.ChartArea) ||
                        (_voyageDeath &&
                         (AllflameContext.Phase ==
                              AllflamePhase.Voyage ||
                          AllflameContext.Phase ==
                              AllflamePhase.WaitingForBathysphere));
                    if (stillInsideFailedEncounter)
                    {
                        if (DateTime.UtcNow >= _nextBoatCommandUtc)
                        {
                            _nextBoatCommandUtc =
                                DateTime.UtcNow.AddSeconds(2);
                            var chatResult =
                                LokiPoe.InGameState.ChatPanel
                                    .Chat("/boat");
                            AllflameLog.Info(
                                "POST_DEATH_ENCOUNTER_EXIT" +
                                "|Command=/boat" +
                                "|Result=" + chatResult +
                                "|Runner=" +
                                (_voyageDeath
                                    ? "Voyage"
                                    : "Chart") +
                                "|Reason=EncounterAllowsSingleEntry");
                        }
                        return true;
                    }

                    _deathObserved = false;
                    _visualDetectionAttempts = 0;
                    _visualClickAttempts = 0;
                    _nextAttemptUtc = DateTime.MinValue;
                    _nextBoatCommandUtc = DateTime.MinValue;
                    _deathObservedUtc = DateTime.MinValue;
                    ResetApiRespawnState();
                    try
                    {
                        ExilePather.Reload(true);
                    }
                    catch
                    {
                    }
                    AllflameLog.Info(
                        "RESPAWN_COMPLETE|Alive=True" +
                        "|Phase=" + AllflameContext.Phase +
                        "|ChartAbandoned=" + _chartDeath +
                        "|VoyageAbandoned=" + _voyageDeath +
                        "|Action=" +
                        (_chartDeath
                            ? "ContinueWithNextChart"
                            : (_voyageDeath
                                ? "ContinueAfterFailedVoyage"
                                : "ResumeCurrentRun")));
                    _chartDeath = false;
                    _voyageDeath = false;
                    return true;
                }
                return false;
            }

            if (!_deathObserved)
            {
                _deathObserved = true;
                _deathObservedUtc = DateTime.UtcNow;
                _visualDetectionAttempts = 0;
                _visualClickAttempts = 0;
                ResetApiRespawnState();
                _chartDeath =
                    AllflameContext.Phase ==
                        AllflamePhase.ChartArea;
                _voyageDeath =
                    AllflameContext.Phase ==
                        AllflamePhase.Voyage ||
                    AllflameContext.Phase ==
                        AllflamePhase.WaitingForBathysphere;
                if (_chartDeath)
                {
                    AllflameRunState
                        .AbandonCurrentChartAfterDeath();
                }
                else if (_voyageDeath)
                {
                    VoyageRunState.AbandonAfterDeath();
                }
            }
            if (DateTime.UtcNow < _nextAttemptUtc)
            {
                return true;
            }

            if (_visualAwaitingConfirmation)
            {
                int elapsed = Math.Max(
                    0,
                    (int)(DateTime.UtcNow - _visualClickIssuedUtc)
                        .TotalMilliseconds);
                if (elapsed < 3000)
                {
                    _nextAttemptUtc =
                        DateTime.UtcNow.AddMilliseconds(150);
                    AllflameLog.Throttled(
                        "respawn_visual_confirmation_wait",
                        TimeSpan.FromMilliseconds(500),
                        "RESPAWN_VISUAL_WAIT" +
                        "|ElapsedMilliseconds=" + elapsed +
                        "|VisualClicks=" + _visualClickAttempts +
                        "|OneActionPerCycle=True");
                    return true;
                }

                _visualAwaitingConfirmation = false;
                _visualClickIssuedUtc = DateTime.MinValue;
                AllflameLog.Info(
                    "RESPAWN_VISUAL_WAIT_TIMEOUT" +
                    "|VisualClicks=" + _visualClickAttempts +
                    "|Action=RetryVisualDetection");
            }

            TimeSpan deadFor =
                _deathObservedUtc == DateTime.MinValue
                    ? TimeSpan.Zero
                    : DateTime.UtcNow - _deathObservedUtc;
            if (deadFor < TimeSpan.FromMilliseconds(750))
            {
                _nextAttemptUtc =
                    DateTime.UtcNow.AddMilliseconds(150);
                AllflameLog.Throttled(
                    "respawn_visual_wait",
                    TimeSpan.FromSeconds(2),
                    "RESPAWN_WAIT|Reason=DeathUiGracePeriod");
                return true;
            }

            if (!_visualFallbackActive)
            {
                if (await TryRunApiRespawn(deadFor))
                {
                    return true;
                }
            }

            if (_visualClickAttempts >=
                MaximumVisualClickAttempts)
            {
                _nextAttemptUtc = DateTime.UtcNow.AddSeconds(5);
                AllflameLog.Throttled(
                    "respawn_recovery_exhausted",
                    TimeSpan.FromSeconds(5),
                    "RESPAWN_RECOVERY_EXHAUSTED" +
                    "|VisualClicks=" +
                    _visualClickAttempts +
                    "|ThresholdFloor=0.40" +
                    "|Action=AwaitManualRecovery");
                return true;
            }

            try
            {
                DreamPoeBot.Loki.Game.Interop
                    .SetForegroundWindow(
                        LokiPoe.ClientWindowHandle);
                await LokiCoroutine.Sleep(80);
            }
            catch
            {
            }

            _visualDetectionAttempts++;
            double requiredCorrelation =
                GetAdaptiveRespawnCorrelation(
                    _visualDetectionAttempts);
            int tierAttempt =
                requiredCorrelation >= 0.60
                    ? _visualDetectionAttempts
                    : (requiredCorrelation >= 0.50
                        ? _visualDetectionAttempts - 5
                        : _visualDetectionAttempts - 10);

            Vector2i firstVisualLocation;
            double firstVisualCorrelation;
            bool firstFound =
                RespawnVisualFallback.TryFindCheckpoint(
                    requiredCorrelation,
                    out firstVisualLocation,
                    out firstVisualCorrelation);
            AllflameLog.Info(
                "RESPAWN_VISUAL_ATTEMPT" +
                "|Attempt=" + _visualDetectionAttempts +
                "|TierAttempt=" + tierAttempt +
                "|Required=" +
                requiredCorrelation.ToString("0.00") +
                "|Correlation=" +
                firstVisualCorrelation.ToString("0.000") +
                "|Found=" + firstFound +
                "|ClientLocation=" + firstVisualLocation);
            if (!firstFound)
            {
                _nextAttemptUtc =
                    DateTime.UtcNow.AddMilliseconds(350);
                return true;
            }

            await LokiCoroutine.Sleep(140);
            if (!LokiPoe.IsInGame ||
                LokiPoe.Me == null ||
                !LokiPoe.Me.IsDead)
            {
                return true;
            }

            Vector2i secondVisualLocation;
            double secondVisualCorrelation;
            bool secondFound =
                RespawnVisualFallback.TryFindCheckpoint(
                    requiredCorrelation,
                    out secondVisualLocation,
                    out secondVisualCorrelation);
            int visualDrift =
                secondFound
                    ? Math.Abs(
                          secondVisualLocation.X -
                          firstVisualLocation.X) +
                      Math.Abs(
                          secondVisualLocation.Y -
                          firstVisualLocation.Y)
                    : Int32.MaxValue;
            bool visuallyConfirmed =
                secondFound &&
                visualDrift <= 10;
            AllflameLog.Info(
                "RESPAWN_VISUAL_CONFIRM" +
                "|Confirmed=" + visuallyConfirmed +
                "|Attempt=" + _visualDetectionAttempts +
                "|Required=" +
                requiredCorrelation.ToString("0.00") +
                "|FirstCorrelation=" +
                firstVisualCorrelation.ToString("0.000") +
                "|SecondCorrelation=" +
                secondVisualCorrelation.ToString("0.000") +
                "|Drift=" +
                (secondFound
                    ? visualDrift.ToString()
                    : "n/a") +
                "|ClientLocation=" +
                secondVisualLocation);
            if (!visuallyConfirmed)
            {
                _nextAttemptUtc =
                    DateTime.UtcNow.AddMilliseconds(350);
                return true;
            }

            _visualClickAttempts++;
            bool clicked =
                RespawnVisualFallback.ClickCheckpoint(
                    secondVisualLocation);
            AllflameLog.Info(
                "RESPAWN_VISUAL_CLICK" +
                "|Destination=Checkpoint" +
                "|ClickAttempt=" + _visualClickAttempts +
                "|DetectionAttempt=" +
                _visualDetectionAttempts +
                "|Required=" +
                requiredCorrelation.ToString("0.00") +
                "|ClientLocation=" +
                secondVisualLocation +
                "|Clicked=" + clicked);
            if (!clicked)
            {
                _nextAttemptUtc =
                    DateTime.UtcNow.AddMilliseconds(500);
                return true;
            }

            _visualAwaitingConfirmation = true;
            _visualClickIssuedUtc = DateTime.UtcNow;
            _nextAttemptUtc = DateTime.UtcNow.AddMilliseconds(150);
            return true;
        }

        private async Task<bool> TryRunApiRespawn(TimeSpan deadFor)
        {
            bool panelOpened = SafeResurrectPanelOpened();
            AllflameLog.Throttled(
                "respawn_api_state",
                TimeSpan.FromMilliseconds(500),
                "RESPAWN_API_STATE" +
                "|PanelOpened=" + panelOpened +
                "|Dead=True" +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|DeadForMilliseconds=" +
                Math.Max(0, (int)deadFor.TotalMilliseconds) +
                "|Attempt=" + _apiAttempts +
                "|AwaitingConfirmation=" +
                _apiAwaitingConfirmation);

            if (_apiAwaitingConfirmation)
            {
                int elapsed = Math.Max(
                    0,
                    (int)(DateTime.UtcNow - _apiAttemptIssuedUtc)
                        .TotalMilliseconds);
                if (elapsed < 3000)
                {
                    AllflameLog.Throttled(
                        "respawn_api_confirmation_wait",
                        TimeSpan.FromMilliseconds(500),
                        "RESPAWN_API_WAIT" +
                        "|Attempt=" + _apiAttempts +
                        "|ElapsedMilliseconds=" + elapsed +
                        "|Dead=True" +
                        "|PanelOpened=" + panelOpened +
                        "|AreaChanged=" +
                        (_apiAttemptAreaHash != 0 &&
                         _apiAttemptAreaHash != AllflameContext.AreaHash));
                    _nextAttemptUtc =
                        DateTime.UtcNow.AddMilliseconds(150);
                    return true;
                }

                _apiAwaitingConfirmation = false;
                AllflameLog.Info(
                    "RESPAWN_API_REJECTED" +
                    "|Attempt=" + _apiAttempts +
                    "|Result=ConfirmationTimeout" +
                    "|Dead=True" +
                    "|PanelOpened=" + panelOpened +
                    "|ElapsedMilliseconds=" + elapsed);
            }

            if (!panelOpened)
            {
                if (deadFor < TimeSpan.FromSeconds(2))
                {
                    _nextAttemptUtc =
                        DateTime.UtcNow.AddMilliseconds(150);
                    return true;
                }
                ActivateVisualRespawnFallback("PanelMissing");
                return false;
            }

            if (_apiAttempts >= MaximumApiAttempts)
            {
                ActivateVisualRespawnFallback("ApiTimeout");
                return false;
            }

            _apiAttempts++;
            if (_apiFirstAttemptUtc == DateTime.MinValue)
            {
                _apiFirstAttemptUtc = DateTime.UtcNow;
            }
            _apiAttemptIssuedUtc = DateTime.UtcNow;
            _apiAttemptAreaHash = AllflameContext.AreaHash;
            string result;
            try
            {
                result = LokiPoe.InGameState.ResurrectPanel
                    .ResurrectToCheckPoint(true)
                    .ToString();
            }
            catch (Exception exception)
            {
                result = "Exception:" + exception.GetType().Name;
                AllflameLog.Info(
                    "RESPAWN_API_REJECTED" +
                    "|Attempt=" + _apiAttempts +
                    "|Result=" + result +
                    "|Message=" +
                    (exception.Message ?? String.Empty)
                        .Replace("|", "/") +
                    "|Dead=True");
                if (_apiAttempts >= MaximumApiAttempts)
                {
                    ActivateVisualRespawnFallback("Exception");
                    return false;
                }
                _nextAttemptUtc = DateTime.UtcNow.AddMilliseconds(750);
                return true;
            }

            AllflameLog.Info(
                "RESPAWN_API_ATTEMPT" +
                "|Destination=Checkpoint" +
                "|Attempt=" + _apiAttempts +
                "|Result=" + result +
                "|AreaHash=" + _apiAttemptAreaHash);
            if (String.Equals(
                    result,
                    "None",
                    StringComparison.OrdinalIgnoreCase))
            {
                _apiAwaitingConfirmation = true;
                _nextAttemptUtc = DateTime.UtcNow.AddMilliseconds(150);
                await LokiCoroutine.Sleep(100);
                return true;
            }

            AllflameLog.Info(
                "RESPAWN_API_REJECTED" +
                "|Attempt=" + _apiAttempts +
                "|Result=" + result +
                "|Dead=True");
            if (_apiAttempts >= MaximumApiAttempts)
            {
                ActivateVisualRespawnFallback("ApiRejected");
                return false;
            }
            _nextAttemptUtc = DateTime.UtcNow.AddMilliseconds(750);
            return true;
        }

        private void ActivateVisualRespawnFallback(string reason)
        {
            if (_visualFallbackActive)
            {
                return;
            }
            _visualFallbackActive = true;
            _apiAwaitingConfirmation = false;
            _nextAttemptUtc = DateTime.MinValue;
            AllflameLog.Info(
                "RESPAWN_FALLBACK" +
                "|Reason=" + (reason ?? String.Empty) +
                "|ApiAttempts=" + _apiAttempts +
                "|Action=VisualCheckpointDetection");
        }

        private static bool SafeResurrectPanelOpened()
        {
            try
            {
                return LokiPoe.InGameState.ResurrectPanel.IsOpened;
            }
            catch
            {
                return false;
            }
        }

        private void ResetApiRespawnState()
        {
            _apiAttempts = 0;
            _apiAwaitingConfirmation = false;
            _visualFallbackActive = false;
            _apiFirstAttemptUtc = DateTime.MinValue;
            _apiAttemptIssuedUtc = DateTime.MinValue;
            _apiAttemptAreaHash = 0;
            _visualAwaitingConfirmation = false;
            _visualClickIssuedUtc = DateTime.MinValue;
        }

        private void ResetTaskState()
        {
            _visualDetectionAttempts = 0;
            _visualClickAttempts = 0;
            _nextAttemptUtc = DateTime.MinValue;
            _deathObserved = false;
            _chartDeath = false;
            _voyageDeath = false;
            _nextBoatCommandUtc = DateTime.MinValue;
            _deathObservedUtc = DateTime.MinValue;
            ResetApiRespawnState();
        }

        private static double GetAdaptiveRespawnCorrelation(
            int attempt)
        {
            if (attempt <= 5)
            {
                return 0.60;
            }
            if (attempt <= 10)
            {
                return 0.50;
            }
            return 0.40;
        }
    }

    internal sealed class UseLifeFlaskTask : ObserverTask
    {
        private DateTime _nextLifeUseUtc = DateTime.MinValue;
        private DateTime _nextUtilityUseUtc = DateTime.MinValue;
        private uint _lastUtilityAreaHash;
        private readonly List<int> _utilityCycleSlots =
            new List<int>();
        private int _utilityCycleCursor;

        public UseLifeFlaskTask()
            : base(
                "UseLifeFlaskTask",
                "Uses the Life Flask by threshold and configured utility flasks periodically.") { }

        public override async Task<bool> Run()
        {
            AllflameSettings settings = AllflameSettings.Instance;
            if (!LokiPoe.IsInGame ||
                LokiPoe.Me == null ||
                LokiPoe.Me.IsDead)
            {
                return false;
            }

            if (settings.EnableLifeFlask &&
                LokiPoe.Me.HealthPercent <
                    settings.LifeFlaskUseThreshold &&
                !LokiPoe.Me.IsUsingHealthFlask &&
                DateTime.UtcNow >= _nextLifeUseUtc)
            {
                try
                {
                    Item flask = LokiPoe.InGameState.QuickFlaskHud
                        .InventoryControl.Inventory.Items
                        .Where(item =>
                            item != null &&
                            item.IsValid &&
                            item.HealthRecover > 0 &&
                            item.CanUse)
                        .OrderByDescending(item => item.HealthRecover)
                        .FirstOrDefault();
                    if (flask == null)
                    {
                        AllflameLog.Throttled(
                            "life_flask_unavailable",
                            TimeSpan.FromSeconds(3),
                            "LIFE_FLASK|Action=Skip|Reason=NoUsableLifeFlask" +
                            "|Health=" +
                            LokiPoe.Me.HealthPercent.ToString("0.0") +
                            "|Threshold=" + settings.LifeFlaskUseThreshold);
                    }
                    else
                    {
                        int slot = flask.LocationTopLeft.X + 1;
                        bool used = LokiPoe.InGameState.QuickFlaskHud
                            .UseFlaskInSlot(slot);
                        _nextLifeUseUtc =
                            DateTime.UtcNow.AddMilliseconds(750);
                        AllflameLog.Info(
                            "LIFE_FLASK|Action=Use" +
                            "|Slot=" + slot +
                            "|Health=" +
                            LokiPoe.Me.HealthPercent.ToString("0.0") +
                            "|Threshold=" +
                            settings.LifeFlaskUseThreshold +
                            "|Success=" + used);
                        return true;
                    }
                }
                catch (Exception ex)
                {
                    _nextLifeUseUtc = DateTime.UtcNow.AddSeconds(1);
                    AllflameLog.Error("LIFE_FLASK_FAILED", ex);
                }
            }

            bool inEncounterArea =
                AllflameContext.IsChartMapArea ||
                (AllflameContext.IsVoyageMapArea &&
                 AllflameContext.Phase == AllflamePhase.Voyage);
            bool onBoat =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            bool utilityAllowed =
                settings.EnableUtilityFlasks &&
                (inEncounterArea ||
                 (onBoat && !settings.DisableUtilityFlasksOnBoat));
            if (VoyageRunState.Active &&
                VoyageRunState.LanternsExhausted)
            {
                utilityAllowed = false;
            }
            if (!utilityAllowed)
            {
                _utilityCycleSlots.Clear();
                _utilityCycleCursor = 0;
                return false;
            }

            if (inEncounterArea &&
                _lastUtilityAreaHash != AllflameContext.AreaHash)
            {
                _lastUtilityAreaHash = AllflameContext.AreaHash;
                _nextUtilityUseUtc = DateTime.MinValue;
            }

            if (_utilityCycleCursor >= _utilityCycleSlots.Count &&
                DateTime.UtcNow < _nextUtilityUseUtc)
            {
                return false;
            }

            try
            {
                if (_utilityCycleCursor >= _utilityCycleSlots.Count)
                {
                    _utilityCycleSlots.Clear();
                    _utilityCycleSlots.AddRange(
                        ParseFlaskSlots(settings.UtilityFlaskSlots));
                    _utilityCycleCursor = 0;
                }
                List<Item> flasks =
                    LokiPoe.InGameState.QuickFlaskHud
                        .InventoryControl.Inventory.Items;
                while (_utilityCycleCursor <
                    _utilityCycleSlots.Count)
                {
                    int slot =
                        _utilityCycleSlots[_utilityCycleCursor++];
                    Item flask = flasks.FirstOrDefault(item =>
                        item != null &&
                        item.IsValid &&
                        item.LocationTopLeft.X + 1 == slot);
                    if (flask == null || !flask.CanUse)
                    {
                        continue;
                    }

                    bool used =
                        LokiPoe.InGameState.QuickFlaskHud
                            .UseFlaskInSlot(slot);
                    bool cycleComplete =
                        _utilityCycleCursor >=
                        _utilityCycleSlots.Count;
                    if (cycleComplete)
                    {
                        _nextUtilityUseUtc = DateTime.UtcNow.AddSeconds(
                            Math.Max(
                                1,
                                settings.UtilityFlaskIntervalSeconds));
                    }
                    AllflameLog.Info(
                        "UTILITY_FLASKS|Action=UseOne" +
                        "|Slot=" + slot +
                        "|Success=" + used +
                        "|Cycle=" + _utilityCycleCursor + "/" +
                        _utilityCycleSlots.Count +
                        "|CycleComplete=" + cycleComplete +
                        "|Phase=" + AllflameContext.Phase +
                        "|OneActionPerCycle=True");
                    return true;
                }

                _nextUtilityUseUtc = DateTime.UtcNow.AddSeconds(
                    Math.Max(1, settings.UtilityFlaskIntervalSeconds));
            }
            catch (Exception ex)
            {
                _nextUtilityUseUtc = DateTime.UtcNow.AddSeconds(1);
                AllflameLog.Error("UTILITY_FLASKS_FAILED", ex);
            }

            return false;
        }

        private static IEnumerable<int> ParseFlaskSlots(string value)
        {
            var slots = new HashSet<int>();
            foreach (string token in (value ?? String.Empty).Split(','))
            {
                int slot;
                if (Int32.TryParse(token.Trim(), out slot) &&
                    slot >= 1 &&
                    slot <= 5)
                {
                    slots.Add(slot);
                }
            }
            return slots.OrderBy(slot => slot);
        }
    }

    internal sealed class UseEnduringCryTask : ObserverTask
    {
        private DateTime _nextCheckUtc = DateTime.MinValue;
        private uint _lastAreaHash;

        public UseEnduringCryTask()
            : base(
                "UseEnduringCryTask",
                "Uses Enduring Cry through DPB's native skill API whenever it is ready.") { }

        public override Task<bool> Run()
        {
            AllflameSettings settings = AllflameSettings.Instance;
            bool inEncounterArea =
                AllflameContext.IsChartMapArea ||
                (AllflameContext.IsVoyageMapArea &&
                 AllflameContext.Phase == AllflamePhase.Voyage);
            if (!settings.EnableEnduringCry ||
                !inEncounterArea ||
                (VoyageRunState.Active &&
                 VoyageRunState.LanternsExhausted) ||
                !LokiPoe.IsInGame ||
                LokiPoe.Me == null ||
                LokiPoe.Me.IsDead ||
                DateTime.UtcNow < _nextCheckUtc)
            {
                return Task.FromResult(false);
            }

            if (_lastAreaHash != AllflameContext.AreaHash)
            {
                _lastAreaHash = AllflameContext.AreaHash;
                _nextCheckUtc = DateTime.MinValue;
            }

            try
            {
                var skills =
                    LokiPoe.InGameState.SkillBarHud.SkillBarSkills;
                if (skills == null)
                {
                    _nextCheckUtc =
                        DateTime.UtcNow.AddSeconds(1);
                    return Task.FromResult(false);
                }

                int configuredSlot = settings.EnduringCrySlot;
                var enduringCry = skills.FirstOrDefault(skill =>
                    skill != null &&
                    skill.IsValid &&
                    (configuredSlot > 0
                        ? skill.Slots != null &&
                          skill.Slots.Contains(configuredSlot)
                        : SafeSkillText(skill.Name).IndexOf(
                              "Enduring Cry",
                              StringComparison.OrdinalIgnoreCase) >= 0 ||
                          SafeSkillText(skill.InternalName).IndexOf(
                              "EnduringCry",
                              StringComparison.OrdinalIgnoreCase) >= 0));
                if (enduringCry == null)
                {
                    _nextCheckUtc =
                        DateTime.UtcNow.AddSeconds(3);
                    AllflameLog.Throttled(
                        "enduring_cry_missing",
                        TimeSpan.FromSeconds(10),
                        "ENDURING_CRY|Action=Skip" +
                        "|Reason=SkillNotFound" +
                        "|ConfiguredSlot=" + configuredSlot);
                    return Task.FromResult(false);
                }

                int slot = configuredSlot > 0
                    ? configuredSlot
                    : enduringCry.Slots == null
                        ? 0
                        : enduringCry.Slots.FirstOrDefault(
                            value => value >= 1 && value <= 13);
                if (slot <= 0 ||
                    enduringCry.IsOnCooldown ||
                    !LokiPoe.InGameState.SkillBarHud.CanUse(slot))
                {
                    _nextCheckUtc =
                        DateTime.UtcNow.AddMilliseconds(250);
                    return Task.FromResult(false);
                }

                var result =
                    LokiPoe.InGameState.SkillBarHud.BeginUse(
                        slot,
                        false);
                _nextCheckUtc =
                    DateTime.UtcNow.AddMilliseconds(500);
                AllflameLog.Info(
                    "ENDURING_CRY|Action=Use" +
                    "|Slot=" + slot +
                    "|Name=" + SafeSkillText(enduringCry.Name) +
                    "|InternalName=" +
                    SafeSkillText(enduringCry.InternalName) +
                    "|Result=" + result);
                return Task.FromResult(true);
            }
            catch (Exception ex)
            {
                _nextCheckUtc = DateTime.UtcNow.AddSeconds(1);
                AllflameLog.Error("ENDURING_CRY_FAILED", ex);
            }

            return Task.FromResult(false);
        }

        private static string SafeSkillText(string value)
        {
            return (value ?? String.Empty).Replace("|", "/");
        }
    }

    internal sealed partial class CollectSulphurRewardTask : ObserverTask
    {
        private DateTime _nextAttemptUtc = DateTime.MinValue;
        private readonly HashSet<int> _collectedWorldIds =
            new HashSet<int>();
        private bool _pickupPending;
        private int _pendingWorldId;
        private string _pendingItemName = String.Empty;
        private int _pendingInventoryBefore;
        private int _pendingQuantity;
        private float _pendingDistance;
        private uint _pendingAreaHash;
        private DateTime _pickupIssuedUtc = DateTime.MinValue;

        public CollectSulphurRewardTask()
            : base(
                "CollectSulphurRewardTask",
                "Collects Dead Man's Sulphur after returning from a Chart Area.") { }

        public override async Task<bool> Run()
        {
            if (AllflameContext.Phase != AllflamePhase.SovereignHub &&
                AllflameContext.Phase != AllflamePhase.VoyagePlanning)
            {
                _collectedWorldIds.Clear();
                ClearPendingPickup();
                return false;
            }

            if (_pickupPending)
            {
                int inventoryAfter =
                    AllflameContext.GetInventoryQuantity(
                        _pendingItemName);
                bool inventoryIncreased =
                    _pendingInventoryBefore >= 0 &&
                    inventoryAfter > _pendingInventoryBefore;
                bool worldItemGone =
                    IsWorldItemGone(_pendingWorldId);
                bool confirmed =
                    inventoryIncreased || worldItemGone;
                if (confirmed)
                {
                    int quantity = inventoryIncreased
                        ? Math.Max(
                            1,
                            inventoryAfter -
                            _pendingInventoryBefore)
                        : Math.Max(1, _pendingQuantity);
                    AllflameLog.Info(
                        "SULPHUR_REWARD|Action=PickupConfirmed" +
                        "|WorldId=" + _pendingWorldId +
                        "|Name=" + _pendingItemName +
                        "|Quantity=" + quantity +
                        "|Distance=" +
                        _pendingDistance.ToString("0.0") +
                        "|InventoryBefore=" +
                        _pendingInventoryBefore +
                        "|InventoryAfter=" + inventoryAfter +
                        "|WorldItemGone=" + worldItemGone +
                        "|OneActionPerCycle=True");
                    _collectedWorldIds.Add(_pendingWorldId);
                    AllflameRunState.MarkSulphurCollected();
                    AllflameSession.RecordSulphurCollected(quantity);
                    ClearPendingPickup();
                    return true;
                }

                if (AllflameContext.AreaHash == _pendingAreaHash &&
                    DateTime.UtcNow - _pickupIssuedUtc <
                        TimeSpan.FromSeconds(2))
                {
                    return true;
                }

                AllflameLog.Info(
                    "SULPHUR_REWARD|Action=PickupUnconfirmed" +
                    "|WorldId=" + _pendingWorldId +
                    "|Name=" + _pendingItemName +
                    "|InventoryBefore=" +
                    _pendingInventoryBefore +
                    "|InventoryAfter=" + inventoryAfter +
                    "|ActionNext=RetryFreshWorldItem");
                ClearPendingPickup();
            }

            WorldItem sulphur = null;
            try
            {
                sulphur = LokiPoe.ObjectManager.Objects
                    .OfType<WorldItem>()
                    .Where(world =>
                        world != null &&
                        world.IsValid &&
                        !_collectedWorldIds.Contains(world.Id))
                    .FirstOrDefault(IsSulphur);
            }
            catch
            {
            }

            if (sulphur == null)
            {
                // The reward materializes just after the area transition.
                // Hold the normal chart loop briefly so it is not abandoned.
                if (AllflameRunState.SulphurCollectionPending)
                {
                    int worldItemCount = 0;
                    try
                    {
                        worldItemCount = LokiPoe.ObjectManager.Objects
                            .OfType<WorldItem>()
                            .Count(world =>
                                world != null &&
                                world.IsValid);
                    }
                    catch
                    {
                    }
                    AllflameLog.Throttled(
                        "sulphur_reward_wait",
                        TimeSpan.FromSeconds(1),
                        "SULPHUR_REWARD|Action=Wait" +
                        "|Reason=NotVisibleYet" +
                        "|WorldItems=" + worldItemCount +
                        "|AreaId=" + AllflameContext.AreaId);
                }
                return AllflameRunState.SulphurCollectionPending;
            }

            if (DateTime.UtcNow < _nextAttemptUtc)
            {
                return true;
            }
            _nextAttemptUtc =
                DateTime.UtcNow.AddMilliseconds(250);

            const float sulphurDirectPickupRange = 70f;
            if (sulphur.Distance >
                sulphurDirectPickupRange)
            {
                bool moving = AllflameMovementCoordinator.MoveTowards(
                    sulphur.Position,
                    Name);
                AllflameLog.Throttled(
                    "sulphur_reward_move",
                    TimeSpan.FromSeconds(1),
                    "SULPHUR_REWARD|Action=Move" +
                    "|Distance=" + sulphur.Distance.ToString("0.0") +
                    "|Position=" + sulphur.Position +
                    "|DirectPickupRange=" +
                    sulphurDirectPickupRange.ToString("0.0") +
                    "|Moving=" + moving);
                return true;
            }

            Item item = null;
            try { item = sulphur.Item; }
            catch { }
            int worldId = sulphur.Id;
            string itemName =
                item == null ? String.Empty : item.FullName;
            int sulphurQuantity =
                item == null ? 1 : Math.Max(1, item.StackCount);
            uint pickupAreaHash = AllflameContext.AreaHash;
            int inventoryBefore =
                AllflameContext.GetInventoryQuantity(itemName);
            float pickupDistance = sulphur.Distance;
            bool picked = await InteractWithRecovery(sulphur);
            AllflameLog.Info(
                "SULPHUR_REWARD|Action=PickupIssued" +
                "|WorldId=" + worldId +
                "|Name=" + itemName +
                "|Quantity=" + sulphurQuantity +
                "|Distance=" +
                pickupDistance.ToString("0.0") +
                "|InteractSuccess=" + picked +
                "|InventoryBefore=" + inventoryBefore +
                "|ActionNext=ConfirmOnLaterCycle" +
                "|OneActionPerCycle=True");
            if (picked)
            {
                _pickupPending = true;
                _pendingWorldId = worldId;
                _pendingItemName = itemName;
                _pendingInventoryBefore = inventoryBefore;
                _pendingQuantity = sulphurQuantity;
                _pendingDistance = pickupDistance;
                _pendingAreaHash = pickupAreaHash;
                _pickupIssuedUtc = DateTime.UtcNow;
            }
            return true;
        }

        private void ClearPendingPickup()
        {
            _pickupPending = false;
            _pendingWorldId = 0;
            _pendingItemName = String.Empty;
            _pendingInventoryBefore = 0;
            _pendingQuantity = 0;
            _pendingDistance = 0f;
            _pendingAreaHash = 0;
            _pickupIssuedUtc = DateTime.MinValue;
        }

        private static bool IsWorldItemGone(int worldId)
        {
            try
            {
                WorldItem current = LokiPoe.ObjectManager.Objects
                    .OfType<WorldItem>()
                    .FirstOrDefault(world =>
                        world != null &&
                        world.Id == worldId);
                return current == null || !current.IsValid;
            }
            catch
            {
                return false;
            }
        }

    }

    internal abstract partial class ObserverTask
    {
        protected bool ContinueValerieApproachRecovery(
            NetworkObject valerie,
            string label)
        {
            if (!_valerieRecoveryActive)
            {
                return false;
            }
            if (valerie == null ||
                !valerie.IsValid ||
                valerie.Id != _valerieRecoveryObjectId ||
                LokiPoe.Me == null)
            {
                ResetValerieApproachRecovery(0, "TargetInvalid");
                return false;
            }

            DateTime now = DateTime.UtcNow;
            if (_valerieRecoveryAreaHash != AllflameContext.AreaHash)
            {
                ResetValerieApproachRecovery(valerie.Id);
                return false;
            }

            Vector2i player = LokiPoe.Me.Position;
            float distance =
                player.DistanceF(
                    _valerieRecoveryTarget);
            bool crossedTarget =
                _valerieRecoveryPreviousSampleUtc != DateTime.MinValue &&
                now - _valerieRecoveryPreviousSampleUtc <=
                    TimeSpan.FromSeconds(2.5) &&
                _valerieRecoveryPreviousPosition.DistanceF(player) >= 5f &&
                VectorsCrossTarget(
                    _valerieRecoveryPreviousPosition,
                    player,
                    _valerieRecoveryTarget) &&
                MoveToBoatStagingTask.DistanceToSegment(
                    _valerieRecoveryTarget.X,
                    _valerieRecoveryTarget.Y,
                    _valerieRecoveryPreviousPosition.X,
                    _valerieRecoveryPreviousPosition.Y,
                    player.X,
                    player.Y) <= ValerieRecoveryArrivalDistance;
            bool npcInRange =
                valerie.Distance <= Math.Max(
                    50f,
                    AllflameSettings.Instance.InteractDistance) &&
                !IsValerieApproachPositionBlacklisted(player);
            // Being near Valerie is not proof that the alternate path reached
            // its target; the boat geometry can block interaction at range.
            bool approachReachedTarget =
                distance <= ValerieRecoveryArrivalDistance ||
                crossedTarget;
            if (approachReachedTarget)
            {
                Vector2i completedTarget = _valerieRecoveryTarget;
                _valerieBestDistance = valerie.Distance;
                _valerieProgressUtc = now;
                AllflameProgressWatchdog.MarkProgress(
                    crossedTarget
                        ? "ValerieApproachCrossed"
                        : "ValerieApproachArrived");
                AllflameLog.Info(
                    "VALERIE_APPROACH_RECOVERY" +
                    "|Task=" + Name +
                    "|State=Arrived" +
                    "|Target=" + completedTarget +
                    "|CompletionMode=" +
                    (crossedTarget
                        ? "CrossedTargetRadius"
                        : "DirectTargetRadius") +
                    "|TargetDistance=" + distance.ToString("0.0") +
                    "|NpcDistance=" +
                    valerie.Distance.ToString("0.0") +
                    "|NpcInRange=" + npcInRange);
                ResetValerieApproachRecovery(
                    valerie.Id,
                    "RecoveryCompleted");
                return false;
            }

            if (distance < _valerieRecoveryBestTargetDistance)
            {
                float improvement =
                    _valerieRecoveryProgressBaselineDistance - distance;
                _valerieRecoveryBestTargetDistance = distance;
                if (improvement >= ValerieRecoveryProgressDistance)
                {
                    _valerieRecoveryProgressBaselineDistance = distance;
                    _valerieRecoveryLastProgressUtc = now;
                    AllflameProgressWatchdog.MarkProgress(
                        "ValerieApproachDistanceImproved");
                    AllflameLog.Info(
                        "VALERIE_APPROACH_PROGRESS" +
                        "|Task=" + Name +
                        "|Target=" + _valerieRecoveryTarget +
                        "|Distance=" + distance.ToString("0.0") +
                        "|BestDistance=" +
                        _valerieRecoveryBestTargetDistance.ToString("0.0") +
                        "|Improvement=" + improvement.ToString("0.0"));
                }
            }

            _valerieRecoveryPreviousPosition = player;
            _valerieRecoveryPreviousSampleUtc = now;
            bool timedOut =
                _valerieRecoveryStartedUtc != DateTime.MinValue &&
                now - _valerieRecoveryStartedUtc >=
                    TimeSpan.FromSeconds(
                        ValerieRecoveryHardTimeoutSeconds);
            bool noProgress =
                _valerieRecoveryLastProgressUtc != DateTime.MinValue &&
                now - _valerieRecoveryLastProgressUtc >=
                    TimeSpan.FromSeconds(
                        ValerieRecoveryNoProgressSeconds);
            if (timedOut ||
                _valerieRecoveryCandidateFailures >=
                    ValerieRecoveryMaximumCandidates)
            {
                string detail =
                    "ActiveTask=" + Name +
                    "|Target=" + _valerieRecoveryTarget +
                    "|Npc=" + valerie.Position +
                    "|CurrentDistance=" + distance.ToString("0.0") +
                    "|BestDistance=" +
                    _valerieRecoveryBestTargetDistance.ToString("0.0") +
                    "|Candidates=" +
                    _valerieRecoveryCandidateFailures +
                    "|Reloads=" + _valerieRecoveryPatherReloads +
                    "|ElapsedSeconds=" +
                    (int)(now - _valerieRecoveryStartedUtc)
                        .TotalSeconds;
                AllflameLog.Info(
                    "VALERIE_APPROACH_EXHAUSTED|" + detail);
                AllflameStopController.Stop(
                    "ValerieApproachTimeout",
                    detail);
                return true;
            }

            if (noProgress)
            {
                _valerieRecoveryCandidateFailures++;
                BlacklistValerieRecoveryTarget(
                    "AlternateApproachNoProgress");
                if (_valerieRecoveryPatherReloads <
                    ValerieRecoveryMaximumPatherReloads)
                {
                    _valerieRecoveryPatherReloads++;
                    try
                    {
                        ExilePather.Reload(true);
                    }
                    catch
                    {
                    }
                    AllflameMover mover =
                        PlayerMoverManager.Current as AllflameMover;
                    if (mover != null)
                    {
                        mover.ResetApproachState();
                    }
                }
                _valerieRecoveryActive = false;
                AllflameProgressWatchdog.SetRetry(
                    _valerieRecoveryCandidateFailures);
                AllflameLog.Info(
                    "VALERIE_APPROACH_RECOVERY" +
                    "|Task=" + Name +
                    "|State=RotateCandidate" +
                    "|Reason=NoProgress" +
                    "|Candidate=" +
                    _valerieRecoveryCandidateFailures +
                    "|Reloads=" + _valerieRecoveryPatherReloads +
                    "|BestDistance=" +
                    _valerieRecoveryBestTargetDistance.ToString("0.0"));
                StartValerieApproachRecovery(
                    valerie,
                    label,
                    "AlternateApproachNoProgress");
                return true;
            }

            bool moving = AllflameMovementCoordinator.MoveTowards(
                _valerieRecoveryTarget,
                Name + " Valerie approach recovery");
            if (!moving)
            {
                _valerieRecoveryLastProgressUtc =
                    now - TimeSpan.FromSeconds(
                        ValerieRecoveryNoProgressSeconds);
            }
            AllflameLog.Throttled(
                "valerie_approach_move_" + Name,
                TimeSpan.FromSeconds(1),
                "VALERIE_APPROACH_RECOVERY" +
                "|Task=" + Name +
                "|State=Moving" +
                "|Label=" + label +
                "|Target=" + _valerieRecoveryTarget +
                "|Distance=" + distance.ToString("0.0") +
                "|Moving=" + moving);
            return true;
        }

        protected bool StartValerieApproachRecovery(
            NetworkObject valerie,
            string label,
            string reason)
        {
            if (valerie == null ||
                !valerie.IsValid ||
                LokiPoe.Me == null)
            {
                AllflameRunState.RequireBoatStaging(
                    "ValerieRecoveryTargetMissing");
                return false;
            }

            bool npcPositionChanged =
                _valerieRecoveryStartedUtc != DateTime.MinValue &&
                _valerieRecoveryNpcPosition != new Vector2i() &&
                _valerieRecoveryNpcPosition.DistanceF(
                    valerie.Position) > 5f;
            if (_valerieRecoveryObjectId != valerie.Id ||
                npcPositionChanged)
            {
                ResetValerieApproachRecovery(
                    valerie.Id,
                    npcPositionChanged
                        ? "TargetPositionChanged"
                        : "TargetObjectChanged");
            }

            Vector2i player = LokiPoe.Me.Position;
            DateTime now = DateTime.UtcNow;
            if (_valerieRecoveryStartedUtc == DateTime.MinValue)
            {
                _valerieRecoveryStartedUtc = now;
                _valerieRecoveryLastProgressUtc = now;
                _valerieRecoveryAreaHash = AllflameContext.AreaHash;
                _valerieRecoveryNpcPosition = valerie.Position;
                _valerieRecoveryCandidateFailures = 0;
                _valerieRecoveryPatherReloads = 0;
                AllflameProgressWatchdog.BeginExplicitProgress(
                    Name,
                    valerie.Id,
                    "ValerieApproachRecovery");
            }
            Vector2i selected = new Vector2i();
            bool found = false;
            int selectedStep = -1;
            for (int offset = 0; offset < 16; offset++)
            {
                int step =
                    (_valerieRecoveryStep + offset) % 16;
                int direction = step % 8;
                int radius = step < 8 ? 34 : 44;
                double angle = direction * Math.PI / 4.0;
                Vector2i candidate = new Vector2i(
                    valerie.Position.X +
                    (int)Math.Round(Math.Cos(angle) * radius),
                    valerie.Position.Y +
                    (int)Math.Round(Math.Sin(angle) * radius));
                // The deck geometry beside Valerie is translated between boat
                // instances, so an absolute coordinate blacklist is not
                // sufficient. Her east-side approach sector maps to the raised
                // waypoint platform in the observed layouts and lets
                // InteractWith report success without opening dialogue.
                if (direction == 0 ||
                    direction == 1 ||
                    direction == 7)
                {
                    AllflameLog.Throttled(
                        "valerie_east_approach_blacklisted",
                        TimeSpan.FromSeconds(2),
                        "VALERIE_APPROACH_BLACKLIST" +
                        "|Task=" + Name +
                        "|State=CandidateSkipped" +
                        "|Reason=KnownBoatNpcEastSector" +
                        "|Candidate=" + candidate +
                        "|Npc=" + valerie.Position);
                    continue;
                }
                if (player.DistanceF(candidate) <= 14f)
                {
                    continue;
                }
                if (IsValerieApproachPositionBlacklisted(
                        candidate))
                {
                    AllflameLog.Throttled(
                        "valerie_approach_candidate_blacklisted",
                        TimeSpan.FromSeconds(2),
                        "VALERIE_APPROACH_BLACKLIST" +
                        "|Task=" + Name +
                        "|State=CandidateSkipped" +
                        "|Candidate=" + candidate);
                    continue;
                }

                bool pathExists;
                try
                {
                    pathExists =
                        ExilePather.PathExistsBetween(
                            player,
                            candidate,
                            false);
                }
                catch
                {
                    pathExists = false;
                }
                if (!pathExists)
                {
                    continue;
                }

                selected = candidate;
                selectedStep = step;
                found = true;
                break;
            }

            if (!found)
            {
                _valerieRecoveryActive = false;
                _valerieRecoveryCandidateFailures++;
                if (_valerieRecoveryPatherReloads <
                    ValerieRecoveryMaximumPatherReloads)
                {
                    _valerieRecoveryPatherReloads++;
                    try
                    {
                        ExilePather.Reload(true);
                    }
                    catch
                    {
                    }
                    AllflameMover mover =
                        PlayerMoverManager.Current as AllflameMover;
                    if (mover != null)
                    {
                        mover.ResetApproachState();
                    }
                }
                AllflameProgressWatchdog.SetRetry(
                    _valerieRecoveryCandidateFailures);
                AllflameLog.Info(
                    "VALERIE_APPROACH_RECOVERY" +
                    "|Task=" + Name +
                    "|State=NoReachableCandidate" +
                    "|Reason=" + reason +
                    "|Candidates=" +
                    _valerieRecoveryCandidateFailures +
                    "|Reloads=" + _valerieRecoveryPatherReloads +
                    "|Action=RetryBoundedRecovery");
                if (_valerieRecoveryCandidateFailures >=
                        ValerieRecoveryMaximumCandidates ||
                    (_valerieRecoveryStartedUtc != DateTime.MinValue &&
                     DateTime.UtcNow - _valerieRecoveryStartedUtc >=
                         TimeSpan.FromSeconds(
                             ValerieRecoveryHardTimeoutSeconds)))
                {
                    string detail =
                        "ActiveTask=" + Name +
                        "|Npc=" + valerie.Position +
                        "|Candidates=" +
                        _valerieRecoveryCandidateFailures +
                        "|Reloads=" + _valerieRecoveryPatherReloads +
                        "|Reason=NoReachableCandidate";
                    AllflameLog.Info(
                        "VALERIE_APPROACH_EXHAUSTED|" + detail);
                    AllflameStopController.Stop(
                        "ValerieApproachTimeout",
                        detail);
                }
                return true;
            }

            _valerieRecoveryStep =
                (selectedStep + 1) % 16;
            _valerieRecoveryTarget = selected;
            _valerieRecoveryActive = true;
            _valerieBestDistance = valerie.Distance;
            _valerieProgressUtc = now;
            _valerieRecoveryAreaHash = AllflameContext.AreaHash;
            _valerieRecoveryLastProgressUtc = now;
            _valerieRecoveryPreviousPosition = player;
            _valerieRecoveryPreviousSampleUtc = now;
            _valerieRecoveryBestTargetDistance =
                player.DistanceF(selected);
            _valerieRecoveryProgressBaselineDistance =
                _valerieRecoveryBestTargetDistance;
            AllflameProgressWatchdog.BeginExplicitProgress(
                Name,
                valerie.Id,
                selected.ToString());
            AllflameProgressWatchdog.SetRetry(
                _valerieRecoveryCandidateFailures);
            bool moving = AllflameMovementCoordinator.MoveTowards(
                selected,
                Name + " Valerie alternate approach");
            if (!moving)
            {
                _valerieRecoveryLastProgressUtc =
                    now - TimeSpan.FromSeconds(
                        ValerieRecoveryNoProgressSeconds);
            }
            AllflameLog.Info(
                "VALERIE_APPROACH_RECOVERY" +
                "|Task=" + Name +
                "|State=Selected" +
                "|Reason=" + reason +
                "|Label=" + label +
                "|Npc=" + valerie.Position +
                "|Player=" + player +
                "|Target=" + selected +
                "|Radius=" +
                valerie.Position.DistanceF(selected)
                    .ToString("0.0") +
                "|Step=" + selectedStep +
                "|Moving=" + moving);
            return moving;
        }

        protected bool IsValerieApproachPositionBlacklisted(
            Vector2i position)
        {
            if (position.DistanceF(
                    KnownBlockedValerieApproach) <= 24f)
            {
                return true;
            }

            if (!_hasDynamicBlockedValerieApproach ||
                DateTime.UtcNow >=
                    _dynamicBlockedValerieUntilUtc ||
                AllflameContext.AreaHash !=
                    _dynamicBlockedValerieAreaHash)
            {
                return false;
            }

            return position.DistanceF(
                _dynamicBlockedValerieApproach) <= 24f;
        }

        protected void BlacklistCurrentValerieApproach(
            string reason)
        {
            if (LokiPoe.Me == null)
            {
                return;
            }

            _dynamicBlockedValerieApproach =
                LokiPoe.Me.Position;
            _dynamicBlockedValerieAreaHash =
                AllflameContext.AreaHash;
            _dynamicBlockedValerieUntilUtc =
                DateTime.UtcNow.AddMinutes(10);
            _hasDynamicBlockedValerieApproach = true;
            AllflameLog.Info(
                "VALERIE_APPROACH_BLACKLIST" +
                "|Task=" + Name +
                "|State=Added" +
                "|Reason=" + reason +
                "|Position=" +
                _dynamicBlockedValerieApproach +
                "|Radius=24" +
                "|DurationSeconds=600" +
                "|KnownBlocked=" +
                KnownBlockedValerieApproach);
        }

        private void BlacklistValerieRecoveryTarget(string reason)
        {
            _dynamicBlockedValerieApproach =
                _valerieRecoveryTarget;
            _dynamicBlockedValerieAreaHash =
                AllflameContext.AreaHash;
            _dynamicBlockedValerieUntilUtc =
                DateTime.UtcNow.AddMinutes(10);
            _hasDynamicBlockedValerieApproach = true;
            AllflameLog.Info(
                "VALERIE_APPROACH_BLACKLIST" +
                "|Task=" + Name +
                "|State=Added" +
                "|Reason=" + reason +
                "|Position=" +
                _dynamicBlockedValerieApproach +
                "|Radius=24" +
                "|DurationSeconds=600");
        }

        private static bool VectorsCrossTarget(
            Vector2i previous,
            Vector2i current,
            Vector2i target)
        {
            double previousX = previous.X - target.X;
            double previousY = previous.Y - target.Y;
            double currentX = current.X - target.X;
            double currentY = current.Y - target.Y;
            return previousX * currentX + previousY * currentY <= 0;
        }

        protected void ResetValerieApproachRecovery(
            int objectId,
            string reason = null)
        {
            bool hadState =
                _valerieRecoveryStartedUtc != DateTime.MinValue ||
                _valerieRecoveryActive ||
                _valerieRecoveryCandidateFailures > 0 ||
                _valerieRecoveryPatherReloads > 0;
            _valerieRecoveryObjectId = objectId;
            _valerieRecoveryStep = 0;
            _valerieRecoveryActive = false;
            _valerieBestDistance = Single.MaxValue;
            _valerieProgressUtc = DateTime.MinValue;
            _valerieRecoveryAreaHash = 0;
            _valerieRecoveryStartedUtc = DateTime.MinValue;
            _valerieRecoveryLastProgressUtc = DateTime.MinValue;
            _valerieRecoveryPreviousSampleUtc = DateTime.MinValue;
            _valerieRecoveryPreviousPosition = new Vector2i();
            _valerieRecoveryTarget = new Vector2i();
            _valerieRecoveryNpcPosition = new Vector2i();
            _valerieRecoveryBestTargetDistance = Single.MaxValue;
            _valerieRecoveryProgressBaselineDistance = Single.MaxValue;
            _valerieRecoveryCandidateFailures = 0;
            _valerieRecoveryPatherReloads = 0;
            if (!String.IsNullOrEmpty(reason) && hadState)
            {
                AllflameLog.Info(
                    "VALERIE_APPROACH_RESET" +
                    "|Task=" + Name +
                    "|Reason=" + reason +
                    "|ObjectId=" + objectId);
            }
        }

    }

    internal sealed partial class CollectSulphurRewardTask : ObserverTask
    {
        private static bool IsSulphur(WorldItem world)
        {
            try
            {
                Item item = world.Item;
                if (item == null || !item.IsValid)
                {
                    return false;
                }

                string name = item.FullName ?? String.Empty;
                string metadata = item.Metadata ?? String.Empty;
                return name.IndexOf(
                           "Sulphur",
                           StringComparison.OrdinalIgnoreCase) >= 0 ||
                       metadata.IndexOf(
                           "Sulphur",
                           StringComparison.OrdinalIgnoreCase) >= 0;
            }
            catch
            {
                return false;
            }
        }
    }

    internal sealed class TravelToSovereignTask : ObserverTask
    {
        private DateTime _nextBoatUtc = DateTime.MinValue;
        private bool _nativeTravelPending;

        public TravelToSovereignTask()
            : base("TravelToSovereignTask", "Uses /boat to travel to The Sovereign.") { }

        public override async Task<bool> Run()
        {
            if (AllflameContext.Phase != AllflamePhase.OutsideContent)
            {
                _nativeTravelPending = false;
                return false;
            }

            if (DateTime.UtcNow < _nextBoatUtc)
            {
                return true;
            }

            _nextBoatUtc = DateTime.UtcNow.AddSeconds(8);

            if (AllflameSettings.Instance.UseNativeSovereignTravel)
            {
                if (_nativeTravelPending)
                {
                    _nativeTravelPending = false;
                    AllflameLog.Info(
                        "ACTION|Task=" + Name +
                        "|Action=GoToTheSovereign" +
                        "|Mode=Native" +
                        "|InputSent=True" +
                        "|Postcondition=False" +
                        "|Fallback=Chat" +
                        "|Reason=AreaDidNotChangeWithin8Seconds");
                }
                else
                {
                    DpbActionResult nativeResult =
                        DpbNativeApi.GoToTheSovereign();
                    AllflameLog.Info(
                        "ACTION|Task=" + Name +
                        "|Action=GoToTheSovereign" +
                        "|Mode=" + nativeResult.Mode +
                        "|InputSent=" + nativeResult.InputSent +
                        "|Postcondition=" +
                        nativeResult.PostconditionVerified +
                        "|Reason=" + nativeResult.Reason +
                        "|Exception=" + nativeResult.Exception);
                    if (nativeResult.InputSent)
                    {
                        _nativeTravelPending = true;
                        AllflameRunState.RequireBoatStaging();
                        return true;
                    }
                    AllflameLog.Info(
                        "UI_FALLBACK|Task=" + Name +
                        "|From=Native" +
                        "|To=Chat" +
                        "|Reason=" + nativeResult.Reason);
                }
            }

            if (!LokiPoe.ProcessHookManager.IsEnabled)
            {
                LokiPoe.ProcessHookManager.Enable();
                await LokiCoroutine.Sleep(250);
            }

            var result = LokiPoe.InGameState.ChatPanel.Chat("/boat");
            AllflameRunState.RequireBoatStaging();
            AllflameLog.Info(
                "ACTION|Task=" + Name + "|Action=Chat|Command=/boat|Result=" + result);

            if (String.Equals(
                result.ToString(),
                "ProcessHookManagerNotEnabled",
                StringComparison.OrdinalIgnoreCase))
            {
                await SendBoatWithKeyboard();
            }

            return true;
        }

        private static async Task SendBoatWithKeyboard()
        {
            LokiPoe.Input.SimulateKeyEvent(
                System.Windows.Forms.Keys.Enter, true, false, true);
            await LokiCoroutine.Sleep(80);

            foreach (char ch in "/boat")
            {
                LokiPoe.Input.SimulateKeyEvent(ch);
                await LokiCoroutine.Sleep(35);
            }

            LokiPoe.Input.SimulateKeyEvent(
                System.Windows.Forms.Keys.Enter, true, false, true);
            AllflameLog.Info(
                "ACTION|Task=TravelToSovereignTask|Action=KeyboardFallback|Command=/boat");
        }
    }

    internal sealed class MoveToBoatStagingTask : ObserverTask
    {
        private const int ArrivalDistance = 18;
        private const float ProgressDistance = 3f;
        private const float MinimumSampleMovement = 5f;
        private const float LargeRelocationDistance = 250f;
        private const double MaximumSampleAgeSeconds = 2.5;
        private const int NoProgressSeconds = 6;
        private const int OscillationWindowSeconds = 6;
        private const int MaximumRecoveries = 2;
        private const int RecoveryCooldownSeconds = 2;
        private const int HardTimeoutSeconds = 30;
        private static readonly Vector2i KnownHubStagingPoint =
            new Vector2i(286, 457);
        private bool _tracking;
        private uint _trackingAreaHash;
        private Vector2i _trackingTarget;
        private Vector2i _previousPosition;
        private DateTime _previousSampleUtc = DateTime.MinValue;
        private DateTime _movementStartedUtc = DateTime.MinValue;
        private DateTime _lastProgressUtc = DateTime.MinValue;
        private DateTime _pathFailureSinceUtc = DateTime.MinValue;
        private DateTime _recoveryCooldownUntilUtc = DateTime.MinValue;
        private float _bestDistance = Single.MaxValue;
        private float _progressReferenceDistance = Single.MaxValue;
        private int _recoveryAttempts;
        private readonly Queue<DateTime> _sideCrossings =
            new Queue<DateTime>();

        public MoveToBoatStagingTask()
            : base(
                "MoveToBoatStagingTask",
                "Moves to the central staging point on the right of Chart Storage after /boat.") { }

        public override void Start()
        {
            ResetLocalState();
        }

        public override void Stop()
        {
            ResetLocalState();
            AllflameProgressWatchdog.Clear(Name);
        }

        public override Task<bool> Run()
        {
            if (!AllflameRunState.BoatStagingRequired)
            {
                ResetLocalState();
                AllflameProgressWatchdog.Clear(Name);
                return Task.FromResult(false);
            }

            bool inHub =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            if (!inHub || LokiPoe.Me == null)
            {
                ResetLocalState();
                AllflameProgressWatchdog.Clear(Name);
                AllflameLog.Throttled(
                    "boat_staging_wait_hub",
                    TimeSpan.FromSeconds(2),
                    "BOAT_STAGING|State=WaitingForSovereign" +
                    "|Phase=" + AllflameContext.Phase);
                return Task.FromResult(true);
            }

            Vector2i target;
            string anchor;
            ResolveTarget(out target, out anchor);
            Vector2i player = LokiPoe.Me.Position;
            uint areaHash = AllflameContext.AreaHash;
            if (!_tracking ||
                _trackingAreaHash != areaHash ||
                _trackingTarget.DistanceF(target) > 0.1f)
            {
                InitializeTracking(areaHash, target, anchor, player);
            }

            DateTime now = DateTime.UtcNow;
            float distance = player.DistanceF(target);
            if (_tracking &&
                _previousSampleUtc != DateTime.MinValue &&
                _previousPosition.DistanceF(player) > LargeRelocationDistance)
            {
                _previousPosition = player;
                _previousSampleUtc = now;
                _sideCrossings.Clear();
            }
            if (distance <= ArrivalDistance)
            {
                Complete(player, distance, "Direct");
                return Task.FromResult(false);
            }

            double segmentDistance;
            double dotProduct;
            bool sampledCrossing =
                TrySampledCrossing(
                    areaHash,
                    target,
                    player,
                    now,
                    out segmentDistance,
                    out dotProduct);
            if (sampledCrossing)
            {
                AllflameLog.Info(
                    "BOAT_STAGING_CROSSING" +
                    "|Previous=" + _previousPosition +
                    "|Current=" + player +
                    "|Target=" + target +
                    "|SegmentDistance=" + segmentDistance.ToString("0.0") +
                    "|DotProduct=" + dotProduct.ToString("0.0"));
                Complete(player, distance, "CrossedArrivalRadius");
                return Task.FromResult(false);
            }

            bool progress = UpdateConvergence(distance, now);
            if (progress)
            {
                AllflameProgressWatchdog.MarkProgress("BoatStagingConvergence");
            }

            _previousPosition = player;
            _previousSampleUtc = now;

            string recoveryReason = GetRecoveryReason(now);
            if (recoveryReason != null)
            {
                if (TryRecover(recoveryReason, now))
                    return Task.FromResult(true);
                StopForBoatStaging(
                    "RecoveryLimitExceeded",
                    now,
                    distance);
                return Task.FromResult(false);
            }

            if (_movementStartedUtc != DateTime.MinValue &&
                now - _movementStartedUtc >=
                TimeSpan.FromSeconds(HardTimeoutSeconds))
            {
                StopForBoatStaging("HardTimeout", now, distance);
                return Task.FromResult(false);
            }

            if (now < _recoveryCooldownUntilUtc)
                return Task.FromResult(true);

            bool moving = AllflameMovementCoordinator.MoveTowards(target, Name);
            if (!moving && _pathFailureSinceUtc == DateTime.MinValue)
                _pathFailureSinceUtc = now;
            if (moving)
            {
                _pathFailureSinceUtc = DateTime.MinValue;
                if (_movementStartedUtc == DateTime.MinValue)
                    _movementStartedUtc = now;
            }

            AllflameLog.Throttled(
                "boat_staging_move",
                TimeSpan.FromSeconds(1),
                "BOAT_STAGING|State=Moving" +
                "|Anchor=" + anchor +
                "|Target=" + target +
                "|Player=" + player +
                "|Distance=" + distance.ToString("0.0") +
                "|Moving=" + moving +
                "|BestDistance=" + _bestDistance.ToString("0.0") +
                "|NoProgressSeconds=" +
                Math.Max(0, (int)(now - _lastProgressUtc).TotalSeconds) +
                "|Crossings=" + _sideCrossings.Count +
                "|Recovery=" + _recoveryAttempts +
                "|MoveSkill=" + AllflameMover.DescribeSelectedMovementSkill());
            return Task.FromResult(true);
        }

        private void ResolveTarget(out Vector2i target, out string anchor)
        {
            NetworkObject storage = AllflameContext.ChartStorageObject;
            NetworkObject valerie = AllflameContext.ValerieObject;
            if (storage != null && storage.IsValid)
            {
                target = new Vector2i(
                    storage.Position.X + 55,
                    storage.Position.Y + 15);
                anchor = "ChartStorage";
            }
            else if (valerie != null && valerie.IsValid)
            {
                target = new Vector2i(
                    valerie.Position.X - 17,
                    valerie.Position.Y - 14);
                anchor = "ValerieFallback";
            }
            else
            {
                target = KnownHubStagingPoint;
                anchor = "KnownDeepwaterHub";
            }
        }

        private void InitializeTracking(
            uint areaHash,
            Vector2i target,
            string anchor,
            Vector2i player)
        {
            DateTime now = DateTime.UtcNow;
            _tracking = true;
            _trackingAreaHash = areaHash;
            _trackingTarget = target;
            _previousPosition = player;
            _previousSampleUtc = now;
            _movementStartedUtc = DateTime.MinValue;
            _lastProgressUtc = now;
            _pathFailureSinceUtc = DateTime.MinValue;
            _recoveryCooldownUntilUtc = DateTime.MinValue;
            _bestDistance = player.DistanceF(target);
            _progressReferenceDistance = _bestDistance;
            _recoveryAttempts = 0;
            _sideCrossings.Clear();
            AllflameProgressWatchdog.BeginExplicitProgress(
                Name,
                0,
                target.ToString());
            AllflameProgressWatchdog.SetRetry(0);
            AllflameLog.Info(
                "BOAT_STAGING_START" +
                "|Anchor=" + anchor +
                "|Target=" + target +
                "|Player=" + player +
                "|Distance=" + _bestDistance.ToString("0.0") +
                "|AreaHash=" + areaHash);
            AllflameMover mover = PlayerMoverManager.Current as AllflameMover;
            if (mover != null)
                mover.LogSelectedMovementSkill(true);
        }

        private bool TrySampledCrossing(
            uint areaHash,
            Vector2i target,
            Vector2i current,
            DateTime now,
            out double segmentDistance,
            out double dotProduct)
        {
            segmentDistance = Double.MaxValue;
            dotProduct = 0;
            if (!_tracking ||
                _trackingAreaHash != areaHash ||
                _trackingTarget.DistanceF(target) > 0.1f)
                return false;

            double age = (now - _previousSampleUtc).TotalSeconds;
            if (age > MaximumSampleAgeSeconds ||
                _previousPosition.DistanceF(current) < MinimumSampleMovement)
                return false;

            double previousX = _previousPosition.X - target.X;
            double previousY = _previousPosition.Y - target.Y;
            double currentX = current.X - target.X;
            double currentY = current.Y - target.Y;
            dotProduct = previousX * currentX + previousY * currentY;
            if (dotProduct > 0)
                return false;

            segmentDistance = DistanceToSegment(
                target.X,
                target.Y,
                _previousPosition.X,
                _previousPosition.Y,
                current.X,
                current.Y);
            if (segmentDistance <= ArrivalDistance)
                return true;

            _sideCrossings.Enqueue(now);
            PruneCrossings(now);
            return false;
        }

        private bool UpdateConvergence(float distance, DateTime now)
        {
            if (distance >= _bestDistance)
                return false;

            _bestDistance = distance;
            float improvement = _progressReferenceDistance - distance;
            if (improvement < ProgressDistance)
                return false;

            _progressReferenceDistance = distance;
            _lastProgressUtc = now;
            _sideCrossings.Clear();
            AllflameLog.Info(
                "BOAT_STAGING_PROGRESS" +
                "|Distance=" + distance.ToString("0.0") +
                "|BestDistance=" + _bestDistance.ToString("0.0") +
                "|Improvement=" + improvement.ToString("0.0") +
                "|ElapsedWithoutProgress=0");
            return true;
        }

        private string GetRecoveryReason(DateTime now)
        {
            PruneCrossings(now);
            if (_sideCrossings.Count >= 2 &&
                now - _lastProgressUtc >=
                TimeSpan.FromSeconds(NoProgressSeconds))
            {
                AllflameLog.Info(
                    "BOAT_STAGING_OSCILLATION" +
                    "|Crossings=" + _sideCrossings.Count +
                    "|WindowSeconds=" + OscillationWindowSeconds +
                    "|BestDistance=" + _bestDistance.ToString("0.0") +
                    "|CurrentDistance=" + _previousPosition.DistanceF(_trackingTarget).ToString("0.0"));
                return "Oscillation";
            }

            if (_pathFailureSinceUtc != DateTime.MinValue &&
                now - _pathFailureSinceUtc >= TimeSpan.FromSeconds(2))
                return "PathFailure";

            if (now - _lastProgressUtc >=
                TimeSpan.FromSeconds(NoProgressSeconds))
                return "NoProgress";

            return null;
        }

        private bool TryRecover(string reason, DateTime now)
        {
            if (_recoveryAttempts >= MaximumRecoveries)
                return false;

            _recoveryAttempts++;
            AllflameProgressWatchdog.SetRetry(_recoveryAttempts);
            bool reloaded = true;
            try
            {
                ExilePather.Reload(true);
            }
            catch
            {
                reloaded = false;
            }

            AllflameMover mover = PlayerMoverManager.Current as AllflameMover;
            if (mover != null)
                mover.ResetApproachState();
            try
            {
                AllflameContext.Refresh(true);
            }
            catch
            {
            }

            Vector2i target;
            string anchor;
            ResolveTarget(out target, out anchor);
            Vector2i player = LokiPoe.Me == null
                ? _previousPosition
                : LokiPoe.Me.Position;
            _trackingAreaHash = AllflameContext.AreaHash;
            _trackingTarget = target;
            _previousPosition = player;
            _previousSampleUtc = now;
            _lastProgressUtc = now;
            _pathFailureSinceUtc = DateTime.MinValue;
            _recoveryCooldownUntilUtc = now.AddSeconds(RecoveryCooldownSeconds);
            _bestDistance = player.DistanceF(target);
            _progressReferenceDistance = _bestDistance;
            _sideCrossings.Clear();
            AllflameProgressWatchdog.BeginExplicitProgress(
                Name,
                0,
                target.ToString());
            AllflameProgressWatchdog.SetRetry(_recoveryAttempts);
            AllflameLog.Info(
                "BOAT_STAGING_RECOVERY" +
                "|Attempt=" + _recoveryAttempts +
                "|Reason=" + reason +
                "|BestDistance=" + _bestDistance.ToString("0.0") +
                "|Action=ReloadPather" +
                "|Result=" + (reloaded ? "Success" : "Failed"));
            return true;
        }

        private void Complete(Vector2i position, float distance, string mode)
        {
            AllflameRunState.MarkBoatStagingComplete(position);
            AllflameLog.Info(
                "BOAT_STAGING_COMPLETE" +
                "|Position=" + position +
                "|Distance=" + distance.ToString("0.0") +
                "|CompletionMode=" + mode);
            AllflameProgressWatchdog.Clear(Name);
            ResetLocalState();
        }

        private void StopForBoatStaging(
            string reason,
            DateTime now,
            float distance)
        {
            string detail =
                "ActiveTask=" + Name +
                "|ElapsedSeconds=" +
                (_movementStartedUtc == DateTime.MinValue
                    ? 0
                    : Math.Max(
                        0,
                        (int)(now - _movementStartedUtc).TotalSeconds)) +
                "|Recoveries=" + _recoveryAttempts +
                "|BestDistance=" + _bestDistance.ToString("0.0") +
                "|CurrentDistance=" + distance.ToString("0.0") +
                "|MoveSkill=" + AllflameMover.DescribeSelectedMovementSkill();
            AllflameLog.Info(
                "BOAT_STAGING_TIMEOUT|" + detail + "|Reason=" + reason);
            AllflameStopController.Stop("BoatStagingTimeout", detail);
        }

        private void PruneCrossings(DateTime now)
        {
            while (_sideCrossings.Count > 0 &&
                now - _sideCrossings.Peek() >
                TimeSpan.FromSeconds(OscillationWindowSeconds))
                _sideCrossings.Dequeue();
        }

        private void ResetLocalState()
        {
            _tracking = false;
            _trackingAreaHash = 0;
            _trackingTarget = new Vector2i();
            _previousPosition = new Vector2i();
            _previousSampleUtc = DateTime.MinValue;
            _movementStartedUtc = DateTime.MinValue;
            _lastProgressUtc = DateTime.MinValue;
            _pathFailureSinceUtc = DateTime.MinValue;
            _recoveryCooldownUntilUtc = DateTime.MinValue;
            _bestDistance = Single.MaxValue;
            _progressReferenceDistance = Single.MaxValue;
            _recoveryAttempts = 0;
            _sideCrossings.Clear();
        }

        internal static double DistanceToSegment(
            double pointX,
            double pointY,
            double startX,
            double startY,
            double endX,
            double endY)
        {
            double dx = endX - startX;
            double dy = endY - startY;
            double lengthSquared = dx * dx + dy * dy;
            if (lengthSquared <= Double.Epsilon)
                return Math.Sqrt(
                    (pointX - startX) * (pointX - startX) +
                    (pointY - startY) * (pointY - startY));

            double projection =
                ((pointX - startX) * dx + (pointY - startY) * dy) /
                lengthSquared;
            projection = Math.Max(0, Math.Min(1, projection));
            double closestX = startX + projection * dx;
            double closestY = startY + projection * dy;
            return Math.Sqrt(
                (pointX - closestX) * (pointX - closestX) +
                (pointY - closestY) * (pointY - closestY));
        }
    }

    internal sealed class PreVoyageChartStashTask : ObserverTask
    {
        private const int MaximumStorageOpenAttempts = 3;
        private const int MaximumStorageResolveAttempts = 3;
        private const int StorageMainTabCount = 3;
        private const int StorageSubTabCount = 5;
        private static readonly TimeSpan StorageDepositTimeout =
            TimeSpan.FromSeconds(30);
        private DateTime _retryAfterUtc = DateTime.MinValue;
        private DateTime _storageStartedUtc = DateTime.MinValue;
        private int _failedChartKey;
        private int _failedAttempts;
        private int _movedCharts;
        private int _storageMovedCharts;
        private int _stashOpenAttempts;
        private int _tabAttempts;
        private int _storageOpenAttempts;
        private int _storageResolveAttempts;
        private int _storageMainTab;
        private int _storageSubTab;
        private string _storageFailureReason = String.Empty;
        private bool _storageUnavailable;
        private bool _storageStartLogged;
        private bool _storageOpenPending;
        private InventoryControlWrapper _storageControl;
        private InventorySlotUiElement _storageSlot;
        private uint _lastAreaHash;
        private bool _storagePageReady;
        private bool _storageDepositPending;
        private int _storagePendingChartKey;
        private int _storagePendingBeforeCount;
        private int _storagePendingBeforeUnits;
        private string _storagePendingChartName = String.Empty;
        private DateTime _storageDepositIssuedUtc = DateTime.MinValue;

        public PreVoyageChartStashTask()
            : base(
                "PreVoyageChartStashTask",
                "Finalizes the non-Chart stash before entering a Voyage while retaining Charts in inventory.") { }

        public override void Start()
        {
            ResetLocalState();
        }

        public override void Stop()
        {
            ResetLocalState();
            AllflameProgressWatchdog.Clear();
        }

        public override async Task<bool> Run()
        {
            AllflameSettings settings = AllflameSettings.Instance;
            bool inHub =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            bool required =
                settings.StashBeforeVoyage &&
                AllflameRunState.VoyageStarted &&
                !AllflameRunState.VoyagePreStashCompleted;
            if (!required || !inHub)
            {
                ResetLocalState();
                AllflameProgressWatchdog.Clear();
                return false;
            }

            int nonChartItems = CountNonChartInventoryItems();
            if (nonChartItems > 0)
            {
                AllflameLog.Throttled(
                    "voyage_pre_stash_wait_loot",
                    TimeSpan.FromSeconds(2),
                    "VOYAGE_PRE_STASH|Stage=Loot|State=Waiting" +
                    "|NonChartItems=" +
                    nonChartItems);
                AllflameProgressWatchdog.Clear();
                return true;
            }

            // StashLootTask already transferred every eligible non-Chart item.
            // Charts must remain in inventory; only finalize the state gate so
            // EnterStartedVoyageTask can proceed to the Bathysphere.
            if (!ShouldTransferChartsBeforeVoyage())
            {
                return await CompletePreStashWithoutChartTransfer(
                    GetInventoryCharts().Count);
            }

            AllflameProgressWatchdog.Begin(
                Name,
                AllflameContext.StashObject == null
                    ? 0
                    : AllflameContext.StashObject.Id,
                "PreVoyage Chart Stash");
            if (_lastAreaHash != AllflameContext.AreaHash)
            {
                _lastAreaHash = AllflameContext.AreaHash;
                _stashOpenAttempts = 0;
                _tabAttempts = 0;
                _failedChartKey = 0;
                _failedAttempts = 0;
                ResetStorageState();
            }

            if (AllflameProgressWatchdog.TryConsumeRecovery(
                    "CloseAndReloadStashUi"))
            {
                await Coroutines.CloseBlockingWindows();
                try
                {
                    ExilePather.Reload(true);
                }
                catch
                {
                }
                AllflameContext.RequestRefresh(
                    "PreVoyageStashRecovery");
                AllflameProgressWatchdog.MarkProgress(
                    "ReacquirePreVoyageStash");
                _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(800);
                return true;
            }

            if (DateTime.UtcNow < _retryAfterUtc)
            {
                return true;
            }

            if (AllflameContext.PlanVoyageVisible)
            {
                await Coroutines.CloseBlockingWindows();
                AllflameProgressWatchdog.MarkProgress(
                    "ClosePlanningUi");
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(350);
                return true;
            }

            if (LokiPoe.InGameState.GuildStashUi.IsOpened)
            {
                await Coroutines.CloseBlockingWindows();
                AllflameProgressWatchdog.MarkProgress(
                    "CloseGuildStashUi");
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(350);
                return true;
            }

            List<Item> charts = GetInventoryCharts();
            if (charts.Count == 0)
            {
                return await CompletePreStash(0, "AllChartsStored");
            }

            if (!_storageUnavailable)
            {
                if (await HandleChartStorageDeposit(charts))
                {
                    return true;
                }
            }

            string configured =
                (settings.VoyageStashTab ?? String.Empty).Trim();
            if (String.IsNullOrEmpty(configured))
            {
                AllflameLog.Info(
                    "VOYAGE_CHART_STASH_SKIPPED" +
                    "|Reason=NoPersonalFallbackConfigured" +
                    "|StorageResult=" +
                    (_storageUnavailable
                        ? "Unavailable"
                        : "Complete") +
                    "|StorageReason=" + _storageFailureReason +
                    "|ChartsKeptInInventory=" + charts.Count +
                    "|NextAction=ContinueVoyage");
                return await CompletePreStash(
                    charts.Count,
                    "NoPersonalFallbackConfigured");
            }

            if (!LokiPoe.InGameState.StashUi.IsOpened)
            {
                NetworkObject stash = AllflameContext.StashObject;
                if (stash == null || !stash.IsValid)
                {
                    _stashOpenAttempts++;
                    AllflameProgressWatchdog.SetRetry(
                        _stashOpenAttempts);
                    AllflameLog.Info(
                        "VOYAGE_PRE_STASH_RETRY|Stage=Open" +
                        "|Attempt=" + _stashOpenAttempts +
                        "|Reason=PersonalStashMissing" +
                        "|NextAction=ReacquireStash");
                    if (_stashOpenAttempts >= 3)
                    {
                        return await SkipPersonalFallback(
                            "StashObjectMissing",
                            String.Empty,
                            String.Empty);
                    }
                    _retryAfterUtc =
                        DateTime.UtcNow.AddSeconds(1);
                    return true;
                }

                if (stash.Distance > settings.InteractDistance)
                {
                    await MoveOrInteract(stash, "Pre-Voyage Chart Stash");
                    return true;
                }

                bool opened = false;
                try
                {
                    opened = await InteractWithRecovery(stash);
                }
                catch (Exception ex)
                {
                    AllflameLog.Info(
                        "VOYAGE_PRE_STASH_OPEN_EXCEPTION|Type=" +
                        ex.GetType().Name +
                        "|Message=" +
                        (ex.Message ?? String.Empty).Replace("|", "/"));
                }
                if (opened)
                {
                    _stashOpenAttempts = 0;
                    AllflameProgressWatchdog.MarkProgress(
                        "StashUiOpened");
                }
                else
                {
                    _stashOpenAttempts++;
                    AllflameProgressWatchdog.SetRetry(
                        _stashOpenAttempts);
                    if (_stashOpenAttempts >= 2)
                    {
                        try
                        {
                            ExilePather.Reload(true);
                        }
                        catch
                        {
                        }
                    }
                }
                _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(
                    opened ? 700 : 500);
                AllflameLog.Info(
                    "VOYAGE_PRE_STASH_OPEN|Success=" + opened +
                    "|Object=" + stash.Name +
                    "|Attempt=" +
                    (_stashOpenAttempts == 0
                        ? 1
                        : _stashOpenAttempts));
                if (!opened && _stashOpenAttempts >= 3)
                {
                    return await SkipPersonalFallback(
                        "StashOpenFailed",
                        String.Empty,
                        String.Empty);
                }
                return true;
            }

            string targetTab = ResolveStashTabName(configured);
            if (String.IsNullOrEmpty(targetTab))
            {
                AllflameLog.Info(
                    "VOYAGE_CHART_STASH_SKIPPED" +
                    "|Reason=PersonalFallbackTabMissing" +
                    "|Configured=" + configured +
                    "|StorageReason=" + _storageFailureReason +
                    "|ChartsKeptInInventory=" + charts.Count +
                    "|NextAction=ContinueVoyage");
                return await CompletePreStash(
                    charts.Count,
                    "PersonalFallbackTabMissing");
            }

            string currentTab =
                LokiPoe.InGameState.StashUi.TabControl
                    .CurrentTabName;
            if (!String.Equals(
                    currentTab,
                    targetTab,
                    StringComparison.OrdinalIgnoreCase))
            {
                var result =
                    LokiPoe.InGameState.StashUi.TabControl
                        .SwitchToTabMouse(targetTab);
                if (Convert.ToInt32(result) != 0)
                {
                    result =
                        LokiPoe.InGameState.StashUi.TabControl
                            .SwitchToTabKeyboard(targetTab);
                }
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(650);
                bool tabAccepted = Convert.ToInt32(result) == 0;
                if (tabAccepted)
                {
                    _tabAttempts = 0;
                    AllflameProgressWatchdog.MarkProgress(
                        "SwitchToVoyageStashTab");
                }
                else
                {
                    _tabAttempts++;
                    AllflameProgressWatchdog.SetRetry(_tabAttempts);
                }
                AllflameLog.Info(
                    "VOYAGE_PRE_STASH_TAB|Configured=" +
                    configured +
                    "|Resolved=" + targetTab +
                    "|Result=" + result +
                    "|Accepted=" + tabAccepted +
                    "|Attempt=" + _tabAttempts);
                if (!tabAccepted && _tabAttempts >= 3)
                {
                    return await SkipPersonalFallback(
                        "TabSwitchFailed",
                        targetTab,
                        String.Empty);
                }
                return true;
            }

            _tabAttempts = 0;

            Item chart = charts[0];
            int chartKey =
                chart.LocalId != 0 ? chart.LocalId : chart.Id;
            int beforeCount = charts.Count;
            int transferDelay =
                AllflameTransferTiming.NextDelayMilliseconds(
                    settings);
            bool inputSent =
                await CtrlClickInventoryChart(
                    chart,
                    true,
                    "VOYAGE_PRE_STASH_CHART_INPUT_FAILED");
            await LokiCoroutine.Sleep(80);
            AllflameContext.Refresh(true);
            int afterCount = GetInventoryCharts().Count;
            bool moved = inputSent && afterCount < beforeCount;

            if (moved)
            {
                _failedChartKey = 0;
                _failedAttempts = 0;
                _movedCharts++;
                AllflameProgressWatchdog.MarkProgress(
                    "ChartTransferConfirmed");
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(
                        transferDelay);
                AllflameLog.Info(
                    "VOYAGE_PRE_STASH_CHART_MOVED|Tab=" +
                    targetTab +
                    "|Name=" + chart.FullName +
                    "|LocalId=" + chart.LocalId +
                    "|Before=" + beforeCount +
                    "|After=" + afterCount +
                    "|Mode=CtrlShiftLeftClick" +
                    "|NextDelayMs=" + transferDelay);
                return true;
            }

            if (_failedChartKey == chartKey)
            {
                _failedAttempts++;
            }
            else
            {
                _failedChartKey = chartKey;
                _failedAttempts = 1;
            }
            AllflameLog.Info(
                "VOYAGE_PRE_STASH_CHART_RETRY|Tab=" +
                targetTab +
                "|Name=" + chart.FullName +
                "|LocalId=" + chart.LocalId +
                "|Attempt=" + _failedAttempts +
                "|InputSent=" + inputSent +
                "|InventoryCharts=" + afterCount +
                "|UiOpen=" + LokiPoe.InGameState.StashUi.IsOpened +
                "|CurrentTab=" + currentTab +
                "|ExpectedTab=" + targetTab);
            AllflameProgressWatchdog.SetRetry(_failedAttempts);
            if (_failedAttempts == 2)
            {
                await Coroutines.CloseBlockingWindows();
                try
                {
                    ExilePather.Reload(true);
                }
                catch
                {
                }
                AllflameContext.Refresh(true);
                AllflameLog.Info(
                    "VOYAGE_PRE_STASH_RECOVERY|Action=ReloadPath" +
                    "|Tab=" + targetTab +
                    "|Item=" + chart.FullName);
            }
            if (_failedAttempts >= 3)
            {
                return await SkipPersonalFallback(
                    "ChartTransferFailed",
                    targetTab,
                    chart.FullName);
            }

            _retryAfterUtc =
                DateTime.UtcNow.AddMilliseconds(250);
            return true;
        }

        private async Task<bool> SkipPersonalFallback(
            string reason,
            string tab,
            string item)
        {
            int inventoryCharts = GetInventoryCharts().Count;
            AllflameLog.Info(
                "VOYAGE_CHART_STASH_FALLBACK" +
                "|Result=Skipped" +
                "|Reason=" + reason +
                "|Tab=" + (tab ?? String.Empty) +
                "|Item=" + (item ?? String.Empty) +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|Attempts=" + Math.Max(_failedAttempts, _stashOpenAttempts) +
                "|InventoryCharts=" + inventoryCharts +
                "|StorageReason=" + _storageFailureReason +
                "|NextAction=ContinueVoyage");
            return await CompletePreStash(
                inventoryCharts,
                reason);
        }

        private async Task<bool> HandleChartStorageDeposit(
            IList<Item> charts)
        {
            if (_storageStartedUtc == DateTime.MinValue)
            {
                _storageStartedUtc = DateTime.UtcNow;
            }
            if (!_storageStartLogged)
            {
                _storageStartLogged = true;
                AllflameLog.Info(
                    "CHART_STORAGE_DEPOSIT_START" +
                    "|Charts=" + charts.Count +
                    "|Player=" + LokiPoe.MyPosition +
                    "|AreaHash=" + AllflameContext.AreaHash +
                    "|PersonalFallback=" +
                    ((AllflameSettings.Instance.VoyageStashTab ??
                        String.Empty).Trim()));
            }

            if (DateTime.UtcNow - _storageStartedUtc >=
                StorageDepositTimeout)
            {
                await MarkStorageUnavailable(
                    "Timeout",
                    charts.Count);
                return true;
            }

            if (LokiPoe.InGameState.StashUi.IsOpened ||
                LokiPoe.InGameState.GuildStashUi.IsOpened)
            {
                await Coroutines.CloseBlockingWindows();
                _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(350);
                return true;
            }

            if (_storageDepositPending)
            {
                int afterCount = GetInventoryCharts().Count;
                int afterUnits = CountInventoryChartUnits();
                bool moved = afterUnits < _storagePendingBeforeUnits;
                if (moved)
                {
                    _storageStartedUtc = DateTime.UtcNow;
                    _storageMovedCharts += Math.Max(
                        1,
                        _storagePendingBeforeUnits - afterUnits);
                    _failedChartKey = 0;
                    _failedAttempts = 0;
                    AllflameProgressWatchdog.MarkProgress(
                        "ChartStorageDepositConfirmed");
                    ChartStorageUi.MarkDepositConfirmed();
                    AllflameLog.Info(
                        "CHART_STORAGE_FAST_DEPOSIT_CONFIRMED" +
                        "|Main=" + (_storageMainTab + 1) +
                        "|Sub=" + (_storageSubTab + 1) +
                        "|Name=" + _storagePendingChartName +
                        "|LocalId=" + _storagePendingChartKey +
                        "|Before=" + _storagePendingBeforeCount +
                        "|After=" + afterCount +
                        "|BeforeUnits=" + _storagePendingBeforeUnits +
                        "|AfterUnits=" + afterUnits +
                        "|ElapsedMs=" + Math.Max(
                            0,
                            (int)(DateTime.UtcNow -
                                _storageDepositIssuedUtc)
                                .TotalMilliseconds) +
                        "|PageReselected=False" +
                        "|OneActionPerCycle=True");
                    ClearPendingStorageDeposit();
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(25);
                    return true;
                }

                if (DateTime.UtcNow - _storageDepositIssuedUtc <
                    TimeSpan.FromMilliseconds(650))
                {
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(40);
                    return true;
                }

                int rejectedChartKey = _storagePendingChartKey;
                string rejectedChartName = _storagePendingChartName;
                int rejectedBeforeUnits = _storagePendingBeforeUnits;
                ClearPendingStorageDeposit();
                if (_failedChartKey == rejectedChartKey)
                {
                    _failedAttempts++;
                }
                else
                {
                    _failedChartKey = rejectedChartKey;
                    _failedAttempts = 1;
                }
                AllflameLog.Info(
                    "CHART_STORAGE_DEPOSIT_PAGE_REJECTED" +
                    "|Main=" + (_storageMainTab + 1) +
                    "|Sub=" + (_storageSubTab + 1) +
                    "|Name=" + rejectedChartName +
                    "|InputSent=True" +
                    "|BeforeUnits=" + rejectedBeforeUnits +
                    "|AfterUnits=" + afterUnits +
                    "|Reason=TransferNotConfirmed" +
                    "|Confirmation=" + _failedAttempts + "/2" +
                    "|NextAction=" + (_failedAttempts >= 2
                        ? "TryNextPage"
                        : "RetrySamePage"));
                if (_failedAttempts < 2)
                {
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(80);
                    return true;
                }
                int rejectedMain = _storageMainTab;
                int rejectedSub = _storageSubTab;
                if (!AdvanceStoragePage())
                {
                    await MarkStorageUnavailable(
                        "AllPagesRejected",
                        afterCount);
                    return true;
                }
                AllflameLog.Info(
                    "CHART_STORAGE_FAST_DEPOSIT_PAGE_FULL" +
                    "|Main=" + (rejectedMain + 1) +
                    "|Sub=" + (rejectedSub + 1) +
                    "|Confirmations=" + _failedAttempts +
                    "|Action=AdvancePage");
                _failedChartKey = 0;
                _failedAttempts = 0;
                _storagePageReady = false;
                _storageControl = null;
                _storageSlot = null;
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(80);
                return true;
            }

            if (_storagePageReady)
            {
                Item chart = charts[0];
                int chartKey =
                    chart.LocalId != 0 ? chart.LocalId : chart.Id;
                int beforeCount = charts.Count;
                int beforeUnits = CountInventoryChartUnits();
                bool inputSent = await CtrlClickInventoryChart(
                    chart,
                    false,
                    "CHART_STORAGE_DEPOSIT_INPUT_FAILED");
                AllflameLog.Info(
                    "CHART_STORAGE_FAST_DEPOSIT_ISSUED" +
                    "|Main=" + (_storageMainTab + 1) +
                    "|Sub=" + (_storageSubTab + 1) +
                    "|Name=" + chart.FullName +
                    "|LocalId=" + chartKey +
                    "|BeforeUnits=" + beforeUnits +
                    "|Ctrl=True" +
                    "|InputSent=" + inputSent +
                    "|OneActionPerCycle=True");
                if (inputSent)
                {
                    _storageDepositPending = true;
                    _storagePendingChartKey = chartKey;
                    _storagePendingBeforeCount = beforeCount;
                    _storagePendingBeforeUnits = beforeUnits;
                    _storagePendingChartName = chart.FullName ?? String.Empty;
                    _storageDepositIssuedUtc = DateTime.UtcNow;
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(35);
                    return true;
                }

                if (_failedChartKey == chartKey)
                {
                    _failedAttempts++;
                }
                else
                {
                    _failedChartKey = chartKey;
                    _failedAttempts = 1;
                }
                if (_failedAttempts >= 2)
                {
                    if (!AdvanceStoragePage())
                    {
                        await MarkStorageUnavailable(
                            "AllPagesRejected",
                            beforeCount);
                        return true;
                    }
                    _failedChartKey = 0;
                    _failedAttempts = 0;
                    _storagePageReady = false;
                }
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(80);
                return true;
            }

            InventoryControlWrapper resolvedControl;
            InventorySlotUiElement resolvedSlot;
            if (ChartStorageUi.TryResolve(
                    _storageControl,
                    _storageSlot,
                    out resolvedControl,
                    out resolvedSlot))
            {
                _storageControl = resolvedControl;
                _storageSlot = resolvedSlot;
                _storageOpenPending = false;
                _storageOpenAttempts = 0;
                _storageResolveAttempts = 0;
                bool pageReady = ChartStorageUi.IsPageActive(
                    _storageMainTab,
                    _storageSubTab);
                if (pageReady)
                {
                    _storagePageReady = true;
                    _storageControl = null;
                    _storageSlot = null;
                    AllflameLog.Info(
                        "CHART_STORAGE_FAST_DEPOSIT_START" +
                        "|Main=" + (_storageMainTab + 1) +
                        "|Sub=" + (_storageSubTab + 1) +
                        "|InventoryCharts=" + charts.Count +
                        "|TabClicks=0" +
                        "|Action=CtrlClickInventoryDirectly");
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(20);
                    return true;
                }
                bool mainReady = ChartStorageUi.IsMainTabActive(
                    _storageMainTab);
                bool mainClicked = false;
                bool subClicked = false;
                string action;
                if (!mainReady)
                {
                    mainClicked =
                        ChartStorageUi.TryClickMainTab(_storageMainTab);
                    action = "SelectMain";
                }
                else
                {
                    subClicked = ChartStorageUi.TryClickSubTab(
                        _storageMainTab,
                        _storageSubTab);
                    action = "SelectSub";
                }
                AllflameLog.Info(
                    "CHART_STORAGE_DEPOSIT_PAGE" +
                    "|Main=" + (_storageMainTab + 1) +
                    "|Sub=" + (_storageSubTab + 1) +
                    "|MainReady=" + mainReady +
                    "|MainClicked=" + mainClicked +
                    "|SubClicked=" + subClicked +
                    "|Action=" + action +
                    "|OneActionPerCycle=True");
                _storageControl = null;
                _storageSlot = null;
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(120);
                return true;
            }

            if (_storageOpenPending)
            {
                _storageResolveAttempts++;
                AllflameLog.Info(
                    "CHART_STORAGE_DEPOSIT_RETRY" +
                    "|Stage=ResolveUi" +
                    "|Attempt=" + _storageResolveAttempts +
                    "|Maximum=" + MaximumStorageResolveAttempts);
                if (_storageResolveAttempts >=
                    MaximumStorageResolveAttempts)
                {
                    await MarkStorageUnavailable(
                        "PageLayerNotResolved",
                        charts.Count);
                    return true;
                }
                _retryAfterUtc = DateTime.UtcNow.AddSeconds(1);
                return true;
            }

            NetworkObject storage = AllflameContext.ChartStorageObject;
            if (storage == null || !storage.IsValid)
            {
                _storageOpenAttempts++;
                AllflameContext.Refresh(true);
                AllflameLog.Info(
                    "CHART_STORAGE_DEPOSIT_RETRY" +
                    "|Stage=Open" +
                    "|Attempt=" + _storageOpenAttempts +
                    "|Maximum=" + MaximumStorageOpenAttempts +
                    "|Reason=StorageObjectMissing");
                if (_storageOpenAttempts >= MaximumStorageOpenAttempts)
                {
                    await MarkStorageUnavailable(
                        "StorageObjectMissing",
                        charts.Count);
                    return true;
                }
                _retryAfterUtc = DateTime.UtcNow.AddSeconds(1);
                return true;
            }

            if (storage.Distance > AllflameSettings.Instance.InteractDistance)
            {
                await MoveOrInteract(storage, "Chart Storage Deposit");
                return true;
            }

            bool interacted = false;
            try
            {
                interacted = await InteractWithRecovery(storage);
            }
            catch (Exception exception)
            {
                AllflameLog.Info(
                    "CHART_STORAGE_DEPOSIT_OPEN_EXCEPTION" +
                    "|Type=" + exception.GetType().Name +
                    "|Message=" +
                    (exception.Message ?? String.Empty).Replace("|", "/"));
            }
            _storageOpenAttempts++;
            _storageOpenPending = interacted;
            AllflameLog.Info(
                "CHART_STORAGE_DEPOSIT_OPEN" +
                "|Success=" + interacted +
                "|Attempt=" + _storageOpenAttempts +
                "|Maximum=" + MaximumStorageOpenAttempts);
            if (!interacted &&
                _storageOpenAttempts >= MaximumStorageOpenAttempts)
            {
                await MarkStorageUnavailable(
                    "StorageInteractionRejected",
                    charts.Count);
                return true;
            }
            _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(
                interacted ? 1000 : 600);
            return true;
        }

        private bool AdvanceStoragePage()
        {
            _storagePageReady = false;
            _storageSubTab++;
            if (_storageSubTab >= StorageSubTabCount)
            {
                _storageSubTab = 0;
                _storageMainTab++;
            }
            return _storageMainTab < StorageMainTabCount;
        }

        private async Task MarkStorageUnavailable(
            string reason,
            int inventoryCharts)
        {
            _storageUnavailable = true;
            _storageFailureReason = reason ?? String.Empty;
            AllflameLog.Info(
                "CHART_STORAGE_DEPOSIT_UNAVAILABLE" +
                "|Reason=" + _storageFailureReason +
                "|Moved=" + _storageMovedCharts +
                "|InventoryCharts=" + inventoryCharts +
                "|ElapsedMilliseconds=" +
                Math.Max(
                    0,
                    (long)(DateTime.UtcNow - _storageStartedUtc)
                        .TotalMilliseconds) +
                "|NextAction=" +
                (String.IsNullOrWhiteSpace(
                    AllflameSettings.Instance.VoyageStashTab)
                    ? "ContinueVoyage"
                    : "PersonalStashFallback"));
            await Coroutines.CloseBlockingWindows();
            _storageControl = null;
            _storageSlot = null;
            _storageOpenPending = false;
            _storagePageReady = false;
            ClearPendingStorageDeposit();
            _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(350);
        }

        private void ClearPendingStorageDeposit()
        {
            _storageDepositPending = false;
            _storagePendingChartKey = 0;
            _storagePendingBeforeCount = 0;
            _storagePendingBeforeUnits = 0;
            _storagePendingChartName = String.Empty;
            _storageDepositIssuedUtc = DateTime.MinValue;
        }

        private async Task<bool> CompletePreStash(
            int chartsKeptInInventory,
            string reason)
        {
            AllflameSettings settings = AllflameSettings.Instance;
            settings.LastChartStorageTotal = Math.Max(
                0,
                settings.LastChartStorageTotal + _storageMovedCharts);
            settings.LastVoyageStashTotal = Math.Max(
                0,
                settings.LastVoyageStashTotal + _movedCharts);
            settings.LastChartStorageScan =
                "ChartStorageDeposit=" + _storageMovedCharts +
                ";VoyageStash:" +
                (settings.VoyageStashTab ?? String.Empty) +
                "=" + settings.LastVoyageStashTotal;
            settings.Save();
            string destination = _storageMovedCharts > 0
                ? (_movedCharts > 0
                    ? "ChartStorage+PersonalStash"
                    : "ChartStorage")
                : (_movedCharts > 0
                    ? "PersonalStash"
                    : "Inventory");
            AllflameLog.Info(
                "CHART_STORAGE_DEPOSIT_COMPLETE" +
                "|Moved=" + _storageMovedCharts +
                "|FallbackMoved=" + _movedCharts +
                "|ChartsKeptInInventory=" + chartsKeptInInventory +
                "|Reason=" + reason +
                "|Destination=" + destination);
            AllflameLog.Info(
                "VOYAGE_PRE_STASH|Stage=Chart|State=Complete" +
                "|StorageMoved=" + _storageMovedCharts +
                "|FallbackMoved=" + _movedCharts +
                "|ChartsKeptInInventory=" + chartsKeptInInventory +
                "|Destination=" + destination +
                "|Action=ProceedToBeginVoyage");
            AllflameRunState.MarkVoyagePreStashCompleted();
            AllflameProgressWatchdog.MarkProgress(
                "ProceedToBeginVoyage");
            await Coroutines.CloseBlockingWindows();
            ResetLocalState();
            AllflameProgressWatchdog.Clear();
            return true;
        }

        private async Task<bool> CompletePreStashWithoutChartTransfer(
            int chartsRetained)
        {
            AllflameLog.Info(
                "CHART_STORAGE_DEPOSIT_SKIPPED" +
                "|Reason=ChartsRetainedInInventory" +
                "|ChartsRetained=" + chartsRetained +
                "|NextAction=ProceedToBeginVoyage");
            AllflameLog.Info(
                "VOYAGE_PRE_STASH|Stage=Chart|State=Skipped" +
                "|NonChartItems=0" +
                "|ChartsRetainedInInventory=" + chartsRetained +
                "|Reason=ChartsRetainedInInventory" +
                "|Action=ProceedToBeginVoyage");
            AllflameRunState.MarkVoyagePreStashCompleted();
            AllflameProgressWatchdog.MarkProgress(
                "ProceedToBeginVoyageWithChartsRetained");
            await Coroutines.CloseBlockingWindows();
            ResetLocalState();
            AllflameProgressWatchdog.Clear();
            return true;
        }

        private static bool ShouldTransferChartsBeforeVoyage()
        {
            // Chart transfer is intentionally disabled. Charts remain in the
            // inventory; this seam keeps the legacy recovery code isolated.
            return false;
        }

        private static List<Item> GetInventoryCharts()
        {
            try
            {
                InventoryControlWrapper control =
                    LokiPoe.InGameState.InventoryUi
                        .InventoryControl_Main;
                return control == null ||
                    control.Inventory == null ||
                    control.Inventory.Items == null
                        ? new List<Item>()
                        : control.Inventory.Items
                            .Where(item =>
                                item != null &&
                                item.IsValid &&
                                AllflameContext.IsChartItem(item))
                            .ToList();
            }
            catch
            {
                return new List<Item>();
            }
        }

        private static int CountInventoryChartUnits()
        {
            return GetInventoryCharts().Sum(item =>
                Math.Max(1, item.StackCount));
        }

        private static int CountNonChartInventoryItems()
        {
            try
            {
                InventoryControlWrapper control =
                    LokiPoe.InGameState.InventoryUi
                        .InventoryControl_Main;
                return control == null ||
                    control.Inventory == null ||
                    control.Inventory.Items == null
                        ? 0
                        : control.Inventory.Items.Count(item =>
                            item != null &&
                            item.IsValid &&
                            !AllflameContext.IsChartItem(item) &&
                            !SecretBottleProcessingTask.ShouldReserveBottle(item));
            }
            catch
            {
                return 0;
            }
        }

        private static string ResolveStashTabName(
            string configured)
        {
            List<string> names =
                LokiPoe.InGameState.StashUi.TabControl.TabNames;
            if (names == null || names.Count == 0)
            {
                return String.Empty;
            }

            string exact = names.FirstOrDefault(name =>
                String.Equals(
                    name,
                    configured,
                    StringComparison.OrdinalIgnoreCase));
            if (!String.IsNullOrEmpty(exact))
            {
                return exact;
            }

            int number;
            return Int32.TryParse(configured, out number) &&
                number >= 1 &&
                number <= names.Count
                    ? names[number - 1]
                    : String.Empty;
        }

        private static async Task<bool> CtrlClickInventoryChart(
            Item chart,
            bool useShift,
            string failureMarker)
        {
            try
            {
                InventoryControlWrapper control =
                    LokiPoe.InGameState.InventoryUi
                        .InventoryControl_Main;
                if (control == null || chart == null)
                {
                    return false;
                }

                var slotUi = control.InventorySlotUiElement;
                if (slotUi == null)
                {
                    return false;
                }

                Element itemElement = null;
                try
                {
                    var elements = slotUi.DictionaryIdElements;
                    if (elements != null &&
                        !elements.TryGetValue(
                            chart.LocalId,
                            out itemElement))
                    {
                        elements.TryGetValue(
                            chart.Id,
                            out itemElement);
                    }
                }
                catch
                {
                    itemElement = null;
                }

                Vector2i clickLocation =
                    itemElement != null &&
                    itemElement.IsValid &&
                    itemElement.IsVisible
                        ? itemElement.CenterClickLocation()
                        : slotUi.SlotClickLocation(
                            new Vector2i(
                                chart.LocationTopLeft.X + 1,
                                chart.LocationTopLeft.Y + 1));
                bool controlDown = false;
                bool shiftDown = false;
                try
                {
                    LokiPoe.ProcessHookManager
                        .ClearAllKeyStates();
                    DreamPoeBot.BotFramework.MouseManager
                        .SetMousePosition(clickLocation, true);
                    await LokiCoroutine.Sleep(5);
                    LokiPoe.ProcessHookManager.SetKeyState(
                        System.Windows.Forms.Keys.ControlKey,
                        short.MinValue,
                        System.Windows.Forms.Keys.None);
                    controlDown = true;
                    if (useShift)
                    {
                        LokiPoe.ProcessHookManager.SetKeyState(
                            System.Windows.Forms.Keys.ShiftKey,
                            short.MinValue,
                            System.Windows.Forms.Keys.None);
                        shiftDown = true;
                    }
                    await LokiCoroutine.Sleep(5);
                    DreamPoeBot.BotFramework.MouseManager
                        .ClickLMB(0, 0);
                    return true;
                }
                finally
                {
                    if (shiftDown)
                    {
                        LokiPoe.ProcessHookManager.SetKeyState(
                            System.Windows.Forms.Keys.ShiftKey,
                            (short)0,
                            System.Windows.Forms.Keys.None);
                    }
                    if (controlDown)
                    {
                        LokiPoe.ProcessHookManager.SetKeyState(
                            System.Windows.Forms.Keys.ControlKey,
                            (short)0,
                            System.Windows.Forms.Keys.None);
                    }
                }
            }
            catch (Exception exception)
            {
                AllflameLog.Info(
                    (failureMarker ??
                        "VOYAGE_PRE_STASH_CHART_INPUT_FAILED") +
                    "|Name=" +
                    (chart == null
                        ? "Unknown"
                        : chart.FullName) +
                    "|Error=" +
                    exception.GetType().Name +
                    "|Message=" +
                    exception.Message.Replace("|", "/"));
                return false;
            }
        }

        private void ResetLocalState()
        {
            _retryAfterUtc = DateTime.MinValue;
            _failedChartKey = 0;
            _failedAttempts = 0;
            _movedCharts = 0;
            _storageMovedCharts = 0;
            _stashOpenAttempts = 0;
            _tabAttempts = 0;
            ResetStorageState();
            _lastAreaHash = 0;
        }

        private void ResetStorageState()
        {
            _storageStartedUtc = DateTime.MinValue;
            _storageOpenAttempts = 0;
            _storageResolveAttempts = 0;
            _storageMainTab = 0;
            _storageSubTab = 0;
            _storageFailureReason = String.Empty;
            _storageUnavailable = false;
            _storageStartLogged = false;
            _storageOpenPending = false;
            _storageControl = null;
            _storageSlot = null;
            _storagePageReady = false;
            ClearPendingStorageDeposit();
        }
    }

    internal sealed class EnterStartedVoyageTask : ObserverTask
    {
        private DateTime _startedUtc = DateTime.MinValue;
        private DateTime _nextInteractUtc = DateTime.MinValue;
        private int _attempts;

        public EnterStartedVoyageTask()
            : base(
                "EnterStartedVoyageTask",
                "Finds and enters the Bathysphere after Begin Voyage.") { }

        public override async Task<bool> Run()
        {
            if (!AllflameRunState.VoyageStarted)
            {
                _startedUtc = DateTime.MinValue;
                _nextInteractUtc = DateTime.MinValue;
                _attempts = 0;
                return false;
            }

            if (AllflameContext.Phase == AllflamePhase.Voyage ||
                AllflameContext.Phase == AllflamePhase.WaitingForBathysphere)
            {
                return false;
            }

            bool inHub =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            if (!inHub)
            {
                return true;
            }

            if (AllflameSettings.Instance.StashBeforeVoyage &&
                !AllflameRunState.VoyagePreStashCompleted)
            {
                AllflameLog.Throttled(
                    "voyage_wait_pre_stash",
                    TimeSpan.FromSeconds(2),
                    "VOYAGE_STAGE|Stage=0|State=WaitingForPreVoyageStash" +
                    "|InventoryItems=" +
                    AllflameContext.InventoryItemCount +
                    "|InventoryCharts=" +
                    AllflameContext.InventoryChartCount);
                return true;
            }

            if (_startedUtc == DateTime.MinValue)
            {
                _startedUtc = DateTime.UtcNow;
                AllflameLog.Info(
                    "VOYAGE_STAGE|Stage=1|State=FindBathysphere");
            }

            if (AllflameContext.PlanVoyageVisible)
            {
                await Coroutines.CloseBlockingWindows();
                await LokiCoroutine.Sleep(250);
                return true;
            }

            NetworkObject bathysphere =
                AllflameContext.BathysphereObject;
            if (bathysphere == null ||
                !bathysphere.IsValid ||
                !bathysphere.IsTargetable)
            {
                AllflameLog.Throttled(
                    "voyage_bathysphere_missing",
                    TimeSpan.FromSeconds(2),
                    "VOYAGE_STAGE|Stage=1|State=Waiting" +
                    "|Bathysphere=False" +
                    "|ElapsedMs=" +
                    (int)(DateTime.UtcNow - _startedUtc)
                        .TotalMilliseconds);
                return true;
            }

            // The object's origin hangs outside the walkable deck. The
            // closest navmesh point is normally 30-35 units away.
            const float voyageBathysphereInteractRange = 70f;
            if (bathysphere.Distance >
                voyageBathysphereInteractRange)
            {
                bool moving = AllflameMovementCoordinator.MoveTowards(
                    bathysphere.Position,
                    Name);
                AllflameLog.Throttled(
                    "voyage_bathysphere_approach",
                    TimeSpan.FromSeconds(1),
                    "VOYAGE_STAGE|Stage=1|State=Approach" +
                    "|Distance=" +
                    bathysphere.Distance.ToString("0.0") +
                    "|InteractRange=" +
                    voyageBathysphereInteractRange.ToString("0.0") +
                    "|Moving=" + moving);
                return true;
            }

            if (DateTime.UtcNow < _nextInteractUtc)
            {
                return true;
            }

            _nextInteractUtc = DateTime.UtcNow.AddMilliseconds(850);
            _attempts++;
            await FinishMovementBeforeInteraction(
                "Voyage Bathysphere");
            bool entered = await InteractWithRecovery(bathysphere);
            AllflameLog.Info(
                "VOYAGE_STAGE|Stage=1|State=Interact" +
                "|Attempt=" + _attempts +
                "|Success=" + entered +
                "|ObjectId=" + bathysphere.Id +
                "|Distance=" +
                bathysphere.Distance.ToString("0.0") +
                "|Runner=Voyage");
            if (!entered)
            {
                AllflameMovementCoordinator.MoveTowards(
                    bathysphere.Position,
                    Name + " interaction recovery");
            }
            await LokiCoroutine.Sleep(350);
            return true;
        }
    }

    internal sealed class PrepareVoyageTask : ObserverTask
    {
        private const float ValerieInteractionRange = 50f;
        private int _stage;
        private DateTime _retryAfterUtc = DateTime.MinValue;
        private DateTime _voyageUiExpectedUntilUtc = DateTime.MinValue;
        private DateTime _valerieEffectDeadlineUtc = DateTime.MinValue;
        private int _valerieEffectFailures;
        private bool _manualReady;
        private bool _planningReadyAtOpen;
        private int _chartDetectionAttempts;
        private int _lastInsufficientChartCount = -1;
        private int _stableInsufficientChartSnapshots;
        private bool _stablePlacementActive;
        private bool _stablePlacementAwaitingVerification;
        private int _stablePlacementBaselineAvailable;
        private int _stablePlacementBeforeAvailable;
        private int _stablePlacementBeforeBoard;
        private int _stablePlacementConfirmed;
        private int _stablePlacementFailures;
        private DateTime _stablePlacementIssuedUtc = DateTime.MinValue;
        private int _nativePlannerShadowMatches;
        private bool _nativeClearPending;
        private bool _nativeClearFallbackUsed;
        private DateTime _nativeClearIssuedUtc = DateTime.MinValue;
        private bool _nativeBeginPending;
        private bool _nativeBeginFallbackUsed;
        private DateTime _nativeBeginIssuedUtc = DateTime.MinValue;
        private bool _plannerOpenTargetOverrideActive;

        private static readonly TimeSpan NativePlannerConfirmationTimeout =
            TimeSpan.FromSeconds(4);
        private const int MaximumVoyagePlannerCloseAttempts = 3;
        private static readonly TimeSpan VoyagePlannerCloseVerificationDelay =
            TimeSpan.FromMilliseconds(180);

        public PrepareVoyageTask()
            : base(
                "PrepareVoyageTask",
                "Counts completed Charts, fills the Voyage board and starts a Voyage.") { }

        public override void Start()
        {
            ResetValerieApproachRecovery(0, "Start");
            ResetStablePlacement();
            _stage = 0;
            _retryAfterUtc = DateTime.MinValue;
            _voyageUiExpectedUntilUtc = DateTime.MinValue;
            _valerieEffectDeadlineUtc = DateTime.MinValue;
            _valerieEffectFailures = 0;
            _manualReady = false;
            _planningReadyAtOpen = false;
            _chartDetectionAttempts = 0;
            _lastInsufficientChartCount = -1;
            _stableInsufficientChartSnapshots = 0;
            _nativePlannerShadowMatches = 0;
            _plannerOpenTargetOverrideActive = false;
            ResetNativePlannerActionState();
        }

        public override void Stop()
        {
            ResetValerieApproachRecovery(0, "Stop");
            ResetStablePlacement();
            _stage = 0;
            _retryAfterUtc = DateTime.MinValue;
            _voyageUiExpectedUntilUtc = DateTime.MinValue;
            _valerieEffectDeadlineUtc = DateTime.MinValue;
            _valerieEffectFailures = 0;
            _manualReady = false;
            _planningReadyAtOpen = false;
            _chartDetectionAttempts = 0;
            _lastInsufficientChartCount = -1;
            _stableInsufficientChartSnapshots = 0;
            _nativePlannerShadowMatches = 0;
            _plannerOpenTargetOverrideActive = false;
            ResetNativePlannerActionState();
        }

        public override async Task<bool> Run()
        {
            if (_nativeBeginPending)
            {
                if (AllflameContext.IsVoyageMapArea)
                {
                    _nativeBeginPending = false;
                    AllflameRunState.MarkVoyageStarted();
                    ResetStablePlacement();
                    _stage = 0;
                    _planningReadyAtOpen = false;
                    _plannerOpenTargetOverrideActive = false;
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(500);
                    AllflameProgressWatchdog.MarkProgress(
                        "NativeVoyageStarted");
                    AllflameLog.Info(
                        "VOYAGE_BEGIN_POSTCONDITION" +
                        "|Mode=Native" +
                        "|Postcondition=True" +
                        "|AreaId=" + AllflameContext.AreaId +
                        "|AreaHash=" + AllflameContext.AreaHash +
                        "|Action=StartVoyageRunner");
                    return false;
                }

                if (DateTime.UtcNow - _nativeBeginIssuedUtc <
                    NativePlannerConfirmationTimeout)
                {
                    AllflameLog.Throttled(
                        "voyage_native_begin_pending",
                        TimeSpan.FromSeconds(1),
                        "VOYAGE_BEGIN_PENDING" +
                        "|Mode=Native" +
                        "|Postcondition=False" +
                        "|Reason=AwaitVoyageAreaTransition");
                    return true;
                }

                _nativeBeginPending = false;
                _nativeBeginFallbackUsed = true;
                _retryAfterUtc = DateTime.MinValue;
                AllflameLog.Info(
                    "VOYAGE_BEGIN_POSTCONDITION" +
                    "|Mode=Native" +
                    "|Postcondition=False" +
                    "|Reason=VoyageAreaTransitionTimeout" +
                    "|Fallback=StableElement");
                return true;
            }

            AllflameSettings settings = AllflameSettings.Instance;
            bool enabled =
                settings.AutoPlanVoyage ||
                settings.StartVoyageWhenReady;
            bool inHub =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            if (!enabled || !inHub)
            {
                ResetValerieApproachRecovery(
                    0,
                    !enabled ? "Disabled" : "LeftHub");
                AllflameProgressWatchdog.Clear();
                _stage = 0;
                _valerieEffectDeadlineUtc = DateTime.MinValue;
                _valerieEffectFailures = 0;
                _manualReady = false;
                _planningReadyAtOpen = false;
                _chartDetectionAttempts = 0;
                _lastInsufficientChartCount = -1;
                _stableInsufficientChartSnapshots = 0;
                _plannerOpenTargetOverrideActive = false;
                ResetNativePlannerActionState();
                return false;
            }

            if (_nativeClearPending)
            {
                if (DateTime.UtcNow < _retryAfterUtc)
                {
                    return true;
                }

                VoyagePlanningUi.StableVoyageSnapshot clearVerification;
                if (VoyagePlanningUi.TryResolveStable(
                        out clearVerification) &&
                    clearVerification.BoardChartCount == 0)
                {
                    _nativeClearPending = false;
                    _stage = 1;
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(250);
                    AllflameLog.Info(
                        "VOYAGE_CLEAR_BOARD_POSTCONDITION" +
                        "|Mode=Native" +
                        "|Postcondition=True" +
                        "|BoardAfter=0" +
                        "|Fallback=None");
                    return true;
                }

                if (DateTime.UtcNow - _nativeClearIssuedUtc <
                    NativePlannerConfirmationTimeout)
                {
                    AllflameLog.Throttled(
                        "voyage_native_clear_pending",
                        TimeSpan.FromSeconds(1),
                        "VOYAGE_CLEAR_BOARD_PENDING" +
                        "|Mode=Native" +
                        "|Postcondition=False" +
                        "|Reason=AwaitStableBoardSnapshot");
                    return true;
                }

                _nativeClearPending = false;
                _nativeClearFallbackUsed = true;
                _stage = 0;
                _retryAfterUtc = DateTime.MinValue;
                AllflameLog.Info(
                    "VOYAGE_CLEAR_BOARD_POSTCONDITION" +
                    "|Mode=Native" +
                    "|Postcondition=False" +
                    "|Reason=StableBoardSnapshotTimeout" +
                    "|Fallback=StableElement");
                return true;
            }

            if (AllflameRunState.VoyageStarted)
            {
                ResetValerieApproachRecovery(0, "VoyageStarted");
                AllflameProgressWatchdog.Clear();
                AllflameLog.Throttled(
                    "voyage_started_wait",
                    TimeSpan.FromSeconds(5),
                    "VOYAGE_READY|Started=True|Action=WaitingForVoyageTransition");
                return false;
            }

            if (_manualReady)
            {
                AllflameProgressWatchdog.Clear();
                AllflameLog.Throttled(
                    "voyage_manual_begin",
                    TimeSpan.FromSeconds(5),
                    "VOYAGE_READY|BoardCharts=9|Action=WaitingForManualBegin");
                return true;
            }

            if (DateTime.UtcNow < _retryAfterUtc)
            {
                return true;
            }

            // Image matching is intentionally armed only after the bot has
            // requested Plan Voyage, DPB reports the planning UI, or an
            // already-confirmed visual stage is in progress. Scanning the
            // ordinary boat scene produced plausible 0.50 correlations and
            // caused random Clear Board clicks before Valerie was opened.
            bool visualScanArmed =
                _stage > 0 ||
                _voyageUiExpectedUntilUtc != DateTime.MinValue ||
                _valerieEffectDeadlineUtc != DateTime.MinValue ||
                AllflameContext.PlanVoyageVisible;
            DeepwaterVoyageSnapshot nativeVoyageSnapshot;
            bool nativeVoyageOpen =
                NativeDeepwaterVoyageUi.TryCapture(
                    out nativeVoyageSnapshot) &&
                nativeVoyageSnapshot.IsOpened;
            bool voyageOpen =
                nativeVoyageOpen ||
                (visualScanArmed &&
                 VoyagePlanningUi.IsOpen());

            AllflameLog.Throttled(
                "voyage_config",
                TimeSpan.FromSeconds(5),
                "VOYAGE_CONFIG" +
                "|ChartsRequired=" + settings.ChartsRequiredForVoyage +
                "|EffectiveStockRequired=" +
                AllflameRunState.VoyageRequiredCharts +
                "|AutoPlan=" + settings.AutoPlanVoyage +
                "|StartWhenReady=" + settings.StartVoyageWhenReady +
                "|PlannerOpen=" + voyageOpen +
                "|NativeRead=" + settings.UseNativeVoyagePlannerRead +
                "|NativeActions=" +
                settings.UseNativeVoyagePlannerActions +
                "|ChainActive=" + AllflameRunState.VoyageChainActive +
                "|AvailableEstimate=" +
                AllflameRunState.VoyageAvailableCharts);

            // The session estimate is only a gate for opening the planner. If
            // the planner is already open, let its fresh inventory snapshot
            // decide whether a legal nine-Chart board can be built.
            if (!voyageOpen &&
                AllflameRunState.VoyagePlanChecked &&
                !AllflameRunState.VoyageReadyForPlanning &&
                !AllflameRunState.VoyageReconcileRequired)
            {
                _planningReadyAtOpen = false;
                _plannerOpenTargetOverrideActive = false;
                _chartDetectionAttempts = 0;
                _lastInsufficientChartCount = -1;
                _stableInsufficientChartSnapshots = 0;
                AllflameLog.Throttled(
                    "voyage_progress_wait",
                    TimeSpan.FromSeconds(5),
                    "VOYAGE_PROGRESS_WAIT" +
                    "|AvailableEstimate=" +
                    AllflameRunState.VoyageAvailableCharts +
                    "|Required=" +
                    AllflameRunState.VoyageRequiredCharts +
                    "|Remaining=" +
                    Math.Max(
                        0,
                        AllflameRunState.VoyageRequiredCharts -
                        AllflameRunState.VoyageAvailableCharts) +
                    "|Action=RunChartAreas");
                return false;
            }

            if (voyageOpen)
            {
                ResetValerieApproachRecovery(0, "VoyageUiOpened");
                AllflameProgressWatchdog.Begin(
                    Name,
                    0,
                    "Voyage Board");
                if (AllflameProgressWatchdog.TryConsumeRecovery(
                        "CloseAndReopenVoyageBoard"))
                {
                    await Coroutines.CloseBlockingWindows();
                    try
                    {
                        ExilePather.Reload(true);
                    }
                    catch
                    {
                    }
                    AllflameContext.Refresh(true);
                    AllflameProgressWatchdog.MarkProgress(
                        "ReopenVoyageBoard");
                    _stage = 0;
                    _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(800);
                    return true;
                }
                _valerieEffectDeadlineUtc = DateTime.MinValue;
                _valerieEffectFailures = 0;
            }
            if (!voyageOpen)
            {
                // Converse returns before the Voyage UI finishes rendering.
                // During this latch the table may already cover the screen, so
                // issuing world movement/interactions would make the character
                // run around Valerie while the UI is visibly open.
                if (DateTime.UtcNow < _voyageUiExpectedUntilUtc)
                {
                    AllflameLog.Throttled(
                        "voyage_visual_render_wait",
                        TimeSpan.FromMilliseconds(700),
                        "VOYAGE_VISUAL_WAIT|Reason=DialogueAccepted" +
                        "|Action=SuppressWorldMovement" +
                        "|RemainingMs=" +
                        Math.Max(
                            0,
                            (int)(_voyageUiExpectedUntilUtc -
                                  DateTime.UtcNow).TotalMilliseconds));
                    return true;
                }

                if (_voyageUiExpectedUntilUtc != DateTime.MinValue)
                {
                    _voyageUiExpectedUntilUtc = DateTime.MinValue;
                    _stage = 0;
                    await Coroutines.CloseBlockingWindows();
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(500);
                    AllflameLog.Info(
                        "VOYAGE_VISUAL_RECOVERY|Reason=TitleTimeout" +
                        "|Action=CloseUiBeforeRetry");
                    return true;
                }

                string voyageDialogOption =
                    FindVoyageDialogOption();
                if (LokiPoe.InGameState.NpcDialogUi.IsOpened)
                {
                    ResetValerieApproachRecovery(
                        0,
                        "ValerieDialogOpened");
                    _valerieEffectDeadlineUtc = DateTime.MinValue;
                    _valerieEffectFailures = 0;
                }
                if (LokiPoe.InGameState.NpcDialogUi.IsOpened &&
                    !String.IsNullOrEmpty(voyageDialogOption))
                {
                    var result =
                        LokiPoe.InGameState.NpcDialogUi.Converse(
                            voyageDialogOption);
                    _stage = 0;
                    VoyagePlanningUi.ArmExpectedOpen(
                        TimeSpan.FromSeconds(12));
                    _voyageUiExpectedUntilUtc =
                        DateTime.UtcNow.AddSeconds(5);
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(800);
                    AllflameLog.Info(
                        "VOYAGE_OPEN|Source=ValerieConversation" +
                        "|Option=" + voyageDialogOption +
                        "|Result=" + result);
                    return true;
                }

                if (LokiPoe.InGameState.NpcDialogUi.IsOpened)
                {
                    AllflameLog.Throttled(
                        "voyage_dialog_option_missing",
                        TimeSpan.FromSeconds(2),
                        "VOYAGE_DIALOG_WAIT|Entries=" +
                        GetDialogEntrySummary());
                    return true;
                }

                NetworkObject valerie = AllflameContext.ValerieObject;
                if (valerie == null || !valerie.IsValid)
                {
                    // Starting the bot while it is already on the boat skips
                    // TravelToSovereignTask, so no /boat staging request was
                    // created. Enter the same deterministic staging flow used
                    // after /boat; once near the central deck Valerie becomes
                    // available to the object manager.
                    AllflameRunState.RequireBoatStaging(
                        "ValerieMissing");
                    AllflameLog.Throttled(
                        "voyage_valerie_missing",
                        TimeSpan.FromSeconds(4),
                        "VOYAGE_OPEN_WAIT|Reason=ValerieMissing");
                    return true;
                }

                float interactionRange =
                    Math.Max(
                        ValerieInteractionRange,
                        settings.InteractDistance);
                if (_valerieEffectDeadlineUtc != DateTime.MinValue)
                {
                    if (DateTime.UtcNow < _valerieEffectDeadlineUtc)
                    {
                        return true;
                    }

                    _valerieEffectDeadlineUtc = DateTime.MinValue;
                    _valerieEffectFailures++;
                    BlacklistCurrentValerieApproach(
                        "VoyageInteractionSucceededWithoutDialog");
                    StartValerieApproachRecovery(
                        valerie,
                        "Valerie, the Corsair",
                        "VoyageInteractionEffectTimeout");
                    AllflameLog.Info(
                        "VOYAGE_NPC_EFFECT_TIMEOUT" +
                        "|Npc=Valerie, the Corsair" +
                        "|Distance=" +
                        valerie.Distance.ToString("0.0") +
                        "|Failures=" + _valerieEffectFailures +
                        "|Action=BlacklistAndAlternateApproach");
                    return true;
                }
                if (ContinueValerieApproachRecovery(
                        valerie,
                        "Valerie, the Corsair"))
                {
                    return true;
                }
                if (LokiPoe.Me != null &&
                    IsValerieApproachPositionBlacklisted(
                        LokiPoe.Me.Position))
                {
                    StartValerieApproachRecovery(
                        valerie,
                        "Valerie, the Corsair",
                        "VoyageCurrentPositionBlacklisted");
                    AllflameLog.Throttled(
                        "voyage_valerie_position_blacklisted",
                        TimeSpan.FromSeconds(2),
                        "VOYAGE_OPEN_RECOVERY" +
                        "|Reason=CurrentPositionBlacklisted" +
                        "|Player=" + LokiPoe.Me.Position +
                        "|Action=AlternateApproach");
                    return true;
                }
                if (valerie.Distance > interactionRange)
                {
                    await MoveOrInteract(
                        valerie,
                        "Valerie, the Corsair",
                        interactionRange);
                    // PrepareVoyage owns this tick even when ExilePather could
                    // not produce a route. Allowing lower tasks to run here
                    // made Stash and Chart Device fight the NPC movement.
                    return true;
                }

                await FinishMovementBeforeInteraction(
                    "Valerie Voyage");
                bool interacted =
                    await InteractWithRecovery(valerie);
                _valerieEffectDeadlineUtc =
                    interacted
                        ? DateTime.UtcNow.AddMilliseconds(900)
                        : DateTime.MinValue;
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(
                        interacted ? 650 : 800);
                AllflameLog.Info(
                    "VOYAGE_OPEN|Source=Valerie" +
                    "|InteractSuccess=" + interacted +
                    "|Distance=" +
                    valerie.Distance.ToString("0.0") +
                    "|InteractionRange=" +
                    interactionRange.ToString("0.0"));
                if (!interacted)
                {
                    StartValerieApproachRecovery(
                        valerie,
                        "Valerie, the Corsair",
                        "VoyageInteractionNotHighlighted");
                }
                return true;
            }

            _voyageUiExpectedUntilUtc = DateTime.MinValue;

            // Always return placed Charts before counting. This makes the
            // right-side pool the single authoritative count and recovers
            // safely from an interrupted previous planning attempt.
            if (_stage == 0)
            {
                ResetStablePlacement();
                _lastInsufficientChartCount = -1;
                _stableInsufficientChartSnapshots = 0;
                // Latch readiness before Clear Board. The visual inventory
                // detector may temporarily report zero while the returned
                // Charts are animating, and must never erase the completed
                // Chart-Area progress that brought us here.
                _planningReadyAtOpen =
                    AllflameRunState.VoyageReadyForPlanning ||
                    AllflameRunState.VoyageReconcileRequired;
                _chartDetectionAttempts = 0;
                VoyagePlanningUi.StableVoyageSnapshot stableClear;
                if (VoyagePlanningUi.TryResolveStable(
                        out stableClear))
                {
                    LogNativeVoyagePlannerShadow(stableClear);
                    if (NativeVoyageActionsEligible(stableClear) &&
                        !_nativeClearFallbackUsed)
                    {
                        string nativeClearReason;
                        bool nativeCleared =
                            NativeDeepwaterVoyageUi.TryClearBoard(
                                out nativeClearReason);
                        AllflameLog.Info(
                            "VOYAGE_CLEAR_BOARD" +
                            "|Mode=Native" +
                            "|InputSent=" + nativeCleared +
                            "|Postcondition=False" +
                            "|Reason=" + nativeClearReason +
                            "|AvailableBefore=" +
                            stableClear.AvailableChartSlots.Count +
                            "|BoardBefore=" +
                            stableClear.BoardChartCount);
                        if (nativeCleared)
                        {
                            _nativeClearPending = true;
                            _nativeClearIssuedUtc = DateTime.UtcNow;
                            _stage = 1;
                            _retryAfterUtc =
                                DateTime.UtcNow.AddMilliseconds(150);
                            return true;
                        }
                        _nativeClearFallbackUsed = true;
                        AllflameLog.Info(
                            "UI_FALLBACK" +
                            "|Task=" + Name +
                            "|From=Native" +
                            "|To=StableElement" +
                            "|Reason=" + nativeClearReason);
                    }
                    AllflameLog.Throttled(
                        "voyage_element_clear",
                        TimeSpan.FromSeconds(2),
                        "VOYAGE_UI_FALLBACK" +
                        "|From=ElementPrimary" +
                        "|To=StableElement" +
                        "|Reason=PlanBoardOpen");
                    bool stableClicked =
                        VoyagePlanningUi.ClickStableElement(
                            stableClear.ClearBoardButton,
                            "ClearBoard");
                    if (stableClicked)
                    {
                        _stage = 1;
                    }
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(
                            stableClicked ? 900 : 300);
                    AllflameLog.Info(
                        "VOYAGE_CLEAR_BOARD" +
                        "|Mode=StableElement" +
                        "|RootIndex=" + stableClear.RootIndex +
                        "|AvailableBefore=" +
                        stableClear.AvailableChartSlots.Count +
                        "|BoardBefore=" +
                        stableClear.BoardChartCount +
                        "|Clicked=" + stableClicked);
                    return true;
                }

                VoyagePlanningUi.VoyageVisualSnapshot
                    firstClearSnapshot;
                AllflameLog.Throttled(
                    "voyage_element_to_visual_clear",
                    TimeSpan.FromSeconds(2),
                    "VOYAGE_UI_FALLBACK" +
                    "|From=StableElement" +
                    "|To=Visual" +
                    "|Reason=StableElementUnavailable");
                bool firstFound =
                    VoyagePlanningUi.TryAnalyze(
                        out firstClearSnapshot,
                        true);
                if (!firstFound ||
                    firstClearSnapshot.ButtonCorrelation < 0.50)
                {
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(350);
                    AllflameLog.Info(
                        "VOYAGE_CLEAR_BOARD_GUARD" +
                        "|State=Wait" +
                        "|Reason=HighConfidenceBeginAnchorNotDetected" +
                        "|Correlation=" +
                        (firstFound
                            ? firstClearSnapshot.ButtonCorrelation
                                .ToString("0.000")
                            : "n/a") +
                        "|Action=NoClick");
                    return true;
                }

                // Complete the safety confirmation atomically. The previous
                // cross-tick guard lost its candidate when an intermediate
                // context refresh reset task state, allowing Valerie
                // interaction to close the visible table before Ctrl+Click.
                AllflameLog.Info(
                    "VOYAGE_CLEAR_BOARD_GUARD" +
                    "|State=ConfirmingAtomic" +
                    "|Snapshot=1/2" +
                    "|Begin=" +
                    firstClearSnapshot.BeginVoyageLocation +
                    "|Correlation=" +
                    firstClearSnapshot.ButtonCorrelation
                        .ToString("0.000") +
                    "|Scale=" +
                    firstClearSnapshot.Scale.ToString("0.00") +
                    "|Action=HoldTaskAndRescan");
                await LokiCoroutine.Sleep(250);

                VoyagePlanningUi.VoyageVisualSnapshot
                    secondClearSnapshot;
                bool secondFound =
                    VoyagePlanningUi.TryAnalyze(
                        out secondClearSnapshot,
                        true);
                double anchorDrift =
                    secondFound
                        ? Math.Sqrt(
                            Math.Pow(
                                secondClearSnapshot
                                    .BeginVoyageLocation.X -
                                firstClearSnapshot
                                    .BeginVoyageLocation.X,
                                2) +
                            Math.Pow(
                                secondClearSnapshot
                                    .BeginVoyageLocation.Y -
                                firstClearSnapshot
                                    .BeginVoyageLocation.Y,
                                2))
                        : Double.MaxValue;
                double scaleDrift =
                    secondFound
                        ? Math.Abs(
                            secondClearSnapshot.Scale -
                            firstClearSnapshot.Scale)
                        : Double.MaxValue;
                bool stable =
                    secondFound &&
                    secondClearSnapshot.ButtonCorrelation >= 0.50 &&
                    anchorDrift <= 12.0 &&
                    scaleDrift <= 0.02;
                if (!stable)
                {
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(300);
                    AllflameLog.Info(
                        "VOYAGE_CLEAR_BOARD_GUARD" +
                        "|State=Wait" +
                        "|Reason=AtomicConfirmationUnstable" +
                        "|SecondFound=" + secondFound +
                        "|FirstCorrelation=" +
                        firstClearSnapshot.ButtonCorrelation
                            .ToString("0.000") +
                        "|SecondCorrelation=" +
                        (secondFound
                            ? secondClearSnapshot.ButtonCorrelation
                                .ToString("0.000")
                            : "n/a") +
                        "|AnchorDrift=" +
                        (secondFound
                            ? anchorDrift.ToString("0.0")
                            : "n/a") +
                        "|ScaleDrift=" +
                        (secondFound
                            ? scaleDrift.ToString("0.00")
                            : "n/a") +
                        "|Action=KeepUiAndRetryWithoutClick");
                    return true;
                }

                bool clicked =
                    VoyagePlanningUi.ClickClient(
                        secondClearSnapshot.ClearBoardLocation);
                _stage = 1;
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(
                        clicked ? 900 : 250);
                AllflameLog.Info(
                    "VOYAGE_CLEAR_BOARD|Found=" +
                    secondFound +
                    "|Clicked=" + clicked +
                    (secondFound
                        ? "|Client=" +
                          secondClearSnapshot.ClearBoardLocation +
                          "|ButtonCorrelation=" +
                           secondClearSnapshot.ButtonCorrelation
                               .ToString("0.000")
                         : String.Empty));
                return true;
            }

            VoyagePlanningUi.StableVoyageSnapshot stableSnapshot;
            if (VoyagePlanningUi.TryResolveStable(
                    out stableSnapshot))
            {
                LogNativeVoyagePlannerShadow(stableSnapshot);
                AllflameLog.Throttled(
                    "voyage_element_primary",
                    TimeSpan.FromSeconds(2),
                    "VOYAGE_UI_FALLBACK" +
                    "|From=ElementPrimary" +
                    "|To=StableElement" +
                    "|Reason=PlanBoardOpen");
                return await RunStableVoyagePlanner(
                    settings,
                    stableSnapshot);
            }

            VoyagePlanningUi.VoyageVisualSnapshot snapshot;
            AllflameLog.Throttled(
                "voyage_element_to_visual",
                TimeSpan.FromSeconds(2),
                "VOYAGE_UI_FALLBACK" +
                "|From=StableElement" +
                "|To=Visual" +
                "|Reason=StableElementUnavailable");
            if (!VoyagePlanningUi.TryAnalyze(
                    out snapshot,
                    true))
            {
                _stage = 0;
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(500);
                AllflameLog.Throttled(
                    "voyage_visual_lost",
                    TimeSpan.FromSeconds(2),
                    "VOYAGE_VISUAL_WAIT|Reason=BeginButtonNotDetected");
                return true;
            }

            var chartLocations = snapshot.ChartLocations;
            int availableCount = snapshot.AvailableChartCount;
            int configuredTarget =
                Math.Max(
                    0,
                    Math.Min(
                        60,
                        settings.ChartsRequiredForVoyage));
            // A Voyage board always consumes nine Charts. Zero therefore
            // means "begin as soon as a legal set of nine exists".
            int effectiveTarget =
                AllflameRunState.VoyageChainActive
                    ? 9
                    : Math.Max(9, configuredTarget);
            bool reconciliation =
                AllflameRunState.VoyageReconcileRequired;

            if (!_plannerOpenTargetOverrideActive &&
                availableCount >= 9)
            {
                _plannerOpenTargetOverrideActive = true;
                AllflameLog.Info(
                    "VOYAGE_PLANNER_TARGET_OVERRIDE" +
                    "|PlannerOpen=True" +
                    "|Available=" + availableCount +
                    "|Board=Unknown" +
                    "|Total=" + availableCount +
                    "|ConfiguredRequired=" + configuredTarget +
                    "|EffectiveTarget=9" +
                    "|Reason=PlannerAlreadyOpen" +
                    "|Action=PlaceNineCharts" +
                    "|Detection=VisualFallback");
            }

            AllflameLog.Info(
                "VOYAGE_CHART_COUNT|Available=" + availableCount +
                "|ConfiguredRequired=" + configuredTarget +
                "|EffectiveRequired=" + effectiveTarget +
                "|Mode=" +
                (AllflameRunState.VoyageChainActive
                    ? "ContinueVoyageChain"
                    : "BuildToConfiguredRequirement") +
                "|Reconciliation=" + reconciliation +
                "|Detection=BeginButtonAnchoredGreenMarkers" +
                "|DpbElements=Removed" +
                "|ClickSource=VisualMarkers" +
                "|ShapeDetection=Disabled" +
                "|BeginEnabled=" + snapshot.BeginVoyageEnabled +
                "|ButtonCorrelation=" +
                snapshot.ButtonCorrelation.ToString("0.000"));

            // An empty pool is authoritative even when the session estimate
            // said planning was ready. That estimate can be stale after a
            // restart or an interrupted Voyage chain. Confirm on two fresh
            // frames so a Clear Board return animation cannot erase valid
            // progress, then close the table and let Chart tasks continue.
            if (availableCount == 0)
            {
                _chartDetectionAttempts++;
                if (_chartDetectionAttempts < 2)
                {
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(500);
                    AllflameLog.Info(
                        "VOYAGE_EMPTY_CONFIRM" +
                        "|Snapshot=1/2" +
                        "|PreviousEstimate=" +
                        AllflameRunState.VoyageAvailableCharts +
                        "|PlanningReadyAtOpen=" +
                        _planningReadyAtOpen +
                        "|Action=WaitForSecondFreshFrame");
                    return true;
                }

                int previousEstimate =
                    AllflameRunState.VoyageAvailableCharts;
                AllflameRunState.MarkVoyagePlanChecked(0);
                _stage = 0;
                _planningReadyAtOpen = false;
                _plannerOpenTargetOverrideActive = false;
                _chartDetectionAttempts = 0;
                bool plannerClosed =
                    await CloseVoyagePlannerBounded(
                        "EmptyVisualSnapshot");
                AllflameLog.Info(
                    "VOYAGE_PLAN_EMPTY" +
                    "|Available=0" +
                    "|ConfirmedSnapshots=2" +
                    "|PreviousEstimate=" + previousEstimate +
                    "|Closed=" + plannerClosed +
                    "|Action=" +
                    (plannerClosed
                        ? "ContinueChartAreas"
                        : "RetryPlannerClose"));
                if (!plannerClosed)
                {
                    _stage = 1;
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(500);
                }
                return !plannerClosed;
            }

            bool progressAllowsPlanning =
                (_plannerOpenTargetOverrideActive &&
                 availableCount >= 9) ||
                (reconciliation
                    ? availableCount >= effectiveTarget
                    : (_planningReadyAtOpen ||
                       availableCount >= effectiveTarget));
            if (!progressAllowsPlanning)
            {
                if (reconciliation &&
                    _chartDetectionAttempts < 2)
                {
                    _chartDetectionAttempts++;
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(500);
                    AllflameLog.Info(
                        "VOYAGE_RECONCILE_CONFIRM" +
                        "|Available=" + availableCount +
                        "|RequiredForAnotherVoyage=" +
                        effectiveTarget +
                        "|Snapshot=" +
                        _chartDetectionAttempts + "/2" +
                        "|Action=WaitForReturnedChartAnimation");
                    return true;
                }
                AllflameRunState.MarkVoyagePlanChecked(
                    availableCount);
                _stage = 0;
                _planningReadyAtOpen = false;
                _plannerOpenTargetOverrideActive = false;
                bool plannerClosed =
                    await CloseVoyagePlannerBounded(
                        "InsufficientVisualCharts");
                AllflameLog.Info(
                    "VOYAGE_NOT_READY|Available=" +
                    availableCount +
                    "|Required=" + effectiveTarget +
                    "|DetectedChartLocations=" +
                    chartLocations.Count +
                    "|Closed=" + plannerClosed +
                    "|Action=" +
                    (plannerClosed
                        ? "ContinueChartAreas"
                        : "RetryPlannerClose"));
                if (!plannerClosed)
                {
                    _stage = 1;
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(500);
                }
                return !plannerClosed;
            }

            if (reconciliation)
            {
                // Replace the post-Begin estimate with the real right-side
                // Voyage inventory count before consuming the next set.
                AllflameRunState.MarkVoyagePlanChecked(
                    availableCount);
                AllflameLog.Info(
                    "VOYAGE_CHAIN_RECONCILED" +
                    "|Available=" + availableCount +
                    "|CanContinue=True" +
                    "|NextConsumption=9");
            }

            int clickableChartCount = chartLocations.Count;
            if (clickableChartCount < 9)
            {
                _chartDetectionAttempts++;
                int confirmedShortfallCount = Math.Min(
                    availableCount,
                    clickableChartCount);
                if (_lastInsufficientChartCount ==
                    confirmedShortfallCount)
                {
                    _stableInsufficientChartSnapshots++;
                }
                else
                {
                    _lastInsufficientChartCount =
                        confirmedShortfallCount;
                    _stableInsufficientChartSnapshots = 1;
                }
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(650);
                AllflameLog.Throttled(
                    "voyage_chart_render_wait",
                    TimeSpan.FromMilliseconds(650),
                    "VOYAGE_CHART_WAIT|ProgressReady=True" +
                    "|Visual=" +
                    snapshot.ChartLocations.Count +
                    "|Dpb=Removed" +
                    "|Attempt=" + _chartDetectionAttempts +
                    "|StableCount=" +
                    _stableInsufficientChartSnapshots + "/2" +
                    "|Action=WaitForReturnedCharts");
                if (_stableInsufficientChartSnapshots >= 2)
                {
                    int previousEstimate =
                        AllflameRunState.VoyageAvailableCharts;
                    AllflameRunState.MarkVoyagePlanChecked(
                        confirmedShortfallCount);
                    _stage = 0;
                    _planningReadyAtOpen = false;
                    _plannerOpenTargetOverrideActive = false;
                    _chartDetectionAttempts = 0;
                    _lastInsufficientChartCount = -1;
                    _stableInsufficientChartSnapshots = 0;
                    bool plannerClosed =
                        await CloseVoyagePlannerBounded(
                            "VisualChartShortfall");
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(500);
                    AllflameLog.Info(
                        "VOYAGE_CHART_SHORTFALL_CONFIRMED" +
                        "|Snapshots=2" +
                        "|PreviousEstimate=" + previousEstimate +
                        "|ActualAvailable=" +
                        confirmedShortfallCount +
                        "|Required=9" +
                        "|Closed=" + plannerClosed +
                        "|Action=" +
                        (plannerClosed
                            ? "CorrectEstimateAndRunCharts"
                            : "RetryPlannerClose"));
                    if (!plannerClosed)
                    {
                        _stage = 1;
                        _retryAfterUtc =
                            DateTime.UtcNow.AddMilliseconds(500);
                    }
                    return !plannerClosed;
                }
                if (_chartDetectionAttempts >= 8)
                {
                    _stage = 0;
                    _chartDetectionAttempts = 0;
                    bool plannerClosed =
                        await CloseVoyagePlannerBounded(
                            "VisualChartRenderRetry");
                    _retryAfterUtc =
                        DateTime.UtcNow.AddSeconds(1);
                    AllflameLog.Info(
                        "VOYAGE_PLAN_RETRY" +
                        "|Reason=FewerThanNineClickableCharts" +
                        "|ProgressPreserved=True" +
                        "|Closed=" + plannerClosed);
                }
                return true;
            }

            _chartDetectionAttempts = 0;
            _lastInsufficientChartCount = -1;
            _stableInsufficientChartSnapshots = 0;
            return await RunIncrementalVisualVoyagePlanner(
                settings,
                snapshot);
        }

        private void LogNativeVoyagePlannerShadow(
            VoyagePlanningUi.StableVoyageSnapshot stableSnapshot)
        {
            if (!AllflameSettings.Instance.UseNativeVoyagePlannerRead ||
                stableSnapshot == null)
            {
                _nativePlannerShadowMatches = 0;
                return;
            }

            DeepwaterVoyageSnapshot nativeSnapshot;
            if (!NativeDeepwaterVoyageUi.TryCapture(
                    out nativeSnapshot) ||
                nativeSnapshot == null)
            {
                _nativePlannerShadowMatches = 0;
                return;
            }

            bool openedMatch = nativeSnapshot.IsOpened;
            bool availableMatch =
                nativeSnapshot.AvailableChartCount ==
                stableSnapshot.AvailableChartSlots.Count;
            bool boardCountMatch =
                nativeSnapshot.BoardChartCount ==
                stableSnapshot.BoardChartCount;
            bool boardSlotsMatch =
                nativeSnapshot.BoardSlotCount ==
                stableSnapshot.BoardSlotCount;
            bool match = openedMatch &&
                availableMatch &&
                boardCountMatch &&
                boardSlotsMatch;
            _nativePlannerShadowMatches = match
                ? Math.Min(3, _nativePlannerShadowMatches + 1)
                : 0;
            AllflameLog.Info(
                "VOYAGE_PLANNER_SHADOW" +
                "|NativeOpened=" + nativeSnapshot.IsOpened +
                "|StableOpened=True" +
                "|NativeAvailable=" +
                nativeSnapshot.AvailableChartCount +
                "|StableAvailable=" +
                stableSnapshot.AvailableChartSlots.Count +
                "|NativeBoard=" + nativeSnapshot.BoardChartCount +
                "|StableBoard=" + stableSnapshot.BoardChartCount +
                "|NativeBoardSlots=" +
                nativeSnapshot.BoardSlotCount +
                "|StableBoardSlots=" +
                stableSnapshot.BoardSlotCount +
                "|Match=" + match +
                "|ConsecutiveMatches=" +
                _nativePlannerShadowMatches +
                "|NativeActionsEligible=" +
                (_nativePlannerShadowMatches >= 2));
        }

        private bool NativeVoyageActionsEligible(
            VoyagePlanningUi.StableVoyageSnapshot stableSnapshot)
        {
            if (!AllflameSettings.Instance.UseNativeVoyagePlannerActions ||
                stableSnapshot == null ||
                !AllflameSettings.Instance.UseNativeVoyagePlannerRead)
            {
                return false;
            }
            return _nativePlannerShadowMatches >= 2;
        }

        private Task<bool> RunStableVoyagePlanner(
            AllflameSettings settings,
            VoyagePlanningUi.StableVoyageSnapshot snapshot)
        {
            return RunIncrementalStableVoyagePlanner(
                settings,
                snapshot);
        }

        private async Task<bool> RunIncrementalStableVoyagePlanner(
            AllflameSettings settings,
            VoyagePlanningUi.StableVoyageSnapshot snapshot)
        {
            int available = snapshot.AvailableChartSlots.Count;
            int board = snapshot.BoardChartCount;
            int totalCharts = available + board;
            int configuredTarget = Math.Max(
                0,
                Math.Min(60, settings.ChartsRequiredForVoyage));
            int effectiveTarget = AllflameRunState.VoyageChainActive
                ? 9
                : Math.Max(9, configuredTarget);

            if (!_plannerOpenTargetOverrideActive &&
                totalCharts >= 9)
            {
                _plannerOpenTargetOverrideActive = true;
                AllflameLog.Info(
                    "VOYAGE_PLANNER_TARGET_OVERRIDE" +
                    "|PlannerOpen=True" +
                    "|Available=" + available +
                    "|Board=" + board +
                    "|Total=" + totalCharts +
                    "|ConfiguredRequired=" + configuredTarget +
                    "|EffectiveTarget=9" +
                    "|Reason=PlannerAlreadyOpen" +
                    "|Action=PlaceNineCharts");
            }
            bool plannerOpenOverrideReady =
                _plannerOpenTargetOverrideActive &&
                totalCharts >= 9;

            AllflameLog.Throttled(
                "voyage_incremental_state",
                TimeSpan.FromMilliseconds(500),
                "VOYAGE_RUNNER_STATE" +
                "|State=" + (_stablePlacementAwaitingVerification
                    ? "VerifyChartMove"
                    : (board >= 9 ? "BeginVoyage" : "PlaceNextChart")) +
                "|Available=" + available +
                "|Board=" + board +
                "|Confirmed=" + _stablePlacementConfirmed + "/9" +
                "|ConfiguredRequired=" + configuredTarget +
                "|TargetOverride=" +
                _plannerOpenTargetOverrideActive +
                "|OneActionPerCycle=True" +
                "|Snapshot=FreshStableElements");

            if (!_stablePlacementActive)
            {
                if (totalCharts == 0)
                {
                    _chartDetectionAttempts++;
                    if (_chartDetectionAttempts < 2)
                    {
                        _retryAfterUtc =
                            DateTime.UtcNow.AddMilliseconds(300);
                        return true;
                    }
                    AllflameRunState.MarkVoyagePlanChecked(0);
                    _stage = 0;
                    _planningReadyAtOpen = false;
                    _plannerOpenTargetOverrideActive = false;
                    _chartDetectionAttempts = 0;
                    bool plannerClosed =
                        await CloseVoyagePlannerBounded(
                            "EmptyStableSnapshot");
                    AllflameLog.Info(
                        "VOYAGE_PLAN_EMPTY|Available=0" +
                        "|Detection=StableVoyageSlots" +
                        "|ConfirmedSnapshots=2" +
                        "|Closed=" + plannerClosed +
                        "|Action=" +
                        (plannerClosed
                            ? "ContinueChartAreas"
                            : "RetryPlannerClose"));
                    if (!plannerClosed)
                    {
                        _stage = 1;
                        _retryAfterUtc =
                            DateTime.UtcNow.AddMilliseconds(500);
                    }
                    return !plannerClosed;
                }

                bool reconciliation =
                    AllflameRunState.VoyageReconcileRequired;
                bool ready = plannerOpenOverrideReady ||
                    (reconciliation
                        ? totalCharts >= effectiveTarget
                        : (_planningReadyAtOpen ||
                           totalCharts >= effectiveTarget));
                if (!ready)
                {
                    if (_lastInsufficientChartCount == totalCharts)
                    {
                        _stableInsufficientChartSnapshots++;
                    }
                    else
                    {
                        _lastInsufficientChartCount = totalCharts;
                        _stableInsufficientChartSnapshots = 1;
                    }
                    if (_stableInsufficientChartSnapshots < 2)
                    {
                        _retryAfterUtc =
                            DateTime.UtcNow.AddMilliseconds(300);
                        return true;
                    }
                    AllflameRunState.MarkVoyagePlanChecked(totalCharts);
                    _stage = 0;
                    _planningReadyAtOpen = false;
                    _plannerOpenTargetOverrideActive = false;
                    bool plannerClosed =
                        await CloseVoyagePlannerBounded(
                            "InsufficientStableCharts");
                    AllflameLog.Info(
                        "VOYAGE_NOT_READY|Available=" + totalCharts +
                        "|Required=" + effectiveTarget +
                        "|Detection=StableVoyageSlots" +
                        "|Closed=" + plannerClosed +
                        "|Action=" +
                        (plannerClosed
                            ? "ContinueChartAreas"
                            : "RetryPlannerClose"));
                    if (!plannerClosed)
                    {
                        _stage = 1;
                        _retryAfterUtc =
                            DateTime.UtcNow.AddMilliseconds(500);
                    }
                    return !plannerClosed;
                }

                if (reconciliation ||
                    _plannerOpenTargetOverrideActive)
                {
                    AllflameRunState.MarkVoyagePlanChecked(totalCharts);
                }
                _stablePlacementActive = true;
                _stablePlacementBaselineAvailable = totalCharts;
                _stablePlacementConfirmed = Math.Min(9, board);
                _stablePlacementFailures = 0;
                _chartDetectionAttempts = 0;
                _lastInsufficientChartCount = -1;
                _stableInsufficientChartSnapshots = 0;
                AllflameLog.Info(
                    "VOYAGE_PLACEMENT_SESSION" +
                    "|State=Started" +
                    "|Available=" + available +
                    "|Board=" + board +
                    "|Target=9" +
                    "|ConfiguredRequired=" + configuredTarget +
                    "|TargetOverride=" +
                    _plannerOpenTargetOverrideActive +
                    "|Mode=OneActionPerCycle");
            }

            if (_stablePlacementAwaitingVerification)
            {
                bool moved =
                    available < _stablePlacementBeforeAvailable ||
                    board > _stablePlacementBeforeBoard;
                if (moved)
                {
                    _stablePlacementConfirmed = Math.Min(
                        9,
                        Math.Max(
                            board,
                            _stablePlacementBaselineAvailable -
                                available));
                    _stablePlacementAwaitingVerification = false;
                    _stablePlacementFailures = 0;
                    AllflameProgressWatchdog.MarkProgress(
                        "VoyageChartPlaced");
                    AllflameLog.Info(
                        "VOYAGE_CHART_MOVE_CONFIRMED" +
                        "|BeforeAvailable=" +
                        _stablePlacementBeforeAvailable +
                        "|AfterAvailable=" + available +
                        "|BeforeBoard=" +
                        _stablePlacementBeforeBoard +
                        "|AfterBoard=" + board +
                        "|Placed=" + _stablePlacementConfirmed + "/9");
                }
                else if (DateTime.UtcNow - _stablePlacementIssuedUtc <
                    TimeSpan.FromMilliseconds(900))
                {
                    return true;
                }
                else
                {
                    _stablePlacementAwaitingVerification = false;
                    _stablePlacementFailures++;
                    AllflameLog.Info(
                        "VOYAGE_CHART_MOVE_REJECTED" +
                        "|Failure=" + _stablePlacementFailures + "/3" +
                        "|Available=" + available +
                        "|Board=" + board +
                        "|Action=" + (_stablePlacementFailures >= 3
                            ? "ClearAndRestart"
                            : "RetryFreshSnapshot"));
                    if (_stablePlacementFailures >= 3)
                    {
                        ResetStablePlacement();
                        _stage = 0;
                        _retryAfterUtc =
                            DateTime.UtcNow.AddMilliseconds(500);
                    }
                    return true;
                }
            }

            if (board >= 9 || _stablePlacementConfirmed >= 9)
            {
                if (!settings.StartVoyageWhenReady)
                {
                    _manualReady = true;
                    return true;
                }
                if (NativeVoyageActionsEligible(snapshot) &&
                    !_nativeBeginFallbackUsed)
                {
                    string nativeBeginReason;
                    bool nativeBeginSent =
                        NativeDeepwaterVoyageUi.TryBeginVoyage(
                            out nativeBeginReason);
                    AllflameLog.Info(
                        "VOYAGE_BEGIN" +
                        "|Mode=Native" +
                        "|InputSent=" + nativeBeginSent +
                        "|Postcondition=False" +
                        "|BoardCharts=" + board +
                        "|Reason=" + nativeBeginReason +
                        "|OneActionPerCycle=True");
                    if (nativeBeginSent)
                    {
                        _nativeBeginPending = true;
                        _nativeBeginIssuedUtc = DateTime.UtcNow;
                        _retryAfterUtc =
                            DateTime.UtcNow.AddMilliseconds(150);
                        return true;
                    }
                    _nativeBeginFallbackUsed = true;
                    AllflameLog.Info(
                        "UI_FALLBACK" +
                        "|Task=" + Name +
                        "|From=Native" +
                        "|To=StableElement" +
                        "|Reason=" + nativeBeginReason);
                }
                bool clicked = VoyagePlanningUi.ClickStableElement(
                    snapshot.BeginVoyageButton,
                    "BeginVoyage");
                AllflameLog.Info(
                    "VOYAGE_BEGIN|Mode=StableElementIncremental" +
                    "|Clicked=" + clicked +
                    "|BoardCharts=" + board +
                    "|OneActionPerCycle=True");
                if (clicked)
                {
                    AllflameRunState.MarkVoyageStarted();
                    ResetStablePlacement();
                    _stage = 0;
                    _planningReadyAtOpen = false;
                    _plannerOpenTargetOverrideActive = false;
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(500);
                }
                else
                {
                    _stablePlacementFailures++;
                    if (_stablePlacementFailures >= 3)
                    {
                        ResetStablePlacement();
                        _stage = 0;
                    }
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(350);
                }
                return true;
            }

            if (snapshot.AvailableChartSlots.Count == 0)
            {
                _stablePlacementFailures++;
                if (_stablePlacementFailures >= 3)
                {
                    ResetStablePlacement();
                    _stage = 0;
                }
                _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(300);
                return true;
            }

            _stablePlacementBeforeAvailable = available;
            _stablePlacementBeforeBoard = board;
            if (NativeVoyageActionsEligible(snapshot))
            {
                FastMoveResult nativeMoveResult;
                string nativeMoveReason;
                bool nativeInputSent =
                    NativeDeepwaterVoyageUi.TryFastMoveFirstChart(
                        out nativeMoveResult,
                        out nativeMoveReason);
                AllflameLog.Info(
                    "VOYAGE_CHART_MOVE_ISSUED" +
                    "|Mode=Native" +
                    "|Placement=" +
                    (_stablePlacementConfirmed + 1) + "/9" +
                    "|BeforeAvailable=" + available +
                    "|BeforeBoard=" + board +
                    "|InputSent=" + nativeInputSent +
                    "|FastMoveResult=" + nativeMoveResult +
                    "|Reason=" + nativeMoveReason +
                    "|OneActionPerCycle=True");
                if (nativeInputSent)
                {
                    _stablePlacementIssuedUtc = DateTime.UtcNow;
                    _stablePlacementAwaitingVerification = true;
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(90);
                    return true;
                }
                AllflameLog.Info(
                    "UI_FALLBACK" +
                    "|Task=" + Name +
                    "|From=Native" +
                    "|To=StableElement" +
                    "|Reason=" + nativeMoveReason);
            }
            bool inputSent =
                await VoyagePlanningUi.CtrlClickStableChartSlot(
                    snapshot,
                    snapshot.AvailableChartSlots[0],
                    _stablePlacementConfirmed);
            _stablePlacementIssuedUtc = DateTime.UtcNow;
            _stablePlacementAwaitingVerification = inputSent;
            _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(90);
            AllflameLog.Info(
                "VOYAGE_CHART_MOVE_ISSUED" +
                "|Placement=" +
                (_stablePlacementConfirmed + 1) + "/9" +
                "|BeforeAvailable=" + available +
                "|BeforeBoard=" + board +
                "|InputSent=" + inputSent +
                "|Action=ReturnToTaskManager");
            if (!inputSent)
            {
                _stablePlacementFailures++;
            }
            return true;
        }

        private static bool VectorsCrossTarget(
            Vector2i previous,
            Vector2i current,
            Vector2i target)
        {
            double previousX = previous.X - target.X;
            double previousY = previous.Y - target.Y;
            double currentX = current.X - target.X;
            double currentY = current.Y - target.Y;
            return previousX * currentX + previousY * currentY <= 0;
        }

        private void ResetStablePlacement()
        {
            _stablePlacementActive = false;
            _stablePlacementAwaitingVerification = false;
            _stablePlacementBaselineAvailable = 0;
            _stablePlacementBeforeAvailable = 0;
            _stablePlacementBeforeBoard = 0;
            _stablePlacementConfirmed = 0;
            _stablePlacementFailures = 0;
            _stablePlacementIssuedUtc = DateTime.MinValue;
        }

        private bool IsVoyagePlannerOpenFresh(out string source)
        {
            source = "None";
            try
            {
                DeepwaterVoyageSnapshot nativeSnapshot;
                if (NativeDeepwaterVoyageUi.TryCapture(
                        out nativeSnapshot))
                {
                    source = "Native";
                    if (nativeSnapshot != null &&
                        nativeSnapshot.IsOpened)
                    {
                        return true;
                    }
                }
            }
            catch
            {
                source = "NativeException";
            }

            try
            {
                VoyagePlanningUi.StableVoyageSnapshot stableSnapshot;
                if (VoyagePlanningUi.TryResolveStable(
                        out stableSnapshot))
                {
                    source = "StableElement";
                    return true;
                }
            }
            catch
            {
                source = "StableElementException";
            }

            // The title is a weaker fallback than a complete stable tree, but
            // it prevents us from declaring the planner closed during a brief
            // Element refresh gap and releasing Chart Storage too early.
            try
            {
                AllflameContext.Refresh(true);
                if (AllflameContext.PlanVoyageVisible)
                {
                    source = "ContextTitle";
                    return true;
                }
            }
            catch
            {
                source = "ContextException";
            }

            return false;
        }

        private async Task<bool> CloseVoyagePlannerBounded(
            string reason)
        {
            string initialSource;
            bool initiallyOpen =
                IsVoyagePlannerOpenFresh(out initialSource);
            if (!initiallyOpen)
            {
                AllflameLog.Info(
                    "VOYAGE_PLANNER_CLOSE" +
                    "|Reason=" + (reason ?? String.Empty) +
                    "|Attempt=0/" + MaximumVoyagePlannerCloseAttempts +
                    "|Mode=None" +
                    "|InputSent=False" +
                    "|Postcondition=True" +
                    "|Source=" + initialSource);
                _plannerOpenTargetOverrideActive = false;
                return true;
            }

            for (int attempt = 1;
                 attempt <= MaximumVoyagePlannerCloseAttempts;
                 attempt++)
            {
                bool inputSent = false;
                bool focusSent = false;
                string inputReason = "Space";
                try
                {
                    if (LokiPoe.ClientWindowHandle != IntPtr.Zero)
                    {
                        DreamPoeBot.Loki.Game.Interop
                            .SetForegroundWindow(
                                LokiPoe.ClientWindowHandle);
                        focusSent = true;
                        await LokiCoroutine.Sleep(80);
                        LokiPoe.Input.SimulateKeyEvent(
                            System.Windows.Forms.Keys.Space,
                            true,
                            false,
                            true);
                        inputSent = true;
                    }
                    else
                    {
                        inputReason = "SpaceClientUnavailable";
                    }
                }
                catch (Exception exception)
                {
                    inputReason = "Space" +
                        exception.GetType().Name;
                    AllflameLog.Info(
                        "VOYAGE_PLANNER_CLOSE_INPUT_FAILED" +
                        "|Reason=" + (reason ?? String.Empty) +
                        "|Attempt=" + attempt + "/" +
                        MaximumVoyagePlannerCloseAttempts +
                        "|Exception=" + exception.GetType().Name +
                        "|Message=" +
                        (exception.Message ?? String.Empty)
                            .Replace("|", "/"));
                }

                await LokiCoroutine.Sleep(
                    (int)VoyagePlannerCloseVerificationDelay.TotalMilliseconds);
                string verificationSource;
                bool stillOpen =
                    IsVoyagePlannerOpenFresh(out verificationSource);
                bool closed = !stillOpen;
                AllflameLog.Info(
                    "VOYAGE_PLANNER_CLOSE" +
                    "|Reason=" + (reason ?? String.Empty) +
                    "|Attempt=" + attempt + "/" +
                    MaximumVoyagePlannerCloseAttempts +
                    "|Mode=" + inputReason +
                    "|FocusSent=" + focusSent +
                    "|InputSent=" + inputSent +
                    "|Postcondition=" + closed +
                    "|Source=" + verificationSource);
                if (closed)
                {
                    _plannerOpenTargetOverrideActive = false;
                    AllflameProgressWatchdog.MarkProgress(
                        "VoyagePlannerClosed");
                    return true;
                }

                if (attempt < MaximumVoyagePlannerCloseAttempts)
                {
                    await LokiCoroutine.Sleep(120);
                }
            }

            AllflameLog.Info(
                "VOYAGE_PLANNER_CLOSE_FAILED" +
                "|Reason=" + (reason ?? String.Empty) +
                "|Attempts=" + MaximumVoyagePlannerCloseAttempts +
                "|Action=HoldVoyageTaskAndRetry");
            return false;
        }

        private void ResetNativePlannerActionState()
        {
            _nativeClearPending = false;
            _nativeClearFallbackUsed = false;
            _nativeClearIssuedUtc = DateTime.MinValue;
            _nativeBeginPending = false;
            _nativeBeginFallbackUsed = false;
            _nativeBeginIssuedUtc = DateTime.MinValue;
        }

        private async Task<bool> RunIncrementalVisualVoyagePlanner(
            AllflameSettings settings,
            VoyagePlanningUi.VoyageVisualSnapshot snapshot)
        {
            int available = snapshot.AvailableChartCount;
            if (!_stablePlacementActive)
            {
                _stablePlacementActive = true;
                _stablePlacementBaselineAvailable = available;
                _stablePlacementConfirmed = 0;
                _stablePlacementFailures = 0;
                AllflameLog.Info(
                    "VOYAGE_PLACEMENT_SESSION" +
                    "|State=Started" +
                    "|Available=" + available +
                    "|Board=Unknown" +
                    "|Target=9" +
                    "|Mode=OneActionPerCycle" +
                    "|Detection=VisualFallback");
            }

            if (_stablePlacementAwaitingVerification)
            {
                bool moved =
                    available < _stablePlacementBeforeAvailable;
                if (moved)
                {
                    _stablePlacementConfirmed = Math.Min(
                        9,
                        _stablePlacementBaselineAvailable - available);
                    _stablePlacementAwaitingVerification = false;
                    _stablePlacementFailures = 0;
                    AllflameProgressWatchdog.MarkProgress(
                        "VoyageChartPlaced");
                    AllflameLog.Info(
                        "VOYAGE_CHART_MOVE_CONFIRMED" +
                        "|BeforeAvailable=" +
                        _stablePlacementBeforeAvailable +
                        "|AfterAvailable=" + available +
                        "|Placed=" + _stablePlacementConfirmed + "/9" +
                        "|Detection=VisualFallback");
                }
                else if (DateTime.UtcNow - _stablePlacementIssuedUtc <
                    TimeSpan.FromMilliseconds(900))
                {
                    return true;
                }
                else
                {
                    _stablePlacementAwaitingVerification = false;
                    _stablePlacementFailures++;
                    if (_stablePlacementFailures >= 3)
                    {
                        ResetStablePlacement();
                        _stage = 0;
                    }
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(250);
                    return true;
                }
            }

            if (_stablePlacementConfirmed >= 9)
            {
                bool enabled = snapshot.BeginVoyageEnabled ||
                    VoyagePlanningUi.IsBeginVoyageEnabledAt(
                        snapshot.BeginVoyageLocation,
                        snapshot.Scale);
                if (!enabled)
                {
                    _stablePlacementFailures++;
                    if (_stablePlacementFailures >= 3)
                    {
                        ResetStablePlacement();
                        _stage = 0;
                    }
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(250);
                    return true;
                }
                if (!settings.StartVoyageWhenReady)
                {
                    _manualReady = true;
                    return true;
                }
                bool beginClicked = VoyagePlanningUi.ClickClient(
                    snapshot.BeginVoyageLocation);
                AllflameLog.Info(
                    "VOYAGE_BEGIN|Mode=IncrementalFallback" +
                    "|Clicked=" + beginClicked +
                    "|BoardCharts=9" +
                    "|OneActionPerCycle=True");
                if (beginClicked)
                {
                    AllflameRunState.MarkVoyageStarted();
                    ResetStablePlacement();
                    _stage = 0;
                    _planningReadyAtOpen = false;
                    _plannerOpenTargetOverrideActive = false;
                }
                else
                {
                    _stablePlacementFailures++;
                    if (_stablePlacementFailures >= 3)
                    {
                        ResetStablePlacement();
                        _stage = 0;
                    }
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(350);
                }
                return true;
            }

            bool inputSent = false;
            Vector2i location = new Vector2i();
            _stablePlacementBeforeAvailable = available;
            if (snapshot.ChartLocations.Count > 0)
            {
                location = snapshot.ChartLocations[0];
                inputSent = await VoyagePlanningUi.CtrlClickClient(
                    location);
            }

            _stablePlacementIssuedUtc = DateTime.UtcNow;
            _stablePlacementAwaitingVerification = inputSent;
            _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(100);
            AllflameLog.Info(
                "VOYAGE_CHART_MOVE_ISSUED" +
                "|Placement=" +
                (_stablePlacementConfirmed + 1) + "/9" +
                "|BeforeAvailable=" + available +
                "|Client=" + location +
                "|InputSent=" + inputSent +
                "|Detection=VisualFallback" +
                "|Action=ReturnToTaskManager");
            if (!inputSent)
            {
                _stablePlacementFailures++;
            }
            return true;
        }

        private static string FindVoyageDialogOption()
        {
            try
            {
                var entries =
                    LokiPoe.InGameState.NpcDialogUi.DialogEntries;
                if (entries != null)
                {
                    foreach (var entry in entries)
                    {
                        if (entry == null ||
                            !entry.IsDialogChoice)
                        {
                            continue;
                        }

                        string text =
                            (entry.Text ?? String.Empty).Trim();
                        if (IsVoyageDialogueText(text))
                        {
                            return text;
                        }
                    }
                }
            }
            catch
            {
            }

            try
            {
                var entries =
                    LokiPoe.InGameState.NpcDialogUi.DialogEntries2;
                if (entries != null)
                {
                    foreach (var entry in entries)
                    {
                        if (entry == null ||
                            !entry.IsDialogChoice)
                        {
                            continue;
                        }

                        string text =
                            (entry.Text ?? String.Empty).Trim();
                        if (IsVoyageDialogueText(text))
                        {
                            return text;
                        }
                    }
                }
            }
            catch
            {
            }

            // Known variants are retained as a fallback for DPB builds whose
            // DialogEntries collection temporarily returns no elements.
            string[] knownOptions =
            {
                "Plan Voyage",
                "Plan your Voyage"
            };
            foreach (string option in knownOptions)
            {
                try
                {
                    if (LokiPoe.InGameState.NpcDialogUi.CanConverse(
                        option))
                    {
                        return option;
                    }
                }
                catch
                {
                }
            }
            return String.Empty;
        }

        private static bool IsVoyageDialogueText(string text)
        {
            return
                !String.IsNullOrWhiteSpace(text) &&
                text.IndexOf(
                    "plan",
                    StringComparison.OrdinalIgnoreCase) >= 0 &&
                text.IndexOf(
                    "voyage",
                    StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static string GetDialogEntrySummary()
        {
            var output = new List<string>();
            try
            {
                var entries =
                    LokiPoe.InGameState.NpcDialogUi.DialogEntries;
                if (entries != null)
                {
                    output.AddRange(
                        entries
                            .Where(entry => entry != null)
                            .Select(entry =>
                                (entry.Text ?? String.Empty)
                                    .Replace("|", "/")
                                    .Replace("\r", " ")
                                    .Replace("\n", " "))
                            .Where(text =>
                                !String.IsNullOrWhiteSpace(text)));
                }
            }
            catch
            {
            }

            try
            {
                var entries =
                    LokiPoe.InGameState.NpcDialogUi.DialogEntries2;
                if (entries != null)
                {
                    output.AddRange(
                        entries
                            .Where(entry => entry != null)
                            .Select(entry =>
                                (entry.Text ?? String.Empty)
                                    .Replace("|", "/")
                                    .Replace("\r", " ")
                                    .Replace("\n", " "))
                            .Where(text =>
                                !String.IsNullOrWhiteSpace(text)));
                }
            }
            catch
            {
            }

            return output.Count == 0
                ? "<none>"
                : String.Join(
                    ",",
                    output.Distinct(
                        StringComparer.OrdinalIgnoreCase));
        }
    }

