        private static void ValidateTemplateSize(
            string name,
            byte[] template,
            int expectedSize)
        {
            if (template.Length != expectedSize)
            {
                string msg = string.Format(
                    "TEMPLATE_SIZE_MISMATCH|{0}|Expected={1}|Actual={2}|Diff={3}",
                    name,
                    expectedSize,
                    template.Length,
                    expectedSize - template.Length);
                AllflameLog.Error(msg, new InvalidOperationException(msg));
            }
        }

