        public static bool IsOpen()
        {
            DeepwaterVoyageSnapshot nativeSnapshot;
            if (NativeDeepwaterVoyageUi.TryCapture(
                    out nativeSnapshot) &&
                nativeSnapshot.IsOpened)
            {
                return true;
            }
            StableVoyageSnapshot stable;
            if (TryResolveStable(out stable))
            {
                return true;
            }
            VoyageVisualSnapshot snapshot;
            return TryAnalyze(out snapshot, false);
        }

        public static bool TryResolveStable(
            out StableVoyageSnapshot snapshot)
        {
            snapshot = null;
            List<Element> roots;
            try
            {
                roots = LokiPoe.GetGuiElements();
            }
            catch
            {
                return false;
            }
            if (roots == null)
            {
                return false;
            }

            for (int rootIndex = 0;
                 rootIndex < roots.Count;
                 rootIndex++)
            {
                Element window = roots[rootIndex];
                if (!IsStableVisible(window) ||
                    !String.Equals(
                        SafeStableIdLabel(window),
                        StableWindowId,
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                Element content = GetStableChild(window, 3);
                Element inventoryRegion = GetStableChild(content, 0);
                Element boardRegion = GetStableChild(content, 1);
                Element beginButton = FindStableButton(
                    GetStableChild(content, 2),
                    "begin voyage");
                Element clearButton = FindStableButton(
                    GetStableChild(content, 3),
                    "clear board");

                if (inventoryRegion == null ||
                    SafeStableChildren(inventoryRegion).Count != 60)
                {
                    inventoryRegion =
                        FindStableRegionByChildCount(window, 60);
                }
                if (boardRegion == null ||
                    SafeStableChildren(boardRegion).Count != 9)
                {
                    boardRegion =
                        FindStableRegionByChildCount(window, 9);
                }
                if (beginButton == null)
                {
                    beginButton =
                        FindStableButton(window, "begin voyage");
                }
                if (clearButton == null)
                {
                    clearButton =
                        FindStableButton(window, "clear board");
                }
                if (inventoryRegion == null ||
                    boardRegion == null ||
                    beginButton == null ||
                    clearButton == null)
                {
                    AllflameLog.Throttled(
                        "voyage_stable_incomplete",
                        TimeSpan.FromSeconds(2),
                        "VOYAGE_UI_STABLE" +
                        "|Resolved=False" +
                        "|RootIndex=" + rootIndex +
                        "|Inventory=" +
                        (inventoryRegion != null) +
                        "|Board=" + (boardRegion != null) +
                        "|Begin=" + (beginButton != null) +
                        "|Clear=" + (clearButton != null));
                    return false;
                }

                var resolved = new StableVoyageSnapshot
                {
                    Window = window,
                    InventoryRegion = inventoryRegion,
                    BeginVoyageButton = beginButton,
                    ClearBoardButton = clearButton,
                    RootIndex = rootIndex
                };
                List<Element> inventorySlots =
                    SafeStableChildren(inventoryRegion);
                resolved.InventorySlotCount = inventorySlots.Count;
                for (int slotIndex = 0;
                     slotIndex < inventorySlots.Count;
                     slotIndex++)
                {
                    Element slot = inventorySlots[slotIndex];
                    if (ContainsStableLevelLabel(slot))
                    {
                        resolved.AvailableChartSlots.Add(
                            new StableChartSlot
                            {
                                Element = slot,
                                Index = slotIndex
                            });
                    }
                }
                List<Element> boardSlots =
                    SafeStableChildren(boardRegion);
                resolved.BoardSlotCount = boardSlots.Count;
                resolved.BoardChartCount =
                    boardSlots.Count(ContainsStableLevelLabel);
                snapshot = resolved;
                AllflameLog.Throttled(
                    "voyage_stable_resolved",
                    TimeSpan.FromSeconds(2),
                    "VOYAGE_UI_STABLE" +
                    "|Resolved=True" +
                    "|IdLabel=" + StableWindowId +
                    "|RootIndex=" + rootIndex +
                    "|WindowAddress=0x" +
                    window.Address.ToString("X") +
                    "|InventorySlots=" +
                    resolved.InventorySlotCount +
                    "|AvailableCharts=" +
                    resolved.AvailableChartSlots.Count +
                    "|BoardSlots=" + resolved.BoardSlotCount +
                    "|BoardCharts=" + resolved.BoardChartCount +
                    "|BeginEnabled=" +
                    resolved.BeginVoyageEnabled);
                return true;
            }
            return false;
        }

        public static bool ClickStableElement(
            Element element,
            string action)
        {
            if (!IsStableVisible(element))
            {
                return false;
            }
            Vector2i location;
            try
            {
                location = element.CenterClickLocation();
            }
            catch
            {
                return false;
            }
            bool clicked = ClickClient(location);
            AllflameLog.Info(
                "VOYAGE_UI_ELEMENT_CLICK" +
                "|Action=" + (action ?? String.Empty) +
                "|Address=0x" + element.Address.ToString("X") +
                "|Client=" + location +
                "|Enabled=" + SafeStableEnabled(element) +
                "|Clicked=" + clicked);
            return clicked;
        }

        public static async Task<bool> CtrlClickStableChartSlot(
            StableVoyageSnapshot snapshot,
            StableChartSlot chartSlot,
            int placementIndex)
        {
            if (snapshot == null ||
                chartSlot == null ||
                !IsStableVisible(chartSlot.Element) ||
                !ContainsStableLevelLabel(chartSlot.Element))
            {
                return false;
            }
            Vector2i location;
            string coordinateMode;
            string rejectionReason;
            if (!TryResolveStableChartLocation(
                    snapshot,
                    chartSlot.Index,
                    out location,
                    out coordinateMode,
                    out rejectionReason))
            {
                AllflameLog.Info(
                    "VOYAGE_CHART_SLOT_REJECTED" +
                    "|Placement=" + (placementIndex + 1) + "/9" +
                    "|InventoryIndex=" + chartSlot.Index +
                    "|Reason=" + rejectionReason +
                    "|Action=UseVisualFallback");
                VoyageVisualSnapshot visual;
                if (!TryAnalyze(out visual, true) ||
                    visual.ChartLocations == null ||
                    visual.ChartLocations.Count == 0)
                {
                    return false;
                }
                location = visual.ChartLocations[0];
                if (!IsClientLocationValid(location))
                {
                    AllflameLog.Info(
                        "VOYAGE_CHART_SLOT_REJECTED" +
                        "|Placement=" +
                        (placementIndex + 1) + "/9" +
                        "|InventoryIndex=" + chartSlot.Index +
                        "|Reason=VisualOutsideClient:" + location +
                        "|Action=AbortClick");
                    return false;
                }
                coordinateMode = "VisualFallback";
            }
            bool inputSent = await CtrlClickClient(location);
            AllflameLog.Info(
                "VOYAGE_CHART_SLOT_CTRL_CLICK" +
                "|Placement=" + (placementIndex + 1) + "/9" +
                "|InventoryIndex=" + chartSlot.Index +
                "|Address=0x" +
                chartSlot.Element.Address.ToString("X") +
                "|Client=" + location +
                "|CoordinateMode=" + coordinateMode +
                "|InputSent=" + inputSent +
                "|Confirmed=False");
            return inputSent;
        }

        public static bool TryCreateStableChartBatchPlan(
            StableVoyageSnapshot snapshot,
            int maximumCharts,
            out StableChartBatchPlan plan,
            out string rejectionReason)
        {
            plan = null;
            rejectionReason = String.Empty;
            if (snapshot == null ||
                snapshot.Window == null ||
                snapshot.InventoryRegion == null ||
                snapshot.AvailableChartSlots.Count == 0)
            {
                rejectionReason = "StableSnapshotUnavailable";
                return false;
            }

            var candidate = new StableChartBatchPlan
            {
                AreaHash = AllflameContext.AreaHash,
                RootIndex = snapshot.RootIndex,
                Window = snapshot.Window,
                InventoryRegion = snapshot.InventoryRegion,
                WindowAddress = snapshot.Window.Address,
                InventoryAddress = snapshot.InventoryRegion.Address,
                InitialAvailable = snapshot.AvailableChartSlots.Count,
                InitialBoard = snapshot.BoardChartCount
            };
            int count = Math.Min(
                Math.Max(0, maximumCharts),
                snapshot.AvailableChartSlots.Count);
            for (int index = 0; index < count; index++)
            {
                StableChartSlot slot =
                    snapshot.AvailableChartSlots[index];
                Vector2i location;
                string coordinateMode;
                string slotRejection;
                if (!TryResolveStableChartLocation(
                        snapshot,
                        slot.Index,
                        out location,
                        out coordinateMode,
                        out slotRejection))
                {
                    rejectionReason =
                        "Slot" + slot.Index + ":" + slotRejection;
                    return false;
                }
                candidate.Entries.Add(
                    new StableChartBatchEntry
                    {
                        InventoryIndex = slot.Index,
                        ElementAddress = slot.Element.Address,
                        ClientLocation = location,
                        CoordinateMode = coordinateMode
                    });
            }
            if (candidate.Entries.Count == 0)
            {
                rejectionReason = "NoBatchEntries";
                return false;
            }
            plan = candidate;
            AllflameLog.Info(
                "VOYAGE_CHART_BATCH_PLAN" +
                "|AreaHash=" + plan.AreaHash +
                "|RootIndex=" + plan.RootIndex +
                "|WindowAddress=0x" +
                plan.WindowAddress.ToString("X") +
                "|InventoryAddress=0x" +
                plan.InventoryAddress.ToString("X") +
                "|Available=" + plan.InitialAvailable +
                "|Board=" + plan.InitialBoard +
                "|Clicks=" + plan.Entries.Count);
            return true;
        }

        public static async Task<int> CtrlClickStableChartBatch(
            StableChartBatchPlan plan,
            int startIndex,
            int count)
        {
            if (plan == null ||
                startIndex < 0 ||
                startIndex >= plan.Entries.Count ||
                count <= 0)
            {
                return 0;
            }
            int endIndex = Math.Min(
                plan.Entries.Count,
                startIndex + count);
            int sent = 0;
            bool controlDown = false;
            try
            {
                LokiPoe.ProcessHookManager.ClearAllKeyStates();
                LokiPoe.ProcessHookManager.SetKeyState(
                    System.Windows.Forms.Keys.ControlKey,
                    short.MinValue,
                    System.Windows.Forms.Keys.None);
                controlDown = true;
                await LokiCoroutine.Sleep(20);
                for (int index = startIndex;
                     index < endIndex;
                     index++)
                {
                    if (!IsStableBatchContextValid(plan))
                    {
                        AllflameLog.Info(
                            "VOYAGE_CHART_BATCH_FALLBACK" +
                            "|Reason=ContextChanged" +
                            "|Sent=" + sent +
                            "|Action=AbortCachedClicks");
                        break;
                    }
                    StableChartBatchEntry entry = plan.Entries[index];
                    DreamPoeBot.BotFramework.MouseManager
                        .SetMousePosition(entry.ClientLocation, false);
                    await LokiCoroutine.Sleep(12);
                    DreamPoeBot.BotFramework.MouseManager.ClickLMB(0, 0);
                    sent++;
                    AllflameLog.Info(
                        "VOYAGE_CHART_BATCH_CLICK" +
                        "|Placement=" + (index + 1) + "/" +
                        plan.Entries.Count +
                        "|InventoryIndex=" + entry.InventoryIndex +
                        "|Address=0x" +
                        entry.ElementAddress.ToString("X") +
                        "|Client=" + entry.ClientLocation +
                        "|CoordinateMode=" + entry.CoordinateMode +
                        "|InputSent=True");
                    await LokiCoroutine.Sleep(45);
                }
            }
            catch (Exception exception)
            {
                AllflameLog.Info(
                    "VOYAGE_CHART_BATCH_FALLBACK" +
                    "|Reason=" + exception.GetType().Name +
                    "|Message=" +
                    (exception.Message ?? String.Empty).Replace("|", "/") +
                    "|Sent=" + sent);
            }
            finally
            {
                if (controlDown)
                {
                    LokiPoe.ProcessHookManager.SetKeyState(
                        System.Windows.Forms.Keys.ControlKey,
                        (short)0,
                        System.Windows.Forms.Keys.None);
                }
                LokiPoe.ProcessHookManager.ClearAllKeyStates();
            }
            return sent;
        }

        public static bool StableSnapshotMatchesBatch(
            StableVoyageSnapshot snapshot,
            StableChartBatchPlan plan)
        {
            return snapshot != null &&
                   plan != null &&
                   AllflameContext.AreaHash == plan.AreaHash &&
                   snapshot.RootIndex == plan.RootIndex &&
                   snapshot.Window != null &&
                   snapshot.Window.Address == plan.WindowAddress &&
                   snapshot.InventoryRegion != null &&
                   snapshot.InventoryRegion.Address == plan.InventoryAddress;
        }

        private static bool IsStableBatchContextValid(
            StableChartBatchPlan plan)
        {
            try
            {
                return plan != null &&
                       LokiPoe.IsInGame &&
                       AllflameContext.AreaHash == plan.AreaHash &&
                       IsStableVisible(plan.Window) &&
                       plan.Window.Address == plan.WindowAddress &&
                       IsStableVisible(plan.InventoryRegion) &&
                       plan.InventoryRegion.Address == plan.InventoryAddress;
            }
            catch
            {
                return false;
            }
        }

        private static bool TryResolveStableChartLocation(
            StableVoyageSnapshot snapshot,
            int inventoryIndex,
            out Vector2i location,
            out string mode,
            out string rejectionReason)
        {
            location = new Vector2i();
            mode = "Unavailable";
            rejectionReason = String.Empty;
            if (snapshot.InventoryRegion == null ||
                inventoryIndex < 0 ||
                inventoryIndex >= 60)
            {
                rejectionReason = "InvalidStableSlot";
                return false;
            }

            try
            {
                var slotUi = new InventorySlotUiElement(
                    snapshot.InventoryRegion.Address,
                    StashType.NormalStash);
                if (slotUi == null ||
                    !slotUi.IsValid ||
                    !slotUi.IsVisible)
                {
                    rejectionReason = "InventorySlotUiUnavailable";
                    return false;
                }

                const int columns = 6;
                const int rows = 10;
                if (slotUi.Size.X != columns ||
                    slotUi.Size.Y != rows)
                {
                    rejectionReason =
                        "UnexpectedGridSize:" + slotUi.Size;
                    return false;
                }
                int column = inventoryIndex % columns;
                int row = inventoryIndex / columns;
                location = slotUi.SlotClickLocation(
                    new Vector2i(column + 1, row + 1));
                if (!IsClientLocationValid(location))
                {
                    rejectionReason =
                        "OutsideClient:" + location;
                    return false;
                }

                mode = "InventorySlotUiElement";
                AllflameLog.Throttled(
                    "voyage_chart_grid_geometry",
                    TimeSpan.FromSeconds(2),
                    "VOYAGE_CHART_GRID" +
                    "|InventoryAddress=0x" +
                    snapshot.InventoryRegion.Address.ToString("X") +
                    "|GridSize=" + slotUi.Size +
                    "|GridTopLeft=" + slotUi.LocationTopLeft +
                    "|Index=" + inventoryIndex +
                    "|Column=" + column +
                    "|Row=" + row +
                    "|Client=" + location +
                    "|Mode=" + mode);
                return true;
            }
            catch (Exception exception)
            {
                rejectionReason =
                    exception.GetType().Name + ":" +
                    exception.Message.Replace("|", "/");
                return false;
            }
        }

        private static bool IsClientLocationValid(Vector2i location)
        {
            try
            {
                var client = LokiPoe.ClientWindowInfo.Client;
                int width = client.Right - client.Left;
                int height = client.Bottom - client.Top;
                if (width <= 0 || height <= 0)
                {
                    return false;
                }
                bool clientRelative =
                    location.X >= 0 &&
                    location.X < width &&
                    location.Y >= 0 &&
                    location.Y < height;
                bool screenRelative =
                    location.X >= client.Left &&
                    location.X < client.Right &&
                    location.Y >= client.Top &&
                    location.Y < client.Bottom;
                return clientRelative || screenRelative;
            }
            catch
            {
                return false;
            }
        }

        private static Element FindStableRegionByChildCount(
            Element root,
            int expectedChildren)
        {
            int visited = 0;
            return FindStableRegionByChildCount(
                root,
                expectedChildren,
                0,
                ref visited);
        }

        private static Element FindStableRegionByChildCount(
            Element element,
            int expectedChildren,
            int depth,
            ref int visited)
        {
            if (element == null ||
                depth > 12 ||
                visited >= MaximumStableWindowVisited)
            {
                return null;
            }
            visited++;
            List<Element> children = SafeStableChildren(element);
            if (IsStableVisible(element) &&
                children.Count == expectedChildren)
            {
                return element;
            }
            foreach (Element child in children)
            {
                Element found = FindStableRegionByChildCount(
                    child,
                    expectedChildren,
                    depth + 1,
                    ref visited);
                if (found != null)
                {
                    return found;
                }
            }
            return null;
        }

        private static Element FindStableButton(
            Element root,
            string caption)
        {
            int visited = 0;
            return FindStableButton(root, caption, 0, ref visited);
        }

        private static Element FindStableButton(
            Element element,
            string caption,
            int depth,
            ref int visited)
        {
            if (element == null ||
                depth > 8 ||
                visited >= MaximumStableWindowVisited)
            {
                return null;
            }
            visited++;
            if (IsStableVisible(element) &&
                SafeStableText(element).IndexOf(
                    caption,
                    StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return element;
            }
            foreach (Element child in SafeStableChildren(element))
            {
                Element found = FindStableButton(
                    child,
                    caption,
                    depth + 1,
                    ref visited);
                if (found != null)
                {
                    return found;
                }
            }
            return null;
        }

        private static bool ContainsStableLevelLabel(Element root)
        {
            int visited = 0;
            return ContainsStableLevelLabel(root, 0, ref visited);
        }

        private static bool ContainsStableLevelLabel(
            Element element,
            int depth,
            ref int visited)
        {
            if (element == null || depth > 5 || visited >= 24)
            {
                return false;
            }
            visited++;
            if (LevelLabel.IsMatch(SafeStableText(element)))
            {
                return true;
            }
            foreach (Element child in SafeStableChildren(element))
            {
                if (ContainsStableLevelLabel(
                        child,
                        depth + 1,
                        ref visited))
                {
                    return true;
                }
            }
            return false;
        }

        private static Element GetStableChild(
            Element element,
            int index)
        {
            List<Element> children = SafeStableChildren(element);
            return index >= 0 && index < children.Count
                ? children[index]
                : null;
        }

        private static bool IsStableVisible(Element element)
        {
            try
            {
                return element != null &&
                    element.IsValid &&
                    (element.IsVisible || element.IsVisibleLocal);
            }
            catch
            {
                return false;
            }
        }

        private static bool SafeStableEnabled(Element element)
        {
            try
            {
                return element != null && element.IsEnable;
            }
            catch
            {
                return false;
            }
        }

        private static string SafeStableIdLabel(Element element)
        {
            try
            {
                return element == null
                    ? String.Empty
                    : element.IdLabel ?? String.Empty;
            }
            catch
            {
                return String.Empty;
            }
        }

        private static string SafeStableText(Element element)
        {
            try
            {
                return element == null
                    ? String.Empty
                    : element.Text ?? String.Empty;
            }
            catch
            {
                return String.Empty;
            }
        }

        private static List<Element> SafeStableChildren(Element element)
        {
            try
            {
                return element == null || element.Children == null
                    ? new List<Element>()
                    : element.Children;
            }
            catch
            {
                return new List<Element>();
            }
        }

        public static void ArmExpectedOpen(TimeSpan duration)
        {
            _expectedOpenUntilUtc =
                DateTime.UtcNow.Add(
                    duration <= TimeSpan.Zero
                        ? TimeSpan.FromSeconds(8)
                        : duration);
            _nextVisualScanUtc = DateTime.MinValue;
            _cachedVisual = null;
        }

        public static bool TryAnalyze(
            out VoyageVisualSnapshot snapshot,
            bool force)
        {
            snapshot = null;
            if (!force &&
                DateTime.UtcNow < _nextVisualScanUtc)
            {
                snapshot = _cachedVisual;
                return snapshot != null;
            }

            _nextVisualScanUtc =
                DateTime.UtcNow.AddMilliseconds(300);
            _cachedVisual = null;

            try
            {
                var client = LokiPoe.ClientWindowInfo.Client;
                int width = client.Right - client.Left;
                int height = client.Bottom - client.Top;
                if (width < 700 || height < 500)
                {
                    AllflameLog.Throttled(
                        "voyage_visual_client_too_small",
                        TimeSpan.FromSeconds(2),
                        "VOYAGE_VISUAL|Open=False" +
                        "|Reason=ClientTooSmall" +
                        "|Client=" + width + "x" + height +
                        "|Minimum=700x500");
                    return false;
                }

                using (var screenshot =
                    new System.Drawing.Bitmap(
                        width,
                        height,
                        System.Drawing.Imaging.PixelFormat
                            .Format24bppRgb))
                {
                    using (System.Drawing.Graphics graphics =
                        System.Drawing.Graphics.FromImage(
                            screenshot))
                    {
                        graphics.CopyFromScreen(
                            client.Left,
                            client.Top,
                            0,
                            0,
                            new System.Drawing.Size(
                                width,
                                height),
                            System.Drawing.CopyPixelOperation
                                .SourceCopy);
                    }

                    var rectangle =
                        new System.Drawing.Rectangle(
                            0,
                            0,
                            width,
                            height);
                    System.Drawing.Imaging.BitmapData data =
                        screenshot.LockBits(
                            rectangle,
                            System.Drawing.Imaging.ImageLockMode
                                .ReadOnly,
                            System.Drawing.Imaging.PixelFormat
                                .Format24bppRgb);
                    try
                    {
                        int stride = Math.Abs(data.Stride);
                        byte[] pixels =
                            new byte[stride * height];
                        System.Runtime.InteropServices.Marshal.Copy(
                            data.Scan0,
                            pixels,
                            0,
                            pixels.Length);

                        int beginX;
                        int beginY;
                        double scale;
                        double correlation;
                        bool enabledTemplate;
                        if (!TryFindBeginButton(
                                pixels,
                                stride,
                                width,
                                height,
                                out beginX,
                                out beginY,
                                out scale,
                                out correlation,
                                out enabledTemplate))
                        {
                            AllflameLog.Throttled(
                                "voyage_visual_low_correlation",
                                TimeSpan.FromSeconds(2),
                                "VOYAGE_VISUAL|Open=False" +
                                "|BestCorrelation=" +
                                correlation.ToString("0.000") +
                                "|Required=" +
                                MinimumBeginCorrelation.ToString("0.000"));
                            return false;
                        }

                        var visual =
                            new VoyageVisualSnapshot();
                        visual.ButtonCorrelation = correlation;
                        visual.Scale = scale;
                        visual.BeginVoyageLocation =
                            new Vector2i(beginX, beginY);
                        visual.ClearBoardLocation =
                            new Vector2i(
                                beginX +
                                    (int)Math.Round(190 * scale),
                                beginY);
                        visual.BeginVoyageEnabled =
                            IsBeginButtonOrange(
                                pixels,
                                stride,
                                width,
                                height,
                                beginX,
                                beginY,
                                scale);

                        visual.ChartLocations =
                            FindChartMarkerCenters(
                                pixels,
                                stride,
                                width,
                                height,
                                beginX,
                                beginY,
                                scale);
                        visual.AvailableChartCount =
                            visual.ChartLocations.Count;

                        _cachedVisual = visual;
                        snapshot = visual;
                        AllflameLog.Throttled(
                            "voyage_visual_detected",
                            TimeSpan.FromSeconds(2),
                            "VOYAGE_VISUAL|Open=True" +
                            "|Begin=" +
                            visual.BeginVoyageLocation +
                            "|ButtonCorrelation=" +
                            correlation.ToString("0.000") +
                            "|Scale=" + scale.ToString("0.00") +
                            "|BeginEnabled=" +
                            visual.BeginVoyageEnabled +
                            "|Available=" +
                            visual.AvailableChartCount +
                            "|ShapeDetection=Disabled");
                        return true;
                    }
                    finally
                    {
                        screenshot.UnlockBits(data);
                    }
                }
            }
            catch (Exception exception)
            {
                AllflameLog.Throttled(
                    "voyage_visual_error",
                    TimeSpan.FromSeconds(3),
                    "VOYAGE_VISUAL|Open=False|Error=" +
                    exception.GetType().Name +
                    "|Message=" + exception.Message);
                return false;
            }
        }

        public static bool ClickClient(Vector2i location)
        {
            try
            {
                LokiPoe.ProcessHookManager.ClearAllKeyStates();
                DreamPoeBot.BotFramework.MouseManager
                    .SetMousePosition(location, false);
                DreamPoeBot.BotFramework.MouseManager
                    .ClickLMB(0, 0);
                return true;
            }
            catch (Exception exception)
            {
                AllflameLog.Info(
                    "VOYAGE_UI_CLICK_FAILED|Client=" +
                    location +
                    "|Error=" +
                    exception.GetType().Name +
                    "|Message=" + exception.Message);
                return false;
            }
        }

        public static bool IsBeginVoyageEnabledAt(
            Vector2i location,
            double scale)
        {
            try
            {
                var client = LokiPoe.ClientWindowInfo.Client;
                int width = client.Right - client.Left;
                int height = client.Bottom - client.Top;
                if (width < 700 ||
                    height < 500 ||
                    location.X < 0 ||
                    location.X >= width ||
                    location.Y < 0 ||
                    location.Y >= height)
                {
                    return false;
                }

                using (var screenshot =
                    new System.Drawing.Bitmap(
                        width,
                        height,
                        System.Drawing.Imaging.PixelFormat
                            .Format24bppRgb))
                {
                    using (System.Drawing.Graphics graphics =
                        System.Drawing.Graphics.FromImage(screenshot))
                    {
                        graphics.CopyFromScreen(
                            client.Left,
                            client.Top,
                            0,
                            0,
                            new System.Drawing.Size(width, height),
                            System.Drawing.CopyPixelOperation.SourceCopy);
                    }

                    var rectangle =
                        new System.Drawing.Rectangle(
                            0,
                            0,
                            width,
                            height);
                    System.Drawing.Imaging.BitmapData data =
                        screenshot.LockBits(
                            rectangle,
                            System.Drawing.Imaging.ImageLockMode.ReadOnly,
                            System.Drawing.Imaging.PixelFormat
                                .Format24bppRgb);
                    try
                    {
                        int stride = Math.Abs(data.Stride);
                        byte[] pixels = new byte[stride * height];
                        System.Runtime.InteropServices.Marshal.Copy(
                            data.Scan0,
                            pixels,
                            0,
                            pixels.Length);
                        bool enabled = IsBeginButtonOrange(
                            pixels,
                            stride,
                            width,
                            height,
                            location.X,
                            location.Y,
                            scale);
                        AllflameLog.Throttled(
                            "voyage_begin_state",
                            TimeSpan.FromSeconds(2),
                            "VOYAGE_BEGIN_STATE|Enabled=" +
                            enabled +
                            "|Client=" + location);
                        return enabled;
                    }
                    finally
                    {
                        screenshot.UnlockBits(data);
                    }
                }
            }
            catch (Exception exception)
            {
                AllflameLog.Throttled(
                    "voyage_begin_anchor_error",
                    TimeSpan.FromSeconds(3),
                    "VOYAGE_BEGIN_ANCHOR|Enabled=False" +
                    "|Client=" + location +
                    "|Error=" + exception.GetType().Name +
                    "|Message=" + exception.Message);
                return false;
            }
        }

        public static async Task<bool> CtrlClickClient(
            Vector2i location)
        {
            bool controlDown = false;
            try
            {
                LokiPoe.ProcessHookManager.ClearAllKeyStates();
                DreamPoeBot.BotFramework.MouseManager
                    .SetMousePosition(location, false);
                await LokiCoroutine.Sleep(20);
                LokiPoe.ProcessHookManager.SetKeyState(
                    System.Windows.Forms.Keys.ControlKey,
                    short.MinValue,
                    System.Windows.Forms.Keys.None);
                controlDown = true;
                await LokiCoroutine.Sleep(25);
                DreamPoeBot.BotFramework.MouseManager
                    .ClickLMB(0, 0);
                await LokiCoroutine.Sleep(80);
                AllflameLog.Info(
                    "VOYAGE_CHART_CTRL_CLICK|Client=" +
                    location);
                return true;
            }
            catch (Exception exception)
            {
                AllflameLog.Info(
                    "VOYAGE_CTRL_CLICK_FAILED|Client=" +
                    location +
                    "|Error=" +
                    exception.GetType().Name +
                    "|Message=" + exception.Message);
                return false;
            }
            finally
            {
                if (controlDown)
                {
                    LokiPoe.ProcessHookManager.SetKeyState(
                        System.Windows.Forms.Keys.ControlKey,
                        (short)0,
                        System.Windows.Forms.Keys.None);
                }
            }
        }

        private static bool TryFindBeginButton(
            byte[] pixels,
            int stride,
            int width,
            int height,
            out int bestCenterX,
            out int bestCenterY,
            out double bestScale,
            out double bestCorrelation,
            out bool bestEnabledTemplate)
        {
            bestCenterX = (int)(width * 0.43);
            bestCenterY = (int)(height * 0.83);
            bestScale = 1.0;
            bestCorrelation = -1.0;
            bestEnabledTemplate = false;
            // PoE scales this UI down heavily in a compact/windowed client.
            // The test recording renders Begin Voyage at roughly 85x20px,
            // versus the 164x38 reference template.
            double[] scales =
                {
                    0.48, 0.52, 0.56, 0.60, 0.66, 0.74,
                    0.84, 0.92, 1.0, 1.08, 1.16, 1.24
                };
            int searchLeft = (int)(width * 0.27);
            int searchRight = (int)(width * 0.59);
            int searchTop = (int)(height * 0.58);
            int searchBottom = height - 12;

            foreach (double scale in scales)
            {
                int candidateWidth =
                    Math.Max(
                        72,
                        (int)Math.Round(164 * scale));
                int disabledHeight =
                    Math.Max(
                        16,
                        (int)Math.Round(38 * scale));
                int enabledHeight =
                    Math.Max(
                        17,
                        (int)Math.Round(42 * scale));
                int halfWidth = candidateWidth / 2;
                int maxHalfHeight =
                    Math.Max(
                        disabledHeight,
                        enabledHeight) / 2;
                int minX = Math.Max(
                    halfWidth,
                    searchLeft);
                int maxX = Math.Min(
                    width - halfWidth - 1,
                    searchRight);
                int minY = Math.Max(
                    maxHalfHeight,
                    searchTop);
                int maxY = Math.Min(
                    height - maxHalfHeight - 1,
                    searchBottom);

                for (int centerY = minY;
                     centerY <= maxY;
                     centerY += 5)
                {
                    for (int centerX = minX;
                         centerX <= maxX;
                         centerX += 5)
                    {
                        double disabled =
                            CalculateImageCorrelation(
                                pixels,
                                stride,
                                width,
                                height,
                                centerX - halfWidth,
                                centerY - disabledHeight / 2,
                                candidateWidth,
                                disabledHeight,
                                BeginDisabledTemplate,
                                BeginTemplateWidth,
                                BeginTemplateHeight,
                                BeginDisabledTemplateMean,
                                BeginDisabledTemplateEnergy);
                        disabled = Math.Max(
                            disabled,
                            CalculateImageCorrelation(
                                pixels,
                                stride,
                                width,
                                height,
                                centerX - halfWidth,
                                centerY - disabledHeight / 2,
                                candidateWidth,
                                disabledHeight,
                                BeginDisabled800Template,
                                BeginTemplateWidth,
                                BeginTemplateHeight,
                                BeginDisabled800TemplateMean,
                                BeginDisabled800TemplateEnergy));
                        if (disabled > bestCorrelation &&
                            IsBeginButtonOrange(
                                pixels,
                                stride,
                                width,
                                height,
                                centerX +
                                    (int)Math.Round(
                                        190 * scale),
                                centerY,
                                scale))
                        {
                            bestCorrelation = disabled;
                            bestCenterX = centerX;
                            bestCenterY = centerY;
                            bestScale = scale;
                            bestEnabledTemplate = false;
                        }

                        double enabled =
                            CalculateImageCorrelation(
                                pixels,
                                stride,
                                width,
                                height,
                                centerX - halfWidth,
                                centerY - enabledHeight / 2,
                                candidateWidth,
                                enabledHeight,
                                BeginEnabledTemplate,
                                BeginTemplateWidth,
                                BeginTemplateHeight,
                                BeginEnabledTemplateMean,
                                BeginEnabledTemplateEnergy);
                        enabled = Math.Max(
                            enabled,
                            CalculateImageCorrelation(
                                pixels,
                                stride,
                                width,
                                height,
                                centerX - halfWidth,
                                centerY - enabledHeight / 2,
                                candidateWidth,
                                enabledHeight,
                                BeginEnabled800Template,
                                BeginTemplateWidth,
                                BeginTemplateHeight,
                                BeginEnabled800TemplateMean,
                                BeginEnabled800TemplateEnergy));
                        if (enabled > bestCorrelation &&
                            IsBeginButtonOrange(
                                pixels,
                                stride,
                                width,
                                height,
                                centerX +
                                    (int)Math.Round(
                                        190 * scale),
                                centerY,
                                scale))
                        {
                            bestCorrelation = enabled;
                            bestCenterX = centerX;
                            bestCenterY = centerY;
                            bestScale = scale;
                            bestEnabledTemplate = true;
                        }
                    }
                }
            }

            double requiredCorrelation =
                DateTime.UtcNow < _expectedOpenUntilUtc
                    ? 0.35
                    : MinimumBeginCorrelation;
            if (bestCorrelation < requiredCorrelation)
            {
                AllflameLog.Throttled(
                    "voyage_begin_not_detected",
                    TimeSpan.FromSeconds(2),
                    "VOYAGE_VISUAL|Open=False" +
                    "|BestBeginCorrelation=" +
                    bestCorrelation.ToString("0.000") +
                    "|RequiredCorrelation=" +
                    requiredCorrelation.ToString("0.000") +
                    "|DialogueExpected=" +
                    (DateTime.UtcNow < _expectedOpenUntilUtc));
                return false;
            }
            return true;
        }

        private static bool IsBeginButtonOrange(
            byte[] pixels,
            int stride,
            int imageWidth,
            int imageHeight,
            int centerX,
            int centerY,
            double scale)
        {
            int sampleWidth =
                Math.Max(
                    58,
                    (int)Math.Round(150 * scale));
            int sampleHeight =
                Math.Max(
                    14,
                    (int)Math.Round(30 * scale));
            int left = centerX - sampleWidth / 2;
            int top = centerY - sampleHeight / 2;
            int orange = 0;
            int total = 0;
            for (int y = Math.Max(0, top);
                 y < Math.Min(imageHeight, top + sampleHeight);
                 y += 2)
            {
                int row = y * stride;
                for (int x = Math.Max(0, left);
                     x < Math.Min(imageWidth, left + sampleWidth);
                     x += 2)
                {
                    int index = row + x * 3;
                    int blue = pixels[index];
                    int green = pixels[index + 1];
                    int red = pixels[index + 2];
                    if (red > green + 18 &&
                        green > blue + 4 &&
                        red > 65)
                    {
                        orange++;
                    }
                    total++;
                }
            }

            return total > 0 &&
                orange / (double)total >= 0.06;
        }

        private static List<Vector2i> FindChartMarkerCenters(
            byte[] pixels,
            int stride,
            int imageWidth,
            int imageHeight,
            int beginX,
            int beginY,
            double scale)
        {
            // Compact/windowed Voyage layouts place the item pool much
            // closer to Clear Board than the original 1920px layout. The old
            // +350 ROI could collapse to the last ~150px of the client and
            // report Available=0 even with a full pool.
            int left = Math.Max(
                0,
                beginX + (int)Math.Round(245 * scale));
            int right = Math.Min(
                imageWidth - 1,
                beginX + (int)Math.Round(900 * scale));
            int top = Math.Max(
                0,
                beginY - (int)Math.Round(630 * scale));
            int bottom = Math.Min(
                imageHeight - 1,
                beginY - (int)Math.Round(5 * scale));
            var output = new List<Vector2i>();
            if (right <= left || bottom <= top)
            {
                return output;
            }

            int roiWidth = right - left + 1;
            int roiHeight = bottom - top + 1;
            var green = new bool[roiWidth * roiHeight];
            for (int y = 0; y < roiHeight; y++)
            {
                int row = (top + y) * stride;
                for (int x = 0; x < roiWidth; x++)
                {
                    int index = row + (left + x) * 3;
                    int blue = pixels[index];
                    int greenValue = pixels[index + 1];
                    int red = pixels[index + 2];
                    if (greenValue > 85 &&
                        greenValue > red + 18 &&
                        greenValue >= blue - 14)
                    {
                        green[y * roiWidth + x] = true;
                    }
                }
            }

            // One-pixel dilation joins the anti-aliased pieces of the green
            // chart marker without merging adjacent 50px inventory cells.
            var mask = new bool[green.Length];
            for (int y = 1; y < roiHeight - 1; y++)
            {
                for (int x = 1; x < roiWidth - 1; x++)
                {
                    if (!green[y * roiWidth + x])
                    {
                        continue;
                    }
                    for (int dy = -1; dy <= 1; dy++)
                    {
                        for (int dx = -1; dx <= 1; dx++)
                        {
                            mask[
                                (y + dy) * roiWidth +
                                x + dx] = true;
                        }
                    }
                }
            }

            var visited = new bool[mask.Length];
            var queue = new int[mask.Length];
            int minimumPixels =
                Math.Max(
                    18,
                    (int)Math.Round(120 * scale * scale));
            int minimumSize =
                Math.Max(
                    7,
                    (int)Math.Round(15 * scale));
            int maximumSize =
                Math.Max(
                    16,
                    (int)Math.Round(36 * scale));
            for (int start = 0;
                 start < mask.Length;
                 start++)
            {
                if (!mask[start] || visited[start])
                {
                    continue;
                }

                int head = 0;
                int tail = 0;
                queue[tail++] = start;
                visited[start] = true;
                int count = 0;
                long sumX = 0;
                long sumY = 0;
                int minX = roiWidth;
                int minY = roiHeight;
                int maxX = 0;
                int maxY = 0;
                while (head < tail)
                {
                    int current = queue[head++];
                    int currentY = current / roiWidth;
                    int currentX = current -
                        currentY * roiWidth;
                    count++;
                    sumX += currentX;
                    sumY += currentY;
                    minX = Math.Min(minX, currentX);
                    minY = Math.Min(minY, currentY);
                    maxX = Math.Max(maxX, currentX);
                    maxY = Math.Max(maxY, currentY);

                    for (int dy = -1; dy <= 1; dy++)
                    {
                        int nextY = currentY + dy;
                        if (nextY < 0 || nextY >= roiHeight)
                        {
                            continue;
                        }
                        for (int dx = -1; dx <= 1; dx++)
                        {
                            if (dx == 0 && dy == 0)
                            {
                                continue;
                            }
                            int nextX = currentX + dx;
                            if (nextX < 0 ||
                                nextX >= roiWidth)
                            {
                                continue;
                            }
                            int next =
                                nextY * roiWidth + nextX;
                            if (mask[next] &&
                                !visited[next])
                            {
                                visited[next] = true;
                                queue[tail++] = next;
                            }
                        }
                    }
                }

                int componentWidth = maxX - minX + 1;
                int componentHeight = maxY - minY + 1;
                double aspectRatio =
                    componentWidth /
                    (double)Math.Max(1, componentHeight);
                if (count < minimumPixels ||
                    componentWidth < minimumSize ||
                    componentHeight < minimumSize ||
                    componentWidth > maximumSize ||
                    componentHeight > maximumSize ||
                    aspectRatio < 0.72 ||
                    aspectRatio > 1.38)
                {
                    continue;
                }

                var center =
                    new Vector2i(
                        left +
                            (int)Math.Round(
                                sumX / (double)count),
                        top +
                            (int)Math.Round(
                                sumY / (double)count));
                double duplicateDistance =
                    Math.Max(18.0, 22.0 * scale);
                if (!output.Any(
                        existing =>
                            Math.Abs(existing.X - center.X) <
                                duplicateDistance &&
                            Math.Abs(existing.Y - center.Y) <
                                duplicateDistance))
                {
                    output.Add(center);
                }
            }

            AllflameLog.Throttled(
                "voyage_chart_detector",
                TimeSpan.FromSeconds(2),
                "VOYAGE_CHART_DETECT" +
                "|MarkerComponents=" + output.Count +
                "|Detection=GreenMarkerOnly" +
                "|Roi=" + left + "," + top + "," +
                    right + "," + bottom);

            return output
                .OrderBy(location => location.Y)
                .ThenBy(location => location.X)
                .Take(60)
                .ToList();
        }

        private static bool TryFindTitle(
            byte[] pixels,
            int stride,
            int width,
            int height,
            out int bestCenterX,
            out int bestCenterY,
            out double bestScale,
            out double bestCorrelation)
        {
            bestCenterX = width / 2;
            bestCenterY = height / 5;
            bestScale = 1.0;
            bestCorrelation = -1.0;
            double[] scales =
                { 0.84, 0.92, 1.0, 1.08, 1.16 };
            int searchLeft = (int)(width * 0.28);
            int searchRight = (int)(width * 0.68);
            int searchTop = 8;
            int searchBottom = (int)(height * 0.34);

            foreach (double scale in scales)
            {
                int candidateWidth =
                    Math.Max(
                        180,
                        (int)Math.Round(265 * scale));
                int candidateHeight =
                    Math.Max(
                        34,
                        (int)Math.Round(50 * scale));
                int halfWidth = candidateWidth / 2;
                int halfHeight = candidateHeight / 2;
                int minX = Math.Max(
                    halfWidth,
                    searchLeft);
                int maxX = Math.Min(
                    width - halfWidth - 1,
                    searchRight);
                int minY = Math.Max(
                    halfHeight,
                    searchTop);
                int maxY = Math.Min(
                    height - halfHeight - 1,
                    searchBottom);

                for (int centerY = minY;
                     centerY <= maxY;
                     centerY += 6)
                {
                    for (int centerX = minX;
                         centerX <= maxX;
                         centerX += 6)
                    {
                        double correlation =
                            CalculateImageCorrelation(
                                pixels,
                                stride,
                                width,
                                height,
                                centerX - halfWidth,
                                centerY - halfHeight,
                                candidateWidth,
                                candidateHeight,
                                TitleTemplate,
                                TitleTemplateWidth,
                                TitleTemplateHeight,
                                TitleTemplateMean,
                                TitleTemplateEnergy);
                        if (correlation > bestCorrelation)
                        {
                            bestCorrelation = correlation;
                            bestCenterX = centerX;
                            bestCenterY = centerY;
                            bestScale = scale;
                        }
                    }
                }
            }

            if (bestCorrelation <
                MinimumTitleCorrelation)
            {
                AllflameLog.Throttled(
                    "voyage_title_not_detected",
                    TimeSpan.FromSeconds(2),
                    "VOYAGE_VISUAL|Open=False" +
                    "|BestTitleCorrelation=" +
                    bestCorrelation.ToString("0.000"));
                return false;
            }
            return true;
        }

        private static int CountGreenPixels(
            byte[] pixels,
            int stride,
            int left,
            int top,
            int width,
            int height)
        {
            int count = 0;
            for (int y = top; y < top + height; y++)
            {
                int row = y * stride;
                for (int x = left;
                     x < left + width;
                     x++)
                {
                    int index = row + x * 3;
                    int blue = pixels[index];
                    int green = pixels[index + 1];
                    int red = pixels[index + 2];
                    if (green > 90 &&
                        green > red + 20 &&
                        green >= blue - 12)
                    {
                        count++;
                    }
                }
            }
            return count;
        }

        private static double CalculateImageCorrelation(
            byte[] pixels,
            int stride,
            int imageWidth,
            int imageHeight,
            int candidateLeft,
            int candidateTop,
            int candidateWidth,
            int candidateHeight,
            byte[] template,
            int templateWidth,
            int templateHeight,
            double templateMean,
            double templateEnergy)
        {
            double sum = 0.0;
            double sumSquares = 0.0;
            double cross = 0.0;
            int count = template.Length;
            for (int templateY = 0;
                 templateY < templateHeight;
                 templateY++)
            {
                int sourceY =
                    candidateTop +
                    templateY *
                    (candidateHeight - 1) /
                    Math.Max(1, templateHeight - 1);
                if (sourceY < 0 ||
                    sourceY >= imageHeight)
                {
                    return -1.0;
                }
                int row = sourceY * stride;
                for (int templateX = 0;
                     templateX < templateWidth;
                     templateX++)
                {
                    int sourceX =
                        candidateLeft +
                        templateX *
                        (candidateWidth - 1) /
                        Math.Max(1, templateWidth - 1);
                    if (sourceX < 0 ||
                        sourceX >= imageWidth)
                    {
                        return -1.0;
                    }

                    int pixelIndex = row + sourceX * 3;
                    double gray =
                        (pixels[pixelIndex + 2] * 77 +
                         pixels[pixelIndex + 1] * 150 +
                         pixels[pixelIndex] * 29) / 256.0;

                    int templateIndex =
                        templateY * templateWidth +
                        templateX;
                    if (templateIndex < 0 ||
                        templateIndex >= template.Length)
                    {
                        return -1.0;
                    }

                    double centered =
                        template[templateIndex] -
                        templateMean;
                    sum += gray;
                    sumSquares += gray * gray;
                    cross += gray * centered;
                }
            }

            double candidateEnergy =
                sumSquares - sum * sum / count;
            if (candidateEnergy <= 0.001 ||
                templateEnergy <= 0.001)
            {
                return -1.0;
            }
            return cross /
                Math.Sqrt(
                    candidateEnergy *
                    templateEnergy);
        }

        private static double CalculateTemplateEnergy(
            byte[] template,
            double mean)
        {
            return template.Sum(
                value =>
                    (value - mean) *
                    (value - mean));
        }

        public static Element FindButton(string text)
        {
            Element label = FindTextElement(text, false);
            if (label == null)
            {
                return null;
            }

            Element best = label;
            Element current = label;
            for (int depth = 0; depth < 3; depth++)
            {
                Element parent;
                try
                {
                    parent = current.Parent;
                }
                catch
                {
                    break;
                }
                if (parent == null ||
                    !parent.IsValid ||
                    !parent.IsVisible)
                {
                    break;
                }
                if (parent.Width >= 65f &&
                    parent.Width <= 360f &&
                    parent.Height >= 18f &&
                    parent.Height <= 95f)
                {
                    best = parent;
                }
                current = parent;
            }
            return best;
        }

        public static List<Element> FindAvailableChartElements()
        {
            var labels = new List<Element>();
            List<Element> roots = LokiPoe.GetGuiElements();
            if (roots == null)
            {
                return labels;
            }

            int visited = 0;
            for (int index = roots.Count - 1;
                 index >= 0 && visited < MaximumVisited;
                 index--)
            {
                CollectChartLabels(
                    roots[index],
                    0,
                    labels,
                    ref visited);
            }

            var unique = new List<Element>();
            var centers = new List<Vector2i>();
            foreach (Element label in labels)
            {
                Element clickable = FindChartClickable(label);
                Vector2i center;
                try
                {
                    center = clickable.CenterClickLocation();
                }
                catch
                {
                    continue;
                }

                if (centers.Any(existing =>
                    Math.Abs(existing.X - center.X) <= 8 &&
                    Math.Abs(existing.Y - center.Y) <= 8))
                {
                    continue;
                }
                centers.Add(center);
                unique.Add(clickable);
            }

            return unique
                .OrderBy(element =>
                    element.CenterClickLocation().Y)
                .ThenBy(element =>
                    element.CenterClickLocation().X)
                .ToList();
        }

        public static bool Click(Element element)
        {
            try
            {
                if (element == null ||
                    !element.IsValid ||
                    !element.IsVisible)
                {
                    return false;
                }

                Vector2i location =
                    element.CenterClickLocation();
                LokiPoe.ProcessHookManager.ClearAllKeyStates();
                DreamPoeBot.BotFramework.MouseManager.SetMousePosition(
                    location,
                    true);
                DreamPoeBot.BotFramework.MouseManager.ClickLMB(0, 0);
                return true;
            }
            catch (Exception exception)
            {
                AllflameLog.Info(
                    "VOYAGE_UI_CLICK_FAILED|Error=" +
                    exception.GetType().Name +
                    "|Message=" + exception.Message);
                return false;
            }
        }

        public static async Task<bool> CtrlClick(Element element)
        {
            if (element == null)
            {
                return false;
            }

            bool controlDown = false;
            try
            {
                Vector2i location =
                    element.CenterClickLocation();
                LokiPoe.ProcessHookManager.ClearAllKeyStates();
                DreamPoeBot.BotFramework.MouseManager.SetMousePosition(
                    location,
                    true);
                await LokiCoroutine.Sleep(20);
                LokiPoe.ProcessHookManager.SetKeyState(
                    System.Windows.Forms.Keys.ControlKey,
                    short.MinValue,
                    System.Windows.Forms.Keys.None);
                controlDown = true;
                await LokiCoroutine.Sleep(25);
                DreamPoeBot.BotFramework.MouseManager.ClickLMB(0, 0);
                await LokiCoroutine.Sleep(80);
                return true;
            }
            catch (Exception exception)
            {
                AllflameLog.Info(
                    "VOYAGE_CTRL_CLICK_FAILED|Error=" +
                    exception.GetType().Name +
                    "|Message=" + exception.Message);
                return false;
            }
            finally
            {
                if (controlDown)
                {
                    LokiPoe.ProcessHookManager.SetKeyState(
                        System.Windows.Forms.Keys.ControlKey,
                        (short)0,
                        System.Windows.Forms.Keys.None);
                }
            }
        }

        private static Element FindTextElement(
            string expected,
            bool partial)
        {
            List<Element> roots = LokiPoe.GetGuiElements();
            if (roots == null)
            {
                return null;
            }

            int visited = 0;
            var visitedAddresses = new HashSet<long>();
            DateTime deadline =
                DateTime.UtcNow.AddMilliseconds(350);
            for (int index = roots.Count - 1;
                 index >= 0 &&
                 visited < MaximumVisited &&
                 DateTime.UtcNow < deadline;
                 index--)
            {
                Element found = FindTextElement(
                    roots[index],
                    expected,
                    partial,
                    0,
                    visitedAddresses,
                    deadline,
                    ref visited);
                if (found != null)
                {
                    return found;
                }
            }
            return null;
        }

        private static Element FindTextElement(
            Element element,
            string expected,
            bool partial,
            int depth,
            ISet<long> visitedAddresses,
            DateTime deadline,
            ref int visited)
        {
            if (element == null ||
                depth > 14 ||
                visited >= MaximumVisited ||
                DateTime.UtcNow >= deadline)
            {
                return null;
            }
            try
            {
                long address = element.Address;
                if (address != 0 &&
                    !visitedAddresses.Add(address))
                {
                    return null;
                }
            }
            catch
            {
            }
            visited++;

            try
            {
                if (element.IsValid && element.IsVisible)
                {
                    string value =
                        (element.Text ?? String.Empty).Trim();
                    bool matches = partial
                        ? value.IndexOf(
                            expected,
                            StringComparison.OrdinalIgnoreCase) >= 0
                        : String.Equals(
                            value,
                            expected,
                            StringComparison.OrdinalIgnoreCase);
                    if (matches)
                    {
                        return element;
                    }
                }
            }
            catch
            {
            }

            List<Element> children;
            try
            {
                children = element.Children;
            }
            catch
            {
                return null;
            }
            if (children == null)
            {
                return null;
            }

            foreach (Element child in children)
            {
                Element found = FindTextElement(
                    child,
                    expected,
                    partial,
                    depth + 1,
                    visitedAddresses,
                    deadline,
                    ref visited);
                if (found != null)
                {
                    return found;
                }
                if (visited >= MaximumVisited ||
                    DateTime.UtcNow >= deadline)
                {
                    break;
                }
            }
            return null;
        }

        private static void CollectChartLabels(
            Element element,
            int depth,
            IList<Element> output,
            ref int visited)
        {
            if (element == null ||
                depth > 14 ||
                visited >= MaximumVisited)
            {
                return;
            }
            visited++;

            try
            {
                if (element.IsValid &&
                    element.IsVisible &&
                    LevelLabel.IsMatch(
                        element.Text ?? String.Empty))
                {
                    output.Add(element);
                }
            }
            catch
            {
            }

            List<Element> children;
            try
            {
                children = element.Children;
            }
            catch
            {
                return;
            }
            if (children == null)
            {
                return;
            }
            foreach (Element child in children)
            {
                CollectChartLabels(
                    child,
                    depth + 1,
                    output,
                    ref visited);
                if (visited >= MaximumVisited)
                {
                    break;
                }
            }
        }

        private static Element FindChartClickable(Element label)
        {
            Element best = label;
            Element current = label;
            for (int depth = 0; depth < 4; depth++)
            {
                Element parent;
                try
                {
                    parent = current.Parent;
                }
                catch
                {
                    break;
                }
                if (parent == null ||
                    !parent.IsValid ||
                    !parent.IsVisible)
                {
                    break;
                }

                if (parent.Width >= 24f &&
                    parent.Width <= 90f &&
                    parent.Height >= 24f &&
                    parent.Height <= 90f)
                {
                    best = parent;
                }
                current = parent;
            }
            return best;
        }
    }

    internal sealed class DebugChartStorageTask : ObserverTask
    {
        private int _stage;
        private DateTime _waitUntilUtc = DateTime.MinValue;
        private DateTime _timeoutUtc = DateTime.MinValue;
        private InventoryControlWrapper _storageControl;
        private InventorySlotUiElement _storageSlot;

        public DebugChartStorageTask()
            : base(
                "DebugChartStorageTask",
                "Opens Chart Storage and reads the visible page without moving any item.") { }

        public override async Task<bool> Run()
        {
            if (!AllflameChartStorageDebug.IsRequested)
            {
                Reset();
                return false;
            }

            bool inHub =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            if (!inHub)
            {
                AllflameChartStorageDebug.SetStatus(
                    "Waiting: start the bot on The Sovereign.");
                return false;
            }

            if (_stage == 0)
            {
                if (TryResolveStorageUi())
                {
                    _stage = 2;
                    _waitUntilUtc =
                        DateTime.UtcNow.AddMilliseconds(250);
                    _timeoutUtc =
                        DateTime.UtcNow.AddSeconds(10);
                    AllflameChartStorageDebug.SetStatus(
                        "Chart Storage is already open; reading visible page...");
                    return true;
                }

                NetworkObject storage =
                    AllflameContext.ChartStorageObject;
                if (storage == null || !storage.IsValid)
                {
                    AllflameContext.Refresh(true);
                    AllflameChartStorageDebug.SetStatus(
                        "Waiting for the Chart Storage object...");
                    AllflameLog.Throttled(
                        "chart_storage_debug_object_missing",
                        TimeSpan.FromSeconds(2),
                        "CHART_STORAGE_DEBUG_WAIT" +
                        "|Reason=ObjectMissing" +
                        "|Area=" + AllflameContext.AreaId);
                    return true;
                }

                if (storage.Distance >
                    AllflameSettings.Instance.InteractDistance)
                {
                    AllflameChartStorageDebug.SetStatus(
                        "Moving to Chart Storage...");
                    await MoveOrInteract(
                        storage,
                        "Chart Storage debug");
                    return true;
                }

                await FinishMovementBeforeInteraction(
                    "Chart Storage Debug");
                bool interacted =
                    await InteractWithRecovery(storage);
                _stage = interacted ? 1 : 0;
                _waitUntilUtc =
                    DateTime.UtcNow.AddMilliseconds(
                        interacted ? 900 : 400);
                _timeoutUtc =
                    DateTime.UtcNow.AddSeconds(10);
                AllflameChartStorageDebug.SetStatus(
                    interacted
                        ? "Chart Storage interaction sent; waiting for UI..."
                        : "Interaction failed; retrying...");
                AllflameLog.Info(
                    "CHART_STORAGE_DEBUG_OPEN" +
                    "|Success=" + interacted +
                    "|ObjectId=" + storage.Id +
                    "|Distance=" +
                    storage.Distance.ToString("0.0"));
                return true;
            }

            if (DateTime.UtcNow < _waitUntilUtc)
            {
                return true;
            }

            if (!TryResolveStorageUi())
            {
                if (DateTime.UtcNow >= _timeoutUtc)
                {
                    AllflameLog.Info(
                        "CHART_STORAGE_DEBUG_FAILED" +
                        "|Reason=PageLayerNotResolved" +
                        "|Detector=ChartStorageUi");
                    AllflameChartStorageDebug.Complete(
                        false,
                        0,
                        0,
                        "UI opened but its active Chart page could not be resolved.");
                    await Coroutines.CloseBlockingWindows();
                    Reset();
                    return true;
                }

                _stage = 1;
                _waitUntilUtc =
                    DateTime.UtcNow.AddMilliseconds(350);
                AllflameChartStorageDebug.SetStatus(
                    "Chart Storage UI detected; waiting for its grid...");
                return true;
            }

            Inventory storageInventory = _storageControl == null
                ? null
                : _storageControl.Inventory;
            List<Item> items =
                storageInventory == null ||
                storageInventory.Items == null
                    ? new List<Item>()
                    : storageInventory.Items
                        .Where(item => item != null && item.IsValid)
                        .ToList();
            List<Item> charts =
                new List<Item>();
            List<KeyValuePair<int, Element>> rawCharts =
                ChartStorageUi.GetRawItemElements(_storageSlot);
            var visibleKeys = new HashSet<int>(
                rawCharts.Select(pair => pair.Key));
            charts = items
                .Where(item =>
                    AllflameContext.IsChartItem(item) &&
                    visibleKeys.Contains(item.LocalId))
                .ToList();
            int chartStacks = storageInventory == null
                ? rawCharts.Count
                : charts.Sum(item => Math.Max(1, item.StackCount));

            AllflameLog.Info(
                "CHART_STORAGE_DEBUG_RESULT" +
                "|ControlAddress=0x" +
                (_storageSlot == null
                    ? 0L
                    : _storageSlot.Address).ToString("X") +
                "|Mode=" + (storageInventory == null
                    ? "RawGrid"
                    : "ServerInventory") +
                "|Rows=" + (storageInventory == null
                    ? _storageSlot.Size.Y
                    : storageInventory.Rows) +
                "|Columns=" + (storageInventory == null
                    ? _storageSlot.Size.X
                    : storageInventory.Columns) +
                "|AllItems=" + (storageInventory == null
                    ? rawCharts.Count
                    : items.Count) +
                "|VisibleRawItems=" + rawCharts.Count +
                "|ChartItems=" + charts.Count +
                "|ChartStacks=" + chartStacks +
                "|ReadOnly=True");
            foreach (Item item in items)
            {
                bool isChart =
                    AllflameContext.IsChartItem(item);
                AllflameLog.Info(
                    "CHART_STORAGE_DEBUG_ITEM" +
                    "|IsChart=" + isChart +
                    "|Id=" + item.Id +
                    "|LocalId=" + item.LocalId +
                    "|Name=" + Sanitize(item.Name) +
                    "|FullName=" + Sanitize(item.FullName) +
                    "|Metadata=" + Sanitize(item.Metadata) +
                    "|Stack=" + Math.Max(1, item.StackCount) +
                    "|Location=" + item.LocationTopLeft);
            }
            foreach (KeyValuePair<int, Element> pair in rawCharts)
            {
                AllflameLog.Info(
                    "CHART_STORAGE_DEBUG_RAW_ITEM" +
                    "|Key=" + pair.Key +
                    "|Address=0x" + pair.Value.Address.ToString("X") +
                    "|Center=" + pair.Value.CenterClickLocation());
            }

            AllflameSettings settings =
                AllflameSettings.Instance;
            int chartCount = storageInventory == null
                ? rawCharts.Count
                : charts.Count;
            settings.LastChartStorageTotal = chartCount;
            settings.LastChartStorageScan =
                "DebugVisiblePage:Items=" + (storageInventory == null
                    ? rawCharts.Count
                    : items.Count) +
                ",Charts=" + chartCount +
                ",Stacks=" + chartStacks;
            settings.Save();

            AllflameChartStorageDebug.Complete(
                true,
                chartCount,
                chartStacks,
                "Visible page read successfully.");
            await Coroutines.CloseBlockingWindows();
            Reset();
            return true;
        }

        private bool TryResolveStorageUi()
        {
            if (ChartStorageUi.TryResolve(
                    _storageControl,
                    _storageSlot,
                    out _storageControl,
                    out _storageSlot))
            {
                return true;
            }

            _storageControl = null;
            _storageSlot = null;
            return false;
        }

        private void Reset()
        {
            _stage = 0;
            _waitUntilUtc = DateTime.MinValue;
            _timeoutUtc = DateTime.MinValue;
            _storageControl = null;
            _storageSlot = null;
        }

        private static string Sanitize(string value)
        {
            return (value ?? String.Empty)
                .Replace("|", "/")
                .Replace("\r", " ")
                .Replace("\n", " ");
        }
    }

    internal sealed class OpenVoyageStashTask : ObserverTask
    {
        private const int StashInteractionTimeoutSeconds = 8;
        private const int MaximumUiRecoveryCycles = 3;
        private const int ApproachNoProgressSeconds = 4;
        private const float ApproachProgressDistance = 3f;
        private const int MaximumApproachRecoveries = 2;
        private const int MaximumAlternateCandidates = 6;
        private const int ApproachTimeoutSeconds = 30;
        private const int CandidateReachedDistance = 10;
        private const int CandidateMinimumPlayerDistance = 8;
        private static readonly int[] AlternateCandidateRadii = { 12, 16 };
        private static int TargetInventoryCharts
        {
            get
            {
                return AllflameSettings.Instance.GetChartWithdrawalCount();
            }
        }
        private DateTime _retryAfterUtc = DateTime.MinValue;
        private int _interactionAttempts;
        private int _tabAttempts;
        private int _lastStashObjectId;
        private uint _lastAreaHash;
        private DateTime _stashInteractionBlockedUtc = DateTime.MinValue;
        private int _uiRecoveryCycles;
        private bool _approachActive;
        private uint _approachAreaHash;
        private int _approachObjectId;
        private Vector2i _approachStashPosition;
        private DateTime _approachStartedUtc = DateTime.MinValue;
        private DateTime _approachLastProgressUtc = DateTime.MinValue;
        private DateTime _approachCooldownUntilUtc = DateTime.MinValue;
        private DateTime _approachPathFailureSinceUtc = DateTime.MinValue;
        private float _approachBestDistance = Single.MaxValue;
        private float _approachProgressReference = Single.MaxValue;
        private int _approachRecoveries;
        private bool _alternateApproach;
        private bool _hasAlternateCandidate;
        private Vector2i _alternateCandidate;
        private DateTime _alternateCandidateSelectedUtc = DateTime.MinValue;
        private bool _lastApproachMoving;
        private readonly List<Vector2i> _triedAlternateCandidates =
            new List<Vector2i>();
        private bool _stashWithdrawPending;
        private int _stashWithdrawLocalId;
        private int _stashWithdrawBeforeInventory;
        private DateTime _stashWithdrawIssuedUtc = DateTime.MinValue;
        private int _stashWithdrawnCharts;

        public OpenVoyageStashTask()
            : base(
                "OpenVoyageStashTask",
                "Withdraws Charts from the configured personal Voyage Stash tab.") { }

        public override void Start()
        {
            ResetLocalState();
        }

        public override void Stop()
        {
            ResetLocalState();
            AllflameProgressWatchdog.Clear(Name);
        }

        public override async Task<bool> Run()
        {
            AllflameSettings settings = AllflameSettings.Instance;
            bool inHub =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            if (!inHub)
            {
                ResetLocalState();
                AllflameProgressWatchdog.Clear(Name);
                return false;
            }

            if (AllflameRunState.VoyageStarted)
            {
                ResetLocalState();
                AllflameProgressWatchdog.Clear(Name);
                return false;
            }

            int loadedDeviceCharts = LoadedChartDeviceItemCount();
            if (AllflameRunState.ChartRequested || loadedDeviceCharts > 0)
            {
                AllflameLog.Throttled(
                    "chart_supply_deferred_device_cycle",
                    TimeSpan.FromSeconds(2),
                    "CHART_SUPPLY_DEFERRED" +
                    "|Reason=" +
                    (loadedDeviceCharts > 0
                        ? "ChartAlreadyLoadedInDevice"
                        : "ChartDeviceCycleActive") +
                    "|Task=" + Name +
                    "|AreaHash=" + AllflameContext.AreaHash +
                    "|ChartRequested=" +
                    AllflameRunState.ChartRequested +
                    "|InventoryCharts=" +
                    AllflameContext.InventoryChartCount +
                    "|DeviceCharts=" + loadedDeviceCharts +
                    "|NextTask=LoadChartDeviceTask");
                ResetApproachTracking();
                AllflameProgressWatchdog.Clear(Name);
                return false;
            }

            if (_lastAreaHash != AllflameContext.AreaHash)
            {
                _lastAreaHash = AllflameContext.AreaHash;
                _interactionAttempts = 0;
                _tabAttempts = 0;
                _lastStashObjectId = 0;
                _stashInteractionBlockedUtc = DateTime.MinValue;
                _uiRecoveryCycles = 0;
                ResetApproachTracking();
            }

            if (settings.RunInventoryChartsOnly ||
                !settings.CheckVoyageStashFirst)
            {
                if (!AllflameRunState.VoyageStashProbeCompleted)
                {
                    AllflameRunState.MarkVoyageStashProbeCompleted();
                }
                if (!AllflameRunState.ChartStorageChecked)
                {
                    if (AllflameContext.InventoryChartCount > 0)
                    {
                        AllflameRunState.MarkStorageChecked();
                    }
                    AllflameLog.Info(
                        "VOYAGE_STASH_SOURCE_RESULT" +
                        "|Result=Disabled" +
                        "|InventoryOnly=" +
                        settings.RunInventoryChartsOnly +
                        "|SettingEnabled=" + settings.CheckVoyageStashFirst +
                        "|InventoryCharts=" +
                        AllflameContext.InventoryChartCount);
                }
                if (AllflameContext.InventoryChartCount == 0)
                {
                    string supplyReason =
                        !settings.EnableChartStorageWithdrawal &&
                        !settings.CheckVoyageStashFirst
                            ? "AllSourcesDisabled"
                            : (settings.RunInventoryChartsOnly
                                ? "InventoryOnlyEmpty"
                                : "ChartStorageUnavailableAndStashDisabled");
                    AllflameLog.Info(
                        "CHART_SUPPLY_FAILED" +
                        "|Reason=" + supplyReason +
                        "|NextAction=ControlledStop");
                    AllflameLog.Info(
                        "CHART_SUPPLY_EXHAUSTED" +
                        "|InventoryCharts=0" +
                        "|DeviceCharts=0" +
                        "|ChartRequested=False" +
                        "|StorageProbeCompleted=" +
                        AllflameRunState.ChartStorageProbeCompleted +
                        "|StorageChecked=" +
                        AllflameRunState.ChartStorageChecked +
                        "|VoyageStashEnabled=" +
                        settings.CheckVoyageStashFirst +
                        "|NextAction=RecoveryStop");
                    AllflameStopController.Stop(
                        "NoChartsRemaining",
                        settings.RunInventoryChartsOnly
                            ? "InventoryOnly=True"
                            : "VoyageStashCheckDisabled=True");
                    return true;
                }
                ResetApproachTracking();
                AllflameProgressWatchdog.Clear(Name);
                return false;
            }

            if (AllflameRunState.ChartStorageChecked)
            {
                ResetApproachTracking();
                AllflameProgressWatchdog.Clear(Name);
                return false;
            }
            if (settings.EnableChartStorageWithdrawal &&
                !AllflameRunState.ChartStorageProbeCompleted)
            {
                return false;
            }
            if (AllflameRunState.VoyageStashProbeCompleted)
            {
                return false;
            }

            AllflameContext.RefreshInventory(false);
            // A Voyage Stash withdrawal is a batch operation. Once a batch has
            // been taken, consume every remaining Chart before opening the
            // stash again. Do not top 19 back up to 20 after each run.
            bool chartStorageTopUpPending =
                AllflameRunState.ChartStorageProbeCompleted &&
                !AllflameRunState.ChartStorageChecked;
            if (AllflameContext.InventoryChartCount > 0 &&
                !chartStorageTopUpPending)
            {
                AllflameRunState.MarkVoyageStashProbeCompleted();
                AllflameRunState.MarkStorageChecked();
                AllflameLog.Info(
                    "VOYAGE_STASH_SKIPPED|Reason=BatchStillActive" +
                    "|RemainingCharts=" +
                    AllflameContext.InventoryChartCount +
                    "|NextWithdrawalAt=0");
                ResetApproachTracking();
                AllflameProgressWatchdog.Clear(Name);
                return false;
            }
            if (chartStorageTopUpPending &&
                AllflameContext.InventoryChartCount > 0)
            {
                AllflameLog.Info(
                    "VOYAGE_STASH_TOP_UP" +
                    "|Reason=ChartStorageBelowTarget" +
                    "|InventoryCharts=" +
                    AllflameContext.InventoryChartCount +
                    "|Target=" + TargetInventoryCharts +
                    "|Needed=" + Math.Max(
                        0,
                        TargetInventoryCharts -
                        AllflameContext.InventoryChartCount));
            }

            if (DateTime.UtcNow < _retryAfterUtc)
            {
                return true;
            }

            if (!LokiPoe.InGameState.StashUi.IsOpened)
            {
                NetworkObject stash = AllflameContext.StashObject;
                int stashObjectId = stash == null ? 0 : stash.Id;
                if (_lastStashObjectId != stashObjectId)
                {
                    _lastStashObjectId = stashObjectId;
                    _interactionAttempts = 0;
                }
                if (stash == null || !stash.IsValid)
                {
                    ResetApproachTracking();
                    AllflameProgressWatchdog.Begin(
                        Name,
                        0,
                        "Voyage Stash");
                    _interactionAttempts++;
                    AllflameProgressWatchdog.SetRetry(
                        _interactionAttempts);
                    AllflameLog.Info(
                        "VOYAGE_STASH_RETRY|Attempt=" +
                        _interactionAttempts +
                        "|Reason=PersonalStashObjectMissing" +
                        "|NextAction=ReacquireStash");
                    if (_interactionAttempts >= 3)
                    {
                        return await FailStash(
                            "StashObjectMissing",
                            "ReacquireStash");
                    }
                    _retryAfterUtc = DateTime.UtcNow.AddSeconds(1);
                    return true;
                }

                EnsureApproachTracking(stash);
                AllflameProgressWatchdog.BeginExplicitProgress(
                    Name,
                    stash.Id,
                    "Voyage Stash");
                if (stash.Distance > settings.InteractDistance)
                {
                    VoyageStashApproachResult approachResult =
                        ContinueVoyageStashApproach(stash);
                    if (approachResult == VoyageStashApproachResult.Failed)
                    {
                        LogApproachFailed(stash);
                        return await FailStash(
                            "StashApproachBlocked",
                            "ApproachRecoveryExhausted");
                    }
                    if (approachResult == VoyageStashApproachResult.Continue)
                        return true;
                }

                bool opened = false;
                try
                {
                    opened = await InteractWithRecovery(stash);
                }
                catch (Exception ex)
                {
                    AllflameLog.Info(
                        "VOYAGE_STASH_OPEN_EXCEPTION|Type=" +
                        ex.GetType().Name +
                        "|Message=" +
                        (ex.Message ?? String.Empty).Replace("|", "/"));
                }
                if (opened)
                {
                    _interactionAttempts = 0;
                    _stashInteractionBlockedUtc = DateTime.MinValue;
                    _uiRecoveryCycles = 0;
                    AllflameProgressWatchdog.MarkProgress(
                        "StashUiOpened");
                    ResetApproachTracking();
                }
                else
                {
                    _interactionAttempts++;
                    if (_stashInteractionBlockedUtc == DateTime.MinValue)
                    {
                        _stashInteractionBlockedUtc = DateTime.UtcNow;
                    }
                    AllflameProgressWatchdog.SetRetry(
                        _interactionAttempts);
                    TimeSpan blockedFor =
                        DateTime.UtcNow - _stashInteractionBlockedUtc;
                    if (blockedFor >= TimeSpan.FromSeconds(
                            StashInteractionTimeoutSeconds))
                    {
                        if (_uiRecoveryCycles >= MaximumUiRecoveryCycles)
                        {
                            return await FailStash(
                                "StashInteractionBlockedAfterUiRecovery",
                                "UiRecoveryCyclesExhausted");
                        }
                        await RecoverBlockedStashUi(blockedFor);
                        return true;
                    }
                }
                _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(
                    opened ? 900 : 600);
                AllflameLog.Info(
                    "VOYAGE_STASH_OPEN|Success=" + opened +
                    "|Object=" + stash.Name +
                    "|Attempt=" +
                    (_interactionAttempts == 0
                        ? 1
                        : _interactionAttempts));
                return true;
            }

            ResetApproachTracking();
            AllflameProgressWatchdog.BeginExplicitProgress(
                Name,
                _lastStashObjectId,
                "Voyage Stash UI");
            string requested = (settings.VoyageStashTab ?? String.Empty).Trim();
            string tabName = ResolveStashTabName(requested);
            if (String.IsNullOrEmpty(tabName))
            {
                _tabAttempts++;
                AllflameProgressWatchdog.SetRetry(_tabAttempts);
                AllflameLog.Info(
                    "VOYAGE_STASH_RETRY|Attempt=" + _tabAttempts +
                    "|Reason=TabMissing|Configured=" + requested +
                    "|NextAction=ReloadStashUi");
                if (_tabAttempts >= 3)
                {
                    return await FailStash(
                        "TabMissing",
                        "ReloadStashUi");
                }
                _retryAfterUtc = DateTime.UtcNow.AddSeconds(1);
                return true;
            }

            if (!String.Equals(
                LokiPoe.InGameState.StashUi.TabControl.CurrentTabName,
                tabName,
                StringComparison.OrdinalIgnoreCase))
            {
                var result =
                    LokiPoe.InGameState.StashUi.TabControl
                        .SwitchToTabMouse(tabName);
                if (Convert.ToInt32(result) != 0)
                {
                    result =
                        LokiPoe.InGameState.StashUi.TabControl
                        .SwitchToTabKeyboard(tabName);
                }
                bool accepted = Convert.ToInt32(result) == 0;
                if (accepted)
                {
                    _tabAttempts = 0;
                    AllflameProgressWatchdog.MarkProgress(
                        "SwitchToVoyageStashTab");
                }
                else
                {
                    _tabAttempts++;
                    AllflameProgressWatchdog.SetRetry(_tabAttempts);
                }
                _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(700);
                AllflameLog.Info(
                    "VOYAGE_STASH_TAB|Requested=" + requested +
                    "|Resolved=" + tabName +
                    "|Result=" + result +
                    "|Accepted=" + accepted +
                    "|Attempt=" + _tabAttempts);
                if (!accepted && _tabAttempts >= 3)
                {
                    return await FailStash(
                        "TabSwitchFailed",
                        "ReloadStashUi");
                }
                return true;
            }

            _tabAttempts = 0;

            InventoryControlWrapper control =
                LokiPoe.InGameState.StashUi.InventoryControl;
            if (control == null ||
                control.Inventory == null ||
                control.Inventory.Items == null)
            {
                _tabAttempts++;
                AllflameProgressWatchdog.SetRetry(_tabAttempts);
                AllflameLog.Info(
                    "VOYAGE_STASH_RETRY|Attempt=" + _tabAttempts +
                    "|Reason=InventoryControlUnavailable" +
                    "|NextAction=WaitForStashGrid");
                if (_tabAttempts >= 3)
                {
                    return await FailStash(
                        "InventoryControlUnavailable",
                        "ReloadStashUi");
                }
                _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(700);
                return true;
            }
            List<Item> charts =
                control.Inventory.Items
                    .Where(AllflameContext.IsChartItem)
                    .ToList();

            int liveInventoryCharts = CountInventoryChartsLive();
            if (_stashWithdrawPending)
            {
                bool sourceGone = charts.All(chart =>
                    chart.LocalId != _stashWithdrawLocalId);
                bool confirmed =
                    liveInventoryCharts >
                    _stashWithdrawBeforeInventory ||
                    sourceGone;
                if (confirmed)
                {
                    _stashWithdrawnCharts++;
                    _stashWithdrawPending = false;
                    _stashWithdrawLocalId = 0;
                    _stashWithdrawIssuedUtc = DateTime.MinValue;
                    AllflameProgressWatchdog.MarkProgress(
                        "VoyageStashChartTransferred");
                    AllflameLog.Info(
                        "VOYAGE_STASH_WITHDRAW_CONFIRMED" +
                        "|Tab=" + tabName +
                        "|InventoryCharts=" + liveInventoryCharts +
                        "|TotalWithdrawn=" +
                        _stashWithdrawnCharts +
                        "|OneActionPerCycle=True");
                }
                else if (DateTime.UtcNow - _stashWithdrawIssuedUtc <
                         TimeSpan.FromSeconds(2))
                {
                    return true;
                }
                else
                {
                    AllflameLog.Info(
                        "VOYAGE_STASH_WITHDRAW_REJECTED" +
                        "|Tab=" + tabName +
                        "|LocalId=" + _stashWithdrawLocalId +
                        "|InventoryBefore=" +
                        _stashWithdrawBeforeInventory +
                        "|InventoryAfter=" + liveInventoryCharts +
                        "|Action=RetryFreshSnapshot");
                    _stashWithdrawPending = false;
                    _stashWithdrawLocalId = 0;
                    _stashWithdrawIssuedUtc = DateTime.MinValue;
                }
            }

            int needed = Math.Max(
                0,
                TargetInventoryCharts -
                liveInventoryCharts);
            if (needed > 0 && charts.Count > 0)
            {
                Item chart = charts[0];
                var result = control.FastMove(chart.LocalId);
                _stashWithdrawPending = true;
                _stashWithdrawLocalId = chart.LocalId;
                _stashWithdrawBeforeInventory = liveInventoryCharts;
                _stashWithdrawIssuedUtc = DateTime.UtcNow;
                AllflameLog.Info(
                    "VOYAGE_STASH_WITHDRAW|Tab=" + tabName +
                    "|Id=" + chart.Id +
                    "|LocalId=" + chart.LocalId +
                    "|Name=" + chart.FullName +
                    "|Result=" + result +
                    "|Action=ConfirmOnNextCycle" +
                    "|OneActionPerCycle=True");
                return true;
            }

            settings.LastVoyageStashTotal = Math.Max(
                0,
                charts.Count);
            settings.LastChartStorageScan =
                "VoyageStash:" + tabName + "=" +
                settings.LastVoyageStashTotal;
            settings.Save();

            if (liveInventoryCharts > 0)
            {
                AllflameRunState.MarkVoyageStashProbeCompleted();
                AllflameRunState.MarkStorageChecked();
                AllflameLog.Info(
                    "VOYAGE_STASH_DONE|Tab=" + tabName +
                    "|StoredCharts=" +
                    settings.LastVoyageStashTotal +
                    "|InventoryCharts=" +
                    liveInventoryCharts +
                    "|Target=" + TargetInventoryCharts);
                AllflameLog.Info(
                    "VOYAGE_STASH_SOURCE_RESULT" +
                    "|Result=Success" +
                    "|Withdrawn=" + _stashWithdrawnCharts +
                    "|NextSource=None");
                AllflameLog.Info(
                    "CHART_SUPPLY_SUCCESS" +
                    "|Source=VoyageStash" +
                    "|InventoryCharts=" +
                    liveInventoryCharts);
                await Coroutines.CloseBlockingWindows();
                ResetLocalState();
                AllflameProgressWatchdog.Clear();
                return false;
            }

            AllflameLog.Info(
                "VOYAGE_STASH_EMPTY|Tab=" + tabName +
                "|InventoryCharts=0|Action=StopBot");
            AllflameRunState.MarkVoyageStashProbeCompleted();
            AllflameLog.Info(
                "VOYAGE_STASH_SOURCE_RESULT" +
                "|Result=Empty" +
                "|Withdrawn=0" +
                "|NextSource=None");
            await Coroutines.CloseBlockingWindows();
            AllflameLog.Info(
                "CHART_SUPPLY_FAILED" +
                "|Reason=AllEnabledSourcesEmpty" +
                "|NextAction=ControlledStop");
            AllflameStopController.Stop(
                "NoChartsRemaining",
                "VoyageStashTab=" + tabName +
                "|StoredCharts=0|InventoryCharts=0");
            return true;
        }

        private static int LoadedChartDeviceItemCount()
        {
            try
            {
                if (NativeDeepwaterChartDeviceUi.IsOpened)
                {
                    List<Item> nativeItems =
                        NativeDeepwaterChartDeviceUi.DeviceItems;
                    return nativeItems == null
                        ? 0
                        : nativeItems.Count;
                }

                if (!LokiPoe.InGameState.MapDeviceUi.IsOpened)
                {
                    return 0;
                }
                InventoryControlWrapper control =
                    LokiPoe.InGameState.MapDeviceUi.InventoryControl;
                return control == null ||
                       control.Inventory == null ||
                       control.Inventory.Items == null
                    ? 0
                    : control.Inventory.Items.Count(
                        AllflameContext.IsChartItem);
            }
            catch
            {
                return 0;
            }
        }

        private static int CountInventoryChartsLive()
        {
            try
            {
                InventoryControlWrapper control =
                    LokiPoe.InGameState.InventoryUi
                        .InventoryControl_Main;
                return control == null || control.Inventory == null ||
                       control.Inventory.Items == null
                    ? AllflameContext.InventoryChartCount
                    : control.Inventory.Items.Count(
                        AllflameContext.IsChartItem);
            }
            catch
            {
                return AllflameContext.InventoryChartCount;
            }
        }

        private enum VoyageStashApproachResult
        {
            Continue,
            ReadyToInteract,
            Failed
        }

        private void EnsureApproachTracking(NetworkObject stash)
        {
            if (_approachActive &&
                _approachAreaHash == AllflameContext.AreaHash &&
                _approachObjectId == stash.Id)
            {
                return;
            }

            ResetApproachTracking();
            DateTime now = DateTime.UtcNow;
            Vector2i player = LokiPoe.Me.Position;
            float distance = stash.Distance;
            _approachActive = true;
            _approachAreaHash = AllflameContext.AreaHash;
            _approachObjectId = stash.Id;
            _approachStashPosition = stash.Position;
            _approachStartedUtc = now;
            _approachLastProgressUtc = now;
            _approachBestDistance = distance;
            _approachProgressReference = distance;
            AllflameLog.Info(
                "VOYAGE_STASH_APPROACH_START" +
                "|ObjectId=" + stash.Id +
                "|StashPosition=" + stash.Position +
                "|Player=" + player +
                "|Distance=" + distance.ToString("0.0") +
                "|AreaHash=" + AllflameContext.AreaHash);
            AllflameMover mover = PlayerMoverManager.Current as AllflameMover;
            if (mover != null)
                mover.LogSelectedMovementSkill(true);
        }

        private VoyageStashApproachResult ContinueVoyageStashApproach(
            NetworkObject stash)
        {
            DateTime now = DateTime.UtcNow;
            Vector2i player = LokiPoe.Me.Position;
            float stashDistance = stash.Distance;
            if (now - _approachStartedUtc >=
                TimeSpan.FromSeconds(ApproachTimeoutSeconds))
            {
                return VoyageStashApproachResult.Failed;
            }

            UpdateApproachProgress(stashDistance, now);
            if (stashDistance <= AllflameSettings.Instance.InteractDistance)
                return VoyageStashApproachResult.ReadyToInteract;

            if (now < _approachCooldownUntilUtc)
                return VoyageStashApproachResult.Continue;

            if (!_alternateApproach &&
                now - _approachLastProgressUtc >=
                TimeSpan.FromSeconds(ApproachNoProgressSeconds))
            {
                AllflameLog.Info(
                    "VOYAGE_STASH_APPROACH_STALLED" +
                    "|Distance=" + stashDistance.ToString("0.0") +
                    "|BestDistance=" + _approachBestDistance.ToString("0.0") +
                    "|Moving=" + _lastApproachMoving +
                    "|ElapsedSeconds=" +
                    (now - _approachLastProgressUtc).TotalSeconds.ToString("0.0"));
                _alternateApproach = true;
                AllflameLog.Info(
                    "VOYAGE_STASH_APPROACH_RECOVERY" +
                    "|Attempt=" + (_triedAlternateCandidates.Count + 1) +
                    "|Reason=NoProgress" +
                    "|Action=SelectAlternateApproach");
            }

            if (_alternateApproach)
            {
                return ContinueAlternateApproach(
                    stash,
                    player,
                    stashDistance,
                    now);
            }

            bool moving = TryMoveTowards(
                stash.Position,
                Name);
            _lastApproachMoving = moving;
            if (!moving)
            {
                if (_approachPathFailureSinceUtc == DateTime.MinValue)
                    _approachPathFailureSinceUtc = now;
                if (now - _approachPathFailureSinceUtc >=
                    TimeSpan.FromSeconds(1))
                {
                    if (!RecoverApproach("PathFailure", now))
                        return VoyageStashApproachResult.Failed;
                }
            }
            else
            {
                _approachPathFailureSinceUtc = DateTime.MinValue;
            }

            LogApproachMovement(
                stash,
                player,
                stashDistance,
                moving,
                "Direct");
            return VoyageStashApproachResult.Continue;
        }

        private VoyageStashApproachResult ContinueAlternateApproach(
            NetworkObject stash,
            Vector2i player,
            float stashDistance,
            DateTime now)
        {
            if (!_hasAlternateCandidate)
            {
                if (_triedAlternateCandidates.Count >=
                    MaximumAlternateCandidates)
                {
                    return VoyageStashApproachResult.Failed;
                }
                if (!TrySelectAlternateCandidate(player, now))
                {
                    if (!RecoverApproach("NoPathableCandidate", now))
                        return VoyageStashApproachResult.Failed;
                    return VoyageStashApproachResult.Continue;
                }
            }

            float candidateDistance =
                player.DistanceF(_alternateCandidate);
            if (candidateDistance <= CandidateReachedDistance)
            {
                bool withinRange =
                    stashDistance <=
                    AllflameSettings.Instance.InteractDistance;
                AllflameLog.Info(
                    "VOYAGE_STASH_APPROACH_CANDIDATE_REACHED" +
                    "|Candidate=" + _alternateCandidate +
                    "|StashDistance=" + stashDistance.ToString("0.0") +
                    "|WithinInteractionRange=" + withinRange);
                MarkCurrentCandidateTried();
                if (withinRange)
                    return VoyageStashApproachResult.ReadyToInteract;
                if (_triedAlternateCandidates.Count >=
                    MaximumAlternateCandidates)
                {
                    return VoyageStashApproachResult.Failed;
                }
                return VoyageStashApproachResult.Continue;
            }

            if (now - _alternateCandidateSelectedUtc >=
                TimeSpan.FromSeconds(ApproachNoProgressSeconds))
            {
                MarkCurrentCandidateTried();
                AllflameLog.Info(
                    "VOYAGE_STASH_APPROACH_RECOVERY" +
                    "|Attempt=" + (_triedAlternateCandidates.Count + 1) +
                    "|Reason=CandidateNotReached" +
                    "|Action=SelectAlternateApproach");
                return _triedAlternateCandidates.Count >=
                    MaximumAlternateCandidates
                    ? VoyageStashApproachResult.Failed
                    : VoyageStashApproachResult.Continue;
            }

            bool moving = TryMoveTowards(
                _alternateCandidate,
                Name + " alternate Voyage Stash approach");
            _lastApproachMoving = moving;
            if (!moving)
            {
                if (_approachPathFailureSinceUtc == DateTime.MinValue)
                    _approachPathFailureSinceUtc = now;
                if (now - _approachPathFailureSinceUtc >=
                    TimeSpan.FromSeconds(1))
                {
                    MarkCurrentCandidateTried();
                    if (!RecoverApproach("PathFailure", now))
                        return VoyageStashApproachResult.Failed;
                }
            }
            else
            {
                _approachPathFailureSinceUtc = DateTime.MinValue;
            }

            LogApproachMovement(
                stash,
                player,
                stashDistance,
                moving,
                "Alternate");
            return VoyageStashApproachResult.Continue;
        }

        private bool TrySelectAlternateCandidate(
            Vector2i player,
            DateTime now)
        {
            Vector2i selected = new Vector2i();
            float selectedPlayerDistance = Single.MaxValue;
            int selectedRadius = 0;
            int selectedIndex = -1;
            for (int radiusIndex = 0;
                radiusIndex < AlternateCandidateRadii.Length;
                radiusIndex++)
            {
                int radius = AlternateCandidateRadii[radiusIndex];
                for (int index = 0; index < 16; index++)
                {
                    double angle = index * Math.PI * 2.0 / 16.0;
                    Vector2i candidate = new Vector2i(
                        _approachStashPosition.X +
                        (int)Math.Round(Math.Cos(angle) * radius),
                        _approachStashPosition.Y +
                        (int)Math.Round(Math.Sin(angle) * radius));
                    if (WasCandidateTried(candidate))
                        continue;
                    float playerDistance = player.DistanceF(candidate);
                    if (playerDistance < CandidateMinimumPlayerDistance ||
                        playerDistance >= selectedPlayerDistance)
                    {
                        continue;
                    }

                    bool pathExists = false;
                    try
                    {
                        PathfindingCommand command =
                            new PathfindingCommand(player, candidate, 3f);
                        pathExists =
                            ExilePather.FindPath(ref command) &&
                            command.Path != null &&
                            command.Path.Count > 0;
                    }
                    catch
                    {
                    }
                    if (!pathExists)
                        continue;

                    selected = candidate;
                    selectedPlayerDistance = playerDistance;
                    selectedRadius = radius;
                    selectedIndex = index;
                }
            }

            if (selectedIndex < 0)
            {
                AllflameLog.Info(
                    "VOYAGE_STASH_APPROACH_CANDIDATE" +
                    "|Candidate=None|Radius=0|Index=-1" +
                    "|PathExists=False" +
                    "|Attempt=" + (_triedAlternateCandidates.Count + 1));
                return false;
            }

            _hasAlternateCandidate = true;
            _alternateCandidate = selected;
            _alternateCandidateSelectedUtc = now;
            _approachPathFailureSinceUtc = DateTime.MinValue;
            AllflameLog.Info(
                "VOYAGE_STASH_APPROACH_CANDIDATE" +
                "|Candidate=" + selected +
                "|Radius=" + selectedRadius +
                "|Index=" + selectedIndex +
                "|PathExists=True" +
                "|Attempt=" + (_triedAlternateCandidates.Count + 1));
            return true;
        }

        private void UpdateApproachProgress(float distance, DateTime now)
        {
            if (distance >= _approachBestDistance)
                return;

            _approachBestDistance = distance;
            float improvement = _approachProgressReference - distance;
            if (improvement < ApproachProgressDistance)
                return;

            _approachProgressReference = distance;
            _approachLastProgressUtc = now;
            AllflameProgressWatchdog.MarkProgress(
                "VoyageStashDistanceImproved");
            AllflameLog.Info(
                "VOYAGE_STASH_APPROACH_PROGRESS" +
                "|Distance=" + distance.ToString("0.0") +
                "|BestDistance=" + _approachBestDistance.ToString("0.0") +
                "|Improvement=" + improvement.ToString("0.0") +
                "|NoProgressSeconds=0");
        }

        private bool RecoverApproach(string reason, DateTime now)
        {
            if (_approachRecoveries >= MaximumApproachRecoveries)
                return false;

            _approachRecoveries++;
            AllflameProgressWatchdog.SetRetry(_approachRecoveries);
            try
            {
                ExilePather.Reload(true);
            }
            catch
            {
            }
            AllflameMover mover = PlayerMoverManager.Current as AllflameMover;
            if (mover != null)
                mover.ResetApproachState();
            try
            {
                AllflameContext.Refresh(true);
            }
            catch
            {
            }
            _approachCooldownUntilUtc = now.AddMilliseconds(500);
            _approachPathFailureSinceUtc = DateTime.MinValue;
            AllflameLog.Info(
                "VOYAGE_STASH_APPROACH_RECOVERY" +
                "|Attempt=" + _approachRecoveries +
                "|Reason=" + reason +
                "|Action=ReloadPather");
            return true;
        }

        private void LogApproachMovement(
            NetworkObject stash,
            Vector2i player,
            float distance,
            bool moving,
            string mode)
        {
            AllflameLog.Throttled(
                "voyage_stash_approach_move",
                TimeSpan.FromSeconds(1),
                "ACTION|Task=" + Name +
                "|Action=MoveTo|Target=Voyage Stash" +
                "|TargetId=" + stash.Id +
                "|Player=" + player +
                "|Distance=" + distance.ToString("0.0") +
                "|InteractionRange=" +
                AllflameSettings.Instance.InteractDistance.ToString("0.0") +
                "|Moving=" + moving +
                "|BestDistance=" + _approachBestDistance.ToString("0.0") +
                "|NoProgressSeconds=" +
                Math.Max(
                    0,
                    (int)(DateTime.UtcNow -
                        _approachLastProgressUtc).TotalSeconds) +
                "|ApproachMode=" + mode +
                "|ApproachAttempt=" +
                (_triedAlternateCandidates.Count +
                    (_hasAlternateCandidate ? 1 : 0)));
        }

        private void LogApproachFailed(NetworkObject stash)
        {
            float currentDistance = stash == null
                ? Single.MaxValue
                : stash.Distance;
            AllflameLog.Info(
                "VOYAGE_STASH_APPROACH_FAILED" +
                "|ObjectId=" + _approachObjectId +
                "|BestDistance=" + _approachBestDistance.ToString("0.0") +
                "|CurrentDistance=" + currentDistance.ToString("0.0") +
                "|CandidatesTried=" +
                (_triedAlternateCandidates.Count +
                    (_hasAlternateCandidate ? 1 : 0)) +
                "|Recoveries=" + _approachRecoveries +
                "|ElapsedSeconds=" +
                Math.Max(
                    0,
                    (int)(DateTime.UtcNow -
                        _approachStartedUtc).TotalSeconds));
        }

        private void MarkCurrentCandidateTried()
        {
            if (_hasAlternateCandidate &&
                !WasCandidateTried(_alternateCandidate))
            {
                _triedAlternateCandidates.Add(_alternateCandidate);
            }
            _hasAlternateCandidate = false;
            _alternateCandidate = new Vector2i();
            _alternateCandidateSelectedUtc = DateTime.MinValue;
        }

        private bool WasCandidateTried(Vector2i candidate)
        {
            return _triedAlternateCandidates.Any(
                tried => tried.DistanceF(candidate) <= 2f);
        }

        private bool TryMoveTowards(Vector2i target, string context)
        {
            try
            {
                return AllflameMovementCoordinator.MoveTowards(target, context);
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "VOYAGE_STASH_APPROACH_MOVE_EXCEPTION" +
                    "|Target=" + target +
                    "|Type=" + ex.GetType().Name +
                    "|Message=" +
                    (ex.Message ?? String.Empty).Replace("|", "/"));
                return false;
            }
        }

        private async Task<bool> FailStash(
            string reason,
            string nextAction)
        {
            int inventoryCharts = AllflameContext.InventoryChartCount;
            string action = inventoryCharts > 0
                ? "ContinueWithInventoryCharts"
                : "ControlledStop";
            AllflameLog.Info(
                "VOYAGE_STASH_UNAVAILABLE" +
                "|Reason=" + reason +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|Attempts=" + Math.Max(_interactionAttempts, _tabAttempts) +
                "|InventoryCharts=" + inventoryCharts +
                "|NextAction=" + action +
                "|Recovery=" + (nextAction ?? String.Empty));
            AllflameRunState.MarkVoyageStashProbeCompleted();
            AllflameLog.Info(
                "VOYAGE_STASH_SOURCE_RESULT" +
                "|Result=Unavailable" +
                "|Reason=" + reason +
                "|Withdrawn=" + inventoryCharts +
                "|NextSource=None");
            await Coroutines.CloseBlockingWindows();
            ResetLocalState();
            if (inventoryCharts > 0)
            {
                AllflameProgressWatchdog.Clear(Name);
                AllflameRunState.MarkStorageChecked();
                return false;
            }
            AllflameLog.Info(
                "CHART_SUPPLY_FAILED" +
                "|Reason=AllEnabledSourcesUnavailable" +
                "|NextAction=ControlledStop");
            AllflameStopController.Stop(
                "VoyageStashUnavailable",
                "Reason=" + reason +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|InventoryCharts=0|NextAction=ControlledStop");
            return true;
        }

        private async Task RecoverBlockedStashUi(TimeSpan blockedFor)
        {
            _uiRecoveryCycles++;
            bool planningOpenBefore =
                AllflameContext.PlanVoyageVisible ||
                VoyagePlanningUi.IsOpen();

            await Coroutines.CloseBlockingWindows();
            await LokiCoroutine.Sleep(250);
            AllflameContext.Refresh(true);

            bool planningOpenAfterApi =
                AllflameContext.PlanVoyageVisible ||
                VoyagePlanningUi.IsOpen();
            bool spaceSent = false;
            if (planningOpenAfterApi)
            {
                LokiPoe.Input.SimulateKeyEvent(
                    System.Windows.Forms.Keys.Space,
                    true,
                    false,
                    true);
                spaceSent = true;
                await LokiCoroutine.Sleep(350);
                AllflameContext.Refresh(true);
            }

            bool planningOpenAfterRecovery =
                AllflameContext.PlanVoyageVisible ||
                VoyagePlanningUi.IsOpen();
            try
            {
                ExilePather.Reload(true);
            }
            catch
            {
            }

            AllflameLog.Info(
                "VOYAGE_STASH_UI_RECOVERY" +
                "|Cycle=" + _uiRecoveryCycles + "/" +
                MaximumUiRecoveryCycles +
                "|BlockedSeconds=" +
                blockedFor.TotalSeconds.ToString("0.0") +
                "|PlanningOpenBefore=" + planningOpenBefore +
                "|PlanningOpenAfterApi=" + planningOpenAfterApi +
                "|SpaceSent=" + spaceSent +
                "|PlanningOpenAfterRecovery=" +
                planningOpenAfterRecovery +
                "|Action=ReloadPathAndReacquireStash");

            _interactionAttempts = 0;
            _lastStashObjectId = 0;
            _stashInteractionBlockedUtc = DateTime.MinValue;
            AllflameProgressWatchdog.SetRetry(_uiRecoveryCycles);
            _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(800);
        }

        private void ResetApproachTracking()
        {
            _approachActive = false;
            _approachAreaHash = 0;
            _approachObjectId = 0;
            _approachStashPosition = new Vector2i();
            _approachStartedUtc = DateTime.MinValue;
            _approachLastProgressUtc = DateTime.MinValue;
            _approachCooldownUntilUtc = DateTime.MinValue;
            _approachPathFailureSinceUtc = DateTime.MinValue;
            _approachBestDistance = Single.MaxValue;
            _approachProgressReference = Single.MaxValue;
            _approachRecoveries = 0;
            _alternateApproach = false;
            _hasAlternateCandidate = false;
            _alternateCandidate = new Vector2i();
            _alternateCandidateSelectedUtc = DateTime.MinValue;
            _lastApproachMoving = false;
            _triedAlternateCandidates.Clear();
        }

        private void ResetLocalState()
        {
            _retryAfterUtc = DateTime.MinValue;
            _interactionAttempts = 0;
            _tabAttempts = 0;
            _lastStashObjectId = 0;
            _lastAreaHash = 0;
            _stashInteractionBlockedUtc = DateTime.MinValue;
            _uiRecoveryCycles = 0;
            _stashWithdrawPending = false;
            _stashWithdrawLocalId = 0;
            _stashWithdrawBeforeInventory = 0;
            _stashWithdrawIssuedUtc = DateTime.MinValue;
            _stashWithdrawnCharts = 0;
            ResetApproachTracking();
        }

        private static string ResolveStashTabName(string configured)
        {
            List<string> names =
                LokiPoe.InGameState.StashUi.TabControl.TabNames;
            if (names == null || names.Count == 0)
            {
                return String.Empty;
            }

            string exact = names.FirstOrDefault(name =>
                String.Equals(
                    name,
                    configured,
                    StringComparison.OrdinalIgnoreCase));
            if (!String.IsNullOrEmpty(exact))
            {
                return exact;
            }

            int number;
            if (Int32.TryParse(configured, out number) &&
                number >= 1 &&
                number <= names.Count)
            {
                return names[number - 1];
            }
            return String.Empty;
        }
    }

    internal sealed class OpenChartStorageTask : ObserverTask
    {
        private static int TargetInventoryCharts
        {
            get
            {
                return AllflameSettings.Instance.GetChartWithdrawalCount();
            }
        }
        private const int FullPageChartCount = 12;
        private const int MaximumOpenAttempts = 3;
        private const int StorageOpenTimeoutSeconds = 8;
        private const int StorageResolveTimeoutSeconds = 8;
        private int _stage;
        private int _mainTab;
        private int _subTab;
        private DateTime _scanAfterUtc;
        private DateTime _retryAfterUtc = DateTime.MinValue;
        private int _openAttempts;
        private int _resolveAttempts;
        private int _tabFailures;
        private int _activeMainTab = -1;
        private int _activeSubTab = -1;
        private int _tabSelectionMain = -1;
        private int _tabSelectionSub = -1;
        private int _tabSelectionStage;
        private int _tabSelectionStableReads;
        private string _tabSelectionLastSignature;
        private DateTime _tabSelectionDeadlineUtc = DateTime.MinValue;
        private DateTime _tabSelectionEmptyConfirmUtc = DateTime.MinValue;
        private readonly int[] _lastUsedSubTab = { -1, -1, -1 };
        private readonly int[,] _pageCounts = new int[3, 5];
        private readonly int[,] _sessionPageObserved = new int[3, 5];
        private readonly int[,] _sessionPageRemaining = new int[3, 5];
        private readonly int[,] _sessionPageWithdrawn = new int[3, 5];
        private readonly HashSet<string> _seenChartKeys =
            new HashSet<string>(StringComparer.Ordinal);
        private readonly HashSet<string> _mappedChartKeys =
            new HashSet<string>(StringComparer.Ordinal);
        private readonly HashSet<string> _skippedChartKeys =
            new HashSet<string>(StringComparer.Ordinal);
        private int _visitedPages;
        private int _withdrawnCharts;
        private int _rawItemsSeen;
        private int _nativeItems;
        private int _nativeRequestedId = -1;
        private bool _nativeBindFailed;
        private bool _rawWithdrawFailed;
        private bool _inventoryFull;
        private bool _rawWithdrawAwaitingVerification;
        private bool _inventoryFirstLogged;
        private int _rawWithdrawPendingKey;
        private int _rawWithdrawBeforeCount;
        private int _rawWithdrawFailures;
        private DateTime _rawWithdrawIssuedUtc = DateTime.MinValue;
        private InventoryControlWrapper _storageControl;
        private InventorySlotUiElement _storageSlot;
        private int _observedDepositRevision;
        private Task<bool> _storageOpenTask;
        private DateTime _storageOpenIssuedUtc = DateTime.MinValue;
        private DateTime _storageResolveDeadlineUtc = DateTime.MinValue;
        private bool _blockingWindowsPrepared;
        private int _storageUiRecoveryAttempts;

        private sealed class StorageChartEntry
        {
            public Item Item;
            public int RawKey;
            public Element RawElement;

            public string StableKey
            {
                get
                {
                    if (Item != null)
                    {
                        return Item.LocalId + "@" + Item.LocationTopLeft +
                            ":" + (Item.Metadata ?? Item.FullName ??
                            Item.Name ?? String.Empty);
                    }
                    Vector2i center = RawElement == null
                        ? new Vector2i()
                        : RawElement.CenterClickLocation();
                    return RawKey + "@0x" +
                        (RawElement == null
                            ? "0"
                            : RawElement.Address.ToString("X")) +
                        ":" + center;
                }
            }
        }

        public OpenChartStorageTask()
            : base("OpenChartStorageTask", "Probes and withdraws Chart Storage pages in forward order.")
        {
            ResetSessionPageCache();
            _observedDepositRevision = ChartStorageUi.DepositRevision;
        }

        public override void Start()
        {
            _inventoryFirstLogged = false;
            ResetSessionPageCache();
            _observedDepositRevision = ChartStorageUi.DepositRevision;
            ResetScan();
        }

        public override void Stop()
        {
            _inventoryFirstLogged = false;
            ResetScan();
            ResetSessionPageCache();
        }

        public override async Task<bool> Run()
        {
            if (_observedDepositRevision != ChartStorageUi.DepositRevision)
            {
                ResetSessionPageCache();
                _observedDepositRevision = ChartStorageUi.DepositRevision;
                AllflameLog.Info(
                    "CHART_STORAGE_PAGE_CACHE_INVALIDATED" +
                    "|Reason=DepositConfirmed" +
                    "|Revision=" + _observedDepositRevision);
            }
            AllflameSettings settings = AllflameSettings.Instance;
            bool inHub =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            if (!inHub)
            {
                ResetScan();
                return false;
            }

            if (DeferForVoyagePlanner())
            {
                return true;
            }

            if (settings.RunInventoryChartsOnly)
            {
                ResetScan();
                if (!AllflameRunState.ChartStorageProbeCompleted)
                {
                    AllflameRunState.MarkChartStorageProbeCompleted();
                    AllflameLog.Info(
                        "CHART_STORAGE_SKIPPED|Mode=InventoryChartsOnly" +
                        "|InventoryCharts=" +
                        AllflameContext.InventoryChartCount);
                }
                return false;
            }

            if (!settings.EnableChartStorageWithdrawal)
            {
                ResetScan();
                if (!AllflameRunState.ChartStorageProbeCompleted)
                {
                    AllflameRunState.MarkChartStorageProbeCompleted();
                    AllflameLog.Info(
                        "CHART_STORAGE_SOURCE_RESULT" +
                        "|Result=Disabled" +
                        "|Withdrawn=0" +
                        "|NextSource=" +
                        (settings.CheckVoyageStashFirst
                            ? "VoyageStash"
                            : "None"));
                }
                return false;
            }

            if (AllflameRunState.ChartStorageChecked)
            {
                return false;
            }
            if (AllflameRunState.ChartStorageProbeCompleted)
            {
                return false;
            }

            if (_stage == 0 &&
                AllflameContext.InventoryChartCount > 0)
            {
                if (!_inventoryFirstLogged)
                {
                    _inventoryFirstLogged = true;
                    AllflameLog.Info(
                        "STARTUP_CHART_POLICY" +
                        "|InventoryCharts=" +
                        AllflameContext.InventoryChartCount +
                        "|Action=RunInventoryFirst");
                    AllflameLog.Info(
                        "CHART_SOURCE_SELECTED" +
                        "|Source=Inventory" +
                        "|Count=" +
                        AllflameContext.InventoryChartCount);
                    AllflameLog.Info(
                        "CHART_STORAGE_WITHDRAW_SKIPPED" +
                        "|Reason=InventoryChartsAvailable" +
                        "|Count=" +
                        AllflameContext.InventoryChartCount);
                }
                AllflameRunState.MarkChartStorageProbeCompleted();
                AllflameRunState.MarkStorageChecked();
                ResetScan();
                return false;
            }

            if (_stage == 0 && AllSessionPagesDepleted())
            {
                return await CompleteSessionEmpty();
            }

            if (DateTime.UtcNow < _retryAfterUtc)
            {
                return true;
            }

            if (_stage == 0)
            {
                if (_storageOpenTask != null)
                {
                    return await ContinueStorageOpenInteraction();
                }

                // The fresh root check is intentionally cheap; the page-layer
                // resolver below is the first point that creates a storage
                // control or slot.
                if (ChartStorageUi.IsFreshlyVisible())
                {
                    _openAttempts = Math.Max(1, _openAttempts);
                    _stage = 1;
                    _scanAfterUtc = DateTime.UtcNow;
                    _storageResolveDeadlineUtc = DateTime.UtcNow.AddSeconds(
                        StorageResolveTimeoutSeconds);
                    AllflameLog.Info(
                        "CHART_STORAGE_STAGE" +
                        "|Stage=Resolve" +
                        "|Reason=FreshStorageRoot" +
                        "|Postcondition=PageLayerResolved");
                    return true;
                }

                NetworkObject storage = AllflameContext.ChartStorageObject;
                if (storage == null || !storage.IsValid)
                {
                    _openAttempts++;
                    AllflameLog.Info(
                        "CHART_STORAGE_RETRY" +
                        "|Attempt=" + _openAttempts +
                        "|Maximum=" + MaximumOpenAttempts +
                        "|Reason=ObjectMissing" +
                        "|NextAction=ReacquireStorage");
                    if (_openAttempts >= MaximumOpenAttempts)
                    {
                        return await CompleteSourceFailure(
                            "StorageObjectMissing");
                    }
                    AllflameContext.Refresh(false);
                    _retryAfterUtc = DateTime.UtcNow.AddSeconds(1);
                    return true;
                }

                AllflameProgressWatchdog.Begin(
                    Name,
                    storage.Id,
                    "Chart Storage");

                if (!_blockingWindowsPrepared)
                {
                    bool closed = true;
                    try
                    {
                        await Coroutines.CloseBlockingWindows();
                    }
                    catch (Exception ex)
                    {
                        closed = false;
                        AllflameLog.Info(
                            "CHART_STORAGE_UI_PREP_FAILED" +
                            "|Type=" + ex.GetType().Name +
                            "|Message=" +
                            (ex.Message ?? String.Empty).Replace("|", "/"));
                    }
                    _blockingWindowsPrepared = true;
                    AllflameLog.Info(
                        "CHART_STORAGE_UI_PREP" +
                        "|BlockingWindowsClosed=" + closed +
                        "|Action=PrepareBeforeInteract" +
                        "|Postcondition=NoBlockingUi");
                    AllflameProgressWatchdog.MarkProgress(
                        "ChartStorageUiPrepared");
                    _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(250);
                    return true;
                }

                if (storage.Distance > AllflameSettings.Instance.InteractDistance)
                {
                    await MoveOrInteract(storage, "Chart Storage");
                    return true;
                }

                _openAttempts++;
                AllflameLog.Info(
                    "CHART_STORAGE_STAGE" +
                    "|Stage=Interact" +
                    "|ObjectId=" + storage.Id +
                    "|Distance=" + storage.Distance.ToString("0.0") +
                    "|Attempt=" + _openAttempts +
                    "|Maximum=" + MaximumOpenAttempts +
                    "|Action=Interact" +
                    "|Postcondition=ChartStorageUi");
                _storageOpenIssuedUtc = DateTime.UtcNow;
                _storageOpenTask = InteractWithRecovery(
                    storage,
                    "Chart Storage");
                AllflameProgressWatchdog.MarkProgress(
                    "ChartStorageInteractionIssued");
                return true;
            }

            if (_stage == 1)
            {
                if (DateTime.UtcNow < _scanAfterUtc)
                {
                    return true;
                }

                if (!ChartStorageUi.IsFreshlyVisible())
                {
                    AllflameLog.Throttled(
                        "chart_storage_confirm_wait",
                        TimeSpan.FromSeconds(2),
                        "CHART_STORAGE_CONFIRM_WAIT" +
                        "|Stage=Confirm" +
                        "|Visible=False" +
                        "|Postcondition=ChartStorageUiVisible" +
                        "|ElapsedMs=" + Math.Max(
                            0,
                            (int)(DateTime.UtcNow -
                                _scanAfterUtc).TotalMilliseconds));
                    if (DateTime.UtcNow >= _storageResolveDeadlineUtc)
                    {
                        return await RecoverStorageUi(
                            "StorageUiVisibilityTimeout");
                    }
                    return true;
                }

                Stopwatch resolveTimer = Stopwatch.StartNew();
                bool resolved = TryResolveStorageUi();
                resolveTimer.Stop();
                AllflameLog.Info(
                    "CHART_STORAGE_RESOLVE" +
                    "|Stage=Confirm" +
                    "|Visible=True" +
                    "|Resolved=" + resolved +
                    "|ElapsedMs=" + resolveTimer.ElapsedMilliseconds +
                    "|Postcondition=PageLayerResolved");
                if (!resolved)
                {
                    _resolveAttempts++;
                    AllflameLog.Info(
                        "CHART_STORAGE_RETRY" +
                        "|Attempt=" + _resolveAttempts +
                        "|Maximum=" + MaximumOpenAttempts +
                        "|Reason=PageLayerNotResolved" +
                        "|NextAction=RetryResolve");
                    if (_resolveAttempts >= MaximumOpenAttempts ||
                        DateTime.UtcNow >= _storageResolveDeadlineUtc)
                    {
                        return await RecoverStorageUi(
                            "PageLayerNotResolved");
                    }
                    _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(350);
                    return true;
                }

                _resolveAttempts = 0;
                _openAttempts = 0;
                _storageResolveDeadlineUtc = DateTime.MinValue;
                AllflameProgressWatchdog.MarkProgress(
                    "ChartStoragePageResolved");
                BeginScan();
                return true;
            }

            if (_stage == 2)
            {
                if (!ChartStorageUi.IsFreshlyVisible())
                {
                    return await RecoverStorageUi(
                        "StorageUiLostDuringScan");
                }
                await ProbeCurrentPage();
                return true;
            }

            if (_stage == 3)
            {
                if (!ChartStorageUi.IsFreshlyVisible())
                {
                    return await RecoverStorageUi(
                        "StorageUiLostDuringWithdraw");
                }
                await WithdrawRawChartCycle();
                return true;
            }

            return true;
        }

        private bool DeferForVoyagePlanner()
        {
            DeepwaterVoyageSnapshot nativeSnapshot;
            if (NativeDeepwaterVoyageUi.TryCapture(
                    out nativeSnapshot))
            {
                if (!nativeSnapshot.IsOpened)
                {
                    return false;
                }

                ResetScan();
                AllflameLog.Throttled(
                    "chart_storage_deferred_voyage_native",
                    TimeSpan.FromSeconds(2),
                    "CHART_STORAGE_DEFERRED" +
                    "|Reason=VoyagePlannerOpen" +
                    "|Detection=DeepwaterVoyageSnapshot" +
                    "|Available=" +
                    nativeSnapshot.AvailableChartCount +
                    "|Board=" + nativeSnapshot.BoardChartCount +
                    "|BoardSlots=" + nativeSnapshot.BoardSlotCount +
                    "|BeginEnabled=" +
                    nativeSnapshot.BeginVoyageEnabled);
                return true;
            }

            VoyagePlanningUi.StableVoyageSnapshot stableSnapshot;
            if (VoyagePlanningUi.TryResolveStable(
                    out stableSnapshot))
            {
                ResetScan();
                AllflameLog.Throttled(
                    "chart_storage_deferred_voyage_stable",
                    TimeSpan.FromSeconds(2),
                    "CHART_STORAGE_DEFERRED" +
                    "|Reason=VoyagePlannerOpen" +
                    "|Detection=StableElement" +
                    "|RootIndex=" + stableSnapshot.RootIndex);
                return true;
            }

            return false;
        }

        private async Task<bool> ContinueStorageOpenInteraction()
        {
            Task<bool> openTask = _storageOpenTask;
            if (openTask == null)
            {
                return true;
            }

            DateTime now = DateTime.UtcNow;
            if (!openTask.IsCompleted)
            {
                TimeSpan elapsed = now - _storageOpenIssuedUtc;
                if (elapsed < TimeSpan.FromSeconds(StorageOpenTimeoutSeconds))
                {
                    AllflameLog.Throttled(
                        "chart_storage_interact_wait",
                        TimeSpan.FromSeconds(2),
                        "CHART_STORAGE_INTERACT_WAIT" +
                        "|Stage=Interact" +
                        "|Attempt=" + _openAttempts +
                        "|ElapsedMs=" + Math.Max(
                            0,
                            (int)elapsed.TotalMilliseconds) +
                        "|TimeoutSeconds=" + StorageOpenTimeoutSeconds +
                        "|Postcondition=InteractionCompleted");
                    return true;
                }

                _storageOpenTask = null;
                AllflameLog.Info(
                    "CHART_STORAGE_INTERACTION_TIMEOUT" +
                    "|Attempt=" + _openAttempts +
                    "|ElapsedMs=" + Math.Max(
                        0,
                        (int)elapsed.TotalMilliseconds) +
                    "|TimeoutSeconds=" + StorageOpenTimeoutSeconds +
                    "|Action=RefreshReacquire");
                return await RecoverStorageUi(
                    "StorageInteractionTimeout");
            }

            _storageOpenTask = null;
            bool interacted = false;
            try
            {
                interacted = await openTask;
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "CHART_STORAGE_OPEN_EXCEPTION" +
                    "|Type=" + ex.GetType().Name +
                    "|Message=" +
                    (ex.Message ?? String.Empty).Replace("|", "/"));
            }

            AllflameLog.Info(
                "CHART_STORAGE_OPEN" +
                "|InputSent=True" +
                "|Success=" + interacted +
                "|Attempt=" + _openAttempts +
                "|Maximum=" + MaximumOpenAttempts +
                "|Postcondition=AwaitChartStorageUi");
            if (!interacted)
            {
                if (_openAttempts >= MaximumOpenAttempts)
                {
                    return await CompleteSourceFailure(
                        "StorageInteractionRejected");
                }
                _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(600);
                return true;
            }

            _stage = 1;
            _scanAfterUtc = DateTime.UtcNow.AddMilliseconds(1200);
            _storageResolveDeadlineUtc = DateTime.UtcNow.AddSeconds(
                StorageResolveTimeoutSeconds);
            _resolveAttempts = 0;
            AllflameProgressWatchdog.MarkProgress(
                "ChartStorageUiOpened");
            return true;
        }

        private async Task<bool> RecoverStorageUi(string reason)
        {
            DateTime startedUtc = DateTime.UtcNow;
            AllflameLog.Info(
                "CHART_STORAGE_UI_RECOVERY" +
                "|Reason=" + reason +
                "|Attempt=" + _openAttempts +
                "|Action=CloseRefreshReacquire");
            try
            {
                await Coroutines.CloseBlockingWindows();
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "CHART_STORAGE_UI_RECOVERY_CLOSE_FAILED" +
                    "|Type=" + ex.GetType().Name);
            }
            try
            {
                AllflameContext.Refresh(true);
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "CHART_STORAGE_UI_RECOVERY_REFRESH_FAILED" +
                    "|Type=" + ex.GetType().Name);
            }
            try
            {
                ExilePather.Reload(true);
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "CHART_STORAGE_UI_RECOVERY_PATH_FAILED" +
                    "|Type=" + ex.GetType().Name);
            }

            _stage = 0;
            _storageOpenTask = null;
            _storageOpenIssuedUtc = DateTime.MinValue;
            _storageResolveDeadlineUtc = DateTime.MinValue;
            _blockingWindowsPrepared = false;
            _storageUiRecoveryAttempts++;
            _resolveAttempts = 0;
            _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(800);
            AllflameProgressWatchdog.SetRetry(_openAttempts);
            AllflameLog.Info(
                "CHART_STORAGE_UI_RECOVERY_DONE" +
                "|Reason=" + reason +
                "|Attempt=" + _openAttempts +
                "|RecoveryAttempt=" + _storageUiRecoveryAttempts +
                "|ElapsedMs=" + Math.Max(
                    0,
                    (int)(DateTime.UtcNow - startedUtc).TotalMilliseconds) +
                "|NextAction=" + (_openAttempts >= MaximumOpenAttempts ||
                    _storageUiRecoveryAttempts >= MaximumOpenAttempts
                    ? "VoyageStashFallback"
                    : "RetryStorage"));
            if (_openAttempts >= MaximumOpenAttempts ||
                _storageUiRecoveryAttempts >= MaximumOpenAttempts)
            {
                return await CompleteSourceFailure(reason);
            }
            return true;
        }

        private void BeginScan()
        {
            _storageUiRecoveryAttempts = 0;
            ResetTabSelection();
            _mainTab = -1;
            _subTab = -1;
            _activeMainTab = -1;
            _activeSubTab = -1;
            _seenChartKeys.Clear();
            _mappedChartKeys.Clear();
            _skippedChartKeys.Clear();
            _visitedPages = 0;
            _withdrawnCharts = 0;
            _rawItemsSeen = 0;
            _nativeItems = 0;
            _nativeRequestedId = -1;
            _nativeBindFailed = false;
            _rawWithdrawFailed = false;
            _inventoryFull = false;
            for (int main = 0; main < 3; main++)
            {
                _lastUsedSubTab[main] = -1;
                for (int sub = 0; sub < 5; sub++)
                {
                    _pageCounts[main, sub] = -1;
                }
            }
            MoveToNextSessionPage(0);
            _stage = 2;
            AllflameLog.Info(
                "CHART_SUPPLY_START" +
                "|ChartStorageEnabled=" +
                AllflameSettings.Instance.EnableChartStorageWithdrawal +
                "|VoyageStashEnabled=" +
                AllflameSettings.Instance.CheckVoyageStashFirst +
                "|InventoryCharts=" +
                AllflameContext.InventoryChartCount);
            AllflameLog.Info(
                "CHART_STORAGE_PROBE_BEGIN|Direction=1_TO_5|FullPage=" +
                FullPageChartCount + "|TargetInventory=" + TargetInventoryCharts +
                "|InventoryCharts=" + AllflameContext.InventoryChartCount +
                "|SessionRemaining=" + GetSessionRemainingCharts() +
                "|SessionDepletedPages=" + CountSessionDepletedPages());
        }

        private async Task ProbeCurrentPage()
        {
            if (_mainTab < 0 || _mainTab >= 3 ||
                _subTab < 0 || _subTab >= 5)
            {
                await FinishScan();
                return;
            }

            StorageTabSelectionResult selection =
                await SelectStorageTab(_mainTab, _subTab);
            if (selection == StorageTabSelectionResult.Pending)
            {
                return;
            }
            if (selection == StorageTabSelectionResult.Failed)
            {
                _tabFailures++;
                if (_tabFailures >= 3)
                {
                    await CompleteSourceFailure(
                        "StorageTabSelectionFailed");
                }
                return;
            }
            _tabFailures = 0;
            List<StorageChartEntry> charts = ReadCurrentStorageCharts();
            RememberPage(_mainTab, _subTab, charts);
            _visitedPages++;
            _rawItemsSeen += charts.Count;

            bool isFull = charts.Count >= FullPageChartCount;
            int mapped = charts.Count(chart => chart.Item != null);
            AllflameLog.Info(
                "CHART_STORAGE_RAW_PAGE_SCAN|Main=" + (_mainTab + 1) +
                "|Sub=" + (_subTab + 1) +
                "|RawItems=" + charts.Count +
                "|MappedCharts=" + mapped +
                "|Mode=" + (HasNativeStorageInventory()
                    ? "ServerInventory"
                    : "RawGrid") +
                "|Full=" + isFull +
                "|Sequence=" + (_mainTab * 5 + _subTab + 1) +
                "/15");

            ResetRawWithdrawCycle();
            _stage = 3;
        }

        private async Task WithdrawRawChartCycle()
        {
            AllflameContext.RefreshInventory(true);
            if (AllflameContext.InventoryChartCount >=
                TargetInventoryCharts)
            {
                await FinishScan();
                return;
            }
            if (AllflameContext.InventoryFreeSquares <= 0)
            {
                _inventoryFull = true;
                await FinishScan();
                return;
            }

            if (!TryResolveStorageUi(_mainTab, _subTab))
            {
                _rawWithdrawFailures++;
                if (_rawWithdrawFailures >= 3)
                {
                    _rawWithdrawFailed = true;
                    await FinishScan();
                }
                else
                {
                    _retryAfterUtc =
                        DateTime.UtcNow.AddMilliseconds(150);
                }
                return;
            }
            if (_rawWithdrawFailures >= 3)
            {
                _rawWithdrawFailed = true;
                await FinishScan();
                return;
            }

            List<KeyValuePair<int, Element>> rawItems =
                ChartStorageUi.GetRawItemElements(_storageSlot);
            if (_rawWithdrawAwaitingVerification)
            {
                bool moved =
                    rawItems.Count < _rawWithdrawBeforeCount ||
                    !rawItems.Any(pair =>
                        pair.Key == _rawWithdrawPendingKey);
                if (moved)
                {
                    _withdrawnCharts++;
                    UpdateSessionPageCache(
                        _mainTab,
                        _subTab,
                        rawItems.Count,
                        true,
                        "ConfirmedWithdraw");
                    AllflameProgressWatchdog.MarkProgress(
                        "ChartStorageRawChartTransferred");
                    AllflameLog.Info(
                        "CHART_STORAGE_WITHDRAW_CONFIRMED" +
                        "|Main=" + (_mainTab + 1) +
                        "|Sub=" + (_subTab + 1) +
                        "|RawKey=" + _rawWithdrawPendingKey +
                        "|Before=" + _rawWithdrawBeforeCount +
                        "|After=" + rawItems.Count +
                        "|TotalWithdrawn=" + _withdrawnCharts +
                        "|Action=ReturnToTaskManager");
                    ResetRawWithdrawCycle();
                    return;
                }
                if (DateTime.UtcNow - _rawWithdrawIssuedUtc <
                    TimeSpan.FromMilliseconds(900))
                {
                    return;
                }

                _rawWithdrawAwaitingVerification = false;
                _rawWithdrawFailures++;
                AllflameLog.Info(
                    "CHART_STORAGE_WITHDRAW_REJECTED" +
                    "|Main=" + (_mainTab + 1) +
                    "|Sub=" + (_subTab + 1) +
                    "|RawKey=" + _rawWithdrawPendingKey +
                    "|Failure=" + _rawWithdrawFailures + "/3" +
                    "|Action=" + (_rawWithdrawFailures >= 3
                        ? "StopSource"
                        : "RetryFreshElement"));
                if (_rawWithdrawFailures >= 3)
                {
                    _rawWithdrawFailed = true;
                    await FinishScan();
                }
                return;
            }

            if (rawItems.Count == 0)
            {
                UpdateSessionPageCache(
                    _mainTab,
                    _subTab,
                    0,
                    false,
                    "ConfirmedEmpty");
                int nextPage = _mainTab * 5 + _subTab + 1;
                if (MoveToNextSessionPage(nextPage))
                {
                    ResetRawWithdrawCycle();
                    _stage = 2;
                    return;
                }
                await FinishScan();
                return;
            }

            KeyValuePair<int, Element> rawItem = rawItems[0];
            bool clicked = await CtrlClickRawChart(rawItem.Value);
            _rawWithdrawPendingKey = rawItem.Key;
            _rawWithdrawBeforeCount = rawItems.Count;
            _rawWithdrawIssuedUtc = DateTime.UtcNow;
            _rawWithdrawAwaitingVerification = clicked;
            _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(100);
            AllflameLog.Info(
                "CHART_STORAGE_WITHDRAW_ISSUED" +
                "|Main=" + (_mainTab + 1) +
                "|Sub=" + (_subTab + 1) +
                "|RawKey=" + rawItem.Key +
                "|Before=" + rawItems.Count +
                "|Clicked=" + clicked +
                "|Action=ReturnToTaskManager");
            if (!clicked)
            {
                _rawWithdrawFailures++;
            }
        }

        private enum StorageTabSelectionResult
        {
            Pending,
            Ready,
            Failed
        }

        private void ResetRawWithdrawCycle()
        {
            _rawWithdrawAwaitingVerification = false;
            _rawWithdrawPendingKey = 0;
            _rawWithdrawBeforeCount = 0;
            _rawWithdrawFailures = 0;
            _rawWithdrawIssuedUtc = DateTime.MinValue;
        }

        private void RememberPage(
            int mainTab,
            int subTab,
            IEnumerable<StorageChartEntry> charts)
        {
            List<StorageChartEntry> page = charts == null
                ? new List<StorageChartEntry>()
                : charts.ToList();
            _pageCounts[mainTab, subTab] = page.Count;
            UpdateSessionPageCache(
                mainTab,
                subTab,
                page.Count,
                false,
                "StablePageRead");
            foreach (StorageChartEntry chart in page)
            {
                _seenChartKeys.Add(
                    mainTab + ":" + subTab + ":" +
                    chart.StableKey);
            }
        }

        private List<StorageChartEntry> ReadCurrentStorageCharts()
        {
            List<KeyValuePair<int, Element>> rawItems =
                ChartStorageUi.GetRawItemElements(_storageSlot);
            List<Item> nativeItems =
                _storageControl == null ||
                _storageControl.Inventory == null ||
                _storageControl.Inventory.Items == null
                    ? new List<Item>()
                    : _storageControl.Inventory.Items;
            bool nativeAvailable = HasNativeStorageInventory();
            var output = new List<StorageChartEntry>();
            foreach (KeyValuePair<int, Element> rawItem in rawItems)
            {
                Item nativeItem = nativeItems.FirstOrDefault(item =>
                    item != null &&
                    item.IsValid &&
                    item.LocalId == rawItem.Key &&
                    AllflameContext.IsChartItem(item));
                if (nativeItem == null)
                {
                    if (nativeAvailable)
                    {
                        _skippedChartKeys.Add(
                            _activeMainTab + ":" +
                            _activeSubTab + ":" + rawItem.Key);
                        AllflameLog.Throttled(
                            "chart_storage_unmatched_" + rawItem.Key,
                            TimeSpan.FromSeconds(3),
                            "CHART_STORAGE_ITEM_SKIPPED" +
                            "|Reason=NativeLocalIdNotMatched" +
                            "|RawKey=" + rawItem.Key +
                            "|Main=" + (_activeMainTab + 1) +
                            "|Sub=" + (_activeSubTab + 1));
                    }
                    output.Add(new StorageChartEntry
                    {
                        RawKey = rawItem.Key,
                        RawElement = rawItem.Value
                    });
                    continue;
                }
                string pageKey = _activeMainTab + ":" +
                    _activeSubTab + ":" + rawItem.Key;
                _mappedChartKeys.Add(pageKey);
                AllflameLog.Throttled(
                    "chart_storage_mapped_" + pageKey,
                    TimeSpan.FromSeconds(10),
                    "CHART_STORAGE_ITEM_MAPPED" +
                    "|Main=" + (_activeMainTab + 1) +
                    "|Sub=" + (_activeSubTab + 1) +
                    "|RawKey=" + rawItem.Key +
                    "|LocalId=" + nativeItem.LocalId +
                    "|Metadata=" + nativeItem.Metadata);
                output.Add(new StorageChartEntry
                {
                    Item = nativeItem,
                    RawKey = rawItem.Key,
                    RawElement = rawItem.Value
                });
            }
            return output;
        }

        private bool HasNativeStorageInventory()
        {
            try
            {
                bool valid = _storageControl != null &&
                    _storageControl.Inventory != null &&
                    _storageControl.Inventory.IsValid &&
                    ChartStorageUi.IsStorageInventoryShape(
                        _storageControl.Inventory);
                if (valid)
                {
                    _nativeRequestedId =
                        ChartStorageUi.BoundRequestedInventoryId;
                    _nativeItems = _storageControl.Inventory.Items == null
                        ? 0
                        : _storageControl.Inventory.Items.Count;
                }
                return valid;
            }
            catch
            {
                return false;
            }
        }

        private async Task<StorageTabSelectionResult> SelectStorageTab(
            int mainTab,
            int subTab)
        {
            await Task.CompletedTask;
            DateTime now = DateTime.UtcNow;
            if (_tabSelectionMain != mainTab ||
                _tabSelectionSub != subTab)
            {
                ResetTabSelection();
                _tabSelectionMain = mainTab;
                _tabSelectionSub = subTab;
                _tabSelectionStage = 0;
            }

            if (_tabSelectionStage == 0)
            {
                if (ChartStorageUi.IsMainTabActive(mainTab))
                {
                    _activeMainTab = mainTab;
                    _activeSubTab = -1;
                    _tabSelectionStage = 2;
                }
                else
                {
                    bool clicked = ChartStorageUi.TryClickMainTab(mainTab);
                    _tabSelectionDeadlineUtc =
                        now.AddSeconds(2);
                    _tabSelectionStage = clicked ? 1 : 0;
                    AllflameLog.Info(
                        "CHART_STORAGE_TAB_ACTION" +
                        "|Action=SelectMain" +
                        "|Main=" + (mainTab + 1) +
                        "|Clicked=" + clicked +
                        "|OneActionPerCycle=True");
                    return clicked
                        ? StorageTabSelectionResult.Pending
                        : FailTabSelection("MainTabMissing");
                }
            }

            if (_tabSelectionStage == 1)
            {
                if (ChartStorageUi.IsMainTabActive(mainTab))
                {
                    _activeMainTab = mainTab;
                    _activeSubTab = -1;
                    _tabSelectionStage = 2;
                }
                else
                {
                    return now < _tabSelectionDeadlineUtc
                        ? StorageTabSelectionResult.Pending
                        : FailTabSelection("MainTabNotActive");
                }
            }

            if (_tabSelectionStage == 2)
            {
                if (ChartStorageUi.IsPageActive(mainTab, subTab))
                {
                    _activeSubTab = subTab;
                    BeginTabStabilityObservation(now);
                }
                else
                {
                    bool clicked = ChartStorageUi.TryClickSubTab(
                        mainTab,
                        subTab);
                    _tabSelectionDeadlineUtc =
                        now.AddSeconds(2);
                    _tabSelectionStage = clicked ? 3 : 2;
                    AllflameLog.Info(
                        "CHART_STORAGE_TAB_ACTION" +
                        "|Action=SelectSub" +
                        "|Main=" + (mainTab + 1) +
                        "|Sub=" + (subTab + 1) +
                        "|Clicked=" + clicked +
                        "|OneActionPerCycle=True");
                    return clicked
                        ? StorageTabSelectionResult.Pending
                        : FailTabSelection("SubTabMissing");
                }
            }

            if (_tabSelectionStage == 3)
            {
                if (ChartStorageUi.IsPageActive(mainTab, subTab))
                {
                    _activeSubTab = subTab;
                    BeginTabStabilityObservation(now);
                }
                else
                {
                    return now < _tabSelectionDeadlineUtc
                        ? StorageTabSelectionResult.Pending
                        : FailTabSelection("PageNotActive");
                }
            }

            if (!ChartStorageUi.IsPageActive(mainTab, subTab))
            {
                return FailTabSelection("PageLostDuringStability");
            }

            string signature = null;
            bool resolved = TryResolveStorageUi(mainTab, subTab) &&
                _storageSlot != null;
            if (resolved)
            {
                signature = CurrentStoragePageSignature();
                _tabSelectionStableReads = String.Equals(
                    signature,
                    _tabSelectionLastSignature,
                    StringComparison.Ordinal)
                        ? _tabSelectionStableReads + 1
                        : 1;
                _tabSelectionLastSignature = signature;
            }
            bool emptyStable = signature != null &&
                (signature.Length > 0 ||
                 now >= _tabSelectionEmptyConfirmUtc);
            bool confirmed = resolved &&
                _tabSelectionStableReads >= 2 &&
                emptyStable;
            if (confirmed)
            {
                AllflameLog.Info(
                    "CHART_STORAGE_TAB_CONFIRMED" +
                    "|Main=" + (mainTab + 1) +
                    "|Sub=" + (subTab + 1) +
                    "|Mode=" + (HasNativeStorageInventory()
                        ? "ServerInventory"
                        : "RawGrid") +
                    "|StableReads=" + _tabSelectionStableReads +
                    "|Signature=" +
                    SanitizeStorageSignature(signature) +
                    "|OneActionPerCycle=True" +
                    "|Confirmed=True");
                return StorageTabSelectionResult.Ready;
            }
            if (now >= _tabSelectionDeadlineUtc)
            {
                return FailTabSelection("PageLayerNotStable");
            }
            return StorageTabSelectionResult.Pending;
        }

        private void BeginTabStabilityObservation(DateTime now)
        {
            _tabSelectionStage = 4;
            _tabSelectionStableReads = 0;
            _tabSelectionLastSignature = null;
            _tabSelectionEmptyConfirmUtc =
                now.AddMilliseconds(220);
            _tabSelectionDeadlineUtc = now.AddSeconds(2);
        }

        private StorageTabSelectionResult FailTabSelection(
            string reason)
        {
            AllflameLog.Info(
                "CHART_STORAGE_TAB_FAILED" +
                "|Reason=" + reason +
                "|Main=" + (_tabSelectionMain + 1) +
                "|Sub=" + (_tabSelectionSub + 1) +
                "|Stage=" + _tabSelectionStage);
            ResetTabSelection();
            return StorageTabSelectionResult.Failed;
        }

        private void ResetTabSelection()
        {
            _tabSelectionMain = -1;
            _tabSelectionSub = -1;
            _tabSelectionStage = 0;
            _tabSelectionStableReads = 0;
            _tabSelectionLastSignature = null;
            _tabSelectionDeadlineUtc = DateTime.MinValue;
            _tabSelectionEmptyConfirmUtc = DateTime.MinValue;
        }

        private string CurrentStoragePageSignature()
        {
            return String.Join(
                ";",
                ChartStorageUi.GetRawItemElements(_storageSlot)
                    .Select(pair => pair.Key)
                    .OrderBy(key => key)
                    .ToArray());
        }

        private static async Task<bool> CtrlClickRawChart(Element element)
        {
            try
            {
                if (element == null ||
                    !element.IsValid ||
                    !element.IsVisible)
                {
                    return false;
                }

                Vector2i location = element.CenterClickLocation();
                bool controlDown = false;
                try
                {
                    LokiPoe.ProcessHookManager.ClearAllKeyStates();
                    DreamPoeBot.BotFramework.MouseManager
                        .SetMousePosition(location, true);
                    LokiPoe.ProcessHookManager.SetKeyState(
                        System.Windows.Forms.Keys.ControlKey,
                        short.MinValue,
                        System.Windows.Forms.Keys.None);
                    controlDown = true;
                    await LokiCoroutine.Sleep(25);
                    DreamPoeBot.BotFramework.MouseManager.ClickLMB(0, 0);
                    await LokiCoroutine.Sleep(90);
                    return true;
                }
                finally
                {
                    if (controlDown)
                    {
                        LokiPoe.ProcessHookManager.SetKeyState(
                            System.Windows.Forms.Keys.ControlKey,
                            (short)0,
                            System.Windows.Forms.Keys.None);
                    }
                    LokiPoe.ProcessHookManager.ClearAllKeyStates();
                }
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "CHART_STORAGE_RAW_CLICK_FAILED|" +
                    ex.GetType().Name + "|" +
                    (ex.Message ?? String.Empty).Replace("|", "/"));
                return false;
            }
        }

        private static string SanitizeStorageSignature(string signature)
        {
            if (signature == null)
            {
                return "<none>";
            }
            if (signature.Length == 0)
            {
                return "<empty>";
            }
            return signature.Replace("|", "/");
        }

        private bool TryResolveStorageUi()
        {
            InventoryControlWrapper resolvedControl;
            InventorySlotUiElement resolvedSlot;
            if (ChartStorageUi.TryResolve(
                _storageControl,
                _storageSlot,
                out resolvedControl,
                out resolvedSlot))
            {
                _storageControl = resolvedControl;
                _storageSlot = resolvedSlot;
                return true;
            }

            return false;
        }

        private bool TryResolveStorageUi(int mainTab, int subTab)
        {
            InventoryControlWrapper resolvedControl;
            InventorySlotUiElement resolvedSlot;
            if (ChartStorageUi.TryResolve(
                mainTab,
                subTab,
                _storageControl,
                _storageSlot,
                out resolvedControl,
                out resolvedSlot))
            {
                _storageControl = resolvedControl;
                _storageSlot = resolvedSlot;
                return true;
            }

            return false;
        }

        private string BuildStorageSnapshot()
        {
            var output = new List<string>();
            for (int main = 0; main < 3; main++)
            {
                for (int sub = 0; sub < 5; sub++)
                {
                    if (_sessionPageRemaining[main, sub] >= 0)
                    {
                        output.Add(
                            "M" + (main + 1) +
                            "S" + (sub + 1) +
                            "=" + _sessionPageRemaining[main, sub]);
                    }
                }
            }
            return String.Join(",", output.ToArray());
        }

        private async Task FinishScan()
        {
            AllflameContext.RefreshInventory(true);
            AllflameSettings settings = AllflameSettings.Instance;
            settings.LastChartStorageTotal = GetSessionRemainingCharts();
            settings.LastChartStorageScan = BuildStorageSnapshot();
            settings.Save();

            AllflameLog.Info(
                "CHART_STORAGE_SCAN_DONE|StoredUnique=" + _seenChartKeys.Count +
                "|MainTabsVisited=" + CountVisitedMainTabs() +
                "|PagesVisited=" + _visitedPages + "/15" +
                "|RawItemsSeen=" + _rawItemsSeen +
                "|NativeRequestedId=" + _nativeRequestedId +
                "|NativeItems=" + _nativeItems +
                "|ChartsMatched=" + _mappedChartKeys.Count +
                "|ChartsSkipped=" + _skippedChartKeys.Count +
                "|ChartsWithdrawn=" + _withdrawnCharts +
                "|InventoryCharts=" + AllflameContext.InventoryChartCount +
                "|Target=" + TargetInventoryCharts +
                "|NativeBindFailed=" + _nativeBindFailed +
                "|RawWithdrawFailed=" + _rawWithdrawFailed +
                "|InventoryFull=" + _inventoryFull +
                "|SessionRemaining=" + GetSessionRemainingCharts() +
                "|SessionDepletedPages=" + CountSessionDepletedPages() +
                "|Mode=RawGridWithdrawForward" +
                "|Tabs=" + settings.LastChartStorageScan);

            await Coroutines.CloseBlockingWindows();
            AllflameRunState.MarkChartStorageProbeCompleted();
            bool hasInventoryCharts =
                AllflameContext.InventoryChartCount > 0;
            bool reachedTarget =
                AllflameContext.InventoryChartCount >= TargetInventoryCharts;
            bool stashTopUpEnabled =
                settings.CheckVoyageStashFirst &&
                !_inventoryFull;
            if (hasInventoryCharts && reachedTarget)
            {
                AllflameRunState.MarkStorageChecked();
                AllflameLog.Info(
                    "CHART_STORAGE_SOURCE_RESULT" +
                    "|Result=" + (_inventoryFull
                        ? "PartialInventoryFull"
                        : (_rawWithdrawFailed
                            ? "PartialRawWithdrawFailed"
                            : "Success")) +
                    "|Withdrawn=" + _withdrawnCharts +
                    "|NextSource=None");
                AllflameLog.Info(
                    "CHART_SUPPLY_SUCCESS" +
                    "|Source=ChartStorage" +
                    "|InventoryCharts=" +
                    AllflameContext.InventoryChartCount);
            }
            else if (hasInventoryCharts && stashTopUpEnabled)
            {
                AllflameLog.Info(
                    "CHART_STORAGE_SOURCE_RESULT" +
                    "|Result=PartialNeedsVoyageStash" +
                    "|Withdrawn=" + _withdrawnCharts +
                    "|InventoryCharts=" +
                    AllflameContext.InventoryChartCount +
                    "|Target=" + TargetInventoryCharts +
                    "|NextSource=VoyageStash");
                AllflameLog.Info(
                    "CHART_SUPPLY_FALLBACK" +
                    "|From=ChartStorage" +
                    "|To=VoyageStash" +
                    "|Reason=BelowTarget" +
                    "|Needed=" + Math.Max(
                        0,
                        TargetInventoryCharts -
                        AllflameContext.InventoryChartCount));
            }
            else if (hasInventoryCharts)
            {
                AllflameRunState.MarkStorageChecked();
                AllflameLog.Info(
                    "CHART_STORAGE_SOURCE_RESULT" +
                    "|Result=PartialSuccess" +
                    "|Withdrawn=" + _withdrawnCharts +
                    "|InventoryCharts=" +
                    AllflameContext.InventoryChartCount +
                    "|Target=" + TargetInventoryCharts +
                    "|NextSource=None");
            }
            else if (_inventoryFull)
            {
                AllflameRunState.MarkStorageChecked();
                AllflameLog.Info(
                    "CHART_STORAGE_SOURCE_RESULT" +
                    "|Result=InventoryFull" +
                    "|Withdrawn=0" +
                    "|NextSource=None");
            }
            else
            {
                AllflameLog.Info(
                    "CHART_STORAGE_SOURCE_RESULT" +
                    "|Result=" + (_rawWithdrawFailed
                        ? "RawWithdrawFailed"
                        : "Empty") +
                    "|Withdrawn=0" +
                    "|NextSource=" +
                    (AllflameSettings.Instance.CheckVoyageStashFirst
                        ? "VoyageStash"
                        : "None"));
                if (AllflameSettings.Instance.CheckVoyageStashFirst)
                {
                    AllflameLog.Info(
                        "CHART_SUPPLY_FALLBACK" +
                        "|From=ChartStorage" +
                        "|To=VoyageStash" +
                        "|Reason=" + (_rawWithdrawFailed
                            ? "RawWithdrawFailed"
                            : "Empty"));
                }
            }
            ResetScan();
        }

        private int CountVisitedMainTabs()
        {
            int count = 0;
            for (int main = 0; main < 3; main++)
            {
                bool visited = false;
                for (int sub = 0; sub < 5; sub++)
                {
                    if (_pageCounts[main, sub] >= 0)
                    {
                        visited = true;
                        break;
                    }
                }
                if (visited)
                {
                    count++;
                }
            }
            return count;
        }

        private bool MoveToNextSessionPage(int startPage)
        {
            int firstPage = Math.Max(0, startPage);
            for (int main = firstPage / 5; main < 3; main++)
            {
                int firstSub = main == firstPage / 5
                    ? firstPage % 5
                    : 0;
                if (firstSub == 0 && IsSessionMainDepleted(main))
                {
                    AllflameLog.Info(
                        "CHART_STORAGE_MAIN_SKIPPED" +
                        "|Reason=AllPagesDepleted" +
                        "|Main=" + (main + 1));
                    continue;
                }

                for (int sub = firstSub; sub < 5; sub++)
                {
                    if (_sessionPageRemaining[main, sub] == 0)
                    {
                        AllflameLog.Info(
                            "CHART_STORAGE_PAGE_SKIPPED" +
                            "|Reason=Depleted" +
                            "|Main=" + (main + 1) +
                            "|Sub=" + (sub + 1));
                        continue;
                    }
                    _mainTab = main;
                    _subTab = sub;
                    return true;
                }
            }

            _mainTab = 3;
            _subTab = 0;
            return false;
        }

        private void UpdateSessionPageCache(
            int mainTab,
            int subTab,
            int remaining,
            bool withdrewChart,
            string source)
        {
            if (mainTab < 0 || mainTab >= 3 ||
                subTab < 0 || subTab >= 5)
            {
                return;
            }

            int previous = _sessionPageRemaining[mainTab, subTab];
            int confirmedRemaining = Math.Max(0, remaining);
            if (withdrewChart)
            {
                _sessionPageWithdrawn[mainTab, subTab]++;
            }
            _sessionPageObserved[mainTab, subTab] = Math.Max(
                _sessionPageObserved[mainTab, subTab],
                confirmedRemaining +
                _sessionPageWithdrawn[mainTab, subTab]);
            _sessionPageRemaining[mainTab, subTab] = confirmedRemaining;

            AllflameLog.Info(
                "CHART_STORAGE_PAGE_CACHE_UPDATE" +
                "|Main=" + (mainTab + 1) +
                "|Sub=" + (subTab + 1) +
                "|Source=" + source +
                "|Previous=" + previous +
                "|Observed=" + _sessionPageObserved[mainTab, subTab] +
                "|Withdrawn=" + _sessionPageWithdrawn[mainTab, subTab] +
                "|Remaining=" + confirmedRemaining +
                "|State=" + (confirmedRemaining == 0
                    ? "Depleted"
                    : "Available"));
        }

        private bool IsSessionMainDepleted(int mainTab)
        {
            for (int sub = 0; sub < 5; sub++)
            {
                if (_sessionPageRemaining[mainTab, sub] != 0)
                {
                    return false;
                }
            }
            return true;
        }

        private bool AllSessionPagesDepleted()
        {
            return CountSessionDepletedPages() == 15;
        }

        private int CountSessionDepletedPages()
        {
            int depleted = 0;
            for (int main = 0; main < 3; main++)
            {
                for (int sub = 0; sub < 5; sub++)
                {
                    if (_sessionPageRemaining[main, sub] == 0)
                    {
                        depleted++;
                    }
                }
            }
            return depleted;
        }

        private int GetSessionRemainingCharts()
        {
            int remaining = 0;
            for (int main = 0; main < 3; main++)
            {
                for (int sub = 0; sub < 5; sub++)
                {
                    remaining += Math.Max(
                        0,
                        _sessionPageRemaining[main, sub]);
                }
            }
            return remaining;
        }

        private async Task<bool> CompleteSessionEmpty()
        {
            AllflameSettings settings = AllflameSettings.Instance;
            settings.LastChartStorageTotal = 0;
            settings.LastChartStorageScan = BuildStorageSnapshot();
            settings.Save();
            AllflameRunState.MarkChartStorageProbeCompleted();
            AllflameLog.Info(
                "CHART_STORAGE_SESSION_EMPTY" +
                "|DepletedPages=15/15" +
                "|Action=" + (settings.CheckVoyageStashFirst
                    ? "UseVoyageStash"
                    : "NoStorageRecheck"));
            AllflameLog.Info(
                "CHART_STORAGE_SOURCE_RESULT" +
                "|Result=SessionCacheEmpty" +
                "|Withdrawn=0" +
                "|NextSource=" + (settings.CheckVoyageStashFirst
                    ? "VoyageStash"
                    : "None"));
            ResetScan();
            await Task.CompletedTask;
            return false;
        }

        private void ResetSessionPageCache()
        {
            for (int main = 0; main < 3; main++)
            {
                for (int sub = 0; sub < 5; sub++)
                {
                    _sessionPageObserved[main, sub] = -1;
                    _sessionPageRemaining[main, sub] = -1;
                    _sessionPageWithdrawn[main, sub] = 0;
                }
            }
        }

        private async Task<bool> CompleteSourceFailure(string reason)
        {
            AllflameContext.RefreshInventory(true);
            bool hasInventoryCharts =
                AllflameContext.InventoryChartCount > 0;
            AllflameRunState.MarkChartStorageProbeCompleted();
            if (hasInventoryCharts)
            {
                AllflameRunState.MarkStorageChecked();
            }
            AllflameLog.Info(
                "CHART_STORAGE_SOURCE_RESULT" +
                "|Result=Unavailable" +
                "|Reason=" + reason +
                "|Withdrawn=" + AllflameContext.InventoryChartCount +
                "|NextSource=" +
                (hasInventoryCharts
                    ? "None"
                    : (AllflameSettings.Instance.CheckVoyageStashFirst
                        ? "VoyageStash"
                        : "None")));
            if (!hasInventoryCharts &&
                AllflameSettings.Instance.CheckVoyageStashFirst)
            {
                AllflameLog.Info(
                    "CHART_SUPPLY_FALLBACK" +
                    "|From=ChartStorage" +
                    "|To=VoyageStash" +
                    "|Reason=" + reason);
            }
            await Coroutines.CloseBlockingWindows();
            ResetScan();
            return false;
        }

        private void ResetScan()
        {
            ResetRawWithdrawCycle();
            ResetTabSelection();
            _stage = 0;
            _mainTab = 0;
            _subTab = 0;
            _seenChartKeys.Clear();
            _mappedChartKeys.Clear();
            _skippedChartKeys.Clear();
            _storageControl = null;
            _storageSlot = null;
            _scanAfterUtc = DateTime.MinValue;
            _retryAfterUtc = DateTime.MinValue;
            _openAttempts = 0;
            _resolveAttempts = 0;
            _tabFailures = 0;
            _activeMainTab = -1;
            _activeSubTab = -1;
            _visitedPages = 0;
            _withdrawnCharts = 0;
            _rawItemsSeen = 0;
            _nativeItems = 0;
            _nativeRequestedId = -1;
            _nativeBindFailed = false;
            _rawWithdrawFailed = false;
            _inventoryFull = false;
            _storageOpenTask = null;
            _storageOpenIssuedUtc = DateTime.MinValue;
            _storageResolveDeadlineUtc = DateTime.MinValue;
            _blockingWindowsPrepared = false;
            _storageUiRecoveryAttempts = 0;
        }
    }

    internal enum CapsuleUiAction
    {
        SendToSurface,
        CallBathysphere
    }

    internal sealed class CapsuleUiButtons
    {
        public Element Window;
        public Element Title;
        public Element SendToSurface;
        public Element CallBathysphere;
        public int RootIndex;
        public string DetectionMode;
        public int Visited;
    }

    /// <summary>
    /// Reads the Allflame Capsule through DPB's live Element tree. Some
    /// Deepwater builds do not publish the button captions through
    /// Element.Text, so a tightly constrained two-button layout is used as a
    /// secondary DPB-memory fallback. This intentionally does not inspect
    /// pixels or depend on the game window position.
    /// </summary>
    internal static class CapsuleDirectUi
    {
        private const int MaximumVisited = 1800;
        private const int MaximumStableVisited = 80;
        private const string StableWindowId =
            "deepwater_extraction_window";

        public static bool TryGetStableButtons(
            out CapsuleUiButtons buttons)
        {
            buttons = new CapsuleUiButtons();
            List<Element> roots;
            try
            {
                roots = LokiPoe.GetGuiElements();
            }
            catch
            {
                return false;
            }
            if (roots == null)
            {
                return false;
            }

            for (int rootIndex = 0;
                 rootIndex < roots.Count;
                 rootIndex++)
            {
                Element window = roots[rootIndex];
                if (!IsUsable(window) ||
                    !String.Equals(
                        SafeIdLabel(window),
                        StableWindowId,
                        StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                Element title = GetChild(GetChild(window, 3), 0);
                Element send = GetChild(GetChild(window, 6), 0);
                Element call = GetChild(GetChild(window, 7), 0);
                bool exact =
                    HasCaption(title, "Allflame Capsule") &&
                    HasCaption(send, "Send to Surface") &&
                    HasCaption(call, "Call Bathysphere");
                if (!HasCaption(send, "Send to Surface"))
                {
                    send = FindButtonInWindow(
                        window,
                        "Send to Surface");
                }
                if (!HasCaption(call, "Call Bathysphere"))
                {
                    call = FindButtonInWindow(
                        window,
                        "Call Bathysphere");
                }

                if (!IsUsable(send) ||
                    !IsUsable(call) ||
                    !TryGetValidatedCenter(send, out Vector2i sendCenter) ||
                    !TryGetValidatedCenter(call, out Vector2i callCenter))
                {
                    AllflameLog.Throttled(
                        "capsule_stable_incomplete",
                        TimeSpan.FromSeconds(2),
                        "CAPSULE_UI_STABLE" +
                        "|Resolved=False" +
                        "|RootIndex=" + rootIndex +
                        "|IdLabel=" + StableWindowId +
                        "|Title=" + IsUsable(title) +
                        "|Send=" + IsUsable(send) +
                        "|Call=" + IsUsable(call));
                    return false;
                }

                buttons.Window = window;
                buttons.Title = title;
                buttons.SendToSurface = send;
                buttons.CallBathysphere = call;
                buttons.RootIndex = rootIndex;
                buttons.DetectionMode = exact
                    ? "StableExtractionPath"
                    : "StableExtractionScopedText";
                AllflameLog.Throttled(
                    "capsule_stable_resolved",
                    TimeSpan.FromSeconds(2),
                    "CAPSULE_UI_STABLE" +
                    "|Resolved=True" +
                    "|IdLabel=" + StableWindowId +
                    "|RootIndex=" + rootIndex +
                    "|WindowAddress=0x" +
                    window.Address.ToString("X") +
                    "|Send=" + sendCenter +
                    "|SendEnabled=" + SafeEnabled(send) +
                    "|Call=" + callCenter +
                    "|CallEnabled=" + SafeEnabled(call) +
                    "|Mode=" + buttons.DetectionMode);
                return true;
            }
            return false;
        }

        public static bool TryGetButtons(
            bool allowGeometry,
            out CapsuleUiButtons buttons)
        {
            buttons = new CapsuleUiButtons();

            if (TryGetStableButtons(out buttons))
            {
                return true;
            }

            Element send =
                VoyagePlanningUi.FindButton("Send to Surface");
            Element call =
                VoyagePlanningUi.FindButton("Call Bathysphere");
            if (IsUsable(send) && IsUsable(call))
            {
                buttons.SendToSurface = send;
                buttons.CallBathysphere = call;
                buttons.DetectionMode = "DPBText";
                return true;
            }

            if (!allowGeometry)
            {
                return false;
            }

            List<Element> roots = LokiPoe.GetGuiElements();
            if (roots == null)
            {
                return false;
            }

            var candidates = new List<Element>();
            var addresses = new HashSet<long>();
            var visitedAddresses = new HashSet<long>();
            DateTime deadline =
                DateTime.UtcNow.AddMilliseconds(500);
            int visited = 0;
            for (int index = roots.Count - 1;
                 index >= 0 &&
                 visited < MaximumVisited &&
                 DateTime.UtcNow < deadline;
                 index--)
            {
                CollectButtonCandidates(
                    roots[index],
                    0,
                    candidates,
                    addresses,
                    visitedAddresses,
                    deadline,
                    ref visited);
            }
            buttons.Visited = visited;

            Element bestLeft = null;
            Element bestRight = null;
            double bestScore = Double.MaxValue;
            foreach (Element left in candidates)
            {
                Vector2i leftCenter;
                if (!TryCenter(left, out leftCenter))
                {
                    continue;
                }

                foreach (Element right in candidates)
                {
                    if (ReferenceEquals(left, right))
                    {
                        continue;
                    }

                    Vector2i rightCenter;
                    if (!TryCenter(right, out rightCenter) ||
                        rightCenter.X <= leftCenter.X)
                    {
                        continue;
                    }

                    double verticalDelta =
                        Math.Abs(rightCenter.Y - leftCenter.Y);
                    double widthDelta =
                        Math.Abs(right.Width - left.Width);
                    double heightDelta =
                        Math.Abs(right.Height - left.Height);
                    double edgeGap =
                        (rightCenter.X - right.Width / 2.0) -
                        (leftCenter.X + left.Width / 2.0);
                    if (verticalDelta > 16 ||
                        widthDelta > 65 ||
                        heightDelta > 20 ||
                        edgeGap < -15 ||
                        edgeGap > 90 ||
                        !SafeEnabled(right))
                    {
                        continue;
                    }

                    bool commonParent =
                        SafeParentAddress(left) != 0 &&
                        SafeParentAddress(left) ==
                            SafeParentAddress(right);
                    double score =
                        verticalDelta * 5.0 +
                        widthDelta +
                        heightDelta * 2.0 +
                        Math.Abs(edgeGap - 10.0) +
                        Math.Abs(left.Width - 190.0) * 0.25 +
                        Math.Abs(left.Height - 42.0) * 0.5 +
                        (commonParent ? 0.0 : 80.0);
                    if (score < bestScore)
                    {
                        bestScore = score;
                        bestLeft = left;
                        bestRight = right;
                    }
                }
            }

            if (bestLeft == null || bestRight == null)
            {
                AllflameLog.Throttled(
                    "capsule_direct_ui_not_found",
                    TimeSpan.FromSeconds(2),
                    "CAPSULE_DIRECT_UI|Found=False" +
                    "|Mode=DPBElementGeometry" +
                    "|Candidates=" + candidates.Count +
                    "|Visited=" + visited);
                return false;
            }

            buttons.SendToSurface = bestLeft;
            buttons.CallBathysphere = bestRight;
            buttons.DetectionMode = "DPBElementGeometry";
            Vector2i sendCenter = bestLeft.CenterClickLocation();
            Vector2i callCenter = bestRight.CenterClickLocation();
            AllflameLog.Throttled(
                "capsule_direct_ui_found",
                TimeSpan.FromSeconds(2),
                "CAPSULE_DIRECT_UI|Found=True" +
                "|Mode=" + buttons.DetectionMode +
                "|Send=" + sendCenter +
                "|SendEnabled=" + SafeEnabled(bestLeft) +
                "|Call=" + callCenter +
                "|CallEnabled=" + SafeEnabled(bestRight) +
                "|Score=" + bestScore.ToString("0.0") +
                "|Candidates=" + candidates.Count +
                "|Visited=" + visited);
            return true;
        }

        public static Element GetButton(
            CapsuleUiButtons buttons,
            CapsuleUiAction action)
        {
            if (buttons == null)
            {
                return null;
            }
            return action == CapsuleUiAction.SendToSurface
                ? buttons.SendToSurface
                : buttons.CallBathysphere;
        }

        public static bool TryGetButton(
            CapsuleUiAction action,
            out Element button,
            out string detectionMode)
        {
            return TryGetButton(
                action,
                true,
                out button,
                out detectionMode);
        }

        public static bool TryGetButton(
            CapsuleUiAction action,
            bool allowGeometry,
            out Element button,
            out string detectionMode)
        {
            button = null;
            detectionMode = "None";

            string caption =
                action == CapsuleUiAction.SendToSurface
                    ? "Send to Surface"
                    : "Call Bathysphere";
            CapsuleUiButtons buttons;
            if (!TryGetButtons(allowGeometry, out buttons))
            {
                return false;
            }

            button = GetButton(buttons, action);
            detectionMode =
                buttons.DetectionMode ?? "DPBElementGeometry";
            return IsUsable(button);
        }

        public static bool IsEnabled(Element element)
        {
            return IsUsable(element) && SafeEnabled(element);
        }

        public static bool IsVisible(Element element)
        {
            return IsUsable(element);
        }

        private static Element GetChild(Element parent, int index)
        {
            if (parent == null || index < 0)
            {
                return null;
            }
            try
            {
                List<Element> children = parent.Children;
                return children != null && index < children.Count
                    ? children[index]
                    : null;
            }
            catch
            {
                return null;
            }
        }

        private static string SafeIdLabel(Element element)
        {
            try
            {
                return element == null
                    ? String.Empty
                    : element.IdLabel ?? String.Empty;
            }
            catch
            {
                return String.Empty;
            }
        }

        private static string SafeText(Element element)
        {
            try
            {
                return element == null
                    ? String.Empty
                    : element.Text ?? String.Empty;
            }
            catch
            {
                return String.Empty;
            }
        }

        private static bool HasCaption(
            Element element,
            string caption)
        {
            return IsUsable(element) &&
                String.Equals(
                    SafeText(element).Trim(),
                    caption,
                    StringComparison.OrdinalIgnoreCase);
        }

        private static Element FindButtonInWindow(
            Element window,
            string caption)
        {
            int visited = 0;
            return FindButtonInWindow(
                window,
                caption,
                0,
                ref visited);
        }

        private static Element FindButtonInWindow(
            Element element,
            string caption,
            int depth,
            ref int visited)
        {
            if (element == null ||
                depth > 8 ||
                visited >= MaximumStableVisited)
            {
                return null;
            }
            visited++;
            if (HasCaption(element, caption))
            {
                return element;
            }
            List<Element> children;
            try
            {
                children = element.Children;
            }
            catch
            {
                return null;
            }
            if (children == null)
            {
                return null;
            }
            foreach (Element child in children)
            {
                Element found = FindButtonInWindow(
                    child,
                    caption,
                    depth + 1,
                    ref visited);
                if (found != null)
                {
                    return found;
                }
            }
            return null;
        }

        private static bool TryGetValidatedCenter(
            Element element,
            out Vector2i center)
        {
            center = new Vector2i();
            if (!TryCenter(element, out center))
            {
                return false;
            }
            try
            {
                var client = LokiPoe.ClientWindowInfo.Client;
                int width = client.Right - client.Left;
                int height = client.Bottom - client.Top;
                if (width <= 0 || height <= 0)
                {
                    return false;
                }
                bool clientRelative =
                    center.X >= 0 && center.X < width &&
                    center.Y >= 0 && center.Y < height;
                bool screenRelative =
                    center.X >= client.Left &&
                    center.X < client.Right &&
                    center.Y >= client.Top &&
                    center.Y < client.Bottom;
                return clientRelative || screenRelative;
            }
            catch
            {
                return false;
            }
        }

        private static void CollectButtonCandidates(
            Element element,
            int depth,
            IList<Element> output,
            ISet<long> addresses,
            ISet<long> visitedAddresses,
            DateTime deadline,
            ref int visited)
        {
            if (element == null ||
                depth > 14 ||
                visited >= MaximumVisited ||
                DateTime.UtcNow >= deadline)
            {
                return;
            }
            try
            {
                long address = element.Address;
                if (address != 0 &&
                    !visitedAddresses.Add(address))
                {
                    return;
                }
            }
            catch
            {
            }
            visited++;

            try
            {
                if ((element.IsVisible || element.IsVisibleLocal) &&
                    element.IsValid &&
                    element.Width >= 125f &&
                    element.Width <= 310f &&
                    element.Height >= 24f &&
                    element.Height <= 78f)
                {
                    Vector2i center = element.CenterClickLocation();
                    var client = LokiPoe.ClientWindowInfo.Client;
                    int width = client.Right - client.Left;
                    int height = client.Bottom - client.Top;
                    if (width > 0 &&
                        height > 0 &&
                        center.X >= 0 &&
                        center.X <= width * 0.72 &&
                        center.Y >= height * 0.12 &&
                        center.Y <= height * 0.88 &&
                        addresses.Add(element.Address))
                    {
                        output.Add(element);
                    }
                }
            }
            catch
            {
            }

            List<Element> children;
            try
            {
                children = element.Children;
            }
            catch
            {
                return;
            }
            if (children == null)
            {
                return;
            }
            foreach (Element child in children)
            {
                CollectButtonCandidates(
                    child,
                    depth + 1,
                    output,
                    addresses,
                    visitedAddresses,
                    deadline,
                    ref visited);
                if (visited >= MaximumVisited ||
                    DateTime.UtcNow >= deadline)
                {
                    break;
                }
            }
        }

        private static bool IsUsable(Element element)
        {
            try
            {
                return element != null &&
                       element.IsValid &&
                       (element.IsVisible ||
                        element.IsVisibleLocal);
            }
            catch
            {
                return false;
            }
        }

        private static bool SafeEnabled(Element element)
        {
            try
            {
                return element != null && element.IsEnable;
            }
            catch
            {
                return false;
            }
        }

        private static bool TryCenter(
            Element element,
            out Vector2i center)
        {
            center = new Vector2i();
            try
            {
                if (!IsUsable(element))
                {
                    return false;
                }
                center = element.CenterClickLocation();
                return true;
            }
            catch
            {
                return false;
            }
        }

        private static long SafeParentAddress(Element element)
        {
            try
            {
                return element == null ||
                       element.Parent == null
                    ? 0
                    : element.Parent.Address;
            }
            catch
            {
                return 0;
            }
        }
    }

    internal sealed class CapsuleWarningMatch
    {
        public Element Dialog;
        public Element OkElement;
        public Element ActionButton;
        public Vector2i Coordinate;
        public int RootIndex;
    }

    /// <summary>
    /// Resolves the modal warning shown after Call Bathysphere. The Element
    /// path is primary; dialog-relative coordinates and scoped OK text are
    /// fallbacks before the existing screenshot matcher is used.
    /// </summary>
    internal static class CapsuleWarningUi
    {
        private const string ConfirmationWindowId =
            "confirmation_window";
        private const string ActionButtonId = "action_button";
        private const string WarningTitle = "Warning";
        private const string UnusedCapsuleText = "unused Capsules";
        private const string ReturnSovereignText =
            "return to the Sovereign";
        private const int MaximumVisited = 1200;

        public static bool TryClick(
            out string mode,
            out Vector2i location)
        {
            mode = "None";
            location = new Vector2i();
            CapsuleWarningMatch match;
            if (!TryFindWarning(out match))
            {
                return false;
            }

            if (IsUsable(match.OkElement) &&
                SafeEnabled(match.OkElement))
            {
                if (TryGetCenter(match.OkElement, out location) &&
                    VoyagePlanningUi.Click(match.OkElement))
                {
                    mode = "Element";
                    LogClick(mode, match, location);
                    return true;
                }
            }

            if (TryGetCoordinate(match, out location) &&
                VoyagePlanningUi.ClickClient(location))
            {
                mode = "Coordinate";
                LogClick(mode, match, location);
                return true;
            }

            Element textOk = FindTextOk(match.Dialog);
            if (IsUsable(textOk) &&
                SafeEnabled(textOk) &&
                TryGetCenter(textOk, out location) &&
                VoyagePlanningUi.Click(textOk))
            {
                mode = "Text";
                LogClick(mode, match, location);
                return true;
            }

            AllflameLog.Throttled(
                "capsule_warning_element_click_failed",
                TimeSpan.FromSeconds(2),
                "CAPSULE_WARNING_CONFIRM" +
                "|Mode=None" +
                "|Reason=NoUsableElementCoordinateOrText" +
                "|RootIndex=" + match.RootIndex);
            return false;
        }

        public static bool IsVisible()
        {
            CapsuleWarningMatch match;
            return TryFindWarning(out match);
        }

        private static bool TryFindWarning(
            out CapsuleWarningMatch match)
        {
            match = null;
            List<Element> roots;
            try
            {
                roots = LokiPoe.GetGuiElements();
            }
            catch
            {
                return false;
            }
            if (roots == null)
            {
                return false;
            }

            int visited = 0;
            DateTime deadline = DateTime.UtcNow.AddMilliseconds(350);
            var seen = new HashSet<long>();
            for (int rootIndex = roots.Count - 1;
                 rootIndex >= 0 &&
                 visited < MaximumVisited &&
                 DateTime.UtcNow < deadline;
                 rootIndex--)
            {
                Element dialog = FindById(
                    roots[rootIndex],
                    ConfirmationWindowId,
                    0,
                    seen,
                    deadline,
                    ref visited);
                if (!IsUsable(dialog) ||
                    !IsWarningDialog(dialog))
                {
                    continue;
                }

                Element action = FindById(
                    dialog,
                    ActionButtonId,
                    0,
                    new HashSet<long>(),
                    deadline,
                    ref visited);
                Element ok = FindText(
                    action ?? dialog,
                    "ok",
                    0,
                    new HashSet<long>(),
                    deadline,
                    ref visited);
                match = new CapsuleWarningMatch
                {
                    Dialog = dialog,
                    ActionButton = action,
                    OkElement = ok,
                    RootIndex = rootIndex
                };
                Vector2i coordinate;
                if (TryGetCoordinate(match, out coordinate))
                {
                    match.Coordinate = coordinate;
                }
                AllflameLog.Throttled(
                    "capsule_warning_element_found",
                    TimeSpan.FromSeconds(2),
                    "CAPSULE_WARNING_ELEMENT" +
                    "|Found=True" +
                    "|RootIndex=" + rootIndex +
                    "|Dialog=" + FormatAddress(dialog) +
                    "|ActionButton=" + FormatAddress(action) +
                    "|Ok=" + FormatAddress(ok) +
                    "|Coordinate=" + match.Coordinate +
                    "|OkEnabled=" + SafeEnabled(ok));
                return true;
            }
            return false;
        }

        private static bool IsWarningDialog(Element dialog)
        {
            string allText = String.Join(
                " ",
                EnumerateText(dialog)
                    .Where(text => !String.IsNullOrWhiteSpace(text)));
            bool titleMatches = EnumerateText(dialog).Any(text =>
                String.Equals(
                    text.Trim(),
                    WarningTitle,
                    StringComparison.OrdinalIgnoreCase));
            bool messageMatches =
                allText.IndexOf(
                    UnusedCapsuleText,
                    StringComparison.OrdinalIgnoreCase) >= 0 ||
                allText.IndexOf(
                    ReturnSovereignText,
                    StringComparison.OrdinalIgnoreCase) >= 0;
            return IsUsable(dialog) && titleMatches && messageMatches;
        }

        private static bool TryGetCoordinate(
            CapsuleWarningMatch match,
            out Vector2i location)
        {
            location = new Vector2i();
            if (match == null || !IsUsable(match.Dialog))
            {
                return false;
            }

            if (TryGetCenter(match.OkElement, out location) ||
                TryGetCenter(match.ActionButton, out location))
            {
                return IsClientLocation(location);
            }

            Vector2i dialogCenter;
            if (!TryGetCenter(match.Dialog, out dialogCenter))
            {
                return false;
            }

            // Reference snapshot: dialog center {1025,513}, OK center
            // {1088,541}. Keep the offset proportional to the dialog so
            // this remains valid across UI scales and resolutions.
            location = new Vector2i(
                dialogCenter.X +
                    (int)Math.Round(match.Dialog.Width * 0.0956),
                dialogCenter.Y +
                    (int)Math.Round(match.Dialog.Height * 0.1302));
            return IsClientLocation(location);
        }

        private static Element FindTextOk(Element dialog)
        {
            int visited = 0;
            return FindText(
                dialog,
                "ok",
                0,
                new HashSet<long>(),
                DateTime.UtcNow.AddMilliseconds(250),
                ref visited);
        }

        private static IEnumerable<string> EnumerateText(Element root)
        {
            if (root == null)
            {
                yield break;
            }
            string text = SafeText(root).Trim();
            if (!String.IsNullOrWhiteSpace(text))
            {
                yield return text;
            }
            List<Element> children;
            try
            {
                children = root.Children;
            }
            catch
            {
                yield break;
            }
            if (children == null)
            {
                yield break;
            }
            foreach (Element child in children)
            {
                foreach (string childText in EnumerateText(child))
                {
                    yield return childText;
                }
            }
        }

        private static Element FindById(
            Element element,
            string id,
            int depth,
            ISet<long> seen,
            DateTime deadline,
            ref int visited)
        {
            if (element == null ||
                depth > 14 ||
                visited >= MaximumVisited ||
                DateTime.UtcNow >= deadline)
            {
                return null;
            }
            if (!MarkVisited(element, seen, ref visited))
            {
                return null;
            }
            if (String.Equals(
                    SafeId(element),
                    id,
                    StringComparison.OrdinalIgnoreCase) &&
                IsUsable(element))
            {
                return element;
            }
            foreach (Element child in SafeChildren(element))
            {
                Element found = FindById(
                    child,
                    id,
                    depth + 1,
                    seen,
                    deadline,
                    ref visited);
                if (found != null)
                {
                    return found;
                }
            }
            return null;
        }

        private static Element FindText(
            Element element,
            string expected,
            int depth,
            ISet<long> seen,
            DateTime deadline,
            ref int visited)
        {
            if (element == null ||
                depth > 14 ||
                visited >= MaximumVisited ||
                DateTime.UtcNow >= deadline)
            {
                return null;
            }
            if (!MarkVisited(element, seen, ref visited))
            {
                return null;
            }
            if (String.Equals(
                    SafeText(element).Trim(),
                    expected,
                    StringComparison.OrdinalIgnoreCase) &&
                IsUsable(element))
            {
                return element;
            }
            foreach (Element child in SafeChildren(element))
            {
                Element found = FindText(
                    child,
                    expected,
                    depth + 1,
                    seen,
                    deadline,
                    ref visited);
                if (found != null)
                {
                    return found;
                }
            }
            return null;
        }

        private static bool MarkVisited(
            Element element,
            ISet<long> seen,
            ref int visited)
        {
            visited++;
            try
            {
                long address = element.Address;
                return address == 0 || seen.Add(address);
            }
            catch
            {
                return true;
            }
        }

        private static List<Element> SafeChildren(Element element)
        {
            try
            {
                return element == null || element.Children == null
                    ? new List<Element>()
                    : element.Children;
            }
            catch
            {
                return new List<Element>();
            }
        }

        private static bool IsUsable(Element element)
        {
            try
            {
                return element != null &&
                    element.IsValid &&
                    element.IsVisible;
            }
            catch
            {
                return false;
            }
        }

        private static bool SafeEnabled(Element element)
        {
            try
            {
                return IsUsable(element) && element.IsEnable;
            }
            catch
            {
                return false;
            }
        }

        private static string SafeId(Element element)
        {
            try
            {
                return element == null ? String.Empty : element.IdLabel ?? String.Empty;
            }
            catch
            {
                return String.Empty;
            }
        }

        private static string SafeText(Element element)
        {
            try
            {
                return element == null ? String.Empty : element.Text ?? String.Empty;
            }
            catch
            {
                return String.Empty;
            }
        }

        private static bool TryGetCenter(
            Element element,
            out Vector2i center)
        {
            center = new Vector2i();
            if (!IsUsable(element))
            {
                return false;
            }
            try
            {
                center = element.CenterClickLocation();
                return IsClientLocation(center);
            }
            catch
            {
                return false;
            }
        }

        private static bool IsClientLocation(Vector2i location)
        {
            try
            {
                var client = LokiPoe.ClientWindowInfo.Client;
                int width = client.Right - client.Left;
                int height = client.Bottom - client.Top;
                return width > 0 && height > 0 &&
                    location.X >= 0 && location.X < width &&
                    location.Y >= 0 && location.Y < height;
            }
            catch
            {
                return false;
            }
        }

        private static string FormatAddress(Element element)
        {
            try
            {
                return element == null
                    ? "0x0"
                    : "0x" + element.Address.ToString("X");
            }
            catch
            {
                return "0x0";
            }
        }

        private static void LogClick(
            string mode,
            CapsuleWarningMatch match,
            Vector2i location)
        {
            AllflameLog.Info(
                "CAPSULE_WARNING_CONFIRM" +
                "|Mode=" + mode +
                "|InputSent=True" +
                "|RootIndex=" + match.RootIndex +
                "|Dialog=" + FormatAddress(match.Dialog) +
                "|Ok=" + FormatAddress(match.OkElement) +
                "|ActionButton=" + FormatAddress(match.ActionButton) +
                "|Client=" + location);
        }
    }

    /// <summary>
    /// Bounded visual fallback for the enabled CALL BATHYSPHERE button.
    /// DPB 0.3.29.14 exposes the Capsule world object but the opened Capsule
    /// window is absent from its Element tree on some clients. This scan is
    /// armed only while the bot is beside a confirmed Capsule and an
    /// extraction request is active.
    /// </summary>
    internal static class CapsuleVisualUi
    {
        private const int CallTemplateWidth = 48;
        private const int CallTemplateHeight = 12;
        private const int WarningTemplateWidth = 48;
        private const int WarningTemplateHeight = 12;
        // The Capsule row is now spatially constrained below, so a lower
        // threshold can tolerate client scaling without allowing unrelated
        // elements elsewhere in the game window to become the click target.
        private const double WarningMinimumCorrelation = 0.66;
        private const string CallEnabledTemplateBase64 =
            "";
        private const string CallEnabledTemplateV2Base64 =
            "";
        private const string CallEnabledTemplateV3Base64 =
            "GDYYEhIWFRYXFRkZFxcZFxcZFxgZFxgZGBkbFxkZFxcZFxcZGBcZFxcVEhIoKhUDL2lORkZFRERERERERERERERERERERERERERERERERERERERERERERERFRUVcTiAcKx8AAAAEAAAAAAAAAAAAAAAAAAcBAAAAAAAAAAYHBwcHBwUABAcHBwcDAAAAOyIg" +
            "JygVGSIiGRkXGR0YHhUWIR4VGhghIyEeHCAhHiAhICMgHx0gISAhIRYdIhcKSCQhIzgXSmh2NnE4Rmc9cRofkHsgdEJwinJwSHONVHd/dIuGeT1/k2GNiih3eiAiViopF0oZdishK5h2QF41Zxscj4s1nXBBeT2HaWk+jSeDYoNpjGJ3kGSPjihvfiRJNRgh" +
            "KjwZX3djY12LVIVqilIiloNrWYtMgkJ3RHQrhzhtgnU6fzqDlmOPcmV5cjIeOhkaMjUiJDkxJiYmJCcmKCUhKCgmJSYlJyQmJCUjJiQ6KTkkJiQmKSg4MDonKSQhNxkYIyomJSclJSUlJSUlJSYlJSUlJSUlJScnJycmJicoKCgoKCgoKCcnJyclJSUjLxUW" +
            "Hjs7NzY2NTU1NTU1NTU1NTU1NTc3Nzc3Nzc3Nzc3Nzc3Nzc3NjU1NTU1NTVDOBMUGiATDg4TFRUVFRUVFRUVFRUVFRUVFRUVFRUVFRUVFRUVFRUVFRUVFRUVFRUcIBcNAAYHBwcHCAgJCA0REhISEhISFBQWFBMTFxgXFxYVFBMUFBMTExEQEBAQEA0IBwYG";
        private static readonly byte[] CallEnabledTemplate =
            Convert.FromBase64String(CallEnabledTemplateV3Base64);
        private static readonly double TemplateMean =
            CallEnabledTemplate.Average(value => (double)value);
        private static readonly double TemplateEnergy =
            CallEnabledTemplate.Sum(
                value =>
                    (value - TemplateMean) *
                    (value - TemplateMean));
        private const string Call1280TemplateBase64 =
            "";
        private const string Call1920TemplateBase64 =
            "";
        private const string Call1280ExactTemplateBase64 =
            "";
        private const string Call1920ExactTemplateBase64 =
            "";
        private const string Call800TemplateBase64 =
            "";
        private static readonly byte[] Call1280Template =
            Convert.FromBase64String(Call1280ExactTemplateBase64);
        private static readonly byte[] Call1920Template =
            Convert.FromBase64String(Call1920ExactTemplateBase64);
        private static readonly byte[] Call800Template =
            Convert.FromBase64String(Call800TemplateBase64);
        private static readonly double Call1280TemplateMean =
            Call1280Template.Average(value => (double)value);
        private static readonly double Call1920TemplateMean =
            Call1920Template.Average(value => (double)value);
        private static readonly double Call800TemplateMean =
            Call800Template.Average(value => (double)value);
        private static readonly double Call1280TemplateEnergy =
            Call1280Template.Sum(
                value =>
                    (value - Call1280TemplateMean) *
                    (value - Call1280TemplateMean));
        private static readonly double Call1920TemplateEnergy =
            Call1920Template.Sum(
                value =>
                    (value - Call1920TemplateMean) *
                    (value - Call1920TemplateMean));
        private static readonly double Call800TemplateEnergy =
            Call800Template.Sum(
                value =>
                    (value - Call800TemplateMean) *
                    (value - Call800TemplateMean));
        private const string WarningOkTemplateBase64 =
            "";
        private const string WarningOk800TemplateBase64 =
            "";
        private static readonly byte[] WarningOkTemplate =
            Convert.FromBase64String(WarningOkTemplateBase64);
        private static readonly byte[] WarningOk800Template =
            Convert.FromBase64String(WarningOk800TemplateBase64);
        private static readonly double WarningTemplateMean =
            WarningOkTemplate.Average(value => (double)value);
        private static readonly double WarningTemplateEnergy =
            WarningOkTemplate.Sum(
                value =>
                    (value - WarningTemplateMean) *
                    (value - WarningTemplateMean));
        private static readonly double Warning800TemplateMean =
            WarningOk800Template.Average(value => (double)value);
        private static readonly double Warning800TemplateEnergy =
            WarningOk800Template.Sum(
                value =>
                    (value - Warning800TemplateMean) *
                    (value - Warning800TemplateMean));

        public static bool TryFindCallButton(
            out Vector2i clientLocation,
            out double bestCorrelation,
            double requiredCorrelation)
        {
            clientLocation = new Vector2i();
            bestCorrelation = -1.0;
            requiredCorrelation = Math.Max(
                0.40,
                Math.Min(0.60, requiredCorrelation));
            if (Call800Template.Length !=
                    CallTemplateWidth * CallTemplateHeight ||
                Call1280Template.Length !=
                    CallTemplateWidth * CallTemplateHeight ||
                Call1920Template.Length !=
                    CallTemplateWidth * CallTemplateHeight)
            {
                AllflameLog.Throttled(
                    "capsule_call_visual_invalid_template",
                    TimeSpan.FromSeconds(5),
                    "CAPSULE_CALL_VISUAL" +
                    "|Error=InvalidTemplateLength" +
                    "|Actual800=" + Call800Template.Length +
                    "|Actual1280=" + Call1280Template.Length +
                    "|Actual1920=" + Call1920Template.Length +
                    "|Expected=" +
                    (CallTemplateWidth * CallTemplateHeight));
                return false;
            }

            try
            {
                var client = LokiPoe.ClientWindowInfo.Client;
                int clientWidth = client.Right - client.Left;
                int clientHeight = client.Bottom - client.Top;
                if (clientWidth < 700 || clientHeight < 450)
                {
                    return false;
                }

                using (var screenshot = new System.Drawing.Bitmap(
                    clientWidth,
                    clientHeight,
                    System.Drawing.Imaging.PixelFormat.Format24bppRgb))
                {
                    using (System.Drawing.Graphics graphics =
                        System.Drawing.Graphics.FromImage(screenshot))
                    {
                        graphics.CopyFromScreen(
                            client.Left,
                            client.Top,
                            0,
                            0,
                            new System.Drawing.Size(
                                clientWidth,
                                clientHeight),
                            System.Drawing.CopyPixelOperation.SourceCopy);
                    }

                    var rectangle = new System.Drawing.Rectangle(
                        0,
                        0,
                        clientWidth,
                        clientHeight);
                    System.Drawing.Imaging.BitmapData bitmapData =
                        screenshot.LockBits(
                            rectangle,
                            System.Drawing.Imaging.ImageLockMode.ReadOnly,
                            System.Drawing.Imaging.PixelFormat.Format24bppRgb);
                    try
                    {
                        int stride = Math.Abs(bitmapData.Stride);
                        byte[] pixels = new byte[stride * clientHeight];
                        System.Runtime.InteropServices.Marshal.Copy(
                            bitmapData.Scan0,
                            pixels,
                            0,
                            pixels.Length);

                        double referenceScale =
                            Math.Min(
                                clientWidth / 1920.0,
                                clientHeight / 1080.0);
                        double[] scales =
                            { 0.78, 0.90, 1.0, 1.10, 1.22, 1.32 };
                        // Call Bathysphere is always the right-hand button
                        // along the bottom edge of the Capsule window. The
                        // previous broad scan selected a false-positive at
                        // {394,292}; the real button in that same 1440x900
                        // client was around {528,532}.
                        int minCenterX =
                            (int)Math.Round(clientWidth * 0.30);
                        int maxCenterX =
                            (int)Math.Round(clientWidth * 0.47);
                        int minCenterY =
                            (int)Math.Round(clientHeight * 0.52);
                        int maxCenterY =
                            (int)Math.Round(clientHeight * 0.66);
                        int bestCenterX = 0;
                        int bestCenterY = 0;
                        int bestCandidateWidth = 0;
                        int bestCandidateHeight = 0;
                        string bestTemplate = "None";

                        foreach (double scale in scales)
                        {
                            int candidateWidth = Math.Max(
                                90,
                                (int)Math.Round(
                                    193.0 * referenceScale * scale));
                            int candidateHeight = Math.Max(
                                22,
                                (int)Math.Round(
                                    46.0 * referenceScale * scale));
                            int halfWidth = candidateWidth / 2;
                            int halfHeight = candidateHeight / 2;
                            int startX = Math.Max(
                                halfWidth,
                                minCenterX);
                            int endX = Math.Min(
                                clientWidth - halfWidth - 1,
                                maxCenterX);
                            int startY = Math.Max(
                                halfHeight,
                                minCenterY);
                            int endY = Math.Min(
                                clientHeight - halfHeight - 1,
                                maxCenterY);

                            for (int centerY = startY;
                                 centerY <= endY;
                                 centerY += 4)
                            {
                                for (int centerX = startX;
                                     centerX <= endX;
                                     centerX += 4)
                                {
                                    string candidateTemplate;
                                    double correlation =
                                        CalculateBestCallCorrelation(
                                            pixels,
                                            stride,
                                            clientWidth,
                                            clientHeight,
                                            centerX - halfWidth,
                                            centerY - halfHeight,
                                            candidateWidth,
                                            candidateHeight,
                                            out candidateTemplate);
                                    if (correlation > bestCorrelation)
                                    {
                                        bestCorrelation = correlation;
                                        bestCenterX = centerX;
                                        bestCenterY = centerY;
                                        bestCandidateWidth = candidateWidth;
                                        bestCandidateHeight = candidateHeight;
                                        bestTemplate = candidateTemplate;
                                    }
                                }
                            }
                        }

                        // The coarse pass uses four-pixel steps to keep the
                        // scan cheap. Refine around its best candidate so the
                        // click lands on the true button center and window
                        // scaling cannot lose the match by a few hundredths.
                        if (bestCandidateWidth > 0 &&
                            bestCandidateHeight > 0)
                        {
                            int halfWidth = bestCandidateWidth / 2;
                            int halfHeight = bestCandidateHeight / 2;
                            int refineStartX = Math.Max(
                                halfWidth,
                                bestCenterX - 5);
                            int refineEndX = Math.Min(
                                clientWidth - halfWidth - 1,
                                bestCenterX + 5);
                            int refineStartY = Math.Max(
                                halfHeight,
                                bestCenterY - 5);
                            int refineEndY = Math.Min(
                                clientHeight - halfHeight - 1,
                                bestCenterY + 5);
                            for (int centerY = refineStartY;
                                 centerY <= refineEndY;
                                 centerY++)
                            {
                                for (int centerX = refineStartX;
                                     centerX <= refineEndX;
                                     centerX++)
                                {
                                    string candidateTemplate;
                                    double correlation =
                                        CalculateBestCallCorrelation(
                                            pixels,
                                            stride,
                                            clientWidth,
                                            clientHeight,
                                            centerX - halfWidth,
                                            centerY - halfHeight,
                                            bestCandidateWidth,
                                            bestCandidateHeight,
                                            out candidateTemplate);
                                    if (correlation > bestCorrelation)
                                    {
                                        bestCorrelation = correlation;
                                        bestCenterX = centerX;
                                        bestCenterY = centerY;
                                        bestTemplate = candidateTemplate;
                                    }
                                }
                            }
                        }

                        if (bestCandidateWidth > 0 &&
                            bestCandidateHeight > 0)
                        {
                            clientLocation = new Vector2i(
                                bestCenterX,
                                bestCenterY);
                        }
                        if (bestCorrelation >= requiredCorrelation)
                        {
                            AllflameLog.Throttled(
                                "capsule_call_visual_found",
                                TimeSpan.FromSeconds(2),
                                "CAPSULE_CALL_VISUAL|Found=True" +
                                "|Client=" + clientLocation +
                                "|Correlation=" +
                                bestCorrelation.ToString("0.000") +
                                "|Required=" +
                                requiredCorrelation.ToString("0.000") +
                                "|Template=" + bestTemplate +
                                "|Window=" + clientWidth + "x" +
                                clientHeight);
                            return true;
                        }

                        AllflameLog.Throttled(
                            "capsule_call_visual_not_found",
                            TimeSpan.FromSeconds(2),
                            "CAPSULE_CALL_VISUAL|Found=False" +
                            "|BestCorrelation=" +
                            bestCorrelation.ToString("0.000") +
                            "|Required=" +
                            requiredCorrelation.ToString("0.000") +
                            "|Template=" + bestTemplate +
                            "|Window=" + clientWidth + "x" +
                            clientHeight);
                    }
                    finally
                    {
                        screenshot.UnlockBits(bitmapData);
                    }
                }
            }
            catch (Exception exception)
            {
                AllflameLog.Throttled(
                    "capsule_call_visual_error",
                    TimeSpan.FromSeconds(2),
                    "CAPSULE_CALL_VISUAL|Error=" +
                    exception.GetType().Name +
                    "|Message=" +
                    (exception.Message ?? String.Empty)
                        .Replace("|", "/"));
            }

            return false;
        }

        public static bool TryFindWarningOk(
            out Vector2i clientLocation,
            out double bestCorrelation)
        {
            clientLocation = new Vector2i();
            bestCorrelation = -1.0;

            try
            {
                var client = LokiPoe.ClientWindowInfo.Client;
                int clientWidth = client.Right - client.Left;
                int clientHeight = client.Bottom - client.Top;
                if (clientWidth < 700 || clientHeight < 450)
                {
                    return false;
                }

                using (var screenshot = new System.Drawing.Bitmap(
                    clientWidth,
                    clientHeight,
                    System.Drawing.Imaging.PixelFormat.Format24bppRgb))
                {
                    using (System.Drawing.Graphics graphics =
                        System.Drawing.Graphics.FromImage(screenshot))
                    {
                        graphics.CopyFromScreen(
                            client.Left,
                            client.Top,
                            0,
                            0,
                            new System.Drawing.Size(clientWidth, clientHeight),
                            System.Drawing.CopyPixelOperation.SourceCopy);
                    }

                    var rectangle = new System.Drawing.Rectangle(
                        0, 0, clientWidth, clientHeight);
                    System.Drawing.Imaging.BitmapData bitmapData =
                        screenshot.LockBits(
                            rectangle,
                            System.Drawing.Imaging.ImageLockMode.ReadOnly,
                            System.Drawing.Imaging.PixelFormat.Format24bppRgb);
                    try
                    {
                        int stride = Math.Abs(bitmapData.Stride);
                        byte[] pixels = new byte[stride * clientHeight];
                        System.Runtime.InteropServices.Marshal.Copy(
                            bitmapData.Scan0,
                            pixels,
                            0,
                            pixels.Length);

                        double[] scales = { 0.82, 0.92, 1.0, 1.08, 1.18 };
                        int nominalWidth = Math.Max(
                            90,
                            (int)Math.Round(clientWidth * 0.0832));
                        int nominalHeight = Math.Max(
                            28,
                            (int)Math.Round(clientHeight * 0.0429));
                        int bestCenterX = 0;
                        int bestCenterY = 0;

                        foreach (double scale in scales)
                        {
                            int candidateWidth = Math.Max(
                                clientWidth <= 900 ? 70 : 80,
                                (int)Math.Round(nominalWidth * scale));
                            int candidateHeight = Math.Max(
                                clientHeight <= 650 ? 20 : 24,
                                (int)Math.Round(nominalHeight * scale));
                            int halfWidth = candidateWidth / 2;
                            int halfHeight = candidateHeight / 2;
                            int startX = Math.Max(
                                halfWidth,
                                (int)Math.Round(clientWidth * 0.48));
                            int endX = Math.Min(
                                clientWidth - halfWidth - 1,
                                (int)Math.Round(clientWidth * 0.69));
                            int startY = Math.Max(
                                halfHeight,
                                (int)Math.Round(clientHeight * 0.45));
                            int endY = Math.Min(
                                clientHeight - halfHeight - 1,
                                (int)Math.Round(clientHeight * 0.62));

                            for (int centerY = startY;
                                 centerY <= endY;
                                 centerY += 3)
                            {
                                for (int centerX = startX;
                                     centerX <= endX;
                                     centerX += 3)
                                {
                                    double correlation =
                                        CalculateCorrelation(
                                            pixels,
                                            stride,
                                            clientWidth,
                                            clientHeight,
                                            centerX - halfWidth,
                                            centerY - halfHeight,
                                            candidateWidth,
                                            candidateHeight,
                                            WarningOkTemplate,
                                            WarningTemplateWidth,
                                            WarningTemplateHeight,
                                            WarningTemplateMean,
                                            WarningTemplateEnergy);
                                    correlation = Math.Max(
                                        correlation,
                                        CalculateCorrelation(
                                            pixels,
                                            stride,
                                            clientWidth,
                                            clientHeight,
                                            centerX - halfWidth,
                                            centerY - halfHeight,
                                            candidateWidth,
                                            candidateHeight,
                                            WarningOk800Template,
                                            WarningTemplateWidth,
                                            WarningTemplateHeight,
                                            Warning800TemplateMean,
                                            Warning800TemplateEnergy));
                                    if (correlation > bestCorrelation)
                                    {
                                        bestCorrelation = correlation;
                                        bestCenterX = centerX;
                                        bestCenterY = centerY;
                                    }
                                }
                            }
                        }

                        if (bestCorrelation >= WarningMinimumCorrelation)
                        {
                            clientLocation =
                                new Vector2i(bestCenterX, bestCenterY);
                            AllflameLog.Info(
                                "CAPSULE_WARNING_OK_VISUAL|Found=True" +
                                "|Client=" + clientLocation +
                                "|Correlation=" +
                                bestCorrelation.ToString("0.000") +
                                "|Window=" + clientWidth + "x" +
                                clientHeight);
                            return true;
                        }

                        AllflameLog.Throttled(
                            "capsule_warning_ok_visual_not_found",
                            TimeSpan.FromSeconds(2),
                            "CAPSULE_WARNING_OK_VISUAL|Found=False" +
                            "|BestCorrelation=" +
                            bestCorrelation.ToString("0.000") +
                            "|Required=" +
                            WarningMinimumCorrelation.ToString("0.000"));
                    }
                    finally
                    {
                        screenshot.UnlockBits(bitmapData);
                    }
                }
            }
            catch (Exception exception)
            {
                AllflameLog.Throttled(
                    "capsule_warning_ok_visual_error",
                    TimeSpan.FromSeconds(2),
                    "CAPSULE_WARNING_OK_VISUAL|Error=" +
                    exception.GetType().Name +
                    "|Message=" +
                    (exception.Message ?? String.Empty).Replace("|", "/"));
            }

            return false;
        }

        public static bool ClickCall(
            Vector2i clientLocation,
            int attempt)
        {
            try
            {
                LokiPoe.ProcessHookManager.ClearAllKeyStates();
                int strategy =
                    (Math.Max(1, attempt) - 1) % 3;
                int horizontalOffset =
                    strategy == 1
                        ? 24
                        : (strategy == 2 ? -24 : 0);
                var clickLocation = new Vector2i(
                    clientLocation.X + horizontalOffset,
                    clientLocation.Y);
                var client = LokiPoe.ClientWindowInfo.Client;
                AllflameLog.Info(
                    "CAPSULE_VISUAL_CLICK" +
                    "|Attempt=" + Math.Max(1, attempt) +
                    "|Strategy=" + strategy +
                    "|DetectedClient=" + clientLocation +
                    "|ClickClient=" + clickLocation +
                    "|ClickScreen={" +
                    (client.Left + clickLocation.X) + ", " +
                    (client.Top + clickLocation.Y) + "}" +
                    "|WindowOrigin={" + client.Left + ", " +
                    client.Top + "}");
                if (strategy == 0)
                {
                    DreamPoeBot.BotFramework.MouseManager
                        .SetMousePosition(clickLocation, false);
                    DreamPoeBot.BotFramework.MouseManager
                        .ClickLMB(0, 0);
                }
                else if (strategy == 1)
                {
                    LokiPoe.Input.MoveMouseToScreenPos(
                        client.Left + clickLocation.X,
                        client.Top + clickLocation.Y,
                        true);
                    LokiPoe.Input.ClickLMB(
                        client.Left + clickLocation.X,
                        client.Top + clickLocation.Y);
                }
                else
                {
                    DreamPoeBot.BotFramework.MouseManager
                        .SetMousePosition(clickLocation, false);
                    DreamPoeBot.BotFramework.MouseManager
                        .ClickLMB(0, 0);
                }
                return true;
            }
            catch
            {
                return false;
            }
        }

        private static double CalculateBestCallCorrelation(
            byte[] pixels,
            int stride,
            int imageWidth,
            int imageHeight,
            int candidateLeft,
            int candidateTop,
            int candidateWidth,
            int candidateHeight,
            out string templateName)
        {
            double correlation800 = CalculateCorrelation(
                pixels,
                stride,
                imageWidth,
                imageHeight,
                candidateLeft,
                candidateTop,
                candidateWidth,
                candidateHeight,
                Call800Template,
                CallTemplateWidth,
                CallTemplateHeight,
                Call800TemplateMean,
                Call800TemplateEnergy);
            double correlation1280 = CalculateCorrelation(
                pixels,
                stride,
                imageWidth,
                imageHeight,
                candidateLeft,
                candidateTop,
                candidateWidth,
                candidateHeight,
                Call1280Template,
                CallTemplateWidth,
                CallTemplateHeight,
                Call1280TemplateMean,
                Call1280TemplateEnergy);
            double correlation1920 = CalculateCorrelation(
                pixels,
                stride,
                imageWidth,
                imageHeight,
                candidateLeft,
                candidateTop,
                candidateWidth,
                candidateHeight,
                Call1920Template,
                CallTemplateWidth,
                CallTemplateHeight,
                Call1920TemplateMean,
                Call1920TemplateEnergy);
            if (correlation800 >= correlation1280 &&
                correlation800 >= correlation1920)
            {
                templateName = "Call800x600";
                return correlation800;
            }
            if (correlation1280 >= correlation1920)
            {
                templateName = "Call1280x800";
                return correlation1280;
            }

            templateName = "Call1920x1080";
            return correlation1920;
        }

        private static double CalculateCorrelation(
            byte[] pixels,
            int stride,
            int imageWidth,
            int imageHeight,
            int candidateLeft,
            int candidateTop,
            int candidateWidth,
            int candidateHeight,
            byte[] template,
            int templateWidth,
            int templateHeight,
            double templateMean,
            double templateEnergy)
        {
            double sum = 0.0;
            double sumSquares = 0.0;
            double cross = 0.0;
            int count = template.Length;

            for (int templateY = 0;
                 templateY < templateHeight;
                 templateY++)
            {
                int sourceY = candidateTop +
                    templateY * (candidateHeight - 1) /
                    (templateHeight - 1);
                if (sourceY < 0 || sourceY >= imageHeight)
                {
                    return -1.0;
                }

                int row = sourceY * stride;
                for (int templateX = 0;
                     templateX < templateWidth;
                     templateX++)
                {
                    int sourceX = candidateLeft +
                        templateX * (candidateWidth - 1) /
                        (templateWidth - 1);
                    if (sourceX < 0 || sourceX >= imageWidth)
                    {
                        return -1.0;
                    }

                    int pixelIndex = row + sourceX * 3;
                    double gray =
                        (pixels[pixelIndex + 2] * 77 +
                         pixels[pixelIndex + 1] * 150 +
                         pixels[pixelIndex] * 29) / 256.0;
                    double templateCentered =
                        template[
                            templateY * templateWidth +
                            templateX] -
                        templateMean;
                    sum += gray;
                    sumSquares += gray * gray;
                    cross += gray * templateCentered;
                }
            }

            double candidateEnergy =
                sumSquares - sum * sum / count;
            if (candidateEnergy <= 0.001 ||
                templateEnergy <= 0.001)
            {
                return -1.0;
            }

            return cross /
                Math.Sqrt(candidateEnergy * templateEnergy);
        }
    }

    internal static class ChartStorageUi
    {
        private const int ChartStorageServerInventoryId = 151;
        private static int _cachedRequestedInventoryId = -1;
        private static int _depositRevision;
        private static DateTime _nextDynamicInventoryProbeUtc =
            DateTime.MinValue;

        public static int DepositRevision
        {
            get { return _depositRevision; }
        }

        public static void MarkDepositConfirmed()
        {
            unchecked
            {
                _depositRevision++;
            }
        }

        public static bool IsFreshlyVisible()
        {
            Element storageRoot;
            return TryFindStorageRoot(out storageRoot);
        }

        public static bool TryResolve(
            InventoryControlWrapper cachedControl,
            InventorySlotUiElement cachedSlot,
            out InventoryControlWrapper control,
            out InventorySlotUiElement slot)
        {
            return TryResolve(
                -1,
                -1,
                cachedControl,
                cachedSlot,
                out control,
                out slot);
        }

        public static bool TryResolve(
            int mainTab,
            int subTab,
            InventoryControlWrapper cachedControl,
            InventorySlotUiElement cachedSlot,
            out InventoryControlWrapper control,
            out InventorySlotUiElement slot)
        {
            control = null;
            slot = null;

            // Cached controls can belong to a previous window instance. They
            // are retained only as call-site state; every resolution must
            // confirm the current root and active page layer first.
            Element storageRoot;
            if (!TryFindStorageRoot(out storageRoot))
            {
                return false;
            }

            int resolvedMain;
            int resolvedSub;
            Element pageLayer;
            if (!TryFindPageLayer(
                    storageRoot,
                    mainTab,
                    subTab,
                    out resolvedMain,
                    out resolvedSub,
                    out pageLayer))
            {
                AllflameLog.Throttled(
                    "chart_storage_control_missing",
                    TimeSpan.FromSeconds(3),
                    "CHART_STORAGE_PAGE_RESOLVE_FAILED" +
                    "|RequestedMain=" + (mainTab + 1) +
                    "|RequestedSub=" + (subTab + 1) +
                    "|Window=ChartStorage" +
                    "|Root=" + FormatAddress(storageRoot));
                return false;
            }

            try
            {
                slot = new InventorySlotUiElement(
                    pageLayer.Address,
                    StashType.NormalStash);
                if (slot == null || !slot.IsValid || !slot.IsVisible)
                {
                    control = null;
                    slot = null;
                    return false;
                }
                control = new InventoryControlWrapper();
                control.SetInventorySlotUi(slot, StashType.NormalStash);
            }
            catch
            {
                control = null;
                slot = null;
                return false;
            }

            List<KeyValuePair<int, Element>> rawItems =
                GetRawItemElements(slot);
            int dictionaryEntries = GetRawDictionaryCount(slot);
            Inventory serverInventory = null;
            const bool nativeBound = false;
            AllflameLog.Throttled(
                "chart_storage_control_found",
                TimeSpan.FromSeconds(3),
                "CHART_STORAGE_PAGE_LAYER|Found=True|Address=0x" +
                slot.Address.ToString("X") +
                "|Size=" + slot.Size.X + "x" + slot.Size.Y +
                "|Main=" + (resolvedMain + 1) +
                "|Sub=" + (resolvedSub + 1) +
                "|RawItems=" + rawItems.Count +
                "|DictionaryEntries=" + dictionaryEntries +
                "|AcceptedRawItems=" + rawItems.Count +
                "|RejectedInvalid=" +
                Math.Max(0, dictionaryEntries - rawItems.Count) +
                "|RejectedSize=0" +
                "|NativeBound=" + nativeBound +
                "|RequestedInventoryId=" +
                ChartStorageServerInventoryId +
                "|ResolvedInventoryId=" + (serverInventory == null
                    ? -1
                    : serverInventory.Id) +
                "|Path=2/0/1/" + resolvedMain +
                "/0/1/" + resolvedSub + "/0" +
                "|Slot=" + (int)slot.Width + "x" +
                (int)slot.Height);
            return true;
        }

        public static int BoundRequestedInventoryId
        {
            get { return _cachedRequestedInventoryId; }
        }

        public static List<KeyValuePair<int, Element>> GetRawItemElements(
            InventorySlotUiElement slot)
        {
            var output = new List<KeyValuePair<int, Element>>();
            try
            {
                if (slot == null ||
                    !slot.IsValid ||
                    !slot.IsVisible ||
                    slot.DictionaryIdElements == null)
                {
                    return output;
                }

                foreach (KeyValuePair<int, Element> pair in
                    slot.DictionaryIdElements)
                {
                    Element element = pair.Value;
                    if (element == null ||
                        !element.IsValid ||
                        !element.IsVisible)
                    {
                        continue;
                    }
                    element.CenterClickLocation();
                    output.Add(pair);
                }
            }
            catch
            {
                output.Clear();
            }
            return output;
        }

        public static bool TryClickMainTab(int mainTab)
        {
            if (mainTab < 0 || mainTab > 2)
            {
                return false;
            }

            Element root;
            if (!TryFindStorageRoot(out root))
            {
                return false;
            }

            Element button = SafeChild(
                root,
                2, 0, 0, 0, mainTab);
            bool clicked = Click(button);
            AllflameLog.Info(
                "CHART_STORAGE_TAB_CLICK" +
                "|Level=Main" +
                "|Main=" + (mainTab + 1) +
                "|Mode=DirectIconPath" +
                "|Clicked=" + clicked +
                "|Address=" + FormatAddress(button) +
                "|Geometry=" + FormatGeometry(button));
            return clicked;
        }

        public static bool TryClickSubTab(int mainTab, int subTab)
        {
            if (mainTab < 0 || mainTab > 2 ||
                subTab < 0 || subTab > 4)
            {
                return false;
            }

            Element root;
            if (!TryFindStorageRoot(out root))
            {
                return false;
            }

            Element button;
            if (!TryFindSubTabButton(
                    root,
                    mainTab,
                    subTab,
                    out button))
            {
                AllflameLog.Info(
                    "CHART_STORAGE_TAB_CLICK" +
                    "|Level=Sub" +
                    "|Main=" + (mainTab + 1) +
                    "|Sub=" + (subTab + 1) +
                    "|Mode=Unresolved" +
                    "|Clicked=False|Address=0x0");
                return false;
            }

            bool clicked = Click(button);
            AllflameLog.Info(
                "CHART_STORAGE_TAB_CLICK" +
                "|Level=Sub" +
                "|Main=" + (mainTab + 1) +
                "|Sub=" + (subTab + 1) +
                "|Mode=MainPageButtonsContainer" +
                "|Clicked=" + clicked +
                "|Address=" + FormatAddress(button));
            return clicked;
        }

        public static bool IsMainTabActive(int mainTab)
        {
            if (mainTab < 0 || mainTab > 2)
            {
                return false;
            }
            Element root;
            return TryFindStorageRoot(out root) &&
                IsMainTabActive(root, mainTab);
        }

        public static bool IsPageActive(int mainTab, int subTab)
        {
            if (mainTab < 0 || mainTab > 2 ||
                subTab < 0 || subTab > 4)
            {
                return false;
            }
            Element root;
            if (!TryFindStorageRoot(out root))
            {
                return false;
            }
            return IsMainTabActive(root, mainTab) &&
                IsSubTabActive(root, mainTab, subTab);
        }

        public static string GetSelectionDiagnostics(
            int mainTab,
            int subTab)
        {
            Element root;
            if (!TryFindStorageRoot(out root))
            {
                return "MainEnabled=False" +
                    "|SelectedSubAddress=0x0" +
                    "|ExpectedSubAddress=0x0";
            }

            Element expected;
            TryFindSubTabButton(
                root,
                mainTab,
                subTab,
                out expected);
            Element selected = SafeChild(
                root,
                2, 0, 1, mainTab, 0, 0, 5);
            return "MainEnabled=" +
                IsMainTabActive(root, mainTab) +
                "|SelectedSubAddress=" + FormatAddress(selected) +
                "|ExpectedSubAddress=" + FormatAddress(expected);
        }

        private static bool IsMainTabActive(
            Element root,
            int mainTab)
        {
            return IsEnabled(SafeChild(
                root,
                2, 0, 0, 0, mainTab));
        }

        private static bool IsSubTabActive(
            Element root,
            int mainTab,
            int subTab)
        {
            Element expected;
            if (!IsMainTabActive(root, mainTab) ||
                !TryFindSubTabButton(
                    root,
                    mainTab,
                    subTab,
                    out expected))
            {
                return false;
            }

            Element selected = SafeChild(
                root,
                2, 0, 1, mainTab, 0, 0, 5);
            return SameAddress(expected, selected);
        }

        private static bool TryFindSubTabButton(
            Element root,
            int mainTab,
            int subTab,
            out Element button)
        {
            button = null;
            if (root == null ||
                mainTab < 0 || mainTab > 2 ||
                subTab < 0 || subTab > 4)
            {
                return false;
            }

            Element container = SafeChild(
                root,
                2, 0, 1, mainTab, 0, 0);
            List<Element> buttons;
            try
            {
                buttons = container == null
                    ? null
                    : container.Children;
            }
            catch
            {
                return false;
            }
            if (buttons == null)
            {
                return false;
            }

            string wanted = (subTab + 1).ToString();
            foreach (Element candidate in buttons)
            {
                try
                {
                    if (candidate != null &&
                        candidate.IsValid &&
                        candidate.FindTextInElementChildrens(wanted) != null)
                    {
                        button = candidate;
                        return true;
                    }
                }
                catch
                {
                    // Ignore the fade bar and malformed button branches.
                }
            }
            return false;
        }

        private static bool TryFindPageLayer(
            Element root,
            int requestedMain,
            int requestedSub,
            out int mainTab,
            out int subTab,
            out Element pageLayer)
        {
            mainTab = -1;
            subTab = -1;
            pageLayer = null;
            int firstMain = requestedMain >= 0 ? requestedMain : 0;
            int lastMain = requestedMain >= 0 ? requestedMain : 2;
            int firstSub = requestedSub >= 0 ? requestedSub : 0;
            int lastSub = requestedSub >= 0 ? requestedSub : 4;
            for (int main = firstMain; main <= lastMain; main++)
            {
                if (!IsMainTabActive(root, main))
                {
                    continue;
                }
                Element pagesContainer = SafeChild(
                    root,
                    2, 0, 1, main, 0, 1);
                if (!HasChildCount(pagesContainer, 5))
                {
                    continue;
                }
                for (int sub = firstSub; sub <= lastSub; sub++)
                {
                    if (!IsSubTabActive(root, main, sub))
                    {
                        continue;
                    }
                    Element layer = SafeChild(
                        root,
                        2, 0, 1, main, 0, 1, sub, 0);
                    if (!IsVisible(layer))
                    {
                        continue;
                    }
                    mainTab = main;
                    subTab = sub;
                    pageLayer = layer;
                    return true;
                }
            }
            return false;
        }

        private static bool TryFindStorageRoot(out Element storageRoot)
        {
            storageRoot = null;
            List<Element> roots;
            try
            {
                roots = LokiPoe.GetGuiElements();
            }
            catch
            {
                return false;
            }
            if (roots == null)
            {
                return false;
            }

            var seenAddresses = new HashSet<string>(
                StringComparer.Ordinal);
            // Only inspect each top-level element and its direct children.
            // The Chart Storage window exposes child 1 as
            // id=label_title, text=Chart Storage.
            foreach (Element root in roots)
            {
                if (root == null)
                {
                    continue;
                }
                if (!seenAddresses.Add(FormatAddress(root)))
                {
                    continue;
                }

                try
                {
                    if (!root.IsValid || !root.IsVisible)
                    {
                        continue;
                    }
                }
                catch
                {
                    continue;
                }

                List<Element> children;
                try
                {
                    children = root.Children;
                }
                catch
                {
                    continue;
                }

                if (children == null)
                {
                    continue;
                }

                foreach (Element child in children)
                {
                    try
                    {
                        if (child != null &&
                            child.IsVisible &&
                            String.Equals(
                                child.IdLabel,
                                "label_title",
                                StringComparison.OrdinalIgnoreCase) &&
                            String.Equals(
                                child.Text,
                                "Chart Storage",
                                StringComparison.OrdinalIgnoreCase))
                        {
                            Element clientArea = SafeChild(root, 2);
                            if (clientArea == null ||
                                !String.Equals(
                                    clientArea.IdLabel,
                                    "client_area",
                                    StringComparison.OrdinalIgnoreCase))
                            {
                                continue;
                            }
                            storageRoot = root;
                            return true;
                        }
                    }
                    catch
                    {
                        // Continue through the small top-level list.
                    }
                }
            }
            return false;
        }

        private static int GetRawDictionaryCount(
            InventorySlotUiElement slot)
        {
            try
            {
                return slot == null ||
                    slot.DictionaryIdElements == null
                        ? 0
                        : slot.DictionaryIdElements.Count;
            }
            catch
            {
                return 0;
            }
        }

        private static bool IsEnabled(Element element)
        {
            try
            {
                return element != null &&
                    element.IsValid &&
                    element.IsVisible &&
                    element.IsEnable;
            }
            catch
            {
                return false;
            }
        }

        private static bool SameAddress(
            Element first,
            Element second)
        {
            try
            {
                return first != null &&
                    second != null &&
                    first.IsValid &&
                    second.IsValid &&
                    first.Address == second.Address;
            }
            catch
            {
                return false;
            }
        }

        private static bool IsVisible(Element element)
        {
            try
            {
                return element != null &&
                    element.IsValid &&
                    element.IsVisible;
            }
            catch
            {
                return false;
            }
        }

        private static bool HasChildCount(Element element, int expected)
        {
            try
            {
                return IsVisible(element) &&
                    element.Children != null &&
                    element.Children.Count == expected;
            }
            catch
            {
                return false;
            }
        }

        private static string FormatAddress(Element element)
        {
            try
            {
                return element == null
                    ? "0x0"
                    : "0x" + element.Address.ToString("X");
            }
            catch
            {
                return "0x0";
            }
        }

        private static string FormatGeometry(Element element)
        {
            try
            {
                if (element == null)
                {
                    return "invalid";
                }
                Vector2i center = element.CenterClickLocation();
                return (int)element.Width + "x" +
                    (int)element.Height + "@" + center;
            }
            catch
            {
                return "invalid";
            }
        }

        private static Element SafeChild(
            Element root,
            params int[] indices)
        {
            try
            {
                return root == null
                    ? null
                    : root.GetChildFromIndices(indices);
            }
            catch
            {
                return null;
            }
        }

        private static bool Click(Element element)
        {
            try
            {
                if (element == null ||
                    !element.IsValid ||
                    !element.IsVisible)
                {
                    return false;
                }

                Vector2i location = element.CenterClickLocation();
                LokiPoe.Input.MoveMouseToScreenPos(
                    location.X,
                    location.Y);
                LokiPoe.Input.ClickLMB();
                return true;
            }
            catch
            {
                return false;
            }
        }

        private static bool IsUsable(InventorySlotUiElement slot)
        {
            try
            {
                return slot != null &&
                       slot.IsValid &&
                       slot.IsVisible &&
                       slot.DictionaryIdElements != null;
            }
            catch
            {
                return false;
            }
        }

        private static bool TryBindServerInventory(
            InventoryControlWrapper control,
            ISet<int> rawKeys,
            out Inventory inventory)
        {
            inventory = null;
            if (control == null)
            {
                return false;
            }

            var preferredIds = new List<int>();
            if (_cachedRequestedInventoryId >= 0)
            {
                preferredIds.Add(_cachedRequestedInventoryId);
            }
            if (!preferredIds.Contains(ChartStorageServerInventoryId))
            {
                preferredIds.Add(ChartStorageServerInventoryId);
            }

            foreach (int requestedId in preferredIds)
            {
                Inventory preferred;
                if (TryAcceptInventory(
                        requestedId,
                        rawKeys,
                        true,
                        out preferred))
                {
                    _cachedRequestedInventoryId = requestedId;
                    control.SetInventory(preferred);
                    inventory = preferred;
                    return true;
                }
                if (requestedId == _cachedRequestedInventoryId)
                {
                    _cachedRequestedInventoryId = -1;
                }
            }

            if (DateTime.UtcNow < _nextDynamicInventoryProbeUtc)
            {
                return false;
            }
            _nextDynamicInventoryProbeUtc =
                DateTime.UtcNow.AddSeconds(2);

            Inventory best = null;
            int bestRequestedId = -1;
            int bestScore = Int32.MinValue;
            for (int requestedId = 0; requestedId <= 255; requestedId++)
            {
                Inventory candidate;
                int score;
                if (!TryAcceptInventory(
                        requestedId,
                        rawKeys,
                        false,
                        out candidate,
                        out score) ||
                    score <= bestScore)
                {
                    continue;
                }
                best = candidate;
                bestRequestedId = requestedId;
                bestScore = score;
            }

            if (best == null)
            {
                AllflameLog.Info(
                    "CHART_STORAGE_NATIVE_BIND_TIMEOUT" +
                    "|Scanned=0-255" +
                    "|RawItems=" + (rawKeys == null
                        ? 0
                        : rawKeys.Count));
                return false;
            }

            _cachedRequestedInventoryId = bestRequestedId;
            control.SetInventory(best);
            inventory = best;
            AllflameLog.Info(
                "CHART_STORAGE_NATIVE_BOUND" +
                "|RequestedId=" + bestRequestedId +
                "|ResolvedId=" + best.Id +
                "|Mode=DynamicScan" +
                "|Items=" + (best.Items == null ? 0 : best.Items.Count));
            return true;
        }

        private static bool TryAcceptInventory(
            int requestedId,
            ISet<int> rawKeys,
            bool logRejected,
            out Inventory inventory)
        {
            int ignoredScore;
            return TryAcceptInventory(
                requestedId,
                rawKeys,
                logRejected,
                out inventory,
                out ignoredScore);
        }

        private static bool TryAcceptInventory(
            int requestedId,
            ISet<int> rawKeys,
            bool logRejected,
            out Inventory inventory,
            out int score)
        {
            inventory = GetPlayerInventoryById(requestedId);
            score = Int32.MinValue;
            try
            {
                List<Item> items = inventory == null ||
                    inventory.Items == null
                        ? new List<Item>()
                        : inventory.Items;
                int rawItemCount = rawKeys == null ? 0 : rawKeys.Count;
                int charts = items.Count(AllflameContext.IsChartItem);
                int keyMatches = CountRawKeyMatches(items, rawKeys);
                bool valid = inventory != null && inventory.IsValid;
                bool shape = valid && IsStorageInventoryShape(inventory);
                bool onlyCharts = items.Count > 0 && charts == items.Count;
                bool keysMatched = rawItemCount == 0 ||
                    keyMatches == rawItemCount;
                bool accepted = valid &&
                    shape &&
                    onlyCharts &&
                    keysMatched;
                if (logRejected || shape)
                {
                    AllflameLog.Info(
                        (accepted
                            ? "CHART_STORAGE_NATIVE_PROBE"
                            : "CHART_STORAGE_NATIVE_CANDIDATE_REJECTED") +
                        "|RequestedId=" + requestedId +
                        "|CandidateNull=" + (inventory == null) +
                        "|ResolvedId=" + (inventory == null
                            ? -1
                            : inventory.Id) +
                        "|Valid=" + valid +
                        "|Requested=" + (inventory != null &&
                            inventory.IsRequested) +
                        "|Rows=" + (inventory == null
                            ? -1
                            : inventory.Rows) +
                        "|Columns=" + (inventory == null
                            ? -1
                            : inventory.Columns) +
                        "|Items=" + items.Count +
                        "|Charts=" + charts +
                        "|KeyMatches=" + keyMatches +
                        "|RawItems=" + rawItemCount +
                        "|Accepted=" + accepted);
                }
                if (!accepted)
                {
                    inventory = null;
                    return false;
                }
                score =
                    (inventory.IsRequested ? 1000 : 0) +
                    keyMatches * 100 +
                    items.Count;
                return true;
            }
            catch (Exception ex)
            {
                if (logRejected)
                {
                    AllflameLog.Info(
                        "CHART_STORAGE_NATIVE_CANDIDATE_REJECTED" +
                        "|RequestedId=" + requestedId +
                        "|Reason=" + ex.GetType().Name +
                        "|Message=" +
                        (ex.Message ?? String.Empty).Replace("|", "/"));
                }
                inventory = null;
                return false;
            }
        }

        private static Inventory GetPlayerInventoryById(int id)
        {
            try
            {
                return LokiPoe.InstanceInfo.GetPlayerInventoryById(id);
            }
            catch
            {
                return null;
            }
        }

        private static int CountRawKeyMatches(
            IEnumerable<Item> items,
            ISet<int> rawKeys)
        {
            if (items == null || rawKeys == null || rawKeys.Count == 0)
            {
                return 0;
            }
            return items.Count(item =>
                item != null &&
                item.LocalId != 0 &&
                rawKeys.Contains(item.LocalId));
        }

        public static bool IsStorageInventoryShape(Inventory inventory)
        {
            return inventory != null &&
                inventory.Rows == 1 &&
                inventory.Columns == 60;
        }

    }

    internal sealed class DeepwaterVoyageSnapshot
    {
        public bool IsOpened { get; }
        public int AvailableChartCount { get; }
        public int BoardChartCount { get; }
        public int BoardSlotCount { get; }
        public bool BeginVoyageEnabled { get; }
        public string BoardSignature { get; }

        public DeepwaterVoyageSnapshot(
            bool isOpened,
            int availableChartCount,
            int boardChartCount,
            int boardSlotCount,
            bool beginVoyageEnabled,
            string boardSignature)
        {
            IsOpened = isOpened;
            AvailableChartCount = availableChartCount;
            BoardChartCount = boardChartCount;
            BoardSlotCount = boardSlotCount;
            BeginVoyageEnabled = beginVoyageEnabled;
            BoardSignature = boardSignature ?? String.Empty;
        }
    }

    internal static class NativeDeepwaterVoyageUi
    {
        public static bool TryCapture(
            out DeepwaterVoyageSnapshot snapshot)
        {
            snapshot = null;
            if (!AllflameSettings.Instance.UseNativeVoyagePlannerRead)
            {
                return false;
            }
            try
            {
                bool isOpened =
                    LokiPoe.InGameState.DeepwaterVoyageUi.IsOpened;
                int availableCharts = 0;
                int boardCharts = 0;
                int boardSlots = 0;
                bool beginEnabled = false;
                string boardSignature = String.Empty;
                var signature = new StringBuilder();

                if (isOpened)
                {
                    var inventory =
                        LokiPoe.InGameState.DeepwaterVoyageUi.ChartsInventory;
                    if (inventory != null)
                    {
                        foreach (var control in inventory)
                        {
                            if (control == null)
                            {
                                continue;
                            }
                            try
                            {
                                var item = control.Item;
                                if (item != null &&
                                    item.IsValid &&
                                    AllflameContext.IsChartItem(item))
                                {
                                    availableCharts++;
                                }
                            }
                            catch
                            {
                                // Ignore a slot while DPB refreshes its item.
                            }
                        }
                    }

                    var map =
                        LokiPoe.InGameState.DeepwaterVoyageUi.VoyageMap;
                    if (map != null)
                    {
                        int rows = map.GetLength(0);
                        int columns = map.GetLength(1);
                        boardSlots = rows * columns;
                        for (int row = 0; row < rows; row++)
                        {
                            for (int column = 0;
                                 column < columns;
                                 column++)
                            {
                                var square = map[row, column];
                                int directions = square == null
                                    ? 0
                                    : Convert.ToInt32(square.Directions);
                                if (directions != 0)
                                {
                                    boardCharts++;
                                }
                                if (signature.Length > 0)
                                {
                                    signature.Append(',');
                                }
                                signature.Append(directions);
                            }
                        }
                    }

                    beginEnabled =
                        LokiPoe.InGameState.DeepwaterVoyageUi
                            .IsBeginVoyageEnabled;
                    boardSignature = signature.ToString();
                }

                snapshot = new DeepwaterVoyageSnapshot(
                    isOpened,
                    availableCharts,
                    boardCharts,
                    boardSlots,
                    beginEnabled,
                    boardSignature);
                AllflameLog.Throttled(
                    "voyage_dpb_snapshot",
                    TimeSpan.FromSeconds(2),
                    "VOYAGE_DPB_SNAPSHOT" +
                    "|Available=" + availableCharts +
                    "|Board=" + boardCharts +
                    "|BoardSlots=" + boardSlots +
                    "|BeginEnabled=" + beginEnabled +
                    "|Opened=" + isOpened +
                    "|BoardSignature=" + boardSignature);
                return true;
            }
            catch (Exception ex)
            {
                AllflameLog.Throttled(
                    "voyage_dpb_snapshot_failed",
                    TimeSpan.FromSeconds(5),
                    "VOYAGE_DPB_SNAPSHOT_FAILED" +
                    "|Exception=" + ex.GetType().Name +
                    "|Message=" +
                    (ex.Message ?? String.Empty).Replace("|", "/"));
                return false;
            }
        }

        public static bool TryClearBoard(out string reason)
        {
            reason = "Unavailable";
            try
            {
                if (!LokiPoe.InGameState.DeepwaterVoyageUi.IsOpened)
                {
                    reason = "PanelClosed";
                    return false;
                }
                LokiPoe.InGameState.DeepwaterVoyageUi.ClearBoard();
                reason = "Invoked";
                return true;
            }
            catch (Exception exception)
            {
                reason = exception.GetType().Name;
                return false;
            }
        }

        public static bool TryBeginVoyage(out string reason)
        {
            reason = "Unavailable";
            try
            {
                if (!LokiPoe.InGameState.DeepwaterVoyageUi.IsOpened)
                {
                    reason = "PanelClosed";
                    return false;
                }
                if (!LokiPoe.InGameState.DeepwaterVoyageUi
                        .IsBeginVoyageEnabled)
                {
                    reason = "ButtonDisabled";
                    return false;
                }
                LokiPoe.InGameState.DeepwaterVoyageUi.BeginVoyage();
                reason = "Invoked";
                return true;
            }
            catch (Exception exception)
            {
                reason = exception.GetType().Name;
                return false;
            }
        }

        public static bool TryFastMoveFirstChart(
            out FastMoveResult result,
            out string reason)
        {
            result = FastMoveResult.Failed;
            reason = "Unavailable";
            try
            {
                if (!LokiPoe.InGameState.DeepwaterVoyageUi.IsOpened)
                {
                    reason = "PanelClosed";
                    return false;
                }
                var inventory =
                    LokiPoe.InGameState.DeepwaterVoyageUi.ChartsInventory;
                if (inventory == null)
                {
                    reason = "InventoryNull";
                    return false;
                }
                foreach (var control in inventory)
                {
                    if (control == null)
                    {
                        continue;
                    }
                    var item = control.Item;
                    if (item == null ||
                        !item.IsValid ||
                        !AllflameContext.IsChartItem(item))
                    {
                        continue;
                    }
                    result = control.FastMove();
                    reason = result.ToString();
                    return result == FastMoveResult.None;
                }
                reason = "NoChart";
                return false;
            }
            catch (Exception exception)
            {
                reason = exception.GetType().Name;
                return false;
            }
        }
    }

