    internal static class DeepwaterChartDeviceUi
    {
        private const int MaximumNodesPerRoot = 450;
        private const int MaximumNodesPerScan = 1000;
        private const string StableWindowId = "deepwater_charts_window";
        private const int DescendTemplateWidth = 48;
        private const int DescendTemplateHeight = 14;
        private const double MinimumImageCorrelation = 0.62;
        private const string DescendTemplateBase64 =
            "";
        private const string DescendDisabled800TemplateBase64 =
            "";
        private const string DescendEnabled800TemplateBase64 =
            "";
        private const string DescendEnabled800V2TemplateBase64 =
            "";
        private static readonly byte[] DescendTemplate =
            Convert.FromBase64String(DescendTemplateBase64);
        private static readonly byte[] DescendDisabled800Template =
            Convert.FromBase64String(DescendDisabled800TemplateBase64);
        private static readonly byte[] DescendEnabled800Template =
            Convert.FromBase64String(DescendEnabled800V2TemplateBase64);
        private static readonly double DescendTemplateMean =
            DescendTemplate.Average(value => (double)value);
        private static readonly double DescendTemplateEnergy =
            DescendTemplate.Sum(
                value =>
                    (value - DescendTemplateMean) *
                    (value - DescendTemplateMean));
        private static readonly double DescendDisabled800TemplateMean =
            DescendDisabled800Template.Average(value => (double)value);
        private static readonly double DescendDisabled800TemplateEnergy =
            DescendDisabled800Template.Sum(
                value =>
                    (value - DescendDisabled800TemplateMean) *
                    (value - DescendDisabled800TemplateMean));
        private static readonly double DescendEnabled800TemplateMean =
            DescendEnabled800Template.Average(value => (double)value);
        private static readonly double DescendEnabled800TemplateEnergy =
            DescendEnabled800Template.Sum(
                value =>
                    (value - DescendEnabled800TemplateMean) *
                    (value - DescendEnabled800TemplateMean));
        private static DateTime _nextScanUtc = DateTime.MinValue;

        public static bool TryGetDescendButton(
            out Element descendButton)
        {
            descendButton = null;
            Element stableWindow;
            int stableRootIndex;
            string stableButtonPath;
            if (TryResolveStableWindow(
                    out stableWindow,
                    out descendButton,
                    out stableRootIndex,
                    out stableButtonPath))
            {
                AllflameLog.Throttled(
                    "deepwater_chart_device_stable_window",
                    TimeSpan.FromSeconds(3),
                    "CHART_DEVICE_WINDOW_RESOLVED" +
                    "|IdLabel=" + StableWindowId +
                    "|RootIndex=" + stableRootIndex +
                    "|WindowAddress=0x" +
                    stableWindow.Address.ToString("X") +
                    "|ButtonPath=" + stableButtonPath +
                    "|ButtonAddress=0x" +
                    descendButton.Address.ToString("X"));
                return true;
            }

            if (DateTime.UtcNow < _nextScanUtc)
            {
                return false;
            }
            _nextScanUtc = DateTime.UtcNow.AddMilliseconds(400);

            List<Element> roots = LokiPoe.GetGuiElements();
            if (roots == null)
            {
                return false;
            }

            int totalVisited = 0;
            Element bestGeometryCandidate = null;
            double bestGeometryScore = Double.MaxValue;

            // League windows are normally appended near the end. Each scan
            // has strict per-root and global budgets so malformed UI trees
            // cannot stall DPB's main coroutine.
            for (int i = roots.Count - 1; i >= 0; i--)
            {
                if (totalVisited >= MaximumNodesPerScan)
                {
                    break;
                }

                Element root = roots[i];
                try
                {
                    if (root == null ||
                        !HasVisibleSurface(root))
                    {
                        continue;
                    }
                }
                catch
                {
                    continue;
                }

                int visited = 0;
                Element found = FindDescend(
                    root,
                    0,
                    ref visited,
                    ref totalVisited,
                    ref bestGeometryCandidate,
                    ref bestGeometryScore);
                if (found != null)
                {
                    descendButton = found;
                    AllflameLog.Throttled(
                        "deepwater_chart_device_found",
                        TimeSpan.FromSeconds(3),
                        "CHART_DEVICE_UI|Found=True|Mode=TextOrId|ButtonAddress=0x" +
                        found.Address.ToString("X") +
                        "|VisitedInRoot=" + visited +
                        "|VisitedTotal=" + totalVisited);
                    return true;
                }
            }

            if (bestGeometryCandidate != null)
            {
                descendButton = bestGeometryCandidate;
                Vector2i center =
                    bestGeometryCandidate.CenterClickLocation();
                AllflameLog.Throttled(
                    "deepwater_chart_device_geometry_found",
                    TimeSpan.FromSeconds(3),
                    "CHART_DEVICE_UI|Found=True|Mode=Geometry" +
                    "|ButtonAddress=0x" +
                    bestGeometryCandidate.Address.ToString("X") +
                    "|Center=" + center.X + "," + center.Y +
                    "|Size=" +
                    bestGeometryCandidate.Width.ToString("0") + "x" +
                    bestGeometryCandidate.Height.ToString("0") +
                    "|Score=" + bestGeometryScore.ToString("0.0") +
                    "|VisitedTotal=" + totalVisited);
                return true;
            }

            AllflameLog.Throttled(
                "deepwater_chart_device_not_found",
                TimeSpan.FromSeconds(3),
                "CHART_DEVICE_UI|Found=False|VisitedTotal=" +
                totalVisited);
            return false;
        }

        public static bool IsStableWindowOpen
        {
            get
            {
                Element window;
                Element button;
                int rootIndex;
                string buttonPath;
                return TryResolveStableWindow(
                    out window,
                    out button,
                    out rootIndex,
                    out buttonPath,
                    false);
            }
        }

        private static bool TryResolveStableWindow(
            out Element window,
            out Element descendButton,
            out int rootIndex,
            out string buttonPath,
            bool requireButton = true)
        {
            window = null;
            descendButton = null;
            rootIndex = -1;
            buttonPath = String.Empty;
            List<Element> roots;
            try
            {
                roots = LokiPoe.GetGuiElements();
            }
            catch
            {
                return false;
            }
            if (roots == null)
            {
                return false;
            }

            // IdLabel is stable while the top-level root index changes between
            // clients and UI sessions. Check every root before recursive scans.
            for (int i = 0; i < roots.Count; i++)
            {
                Element candidate = roots[i];
                try
                {
                    if (candidate == null ||
                        !candidate.IsValid ||
                        (!candidate.IsVisible &&
                         !candidate.IsVisibleLocal) ||
                        !String.Equals(
                            candidate.IdLabel,
                            StableWindowId,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        continue;
                    }
                }
                catch
                {
                    continue;
                }

                window = candidate;
                rootIndex = i;
                int visited = 0;
                descendButton = FindStableDescend(
                    candidate,
                    "root[" + i + "]",
                    0,
                    ref visited,
                    out buttonPath);
                return !requireButton || descendButton != null;
            }
            return false;
        }

        private static Element FindStableDescend(
            Element element,
            string path,
            int depth,
            ref int visited,
            out string foundPath)
        {
            foundPath = String.Empty;
            if (element == null ||
                depth > 12 ||
                visited >= MaximumNodesPerRoot)
            {
                return null;
            }
            visited++;
            if (IsVisibleDescend(element))
            {
                foundPath = path;
                return element;
            }

            List<Element> children;
            try
            {
                children = element.Children;
            }
            catch
            {
                return null;
            }
            if (children == null)
            {
                return null;
            }
            for (int i = 0; i < children.Count; i++)
            {
                string childPath;
                Element found = FindStableDescend(
                    children[i],
                    path + "/" + i,
                    depth + 1,
                    ref visited,
                    out childPath);
                if (found != null)
                {
                    foundPath = childPath;
                    return found;
                }
            }
            return null;
        }

        private static bool HasVisibleSurface(Element root)
        {
            try
            {
                if (root.IsVisible)
                {
                    return true;
                }

                List<Element> children = root.Children;
                if (children == null)
                {
                    return false;
                }

                foreach (Element child in children)
                {
                    if (child != null && child.IsVisible)
                    {
                        return true;
                    }
                }
            }
            catch
            {
                return false;
            }
            return false;
        }

        public static bool ClickDescend(
            Element descendButton,
            int attempt)
        {
            try
            {
                double geometryScore;
                if (IsVisibleDescend(descendButton) ||
                    IsGeometryDescendCandidate(
                        descendButton,
                        out geometryScore))
                {
                    Vector2i location =
                        descendButton.CenterClickLocation();
                    string strategy =
                        DispatchDescendClick(
                            location,
                            attempt);
                    AllflameLog.Info(
                        "CHART_DEVICE_DESCEND_ELEMENT|Client=" +
                        location.X + "," + location.Y +
                        "|Address=0x" +
                        descendButton.Address.ToString("X") +
                        "|Text=" +
                        SanitizeUiText(descendButton.Text) +
                        "|Id=" +
                        SanitizeUiText(descendButton.IdLabel) +
                        "|Attempt=" + attempt +
                        "|Strategy=" + strategy);
                    return true;
                }

                Vector2i imageLocation;
                double imageCorrelation;
                if (TryFindDescendByImage(
                        out imageLocation,
                        out imageCorrelation))
                {
                    string strategy =
                        DispatchDescendClick(
                            imageLocation,
                            attempt);
                    AllflameLog.Info(
                        "CHART_DEVICE_DESCEND_IMAGE|Client=" +
                        imageLocation.X + "," + imageLocation.Y +
                        "|Correlation=" +
                        imageCorrelation.ToString("0.000") +
                        "|Attempt=" + attempt +
                        "|Strategy=" + strategy);
                    return true;
                }

                AllflameLog.Info(
                    "CHART_DEVICE_DESCEND_UNRESOLVED" +
                    "|Attempt=" + attempt +
                    "|Element=False|Image=False" +
                    "|Action=RetryWithoutBlindCoordinate");
                return false;
            }
            catch
            {
                return false;
            }
        }

        private static string DispatchDescendClick(
            Vector2i clientLocation,
            int attempt)
        {
            int strategy = Math.Max(1, attempt);
            strategy = (strategy - 1) % 7 + 1;
            var clientRectangle = LokiPoe.ClientWindowInfo.Client;

            LokiPoe.ProcessHookManager.ClearAllKeyStates();
            switch (strategy)
            {
                case 1:
                    DreamPoeBot.BotFramework.MouseManager.SetMousePosition(
                        clientLocation,
                        false);
                    DreamPoeBot.BotFramework.MouseManager.ClickLMB(0, 0);
                    return "MouseManagerClick";

                case 2:
                    DreamPoeBot.BotFramework.MouseManager.SetMousePosition(
                        clientLocation,
                        false);
                    DreamPoeBot.BotFramework.MouseManager.ClickLMB(0, 0);
                    return "MouseManagerClickRetry";

                case 3:
                    LokiPoe.Input.MoveMouseToScreenPos(
                        clientRectangle.Left + clientLocation.X,
                        clientRectangle.Top + clientLocation.Y,
                        true);
                    LokiPoe.Input.ClickLMB(
                        clientRectangle.Left + clientLocation.X,
                        clientRectangle.Top + clientLocation.Y);
                    return "LokiExplicitCoordinates";

                case 4:
                    int clientX = clientLocation.X;
                    int clientY = clientLocation.Y;
                    int packedCoordinates =
                        (clientY << 16) |
                        (clientX & 0xFFFF);
                    DreamPoeBot.Loki.Game.Interop.PostMessage(
                        LokiPoe.ClientWindowHandle,
                        0x0200,
                        IntPtr.Zero,
                        new IntPtr(packedCoordinates));
                    DreamPoeBot.Loki.Game.Interop.PostMessage(
                        LokiPoe.ClientWindowHandle,
                        0x0201,
                        new IntPtr(1),
                        new IntPtr(packedCoordinates));
                    DreamPoeBot.Loki.Game.Interop.PostMessage(
                        LokiPoe.ClientWindowHandle,
                        0x0202,
                        IntPtr.Zero,
                        new IntPtr(packedCoordinates));
                    return "Win32PostMessage";

                case 5:
                    DreamPoeBot.Loki.Game.Interop.SetForegroundWindow(
                        LokiPoe.ClientWindowHandle);
                    DreamPoeBot.Loki.Game.Interop.SetCursorPos(
                        clientRectangle.Left + clientLocation.X,
                        clientRectangle.Top + clientLocation.Y);
                    NativeMouseEvent(0x0002, 0, 0, 0, UIntPtr.Zero);
                    NativeMouseEvent(0x0004, 0, 0, 0, UIntPtr.Zero);
                    return "Win32ForegroundMouseEvent";

                case 6:
                    DreamPoeBot.BotFramework.MouseManager.SetMousePosition(
                        clientLocation,
                        false);
                    DreamPoeBot.BotFramework.MouseManager.DblClickLMB(0, 0);
                    return "MouseManagerDoubleClick";

                default:
                    DreamPoeBot.Loki.Game.Interop.SetForegroundWindow(
                        LokiPoe.ClientWindowHandle);
                    DreamPoeBot.BotFramework.MouseManager.SetMousePosition(
                        clientLocation,
                        false);
                    LokiPoe.Input.SimulateKeyEvent(
                        System.Windows.Forms.Keys.Enter,
                        true,
                        false,
                        true);
                    return "ForegroundHoverEnter";
            }
        }

        [System.Runtime.InteropServices.DllImport(
            "user32.dll",
            EntryPoint = "mouse_event")]
        private static extern void NativeMouseEvent(
            uint flags,
            uint dx,
            uint dy,
            uint data,
            UIntPtr extraInfo);

        private static bool TryFindDescendByImage(
            out Vector2i clientLocation,
            out double bestCorrelation)
        {
            clientLocation = new Vector2i();
            bestCorrelation = -1.0;

            try
            {
                var client = LokiPoe.ClientWindowInfo.Client;
                int clientWidth = client.Right - client.Left;
                int clientHeight = client.Bottom - client.Top;
                if (clientWidth < 800 || clientHeight < 500)
                {
                    return false;
                }

                using (var screenshot = new System.Drawing.Bitmap(
                    clientWidth,
                    clientHeight,
                    System.Drawing.Imaging.PixelFormat.Format24bppRgb))
                {
                    using (System.Drawing.Graphics graphics =
                        System.Drawing.Graphics.FromImage(screenshot))
                    {
                        graphics.CopyFromScreen(
                            client.Left,
                            client.Top,
                            0,
                            0,
                            new System.Drawing.Size(
                                clientWidth,
                                clientHeight),
                            System.Drawing.CopyPixelOperation.SourceCopy);
                    }

                    var rectangle = new System.Drawing.Rectangle(
                        0,
                        0,
                        clientWidth,
                        clientHeight);
                    System.Drawing.Imaging.BitmapData bitmapData =
                        screenshot.LockBits(
                            rectangle,
                            System.Drawing.Imaging.ImageLockMode.ReadOnly,
                            System.Drawing.Imaging.PixelFormat.Format24bppRgb);
                    try
                    {
                        int stride = Math.Abs(bitmapData.Stride);
                        byte[] pixels =
                            new byte[stride * clientHeight];
                        System.Runtime.InteropServices.Marshal.Copy(
                            bitmapData.Scan0,
                            pixels,
                            0,
                            pixels.Length);

                        int expectedX = clientWidth / 2;
                        int expectedY =
                            (int)Math.Round(clientHeight * 0.607);
                        int searchRadiusX =
                            Math.Max(85, clientWidth / 12);
                        int searchRadiusY =
                            Math.Max(45, clientHeight / 14);
                        double referenceScale =
                            Math.Min(
                                clientWidth / 1920.0,
                                clientHeight / 1071.0);
                        double[] scales =
                            { 0.82, 0.92, 1.0, 1.08, 1.18 };
                        int bestCenterX = expectedX;
                        int bestCenterY = expectedY;

                        foreach (double scale in scales)
                        {
                            int candidateWidth = Math.Max(
                                75,
                                (int)Math.Round(
                                    145.0 * referenceScale * scale));
                            int candidateHeight = Math.Max(
                                20,
                                (int)Math.Round(
                                    37.0 * referenceScale * scale));
                            int halfWidth = candidateWidth / 2;
                            int halfHeight = candidateHeight / 2;
                            int minX = Math.Max(
                                halfWidth,
                                expectedX - searchRadiusX);
                            int maxX = Math.Min(
                                clientWidth - halfWidth - 1,
                                expectedX + searchRadiusX);
                            int minY = Math.Max(
                                halfHeight,
                                expectedY - searchRadiusY);
                            int maxY = Math.Min(
                                clientHeight - halfHeight - 1,
                                expectedY + searchRadiusY);

                            for (int centerY = minY;
                                 centerY <= maxY;
                                 centerY += 3)
                            {
                                for (int centerX = minX;
                                     centerX <= maxX;
                                     centerX += 3)
                                {
                                    double correlation =
                                        CalculateImageCorrelation(
                                            pixels,
                                            stride,
                                            clientWidth,
                                            clientHeight,
                                            centerX - halfWidth,
                                            centerY - halfHeight,
                                            candidateWidth,
                                            candidateHeight);
                                    if (correlation > bestCorrelation)
                                    {
                                        bestCorrelation = correlation;
                                        bestCenterX = centerX;
                                        bestCenterY = centerY;
                                    }
                                }
                            }
                        }

                        if (bestCorrelation >= MinimumImageCorrelation)
                        {
                            clientLocation = new Vector2i(
                                bestCenterX,
                                bestCenterY);
                            AllflameLog.Throttled(
                                "descend_image_found",
                                TimeSpan.FromSeconds(2),
                                "CHART_DEVICE_IMAGE|Found=True" +
                                "|Correlation=" +
                                bestCorrelation.ToString("0.000") +
                                "|ClientLocation=" +
                                clientLocation +
                                "|Client=" + clientWidth + "x" +
                                clientHeight);
                            return true;
                        }

                        AllflameLog.Throttled(
                            "descend_image_not_found",
                            TimeSpan.FromSeconds(3),
                            "CHART_DEVICE_IMAGE|Found=False" +
                            "|BestCorrelation=" +
                            bestCorrelation.ToString("0.000") +
                            "|Client=" + clientWidth + "x" +
                            clientHeight +
                            "|Required=" +
                            MinimumImageCorrelation.ToString("0.000"));
                    }
                    finally
                    {
                        screenshot.UnlockBits(bitmapData);
                    }
                }
            }
            catch (Exception exception)
            {
                AllflameLog.Throttled(
                    "descend_image_error",
                    TimeSpan.FromSeconds(3),
                    "CHART_DEVICE_IMAGE|Error=" +
                    exception.GetType().Name +
                    "|Message=" + exception.Message);
            }

            return false;
        }

        private static double CalculateImageCorrelation(
            byte[] pixels,
            int stride,
            int imageWidth,
            int imageHeight,
            int candidateLeft,
            int candidateTop,
            int candidateWidth,
            int candidateHeight)
        {
            double legacy = CalculateDescendCorrelationForTemplate(
                pixels, stride, imageWidth, imageHeight,
                candidateLeft, candidateTop,
                candidateWidth, candidateHeight,
                DescendTemplate,
                DescendTemplateMean,
                DescendTemplateEnergy);
            double disabled800 = CalculateDescendCorrelationForTemplate(
                pixels, stride, imageWidth, imageHeight,
                candidateLeft, candidateTop,
                candidateWidth, candidateHeight,
                DescendDisabled800Template,
                DescendDisabled800TemplateMean,
                DescendDisabled800TemplateEnergy);
            double enabled800 = CalculateDescendCorrelationForTemplate(
                pixels, stride, imageWidth, imageHeight,
                candidateLeft, candidateTop,
                candidateWidth, candidateHeight,
                DescendEnabled800Template,
                DescendEnabled800TemplateMean,
                DescendEnabled800TemplateEnergy);
            return Math.Max(legacy, Math.Max(disabled800, enabled800));
        }

        private static double CalculateDescendCorrelationForTemplate(
            byte[] pixels,
            int stride,
            int imageWidth,
            int imageHeight,
            int candidateLeft,
            int candidateTop,
            int candidateWidth,
            int candidateHeight,
            byte[] template,
            double templateMean,
            double templateEnergy)
        {
            double sum = 0.0;
            double sumSquares = 0.0;
            double cross = 0.0;
            int count = template.Length;

            for (int templateY = 0;
                 templateY < DescendTemplateHeight;
                 templateY++)
            {
                int sourceY = candidateTop +
                    templateY * (candidateHeight - 1) /
                    (DescendTemplateHeight - 1);
                if (sourceY < 0 || sourceY >= imageHeight)
                {
                    return -1.0;
                }

                int row = sourceY * stride;
                for (int templateX = 0;
                     templateX < DescendTemplateWidth;
                     templateX++)
                {
                    int sourceX = candidateLeft +
                        templateX * (candidateWidth - 1) /
                        (DescendTemplateWidth - 1);
                    if (sourceX < 0 || sourceX >= imageWidth)
                    {
                        return -1.0;
                    }

                    int pixelIndex = row + sourceX * 3;
                    double gray =
                        (pixels[pixelIndex + 2] * 77 +
                         pixels[pixelIndex + 1] * 150 +
                         pixels[pixelIndex] * 29) / 256.0;
                    double templateCentered =
                        template[
                            templateY * DescendTemplateWidth +
                            templateX] -
                        templateMean;
                    sum += gray;
                    sumSquares += gray * gray;
                    cross += gray * templateCentered;
                }
            }

            double candidateEnergy =
                sumSquares - sum * sum / count;
            if (candidateEnergy <= 0.001 ||
                templateEnergy <= 0.001)
            {
                return -1.0;
            }

            return cross /
                Math.Sqrt(
                    candidateEnergy *
                    templateEnergy);
        }

        private static Element FindDescend(
            Element element,
            int depth,
            ref int visited,
            ref int totalVisited,
            ref Element bestGeometryCandidate,
            ref double bestGeometryScore)
        {
            if (element == null ||
                depth > 12 ||
                visited >= MaximumNodesPerRoot ||
                totalVisited >= MaximumNodesPerScan)
            {
                return null;
            }

            visited++;
            totalVisited++;
            if (IsVisibleDescend(element))
            {
                return element;
            }

            double geometryScore;
            if (IsGeometryDescendCandidate(
                    element,
                    out geometryScore) &&
                geometryScore < bestGeometryScore)
            {
                bestGeometryCandidate = element;
                bestGeometryScore = geometryScore;
            }

            List<Element> children;
            try
            {
                children = element.Children;
            }
            catch
            {
                return null;
            }

            if (children == null)
            {
                return null;
            }

            foreach (Element child in children)
            {
                Element found = FindDescend(
                    child,
                    depth + 1,
                    ref visited,
                    ref totalVisited,
                    ref bestGeometryCandidate,
                    ref bestGeometryScore);
                if (found != null)
                {
                    return found;
                }
                if (visited >= MaximumNodesPerRoot ||
                    totalVisited >= MaximumNodesPerScan)
                {
                    break;
                }
            }
            return null;
        }

        private static bool IsVisibleDescend(Element element)
        {
            try
            {
                if (element == null ||
                    !element.IsValid ||
                    !element.IsVisible)
                {
                    return false;
                }

                string text = (element.Text ?? String.Empty).Trim();
                string id = element.IdLabel ?? String.Empty;
                return
                    String.Equals(
                        text,
                        "DESCEND",
                        StringComparison.OrdinalIgnoreCase) ||
                    id.IndexOf(
                        "descend",
                        StringComparison.OrdinalIgnoreCase) >= 0;
            }
            catch
            {
                return false;
            }
        }

        private static bool IsGeometryDescendCandidate(
            Element element,
            out double score)
        {
            score = Double.MaxValue;
            try
            {
                if (element == null ||
                    !element.IsValid ||
                    !element.IsVisible ||
                    !element.IsEnable)
                {
                    return false;
                }

                float width = element.Width;
                float height = element.Height;
                if (width < 45f || width > 320f ||
                    height < 14f || height > 90f)
                {
                    return false;
                }

                var client = LokiPoe.ClientWindowInfo.Client;
                int clientWidth = client.Right - client.Left;
                int clientHeight = client.Bottom - client.Top;
                if (clientWidth <= 0 || clientHeight <= 0)
                {
                    return false;
                }

                Vector2i center = element.CenterClickLocation();
                int expectedX = client.Left + clientWidth / 2;
                int expectedY = client.Top +
                    (int)Math.Round(clientHeight * 0.607);
                int deltaX = Math.Abs(center.X - expectedX);
                int deltaY = Math.Abs(center.Y - expectedY);
                if (deltaX > Math.Max(90, clientWidth / 18) ||
                    deltaY > Math.Max(45, clientHeight / 20))
                {
                    return false;
                }

                // Prefer a centered, wide, button-shaped element.
                score = deltaX + deltaY * 2.0 +
                    Math.Abs(width - 140f) * 0.08 +
                    Math.Abs(height - 34f) * 0.15;
                return true;
            }
            catch
            {
                return false;
            }
        }

        private static string SanitizeUiText(string value)
        {
            if (String.IsNullOrEmpty(value))
            {
                return String.Empty;
            }

            return value.Replace("|", "/")
                .Replace("\r", " ")
                .Replace("\n", " ");
        }
    }

    internal sealed class IdentifyInventoryChartsTask : ObserverTask
    {
        private const float ValerieInteractionRange = 50f;
        private DateTime _nextActionUtc = DateTime.MinValue;

        public IdentifyInventoryChartsTask()
            : base(
                "IdentifyInventoryChartsTask",
                "Uses Valerie's Identify Items service when an unidentified Chart is in inventory.") { }

        public override async Task<bool> Run()
        {
            bool inHub =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            if (!inHub ||
                !AllflameSettings.Instance.AutoRunChartAreas ||
                LokiPoe.InGameState.MapDeviceUi.IsOpened ||
                NativeDeepwaterChartDeviceUi.IsOpened)
            {
                return false;
            }

            List<Item> unidentifiedCharts = GetUnidentifiedCharts();
            if (unidentifiedCharts.Count == 0)
            {
                return false;
            }

            if (DateTime.UtcNow < _nextActionUtc)
            {
                return true;
            }

            if (LokiPoe.InGameState.NpcDialogUi.IsOpened)
            {
                string identifyOption = FindIdentifyOption();
                if (!String.IsNullOrEmpty(identifyOption))
                {
                    var result =
                        LokiPoe.InGameState.NpcDialogUi.Converse(
                            identifyOption);
                    _nextActionUtc = DateTime.UtcNow.AddSeconds(2);
                    AllflameLog.Info(
                        "CHART_IDENTIFY|Action=Converse" +
                        "|Npc=Valerie, the Corsair" +
                        "|Option=" + SanitizeLogValue(identifyOption) +
                        "|UnidentifiedBefore=" +
                        unidentifiedCharts.Count +
                        "|Result=" + result);
                    await LokiCoroutine.Sleep(700);
                    return true;
                }

                string availableOptions = String.Join(
                    ", ",
                    GetDialogOptions()
                        .Select(SanitizeLogValue)
                        .Take(12)
                        .ToArray());
                AllflameLog.Throttled(
                    "chart_identify_option_missing",
                    TimeSpan.FromSeconds(5),
                    "CHART_IDENTIFY_WAIT|Reason=IdentifyOptionMissing" +
                    "|Unidentified=" + unidentifiedCharts.Count +
                    "|DialogTitle=" +
                    SanitizeLogValue(
                        LokiPoe.InGameState.NpcDialogUi.Title) +
                    "|Options=" + availableOptions);
                _nextActionUtc = DateTime.UtcNow.AddSeconds(1);
                return true;
            }

            NetworkObject valerie = AllflameContext.ValerieObject;
            if (valerie == null)
            {
                AllflameLog.Throttled(
                    "chart_identify_valerie_missing",
                    TimeSpan.FromSeconds(5),
                    "CHART_IDENTIFY_WAIT|Reason=ValerieMissing" +
                    "|Unidentified=" + unidentifiedCharts.Count);
                return true;
            }

            float interactionRange =
                Math.Max(
                    ValerieInteractionRange,
                    AllflameSettings.Instance.InteractDistance);
            if (ContinueValerieApproachRecovery(
                    valerie,
                    "Valerie identify Charts"))
            {
                return true;
            }
            if (valerie.Distance > interactionRange)
            {
                await MoveOrInteract(
                    valerie,
                    "Valerie identify Charts",
                    interactionRange);
                return true;
            }

            await FinishMovementBeforeInteraction(
                "Valerie Identify");
            bool interacted = await InteractWithRecovery(valerie);
            _nextActionUtc = DateTime.UtcNow.AddMilliseconds(800);
            AllflameLog.Info(
                "CHART_IDENTIFY|Action=Interact" +
                "|Npc=Valerie, the Corsair" +
                "|Unidentified=" + unidentifiedCharts.Count +
                "|Distance=" + valerie.Distance.ToString("0.0") +
                "|InteractionRange=" +
                interactionRange.ToString("0.0") +
                "|Success=" + interacted);
            if (!interacted)
            {
                StartValerieApproachRecovery(
                    valerie,
                    "Valerie identify Charts",
                    "IdentifyInteractionNotHighlighted");
                AllflameLog.Throttled(
                    "chart_identify_interact_recovery",
                    TimeSpan.FromSeconds(2),
                    "CHART_IDENTIFY_RECOVERY|Reason=NpcNotHighlighted" +
                    "|Action=AlternateApproach" +
                    "|Distance=" + valerie.Distance.ToString("0.0"));
            }
            return true;
        }

        private static List<Item> GetUnidentifiedCharts()
        {
            try
            {
                InventoryControlWrapper control =
                    LokiPoe.InGameState.InventoryUi.InventoryControl_Main;
                if (control == null ||
                    control.Inventory == null ||
                    control.Inventory.Items == null)
                {
                    return new List<Item>();
                }

                return control.Inventory.Items
                    .Where(item =>
                        AllflameContext.IsChartItem(item) &&
                        !item.IsIdentified)
                    .ToList();
            }
            catch (Exception ex)
            {
                AllflameLog.Throttled(
                    "chart_identify_scan_failed",
                    TimeSpan.FromSeconds(5),
                    "CHART_IDENTIFY_SCAN_FAILED|" +
                    ex.GetType().Name + "|" +
                    SanitizeLogValue(ex.Message));
                return new List<Item>();
            }
        }

        private static string FindIdentifyOption()
        {
            return GetDialogOptions()
                .FirstOrDefault(text =>
                    text.IndexOf(
                        "Identify",
                        StringComparison.OrdinalIgnoreCase) >= 0);
        }

        private static IEnumerable<string> GetDialogOptions()
        {
            try
            {
                List<string> options = new List<string>();
                var entries =
                    LokiPoe.InGameState.NpcDialogUi.DialogEntries;
                if (entries != null)
                {
                    options.AddRange(
                        entries
                            .Where(entry =>
                                entry != null &&
                                entry.IsDialogChoice &&
                                !String.IsNullOrWhiteSpace(entry.Text))
                            .Select(entry => entry.Text.Trim()));
                }

                var entries2 =
                    LokiPoe.InGameState.NpcDialogUi.DialogEntries2;
                if (entries2 != null)
                {
                    options.AddRange(
                        entries2
                            .Where(entry =>
                                entry != null &&
                                entry.IsDialogChoice &&
                                !String.IsNullOrWhiteSpace(entry.Text))
                            .Select(entry => entry.Text.Trim()));
                }

                return options.Distinct(
                    StringComparer.OrdinalIgnoreCase).ToList();
            }
            catch
            {
                return Enumerable.Empty<string>();
            }
        }

        private static string SanitizeLogValue(string value)
        {
            return String.IsNullOrEmpty(value)
                ? String.Empty
                : value.Replace("|", "/")
                    .Replace("\r", " ")
                    .Replace("\n", " ");
        }
    }

    internal sealed class PlanVoyageTask : ObserverTask
    {
        private const float ValerieInteractionRange = 50f;
        private DateTime _nextBathysphereAttemptUtc = DateTime.MinValue;
        private int _bathysphereAttempts;
        private float _bestValerieDistance = Single.MaxValue;
        private DateTime _lastValerieProgressUtc = DateTime.MinValue;
        private int _valerieInteractionFailures;
        private DateTime _valerieEffectDeadlineUtc =
            DateTime.MinValue;

        public PlanVoyageTask()
            : base("OpenChartDeviceTask", "Opens the Chart Device through Valerie or the Bathysphere.") { }

        public override async Task<bool> Run()
        {
            bool inHub =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            if (!inHub ||
                !AllflameSettings.Instance.AutoRunChartAreas ||
                AllflameRunState.VoyageStarted ||
                !AllflameRunState.ChartStorageChecked ||
                AllflameRunState.ChartRequested)
            {
                _valerieEffectDeadlineUtc =
                    DateTime.MinValue;
                ResetValerieApproachRecovery(0);
                AllflameProgressWatchdog.Clear(Name);
                return false;
            }

            if (AllflameContext.InventoryChartCount <= 0)
            {
                AllflameLog.Throttled(
                    "chart_inventory_empty",
                    TimeSpan.FromSeconds(5),
                    "CHART_DEVICE_WAIT|InventoryCharts=0");
                return true;
            }

            bool standardChartUiOpened =
                LokiPoe.InGameState.MapDeviceUi.IsOpened;
            bool nativeDeepwaterUiOpened =
                NativeDeepwaterChartDeviceUi.IsOpened;
            if (standardChartUiOpened || nativeDeepwaterUiOpened)
            {
                _valerieEffectDeadlineUtc =
                    DateTime.MinValue;
                ResetValerieApproachRecovery(0);
                AllflameProgressWatchdog.Clear(Name);
                AllflameSettings settings = AllflameSettings.Instance;
                if (!settings.ChartDeviceUnlocked)
                {
                    settings.ChartDeviceUnlocked = true;
                    settings.Save();
                }

                _bathysphereAttempts = 0;
                AllflameRunState.MarkChartRequested();
                AllflameLog.Info(
                    "CHART_DEVICE_OPEN|Source=Detected" +
                    "|Ui=" +
                    (nativeDeepwaterUiOpened
                        ? "DeepwaterNative"
                        : "MapDevice") +
                    "|InventoryCharts=" +
                    AllflameContext.InventoryChartCount);
                return false;
            }

            AllflameSettings currentSettings = AllflameSettings.Instance;
            bool canReuseBathysphereThisSession =
                currentSettings.ChartDeviceUnlocked &&
                AllflameRunState.CompletedChartAreas > 0;
            if (canReuseBathysphereThisSession &&
                _bathysphereAttempts < 3)
            {
                if (DateTime.UtcNow < _nextBathysphereAttemptUtc)
                {
                    return true;
                }

                NetworkObject bathysphere = AllflameContext.BathysphereObject;
                if (bathysphere != null)
                {
                    if (bathysphere.Distance >
                        Math.Max(
                            35,
                            AllflameSettings.Instance.InteractDistance))
                    {
                        _bathysphereAttempts = 3;
                        AllflameLog.Info(
                            "CHART_DEVICE_BATHYSPHERE_SKIPPED" +
                            "|Reason=UnreachableOrTooFar" +
                            "|Distance=" +
                            bathysphere.Distance.ToString("0.0") +
                            "|Fallback=Valerie");
                    }
                    else
                    {
                        await FinishMovementBeforeInteraction(
                            "Bathysphere Chart Device");
                        bool interacted =
                            await InteractWithRecovery(bathysphere);
                        _bathysphereAttempts++;
                        _nextBathysphereAttemptUtc =
                            DateTime.UtcNow.AddSeconds(2);
                        AllflameLog.Info(
                            "CHART_DEVICE_OPEN_ATTEMPT|Source=Bathysphere|Attempt=" +
                            _bathysphereAttempts + "|Success=" + interacted +
                            "|Distance=" +
                            bathysphere.Distance.ToString("0.0"));
                        return true;
                    }
                }
            }

            if (LokiPoe.InGameState.NpcDialogUi.IsOpened &&
                LokiPoe.InGameState.NpcDialogUi.CanConverse("Chart Area"))
            {
                _valerieEffectDeadlineUtc =
                    DateTime.MinValue;
                var result = LokiPoe.InGameState.NpcDialogUi.Converse("Chart Area");
                AllflameSettings settings = AllflameSettings.Instance;
                if (!settings.ChartDeviceUnlocked)
                {
                    settings.ChartDeviceUnlocked = true;
                    settings.Save();
                }
                AllflameRunState.MarkChartRequested(true);
                ResetValerieApproachRecovery(0);
                AllflameProgressWatchdog.Clear(Name);
                AllflameLog.Info(
                    "ACTION|Task=" + Name + "|Action=Converse|Option=Chart Area|Result=" + result);
                AllflameLog.Info(
                    "CHART_DEVICE_OPEN|Source=ValerieConversationAssumed|InventoryCharts=" +
                    AllflameContext.InventoryChartCount);
                return true;
            }

            NetworkObject valerie = AllflameContext.ValerieObject;
            if (valerie != null)
            {
                AllflameSettings settings =
                    AllflameSettings.Instance;
                float interactionRange =
                    Math.Max(
                        ValerieInteractionRange,
                        settings.InteractDistance);
                if (_valerieEffectDeadlineUtc !=
                    DateTime.MinValue)
                {
                    if (DateTime.UtcNow <
                        _valerieEffectDeadlineUtc)
                    {
                        return true;
                    }

                    _valerieEffectDeadlineUtc =
                        DateTime.MinValue;
                    _valerieInteractionFailures++;
                    BlacklistCurrentValerieApproach(
                        "InteractionSucceededWithoutDialog");
                    StartValerieApproachRecovery(
                        valerie,
                        "Valerie, the Corsair",
                        "InteractionEffectTimeout");
                    AllflameLog.Info(
                        "CHART_DEVICE_NPC_EFFECT_TIMEOUT" +
                        "|Npc=Valerie, the Corsair" +
                        "|Distance=" +
                        valerie.Distance.ToString("0.0") +
                        "|Failures=" +
                        _valerieInteractionFailures +
                        "|Action=BlacklistAndAlternateApproach");
                    return true;
                }
                if (ContinueValerieApproachRecovery(
                        valerie,
                        "Valerie, the Corsair"))
                {
                    return true;
                }
                if (LokiPoe.Me != null &&
                    IsValerieApproachPositionBlacklisted(
                        LokiPoe.Me.Position))
                {
                    StartValerieApproachRecovery(
                        valerie,
                        "Valerie, the Corsair",
                        "CurrentPositionBlacklisted");
                    AllflameLog.Throttled(
                        "chart_device_valerie_position_blacklisted",
                        TimeSpan.FromSeconds(2),
                        "CHART_DEVICE_RECOVERY" +
                        "|Reason=CurrentPositionBlacklisted" +
                        "|Player=" + LokiPoe.Me.Position +
                        "|Action=AlternateApproach");
                    return true;
                }
                if (valerie.Distance > interactionRange)
                {
                    if (_lastValerieProgressUtc == DateTime.MinValue ||
                        valerie.Distance + 4f < _bestValerieDistance)
                    {
                        _bestValerieDistance = valerie.Distance;
                        _lastValerieProgressUtc = DateTime.UtcNow;
                    }
                    else if (DateTime.UtcNow - _lastValerieProgressUtc >=
                             TimeSpan.FromSeconds(4))
                    {
                        _bestValerieDistance = Single.MaxValue;
                        _lastValerieProgressUtc = DateTime.UtcNow;
                        StartValerieApproachRecovery(
                            valerie,
                            "Valerie, the Corsair",
                            "ChartDeviceApproachStalled");
                        AllflameLog.Info(
                            "CHART_DEVICE_RECOVERY|Reason=ValerieApproachStalled" +
                            "|Action=AlternateApproach" +
                            "|Distance=" +
                            valerie.Distance.ToString("0.0"));
                        return true;
                    }

                    await MoveOrInteract(
                        valerie,
                        "Valerie, the Corsair",
                        interactionRange);
                    return true;
                }

                await FinishMovementBeforeInteraction(
                    "Valerie Chart Device");
                bool interacted =
                    await InteractWithRecovery(valerie);
                _bestValerieDistance = Single.MaxValue;
                _lastValerieProgressUtc = DateTime.MinValue;
                _valerieInteractionFailures =
                    interacted
                        ? 0
                        : _valerieInteractionFailures + 1;
                _valerieEffectDeadlineUtc =
                    interacted
                        ? DateTime.UtcNow.AddMilliseconds(900)
                        : DateTime.MinValue;
                if (interacted)
                {
                    AllflameProgressWatchdog.MarkProgress(
                        "ValerieInteractionIssued");
                }
                AllflameLog.Info(
                    "ACTION|Task=" + Name +
                    "|Action=Interact|Target=Valerie, the Corsair" +
                    "|Success=" + interacted +
                    "|Distance=" +
                    valerie.Distance.ToString("0.0") +
                    "|InteractRange=" +
                    interactionRange.ToString("0.0"));
                if (!interacted)
                {
                    StartValerieApproachRecovery(
                        valerie,
                        "Valerie, the Corsair",
                        "ChartDeviceInteractionFailed");
                    AllflameLog.Throttled(
                        "chart_device_valerie_interact_recovery",
                        TimeSpan.FromSeconds(2),
                        "CHART_DEVICE_RECOVERY|Reason=NpcNotHighlighted" +
                        "|Action=AlternateApproach" +
                        "|Distance=" +
                        valerie.Distance.ToString("0.0"));
                }
                return true;
            }

            AllflameLog.Throttled(
                "valerie_missing",
                TimeSpan.FromSeconds(5),
                "CHART_AREA_WAIT|ValerieAvailable=False");
            return true;
        }
    }

    internal sealed class EnterBathysphereTask : ObserverTask
    {
        private const int MaximumDescendAttempts = 3;
        private const int MaximumDescendConfirmationRecoveries = 2;
        private const int MaximumEmptyDeviceRecoveries = 2;
        private const int MaximumPortalApproachRecoveries = 3;
        private const int MaximumPortalPathFailuresPerAnchor = 2;
        private static readonly Vector2i[] PortalApproachOffsets =
        {
            new Vector2i(0, 0),
            new Vector2i(42, 0),
            new Vector2i(0, 42),
            new Vector2i(-42, 0),
            new Vector2i(0, -42),
            new Vector2i(30, 30),
            new Vector2i(-30, 30),
            new Vector2i(-30, -30),
            new Vector2i(30, -30)
        };
        private static readonly TimeSpan CapacityFullConfirmation =
            TimeSpan.FromSeconds(3);
        private static readonly TimeSpan EmptyDeviceRecoveryDelay =
            TimeSpan.FromSeconds(3);
        private static readonly TimeSpan TransactionTimeout =
            TimeSpan.FromSeconds(30);
        private static readonly TimeSpan DescendConfirmationTimeout =
            TimeSpan.FromSeconds(3);
        private static readonly TimeSpan PortalAppearanceTimeout =
            TimeSpan.FromSeconds(6);
        private static readonly TimeSpan PortalEntryTimeout =
            TimeSpan.FromSeconds(15);
        private DateTime _nextActivateUtc = DateTime.MinValue;
        private DateTime _descendDisabledSinceUtc =
            DateTime.MinValue;
        private bool _customLoadAttempted;
        private int _customChartLocalId;
        private int _descendAttempts;
        private bool _descendIssued;
        private bool _descendConfirmed;
        private bool _loadConfirmationLogged;
        private DateTime _descendIssuedUtc = DateTime.MinValue;
        private int _descendConfirmationRecoveries;
        private DateTime _portalConfirmedUtc = DateTime.MinValue;
        private DateTime _portalWaitUntilUtc = DateTime.MinValue;
        private DateTime _nextPortalInteractUtc = DateTime.MinValue;
        private DateTime _lastTransitionHeartbeatUtc = DateTime.MinValue;
        private int _portalUiRecoveries;
        private int _transactionRecoveries;
        private bool _capacityRecoveryClosePending;
        private uint _transactionAreaHash;
        private DateTime _transactionStartedUtc = DateTime.MinValue;
        private int _emptyDeviceRecoveries;
        private bool _portalAppearanceProgressMarked;
        private bool _portalInteractionProgressMarked;
        private int _portalMoveFailures;
        private int _portalApproachAnchorIndex;
        private int _portalApproachRecoveries;
        private int _portalTargetId;
        private Vector2i _portalTargetPosition;
        private DateTime _nextPortalApproachRecoveryUtc =
            DateTime.MinValue;
        private bool _portalPathBlocked;

        public EnterBathysphereTask()
            : base("LoadChartDeviceTask", "Loads a Chart into the device and presses Descend.") { }

        public override void Start()
        {
            ResetTransactionState();
        }

        public override void Stop()
        {
            ResetTransactionState();
            AllflameAreaTransitionGuard.Reset();
            AllflameProgressWatchdog.Clear(Name);
        }

        private void ResetTransactionState()
        {
            _capacityRecoveryClosePending = false;
            _nextActivateUtc = DateTime.MinValue;
            _customLoadAttempted = false;
            _customChartLocalId = 0;
            _descendAttempts = 0;
            _descendIssued = false;
            _descendConfirmed = false;
            _loadConfirmationLogged = false;
            _descendIssuedUtc = DateTime.MinValue;
            _descendConfirmationRecoveries = 0;
            _portalConfirmedUtc = DateTime.MinValue;
            _portalWaitUntilUtc = DateTime.MinValue;
            _nextPortalInteractUtc = DateTime.MinValue;
            _lastTransitionHeartbeatUtc = DateTime.MinValue;
            _portalUiRecoveries = 0;
            _transactionRecoveries = 0;
            _descendDisabledSinceUtc = DateTime.MinValue;
            _transactionAreaHash = 0;
            _transactionStartedUtc = DateTime.MinValue;
            _emptyDeviceRecoveries = 0;
            _portalAppearanceProgressMarked = false;
            _portalInteractionProgressMarked = false;
            _portalMoveFailures = 0;
            _portalApproachAnchorIndex = 0;
            _portalApproachRecoveries = 0;
            _portalTargetId = 0;
            _portalTargetPosition = new Vector2i();
            _nextPortalApproachRecoveryUtc = DateTime.MinValue;
            _portalPathBlocked = false;
        }

        private void ResetCustomLoadState()
        {
            _customLoadAttempted = false;
            _customChartLocalId = 0;
            _loadConfirmationLogged = false;
            _descendDisabledSinceUtc = DateTime.MinValue;
            _nextActivateUtc = DateTime.MinValue;
        }

        private void BeginTransaction()
        {
            _transactionAreaHash = AllflameContext.AreaHash;
            _transactionStartedUtc = DateTime.UtcNow;
            _emptyDeviceRecoveries = 0;
            AllflameProgressWatchdog.BeginExplicitProgress(
                Name,
                0,
                "ChartDeviceTransaction");
            AllflameProgressWatchdog.SetRetry(0);
            AllflameLog.Info(
                "CHART_DEVICE_TRANSACTION_START" +
                "|AreaHash=" + _transactionAreaHash +
                "|InventoryCharts=" +
                AllflameContext.InventoryChartCount);
        }

        public override async Task<bool> Run()
        {
            bool inHub =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            if (_capacityRecoveryClosePending)
            {
                _capacityRecoveryClosePending = false;
                await Coroutines.CloseBlockingWindows();
                _nextActivateUtc =
                    DateTime.UtcNow.AddMilliseconds(750);
                AllflameLog.Info(
                    "CHART_DEVICE_CAPACITY_RECOVERY" +
                    "|Action=CloseChartDeviceOnNextCycle" +
                    "|OneActionPerCycle=True");
                return true;
            }
            if (!inHub ||
                !AllflameRunState.ChartRequested)
            {
                if (_transactionAreaHash != 0)
                {
                    AllflameLog.Info(
                        "CHART_DEVICE_TRANSACTION_RESET" +
                        "|Reason=" +
                        (!inHub
                            ? "AreaTransition"
                            : "ChartRequestCleared") +
                        "|PreviousAreaHash=" +
                        _transactionAreaHash +
                        "|CurrentAreaHash=" +
                        AllflameContext.AreaHash +
                        "|DescendConfirmed=" +
                        _descendConfirmed);
                }
                ResetTransactionState();
                AllflameProgressWatchdog.Clear(Name);
                return false;
            }

            if (_transactionAreaHash == 0)
            {
                BeginTransaction();
            }
            else if (_transactionAreaHash !=
                     AllflameContext.AreaHash)
            {
                AllflameLog.Info(
                    "CHART_DEVICE_TRANSACTION_RESET" +
                    "|Reason=AreaHashChanged" +
                    "|PreviousAreaHash=" +
                    _transactionAreaHash +
                    "|CurrentAreaHash=" +
                    AllflameContext.AreaHash);
                ResetTransactionState();
                BeginTransaction();
            }

            TimeSpan transactionElapsed =
                DateTime.UtcNow - _transactionStartedUtc;
            LogTransitionHeartbeat(transactionElapsed);
            if (!_descendConfirmed &&
                transactionElapsed >= TransactionTimeout)
            {
                string detail =
                    "ActiveTask=" + Name +
                    "|AreaHash=" + AllflameContext.AreaHash +
                    "|ElapsedMs=" +
                    (int)transactionElapsed.TotalMilliseconds +
                    "|DescendAttempts=" + _descendAttempts +
                    "|DescendConfirmed=" + _descendConfirmed +
                    "|EmptyDeviceRecoveries=" +
                    _emptyDeviceRecoveries +
                    "|PortalUiRecoveries=" + _portalUiRecoveries +
                    "|LoadedChartId=" + _customChartLocalId;
                AllflameLog.Info(
                    "CHART_DEVICE_TRANSACTION_RECOVERY|" + detail +
                    "|Action=RefreshUiAndRetry");
                await RecoverChartDeviceTransaction(
                    "TransactionTimeout",
                    true);
                return true;
            }

            if (_descendIssued)
            {
                bool nativeUiOpen =
                    NativeDeepwaterChartDeviceUi.IsOpened;
                bool stableUiOpen =
                    DeepwaterChartDeviceUi.IsStableWindowOpen;
                TimeSpan issuedFor =
                    DateTime.UtcNow - _descendIssuedUtc;
                if (!nativeUiOpen && !stableUiOpen)
                {
                    _descendIssued = false;
                    _descendIssuedUtc = DateTime.MinValue;
                    _descendConfirmed = true;
                    _portalConfirmedUtc = DateTime.UtcNow;
                    _portalWaitUntilUtc =
                        DateTime.UtcNow + PortalAppearanceTimeout;
                    AllflameProgressWatchdog.MarkProgress(
                        "DescendUiClosed");
                    AllflameLog.Info(
                        "CHART_DEVICE_DESCEND_CONFIRMED" +
                        "|Evidence=UiClosed" +
                        "|Attempt=" + _descendAttempts +
                        "|ElapsedMs=" +
                        (int)issuedFor.TotalMilliseconds);
                }
                else if (issuedFor < DescendConfirmationTimeout)
                {
                    AllflameLog.Throttled(
                        "chart_device_descend_confirmation_wait",
                        TimeSpan.FromMilliseconds(500),
                        "CHART_DEVICE_DESCEND_CONFIRM_WAIT" +
                        "|Attempt=" + _descendAttempts +
                        "|NativeUiOpen=" + nativeUiOpen +
                        "|StableUiOpen=" + stableUiOpen +
                        "|ElapsedMs=" +
                        (int)issuedFor.TotalMilliseconds);
                    return true;
                }
                else
                {
                    return await RecoverDescendConfirmation(
                        issuedFor,
                        nativeUiOpen,
                        stableUiOpen);
                }
            }

            if (_descendConfirmed)
            {
                bool chartUiReopened =
                    NativeDeepwaterChartDeviceUi.IsOpened ||
                    DeepwaterChartDeviceUi.IsStableWindowOpen;
                TimeSpan portalEntryElapsed =
                    DateTime.UtcNow - _portalConfirmedUtc;
                if (portalEntryElapsed >= PortalEntryTimeout)
                {
                    AllflameLog.Info(
                        "BATHYSPHERE_PORTAL_ENTRY_RECOVERY" +
                        "|Attempts=" + _descendAttempts +
                        "|UiRecoveries=" + _portalUiRecoveries +
                        "|ElapsedMs=" +
                        (int)portalEntryElapsed.TotalMilliseconds +
                        "|Action=RefreshPathAndReacquire");
                    return RecoverBathysphereApproach(
                        "PortalEntryTimeout");
                }

                if (chartUiReopened)
                {
                    List<Item> reopenedDeviceItems =
                        NativeDeepwaterChartDeviceUi.IsOpened
                            ? NativeDeepwaterChartDeviceUi.DeviceItems
                            : new List<Item>();
                    _portalUiRecoveries++;
                    _nextPortalInteractUtc =
                        DateTime.UtcNow.AddMilliseconds(450);
                    _portalWaitUntilUtc =
                        DateTime.UtcNow + PortalAppearanceTimeout;
                    AllflameLog.Info(
                        "CHART_PORTAL_UI_REOPENED" +
                        "|State=Recovery" +
                        "|Reason=PortalInteractionReopenedChartDevice" +
                        "|DeviceItems=" + reopenedDeviceItems.Count +
                        "|Recovery=" + _portalUiRecoveries +
                        "|DescendConfirmed=True" +
                        "|Action=CloseUiAndReacquirePortal");
                    await Coroutines.CloseBlockingWindows();
                    return true;
                }
            }

            if (_descendConfirmed &&
                AllflameContext.BathysphereAvailable &&
                AllflameContext.BathysphereObject != null)
            {
                NetworkObject portal =
                    AllflameContext.BathysphereObject;
                EnsurePortalApproachTarget(portal);
                if (!_portalAppearanceProgressMarked)
                {
                    _portalAppearanceProgressMarked = true;
                    AllflameProgressWatchdog.MarkProgress(
                        "ChartPortalAppeared");
                }
                AllflameLog.Throttled(
                    "bathysphere_portal_ready",
                    TimeSpan.FromSeconds(2),
                    "BATHYSPHERE_PORTAL_READY|Id=" +
                    portal.Id +
                    "|Name=" + portal.Name +
                    "|Metadata=" + portal.Metadata +
                    "|Distance=" +
                    portal.Distance.ToString("0.0") +
                    "|Targetable=" + portal.IsTargetable);

                if (portal.Distance <= 70f &&
                    DateTime.UtcNow >= _nextPortalInteractUtc)
                {
                    await FinishMovementBeforeInteraction(
                        "Chart Bathysphere Portal");
                    bool entered =
                        await InteractWithRecovery(portal);
                    AllflameLog.Info(
                        "BATHYSPHERE_ENTER|Id=" +
                        portal.Id +
                        "|Name=" + portal.Name +
                        "|Distance=" +
                        portal.Distance.ToString("0.0") +
                        "|Mode=DirectObjectInteraction" +
                        "|Success=" + entered);
                    if (entered)
                    {
                        AllflameAreaTransitionGuard.Arm(portal);
                        if (!_portalInteractionProgressMarked)
                        {
                            _portalInteractionProgressMarked = true;
                            AllflameProgressWatchdog.MarkProgress(
                                "ChartPortalInteractionIssued");
                        }
                        _nextPortalInteractUtc =
                            DateTime.UtcNow.AddMilliseconds(450);
                        return true;
                    }
                }

                Vector2i approachTarget =
                    PortalApproachTarget(portal);
                bool moving =
                    AllflameMovementCoordinator.MoveTowards(
                        approachTarget,
                        Name + " Bathysphere Capsule Extraction");
                if (moving)
                {
                    _portalMoveFailures = 0;
                    _portalPathBlocked = false;
                }
                else
                {
                    HandlePortalApproachFailure(
                        portal,
                        approachTarget);
                }
                AllflameLog.Throttled(
                    "bathysphere_approach",
                    TimeSpan.FromSeconds(2),
                    "BATHYSPHERE_APPROACH|Id=" +
                    portal.Id +
                    "|Name=" + portal.Name +
                    "|RequestedPosition=" +
                    approachTarget +
                    "|PortalPosition=" +
                    portal.Position +
                    "|AnchorIndex=" +
                    _portalApproachAnchorIndex +
                    "|PathFailures=" +
                    _portalMoveFailures +
                    "|Distance=" +
                    portal.Distance.ToString("0.0") +
                    "|Moving=" + moving);
                return true;
            }

            if (_descendConfirmed &&
                DateTime.UtcNow < _portalWaitUntilUtc)
            {
                AllflameLog.Throttled(
                    "bathysphere_portal_wait",
                    TimeSpan.FromSeconds(2),
                    "BATHYSPHERE_PORTAL_WAIT|Visible=False" +
                    "|RemainingMs=" +
                    Math.Max(
                        0,
                        (int)(_portalWaitUntilUtc -
                              DateTime.UtcNow).TotalMilliseconds));
                return true;
            }

            if (_descendConfirmed)
            {
                AllflameLog.Info(
                    "BATHYSPHERE_PORTAL_APPEARANCE_RECOVERY" +
                    "|Attempts=" + _descendAttempts +
                    "|ElapsedMs=" +
                    (int)(DateTime.UtcNow -
                          _portalConfirmedUtc).TotalMilliseconds +
                    "|Action=RefreshPathAndReacquire");
                return RecoverBathysphereApproach(
                    "PortalAppearanceTimeout");
            }

            Element descendButton;
            descendButton = null;
            bool nativeDeepwaterUiOpened =
                NativeDeepwaterChartDeviceUi.IsOpened;
            bool descendElementFound = false;
            if (!nativeDeepwaterUiOpened)
            {
                descendElementFound =
                    DeepwaterChartDeviceUi.TryGetDescendButton(
                        out descendButton);
            }
            bool customUiOpened =
                nativeDeepwaterUiOpened ||
                descendElementFound ||
                AllflameRunState.CustomChartDeviceExpected;
            bool standardUiOpened =
                LokiPoe.InGameState.MapDeviceUi.IsOpened;
            if (!standardUiOpened && !customUiOpened)
            {
                AllflameLog.Throttled(
                    "chart_device_wait",
                    TimeSpan.FromSeconds(2),
                    "CHART_DEVICE_WAIT|Opened=False");
                return true;
            }

            if (customUiOpened)
            {
                return await RunCustomChartDevice(
                    descendButton,
                    nativeDeepwaterUiOpened);
            }

            var deviceControl = LokiPoe.InGameState.MapDeviceUi.InventoryControl;
            List<Item> deviceItems =
                deviceControl == null ||
                deviceControl.Inventory == null ||
                deviceControl.Inventory.Items == null
                    ? new List<Item>()
                    : deviceControl.Inventory.Items.ToList();

            if (!deviceItems.Any(AllflameContext.IsChartItem))
            {
                var mainControl = LokiPoe.InGameState.InventoryUi.InventoryControl_Main;
                Item chart =
                    mainControl == null ||
                    mainControl.Inventory == null ||
                    mainControl.Inventory.Items == null
                        ? null
                        : mainControl.Inventory.Items.FirstOrDefault(AllflameContext.IsChartItem);
                if (chart == null)
                {
                    AllflameLog.Info("CHART_DEVICE_LOAD_FAILED|Reason=InventoryChartMissing");
                    return true;
                }

                bool moveResult =
                    await CtrlClickInventoryChart(mainControl, chart);
                AllflameLog.Info(
                    "CHART_DEVICE_LOAD|Id=" + chart.Id +
                    "|LocalId=" + chart.LocalId +
                    "|Name=" + chart.FullName +
                    "|Metadata=" + chart.Metadata +
                    "|Mode=CtrlClick" +
                    "|Result=" + moveResult);
                return true;
            }

            LogChartDeviceLoadConfirmed(
                "MapDevice",
                deviceItems.Count(AllflameContext.IsChartItem),
                AllflameContext.InventoryChartCount);

            if (DateTime.UtcNow < _nextActivateUtc)
            {
                return true;
            }

            var activateResult = LokiPoe.InGameState.MapDeviceUi.Activate();
            _nextActivateUtc = DateTime.UtcNow.AddSeconds(3);
            AllflameLog.Info(
                "CHART_DEVICE_DESCEND|DeviceCharts=" +
                deviceItems.Count(AllflameContext.IsChartItem) +
                "|Result=" + activateResult);
            return true;
        }

        private async Task<bool> RunCustomChartDevice(
            Element descendButton,
            bool nativeDeepwaterUiOpened)
        {
            var mainControl =
                LokiPoe.InGameState.InventoryUi.InventoryControl_Main;
            List<Item> inventoryItems =
                mainControl == null ||
                mainControl.Inventory == null ||
                mainControl.Inventory.Items == null
                    ? new List<Item>()
                    : mainControl.Inventory.Items.ToList();
            List<Item> nativeDeviceItems =
                nativeDeepwaterUiOpened
                    ? NativeDeepwaterChartDeviceUi.DeviceItems
                    : new List<Item>();
            bool nativeDeviceHasChart =
                nativeDeviceItems.Any(AllflameContext.IsChartItem) ||
                nativeDeviceItems.Count > 0;

            Item availableInventoryChart = inventoryItems
                .FirstOrDefault(AllflameContext.IsChartItem);
            bool staleLoadedChartId =
                nativeDeepwaterUiOpened &&
                !nativeDeviceHasChart &&
                _customLoadAttempted &&
                _customChartLocalId != 0 &&
                inventoryItems.All(
                    item => item.LocalId != _customChartLocalId) &&
                availableInventoryChart != null &&
                availableInventoryChart.LocalId != _customChartLocalId;
            if (staleLoadedChartId)
            {
                int staleLocalId = _customChartLocalId;
                ResetCustomLoadState();
                AllflameLog.Info(
                    "CHART_DEVICE_STATE_RESET" +
                    "|Reason=StaleLoadedChartId" +
                    "|PreviousLocalId=" + staleLocalId +
                    "|NextLocalId=" + availableInventoryChart.LocalId +
                    "|DeviceItems=0" +
                    "|Action=LoadCurrentInventoryChart");
            }

            bool movedChartLeftInventory =
                _customLoadAttempted &&
                (_customChartLocalId == 0 ||
                 inventoryItems.All(
                     item => item.LocalId != _customChartLocalId));
            bool chartLoadConfirmed =
                nativeDeepwaterUiOpened
                    ? nativeDeviceHasChart
                    : movedChartLeftInventory;
            if (chartLoadConfirmed)
            {
                LogChartDeviceLoadConfirmed(
                    nativeDeepwaterUiOpened
                        ? "DeepwaterNative"
                        : "DeepwaterFallback",
                    nativeDeepwaterUiOpened
                        ? nativeDeviceItems.Count
                        : 1,
                    inventoryItems.Count(
                        AllflameContext.IsChartItem));
            }
            if (!chartLoadConfirmed)
            {
                Item chart = inventoryItems
                    .FirstOrDefault(AllflameContext.IsChartItem);
                if (chart == null)
                {
                    if (_customLoadAttempted)
                    {
                        movedChartLeftInventory = true;
                    }
                    else
                    {
                        AllflameLog.Info(
                            "CHART_DEVICE_LOAD_FAILED|Reason=InventoryChartMissing|Ui=DeepwaterCustom");
                        return true;
                    }
                }
                else if (!_customLoadAttempted ||
                         chart.LocalId == _customChartLocalId)
                {
                    _customChartLocalId = chart.LocalId;
                    bool moveResult =
                        await CtrlClickInventoryChart(mainControl, chart);
                    _customLoadAttempted = moveResult;
                    AllflameLog.Info(
                        "CHART_DEVICE_LOAD|Ui=" +
                        (nativeDeepwaterUiOpened
                            ? "DeepwaterNative"
                            : "DeepwaterFallback") +
                        "|Id=" +
                        chart.Id + "|LocalId=" + chart.LocalId +
                        "|Name=" + chart.FullName +
                        "|Metadata=" + chart.Metadata +
                        "|Mode=CtrlClick" +
                        "|Result=" + moveResult);
                    return true;
                }
            }

            if (DateTime.UtcNow < _nextActivateUtc)
            {
                return true;
            }

            if (_descendAttempts >= MaximumDescendAttempts)
            {
                AllflameLog.Info(
                    "CHART_DEVICE_DESCEND_RECOVERY|Attempts=" +
                    _descendAttempts +
                    "|LoadedChartId=" + _customChartLocalId +
                    "|Action=CloseUiAndRetry");
                await RecoverChartDeviceTransaction(
                    "DescendAttemptsExhausted",
                    true);
                return true;
            }

            bool descendEnabled =
                !nativeDeepwaterUiOpened ||
                NativeDeepwaterChartDeviceUi.IsDescendEnabled;
            if (!descendEnabled)
            {
                bool voyageAutomationEnabled =
                    AllflameSettings.Instance.AutoPlanVoyage ||
                    AllflameSettings.Instance.StartVoyageWhenReady;
                if (_descendDisabledSinceUtc ==
                    DateTime.MinValue)
                {
                    _descendDisabledSinceUtc =
                        DateTime.UtcNow;
                }
                TimeSpan disabledFor =
                    DateTime.UtcNow -
                    _descendDisabledSinceUtc;
                if (voyageAutomationEnabled &&
                    nativeDeepwaterUiOpened &&
                    nativeDeviceHasChart &&
                    disabledFor >= CapacityFullConfirmation)
                {
                    InventoryControlWrapper nativeControl =
                        LokiPoe.InGameState.DeepwaterChartUi
                            .InventoryControl_Main;
                    Item loadedChart =
                        nativeDeviceItems.FirstOrDefault();
                    bool returned =
                        loadedChart != null &&
                        await CtrlClickInventoryChart(
                            nativeControl,
                            loadedChart);
                    AllflameLog.Info(
                        "CHART_DEVICE_CAPACITY_RECOVERY" +
                        "|DescendDisabledMs=" +
                        (int)disabledFor.TotalMilliseconds +
                        "|DeviceItems=" +
                        nativeDeviceItems.Count +
                        "|LoadedChartId=" +
                        _customChartLocalId +
                        "|ReturnedToInventory=" + returned +
                        "|Action=SwitchToVoyagePlanning");
                    AllflameRunState
                        .MarkVoyageCapacityFullFromChartDevice();
                    _customLoadAttempted = false;
                    _customChartLocalId = 0;
                    _descendAttempts = 0;
                    _descendIssued = false;
                    _descendConfirmed = false;
                    _descendIssuedUtc = DateTime.MinValue;
                    _portalConfirmedUtc = DateTime.MinValue;
                    _portalWaitUntilUtc = DateTime.MinValue;
                    _nextPortalInteractUtc = DateTime.MinValue;
                    _portalUiRecoveries = 0;
                    _descendDisabledSinceUtc =
                        DateTime.MinValue;
                    _capacityRecoveryClosePending = true;
                    return true;
                }
                if (nativeDeepwaterUiOpened &&
                    !nativeDeviceHasChart &&
                    disabledFor >= EmptyDeviceRecoveryDelay)
                {
                    if (_emptyDeviceRecoveries <
                        MaximumEmptyDeviceRecoveries)
                    {
                        _emptyDeviceRecoveries++;
                        int staleLocalId = _customChartLocalId;
                        ResetCustomLoadState();
                        AllflameProgressWatchdog.SetRetry(
                            _emptyDeviceRecoveries);
                        AllflameLog.Info(
                            "CHART_DEVICE_EMPTY_RECOVERY" +
                            "|Recovery=" + _emptyDeviceRecoveries +
                            "|PreviousLocalId=" + staleLocalId +
                            "|InventoryCharts=" +
                            inventoryItems.Count(
                                AllflameContext.IsChartItem) +
                            "|DeviceItems=0" +
                            "|Action=ResetLoadStateAndRetry");
                        return true;
                    }

                    string detail =
                        "ActiveTask=" + Name +
                        "|Reason=DescendDisabledWithEmptyDevice" +
                        "|Recoveries=" + _emptyDeviceRecoveries +
                        "|DisabledMs=" +
                        (int)disabledFor.TotalMilliseconds +
                        "|InventoryCharts=" +
                        inventoryItems.Count(
                            AllflameContext.IsChartItem) +
                        "|LoadedChartId=" + _customChartLocalId;
                    AllflameLog.Info(
                        "CHART_DEVICE_EMPTY_RECOVERY_EXHAUSTED|" +
                        detail + "|Action=RefreshUiAndRetry");
                    await RecoverChartDeviceTransaction(
                        "EmptyDeviceRecoveryExhausted",
                        true);
                    return true;
                }
                _nextActivateUtc =
                    DateTime.UtcNow.AddMilliseconds(500);
                AllflameLog.Throttled(
                    "native_descend_not_ready",
                    TimeSpan.FromSeconds(2),
                    "CHART_DEVICE_DESCEND_WAIT|Ui=DeepwaterNative" +
                    "|DeviceItems=" + nativeDeviceItems.Count +
                    "|LoadedChartId=" + _customChartLocalId +
                    "|IsDescendEnabled=False" +
                    "|DisabledMs=" +
                    (int)disabledFor.TotalMilliseconds);
                return true;
            }

            _descendDisabledSinceUtc = DateTime.MinValue;
            _descendAttempts++;
            AllflameLog.Info(
                "CHART_DEVICE_DESCEND_CALL_BEGIN" +
                "|Ui=" +
                (nativeDeepwaterUiOpened
                    ? "DeepwaterNative"
                    : "DeepwaterFallback") +
                "|Attempt=" + _descendAttempts +
                "|LoadedChartId=" + _customChartLocalId);
            bool clicked = false;
            try
            {
                clicked = nativeDeepwaterUiOpened
                    ? NativeDeepwaterChartDeviceUi.Descend()
                    : DeepwaterChartDeviceUi.ClickDescend(
                        descendButton,
                        _descendAttempts);
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "CHART_DEVICE_DESCEND_CALL_FAILED" +
                    "|Attempt=" + _descendAttempts +
                    "|Type=" + ex.GetType().Name +
                    "|Message=" +
                    (ex.Message ?? String.Empty).Replace("|", "/"));
            }
            AllflameLog.Info(
                "CHART_DEVICE_DESCEND_CALL_END" +
                "|Attempt=" + _descendAttempts +
                "|InputSent=" + clicked);
            if (clicked)
            {
                _descendIssued = true;
                _descendIssuedUtc = DateTime.UtcNow;
                AllflameProgressWatchdog.MarkProgress(
                    "DescendIssued");
            }
            _nextActivateUtc = DateTime.UtcNow.AddSeconds(2);
            AllflameLog.Info(
                "CHART_DEVICE_DESCEND|Ui=" +
                (nativeDeepwaterUiOpened
                    ? "DeepwaterNative"
                    : "DeepwaterFallback") +
                "|LoadedChartId=" +
                _customChartLocalId + "|Clicked=" + clicked +
                "|DeviceItems=" + nativeDeviceItems.Count +
                "|Attempt=" + _descendAttempts);
            return true;
        }

        private void EnsurePortalApproachTarget(NetworkObject portal)
        {
            if (_portalTargetId == portal.Id &&
                _portalTargetPosition == portal.Position)
            {
                return;
            }

            _portalTargetId = portal.Id;
            _portalTargetPosition = portal.Position;
            _portalMoveFailures = 0;
            _portalApproachAnchorIndex = 0;
            _portalPathBlocked = false;
            AllflameLog.Info(
                "BATHYSPHERE_APPROACH_TARGET_REFRESHED" +
                "|Id=" + portal.Id +
                "|Target=" + portal.Position +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|NavigationRevision=" +
                AllflameMovementCoordinator.NavigationRevision);
        }

        private Vector2i PortalApproachTarget(NetworkObject portal)
        {
            int index = Math.Max(
                0,
                Math.Min(
                    _portalApproachAnchorIndex,
                    PortalApproachOffsets.Length - 1));
            Vector2i offset = PortalApproachOffsets[index];
            return new Vector2i(
                portal.Position.X + offset.X,
                portal.Position.Y + offset.Y);
        }

        private void HandlePortalApproachFailure(
            NetworkObject portal,
            Vector2i approachTarget)
        {
            _portalPathBlocked = true;
            _portalMoveFailures++;
            AllflameProgressWatchdog.SetRetry(
                _portalApproachRecoveries *
                    PortalApproachOffsets.Length +
                _portalApproachAnchorIndex +
                _portalMoveFailures);
            AllflameLog.Info(
                "BATHYSPHERE_APPROACH_PATH_FAILURE" +
                "|Id=" + portal.Id +
                "|PortalPosition=" + portal.Position +
                "|ApproachTarget=" + approachTarget +
                "|Distance=" + portal.Distance.ToString("0.0") +
                "|Failures=" + _portalMoveFailures +
                "|AnchorIndex=" + _portalApproachAnchorIndex +
                "|NavigationRevision=" +
                AllflameMovementCoordinator.NavigationRevision +
                "|Action=RotateAnchorOrRecover");

            if (_portalMoveFailures < MaximumPortalPathFailuresPerAnchor)
            {
                return;
            }

            _portalMoveFailures = 0;
            if (_portalApproachAnchorIndex <
                PortalApproachOffsets.Length - 1)
            {
                _portalApproachAnchorIndex++;
                ResetBathyspherePath("BathysphereApproachAnchorRotation");
                AllflameContext.RequestManualSnapshot();
                AllflameProgressWatchdog.MarkProgress(
                    "BathysphereAnchorRotated");
                AllflameLog.Info(
                    "BATHYSPHERE_APPROACH_ANCHOR_ROTATED" +
                    "|Id=" + portal.Id +
                    "|AnchorIndex=" + _portalApproachAnchorIndex +
                    "|AnchorTarget=" + PortalApproachTarget(portal) +
                    "|Action=RefreshPathAndContinue");
                return;
            }

            if (DateTime.UtcNow >= _nextPortalApproachRecoveryUtc)
            {
                RecoverBathysphereApproach("PathFailed");
            }
        }

        private bool RecoverBathysphereApproach(string reason)
        {
            if (_portalApproachRecoveries >=
                MaximumPortalApproachRecoveries)
            {
                AllflameLog.Info(
                    "BATHYSPHERE_APPROACH_RECOVERY_EXHAUSTED" +
                    "|Recoveries=" + _portalApproachRecoveries +
                    "|Max=" + MaximumPortalApproachRecoveries +
                    "|Reason=" + (reason ?? String.Empty) +
                    "|Action=ReleaseChartDeviceAndResumeChartRunner");
                AllflameRunState.ReleaseChartDeviceRequest(
                    "BathysphereApproachRecoveryExhausted");
                ResetBathyspherePath(
                    "BathysphereApproachRecoveryExhausted");
                ResetTransactionState();
                AllflameProgressWatchdog.Clear(Name);
                AllflameContext.RequestManualSnapshot();
                return false;
            }

            _portalApproachRecoveries++;
            _portalMoveFailures = 0;
            _portalApproachAnchorIndex = 0;
            _portalPathBlocked = false;
            _portalConfirmedUtc = DateTime.UtcNow;
            _portalWaitUntilUtc =
                DateTime.UtcNow + PortalAppearanceTimeout;
            _nextPortalInteractUtc = DateTime.MinValue;
            _transactionStartedUtc = DateTime.UtcNow;
            _nextPortalApproachRecoveryUtc =
                DateTime.UtcNow.AddSeconds(2);
            ResetBathyspherePath(
                "BathysphereApproachRecovery");
            AllflameContext.RequestManualSnapshot();
            AllflameProgressWatchdog.SetRetry(
                _portalApproachRecoveries);
            AllflameProgressWatchdog.MarkProgress(
                "BathysphereApproachRecovery");
            AllflameLog.Info(
                "BATHYSPHERE_APPROACH_RECOVERY" +
                "|Reason=" + (reason ?? String.Empty) +
                "|Recovery=" + _portalApproachRecoveries +
                "/" + MaximumPortalApproachRecoveries +
                "|Action=RefreshPathAndReacquire" +
                "|KeepChartTransaction=True");
            return true;
        }

        private static void ResetBathyspherePath(string reason)
        {
            bool pathReloaded = false;
            try
            {
                ExilePather.Reload(true);
                pathReloaded = true;
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "BATHYSPHERE_PATH_RELOAD_FAILED" +
                    "|Reason=" + (reason ?? String.Empty) +
                    "|Type=" + ex.GetType().Name);
            }

            bool moverReset = false;
            try
            {
                AllflameMover mover =
                    PlayerMoverManager.Current as AllflameMover;
                if (mover != null)
                {
                    mover.ReleaseMovementInput();
                    mover.ResetApproachState();
                    moverReset = true;
                }
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "BATHYSPHERE_MOVER_RESET_FAILED" +
                    "|Reason=" + (reason ?? String.Empty) +
                    "|Type=" + ex.GetType().Name);
            }

            int revision =
                AllflameMovementCoordinator.AdvanceNavigation(
                    reason ?? "BathyspherePathReset");
            AllflameLog.Info(
                "BATHYSPHERE_PATH_RESET" +
                "|Reason=" + (reason ?? String.Empty) +
                "|PathReloaded=" + pathReloaded +
                "|MoverReset=" + moverReset +
                "|NavigationRevision=" + revision);
        }

        private async Task<bool> RecoverDescendConfirmation(
            TimeSpan issuedFor,
            bool nativeUiOpen,
            bool stableUiOpen)
        {
            _descendIssued = false;
            _descendIssuedUtc = DateTime.MinValue;
            _descendConfirmationRecoveries++;
            AllflameProgressWatchdog.SetRetry(
                _descendConfirmationRecoveries);

            AllflameLog.Info(
                "CHART_DEVICE_DESCEND_CONFIRM_TIMEOUT" +
                "|Attempt=" + _descendAttempts +
                "|Recovery=" + _descendConfirmationRecoveries +
                "/" + MaximumDescendConfirmationRecoveries +
                "|NativeUiOpen=" + nativeUiOpen +
                "|StableUiOpen=" + stableUiOpen +
                "|ElapsedMs=" + (int)issuedFor.TotalMilliseconds +
                "|Action=SpaceCloseAndReacquire");

            bool spaceSent =
                SendSpaceForChartDeviceRecovery(
                    "DescendConfirmationTimeout");
            bool closeCompleted = false;
            AllflameLog.Info(
                "CHART_DEVICE_RECOVERY_CLOSE_UI_BEGIN" +
                "|Reason=DescendConfirmationTimeout");
            try
            {
                await Coroutines.CloseBlockingWindows();
                closeCompleted = true;
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "CHART_DEVICE_RECOVERY_CLOSE_UI_FAILED" +
                    "|Reason=DescendConfirmationTimeout" +
                    "|Type=" + ex.GetType().Name);
            }

            AllflameContext.RequestManualSnapshot();

            if (_descendConfirmationRecoveries >=
                MaximumDescendConfirmationRecoveries)
            {
                AllflameLog.Info(
                    "CHART_DEVICE_DESCEND_RECOVERY_EXHAUSTED" +
                    "|Attempts=" + _descendAttempts +
                    "|Recoveries=" + _descendConfirmationRecoveries +
                    "|SpaceSent=" + spaceSent +
                    "|CloseCompleted=" + closeCompleted +
                    "|Postcondition=DeferredFreshCycle" +
                    "|Action=ReleaseChartRequest");
                AllflameRunState.ReleaseChartDeviceRequest(
                    "DescendConfirmationRecoveriesExhausted");
                ResetTransactionState();
                AllflameProgressWatchdog.Clear(Name);
                return true;
            }

            _descendConfirmed = false;
            _portalConfirmedUtc = DateTime.MinValue;
            _portalWaitUntilUtc = DateTime.MinValue;
            _nextPortalInteractUtc = DateTime.MinValue;
            _nextActivateUtc = DateTime.UtcNow.AddSeconds(1);
            AllflameProgressWatchdog.MarkProgress(
                "DescendConfirmationRecovery");
            AllflameLog.Info(
                "CHART_DEVICE_DESCEND_RECOVERY_READY" +
                "|Recovery=" + _descendConfirmationRecoveries +
                "/" + MaximumDescendConfirmationRecoveries +
                "|SpaceSent=" + spaceSent +
                "|CloseCompleted=" + closeCompleted +
                "|Postcondition=DeferredFreshCycle" +
                "|Action=ReacquireChartDevice");
            return true;
        }

        private static bool SendSpaceForChartDeviceRecovery(
            string reason)
        {
            bool inputSent = false;
            string mode = "Space";
            if (!IsChartDeviceUiOpen())
            {
                AllflameLog.Info(
                    "CHART_DEVICE_RECOVERY_INPUT" +
                    "|Reason=" + (reason ?? String.Empty) +
                    "|Mode=Skipped" +
                    "|InputSent=False" +
                    "|Postcondition=ChartDeviceUiNotOpen");
                return false;
            }
            try
            {
                if (LokiPoe.ClientWindowHandle == IntPtr.Zero)
                {
                    mode = "SpaceClientUnavailable";
                }
                else
                {
                    DreamPoeBot.Loki.Game.Interop.SetForegroundWindow(
                        LokiPoe.ClientWindowHandle);
                    LokiPoe.Input.SimulateKeyEvent(
                        System.Windows.Forms.Keys.Space,
                        true,
                        false,
                        true);
                    inputSent = true;
                }
            }
            catch (Exception ex)
            {
                mode = "Space" + ex.GetType().Name;
                AllflameLog.Info(
                    "CHART_DEVICE_RECOVERY_SPACE_FAILED" +
                    "|Reason=" + (reason ?? String.Empty) +
                    "|Type=" + ex.GetType().Name);
            }
            finally
            {
                try
                {
                    LokiPoe.ProcessHookManager.ClearAllKeyStates();
                }
                catch (Exception ex)
                {
                    AllflameLog.Info(
                        "CHART_DEVICE_RECOVERY_INPUT_CLEANUP_FAILED" +
                        "|Reason=" + (reason ?? String.Empty) +
                        "|Type=" + ex.GetType().Name);
                }
            }

            AllflameLog.Info(
                "CHART_DEVICE_RECOVERY_INPUT" +
                "|Reason=" + (reason ?? String.Empty) +
                "|Mode=" + mode +
                "|InputSent=" + inputSent);
            return inputSent;
        }

        private static bool IsChartDeviceUiOpen()
        {
            try
            {
                return LokiPoe.InGameState.MapDeviceUi.IsOpened ||
                    NativeDeepwaterChartDeviceUi.IsOpened ||
                    DeepwaterChartDeviceUi.IsStableWindowOpen;
            }
            catch
            {
                return false;
            }
        }

        private async Task RecoverChartDeviceTransaction(
            string reason,
            bool closeBlockingUi)
        {
            _transactionRecoveries++;
            _descendAttempts = 0;
            _descendIssued = false;
            _descendConfirmed = false;
            _descendIssuedUtc = DateTime.MinValue;
            _portalConfirmedUtc = DateTime.MinValue;
            _portalWaitUntilUtc = DateTime.MinValue;
            _nextPortalInteractUtc = DateTime.MinValue;
            _portalUiRecoveries = 0;
            _descendDisabledSinceUtc = DateTime.MinValue;
            _transactionStartedUtc = DateTime.UtcNow;
            _lastTransitionHeartbeatUtc = DateTime.MinValue;
            _nextActivateUtc = DateTime.UtcNow.AddSeconds(1);
            AllflameProgressWatchdog.SetRetry(_transactionRecoveries);
            AllflameProgressWatchdog.MarkProgress(
                "ChartDeviceRecovery:" + reason);

            AllflameLog.Info(
                "CHART_DEVICE_RECOVERY_BEGIN" +
                "|Reason=" + reason +
                "|Recovery=" + _transactionRecoveries +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|LoadedChartId=" + _customChartLocalId +
                "|InventoryCharts=" +
                AllflameContext.InventoryChartCount +
                "|Action=RequestContextRefresh" +
                (closeBlockingUi ? "+CloseUi" : String.Empty));

            AllflameContext.RequestManualSnapshot();
            AllflameLog.Info(
                "CHART_DEVICE_RECOVERY_REFRESH_REQUESTED" +
                "|Reason=" + reason +
                "|Mode=NextTaskCycle" +
                "|Postcondition=DeferredFreshSnapshot");

            bool chartDeviceUiOpen = IsChartDeviceUiOpen();
            bool closeUiAllowed = closeBlockingUi && chartDeviceUiOpen;
            bool spaceSent = false;
            bool closeCompleted = false;
            if (closeBlockingUi && !chartDeviceUiOpen)
            {
                AllflameLog.Info(
                    "CHART_DEVICE_RECOVERY_CLOSE_SKIPPED" +
                    "|Reason=" + reason +
                    "|Postcondition=ChartDeviceUiNotOpen" +
                    "|Action=KeepCurrentUi");
            }
            if (closeUiAllowed)
            {
                spaceSent = SendSpaceForChartDeviceRecovery(reason);
                AllflameLog.Info(
                    "CHART_DEVICE_RECOVERY_CLOSE_UI_BEGIN" +
                    "|Reason=" + reason);
                try
                {
                    await Coroutines.CloseBlockingWindows();
                    closeCompleted = true;
                }
                catch (Exception ex)
                {
                    AllflameLog.Info(
                        "CHART_DEVICE_RECOVERY_CLOSE_UI_FAILED" +
                        "|Reason=" + reason +
                        "|Type=" + ex.GetType().Name);
                }
            }

            AllflameLog.Info(
                "CHART_DEVICE_RECOVERY_READY" +
                "|Reason=" + reason +
                "|Recovery=" + _transactionRecoveries +
                "|SpaceSent=" + spaceSent +
                "|CloseCompleted=" + closeCompleted +
                "|ChartDeviceUiOpen=" + chartDeviceUiOpen +
                "|Postcondition=DeferredFreshCycle" +
                "|NextAction=ReacquireChartDevice");
        }

        private void LogTransitionHeartbeat(TimeSpan transactionElapsed)
        {
            DateTime now = DateTime.UtcNow;
            if (now - _lastTransitionHeartbeatUtc <
                TimeSpan.FromSeconds(2))
            {
                return;
            }

            _lastTransitionHeartbeatUtc = now;
            if (!_descendConfirmed || !_portalPathBlocked)
            {
                AllflameProgressWatchdog.MarkProgress(
                    "ChartDeviceHeartbeat");
            }
            else
            {
                AllflameLog.Throttled(
                    "bathysphere_approach_watchdog",
                    TimeSpan.FromSeconds(2),
                    "BATHYSPHERE_APPROACH_WATCHDOG" +
                    "|PathBlocked=True" +
                    "|Failures=" + _portalMoveFailures +
                    "|AnchorIndex=" + _portalApproachAnchorIndex +
                    "|Recoveries=" + _portalApproachRecoveries +
                    "|Action=BoundedRecovery");
            }
            bool nativeUiOpen = false;
            bool stableUiOpen = false;
            int deviceItems = 0;
            try
            {
                nativeUiOpen = NativeDeepwaterChartDeviceUi.IsOpened;
                stableUiOpen = DeepwaterChartDeviceUi.IsStableWindowOpen;
                if (nativeUiOpen)
                {
                    deviceItems = NativeDeepwaterChartDeviceUi.DeviceItems.Count;
                }
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "CHART_DEVICE_HEARTBEAT_READ_FAILED" +
                    "|Type=" + ex.GetType().Name);
            }

            AllflameLog.Info(
                "CHART_DEVICE_TRANSITION_HEARTBEAT" +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|Phase=" + AllflameContext.Phase +
                "|UiOpen=" + (nativeUiOpen || stableUiOpen) +
                "|NativeUiOpen=" + nativeUiOpen +
                "|StableUiOpen=" + stableUiOpen +
                "|DeviceItems=" + deviceItems +
                "|InventoryCharts=" +
                AllflameContext.InventoryChartCount +
                "|DescendIssued=" + _descendIssued +
                "|DescendConfirmed=" + _descendConfirmed +
                "|DescendAttempts=" + _descendAttempts +
                "|Recoveries=" + _transactionRecoveries +
                "|ElapsedMs=" +
                (int)transactionElapsed.TotalMilliseconds +
                "|NextAction=" +
                (_descendIssued
                    ? "AwaitDescendConfirmation"
                    : (_descendConfirmed
                        ? "AcquireBathysphere"
                        : "ResolveChartDevice")));
        }

        private void LogChartDeviceLoadConfirmed(
            string ui,
            int deviceCharts,
            int inventoryCharts)
        {
            if (_loadConfirmationLogged)
            {
                return;
            }
            _loadConfirmationLogged = true;
            AllflameProgressWatchdog.MarkProgress(
                "ChartLoadConfirmed");
            string source =
                AllflameSettings.Instance.EnableChartStorageWithdrawal &&
                AllflameRunState.ChartStorageProbeCompleted
                    ? "ChartStorage"
                    : "InventoryOrVoyageStash";
            AllflameLog.Info(
                "CHART_DEVICE_LOAD_CONFIRMED" +
                "|Source=" + source +
                "|Ui=" + ui +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|LocalId=" + _customChartLocalId +
                "|InventoryCharts=" + inventoryCharts +
                "|DeviceCharts=" + deviceCharts +
                "|ChartRequested=" +
                AllflameRunState.ChartRequested +
                "|NextAction=Descend");
        }

        private static async Task<bool> CtrlClickInventoryChart(
            InventoryControlWrapper inventoryControl,
            Item chart)
        {
            if (inventoryControl == null || chart == null)
            {
                return false;
            }

            try
            {
                var slotUi = inventoryControl.InventorySlotUiElement;
                if (slotUi == null)
                {
                    AllflameLog.Info(
                        "CHART_DEVICE_CTRL_CLICK_FAILED|Reason=InventorySlotUiMissing");
                    return false;
                }

                Element chartElement = null;
                int elementKey = 0;
                try
                {
                    var itemElements = slotUi.DictionaryIdElements;
                    if (itemElements != null)
                    {
                        if (itemElements.TryGetValue(
                            chart.LocalId,
                            out chartElement))
                        {
                            elementKey = chart.LocalId;
                        }
                        else if (itemElements.TryGetValue(
                            chart.Id,
                            out chartElement))
                        {
                            elementKey = chart.Id;
                        }
                        else
                        {
                            foreach (var pair in itemElements)
                            {
                                Element candidate = pair.Value;
                                if (candidate == null ||
                                    !candidate.IsValid)
                                {
                                    continue;
                                }

                                Vector2i candidateSlot =
                                    slotUi.ElementLocationTopLeft(
                                        candidate);
                                if (candidateSlot.X ==
                                        chart.LocationTopLeft.X &&
                                    candidateSlot.Y ==
                                        chart.LocationTopLeft.Y)
                                {
                                    chartElement = candidate;
                                    elementKey = pair.Key;
                                    break;
                                }
                            }
                        }
                    }
                }
                catch
                {
                    chartElement = null;
                }

                Vector2i clickLocation =
                    chartElement != null &&
                    chartElement.IsValid &&
                    chartElement.IsVisible
                        ? chartElement.CenterClickLocation()
                        : slotUi.SlotClickLocation(
                            new Vector2i(
                                chart.LocationTopLeft.X + 1,
                                chart.LocationTopLeft.Y + 1));

                bool controlDown = false;
                try
                {
                    LokiPoe.ProcessHookManager.ClearAllKeyStates();
                    DreamPoeBot.BotFramework.MouseManager.SetMousePosition(
                        clickLocation,
                        true);
                    await LokiCoroutine.Sleep(20);
                    LokiPoe.ProcessHookManager.SetKeyState(
                        System.Windows.Forms.Keys.ControlKey,
                        short.MinValue,
                        System.Windows.Forms.Keys.None);
                    controlDown = true;
                    await LokiCoroutine.Sleep(30);
                    DreamPoeBot.BotFramework.MouseManager.ClickLMB(0, 0);
                    await LokiCoroutine.Sleep(120);
                }
                finally
                {
                    if (controlDown)
                    {
                        LokiPoe.ProcessHookManager.SetKeyState(
                            System.Windows.Forms.Keys.ControlKey,
                            (short)0,
                            System.Windows.Forms.Keys.None);
                    }
                }

                AllflameLog.Info(
                    "CHART_DEVICE_CTRL_CLICK|Id=" + chart.Id +
                    "|LocalId=" + chart.LocalId +
                    "|Inventory=" + chart.LocationTopLeft +
                    "|Screen=" + clickLocation +
                    "|Element=" + (chartElement != null) +
                    "|ElementKey=" + elementKey +
                    "|SlotOrigin=" + slotUi.LocationTopLeft +
                    "|SlotSize=" + slotUi.Size);
                return true;
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "CHART_DEVICE_CTRL_CLICK_FAILED|Id=" +
                    chart.Id + "|LocalId=" + chart.LocalId +
                    "|Error=" + ex.Message);
                return false;
            }
        }
    }

    internal sealed class LayoutFrontierNode
    {
        public Vector2i Position;
        public int Direction;
        public int Ring;
        public int State;
    }

    internal sealed class TopologyRoomRouteNode
    {
        public Vector2i Position;
        public string Name;
        public int State;
        public int Priority;
    }

    /// <summary>
    /// Uses DPB 0.3.29.15 AreaGraphs as an optional discovery hint. It never
    /// owns chest/loot interaction and automatically falls back to the
    /// existing frontier planners when the API is empty, malformed or a room
    /// is not reachable.
    /// </summary>
    internal sealed class TopologyRoomRoutePlanner
    {
        private readonly List<TopologyRoomRouteNode> _rooms =
            new List<TopologyRoomRouteNode>();
        private uint _areaHash;
        private DateTime _nextLoadUtc = DateTime.MinValue;
        private bool _loaded;

        public void Reset(uint areaHash)
        {
            _areaHash = areaHash;
            _nextLoadUtc = DateTime.MinValue;
            _loaded = false;
            _rooms.Clear();
        }

        public bool TrySelect(
            Vector2i player,
            out int roomIndex,
            out Vector2i target,
            out string roomName)
        {
            roomIndex = -1;
            target = player;
            roomName = String.Empty;
            if (!AllflameSettings.Instance.EnableTopologyRoomRouting ||
                !EnsureLoaded(player))
            {
                return false;
            }

            List<KeyValuePair<int, TopologyRoomRouteNode>> candidates =
                _rooms
                    .Select((room, index) =>
                        new KeyValuePair<int, TopologyRoomRouteNode>(
                            index,
                            room))
                    .Where(pair =>
                        pair.Value.State == 0 &&
                        pair.Value.Position.DistanceF(player) >= 55f &&
                        !AllflameRunState.IsNearPlacedLantern(
                            pair.Value.Position,
                            42f) &&
                        !AllflameChestRoute.IsInsideCompletedArea(
                            pair.Value.Position,
                            110))
                    .OrderByDescending(pair => pair.Value.Priority)
                    .ThenBy(pair =>
                        pair.Value.Position.DistanceF(player))
                    // Test a small queue per cycle so topology discovery does
                    // not monopolize the movement cycle with path queries.
                    .Take(4)
                    .ToList();

            foreach (KeyValuePair<int, TopologyRoomRouteNode> pair
                     in candidates)
            {
                bool pathExists;
                try
                {
                    pathExists = VoyageRunnerMetrics.PathExistsBetween(
                        player,
                        pair.Value.Position,
                        false);
                }
                catch
                {
                    pathExists = false;
                }

                if (!pathExists)
                {
                    pair.Value.State = 3;
                    AllflameLog.Info(
                        "TOPOLOGY_ROOM_REJECTED" +
                        "|Index=" + pair.Key +
                        "|Name=" + SafeName(pair.Value.Name) +
                        "|Target=" + pair.Value.Position +
                        "|Reason=NoPath");
                    continue;
                }

                pair.Value.State = 1;
                roomIndex = pair.Key;
                target = pair.Value.Position;
                roomName = pair.Value.Name;
                return true;
            }

            return false;
        }

        public void MarkReached(int roomIndex)
        {
            if (roomIndex >= 0 && roomIndex < _rooms.Count)
            {
                _rooms[roomIndex].State = 2;
            }
        }

        public void MarkBlocked(int roomIndex, string reason)
        {
            if (roomIndex < 0 || roomIndex >= _rooms.Count)
            {
                return;
            }

            TopologyRoomRouteNode room = _rooms[roomIndex];
            room.State = 3;
            AllflameLog.Info(
                "TOPOLOGY_ROOM_BLOCKED" +
                "|Index=" + roomIndex +
                "|Name=" + SafeName(room.Name) +
                "|Target=" + room.Position +
                "|Reason=" + SafeName(reason) +
                "|Action=FallBackToFrontier");
        }

        public void Release(int roomIndex)
        {
            if (roomIndex >= 0 &&
                roomIndex < _rooms.Count &&
                _rooms[roomIndex].State == 1)
            {
                _rooms[roomIndex].State = 0;
            }
        }

        private bool EnsureLoaded(Vector2i player)
        {
            if (_loaded)
            {
                return _rooms.Count > 0;
            }
            if (_areaHash == 0 ||
                DateTime.UtcNow < _nextLoadUtc)
            {
                return false;
            }

            _nextLoadUtc = DateTime.UtcNow.AddSeconds(2);
            try
            {
                var topologies = LokiPoe.AreaGraphs.Topologies;
                if (topologies == null || topologies.Count == 0)
                {
                    AllflameLog.Throttled(
                        "topology_rooms_empty",
                        TimeSpan.FromSeconds(10),
                        "TOPOLOGY_ROOM_SCAN" +
                        "|AreaHash=" + _areaHash +
                        "|Result=NoTopologies" +
                        "|Action=UseExistingFrontier");
                    return false;
                }

                var discovered =
                    new List<TopologyRoomRouteNode>();
                int topologyCount = 0;
                int rawRoomCount = 0;
                foreach (var topology in topologies)
                {
                    if (topology == null)
                    {
                        continue;
                    }
                    topologyCount++;
                    var rooms = topology.TopologieRooms;
                    if (rooms == null)
                    {
                        continue;
                    }

                    foreach (var room in rooms)
                    {
                        rawRoomCount++;
                        if (room == null ||
                            String.IsNullOrWhiteSpace(room.Name))
                        {
                            continue;
                        }

                        Vector2i min = room.MinCoord;
                        Vector2i max = room.MaxCoord;
                        long width = (long)max.X - min.X;
                        long height = (long)max.Y - min.Y;
                        if (width < 0 || height < 0 ||
                            width > 2000 || height > 2000)
                        {
                            continue;
                        }

                        Vector2i center = new Vector2i(
                            min.X + (int)(width / 2),
                            min.Y + (int)(height / 2));
                        float distance = center.DistanceF(player);
                        if (distance > 6000f ||
                            discovered.Any(existing =>
                                existing.Position.DistanceF(center) <= 24f))
                        {
                            continue;
                        }

                        discovered.Add(
                            new TopologyRoomRouteNode
                            {
                                Position = center,
                                Name = room.Name,
                                State = distance < 55f ? 2 : 0,
                                Priority = GetRoomPriority(room.Name)
                            });
                    }
                }

                if (rawRoomCount == 0)
                {
                    AllflameLog.Throttled(
                        "topology_rooms_not_ready",
                        TimeSpan.FromSeconds(10),
                        "TOPOLOGY_ROOM_SCAN" +
                        "|AreaHash=" + _areaHash +
                        "|Topologies=" + topologyCount +
                        "|RawRooms=0" +
                        "|Result=RoomsNotReady" +
                        "|Action=RetryAndUseExistingFrontier");
                    return false;
                }

                _rooms.AddRange(
                    discovered
                        .OrderByDescending(room => room.Priority)
                        .ThenBy(room =>
                            room.Position.DistanceF(player))
                        .Take(64));
                _loaded = true;
                AllflameLog.Info(
                    "TOPOLOGY_ROOM_SCAN" +
                    "|AreaHash=" + _areaHash +
                    "|Topologies=" + topologyCount +
                    "|RawRooms=" + rawRoomCount +
                    "|AcceptedRooms=" + _rooms.Count +
                    "|NamedRooms=" +
                    String.Join(
                        ",",
                        _rooms.Take(8)
                            .Select(room => SafeName(room.Name))) +
                    "|Action=" +
                    (_rooms.Count > 0
                        ? "PrioritizeBeforeFrontier"
                        : "UseExistingFrontier"));
                return _rooms.Count > 0;
            }
            catch (Exception ex)
            {
                _nextLoadUtc = DateTime.UtcNow.AddSeconds(10);
                AllflameLog.Throttled(
                    "topology_rooms_failed",
                    TimeSpan.FromSeconds(10),
                    "TOPOLOGY_ROOM_SCAN_FAILED" +
                    "|AreaHash=" + _areaHash +
                    "|Error=" + SafeName(ex.Message) +
                    "|Action=UseExistingFrontier");
                return false;
            }
        }

        private static int GetRoomPriority(string name)
        {
            string value = name ?? String.Empty;
            if (value.IndexOf("Chest", StringComparison.OrdinalIgnoreCase) >= 0 ||
                value.IndexOf("Treasure", StringComparison.OrdinalIgnoreCase) >= 0 ||
                value.IndexOf("Reward", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return 3;
            }
            if (value.IndexOf("Deepwater", StringComparison.OrdinalIgnoreCase) >= 0 ||
                value.IndexOf("Anchor", StringComparison.OrdinalIgnoreCase) >= 0 ||
                value.IndexOf("Capsule", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return 2;
            }
            return 1;
        }

        private static string SafeName(string value)
        {
            return String.IsNullOrWhiteSpace(value)
                ? "Unknown"
                : value.Replace("|", "/").Replace(",", ";");
        }
    }

    /// <summary>
    /// Samples the immutable DPB terrain grid into coarse Chart targets. The
    /// existing layout planner remains the fallback when coordinates or
    /// walkability data are not usable at runtime.
    /// </summary>
    internal sealed class ChartTerrainFrontierPlanner
    {
        private readonly List<Vector2i> _targets =
            new List<Vector2i>();
        private uint _areaHash;
        private Vector2i _center;
        private int _activeIndex = -1;

        public void Reset(uint areaHash)
        {
            _areaHash = areaHash;
            _center = default(Vector2i);
            _activeIndex = -1;
            _targets.Clear();
        }

        public bool IsReady(uint areaHash)
        {
            return _areaHash == areaHash && _targets.Count > 0;
        }

        public bool IsBuilt(uint areaHash)
        {
            return _areaHash == areaHash;
        }

        public bool Build(
            AreaMapSnapshot snapshot,
            Vector2i center,
            int spacing)
        {
            _targets.Clear();
            _activeIndex = -1;
            _center = center;
            if (snapshot == null ||
                snapshot.AreaHash == 0 ||
                snapshot.Walkable == null ||
                snapshot.Rows <= 0 ||
                snapshot.Cols <= 0)
            {
                return false;
            }

            _areaHash = snapshot.AreaHash;
            int step = Math.Max(60, Math.Min(140, spacing));
            int maxRadius = Math.Max(900, step * 10);
            int minDistance = Math.Max(80, step);
            for (int row = 0; row < snapshot.Rows; row += step)
            {
                for (int col = 0; col < snapshot.Cols; col += step)
                {
                    int index = row * snapshot.Cols + col;
                    if (index < 0 || index >= snapshot.Walkable.Length ||
                        !snapshot.Walkable[index])
                    {
                        continue;
                    }

                    Vector2i candidate = new Vector2i(col, row);
                    float distance = candidate.DistanceF(center);
                    if (distance < minDistance || distance > maxRadius)
                    {
                        continue;
                    }

                    if (_targets.Any(existing =>
                            existing.DistanceF(candidate) < step * 0.75f))
                    {
                        continue;
                    }

                    _targets.Add(candidate);
                }
            }

            AllflameLog.Info(
                "CHART_TERRAIN_FRONTIER_BUILT" +
                "|AreaHash=" + snapshot.AreaHash +
                "|Center=" + center +
                "|Rows=" + snapshot.Rows +
                "|Cols=" + snapshot.Cols +
                "|Targets=" + _targets.Count +
                "|Spacing=" + step +
                "|Action=" +
                (_targets.Count > 0
                    ? "UseTerrainTargets"
                    : "UseExistingFrontier"));
            return _targets.Count > 0;
        }

        public bool TrySelect(
            Vector2i player,
            out int targetIndex,
            out Vector2i target)
        {
            targetIndex = -1;
            target = player;
            double bestScore = Double.MinValue;
            for (int i = 0; i < _targets.Count; i++)
            {
                Vector2i candidate = _targets[i];
                if (candidate.Equals(default(Vector2i)))
                {
                    continue;
                }

                bool pathExists;
                try
                {
                    pathExists = VoyageRunnerMetrics.PathExistsBetween(
                        player,
                        candidate,
                        false);
                }
                catch
                {
                    pathExists = true;
                }
                if (!pathExists)
                {
                    AllflameLog.Throttled(
                        "chart_terrain_no_path",
                        TimeSpan.FromSeconds(2),
                        "CHART_TERRAIN_PATH_REJECTED" +
                        "|Player=" + player +
                        "|Target=" + candidate +
                        "|Action=DiscardTarget");
                    _targets.RemoveAt(i);
                    i--;
                    continue;
                }

                double distanceFromCenter = candidate.DistanceF(_center);
                double outwardGain =
                    distanceFromCenter - player.DistanceF(_center);
                double score =
                    outwardGain * 2.0 -
                    candidate.DistanceF(player) * 0.15;
                if (score <= bestScore)
                {
                    continue;
                }

                bestScore = score;
                targetIndex = i;
                target = candidate;
            }

            if (targetIndex < 0)
            {
                return false;
            }

            _activeIndex = targetIndex;
            return true;
        }

        public void MarkReached(int targetIndex)
        {
            Remove(targetIndex);
        }

        public void MarkBlocked(int targetIndex)
        {
            Remove(targetIndex);
        }

        public void Release(int targetIndex)
        {
            if (targetIndex == _activeIndex)
            {
                _activeIndex = -1;
            }
        }

        private void Remove(int targetIndex)
        {
            if (targetIndex < 0 || targetIndex >= _targets.Count)
            {
                return;
            }

            _targets.RemoveAt(targetIndex);
            _activeIndex = -1;
        }
    }

    internal sealed class HybridLayoutFrontierPlanner
    {
        private readonly List<LayoutFrontierNode> _nodes =
            new List<LayoutFrontierNode>();
        private Vector2i _center;
        private uint _areaHash;
        private int _spacing;

        public void Reset(uint areaHash, Vector2i center, int spacing)
        {
            _areaHash = areaHash;
            _center = center;
            _spacing = Math.Max(70, Math.Min(140, spacing));
            _nodes.Clear();

            // Sample progressively wider frontiers from the immutable spawn.
            // Three lanes per cardinal branch make the plan tolerant of walls
            // without performing an expensive full-terrain scan in one tick.
            for (int direction = 0; direction < 4; direction++)
            {
                for (int ring = 1; ring <= 6; ring++)
                {
                    for (int lane = -1; lane <= 1; lane++)
                    {
                        int distance = ring * _spacing;
                        int lateral = lane * (_spacing / 3);
                        Vector2i position;
                        switch (direction)
                        {
                            case 0:
                                position = new Vector2i(
                                    center.X + distance,
                                    center.Y + lateral);
                                break;
                            case 1:
                                position = new Vector2i(
                                    center.X + lateral,
                                    center.Y - distance);
                                break;
                            case 2:
                                position = new Vector2i(
                                    center.X - distance,
                                    center.Y + lateral);
                                break;
                            default:
                                position = new Vector2i(
                                    center.X + lateral,
                                    center.Y + distance);
                                break;
                        }
                        _nodes.Add(new LayoutFrontierNode
                        {
                            Position = position,
                            Direction = direction,
                            Ring = ring,
                            State = 0
                        });
                    }
                }
            }

            AllflameLog.Info(
                "LAYOUT_FRONTIER_PLAN_BUILT|AreaHash=" + areaHash +
                "|Center=" + center +
                "|Nodes=" + _nodes.Count +
                "|Branches=4|LanesPerBranch=3" +
                "|Spacing=" + _spacing +
                "|ChestDiscovery=Dynamic");
        }

        public bool IsReady(uint areaHash)
        {
            return _areaHash == areaHash && _nodes.Count > 0;
        }

        public bool TrySelect(
            Vector2i player,
            int preferredDirection,
            bool allowCompletedAreaEscape,
            out int nodeIndex,
            out int direction,
            out Vector2i target)
        {
            nodeIndex = -1;
            direction = -1;
            target = player;
            double currentRadius = player.Distance(_center);
            double wantedRadius =
                Math.Max(_spacing, currentRadius + _spacing);
            double bestScore = Double.MinValue;

            for (int i = 0; i < _nodes.Count; i++)
            {
                LayoutFrontierNode node = _nodes[i];
                if (node.State != 0 ||
                    AllflameRunState.IsNearPlacedLantern(
                        node.Position,
                        42f) ||
                    (!allowCompletedAreaEscape &&
                     AllflameChestRoute.IsInsideCompletedArea(
                         node.Position,
                         120)))
                {
                    continue;
                }

                double radius = node.Position.Distance(_center);
                double travel = node.Position.Distance(player);
                double progressionPenalty =
                    Math.Abs(radius - wantedRadius);
                double branchBonus =
                    node.Direction == preferredDirection ? 220 : 0;
                double outwardBonus =
                    radius >= currentRadius - 20 ? 100 : -250;
                double score =
                    branchBonus +
                    outwardBonus -
                    progressionPenalty -
                    travel * 0.12;
                if (score <= bestScore)
                {
                    continue;
                }

                bestScore = score;
                nodeIndex = i;
                direction = node.Direction;
                target = node.Position;
            }

            if (nodeIndex < 0)
            {
                return false;
            }

            _nodes[nodeIndex].State = 1;
            return true;
        }

        public void MarkReached(int nodeIndex)
        {
            if (nodeIndex >= 0 && nodeIndex < _nodes.Count)
            {
                _nodes[nodeIndex].State = 2;
            }
        }

        public void MarkBlocked(int nodeIndex)
        {
            if (nodeIndex >= 0 && nodeIndex < _nodes.Count)
            {
                _nodes[nodeIndex].State = 3;
            }
        }

        public void MarkBlockedRegion(Vector2i position, float radius)
        {
            float safeRadius = Math.Max(35f, radius);
            for (int i = 0; i < _nodes.Count; i++)
            {
                LayoutFrontierNode node = _nodes[i];
                if ((node.State == 0 || node.State == 1) &&
                    node.Position.DistanceF(position) <= safeRadius)
                {
                    node.State = 3;
                }
            }
        }

        public void Release(int nodeIndex)
        {
            if (nodeIndex >= 0 &&
                nodeIndex < _nodes.Count &&
                _nodes[nodeIndex].State == 1)
            {
                _nodes[nodeIndex].State = 0;
            }
        }

        public bool HasPending
        {
            get { return _nodes.Any(node => node.State == 0); }
        }
    }

    internal sealed class VoyageBlockedFrontier
    {
        public Vector2i Position;
        public float Radius;
        public DateTime ExpiresUtc;
    }

    /// <summary>
    /// A forward-growing Voyage planner. Unlike the Chart four-branch plan,
    /// it continuously samples a short ring around the player's current
    /// position and scores candidates by novelty, outward gain and heading
    /// continuity. This is intentionally Voyage-only because its map is much
    /// larger and revisiting the original spawn wastes most of the run.
    /// </summary>
    internal sealed class VoyageRollingFrontierPlanner
    {
        private readonly List<Vector2i> _visited =
            new List<Vector2i>();
        private readonly List<VoyageBlockedFrontier> _blocked =
            new List<VoyageBlockedFrontier>();
        private readonly Dictionary<int, KeyValuePair<Vector2i, int>> _active =
            new Dictionary<int, KeyValuePair<Vector2i, int>>();
        private uint _areaHash;
        private Vector2i _spawn;
        private int _lookAhead;
        private int _nextId;
        private int _heading = -1;

        public void Reset(uint areaHash, Vector2i spawn, int spacing)
        {
            _areaHash = areaHash;
            _spawn = spawn;
            // 130 is a useful compromise for the requested 120-150 range:
            // far enough to reveal new terrain, short enough to detect a
            // collision and redirect without a long detour.
            _lookAhead = Math.Max(120, Math.Min(150, spacing));
            _nextId = 0;
            _heading = -1;
            _visited.Clear();
            _blocked.Clear();
            _active.Clear();
            Observe(spawn);
            AllflameLog.Info(
                "VOYAGE_ROLLING_FRONTIER_RESET" +
                "|AreaHash=" + areaHash +
                "|Spawn=" + spawn +
                "|LookAhead=" + _lookAhead +
                "|Directions=8" +
                "|StationaryFailsafeSeconds=1");
        }

        public void Observe(Vector2i position)
        {
            if (_visited.Count == 0 ||
                !_visited.Any(point =>
                    point.DistanceF(position) <= 48f))
            {
                _visited.Add(position);
                if (_visited.Count > 1200)
                {
                    _visited.RemoveRange(0, 200);
                }
            }
        }

        public int SteerToward(
            Vector2i player,
            Vector2i target)
        {
            double angle = Math.Atan2(
                target.Y - player.Y,
                target.X - player.X);
            if (angle < 0)
            {
                angle += Math.PI * 2.0;
            }
            _heading =
                ((int)Math.Round(angle / (Math.PI / 4.0))) % 8;
            return _heading;
        }

        public bool TrySelect(
            Vector2i player,
            int preferredDirection,
            bool allowCompletedAreaEscape,
            out int nodeIndex,
            out int direction,
            out Vector2i target)
        {
            nodeIndex = -1;
            direction = -1;
            target = player;
            DateTime now = DateTime.UtcNow;
            _blocked.RemoveAll(entry => entry.ExpiresUtc <= now);
            Observe(player);

            double bestScore = Double.MinValue;
            bool bestRaycastClipped = false;
            Vector2i bestRaycastHit = player;
            string bestSideClearance = "BothClear";
            int bestEdgePenalty = 0;
            for (int candidateDirection = 0;
                 candidateDirection < 8;
                 candidateDirection++)
            {
                double angle =
                    candidateDirection * Math.PI / 4.0;
                Vector2i candidate = new Vector2i(
                    player.X +
                    (int)Math.Round(Math.Cos(angle) * _lookAhead),
                    player.Y +
                    (int)Math.Round(Math.Sin(angle) * _lookAhead));
                Vector2i originalCandidate = candidate;
                Vector2i raycastHit;
                bool raycastClipped;
                if (!TryResolveRaycastTarget(
                        player,
                        originalCandidate,
                        out candidate,
                        out raycastHit,
                        out raycastClipped))
                {
                    continue;
                }

                if (_blocked.Any(entry =>
                        entry.Position.DistanceF(candidate) <=
                            Math.Max(90f, entry.Radius)) ||
                    AllflameRunState.IsNearPlacedLantern(
                        candidate,
                        42f))
                {
                    continue;
                }

                float nearestVisited =
                    _visited.Min(point =>
                        point.DistanceF(candidate));
                double currentRadius =
                    player.Distance(_spawn);
                double candidateRadius =
                    candidate.Distance(_spawn);
                double outwardGain =
                    candidateRadius - currentRadius;
                int referenceDirection =
                    _heading >= 0
                        ? _heading
                        : preferredDirection;
                int turn =
                    Math.Abs(candidateDirection - referenceDirection);
                turn = Math.Min(turn, 8 - turn);

                // Strongly discourage crossing the recent trail. A candidate
                // remains possible only as a last resort when terrain leaves
                // no genuinely new direction.
                double revisitPenalty =
                    nearestVisited < 75f
                        ? 900.0
                        : nearestVisited < 105f
                            ? 260.0
                            : 0.0;
                double headingBonus =
                    turn == 0
                        ? 230.0
                        : turn == 1
                            ? 120.0
                            : turn == 2
                            ? 20.0
                            : -180.0;
                string sideClearance;
                int edgePenalty =
                    MeasureSideEdgePenalty(
                        player,
                        candidate,
                        out sideClearance);
                double score =
                    Math.Min(220f, nearestVisited) * 2.4 +
                    outwardGain * 1.25 +
                    headingBonus -
                    revisitPenalty -
                    (raycastClipped ? 90.0 : 0.0) -
                    edgePenalty;

                if (score <= bestScore)
                {
                    continue;
                }

                bestScore = score;
                direction = candidateDirection;
                target = candidate;
                bestRaycastClipped = raycastClipped;
                bestRaycastHit = raycastHit;
                bestSideClearance = sideClearance;
                bestEdgePenalty = edgePenalty;
            }

            if (direction < 0)
            {
                return false;
            }

            nodeIndex = ++_nextId;
            _active[nodeIndex] =
                new KeyValuePair<Vector2i, int>(
                    target,
                    direction);
            AllflameLog.Info(
                "VOYAGE_ROLLING_FRONTIER_SELECT" +
                "|From=" + player +
                "|To=" + target +
                "|Direction=" + direction +
                "|Heading=" + _heading +
                "|VisitedSamples=" + _visited.Count +
                "|BlockedRegions=" + _blocked.Count +
                "|Raycast=" +
                (bestRaycastClipped ? "Clipped" : "Clear") +
                (bestRaycastClipped
                    ? "|RaycastHit=" + bestRaycastHit
                    : String.Empty) +
                "|SideClearance=" + bestSideClearance +
                "|EdgePenalty=" + bestEdgePenalty +
                "|Score=" + bestScore.ToString("0.0"));
            return true;
        }

        public bool TrySelectLoopEscape(
            Vector2i player,
            Vector2i loopCenter,
            Vector2i escapeToward,
            out int nodeIndex,
            out int direction,
            out Vector2i target)
        {
            nodeIndex = -1;
            direction = -1;
            target = player;
            double bestScore = Double.MinValue;
            bool bestClipped = false;
            Vector2i bestHit = player;
            int escapeDistance = Math.Max(220, _lookAhead * 2);

            for (int candidateDirection = 0;
                 candidateDirection < 8;
                 candidateDirection++)
            {
                double angle =
                    candidateDirection * Math.PI / 4.0;
                Vector2i requested = new Vector2i(
                    player.X +
                    (int)Math.Round(
                        Math.Cos(angle) * escapeDistance),
                    player.Y +
                    (int)Math.Round(
                        Math.Sin(angle) * escapeDistance));
                Vector2i candidate;
                Vector2i raycastHit;
                bool clipped;
                if (!TryResolveRaycastTarget(
                        player,
                        requested,
                        out candidate,
                        out raycastHit,
                        out clipped) ||
                    player.DistanceF(candidate) < 80f)
                {
                    continue;
                }

                double awayFromLoop =
                    candidate.Distance(loopCenter);
                double towardRecoveryAnchor =
                    candidate.Distance(escapeToward);
                double score =
                    awayFromLoop * 3.0 -
                    towardRecoveryAnchor * 1.35 -
                    (clipped ? 120.0 : 0.0);
                if (score <= bestScore)
                {
                    continue;
                }

                bestScore = score;
                direction = candidateDirection;
                target = candidate;
                bestClipped = clipped;
                bestHit = raycastHit;
            }

            if (direction < 0)
            {
                return false;
            }

            nodeIndex = ++_nextId;
            _active[nodeIndex] =
                new KeyValuePair<Vector2i, int>(
                    target,
                    direction);
            AllflameLog.Info(
                "VOYAGE_SPATIAL_LOOP_ESCAPE_SELECT" +
                "|From=" + player +
                "|LoopCenter=" + loopCenter +
                "|Toward=" + escapeToward +
                "|Target=" + target +
                "|Direction=" + direction +
                "|Raycast=" +
                (bestClipped ? "Clipped" : "Clear") +
                (bestClipped
                    ? "|RaycastHit=" + bestHit
                    : String.Empty) +
                "|Score=" + bestScore.ToString("0.0"));
            return true;
        }

        private static int MeasureSideEdgePenalty(
            Vector2i start,
            Vector2i forwardTarget,
            out string clearance)
        {
            clearance = "BothClear";
            try
            {
                double dx = forwardTarget.X - start.X;
                double dy = forwardTarget.Y - start.Y;
                double length = Math.Sqrt(dx * dx + dy * dy);
                if (length < 1.0)
                {
                    return 0;
                }

                const int sideProbeDistance = 72;
                double sideX = -dy / length;
                double sideY = dx / length;
                Vector2i leftTarget = new Vector2i(
                    start.X +
                    (int)Math.Round(sideX * sideProbeDistance),
                    start.Y +
                    (int)Math.Round(sideY * sideProbeDistance));
                Vector2i rightTarget = new Vector2i(
                    start.X -
                    (int)Math.Round(sideX * sideProbeDistance),
                    start.Y -
                    (int)Math.Round(sideY * sideProbeDistance));
                Vector2i leftHit;
                Vector2i rightHit;
                bool leftBlocked =
                    IsCloseRaycastBlock(
                        start,
                        leftTarget,
                        out leftHit);
                bool rightBlocked =
                    IsCloseRaycastBlock(
                        start,
                        rightTarget,
                        out rightHit);

                if (!leftBlocked && !rightBlocked)
                {
                    return 0;
                }
                if (leftBlocked && rightBlocked)
                {
                    clearance = "BothSidesBlocked";
                    return 110;
                }

                clearance =
                    leftBlocked
                        ? "LeftBlocked"
                        : "RightBlocked";
                // Must outweigh the 230-point heading-continuity bonus.
                return 360;
            }
            catch
            {
                clearance = "Unknown";
                return 0;
            }
        }

        private static bool IsCloseRaycastBlock(
            Vector2i start,
            Vector2i target,
            out Vector2i hitPoint)
        {
            hitPoint = target;
            VoyageRunnerMetrics.RecordRaycastQuery();
            if (ExilePather.Raycast(
                    start,
                    target,
                    out hitPoint,
                    false,
                    false))
            {
                return false;
            }

            float hitDistance = start.DistanceF(hitPoint);
            return hitDistance >= 1f &&
                   hitDistance <= 68f;
        }

        public static bool TryResolveRaycastTarget(
            Vector2i start,
            Vector2i requested,
            out Vector2i resolved,
            out Vector2i hitPoint,
            out bool clipped)
        {
            resolved = requested;
            hitPoint = requested;
            clipped = false;
            try
            {
                VoyageRunnerMetrics.RecordRaycastQuery();
                if (ExilePather.Raycast(
                        start,
                        requested,
                        out hitPoint,
                        false,
                        false))
                {
                    return true;
                }

                float requestedDistance =
                    start.DistanceF(requested);
                float clearDistance =
                    start.DistanceF(hitPoint);
                if (clearDistance < 55f ||
                    clearDistance >
                    requestedDistance + 8f)
                {
                    // A straight ray can hit a nearby wall while the navmesh
                    // still has a valid curved route around it. Preserve that
                    // candidate only when DPB confirms such a route exists.
                    bool curvedPathExists =
                        VoyageRunnerMetrics.PathExistsBetween(
                            start,
                            requested,
                            false);
                    if (curvedPathExists)
                    {
                        resolved = requested;
                        hitPoint = requested;
                        clipped = false;
                    }
                    return curvedPathExists;
                }

                // Stop before the first blocked walk-map cell. The next
                // frontier selection will then turn around the obstacle.
                float usableDistance =
                    Math.Max(24f, clearDistance - 28f);
                double ratio =
                    usableDistance /
                    Math.Max(1f, requestedDistance);
                resolved = new Vector2i(
                    start.X +
                    (int)Math.Round(
                        (requested.X - start.X) * ratio),
                    start.Y +
                    (int)Math.Round(
                        (requested.Y - start.Y) * ratio));
                clipped = true;
                return start.DistanceF(resolved) >= 24f;
            }
            catch (Exception ex)
            {
                AllflameLog.Throttled(
                    "voyage_raycast_failed",
                    TimeSpan.FromSeconds(3),
                    "VOYAGE_RAYCAST_FAILED|From=" + start +
                    "|To=" + requested +
                    "|Error=" + ex.GetType().Name +
                    ":" + ex.Message +
                    "|Fallback=Pathfinder");
                resolved = requested;
                hitPoint = requested;
                clipped = false;
                return true;
            }
        }

        public void MarkReached(int nodeIndex)
        {
            KeyValuePair<Vector2i, int> entry;
            if (!_active.TryGetValue(nodeIndex, out entry))
            {
                return;
            }
            Observe(entry.Key);
            _heading = entry.Value;
            _active.Remove(nodeIndex);
        }

        public void MarkBlockedRegion(Vector2i position, float radius)
        {
            _blocked.Add(new VoyageBlockedFrontier
            {
                Position = position,
                Radius = Math.Max(50f, radius),
                ExpiresUtc = DateTime.UtcNow.AddSeconds(35)
            });
            int[] activeIds = _active
                .Where(pair =>
                    pair.Value.Key.DistanceF(position) <=
                    Math.Max(50f, radius))
                .Select(pair => pair.Key)
                .ToArray();
            foreach (int activeId in activeIds)
            {
                _active.Remove(activeId);
            }
        }

        public bool HasPending
        {
            get { return true; }
        }
    }

    internal sealed class AreaMapSnapshot
    {
        public uint AreaHash { get; private set; }
        public string AreaId { get; private set; }
        public int Rows { get; private set; }
        public int Cols { get; private set; }
        public Vector2i SizeInNavCells { get; private set; }
        public int DataLength { get; private set; }
        public string Signature { get; private set; }
        public byte[] Data { get; private set; }
        public byte[] FlyData { get; private set; }
        public byte[,] JumpMask { get; private set; }
        public System.Collections.BitArray Walkable { get; private set; }
        public int WalkableCells { get; private set; }
        public int TerrainCells { get; private set; }
        public DateTime CreatedUtc { get; private set; }

        private AreaMapSnapshot(
            uint areaHash,
            string areaId,
            int rows,
            int cols,
            Vector2i sizeInNavCells,
            int dataLength,
            string signature,
            byte[] data,
            byte[] flyData,
            byte[,] jumpMask,
            System.Collections.BitArray walkable,
            int walkableCells,
            int terrainCells)
        {
            AreaHash = areaHash;
            AreaId = areaId ?? String.Empty;
            Rows = rows;
            Cols = cols;
            SizeInNavCells = sizeInNavCells;
            DataLength = dataLength;
            Signature = signature ?? String.Empty;
            Data = data == null ? null : (byte[])data.Clone();
            FlyData = flyData == null ? null : (byte[])flyData.Clone();
            JumpMask = jumpMask == null
                ? null
                : (byte[,])jumpMask.Clone();
            Walkable = walkable == null
                ? null
                : new System.Collections.BitArray(walkable);
            WalkableCells = walkableCells;
            TerrainCells = terrainCells;
            CreatedUtc = DateTime.UtcNow;
        }

        public static AreaMapSnapshot Create(
            uint areaHash,
            string areaId,
            DreamPoeBot.Loki.Game.CachedTerrainData cache,
            Vector2i sizeInNavCells,
            string signature,
            System.Collections.BitArray walkable,
            int walkableCells,
            int terrainCells)
        {
            return new AreaMapSnapshot(
                areaHash,
                areaId,
                cache.Rows,
                cache.Cols,
                sizeInNavCells,
                cache.Data == null ? 0 : cache.Data.Length,
                signature,
                cache.Data,
                cache.FlyData,
                cache.JumpMask,
                walkable,
                walkableCells,
                terrainCells);
        }
    }

    internal static class AreaMapSnapshotService
    {
        private static readonly object Sync = new object();
        private static AreaMapSnapshot _current;
        private static string _candidateSignature = String.Empty;
        private static int _candidateSamples;
        private static uint _candidateAreaHash;
        private static string _currentSignature = String.Empty;

        public static AreaMapSnapshot Current
        {
            get
            {
                lock (Sync)
                {
                    return _current;
                }
            }
        }

        public static bool IsReady(uint areaHash)
        {
            AreaMapSnapshot snapshot = Current;
            return snapshot != null && snapshot.AreaHash == areaHash;
        }

        public static void Reset(uint areaHash, string reason)
        {
            lock (Sync)
            {
                _current = null;
                _candidateSignature = String.Empty;
                _candidateSamples = 0;
                _candidateAreaHash = areaHash;
                _currentSignature = String.Empty;
                AllflameLog.Info(
                    "VOYAGE_TERRAIN_REBUILT" +
                    "|AreaHash=" + areaHash +
                    "|Reason=" + (reason ?? String.Empty) +
                    "|State=Loading");
            }
        }

        public static void Observe(
            uint areaHash,
            string areaId,
            Vector2i player,
            int navigationRevision,
            string mode = "Voyage")
        {
            if (areaHash == 0 ||
                LokiPoe.Me == null)
            {
                return;
            }

            string logPrefix =
                String.Equals(mode, "Chart", StringComparison.OrdinalIgnoreCase)
                    ? "CHART_TERRAIN"
                    : "VOYAGE_TERRAIN";

            try
            {
                DreamPoeBot.Loki.Game.CachedTerrainData cache =
                    LokiPoe.TerrainData.Cache;
                Vector2i size = LokiPoe.TerrainData.SizeInNavCells;
                if (cache == null ||
                    cache.Rows <= 0 ||
                    cache.Cols <= 0 ||
                    cache.Data == null ||
                    cache.Data.Length == 0 ||
                    size.X <= 0 ||
                    size.Y <= 0)
                {
                    AllflameLog.Throttled(
                        "voyage_terrain_wait",
                        TimeSpan.FromSeconds(3),
                        logPrefix + "_WAIT" +
                        "|AreaHash=" + areaHash +
                        "|Player=" + player +
                        "|NavigationRevision=" + navigationRevision +
                        "|Reason=CacheNotReady");
                    return;
                }

                string signature =
                    areaHash + "|" + cache.Rows + "|" + cache.Cols +
                    "|" + cache.Data.Length + "|" + size;
                int metadataSamples;
                lock (Sync)
                {
                    if (_candidateAreaHash != areaHash)
                    {
                        _current = null;
                        _candidateSignature = String.Empty;
                        _candidateSamples = 0;
                        _candidateAreaHash = areaHash;
                        _currentSignature = String.Empty;
                    }
                    if (String.Equals(
                            _candidateSignature,
                            signature,
                            StringComparison.Ordinal))
                    {
                        _candidateSamples++;
                    }
                    else
                    {
                        _candidateSignature = signature;
                        _candidateSamples = 1;
                    }

                    metadataSamples = _candidateSamples;
                    if (metadataSamples < 2)
                    {
                        AllflameLog.Throttled(
                            "voyage_terrain_stabilizing",
                            TimeSpan.FromSeconds(2),
                            logPrefix + "_WAIT" +
                            "|AreaHash=" + areaHash +
                            "|Player=" + player +
                            "|Rows=" + cache.Rows +
                            "|Cols=" + cache.Cols +
                            "|DataLength=" + cache.Data.Length +
                            "|Samples=" + metadataSamples +
                            "|Reason=MetadataStabilizing");
                        return;
                    }

                    if (String.Equals(
                            _currentSignature,
                            signature,
                            StringComparison.Ordinal))
                    {
                        return;
                    }
                }

                // Read metadata on every observation, but only build the
                // expensive walkability grid after two stable samples and
                // when the terrain signature actually changes.
                Stopwatch buildTimer = Stopwatch.StartNew();
                System.Collections.BitArray walkable =
                    WalkabilityGrid.GetWalkableBitArray(cache, 0);
                int walkableCells = 0;
                int terrainCells = walkable == null ? 0 : walkable.Length;
                if (walkable != null)
                {
                    for (int i = 0; i < walkable.Length; i++)
                    {
                        if (walkable[i])
                        {
                            walkableCells++;
                        }
                    }
                }
                buildTimer.Stop();
                VoyageRunnerMetrics.RecordTerrainBuild(
                    buildTimer.ElapsedMilliseconds);
                lock (Sync)
                {
                    if (!String.Equals(
                            _candidateSignature,
                            signature,
                            StringComparison.Ordinal) ||
                        _candidateSamples < 2 ||
                        String.Equals(
                            _currentSignature,
                            signature,
                            StringComparison.Ordinal))
                    {
                        return;
                    }

                    _current = AreaMapSnapshot.Create(
                        areaHash,
                        areaId,
                        cache,
                        size,
                        signature,
                        walkable,
                        walkableCells,
                        terrainCells);
                    _currentSignature = signature;
                    AllflameLog.Info(
                        logPrefix + "_READY" +
                        "|AreaHash=" + areaHash +
                        "|AreaId=" + (areaId ?? String.Empty) +
                        "|Rows=" + cache.Rows +
                        "|Cols=" + cache.Cols +
                        "|DataLength=" + cache.Data.Length +
                        "|WalkableCells=" + walkableCells +
                        "|TerrainCells=" + terrainCells +
                        "|SizeInNavCells=" + size +
                        "|BuildMs=" + buildTimer.ElapsedMilliseconds +
                        "|Player=" + player +
                        "|NavigationRevision=" +
                        navigationRevision);
                }
            }
            catch (Exception ex)
            {
                AllflameLog.Throttled(
                    "voyage_terrain_invalid",
                    TimeSpan.FromSeconds(5),
                    logPrefix + "_INVALID" +
                    "|AreaHash=" + areaHash +
                    "|Player=" + player +
                    "|NavigationRevision=" + navigationRevision +
                    "|Error=" + ex.GetType().Name +
                    "|Action=UseExistingPlannerAndRetry");
            }
        }

        public static bool ValidatePath(
            uint areaHash,
            Vector2i player,
            Vector2i target,
            string source,
            int navigationRevision)
        {
            if (!IsReady(areaHash))
            {
                return true;
            }

            bool pathExists;
            try
            {
                pathExists = VoyageRunnerMetrics.PathExistsBetween(
                    player,
                    target,
                    false);
            }
            catch (Exception ex)
            {
                AllflameLog.Throttled(
                    "voyage_terrain_path_validation_failed",
                    TimeSpan.FromSeconds(3),
                    "VOYAGE_TERRAIN_INVALID" +
                    "|AreaHash=" + areaHash +
                    "|Player=" + player +
                    "|Target=" + target +
                    "|Source=" + (source ?? String.Empty) +
                    "|NavigationRevision=" + navigationRevision +
                    "|Error=" + ex.GetType().Name +
                    "|Action=UsePathfinderFallback");
                return true;
            }

            if (!pathExists)
            {
                AllflameLog.Info(
                    "VOYAGE_TARGET_NO_PATH" +
                    "|AreaHash=" + areaHash +
                    "|Player=" + player +
                    "|Target=" + target +
                    "|Source=" + (source ?? String.Empty) +
                    "|NavigationRevision=" + navigationRevision +
                    "|Action=DiscardTargetAndSelectAnother");
            }
            return pathExists;
        }
    }

    internal sealed class ExploreVoyageTask : ObserverTask
    {
        private const int ShortTargetRejectsBeforeEscape = 4;
        private const int MaximumShortEscapeAttempts = 8;
        private const int MaximumShortEscapeCycles = 3;
        private const int MaximumShortEscapeRecoveries = 2;
        private const int MaximumVoyageRecoveryBudget = 4;
        private const int VoyageRecoveryBudgetSeconds = 30;
        private static readonly int[] ShortEscapeRadii =
        {
            130,
            90,
            60,
            35
        };
        private static readonly Vector2i[] ShortEscapeOffsets =
        {
            new Vector2i(1, 0),
            new Vector2i(1, 1),
            new Vector2i(0, 1),
            new Vector2i(-1, 1),
            new Vector2i(-1, 0),
            new Vector2i(-1, -1),
            new Vector2i(0, -1),
            new Vector2i(1, -1)
        };
        private readonly VoyageRollingFrontierPlanner _planner =
            new VoyageRollingFrontierPlanner();
        private readonly TopologyRoomRoutePlanner _topologyPlanner =
            new TopologyRoomRoutePlanner();
        private uint _areaHash;
        private Vector2i _sectorCenter;
        private int _nodeIndex = -1;
        private int _activeTopologyRoomIndex = -1;
        private string _activeTopologyRoomName = String.Empty;
        private Vector2i _target;
        private DateTime _targetStartedUtc = DateTime.MinValue;
        private Vector2i _lastProgressPosition;
        private DateTime _meaningfulProgressUtc = DateTime.MinValue;
        private float _bestTargetDistance = Single.MaxValue;
        private Vector2i _lastObservedPlayer;
        private bool _hasObservedPlayer;
        private bool _detouring;
        private Vector2i _detourTarget;
        private Vector2i _detourProgressPosition;
        private DateTime _detourStartedUtc = DateTime.MinValue;
        private DateTime _detourProgressUtc = DateTime.MinValue;
        private DateTime _obstacleRecoveryStartedUtc =
            DateTime.MinValue;
        private int _detourAttempt;
        private int _sector;
        private int _preferredDirection;
        private readonly List<KeyValuePair<DateTime, Vector2i>>
            _loopSamples =
                new List<KeyValuePair<DateTime, Vector2i>>();
        private DateTime _nextLoopSampleUtc = DateTime.MinValue;
        private DateTime _lastSpatialLoopRecoveryUtc =
            DateTime.MinValue;
        private int _lastLoopLanternCounter = -1;
        private DateTime _lastLanternProgressUtc =
            DateTime.MinValue;
        private bool _capsuleSecuringMode;
        private bool _capsuleTargetActive;
        private int _consecutiveShortTargetRejects;
        private Vector2i _shortTargetRejectAnchor;
        private bool _shortEscapeActive;
        private Vector2i _shortEscapeOrigin;
        private Vector2i _shortEscapeTarget;
        private DateTime _shortEscapeStartedUtc = DateTime.MinValue;
        private DateTime _shortEscapeTotalStartedUtc = DateTime.MinValue;
        private DateTime _shortEscapeWaitUntilUtc = DateTime.MinValue;
        private Vector2i _shortEscapeRecoveryOrigin;
        private int _shortEscapeAttempts;
        private int _shortEscapeRadiusIndex;
        private int _shortEscapeCycle;
        private int _shortEscapeRecoveries;
        private string _lastTargetFingerprint = String.Empty;
        private int _repeatedTargetFingerprintCount;
        private DateTime _recoveryBudgetStartedUtc = DateTime.MinValue;
        private string _recoveryBudgetFingerprint = String.Empty;
        private int _recoveryBudgetUsed;

        public ExploreVoyageTask()
            : base(
                "ExploreVoyageTask",
                "Explores a Voyage through dynamic sectors and micro-frontiers.") { }

        public override void Start()
        {
            _topologyPlanner.Reset(0);
            ResetSpatialLoopTracking();
            ResetShortTargetRecovery();
            _capsuleTargetActive = false;
            _lastTargetFingerprint = String.Empty;
            _repeatedTargetFingerprintCount = 0;
            ResetRecoveryBudget();
        }

        public override void Stop()
        {
            _topologyPlanner.Release(_activeTopologyRoomIndex);
            _activeTopologyRoomIndex = -1;
            ResetSpatialLoopTracking();
            ResetShortTargetRecovery();
            _capsuleTargetActive = false;
            _lastTargetFingerprint = String.Empty;
            _repeatedTargetFingerprintCount = 0;
            ResetRecoveryBudget();
            AllflameProgressWatchdog.Clear(Name);
        }

        public override Task<bool> Run()
        {
            Vector2i cycleStart = LokiPoe.Me == null
                ? new Vector2i()
                : LokiPoe.Me.Position;
            VoyageRunnerMetrics.BeginCycle(
                Name,
                cycleStart,
                _target);
            Task<bool> result = null;
            try
            {
                result = RunCore();
                return result;
            }
            finally
            {
                Vector2i cycleEnd = LokiPoe.Me == null
                    ? cycleStart
                    : LokiPoe.Me.Position;
                VoyageRunnerMetrics.EndCycle(
                    cycleEnd,
                    _target,
                    result != null && result.Result,
                    _shortEscapeAttempts,
                    _recoveryBudgetUsed);
            }
        }

        private Task<bool> RunCore()
        {
            AllflameSettings settings = AllflameSettings.Instance;
            bool capsuleSearchRequired =
                (VoyageRunState.LanternsExhausted ||
                 VoyageRunState.SurfaceTransferPending) &&
                !VoyageRunState.CallIssued &&
                !VoyageRunState.HasUsableCapsuleAnchor ||
                VoyageRunState.ExitCapsuleSecuringRequired;
            if (!AllflameContext.IsVoyageMapArea ||
                AllflameContext.Phase != AllflamePhase.Voyage ||
                !settings.EnableVoyageRunner ||
                (VoyageRunState.LanternsExhausted &&
                 !capsuleSearchRequired) ||
                AllflameLootState.IsActive ||
                (AllflameChestRoute.PendingCount > 0 &&
                 !capsuleSearchRequired) ||
                (VoyageRunState.SurfaceTransferPending &&
                 !capsuleSearchRequired) ||
                LokiPoe.Me == null)
            {
                AllflameProgressWatchdog.Clear(Name);
                return Task.FromResult(false);
            }

            if (_areaHash != AllflameContext.AreaHash)
            {
                _areaHash = AllflameContext.AreaHash;
                _sectorCenter = VoyageRunState.HasSpawn
                    ? VoyageRunState.Spawn
                    : LokiPoe.Me.Position;
                _sector = 1;
                _preferredDirection = 0;
                _topologyPlanner.Reset(_areaHash);
                ResetShortTargetRecovery();
                ResetRecoveryBudget();
                ResetPlanner();
                AreaMapSnapshotService.Reset(
                    _areaHash,
                    "VoyageAreaChanged");
                AllflameMovementCoordinator.AdvanceNavigation(
                    "VoyageAreaChanged");
                try { ExilePather.Reload(true); }
                catch { }
            }

            Vector2i player = LokiPoe.Me.Position;
            AllflameProgressWatchdog.BeginExplicitProgress(
                Name,
                WatchdogTargetId(),
                WatchdogTargetDescription());
            if (TryRecoverVoyageWatchdog(player))
            {
                return Task.FromResult(true);
            }
            AreaMapSnapshotService.Observe(
                AllflameContext.AreaHash,
                AllflameContext.AreaId,
                player,
                AllflameMovementCoordinator.NavigationRevision);
            if (capsuleSearchRequired != _capsuleSecuringMode)
            {
                _capsuleSecuringMode = capsuleSearchRequired;
                if (_capsuleSecuringMode)
                {
                    ResetActiveNavigation();
                    AllflameLog.Info(
                        "CAPSULE_SECURING_MODE" +
                        "|Active=True" +
                        "|LanternCounter=" +
                        AllflameContext.LanternCounterCurrent + "/" +
                        AllflameContext.LanternCounterMaximum +
                        "|ReserveThreshold=" +
                        VoyageRunState
                            .ExitCapsuleLanternReserveThreshold +
                        "|RegisteredCapsules=" +
                        VoyageRunState.CapsuleAnchorCount +
                        "|TraversedCapsules=" +
                        VoyageRunState.TraversedCapsuleCount +
                        "|Action=PauseChestRoutingAndSearchExit");
                }
            }
            if (_hasObservedPlayer &&
                player.DistanceF(_lastObservedPlayer) > 250f)
            {
                // A checkpoint resurrection or another forced relocation can
                // retain the same area hash. Targets created around the old
                // spawn then become thousands of units away and are invalid.
                _sectorCenter = player;
                _sector = 1;
                _preferredDirection =
                    (_preferredDirection + 1) % 4;
                ResetShortTargetRecovery();
                ResetPlanner();
                ResetActiveNavigation();
                ResetRecoveryBudget();
                AllflameMovementCoordinator.AdvanceNavigation(
                    "LargePositionDiscontinuity");
                AllflameLog.Info(
                    "VOYAGE_NAVIGATION_REBASED" +
                    "|Reason=LargePositionDiscontinuity" +
                    "|Previous=" + _lastObservedPlayer +
                    "|Current=" + player +
                    "|Action=DiscardOldFrontiers");
            }
            _lastObservedPlayer = player;
            _hasObservedPlayer = true;
            _planner.Observe(player);
            ObserveSpatialLoopState(player);

            if (!_capsuleTargetActive &&
                (_shortEscapeActive ||
                _consecutiveShortTargetRejects >=
                    ShortTargetRejectsBeforeEscape ||
                DateTime.UtcNow < _shortEscapeWaitUntilUtc))
            {
                return Task.FromResult(
                    RunShortTargetEscape(player));
            }

            if (!_capsuleTargetActive &&
                TryRecoverSpatialLoop(player))
            {
                return Task.FromResult(true);
            }

            if (_detouring)
            {
                return Task.FromResult(RunDetour(player));
            }

            if (_nodeIndex >= 0 ||
                _activeTopologyRoomIndex >= 0 ||
                _capsuleTargetActive)
            {
                float distance = player.DistanceF(_target);
                // Frontier points can lie just inside large terrain objects.
                // Reaching half a micro-frontier spacing is sufficient for
                // discovery and prevents fighting an unreachable exact point.
                float arrivalRadius = Math.Max(
                    28f,
                    Math.Min(
                        48f,
                        settings.VoyageFrontierSpacing * 0.5f));
                bool reached = distance <= arrivalRadius;
                bool timedOut =
                    DateTime.UtcNow - _targetStartedUtc >=
                    TimeSpan.FromSeconds(
                        Math.Max(7, settings.VoyageFrontierTimeoutSeconds));
                if (distance <= _bestTargetDistance - 6f)
                {
                    _bestTargetDistance = distance;
                    _meaningfulProgressUtc = DateTime.UtcNow;
                    _lastProgressPosition = player;
                    AllflameProgressWatchdog.MarkProgress(
                        "VoyageTargetDistanceImproved");
                }
                bool noProgress =
                    DateTime.UtcNow - _meaningfulProgressUtc >=
                    TimeSpan.FromSeconds(1);
                if (reached)
                {
                    if (_capsuleTargetActive)
                    {
                        VoyageRunState.MarkCapsuleTraversed(
                            _target,
                            "ExploreVoyageCapsulePriority");
                        AllflameLog.Info(
                            "CAPSULE_PRIORITY_TARGET_REACHED" +
                            "|Target=" + _target +
                            "|Distance=" + distance.ToString("0.0") +
                            "|Action=ResumeVoyage");
                        _capsuleTargetActive = false;
                    }
                    else if (_activeTopologyRoomIndex >= 0)
                    {
                        AllflameLog.Info(
                            "TOPOLOGY_ROOM_REACHED" +
                            "|Mode=Voyage" +
                            "|Index=" + _activeTopologyRoomIndex +
                            "|Name=" + _activeTopologyRoomName +
                            "|Target=" + _target +
                            "|Distance=" + distance.ToString("0.0") +
                            "|Action=ResumeTopologyOrFrontier");
                        _topologyPlanner.MarkReached(
                            _activeTopologyRoomIndex);
                        _activeTopologyRoomIndex = -1;
                        _activeTopologyRoomName = String.Empty;
                    }
                    else
                    {
                        _planner.MarkReached(_nodeIndex);
                    }
                    _nodeIndex = -1;
                    _detourAttempt = 0;
                    _obstacleRecoveryStartedUtc =
                        DateTime.MinValue;
                    AllflameProgressWatchdog.MarkProgress(
                        "VoyageTargetReached");
                }
                else if (timedOut || noProgress)
                {
                    if (!timedOut &&
                        _detourAttempt < 4 &&
                        TryStartDetour(player))
                    {
                        return Task.FromResult(true);
                    }

                    if (_capsuleTargetActive)
                    {
                        VoyageRunState.DeferCapsuleVisit(
                            _target,
                            timedOut
                                ? "PriorityTargetTimeout"
                                : "PriorityTargetNoProgress");
                        _capsuleTargetActive = false;
                        AllflameLog.Info(
                            "CAPSULE_PRIORITY_TARGET_DEFERRED" +
                            "|Target=" + _target +
                            "|Timeout=" + timedOut +
                            "|NoProgress=" + noProgress +
                            "|Action=ResumeVoyageThenRetry");
                    }
                    else if (_activeTopologyRoomIndex >= 0)
                    {
                        _topologyPlanner.MarkBlocked(
                            _activeTopologyRoomIndex,
                            timedOut ? "Timeout" : "NoProgress");
                        _activeTopologyRoomIndex = -1;
                        _activeTopologyRoomName = String.Empty;
                    }
                    else
                    {
                        _planner.MarkBlockedRegion(
                            _target,
                            Math.Max(
                                45f,
                                settings.VoyageFrontierSpacing * 0.65f));
                    }
                    _nodeIndex = -1;
                    AllflameMovementCoordinator.AdvanceNavigation(
                        timedOut ? "FrontierTimeout" : "FrontierNoProgress");
                    _preferredDirection =
                        (_preferredDirection + 1) % 8;
                    AllflameLog.Info(
                        "VOYAGE_FRONTIER_BLOCKED|Sector=" + _sector +
                        "|Target=" + _target +
                        "|Timeout=" + timedOut +
                        "|NoProgress=" + noProgress +
                        "|DetourAttempts=" + _detourAttempt +
                        "|Action=BlockNearbyFrontiersAndChangeBranch");
                    _detourAttempt = 0;
                    _obstacleRecoveryStartedUtc =
                        DateTime.MinValue;
                    AllflameProgressWatchdog.MarkProgress(
                        timedOut
                            ? "VoyageFrontierTimeoutRotated"
                            : "VoyageFrontierNoProgressRotated");
                }
                else
                {
                    string targetFingerprint =
                        AllflameContext.AreaHash + "|" +
                        AllflameMovementCoordinator.NavigationRevision +
                        "|" + _target;
                    if (String.Equals(
                            targetFingerprint,
                            _lastTargetFingerprint,
                            StringComparison.Ordinal))
                    {
                        _repeatedTargetFingerprintCount++;
                    }
                    else
                    {
                        _lastTargetFingerprint = targetFingerprint;
                        _repeatedTargetFingerprintCount = 1;
                    }
                    if (_repeatedTargetFingerprintCount >= 4 &&
                        DateTime.UtcNow - _meaningfulProgressUtc >=
                            TimeSpan.FromSeconds(2))
                    {
                        AllflameLog.Info(
                            "NAVIGATION_FINGERPRINT_REPEAT" +
                            "|Target=" + _target +
                            "|Count=" + _repeatedTargetFingerprintCount +
                            "|Action=DiscardTargetAndRebuild");
                        _planner.MarkBlockedRegion(_target, 120f);
                        _nodeIndex = -1;
                        _activeTopologyRoomIndex = -1;
                        _activeTopologyRoomName = String.Empty;
                        _preferredDirection =
                            (_preferredDirection + 1) % 8;
                        AllflameMovementCoordinator.AdvanceNavigation(
                            "TargetFingerprintRepeat");
                        ResetPlanner();
                        _repeatedTargetFingerprintCount = 0;
                        return Task.FromResult(true);
                    }
                    string movementContext =
                        _capsuleTargetActive || capsuleSearchRequired
                            ? Name + " Capsule extraction priority"
                            : Name;
                    bool moving = AllflameMovementCoordinator.MoveTowards(
                        _target,
                        movementContext);
                    AllflameLog.Throttled(
                        "voyage_frontier_move",
                        TimeSpan.FromSeconds(2),
                        "VOYAGE_STAGE|Stage=3-4|Sector=" + _sector +
                        "|Target=" + _target +
                        "|Distance=" + distance.ToString("0.0") +
                        "|Moving=" + moving);
                    return Task.FromResult(true);
                }
            }

            int direction;
            Vector2i target;
            string topologyRoomName;
            Vector2i knownCapsule;
            if (capsuleSearchRequired &&
                VoyageRunState.TryGetNearestUntraversedCapsule(
                    player,
                    out knownCapsule))
            {
                _capsuleTargetActive = true;
                _nodeIndex = -1;
                _activeTopologyRoomIndex = -1;
                _activeTopologyRoomName = String.Empty;
                _target = knownCapsule;
                _targetStartedUtc = DateTime.UtcNow;
                _meaningfulProgressUtc = DateTime.UtcNow;
                _lastProgressPosition = player;
                _bestTargetDistance = player.DistanceF(knownCapsule);
                _detourAttempt = 0;
                BeginRecoveryBudget(
                    knownCapsule,
                    "CapsuleTargetSelected");
                AllflameProgressWatchdog.MarkProgress(
                    "VoyageCapsuleTargetSelected");
                AllflameLog.Info(
                    "CAPSULE_PRIORITY_TARGET_SELECTED" +
                    "|Target=" + knownCapsule +
                    "|Distance=" +
                    _bestTargetDistance.ToString("0.0") +
                    "|LanternCounter=" +
                    AllflameContext.LanternCounterCurrent + "/" +
                    AllflameContext.LanternCounterMaximum +
                    "|Action=PreemptTopologyAndFrontier");
                return Task.FromResult(true);
            }
            if (!capsuleSearchRequired &&
                _topologyPlanner.TrySelect(
                    player,
                    out _activeTopologyRoomIndex,
                    out target,
                    out topologyRoomName))
            {
                _nodeIndex = -1;
                _target = target;
                _activeTopologyRoomName = topologyRoomName;
                _targetStartedUtc = DateTime.UtcNow;
                _meaningfulProgressUtc = DateTime.UtcNow;
                _lastProgressPosition = player;
                _bestTargetDistance = player.DistanceF(target);
                _detourAttempt = 0;
                BeginRecoveryBudget(
                    target,
                    "TopologyTargetSelected");
                AllflameProgressWatchdog.MarkProgress(
                    "VoyageTopologyTargetSelected");
                AllflameLog.Info(
                    "TOPOLOGY_ROOM_SELECTED" +
                    "|Mode=Voyage" +
                    "|Index=" + _activeTopologyRoomIndex +
                    "|Name=" + _activeTopologyRoomName +
                    "|From=" + player +
                    "|Target=" + target +
                    "|Distance=" +
                    _bestTargetDistance.ToString("0.0") +
                    "|ChestPreemption=True" +
                    "|Fallback=RollingFrontier");
                return Task.FromResult(true);
            }

            if (!_planner.TrySelect(
                    player,
                    _preferredDirection,
                    true,
                    out _nodeIndex,
                    out direction,
                    out target))
            {
                if (_consecutiveShortTargetRejects > 0)
                {
                    _consecutiveShortTargetRejects =
                        ShortTargetRejectsBeforeEscape;
                    AllflameLog.Info(
                        "VOYAGE_SHORT_TARGET_SET_EXHAUSTED" +
                        "|Rejects=" +
                        _consecutiveShortTargetRejects +
                        "|Player=" + player +
                        "|Action=StartBoundedEscapeRecovery");
                    return Task.FromResult(
                        RunShortTargetEscape(player));
                }

                // A completed micro-grid becomes one macro sector. The next
                // sector grows from the furthest reachable player position,
                // not from a hard-coded 3x3 rectangle.
                _sector++;
                VoyageRunState.SectorBoundaryReached = true;
                _sectorCenter = player;
                _preferredDirection =
                    (_preferredDirection + 1) % 8;
                ResetPlanner();
                return Task.FromResult(true);
            }

            if (!AreaMapSnapshotService.ValidatePath(
                    AllflameContext.AreaHash,
                    player,
                    target,
                    capsuleSearchRequired
                        ? "CapsuleSearchFallback"
                        : "TerrainFrontier",
                    AllflameMovementCoordinator.NavigationRevision))
            {
                _planner.MarkBlockedRegion(
                    target,
                    Math.Max(
                        45f,
                        settings.VoyageFrontierSpacing * 0.65f));
                _nodeIndex = -1;
                AllflameMovementCoordinator.AdvanceNavigation(
                    "TerrainTargetNoPath");
                return Task.FromResult(true);
            }

            float selectedArrivalRadius = Math.Max(
                28f,
                Math.Min(
                    48f,
                    settings.VoyageFrontierSpacing * 0.5f));
            float selectedDistance = player.DistanceF(target);
            if (selectedDistance <= selectedArrivalRadius)
            {
                if (_consecutiveShortTargetRejects == 0 ||
                    player.DistanceF(_shortTargetRejectAnchor) > 80f)
                {
                    _consecutiveShortTargetRejects = 0;
                    _shortTargetRejectAnchor = player;
                }
                _consecutiveShortTargetRejects++;
                _nodeIndex = -1;
                _preferredDirection = (direction + 1) % 8;
                AllflameLog.Info(
                    "VOYAGE_FRONTIER_SHORT_TARGET_REJECTED" +
                    "|Sector=" + _sector +
                    "|Target=" + target +
                    "|Player=" + player +
                    "|Distance=" + selectedDistance.ToString("0.0") +
                    "|ArrivalRadius=" +
                    selectedArrivalRadius.ToString("0.0") +
                    "|ConsecutiveRejects=" +
                    _consecutiveShortTargetRejects + "/" +
                    ShortTargetRejectsBeforeEscape +
                    "|Action=" +
                    (_consecutiveShortTargetRejects >=
                        ShortTargetRejectsBeforeEscape
                            ? "StartBoundedEscapeRecovery"
                            : "RotateWithoutReset"));
                if (_consecutiveShortTargetRejects >=
                    ShortTargetRejectsBeforeEscape)
                {
                    return Task.FromResult(
                        RunShortTargetEscape(player));
                }
                return Task.FromResult(true);
            }

            ResetShortTargetRecovery();
            _target = target;
            _targetStartedUtc = DateTime.UtcNow;
            _meaningfulProgressUtc = DateTime.UtcNow;
            _lastProgressPosition = player;
            _bestTargetDistance = player.DistanceF(target);
            _detourAttempt = 0;
            _preferredDirection = direction;
            BeginRecoveryBudget(
                target,
                "FrontierTargetSelected");
            AllflameProgressWatchdog.MarkProgress(
                "VoyageFrontierTargetSelected");
            AllflameLog.Info(
                "VOYAGE_FRONTIER_SELECTED|Sector=" + _sector +
                "|Mode=" +
                (capsuleSearchRequired
                    ? "CapsuleSearch"
                    : "Explore") +
                "|Direction=" + direction +
                "|Center=" + _sectorCenter +
                "|Target=" + target);
            _lastTargetFingerprint =
                AllflameContext.AreaHash + "|" +
                AllflameMovementCoordinator.NavigationRevision + "|" +
                target;
            _repeatedTargetFingerprintCount = 0;
            return Task.FromResult(true);
        }

        private int WatchdogTargetId()
        {
            if (_capsuleTargetActive)
            {
                return -2;
            }
            if (_activeTopologyRoomIndex >= 0)
            {
                return _activeTopologyRoomIndex;
            }
            return _nodeIndex;
        }

        private string WatchdogTargetDescription()
        {
            return _target == default(Vector2i)
                ? "VoyageSector=" + _sector
                : _target.ToString();
        }

        private bool TryRecoverVoyageWatchdog(Vector2i player)
        {
            if (!AllflameProgressWatchdog.TryConsumeRecovery(
                    "VoyageTargetReacquire"))
            {
                return false;
            }

            bool budgetAvailable =
                TryConsumeVoyageRecoveryBudget(
                    "ProgressWatchdog",
                    player);
            Vector2i abandonedTarget = _target;
            if (_capsuleTargetActive)
            {
                VoyageRunState.DeferCapsuleVisit(
                    abandonedTarget,
                    "ProgressWatchdogRecovery");
            }
            else if (_activeTopologyRoomIndex >= 0)
            {
                _topologyPlanner.MarkBlocked(
                    _activeTopologyRoomIndex,
                    "ProgressWatchdogRecovery");
            }
            else if (_nodeIndex >= 0)
            {
                _planner.MarkBlockedRegion(
                    abandonedTarget,
                    Math.Max(
                        60f,
                        AllflameSettings.Instance.VoyageFrontierSpacing));
            }

            _sectorCenter = player;
            _preferredDirection = (_preferredDirection + 1) % 8;
            ResetActiveNavigation();
            if (!budgetAvailable)
            {
                _sector++;
                ResetPlanner();
            }
            AllflameMovementCoordinator.AdvanceNavigation(
                "VoyageProgressWatchdogRecovery");
            AllflameContext.RequestRefresh(
                "VoyageProgressWatchdogRecovery");
            AllflameProgressWatchdog.MarkProgress(
                budgetAvailable
                    ? "VoyageTargetReacquired"
                    : "VoyageRecoveryBudgetRotated");
            AllflameLog.Info(
                "VOYAGE_PROGRESS_RECOVERY" +
                "|Player=" + player +
                "|AbandonedTarget=" + abandonedTarget +
                "|BudgetAvailable=" + budgetAvailable +
                "|BudgetUsed=" + _recoveryBudgetUsed +
                "|BudgetLimit=" + MaximumVoyageRecoveryBudget +
                "|Action=" +
                (budgetAvailable
                    ? "DiscardTargetAndReacquire"
                    : "RotateSectorAndReacquire"));
            return true;
        }

        private void BeginRecoveryBudget(
            Vector2i target,
            string source)
        {
            _recoveryBudgetStartedUtc = DateTime.UtcNow;
            _recoveryBudgetFingerprint =
                AllflameContext.AreaHash + "|" + target;
            _recoveryBudgetUsed = 0;
            VoyageRunnerMetrics.RecordRecovery(0, source);
        }

        private bool TryConsumeVoyageRecoveryBudget(
            string reason,
            Vector2i player)
        {
            string fingerprint =
                AllflameContext.AreaHash + "|" + _target;
            if (!String.Equals(
                    _recoveryBudgetFingerprint,
                    fingerprint,
                    StringComparison.Ordinal) ||
                _recoveryBudgetStartedUtc == DateTime.MinValue)
            {
                BeginRecoveryBudget(_target, "LazyStart");
            }

            double elapsedSeconds =
                (DateTime.UtcNow - _recoveryBudgetStartedUtc)
                    .TotalSeconds;
            if (_recoveryBudgetUsed >= MaximumVoyageRecoveryBudget ||
                elapsedSeconds >= VoyageRecoveryBudgetSeconds)
            {
                VoyageRunnerMetrics.RecordRecovery(
                    _recoveryBudgetUsed,
                    "BudgetExhausted:" + reason);
                AllflameLog.Info(
                    "VOYAGE_RECOVERY_BUDGET_EXHAUSTED" +
                    "|Reason=" + reason +
                    "|Player=" + player +
                    "|Target=" + _target +
                    "|Used=" + _recoveryBudgetUsed +
                    "|Limit=" + MaximumVoyageRecoveryBudget +
                    "|ElapsedSeconds=" +
                    elapsedSeconds.ToString("0.0") +
                    "|Action=RotateStrategy");
                return false;
            }

            _recoveryBudgetUsed++;
            VoyageRunnerMetrics.RecordRecovery(
                _recoveryBudgetUsed,
                reason);
            AllflameProgressWatchdog.SetRetry(
                _recoveryBudgetUsed);
            AllflameLog.Info(
                "VOYAGE_RECOVERY_BUDGET" +
                "|Reason=" + reason +
                "|Player=" + player +
                "|Target=" + _target +
                "|Used=" + _recoveryBudgetUsed +
                "|Limit=" + MaximumVoyageRecoveryBudget +
                "|Remaining=" +
                (MaximumVoyageRecoveryBudget - _recoveryBudgetUsed));
            return true;
        }

        private void ResetRecoveryBudget()
        {
            _recoveryBudgetStartedUtc = DateTime.MinValue;
            _recoveryBudgetFingerprint = String.Empty;
            _recoveryBudgetUsed = 0;
        }

        private bool RunShortTargetEscape(Vector2i player)
        {
            DateTime now = DateTime.UtcNow;
            if (now < _shortEscapeWaitUntilUtc)
            {
                AllflameLog.Throttled(
                    "voyage_short_escape_wait",
                    TimeSpan.FromSeconds(2),
                    "VOYAGE_SHORT_ESCAPE_WAIT" +
                    "|Cycle=" + _shortEscapeCycle +
                    "|RemainingSeconds=" +
                    (_shortEscapeWaitUntilUtc - now)
                        .TotalSeconds.ToString("0.0") +
                    "|Action=RetryNewCycle");
                return true;
            }

            if (_shortEscapeActive)
            {
                float moved =
                    _shortEscapeRecoveryOrigin.DistanceF(player);
                if (moved >= 35f)
                {
                    AllflameLog.Info(
                        "VOYAGE_SHORT_ESCAPE_CONFIRMED" +
                        "|Cycle=" + _shortEscapeCycle +
                        "|Attempt=" + _shortEscapeAttempts + "/" +
                        MaximumShortEscapeAttempts +
                        "|Origin=" + _shortEscapeOrigin +
                        "|RecoveryOrigin=" +
                        _shortEscapeRecoveryOrigin +
                        "|Player=" + player +
                        "|Moved=" + moved.ToString("0.0") +
                        "|Action=ResumeRollingFrontier");
                    _sectorCenter = player;
                    _preferredDirection =
                        (_preferredDirection + 1) % 8;
                    ResetShortTargetRecovery();
                    ResetPlanner();
                    AllflameProgressWatchdog.MarkProgress(
                        "VoyageShortEscapeConfirmed");
                    return true;
                }

                if (now - _shortEscapeStartedUtc <
                    TimeSpan.FromSeconds(3))
                {
                    bool moving = AllflameMovementCoordinator.MoveTowards(
                        _shortEscapeTarget,
                        Name + " short frontier escape");
                    AllflameLog.Throttled(
                        "voyage_short_escape_move",
                        TimeSpan.FromSeconds(1),
                        "VOYAGE_SHORT_ESCAPE_MOVE" +
                        "|Cycle=" + _shortEscapeCycle +
                        "|Attempt=" + _shortEscapeAttempts + "/" +
                        MaximumShortEscapeAttempts +
                        "|Target=" + _shortEscapeTarget +
                        "|Moved=" + moved.ToString("0.0") +
                        "|Moving=" + moving);
                    return true;
                }

                _planner.MarkBlockedRegion(
                    _shortEscapeTarget,
                    80f);
                _shortEscapeActive = false;
                AllflameLog.Info(
                    "VOYAGE_SHORT_ESCAPE_TIMEOUT" +
                    "|Cycle=" + _shortEscapeCycle +
                    "|Attempt=" + _shortEscapeAttempts + "/" +
                    MaximumShortEscapeAttempts +
                    "|Target=" + _shortEscapeTarget +
                    "|Moved=" + moved.ToString("0.0") +
                    "|Action=TryNextDirection");
            }

            if (_shortEscapeCycle == 0)
            {
                _shortEscapeCycle = 1;
                _shortEscapeTotalStartedUtc = now;
                _shortEscapeRecoveryOrigin = player;
                AllflameProgressWatchdog.BeginExplicitProgress(
                    Name,
                    0,
                    "Voyage Short Frontier Escape");
            }

            if (now - _shortEscapeTotalStartedUtc >=
                TimeSpan.FromSeconds(30))
            {
                return StopShortEscape(
                    "TotalTimeout30Seconds",
                    player);
            }

            if (_shortEscapeAttempts <
                MaximumShortEscapeAttempts)
            {
                int direction =
                    (_preferredDirection + _shortEscapeAttempts +
                     _shortEscapeCycle - 1) %
                    ShortEscapeOffsets.Length;
                int radiusIndex = Math.Max(
                    0,
                    Math.Min(
                        ShortEscapeRadii.Length - 1,
                        _shortEscapeRadiusIndex));
                int radius = radiusIndex == 0
                    ? Math.Max(
                        ShortEscapeRadii[0],
                        AllflameSettings.Instance
                            .VoyageFrontierSpacing + 35)
                    : ShortEscapeRadii[radiusIndex];
                int candidateNumber =
                    _shortEscapeAttempts *
                    ShortEscapeRadii.Length +
                    radiusIndex + 1;
                _shortEscapeRadiusIndex++;
                if (_shortEscapeRadiusIndex >=
                    ShortEscapeRadii.Length)
                {
                    _shortEscapeRadiusIndex = 0;
                    _shortEscapeAttempts++;
                }
                if (!TryConsumeVoyageRecoveryBudget(
                        "ShortFrontierEscape",
                        player))
                {
                    return StopShortEscape(
                        "RecoveryBudgetExhausted",
                        player);
                }
                AllflameProgressWatchdog.SetRetry(candidateNumber);

                double angle =
                    direction * Math.PI * 2.0 /
                        ShortEscapeOffsets.Length +
                    (_shortEscapeCycle - 1) * Math.PI / 12.0;
                Vector2i requested = new Vector2i(
                    player.X +
                    (int)Math.Round(Math.Cos(angle) * radius),
                    player.Y +
                    (int)Math.Round(Math.Sin(angle) * radius));
                Vector2i resolved;
                Vector2i raycastHit;
                bool clipped;
                bool raycastOk =
                    VoyageRollingFrontierPlanner
                        .TryResolveRaycastTarget(
                            player,
                            requested,
                            out resolved,
                            out raycastHit,
                            out clipped);
                float distance = player.DistanceF(resolved);
                bool pathChecked = false;
                bool pathOk = false;
                string rejectReason = String.Empty;
                if (!raycastOk)
                {
                    rejectReason = "RaycastRejected";
                }
                else if (distance < 12f)
                {
                    rejectReason = "ResolvedStepTooShort";
                }
                else
                {
                    pathChecked = true;
                    try
                    {
                        pathOk = VoyageRunnerMetrics.PathExistsBetween(
                            player,
                            resolved,
                            false);
                    }
                    catch
                    {
                        rejectReason = "PathException";
                    }
                    if (!pathOk &&
                        String.IsNullOrEmpty(rejectReason))
                    {
                        rejectReason = "PathRejected";
                    }
                }

                bool moving = false;
                if (pathOk)
                {
                    moving = AllflameMovementCoordinator.MoveTowards(
                        resolved,
                        Name + " short frontier escape");
                    if (!moving)
                    {
                        rejectReason = "MoveRejected";
                    }
                }
                AllflameLog.Info(
                    "VOYAGE_SHORT_ESCAPE_ATTEMPT" +
                    "|Cycle=" + _shortEscapeCycle +
                    "|Candidate=" + candidateNumber + "/" +
                    (MaximumShortEscapeAttempts *
                     ShortEscapeRadii.Length) +
                    "|Direction=" + direction +
                    "|Radius=" + radius +
                    "|Requested=" + requested +
                    "|Resolved=" + resolved +
                    "|Distance=" + distance.ToString("0.0") +
                    "|Raycast=" + (raycastOk
                        ? (clipped ? "Clipped" : "Clear")
                        : "Rejected") +
                    "|PathChecked=" + pathChecked +
                    "|PathResult=" +
                    (pathChecked ? pathOk.ToString() : "NotRun") +
                    "|RejectReason=" +
                    (String.IsNullOrEmpty(rejectReason)
                        ? "None"
                        : rejectReason) +
                    "|Moving=" + moving +
                    "|OneCandidatePerCycle=True");
                if (moving)
                {
                    _shortEscapeActive = true;
                    _shortEscapeOrigin = player;
                    _shortEscapeTarget = resolved;
                    _shortEscapeStartedUtc = now;
                    _preferredDirection = direction;
                    AllflameProgressWatchdog.MarkProgress(
                        "VoyageShortEscapeStarted");
                }
                return true;
            }

            if (_shortEscapeCycle >= MaximumShortEscapeCycles ||
                now - _shortEscapeTotalStartedUtc >=
                    TimeSpan.FromSeconds(30))
            {
                return StopShortEscape(
                    "CandidateCyclesExhausted",
                    player);
            }
            if (_shortEscapeRecoveries >=
                MaximumShortEscapeRecoveries)
            {
                return StopShortEscape(
                    "RecoveryLimitExceeded",
                    player);
            }
            _shortEscapeRecoveries++;
            try
            {
                ExilePather.Reload(true);
            }
            catch
            {
            }
            AllflameLog.Info(
                "VOYAGE_SHORT_ESCAPE_RECOVERY" +
                "|Cycle=" + _shortEscapeCycle +
                "|Attempt=" + _shortEscapeRecoveries + "/" +
                MaximumShortEscapeRecoveries +
                "|Player=" + player +
                "|Action=ReloadPatherAndRotateCycle");
            _shortEscapeActive = false;
            _shortEscapeAttempts = 0;
            _shortEscapeRadiusIndex = 0;
            _shortEscapeCycle++;
            _shortEscapeWaitUntilUtc = now.AddSeconds(1);
            return true;
        }

        private bool StopShortEscape(string reason, Vector2i player)
        {
            double elapsed =
                _shortEscapeTotalStartedUtc == DateTime.MinValue
                    ? 0
                    : (DateTime.UtcNow - _shortEscapeTotalStartedUtc)
                        .TotalSeconds;
            AllflameLog.Info(
                "VOYAGE_SHORT_ESCAPE_ROTATE" +
                "|Reason=" + (reason ?? String.Empty) +
                "|Cycle=" + _shortEscapeCycle +
                "|Recoveries=" + _shortEscapeRecoveries +
                "|ElapsedSeconds=" + elapsed.ToString("0.0") +
                "|Player=" + player +
                "|Action=ResetPlannerAndContinue");
            _sectorCenter = player;
            _preferredDirection =
                (_preferredDirection + 1) % 8;
            _nodeIndex = -1;
            _activeTopologyRoomIndex = -1;
            _activeTopologyRoomName = String.Empty;
            AllflameMovementCoordinator.AdvanceNavigation(
                "ShortEscapeStrategyRotated");
            ResetShortTargetRecovery();
            ResetPlanner();
            _shortEscapeWaitUntilUtc =
                DateTime.UtcNow.AddSeconds(1);
            return true;
        }

        private void ResetShortTargetRecovery()
        {
            _consecutiveShortTargetRejects = 0;
            _shortTargetRejectAnchor = new Vector2i();
            _shortEscapeActive = false;
            _shortEscapeOrigin = new Vector2i();
            _shortEscapeTarget = new Vector2i();
            _shortEscapeStartedUtc = DateTime.MinValue;
            _shortEscapeTotalStartedUtc = DateTime.MinValue;
            _shortEscapeWaitUntilUtc = DateTime.MinValue;
            _shortEscapeRecoveryOrigin = new Vector2i();
            _shortEscapeAttempts = 0;
            _shortEscapeRadiusIndex = 0;
            _shortEscapeCycle = 0;
            _shortEscapeRecoveries = 0;
        }

        private void ObserveSpatialLoopState(Vector2i player)
        {
            DateTime now = DateTime.UtcNow;
            int lantern = AllflameContext.LanternCounterCurrent;
            if (lantern >= 0 &&
                lantern != _lastLoopLanternCounter)
            {
                _lastLoopLanternCounter = lantern;
                _lastLanternProgressUtc = now;
                _loopSamples.Clear();
                _nextLoopSampleUtc = now;
            }
            else if (_lastLanternProgressUtc == DateTime.MinValue)
            {
                _lastLanternProgressUtc = now;
            }

            if (now < _nextLoopSampleUtc)
            {
                return;
            }
            _nextLoopSampleUtc = now.AddSeconds(1);
            _loopSamples.Add(
                new KeyValuePair<DateTime, Vector2i>(
                    now,
                    player));
            _loopSamples.RemoveAll(sample =>
                now - sample.Key > TimeSpan.FromSeconds(16));
        }

        private bool TryRecoverSpatialLoop(Vector2i player)
        {
            DateTime now = DateTime.UtcNow;
            if (_loopSamples.Count < 9 ||
                now - _lastLanternProgressUtc <
                    TimeSpan.FromSeconds(10) ||
                now - _lastSpatialLoopRecoveryUtc <
                    TimeSpan.FromSeconds(12))
            {
                return false;
            }

            KeyValuePair<DateTime, Vector2i>? oldNearby =
                _loopSamples
                    .Where(sample =>
                        now - sample.Key >=
                            TimeSpan.FromSeconds(9) &&
                        sample.Value.DistanceF(player) <= 175f)
                    .Cast<KeyValuePair<DateTime, Vector2i>?>()
                    .FirstOrDefault();
            if (!oldNearby.HasValue)
            {
                return false;
            }

            float travelled = 0f;
            for (int i = 1; i < _loopSamples.Count; i++)
            {
                travelled +=
                    _loopSamples[i - 1].Value.DistanceF(
                        _loopSamples[i].Value);
            }
            if (travelled < 320f)
            {
                // Stationary obstruction is handled by the existing
                // one/five-second obstacle failsafes. This detector is for a
                // moving orbit that those failsafes cannot see.
                return false;
            }

            int centerX =
                (int)Math.Round(_loopSamples.Average(
                    sample => sample.Value.X));
            int centerY =
                (int)Math.Round(_loopSamples.Average(
                    sample => sample.Value.Y));
            Vector2i loopCenter =
                new Vector2i(centerX, centerY);
            Vector2i recoveryAnchor =
                player.DistanceF(_sectorCenter) >= 260f
                    ? _sectorCenter
                    : (VoyageRunState.HasSpawn
                        ? VoyageRunState.Spawn
                        : _sectorCenter);

            if (!TryConsumeVoyageRecoveryBudget(
                    "SpatialLoop",
                    player))
            {
                _loopSamples.Clear();
                _lastSpatialLoopRecoveryUtc = now;
                return false;
            }

            if (_nodeIndex >= 0)
            {
                _planner.MarkBlockedRegion(_target, 80f);
            }
            if (_activeTopologyRoomIndex >= 0)
            {
                _topologyPlanner.MarkBlocked(
                    _activeTopologyRoomIndex,
                    "SpatialLoop");
                _activeTopologyRoomIndex = -1;
                _activeTopologyRoomName = String.Empty;
            }
            _planner.MarkBlockedRegion(loopCenter, 210f);
            _detouring = false;
            _detourAttempt = 0;
            _obstacleRecoveryStartedUtc = DateTime.MinValue;

            int escapeNode;
            int escapeDirection;
            Vector2i escapeTarget;
            if (!_planner.TrySelectLoopEscape(
                    player,
                    loopCenter,
                    recoveryAnchor,
                    out escapeNode,
                    out escapeDirection,
                    out escapeTarget))
            {
                AllflameLog.Info(
                    "VOYAGE_SPATIAL_LOOP_ESCAPE_FAILED" +
                    "|Player=" + player +
                    "|LoopCenter=" + loopCenter +
                    "|Travelled=" + travelled.ToString("0.0") +
                    "|Action=RotatePreferredDirection");
                _preferredDirection =
                    (_preferredDirection + 3) % 8;
                _lastSpatialLoopRecoveryUtc = now;
                _loopSamples.Clear();
                return false;
            }

            _nodeIndex = escapeNode;
            _target = escapeTarget;
            _preferredDirection = escapeDirection;
            _targetStartedUtc = now;
            _meaningfulProgressUtc = now;
            _lastProgressPosition = player;
            _bestTargetDistance =
                player.DistanceF(escapeTarget);
            _lastSpatialLoopRecoveryUtc = now;
            _loopSamples.Clear();
            _nextLoopSampleUtc = now.AddSeconds(1);
            AllflameLog.Info(
                "VOYAGE_SPATIAL_LOOP_DETECTED" +
                "|LanternCounter=" +
                AllflameContext.LanternCounterCurrent + "/" +
                AllflameContext.LanternCounterMaximum +
                "|Player=" + player +
                "|Revisited=" + oldNearby.Value.Value +
                "|WindowSeconds=" +
                (now - oldNearby.Value.Key)
                    .TotalSeconds.ToString("0.0") +
                "|Travelled=" + travelled.ToString("0.0") +
                "|LoopCenter=" + loopCenter +
                "|BlockedRadius=210" +
                "|EscapeToward=" + recoveryAnchor +
                "|EscapeTarget=" + escapeTarget);

            bool moving = AllflameMovementCoordinator.MoveTowards(
                escapeTarget,
                Name + " spatial loop escape");
            AllflameLog.Info(
                "VOYAGE_SPATIAL_LOOP_ESCAPE_MOVE" +
                "|Target=" + escapeTarget +
                "|Distance=" +
                player.DistanceF(escapeTarget).ToString("0.0") +
                "|Moving=" + moving);
            return true;
        }

        private bool TryStartDetour(Vector2i player)
        {
            if (_obstacleRecoveryStartedUtc ==
                DateTime.MinValue)
            {
                _obstacleRecoveryStartedUtc =
                    DateTime.UtcNow;
                AllflameLog.Info(
                    "VOYAGE_OBSTACLE_RECOVERY_BEGIN" +
                    "|Player=" + player +
                    "|BlockedTarget=" + _target +
                    "|HardFailsafeSeconds=5");
            }

            double dx = _target.X - player.X;
            double dy = _target.Y - player.Y;
            double length = Math.Sqrt(dx * dx + dy * dy);
            if (length < 1.0)
            {
                return false;
            }

            double forwardX = dx / length;
            double forwardY = dy / length;
            double sideX = -forwardY;
            double sideY = forwardX;
            int[] sideOffsets = { 75, -75, 120, -120 };

            if (_detourAttempt < sideOffsets.Length)
            {
                if (!TryConsumeVoyageRecoveryBudget(
                        "ObstacleDetour",
                        player))
                {
                    return false;
                }
                int sideOffset = sideOffsets[_detourAttempt++];
                Vector2i candidate = new Vector2i(
                    player.X +
                    (int)Math.Round(sideX * sideOffset - forwardX * 24),
                    player.Y +
                    (int)Math.Round(sideY * sideOffset - forwardY * 24));
                Vector2i resolvedCandidate;
                Vector2i raycastHit;
                bool raycastClipped;
                if (!VoyageRollingFrontierPlanner
                        .TryResolveRaycastTarget(
                            player,
                            candidate,
                            out resolvedCandidate,
                            out raycastHit,
                            out raycastClipped) ||
                    raycastClipped)
                {
                    AllflameLog.Info(
                        "VOYAGE_OBSTACLE_DETOUR_REJECTED" +
                        "|Attempt=" + _detourAttempt +
                        "|Candidate=" + candidate +
                        "|Reason=RaycastBlocked" +
                        "|Hit=" + raycastHit +
                        "|OneCandidatePerCycle=True");
                    return true;
                }
                candidate = resolvedCandidate;
                bool moving = AllflameMovementCoordinator.MoveTowards(
                    candidate,
                    Name + " obstacle detour");
                if (!moving)
                {
                    AllflameLog.Info(
                        "VOYAGE_OBSTACLE_DETOUR_REJECTED" +
                        "|Attempt=" + _detourAttempt +
                        "|Candidate=" + candidate +
                        "|Reason=MoveRejected" +
                        "|OneCandidatePerCycle=True");
                    return true;
                }

                _detouring = true;
                _detourTarget = candidate;
                _detourProgressPosition = player;
                _detourStartedUtc = DateTime.UtcNow;
                _detourProgressUtc = DateTime.UtcNow;
                AllflameLog.Info(
                    "VOYAGE_OBSTACLE_DETOUR" +
                    "|Attempt=" + _detourAttempt +
                    "|SideOffset=" + sideOffset +
                    "|From=" + player +
                    "|BlockedTarget=" + _target +
                    "|DetourTarget=" + candidate);
                return true;
            }

            return false;
        }

        private bool RunDetour(Vector2i player)
        {
            double totalRecoverySeconds =
                (DateTime.UtcNow -
                 _obstacleRecoveryStartedUtc)
                .TotalSeconds;
            if (totalRecoverySeconds >= 5.0)
            {
                Vector2i abandonedTarget = _target;
                if (_capsuleTargetActive)
                {
                    VoyageRunState.DeferCapsuleVisit(
                        abandonedTarget,
                        "PriorityDetourFailsafe");
                    _capsuleTargetActive = false;
                    AllflameLog.Info(
                        "CAPSULE_PRIORITY_TARGET_DEFERRED" +
                        "|Target=" + abandonedTarget +
                        "|Reason=DetourFailsafe" +
                        "|Action=ResumeVoyageThenRetry");
                }
                else if (_activeTopologyRoomIndex >= 0)
                {
                    _topologyPlanner.MarkBlocked(
                        _activeTopologyRoomIndex,
                        "ObstacleFiveSecondFailsafe");
                    _activeTopologyRoomIndex = -1;
                    _activeTopologyRoomName = String.Empty;
                }
                else
                {
                    _planner.MarkBlockedRegion(
                        abandonedTarget,
                        150f);
                }
                _planner.MarkBlockedRegion(
                    _detourTarget,
                    100f);
                _nodeIndex = -1;
                _detouring = false;
                _detourAttempt = 0;
                _preferredDirection =
                    (_preferredDirection + 2) % 8;
                _targetStartedUtc = DateTime.MinValue;
                _meaningfulProgressUtc =
                    DateTime.MinValue;
                _bestTargetDistance =
                    Single.MaxValue;
                _obstacleRecoveryStartedUtc =
                    DateTime.MinValue;
                AllflameMovementCoordinator.AdvanceNavigation(
                    "ObstacleFiveSecondFailsafe");
                AllflameLog.Info(
                    "VOYAGE_OBSTACLE_FIVE_SECOND_FAILSAFE" +
                    "|ElapsedSeconds=" +
                    totalRecoverySeconds.ToString("0.0") +
                    "|AbandonedTarget=" +
                    abandonedTarget +
                    "|BlockedRadius=150" +
                    "|Action=SelectUnvisitedRollingFrontier");
                return true;
            }

            float distance = player.DistanceF(_detourTarget);
            bool reached = distance <= 35f;
            bool timedOut =
                DateTime.UtcNow - _detourProgressUtc >=
                TimeSpan.FromSeconds(1);
            bool progressed =
                player.DistanceF(_detourProgressPosition) >= 8f;
            if (progressed)
            {
                _detourProgressPosition = player;
                _detourProgressUtc = DateTime.UtcNow;
            }

            if (reached)
            {
                _detouring = false;
                _targetStartedUtc = DateTime.UtcNow;
                _meaningfulProgressUtc = DateTime.UtcNow;
                _bestTargetDistance = player.DistanceF(_target);
                AllflameLog.Info(
                    "VOYAGE_OBSTACLE_DETOUR_COMPLETE" +
                    "|At=" + player +
                    "|ResumeTarget=" + _target);
                return true;
            }

            string movementContext =
                _capsuleTargetActive
                    ? Name + " Capsule extraction priority obstacle detour"
                    : Name + " obstacle detour";
            bool moving = AllflameMovementCoordinator.MoveTowards(
                _detourTarget,
                movementContext);
            if (timedOut || !moving)
            {
                _detouring = false;
                AllflameLog.Info(
                    "VOYAGE_OBSTACLE_DETOUR_FAILED" +
                    "|Attempt=" + _detourAttempt +
                    "|Target=" + _detourTarget +
                    "|TimedOut=" + timedOut +
                    "|Moving=" + moving);
                if (!TryStartDetour(player))
                {
                    AllflameMovementCoordinator.AdvanceNavigation(
                        "DetourCandidatesExhausted");
                    _meaningfulProgressUtc =
                        DateTime.UtcNow.AddSeconds(-4);
                }
                return true;
            }

            AllflameLog.Throttled(
                "voyage_obstacle_detour_move",
                TimeSpan.FromSeconds(1),
                "VOYAGE_OBSTACLE_DETOUR_MOVE" +
                "|Attempt=" + _detourAttempt +
                "|Target=" + _detourTarget +
                "|Distance=" + distance.ToString("0.0") +
                "|Moving=True");
            return true;
        }

        private void ResetActiveNavigation()
        {
            _topologyPlanner.Release(_activeTopologyRoomIndex);
            _activeTopologyRoomIndex = -1;
            _activeTopologyRoomName = String.Empty;
            _nodeIndex = -1;
            _capsuleTargetActive = false;
            _detouring = false;
            _detourAttempt = 0;
            _targetStartedUtc = DateTime.MinValue;
            _meaningfulProgressUtc = DateTime.MinValue;
            _bestTargetDistance = Single.MaxValue;
            _obstacleRecoveryStartedUtc =
                DateTime.MinValue;
        }

        private void ResetPlanner()
        {
            _planner.Reset(
                _areaHash,
                _sectorCenter,
                AllflameSettings.Instance.VoyageFrontierSpacing);
            ResetSpatialLoopTracking();
            ResetActiveNavigation();
            AllflameLog.Info(
                "VOYAGE_SECTOR_BEGIN|Sector=" + _sector +
                "|Center=" + _sectorCenter +
                "|Spacing=" +
                AllflameSettings.Instance.VoyageFrontierSpacing);
        }

        private void ResetSpatialLoopTracking()
        {
            _loopSamples.Clear();
            _nextLoopSampleUtc = DateTime.MinValue;
            _lastSpatialLoopRecoveryUtc = DateTime.MinValue;
            _lastLoopLanternCounter = -1;
            _lastLanternProgressUtc = DateTime.MinValue;
        }
    }

    internal sealed class ExploreEncounterTask : ObserverTask
    {
        private Vector2i _fallbackDestination;
        private bool _hasFallbackDestination;
        private DateTime _fallbackDeadlineUtc = DateTime.MinValue;
        private DateTime _nextLanternFallbackUtc = DateTime.MinValue;
        private string _fallbackReason = "DeepwaterPatrol";
        private uint _pathfinderAreaHash;
        private DateTime _pathfinderReadyUtc = DateTime.MinValue;
        private DateTime _nextRecoveryReloadUtc = DateTime.MinValue;
        private DateTime _nextDirectStepUtc = DateTime.MinValue;
        private int _directStepSequence;
        private int _consecutivePathFailures;
        private Vector2i _fallbackProgressPosition;
        private DateTime _fallbackProgressUtc = DateTime.MinValue;
        private Vector2i _patrolCenter;
        private bool _hasPatrolCenter;
        private uint _patrolAreaHash;
        private int _cardinalLeg;
        private int _activeDirection = -1;
        private int _blockedDirection = -1;
        private DateTime _blockedDirectionUntilUtc = DateTime.MinValue;
        private int _terrainCollisionStreak;
        private bool _returningToSpawn;
        private DateTime _pathRecoveryStartedUtc = DateTime.MinValue;
        private readonly HashSet<int> _visitedSpawnDirections =
            new HashSet<int>();
        private readonly HybridLayoutFrontierPlanner _layoutPlanner =
            new HybridLayoutFrontierPlanner();
        private readonly ChartTerrainFrontierPlanner _terrainPlanner =
            new ChartTerrainFrontierPlanner();
        private readonly TopologyRoomRoutePlanner _topologyPlanner =
            new TopologyRoomRoutePlanner();
        private int _activeFrontierIndex = -1;
        private int _activeTerrainIndex = -1;
        private DateTime _terrainSnapshotUtc = DateTime.MinValue;
        private int _activeTopologyRoomIndex = -1;
        private string _activeTopologyRoomName = String.Empty;
        private int _observedLootSessionRevision = -1;
        private bool _exploreTargetLogged;

        public ExploreEncounterTask()
            : base("ExploreEncounterTask", "Explores all reachable Chart Area tiles.") { }

        public override void Start()
        {
            ResetFallback();
        }

        public override void Stop()
        {
            ResetFallback();
        }

        public override void Tick()
        {
            if (AllflameContext.IsChartMapArea)
            {
                AllflameRunState.SetExplorationPercent(
                    Math.Min(99f, AllflameRunState.OutwardBreadcrumbCount * 2f));
            }
        }

        public override Task<bool> Run()
        {
            if (!AllflameContext.IsChartMapArea ||
                !AllflameSettings.Instance.ExploreWholeChart ||
                AllflameRunState.LanternsExhausted)
            {
                return Task.FromResult(false);
            }

            if (!EnsureChartPathfinder())
            {
                return Task.FromResult(true);
            }

            EnsurePatrolCenter();
            ObserveChartTerrain();
            HandleLootToExploreHandoff();
            if (AllflameRunState.ExplorationTargetReached &&
                !_exploreTargetLogged)
            {
                _exploreTargetLogged = true;
                AllflameLog.Info(
                    "EXPLORE_TARGET_REACHED|Target=" +
                    AllflameSettings.Instance.ChartExplorePercent +
                    "|Actual=" +
                    AllflameRunState.ExplorationPercent.ToString("0.0") +
                    "|Action=ExtendedLanternSweep" +
                    "|ReturnRequiresConfirmedEmptyCounter=True");
            }
            _fallbackReason = "DeepwaterPatrol";
            return Task.FromResult(RunPathfindingFallback());
        }

        private bool RunPathfindingFallback()
        {
            Vector2i player = LokiPoe.Me.Position;
            EnforcePathRecoveryDeadline(player);
            float targetArrivalRadius =
                _activeTopologyRoomIndex >= 0 ? 55f : 18f;
            if (_hasFallbackDestination &&
                player.DistanceF(_fallbackDestination) >
                    targetArrivalRadius &&
                DateTime.UtcNow < _fallbackDeadlineUtc)
            {
                if (_fallbackProgressUtc == DateTime.MinValue ||
                    player.Distance(_fallbackProgressPosition) >= 8)
                {
                    _fallbackProgressPosition = player;
                    _fallbackProgressUtc = DateTime.UtcNow;
                    MarkPathProgress();
                }
                else if (DateTime.UtcNow - _fallbackProgressUtc >=
                         TimeSpan.FromMilliseconds(800))
                {
                    AllflameLog.Throttled(
                        "chart_edge_stall",
                        TimeSpan.FromSeconds(1),
                        "CHART_EDGE_AVOIDANCE|Action=AbandonProbe" +
                        "|Player=" + player +
                        "|BlockedDestination=" +
                        _fallbackDestination);
                    _hasFallbackDestination = false;
                    MarkActiveExplorationTargetBlocked("NoProgress");
                    RegisterTerrainCollision(
                        "NoProgress",
                        player,
                        _fallbackDestination);
                    _consecutivePathFailures++;
                }

                if (!_hasFallbackDestination)
                {
                    // Select a different angle during this same bot tick.
                }
                else
                {
                bool continuing = AllflameMovementCoordinator.MoveTowards(
                    _fallbackDestination,
                    Name + " fallback");
                if (continuing)
                {
                    _consecutivePathFailures = 0;
                    MaybePressLanternFallback();
                    LogFallback(continuing);
                    return true;
                }

                _hasFallbackDestination = false;
                MarkActiveExplorationTargetBlocked(
                    "MoveTowardsRejected");
                RegisterTerrainCollision(
                    "MoveTowardsRejected",
                    player,
                    _fallbackDestination);
                }
            }
            else if (_hasFallbackDestination)
            {
                // Reaching a spoke, its center return, or its short deadline
                // advances the patrol instead of repeatedly pushing the edge.
                bool reachedTarget =
                    player.DistanceF(_fallbackDestination) <=
                    targetArrivalRadius;
                _hasFallbackDestination = false;
                if (reachedTarget)
                {
                    MarkActiveExplorationTargetReached(player);
                }
                else
                {
                    MarkActiveExplorationTargetBlocked(
                        "MovementDeadline");
                }
                AdvanceCardinalLeg();
            }

            _hasFallbackDestination = false;
            if (_returningToSpawn)
            {
                return RunReturnToSpawn(player);
            }

            // Grow an outward-only frontier from the immutable Chart spawn.
            // We never intentionally route through the center or target a
            // placed Lantern while the counter is still above zero.
            for (int attempt = 0; attempt < 2; attempt++)
            {
                int selectedDirection;
                Vector2i candidate =
                    GetOutwardDestination(
                        player,
                        out selectedDirection);
                if (player.Distance(candidate) <= 18)
                {
                    MarkActiveExplorationTargetReached(player);
                    AdvanceCardinalLeg();
                    continue;
                }

                bool moving = AllflameMovementCoordinator.MoveTowards(
                    candidate,
                    Name + " cardinal patrol");
                if (!moving)
                {
                    MarkActiveExplorationTargetBlocked("PathRejected");
                    _activeDirection = selectedDirection;
                    RegisterTerrainCollision(
                        "PathRejected",
                        player,
                        candidate);
                    if (_returningToSpawn)
                    {
                        return RunReturnToSpawn(player);
                    }
                    continue;
                }

                _activeDirection = selectedDirection;
                _fallbackDestination = candidate;
                _hasFallbackDestination = true;
                _fallbackDeadlineUtc =
                    _activeTopologyRoomIndex >= 0
                        ? DateTime.UtcNow.AddSeconds(
                            Math.Max(
                                5.0,
                                Math.Min(
                                    15.0,
                                    player.DistanceF(candidate) /
                                        80.0)))
                        : DateTime.UtcNow.AddMilliseconds(3000);
                _fallbackProgressPosition = player;
                _fallbackProgressUtc = DateTime.UtcNow;
                _consecutivePathFailures = 0;
                if (player.Distance(_patrolCenter) <= 35)
                {
                    _visitedSpawnDirections.Add(selectedDirection);
                }
                MaybePressLanternFallback();
                LogFallback(true);
                return true;
            }

            _consecutivePathFailures++;
            if (_consecutivePathFailures >= 6)
            {
                TryRecoveryReload();
                if (TryDirectStep(player))
                {
                    return true;
                }
            }

            AllflameLog.Throttled(
                "chart_explore_fallback_failed",
                TimeSpan.FromSeconds(3),
                "ACTION|Task=" + Name +
                "|Action=Explore|Mode=PathfindingFallback|Result=NoReachableProbe" +
                "|Player=" + player +
                "|Percent=" + AllflameRunState.ExplorationPercent.ToString("0.0"));
            return false;
        }

        private void EnsurePatrolCenter()
        {
            uint areaHash = AllflameContext.AreaHash;
            if (_hasPatrolCenter &&
                _patrolAreaHash == areaHash)
            {
                return;
            }

            _patrolCenter =
                AllflameRunState.HasChartSpawnPosition
                    ? AllflameRunState.ChartSpawnPosition
                    : LokiPoe.Me.Position;
            _hasPatrolCenter = true;
            _patrolAreaHash = areaHash;
            _cardinalLeg = 0;
            _activeDirection = -1;
            _blockedDirection = -1;
            _blockedDirectionUntilUtc = DateTime.MinValue;
            _terrainCollisionStreak = 0;
            _returningToSpawn = false;
            _pathRecoveryStartedUtc = DateTime.MinValue;
            _visitedSpawnDirections.Clear();
            _layoutPlanner.Reset(
                areaHash,
                _patrolCenter,
                AllflameSettings.Instance.LayoutFrontierStep);
            _terrainPlanner.Reset(areaHash);
            _terrainSnapshotUtc = DateTime.MinValue;
            _topologyPlanner.Reset(areaHash);
            _activeFrontierIndex = -1;
            _activeTerrainIndex = -1;
            _activeTopologyRoomIndex = -1;
            _activeTopologyRoomName = String.Empty;
            AllflameLog.Info(
                "CARDINAL_PATROL_START|Center=" + _patrolCenter +
                "|AreaHash=" + areaHash +
                "|Pattern=FourBranchCardinalFrontier" +
                "|ReturnToCenterOnTerrainCollision=True" +
                "|AvoidPlacedLanterns=True");
        }

        private void ObserveChartTerrain()
        {
            uint areaHash = AllflameContext.AreaHash;
            Vector2i player = LokiPoe.Me.Position;
            AreaMapSnapshotService.Observe(
                areaHash,
                AllflameContext.AreaId,
                player,
                AllflameMovementCoordinator.NavigationRevision,
                "Chart");

            AreaMapSnapshot snapshot =
                AreaMapSnapshotService.Current;
            if (snapshot == null || snapshot.AreaHash != areaHash)
            {
                AllflameLog.Throttled(
                    "chart_terrain_snapshot_wait",
                    TimeSpan.FromSeconds(3),
                    "CHART_TERRAIN_WAIT" +
                    "|AreaHash=" + areaHash +
                    "|Player=" + player +
                    "|Action=UseExistingFrontier");
                return;
            }

            AllflameLog.Throttled(
                "chart_terrain_heartbeat",
                TimeSpan.FromSeconds(3),
                "CHART_TERRAIN_HEARTBEAT" +
                "|AreaHash=" + snapshot.AreaHash +
                "|Rows=" + snapshot.Rows +
                "|Cols=" + snapshot.Cols +
                "|Walkable=" + snapshot.WalkableCells +
                "|TerrainCells=" + snapshot.TerrainCells +
                "|DataLength=" + snapshot.DataLength +
                "|PlannerReady=" +
                _terrainPlanner.IsReady(areaHash) +
                "|Fallback=HybridLayoutFrontier");
        }

        private Vector2i GetOutwardDestination(
            Vector2i player,
            out int selectedDirection)
        {
            selectedDirection = -1;
            Vector2i topologyTarget;
            string topologyRoomName;
            if (_topologyPlanner.TrySelect(
                    player,
                    out _activeTopologyRoomIndex,
                    out topologyTarget,
                    out topologyRoomName))
            {
                _activeFrontierIndex = -1;
                _activeTopologyRoomName = topologyRoomName;
                AllflameLog.Info(
                    "TOPOLOGY_ROOM_SELECTED" +
                    "|Mode=Chart" +
                    "|Index=" + _activeTopologyRoomIndex +
                    "|Name=" + _activeTopologyRoomName +
                    "|From=" + player +
                    "|Target=" + topologyTarget +
                    "|Distance=" +
                    player.DistanceF(topologyTarget).ToString("0.0") +
                    "|ChestPreemption=True" +
                    "|Fallback=HybridLayoutFrontier");
                return topologyTarget;
            }

            AreaMapSnapshot terrain =
                AreaMapSnapshotService.Current;
            if (terrain != null &&
                terrain.AreaHash == AllflameContext.AreaHash &&
                (_terrainSnapshotUtc != terrain.CreatedUtc ||
                 !_terrainPlanner.IsBuilt(AllflameContext.AreaHash)))
            {
                _terrainPlanner.Reset(terrain.AreaHash);
                _terrainPlanner.Build(
                    terrain,
                    _patrolCenter,
                    AllflameSettings.Instance.LayoutFrontierStep);
                _terrainSnapshotUtc = terrain.CreatedUtc;
            }

            Vector2i terrainTarget;
            int terrainIndex;
            if (_terrainPlanner.TrySelect(
                    player,
                    out terrainIndex,
                    out terrainTarget))
            {
                _activeTerrainIndex = terrainIndex;
                _activeFrontierIndex = -1;
                _activeTopologyRoomIndex = -1;
                AllflameLog.Throttled(
                    "chart_terrain_target",
                    TimeSpan.FromSeconds(1),
                    "CHART_TERRAIN_TARGET" +
                    "|From=" + player +
                    "|To=" + terrainTarget +
                    "|Distance=" +
                    player.DistanceF(terrainTarget).ToString("0.0") +
                    "|CapsulePriority=True" +
                    "|Fallback=HybridLayoutFrontier");
                return terrainTarget;
            }

            if (AllflameSettings.Instance.EnableHybridLayoutPlanner &&
                _layoutPlanner.IsReady(AllflameContext.AreaHash))
            {
                bool escapingCompletedChestArea =
                    AllflameChestRoute.IsInsideCompletedArea(
                        player,
                        120);
                Vector2i layoutTarget;
                int nodeIndex;
                if (_layoutPlanner.TrySelect(
                    player,
                    _cardinalLeg % 4,
                    escapingCompletedChestArea,
                    out nodeIndex,
                    out selectedDirection,
                    out layoutTarget))
                {
                    _activeTopologyRoomIndex = -1;
                    _activeTopologyRoomName = String.Empty;
                    _activeFrontierIndex = nodeIndex;
                    AllflameLog.Throttled(
                        "layout_frontier_target",
                        TimeSpan.FromSeconds(1),
                        "LAYOUT_FRONTIER_TARGET" +
                        "|From=" + player +
                        "|To=" + layoutTarget +
                        "|Direction=" + selectedDirection +
                        "|EscapeCompletedChestArea=" +
                        escapingCompletedChestArea +
                        "|DynamicChestPreemption=True");
                    return layoutTarget;
                }
            }

            bool extendedSweep =
                AllflameRunState.ExplorationTargetReached ||
                AllflameRunState.LanternSearchRecovery;
            int step = extendedSweep ? 120 : 95;
            double currentRadius =
                player.Distance(_patrolCenter);
            var candidates = new List<KeyValuePair<Vector2i, double>>();

            for (int direction = 0; direction < 4; direction++)
            {
                if (direction == _blockedDirection &&
                    DateTime.UtcNow < _blockedDirectionUntilUtc)
                {
                    continue;
                }

                bool atSpawn =
                    player.Distance(_patrolCenter) <= 35;
                if (atSpawn &&
                    _visitedSpawnDirections.Count < 4 &&
                    _visitedSpawnDirections.Contains(direction))
                {
                    continue;
                }

                Vector2i candidate;
                switch (direction)
                {
                    case 0:
                        candidate =
                            new Vector2i(player.X + step, player.Y);
                        break;
                    case 1:
                        candidate =
                            new Vector2i(player.X, player.Y - step);
                        break;
                    case 2:
                        candidate =
                            new Vector2i(player.X - step, player.Y);
                        break;
                    default:
                        candidate =
                            new Vector2i(player.X, player.Y + step);
                        break;
                }

                double outwardGain =
                    candidate.Distance(_patrolCenter) - currentRadius;
                bool playerInsideCompletedArea =
                    AllflameChestRoute.IsInsideCompletedArea(
                        player,
                        120);
                if (outwardGain < 3 ||
                    (!playerInsideCompletedArea &&
                     AllflameChestRoute.IsInsideCompletedArea(
                        candidate,
                        120)) ||
                    AllflameRunState.IsNearPlacedLantern(
                        candidate,
                        42f))
                {
                    continue;
                }

                candidates.Add(
                    new KeyValuePair<Vector2i, double>(
                        candidate,
                        outwardGain));
            }

            if (candidates.Count == 0)
            {
                AllflameLog.Throttled(
                    "outward_frontier_blocked",
                    TimeSpan.FromSeconds(1),
                    "OUTWARD_FRONTIER_BLOCKED" +
                    "|Player=" + player +
                    "|Center=" + _patrolCenter +
                    "|Action=TryRecovery");
                return player;
            }

            List<KeyValuePair<Vector2i, double>> ordered =
                candidates
                    .OrderByDescending(candidate => candidate.Value)
                    .ThenBy(candidate => candidate.Key.X)
                    .ThenBy(candidate => candidate.Key.Y)
                    .ToList();
            int selectedIndex =
                _cardinalLeg % ordered.Count;
            Vector2i selected =
                ordered[selectedIndex].Key;
            for (int direction = 0; direction < 4; direction++)
            {
                Vector2i directionTarget;
                switch (direction)
                {
                    case 0:
                        directionTarget =
                            new Vector2i(player.X + step, player.Y);
                        break;
                    case 1:
                        directionTarget =
                            new Vector2i(player.X, player.Y - step);
                        break;
                    case 2:
                        directionTarget =
                            new Vector2i(player.X - step, player.Y);
                        break;
                    default:
                        directionTarget =
                            new Vector2i(player.X, player.Y + step);
                        break;
                }
                if (directionTarget.Equals(selected))
                {
                    selectedDirection = direction;
                    break;
                }
            }
            AllflameLog.Throttled(
                "outward_frontier_target",
                TimeSpan.FromSeconds(2),
                "OUTWARD_FRONTIER_TARGET" +
                "|From=" + player +
                "|To=" + selected +
                "|CurrentRadius=" +
                currentRadius.ToString("0.0") +
                "|TargetRadius=" +
                selected.Distance(_patrolCenter).ToString("0.0") +
                "|Direction=" + selectedDirection +
                "|StepSeconds=3");
            return selected;
        }

        private void RegisterTerrainCollision(
            string reason,
            Vector2i player,
            Vector2i blockedDestination)
        {
            _terrainCollisionStreak++;
            if (_pathRecoveryStartedUtc == DateTime.MinValue)
            {
                _pathRecoveryStartedUtc = DateTime.UtcNow;
            }
            _blockedDirection = _activeDirection;
            _blockedDirectionUntilUtc =
                DateTime.UtcNow.AddSeconds(8);
            AdvanceCardinalLeg();

            bool farFromSpawn =
                player.Distance(_patrolCenter) > 45;
            if (_terrainCollisionStreak >= 2 && farFromSpawn)
            {
                _returningToSpawn = true;
            }

            AllflameLog.Info(
                "TERRAIN_COLLISION_ROUTE_CHANGE" +
                "|Reason=" + reason +
                "|Direction=" + _blockedDirection +
                "|Streak=" + _terrainCollisionStreak +
                "|Player=" + player +
                "|BlockedDestination=" + blockedDestination +
                "|ReturnToSpawn=" + _returningToSpawn);
        }

        private bool RunReturnToSpawn(Vector2i player)
        {
            if (player.Distance(_patrolCenter) <= 24)
            {
                _returningToSpawn = false;
                _terrainCollisionStreak = 0;
                _pathRecoveryStartedUtc = DateTime.MinValue;
                _activeDirection = -1;
                _hasFallbackDestination = false;
                if (_visitedSpawnDirections.Count >= 4)
                {
                    _visitedSpawnDirections.Clear();
                }
                AllflameLog.Info(
                    "CARDINAL_CENTER_REACHED|Center=" +
                    _patrolCenter +
                    "|VisitedDirections=" +
                    _visitedSpawnDirections.Count +
                    "|Action=SelectUnusedDirection");
                return true;
            }

            bool moving = AllflameMovementCoordinator.MoveTowards(
                _patrolCenter,
                Name + " return to Chart spawn");
            if (!moving)
            {
                moving = TryDirectStepTo(
                    player,
                    _patrolCenter,
                    false,
                    "ReturnToSpawn");
            }
            AllflameLog.Throttled(
                "cardinal_return_to_spawn",
                TimeSpan.FromSeconds(1),
                "CARDINAL_RETURN_TO_SPAWN" +
                "|Player=" + player +
                "|Center=" + _patrolCenter +
                "|Distance=" +
                player.Distance(_patrolCenter).ToString("0.0") +
                "|Moving=" + moving);
            return true;
        }

        private void EnforcePathRecoveryDeadline(Vector2i player)
        {
            if (_pathRecoveryStartedUtc == DateTime.MinValue)
            {
                return;
            }

            double elapsedSeconds =
                (DateTime.UtcNow - _pathRecoveryStartedUtc)
                    .TotalSeconds;
            if (elapsedSeconds >= 15)
            {
                TryRecoveryReload();
                // Keep the recovery active until RunReturnToSpawn confirms
                // that the player reached the center and clears the recovery
                // timer. Deriving this flag from the current distance skipped
                // that cleanup when the hard-deadline reload landed inside the
                // center radius, leaving _pathRecoveryStartedUtc stuck forever.
                _returningToSpawn = true;
                _hasFallbackDestination = false;
                _blockedDirectionUntilUtc =
                    DateTime.UtcNow.AddSeconds(15);
                AllflameLog.Throttled(
                    "path_recovery_hard_deadline",
                    TimeSpan.FromSeconds(2),
                    "PATH_RECOVERY_DEADLINE" +
                    "|ElapsedSeconds=" +
                    elapsedSeconds.ToString("0.0") +
                    "|TargetSeconds=7" +
                    "|MaximumSeconds=15" +
                    "|Action=ReloadAndReturnToSpawn" +
                    "|Player=" + player);
                return;
            }

            if (elapsedSeconds >= 7 &&
                player.Distance(_patrolCenter) > 45)
            {
                _returningToSpawn = true;
                _hasFallbackDestination = false;
                AllflameLog.Throttled(
                    "path_recovery_target_deadline",
                    TimeSpan.FromSeconds(2),
                    "PATH_RECOVERY_TARGET" +
                    "|ElapsedSeconds=" +
                    elapsedSeconds.ToString("0.0") +
                    "|TargetSeconds=7" +
                    "|Action=ReturnToSpawnAndChangeBranch");
            }
        }

        private void MarkPathProgress()
        {
            if (_pathRecoveryStartedUtc == DateTime.MinValue)
            {
                return;
            }

            double elapsedSeconds =
                (DateTime.UtcNow - _pathRecoveryStartedUtc)
                    .TotalSeconds;
            AllflameLog.Info(
                "PATH_RECOVERY_RESOLVED" +
                "|ElapsedSeconds=" +
                elapsedSeconds.ToString("0.0") +
                "|TargetSeconds=7" +
                "|MaximumSeconds=15");
            _pathRecoveryStartedUtc = DateTime.MinValue;
            _terrainCollisionStreak = 0;
        }

        private void AdvanceCardinalLeg()
        {
            _cardinalLeg++;
        }

        private void LogFallback(bool moving)
        {
            AllflameLog.Throttled(
                "chart_explore_fallback",
                TimeSpan.FromSeconds(3),
                "ACTION|Task=" + Name +
                "|Action=Explore|Mode=PathfindingFallback" +
                "|Reason=" + _fallbackReason +
                "|Destination=" + _fallbackDestination +
                "|Percent=" + AllflameRunState.ExplorationPercent.ToString("0.0") +
                "|Moving=" + moving);
        }

        private void ResetFallback()
        {
            _hasFallbackDestination = false;
            _fallbackDeadlineUtc = DateTime.MinValue;
            _nextLanternFallbackUtc = DateTime.MinValue;
            _fallbackReason = "DeepwaterPatrol";
            _pathfinderAreaHash = 0;
            _pathfinderReadyUtc = DateTime.MinValue;
            _nextRecoveryReloadUtc = DateTime.MinValue;
            _nextDirectStepUtc = DateTime.MinValue;
            _directStepSequence = 0;
            _consecutivePathFailures = 0;
            _fallbackProgressPosition = default(Vector2i);
            _fallbackProgressUtc = DateTime.MinValue;
            _patrolCenter = default(Vector2i);
            _hasPatrolCenter = false;
            _patrolAreaHash = 0;
            _cardinalLeg = 0;
            _activeDirection = -1;
            _blockedDirection = -1;
            _blockedDirectionUntilUtc = DateTime.MinValue;
            _terrainCollisionStreak = 0;
            _returningToSpawn = false;
            _pathRecoveryStartedUtc = DateTime.MinValue;
            _visitedSpawnDirections.Clear();
            _activeFrontierIndex = -1;
            _activeTerrainIndex = -1;
            _terrainSnapshotUtc = DateTime.MinValue;
            _terrainPlanner.Reset(0);
            _topologyPlanner.Reset(0);
            _activeTopologyRoomIndex = -1;
            _activeTopologyRoomName = String.Empty;
            _observedLootSessionRevision = -1;
            _exploreTargetLogged = false;
        }

        private void MarkActiveExplorationTargetReached(
            Vector2i player)
        {
            if (_activeTopologyRoomIndex >= 0)
            {
                AllflameLog.Info(
                    "TOPOLOGY_ROOM_REACHED" +
                    "|Mode=Chart" +
                    "|Index=" + _activeTopologyRoomIndex +
                    "|Name=" + _activeTopologyRoomName +
                    "|Target=" + _fallbackDestination +
                    "|Distance=" +
                    player.DistanceF(_fallbackDestination)
                        .ToString("0.0") +
                    "|Action=ResumeTopologyOrFrontier");
                _topologyPlanner.MarkReached(
                    _activeTopologyRoomIndex);
                _activeTopologyRoomIndex = -1;
                _activeTopologyRoomName = String.Empty;
            }
            else if (_activeTerrainIndex >= 0)
            {
                _terrainPlanner.MarkReached(_activeTerrainIndex);
                _activeTerrainIndex = -1;
                AllflameLog.Info(
                    "CHART_TERRAIN_TARGET_REACHED" +
                    "|Target=" + _fallbackDestination +
                    "|Action=SelectNextTerrainTarget");
            }
            else
            {
                _layoutPlanner.MarkReached(
                    _activeFrontierIndex);
            }
            _activeFrontierIndex = -1;
        }

        private void MarkActiveExplorationTargetBlocked(
            string reason)
        {
            if (_activeTopologyRoomIndex >= 0)
            {
                _topologyPlanner.MarkBlocked(
                    _activeTopologyRoomIndex,
                    reason);
                _activeTopologyRoomIndex = -1;
                _activeTopologyRoomName = String.Empty;
            }
            else if (_activeTerrainIndex >= 0)
            {
                _terrainPlanner.MarkBlocked(_activeTerrainIndex);
                _activeTerrainIndex = -1;
                AllflameLog.Info(
                    "CHART_TERRAIN_TARGET_BLOCKED" +
                    "|Reason=" + reason +
                    "|Action=SelectAnotherTerrainTarget");
            }
            else
            {
                _layoutPlanner.MarkBlocked(
                    _activeFrontierIndex);
            }
            _activeFrontierIndex = -1;
        }

        private void ReleaseActiveExplorationTarget()
        {
            _topologyPlanner.Release(
                _activeTopologyRoomIndex);
            _activeTopologyRoomIndex = -1;
            _activeTopologyRoomName = String.Empty;
            _terrainPlanner.Release(_activeTerrainIndex);
            _activeTerrainIndex = -1;
            _layoutPlanner.Release(
                _activeFrontierIndex);
            _activeFrontierIndex = -1;
        }

        private void HandleLootToExploreHandoff()
        {
            int revision = AllflameLootState.SessionRevision;
            if (revision == _observedLootSessionRevision ||
                AllflameLootState.IsActive)
            {
                return;
            }

            _observedLootSessionRevision = revision;
            _hasFallbackDestination = false;
            ReleaseActiveExplorationTarget();
            _returningToSpawn = false;
            _terrainCollisionStreak = 0;
            _pathRecoveryStartedUtc = DateTime.MinValue;
            _fallbackProgressUtc = DateTime.MinValue;
            AdvanceCardinalLeg();
            AllflameLog.Info(
                "LOOT_TO_EXPLORE_HANDOFF" +
                "|SessionRevision=" + revision +
                "|Action=ReleaseOldTargetAndSelectEscapeFrontier");
        }

        private void MaybePressLanternFallback()
        {
            if (!AllflameSettings.Instance.UseVForLantern ||
                AllflameContext.GoldenLanternAvailable ||
                AllflameRunState.PreserveLastLanternForChestWork ||
                DateTime.UtcNow < _nextLanternFallbackUtc)
            {
                return;
            }

            LokiPoe.Input.SimulateKeyEvent('v');
            _nextLanternFallbackUtc =
                DateTime.UtcNow.AddMilliseconds(1400);
            AllflameLog.Throttled(
                "lantern_v_patrol",
                TimeSpan.FromSeconds(3),
                "LANTERN_V_FALLBACK|Phase=OutwardPatrol|Pressed=True");
        }

        private bool EnsureChartPathfinder()
        {
            uint areaHash = AllflameContext.AreaHash;
            if (areaHash == 0)
            {
                return false;
            }

            if (_pathfinderAreaHash != areaHash)
            {
                uint previousHash = 0;
                try
                {
                    previousHash = ExilePather.AreaHash;
                    if (previousHash == areaHash)
                    {
                        _pathfinderAreaHash = areaHash;
                        _pathfinderReadyUtc = DateTime.UtcNow;
                        _nextRecoveryReloadUtc =
                            DateTime.UtcNow.AddSeconds(5);
                        _consecutivePathFailures = 0;
                        AllflameLog.Info(
                            "PATHFINDER_AREA_READY" +
                            "|Reason=LoadedByEarlierTask" +
                            "|ChartHash=" + areaHash +
                            "|LoadedHash=" + previousHash);
                        return true;
                    }
                    ExilePather.Reload(true);
                    _pathfinderAreaHash = areaHash;
                    _pathfinderReadyUtc =
                        DateTime.UtcNow.AddMilliseconds(250);
                    _nextRecoveryReloadUtc =
                        DateTime.UtcNow.AddSeconds(5);
                    _consecutivePathFailures = 0;
                    AllflameLog.Info(
                        "PATHFINDER_AREA_RELOAD|Reason=ChartAreaChanged" +
                        "|PreviousHash=" + previousHash +
                        "|ChartHash=" + areaHash +
                        "|LoadedHash=" + ExilePather.AreaHash);
                }
                catch (Exception ex)
                {
                    _pathfinderAreaHash = areaHash;
                    _pathfinderReadyUtc = DateTime.UtcNow;
                    AllflameLog.Info(
                        "PATHFINDER_AREA_RELOAD_FAILED|" +
                        ex.GetType().Name + "|" +
                        ex.Message.Replace("|", "/"));
                }
                return false;
            }

            return DateTime.UtcNow >= _pathfinderReadyUtc;
        }

        private void TryRecoveryReload()
        {
            if (DateTime.UtcNow < _nextRecoveryReloadUtc)
            {
                return;
            }

            _nextRecoveryReloadUtc = DateTime.UtcNow.AddSeconds(5);
            try
            {
                ExilePather.Reload(true);
                AllflameLog.Info(
                    "PATHFINDER_AREA_RELOAD|Reason=RepeatedPathFailures" +
                    "|Failures=" + _consecutivePathFailures +
                    "|ChartHash=" + AllflameContext.AreaHash +
                    "|LoadedHash=" + ExilePather.AreaHash);
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "PATHFINDER_AREA_RELOAD_FAILED|Reason=Recovery|" +
                    ex.GetType().Name + "|" +
                    ex.Message.Replace("|", "/"));
            }
        }

        private bool TryDirectStep(Vector2i player)
        {
            if (DateTime.UtcNow < _nextDirectStepUtc)
            {
                return true;
            }

            var moveSkill =
                LokiPoe.InGameState.SkillBarHud.LastBoundMoveSkill;
            if (moveSkill == null ||
                moveSkill.Slots == null ||
                !moveSkill.Slots.Any())
            {
                AllflameLog.Throttled(
                    "direct_step_skill_missing",
                    TimeSpan.FromSeconds(3),
                    "DIRECT_STEP_FAILED|Reason=MoveSkillMissing");
                return false;
            }

            int selectedDirection;
            Vector2i outwardTarget =
                GetOutwardDestination(
                    player,
                    out selectedDirection);
            _activeDirection = selectedDirection;
            return TryDirectStepTo(
                player,
                outwardTarget,
                true,
                "PathfinderUnavailable");
        }

        private bool TryDirectStepTo(
            Vector2i player,
            Vector2i target,
            bool allowLanternFallback,
            string reason)
        {
            var moveSkill =
                LokiPoe.InGameState.SkillBarHud.LastBoundMoveSkill;
            if (moveSkill == null ||
                moveSkill.Slots == null ||
                !moveSkill.Slots.Any())
            {
                return false;
            }

            int deltaX = target.X - player.X;
            int deltaY = target.Y - player.Y;
            double length =
                Math.Sqrt(
                    (double)deltaX * deltaX +
                    (double)deltaY * deltaY);
            if (length < 1)
            {
                return false;
            }
            Vector2i destination = new Vector2i(
                player.X + (int)Math.Round(deltaX / length * 34),
                player.Y + (int)Math.Round(deltaY / length * 34));

            int moveSlot = moveSkill.Slots.Last();
            if (!LokiPoe.InGameState.SkillBarHud.CanUse(moveSlot))
            {
                _nextDirectStepUtc =
                    DateTime.UtcNow.AddMilliseconds(125);
                AllflameLog.Throttled(
                    "direct_step_skill_not_ready",
                    TimeSpan.FromSeconds(2),
                    "DIRECT_STEP_WAIT|Reason=MoveSkillNotReady" +
                    "|Slot=" + moveSlot +
                    "|Skill=" + moveSkill.Name);
                return true;
            }

            LokiPoe.InGameState.SkillBarHud.BeginUseAt(
                moveSlot,
                false,
                destination);
            _nextDirectStepUtc =
                DateTime.UtcNow.AddMilliseconds(750);
            if (allowLanternFallback)
            {
                MaybePressLanternFallback();
            }
            AllflameLog.Throttled(
                "direct_step",
                TimeSpan.FromSeconds(2),
                "DIRECT_STEP|Reason=" + reason +
                "|Destination=" + destination +
                "|Direction=" + _directStepSequence +
                "|Failures=" + _consecutivePathFailures);
            return true;
        }
    }

    internal sealed class VisitAllflameCapsuleTask : ObserverTask
    {
        private uint _areaHash;
        private bool _hasTarget;
        private Vector2i _target;
        private float _bestDistance = Single.MaxValue;
        private DateTime _targetStartedUtc = DateTime.MinValue;
        private DateTime _lastProgressUtc = DateTime.MinValue;

        public VisitAllflameCapsuleTask()
            : base(
                "VisitAllflameCapsuleTask",
                "Passes discovered Allflame Capsules while Lanterns remain.") { }

        public override Task<bool> Run()
        {
            bool activeVoyage =
                AllflameContext.IsVoyageMapArea &&
                AllflameContext.Phase == AllflamePhase.Voyage;
            if (!activeVoyage)
            {
                Reset(0);
                return Task.FromResult(false);
            }
            if (_areaHash != AllflameContext.AreaHash)
            {
                Reset(AllflameContext.AreaHash);
            }

            // Task ordering makes chest movement/opening and required loot the
            // only work allowed to preempt a proactive Capsule visit.
            bool securingExit =
                VoyageRunState.ExitCapsuleSecuringRequired;
            if (VoyageRunState.LanternsExhausted ||
                VoyageRunState.SurfaceTransferPending ||
                AllflameContext.LanternCounterMaximum <= 0 ||
                AllflameContext.LanternCounterCurrent <= 0 ||
                (AllflameChestRoute.PendingCount > 0 &&
                 !securingExit) ||
                AllflameLootState.IsActive ||
                LokiPoe.Me == null)
            {
                return Task.FromResult(false);
            }

            Vector2i player = LokiPoe.Me.Position;
            if (_hasTarget &&
                VoyageRunState.IsCapsuleTraversed(_target))
            {
                ClearTarget();
            }
            if (!_hasTarget &&
                !VoyageRunState.TryGetNearestUntraversedCapsule(
                    player,
                    out _target))
            {
                return Task.FromResult(false);
            }
            if (!_hasTarget)
            {
                _hasTarget = true;
                _bestDistance = player.DistanceF(_target);
                _targetStartedUtc = DateTime.UtcNow;
                _lastProgressUtc = DateTime.UtcNow;
                AllflameLog.Info(
                    "CAPSULE_CACHE_APPROACH" +
                    "|Position=" + _target +
                    "|Distance=" + _bestDistance.ToString("0.0") +
                    "|LanternCounter=" +
                    AllflameContext.LanternCounterCurrent + "/" +
                    AllflameContext.LanternCounterMaximum +
                    "|Priority=" +
                    (securingExit
                        ? "ExitSafetyBeforeChest"
                        : "AfterChestBeforeLantern"));
            }

            float distance = player.DistanceF(_target);
            if (distance <= VoyageRunState.CapsuleTraversalRadius)
            {
                VoyageRunState.MarkCapsuleTraversed(
                    _target,
                    "PriorityVisitTask");
                ClearTarget();
                return Task.FromResult(true);
            }

            if (_bestDistance - distance >= 6f)
            {
                _bestDistance = distance;
                _lastProgressUtc = DateTime.UtcNow;
            }
            bool timedOut =
                DateTime.UtcNow - _targetStartedUtc >=
                    TimeSpan.FromSeconds(10);
            bool stalled =
                DateTime.UtcNow - _lastProgressUtc >=
                    TimeSpan.FromSeconds(3);
            if (timedOut || stalled)
            {
                VoyageRunState.DeferCapsuleVisit(
                    _target,
                    timedOut
                        ? "VisitTimeout10Seconds"
                        : "NoProgress3Seconds");
                ClearTarget();
                return Task.FromResult(false);
            }

            bool moving = MoveTowardsInteraction(
                _target,
                Name);
            AllflameLog.Throttled(
                "capsule_priority_visit",
                TimeSpan.FromSeconds(1),
                "CAPSULE_VISIT_MOVE" +
                "|Position=" + _target +
                "|Distance=" + distance.ToString("0.0") +
                "|BestDistance=" + _bestDistance.ToString("0.0") +
                "|Moving=" + moving +
                "|PendingChests=" +
                AllflameChestRoute.PendingCount);
            return Task.FromResult(true);
        }

        private void Reset(uint areaHash)
        {
            _areaHash = areaHash;
            ClearTarget();
        }

        private void ClearTarget()
        {
            _hasTarget = false;
            _target = new Vector2i();
            _bestDistance = Single.MaxValue;
            _targetStartedUtc = DateTime.MinValue;
            _lastProgressUtc = DateTime.MinValue;
        }
    }

    internal sealed class InteractLanternTask : ObserverTask
    {
        private readonly HashSet<int> _handledLanternIds =
            new HashSet<int>();
        private uint _areaHash;
        private DateTime _nextAttemptUtc = DateTime.MinValue;
        private int _approachLanternId;
        private float _approachBestDistance = Single.MaxValue;
        private DateTime _approachLastProgressUtc = DateTime.MinValue;
        private bool _awaitingPlacementPostcondition;
        private int _placementCounterBefore = -1;
        private int _placementCountBefore = -1;
        private int _placementLanternId;
        private DateTime _placementPostconditionDeadlineUtc =
            DateTime.MinValue;

        public InteractLanternTask()
            : base("InteractLanternTask", "Would interact with a targetable Golden Lantern.") { }

        public override async Task<bool> Run()
        {
            bool chart =
                AllflameContext.IsChartMapArea;
            bool voyage =
                AllflameContext.IsVoyageMapArea &&
                AllflameContext.Phase == AllflamePhase.Voyage;
            if (!chart && !voyage)
            {
                _handledLanternIds.Clear();
                _areaHash = 0;
                ResetApproach();
                ResetPlacementWait();
                return false;
            }

            if (_areaHash != AllflameContext.AreaHash)
            {
                _handledLanternIds.Clear();
                _areaHash = AllflameContext.AreaHash;
                _nextAttemptUtc = DateTime.MinValue;
                ResetApproach();
                ResetPlacementWait();
            }

            if (!_awaitingPlacementPostcondition &&
                ((chart && AllflameRunState.LanternsExhausted) ||
                 (voyage && VoyageRunState.LanternsExhausted) ||
                 (AllflameContext.LanternCounterMaximum > 0 &&
                  AllflameContext.LanternCounterCurrent <= 0) ||
                 (voyage &&
                  VoyageRunState.SurfaceTransferPending) ||
                 !AllflameContext.GoldenLanternAvailable))
            {
                return false;
            }

            if (_awaitingPlacementPostcondition)
            {
                bool counterChanged =
                    _placementCounterBefore >= 0 &&
                    AllflameContext.LanternCounterCurrent >= 0 &&
                    AllflameContext.LanternCounterCurrent <
                        _placementCounterBefore;
                bool placementChanged =
                    _placementCountBefore >= 0 &&
                    AllflameContext.PlacedLanterns >
                        _placementCountBefore;
                if (counterChanged || placementChanged)
                {
                    AllflameLog.Info(
                        "LANTERN_POSTCONDITION_CONFIRMED" +
                        "|LanternId=" + _placementLanternId +
                        "|CounterBefore=" + _placementCounterBefore +
                        "|CounterAfter=" +
                        AllflameContext.LanternCounterCurrent +
                        "|PlacedBefore=" + _placementCountBefore +
                        "|PlacedAfter=" +
                        AllflameContext.PlacedLanterns +
                        "|Confirmation=" +
                        (counterChanged ? "Counter" : "PlacedLantern") +
                        "|Action=AllowNextPlacement");
                    ResetPlacementWait();
                    _nextAttemptUtc = DateTime.MinValue;
                }
                else if (DateTime.UtcNow <
                         _placementPostconditionDeadlineUtc)
                {
                    return true;
                }
                else
                {
                    AllflameLog.Info(
                        "LANTERN_POSTCONDITION_TIMEOUT" +
                        "|LanternId=" + _placementLanternId +
                        "|CounterBefore=" + _placementCounterBefore +
                        "|CounterAfter=" +
                        AllflameContext.LanternCounterCurrent +
                        "|PlacedBefore=" + _placementCountBefore +
                        "|PlacedAfter=" +
                        AllflameContext.PlacedLanterns +
                        "|WaitMilliseconds=2000" +
                        "|Action=ResumeAfterBoundedObservation");
                    ResetPlacementWait();
                    _nextAttemptUtc = DateTime.UtcNow.AddMilliseconds(250);
                }
            }

            if (chart &&
                AllflameRunState.PreserveLastLanternForChestWork)
            {
                AllflameLog.Throttled(
                    "last_lantern_chest_priority",
                    TimeSpan.FromSeconds(1),
                    "LAST_LANTERN_HELD" +
                    "|Counter=" +
                    AllflameContext.LanternCounterCurrent + "/" +
                    AllflameContext.LanternCounterMaximum +
                    "|PendingChests=" +
                    AllflameChestRoute.PendingCount +
                    "|LootActive=" +
                    AllflameLootState.IsActive +
                    "|Action=FinishChestWorkFirst");
                return false;
            }

            NetworkObject lantern = AllflameContext.GoldenLanternObject;
            if (lantern == null)
            {
                return false;
            }
            if (_handledLanternIds.Contains(lantern.Id))
            {
                return false;
            }
            if (AllflameRunState.IsNearPlacedLantern(
                    lantern.Position,
                    28f))
            {
                _handledLanternIds.Add(lantern.Id);
                AllflameLog.Throttled(
                    "placed_lantern_revisit_blocked_" + lantern.Id,
                    TimeSpan.FromSeconds(2),
                    "LANTERN_REVISIT_BLOCKED" +
                    "|Id=" + lantern.Id +
                    "|Position=" + lantern.Position +
                    "|CounterExhausted=False");
                return false;
            }
            if (DateTime.UtcNow < _nextAttemptUtc)
            {
                return true;
            }

            if (lantern.Distance > AllflameSettings.Instance.InteractDistance)
            {
                if (_approachLanternId != lantern.Id)
                {
                    _approachLanternId = lantern.Id;
                    _approachBestDistance = lantern.Distance;
                    _approachLastProgressUtc = DateTime.UtcNow;
                }
                else if (_approachBestDistance - lantern.Distance >= 5f)
                {
                    _approachBestDistance = lantern.Distance;
                    _approachLastProgressUtc = DateTime.UtcNow;
                }
                else if (_approachLastProgressUtc != DateTime.MinValue &&
                         DateTime.UtcNow - _approachLastProgressUtc >=
                         TimeSpan.FromSeconds(3))
                {
                    _handledLanternIds.Add(lantern.Id);
                    AllflameLog.Info(
                        "LANTERN_APPROACH_ABORTED" +
                        "|Id=" + lantern.Id +
                        "|Distance=" + lantern.Distance.ToString("0.0") +
                        "|BestDistance=" +
                        _approachBestDistance.ToString("0.0") +
                        "|Reason=NoProgress3Seconds" +
                        "|Action=ReleaseToExplorer");
                    ResetApproach();
                    return false;
                }

                bool moving =
                    AllflameMovementCoordinator.MoveTowards(
                        lantern.Position,
                        Name + " Golden Lantern");
                if (!moving &&
                    DateTime.UtcNow - _approachLastProgressUtc >=
                    TimeSpan.FromSeconds(1))
                {
                    _approachLastProgressUtc =
                        DateTime.UtcNow.AddSeconds(-3);
                }
                AllflameLog.Throttled(
                    "lantern_approach_" + lantern.Id,
                    TimeSpan.FromSeconds(1),
                    "ACTION|Task=" + Name +
                    "|Action=MoveTo|Target=Golden Lantern" +
                    "|Distance=" + lantern.Distance.ToString("0.0") +
                    "|BestDistance=" +
                    _approachBestDistance.ToString("0.0") +
                    "|Moving=" + moving);
                return true;
            }

            ResetApproach();
            _nextAttemptUtc = DateTime.UtcNow.AddMilliseconds(250);
            _placementCounterBefore =
                AllflameContext.LanternCounterCurrent;
            _placementCountBefore = AllflameContext.PlacedLanterns;
            _placementLanternId = lantern.Id;
            _placementPostconditionDeadlineUtc =
                DateTime.UtcNow.AddSeconds(2);
            _awaitingPlacementPostcondition = true;
            bool interacted = false;
            bool pressedV = false;
            if (AllflameSettings.Instance.UseVForLantern)
            {
                // V is also the league-panel hotkey. Only send it while a
                // positively observed counter proves that a Lantern charge is
                // still available. This second guard closes the race where
                // the counter reaches 0 while approaching the object.
                if (AllflameContext.LanternCounterMaximum <= 0 ||
                    AllflameContext.LanternCounterCurrent <= 0)
                {
                    AllflameLog.Throttled(
                        "lantern_v_blocked_no_charge",
                        TimeSpan.FromSeconds(2),
                        "LANTERN_V_BLOCKED" +
                        "|Counter=" +
                        AllflameContext.LanternCounterCurrent + "/" +
                        AllflameContext.LanternCounterMaximum +
                        "|LanternId=" + lantern.Id +
                        "|Reason=NoConfirmedCharge" +
                        "|Action=SkipInputAndResumeRecovery");
                    ResetPlacementWait();
                    return false;
                }
                LokiPoe.Input.SimulateKeyEvent('v');
                pressedV = true;
                // A V attempt consumes this anchor for the outward pass even
                // if the game rejects placement. Never route back to it until
                // the confirmed 0/x return phase.
                _handledLanternIds.Add(lantern.Id);
                await LokiCoroutine.Sleep(120);
            }
            else
            {
                interacted =
                    await InteractWithRecovery(lantern);
            }
            if (interacted)
            {
                _handledLanternIds.Add(lantern.Id);
            }
            // Interaction and V are attempts only. SnapshotObjects is the sole
            // authority that records a Lantern after the real object appears.
            AllflameLog.Info(
                "ACTION|Task=" + Name + "|Action=PlaceLantern|InteractSuccess=" + interacted +
                "|PressedV=" + pressedV +
                "|Handled=" + interacted);
            return true;
        }

        private void ResetApproach()
        {
            _approachLanternId = 0;
            _approachBestDistance = Single.MaxValue;
            _approachLastProgressUtc = DateTime.MinValue;
        }

        private void ResetPlacementWait()
        {
            _awaitingPlacementPostcondition = false;
            _placementCounterBefore = -1;
            _placementCountBefore = -1;
            _placementLanternId = 0;
            _placementPostconditionDeadlineUtc = DateTime.MinValue;
        }
    }

    internal sealed class MoveToDeepwaterChestTask : ObserverTask
    {
        private int _targetId;
        private int _failures;
        private float _lastDistance = Single.MaxValue;
        private DateTime _lastProgressUtc = DateTime.MinValue;
        private DateTime _arrivedWithoutObjectUtc = DateTime.MinValue;
        private uint _pathfinderAreaHash;
        private DateTime _pathfinderReadyUtc = DateTime.MinValue;
        private DateTime _nextPathFailureUtc = DateTime.MinValue;
        private int _pathfinderRecoveries;
        private int _pathfinderSetupFailures;

        public MoveToDeepwaterChestTask()
            : base("MoveToDeepwaterChestTask", "Navigates to the next configured Deepwater reward chest.") { }

        public override void Start()
        {
            ResetTarget();
            ResetPathfinder();
        }

        public override void Stop()
        {
            ResetTarget();
            ResetPathfinder();
        }

        public override Task<bool> Run()
        {
            bool encounter =
                AllflameContext.IsChartMapArea ||
                (AllflameContext.IsVoyageMapArea &&
                 AllflameContext.Phase == AllflamePhase.Voyage);
            if (!encounter)
            {
                ResetTarget();
                ResetPathfinder();
                return Task.FromResult(false);
            }
            if (!AllflameSettings.Instance.OpenKnownChestsFirst ||
                (AllflameContext.Phase == AllflamePhase.ChartArea &&
                 AllflameRunState.LanternsExhausted) ||
                (AllflameContext.Phase == AllflamePhase.ChartArea &&
                 AllflameContext.LanternCounterMaximum > 0 &&
                 AllflameContext.LanternCounterCurrent <= 0) ||
                (AllflameContext.Phase == AllflamePhase.Voyage &&
                  (VoyageRunState.LanternsExhausted ||
                   VoyageRunState.SurfaceTransferPending)) ||
                (AllflameContext.Phase == AllflamePhase.Voyage &&
                 VoyageRunState.ExitCapsuleSecuringRequired) ||
                AllflameChestRoute.PendingCount <= 0 ||
                LokiPoe.Me == null)
            {
                return Task.FromResult(false);
            }

            if (!EnsurePathfinderReady())
            {
                return Task.FromResult(true);
            }

            int requiredLootDebt =
                AllflameSettings.Instance.EnableGroundLoot
                    ? AllflameLootState
                        .CountRequiredTrackedDropsOnGround(
                            AllflameSettings.Instance)
                    : 0;
            if (requiredLootDebt > 0)
            {
                AllflameLog.Throttled(
                    "chest_route_yield_to_required_loot",
                    TimeSpan.FromMilliseconds(750),
                    "CHEST_PHASE|Phase=YieldToLoot" +
                    "|PendingDrops=" + requiredLootDebt +
                    "|Action=LootTaskOwnsMovement");
                return Task.FromResult(false);
            }

            int id;
            Vector2i rememberedPosition;
            string rememberedName;
            if (!AllflameChestRoute.TryGetNextWaypoint(
                out id,
                out rememberedPosition,
                out rememberedName))
            {
                return Task.FromResult(false);
            }
            if (AllflameSettings.Instance.EnableGroundLoot &&
                AllflameLootState.IsActive &&
                !AllflameLootState.IsNearbyClusterPosition(
                    rememberedPosition,
                    120))
            {
                return Task.FromResult(false);
            }

            NetworkObject live = AllflameChestRoute.FindLiveActiveTarget();
            Vector2i targetPosition = live == null
                ? rememberedPosition
                : live.Position;
            float distance = LokiPoe.Me.Position.DistanceF(targetPosition);

            if (_targetId != id)
            {
                _targetId = id;
                _failures = 0;
                _lastDistance = distance;
                _lastProgressUtc = DateTime.UtcNow;
                _arrivedWithoutObjectUtc = DateTime.MinValue;
                _nextPathFailureUtc = DateTime.MinValue;
                _pathfinderRecoveries = 0;
                AllflameLog.Info(
                    "CHEST_PHASE|Phase=Navigate|Id=" + id +
                    "|Name=" + rememberedName +
                    "|Position=" + targetPosition +
                    "|Pending=" + AllflameChestRoute.PendingCount);
            }

            float approachDistance =
                Math.Max(12, AllflameSettings.Instance.InteractDistance + 4);
            if (distance <= approachDistance)
            {
                if (live != null)
                {
                    AllflameLog.Throttled(
                        "chest_ready_to_open",
                        TimeSpan.FromSeconds(1),
                        "CHEST_PHASE|Phase=OpenReady|Id=" + id +
                        "|Distance=" + distance.ToString("0.0"));
                    return Task.FromResult(false);
                }

                if (_arrivedWithoutObjectUtc == DateTime.MinValue)
                {
                    _arrivedWithoutObjectUtc = DateTime.UtcNow;
                    return Task.FromResult(true);
                }

                if (DateTime.UtcNow - _arrivedWithoutObjectUtc >=
                    TimeSpan.FromSeconds(2))
                {
                    AllflameChestRoute.MarkUnreachable(id);
                    ResetTarget();
                }
                return Task.FromResult(true);
            }

            _arrivedWithoutObjectUtc = DateTime.MinValue;
            if (_lastDistance - distance >= 8f)
            {
                _lastDistance = distance;
                _lastProgressUtc = DateTime.UtcNow;
                _failures = 0;
            }
            else if (DateTime.UtcNow - _lastProgressUtc >=
                     TimeSpan.FromSeconds(4))
            {
                _failures++;
                _lastDistance = distance;
                _lastProgressUtc = DateTime.UtcNow;
                AllflameLog.Info(
                    "CHEST_ROUTE_STALL|Id=" + id +
                    "|Distance=" + distance.ToString("0.0") +
                    "|Failures=" + _failures);
            }

            bool moving = MoveTowardsInteraction(
                targetPosition,
                Name);
            if (!moving &&
                DateTime.UtcNow >= _nextPathFailureUtc)
            {
                _failures++;
                _nextPathFailureUtc =
                    DateTime.UtcNow.AddMilliseconds(750);
            }

            if (_failures >= 2 && _pathfinderRecoveries < 2)
            {
                ReloadPathfinderForChest(
                    id,
                    targetPosition,
                    distance);
                return Task.FromResult(true);
            }

            if (_failures >= 3)
            {
                AllflameChestRoute.MarkUnreachable(id);
                ResetTarget();
                return Task.FromResult(true);
            }

            AllflameLog.Throttled(
                "chest_route_move",
                TimeSpan.FromSeconds(2),
                "CHEST_PHASE|Phase=Navigate|Id=" + id +
                "|Name=" + rememberedName +
                "|Position=" + targetPosition +
                "|Distance=" + distance.ToString("0.0") +
                "|Live=" + (live != null) +
                "|Moving=" + moving +
                "|Failures=" + _failures);
            return Task.FromResult(true);
        }

        private bool EnsurePathfinderReady()
        {
            uint areaHash = AllflameContext.AreaHash;
            if (areaHash == 0)
            {
                return false;
            }

            uint loadedHash = 0;
            try
            {
                loadedHash = ExilePather.AreaHash;
            }
            catch
            {
            }

            bool loadedAreaMismatch =
                loadedHash != areaHash &&
                _pathfinderSetupFailures < 2;
            if (_pathfinderAreaHash != areaHash || loadedAreaMismatch)
            {
                ResetTarget();
                if (loadedHash == areaHash)
                {
                    _pathfinderAreaHash = areaHash;
                    _pathfinderReadyUtc = DateTime.UtcNow;
                    _pathfinderSetupFailures = 0;
                    AllflameLog.Info(
                        "CHEST_PATHFINDER_READY" +
                        "|Reason=AlreadyLoaded" +
                        "|AreaHash=" + areaHash);
                    return true;
                }

                try
                {
                    ExilePather.Reload(true);
                    _pathfinderAreaHash = areaHash;
                    _pathfinderReadyUtc =
                        DateTime.UtcNow.AddMilliseconds(250);
                    _pathfinderSetupFailures = 0;
                    AllflameLog.Info(
                        "CHEST_PATHFINDER_RELOAD" +
                        "|Reason=AreaChanged" +
                        "|PreviousHash=" + loadedHash +
                        "|AreaHash=" + areaHash +
                        "|LoadedHash=" + ExilePather.AreaHash +
                        "|WarmupMs=250");
                }
                catch (Exception ex)
                {
                    _pathfinderSetupFailures++;
                    _pathfinderAreaHash =
                        _pathfinderSetupFailures >= 2
                            ? areaHash
                            : 0;
                    _pathfinderReadyUtc =
                        _pathfinderSetupFailures >= 2
                            ? DateTime.UtcNow
                            : DateTime.UtcNow.AddMilliseconds(250);
                    AllflameLog.Info(
                        "CHEST_PATHFINDER_RELOAD_FAILED" +
                        "|Reason=AreaChanged" +
                        "|AreaHash=" + areaHash +
                        "|Attempt=" + _pathfinderSetupFailures +
                        "|Maximum=2" +
                        "|Action=" + (_pathfinderSetupFailures >= 2
                            ? "ProceedToBoundedMovement"
                            : "Retry") +
                        "|Error=" + ex.GetType().Name +
                        ":" + ex.Message.Replace("|", "/"));
                }
                return false;
            }

            if (DateTime.UtcNow < _pathfinderReadyUtc)
            {
                AllflameLog.Throttled(
                    "chest_pathfinder_warmup_" + areaHash,
                    TimeSpan.FromMilliseconds(500),
                    "CHEST_PATHFINDER_WAIT" +
                    "|AreaHash=" + areaHash +
                    "|Reason=Warmup" +
                    "|FailuresIgnored=True");
                return false;
            }
            return true;
        }

        private void ReloadPathfinderForChest(
            int id,
            Vector2i targetPosition,
            float distance)
        {
            _pathfinderRecoveries++;
            _failures = 0;
            _nextPathFailureUtc =
                DateTime.UtcNow.AddMilliseconds(750);
            try
            {
                ExilePather.Reload(true);
                _pathfinderAreaHash = AllflameContext.AreaHash;
                _pathfinderReadyUtc =
                    DateTime.UtcNow.AddMilliseconds(250);
                AllflameMover mover =
                    PlayerMoverManager.Current as AllflameMover;
                if (mover != null)
                {
                    mover.ResetApproachState();
                }
                AllflameLog.Info(
                    "CHEST_PATH_RECOVERY" +
                    "|Id=" + id +
                    "|Target=" + targetPosition +
                    "|Distance=" + distance.ToString("0.0") +
                    "|Recovery=" + _pathfinderRecoveries +
                    "|Maximum=2" +
                    "|Action=ReloadPatherAndResetMover");
            }
            catch (Exception ex)
            {
                _pathfinderReadyUtc = DateTime.UtcNow;
                AllflameLog.Info(
                    "CHEST_PATH_RECOVERY_FAILED" +
                    "|Id=" + id +
                    "|Recovery=" + _pathfinderRecoveries +
                    "|Error=" + ex.GetType().Name +
                    ":" + ex.Message.Replace("|", "/"));
            }
        }

        private void ResetTarget()
        {
            _targetId = 0;
            _failures = 0;
            _lastDistance = Single.MaxValue;
            _lastProgressUtc = DateTime.MinValue;
            _arrivedWithoutObjectUtc = DateTime.MinValue;
            _nextPathFailureUtc = DateTime.MinValue;
            _pathfinderRecoveries = 0;
        }

        private void ResetPathfinder()
        {
            _pathfinderAreaHash = 0;
            _pathfinderReadyUtc = DateTime.MinValue;
            _pathfinderSetupFailures = 0;
        }
    }

    internal sealed class OpenDeepwaterChestsTask : ObserverTask
    {
        private readonly Dictionary<int, int> _attempts =
            new Dictionary<int, int>();
        private int _lastChestId;
        private DateTime _nextChestAttemptUtc = DateTime.MinValue;

        public OpenDeepwaterChestsTask()
            : base("OpenDeepwaterChestsTask", "Opens a configured chest after navigation has reached it.") { }

        public override async Task<bool> Run()
        {
            bool encounter =
                AllflameContext.IsChartMapArea ||
                (AllflameContext.IsVoyageMapArea &&
                 AllflameContext.Phase == AllflamePhase.Voyage);
            if (!encounter ||
                !AllflameSettings.Instance.OpenKnownChestsFirst ||
                (AllflameContext.Phase == AllflamePhase.ChartArea &&
                 AllflameRunState.LanternsExhausted) ||
                (AllflameContext.Phase == AllflamePhase.ChartArea &&
                 AllflameContext.LanternCounterMaximum > 0 &&
                 AllflameContext.LanternCounterCurrent <= 0) ||
                (AllflameContext.Phase == AllflamePhase.Voyage &&
                  (VoyageRunState.LanternsExhausted ||
                   VoyageRunState.SurfaceTransferPending)) ||
                (AllflameContext.Phase == AllflamePhase.Voyage &&
                 VoyageRunState.ExitCapsuleSecuringRequired) ||
                AllflameChestRoute.PendingCount <= 0)
            {
                return false;
            }

            NetworkObject chest = AllflameChestRoute.FindLiveActiveTarget();
            if (chest == null ||
                chest.Distance >
                Math.Max(12, AllflameSettings.Instance.InteractDistance + 4))
            {
                return false;
            }
            if (AllflameSettings.IsEssenceObject(
                    chest.Name,
                    chest.Metadata))
            {
                AllflameChestRoute.MarkUnreachable(chest.Id);
                AllflameLog.Info(
                    "CHEST_OBJECT_REJECTED" +
                    "|Id=" + chest.Id +
                    "|Name=" + (chest.Name ?? String.Empty) +
                    "|Metadata=" +
                    (chest.Metadata ?? String.Empty) +
                    "|Reason=EssenceDenyList" +
                    "|Action=BlockFinalInteraction");
                return true;
            }
            if (AllflameSettings.Instance.EnableGroundLoot &&
                AllflameLootState.IsActive &&
                !AllflameLootState.IsNearbyClusterPosition(
                    chest.Position,
                    120))
            {
                return false;
            }
            if (AllflameSettings.Instance.EnableGroundLoot &&
                AllflameLootState.IsActive)
            {
                AllflameLootState.RefreshChestDrops(
                    AllflameSettings.Instance.GroundLootRadius);
                int requiredDrops =
                    AllflameLootState.CountRequiredTrackedDropsOnGround(
                        AllflameSettings.Instance);
                if (requiredDrops > 0)
                {
                    AllflameLog.Throttled(
                        "chest_defer_for_loot_debt",
                        TimeSpan.FromMilliseconds(500),
                        "CHEST_PHASE|Phase=DeferOpen" +
                        "|Id=" + chest.Id +
                        "|Reason=RequiredDropsFromOpenedCluster" +
                        "|PendingDrops=" + requiredDrops +
                        "|Action=LootBeforeNextChest");
                    return false;
                }
            }

            if (_lastChestId == chest.Id &&
                DateTime.UtcNow < _nextChestAttemptUtc)
            {
                return true;
            }

            _lastChestId = chest.Id;
            _nextChestAttemptUtc = DateTime.UtcNow.AddSeconds(1);
            int attempts;
            _attempts.TryGetValue(chest.Id, out attempts);
            attempts++;
            _attempts[chest.Id] = attempts;

            AllflameLog.Info(
                "CHEST_PHASE|Phase=Open|Id=" + chest.Id +
                "|Name=" + chest.Name +
                "|Distance=" + chest.Distance.ToString("0.0") +
                "|Attempt=" + attempts);
            if (attempts == 1)
            {
                AllflameLootState.BeginChestOpen(chest);
            }
            int chestId = chest.Id;
            string chestName = chest.Name ?? String.Empty;
            string chestMetadata = chest.Metadata ?? String.Empty;
            Vector2i chestPosition = chest.Position;
            bool messageBottleChest =
                AllflameLootState.IsMessageBottleChest(chest);
            bool interacted = await InteractWithRecovery(chest);
            bool confirmedOpen =
                interacted &&
                await WaitForChestOpenConfirmation(
                    chestId,
                    450);
            AllflameLog.Info(
                "CHEST_OPEN|Id=" + chestId +
                "|Name=" + chestName +
                "|Metadata=" + chestMetadata +
                "|Attempt=" + attempts +
                "|InteractSuccess=" + interacted +
                "|Confirmed=" + confirmedOpen);

            if (confirmedOpen)
            {
                AllflameSession.RecordChestOpened();
                if (messageBottleChest)
                {
                    BottleSafetyMovement.Activate(
                        chestId,
                        chestPosition);
                }
                AllflameChestRoute.MarkOpened(chestId);
                AllflameLootState.MarkChestOpened(
                    chestId,
                    chestPosition);
                _attempts.Remove(chestId);
                AllflameLog.Info(
                    "CHEST_PHASE|Phase=Loot|Id=" + chestId +
                    "|Radius=" + AllflameSettings.Instance.GroundLootRadius);
                int settleMilliseconds =
                    AllflameSettings.Instance
                        .LootSettleMilliseconds;
                if (messageBottleChest)
                {
                    await WaitWithBottleSafetyMovement(
                        settleMilliseconds,
                        "WaitForBottleDrop");
                }
                else
                {
                    await LokiCoroutine.Sleep(
                        settleMilliseconds);
                }
            }
            else if (attempts >= 6)
            {
                AllflameChestRoute.MarkUnreachable(chestId);
                _attempts.Remove(chestId);
                AllflameLog.Info(
                    "CHEST_OPEN_GIVE_UP|Id=" + chestId +
                    "|Name=" + chestName +
                    "|Attempts=" + attempts +
                    "|Reason=NotConfirmedOpen");
            }
            else
            {
                AllflameLog.Info(
                    "CHEST_OPEN_RETRY|Id=" + chestId +
                    "|Attempt=" + attempts +
                    "|NextAttemptMs=1000");
            }
            return true;
        }

        private static async Task WaitWithBottleSafetyMovement(
            int milliseconds,
            string reason)
        {
            int remaining = Math.Max(0, milliseconds);
            while (remaining > 0)
            {
                if (LokiPoe.Me == null ||
                    LokiPoe.Me.IsDead)
                {
                    return;
                }
                bool voyage =
                    AllflameContext.IsVoyageMapArea &&
                    AllflameContext.Phase == AllflamePhase.Voyage;
                if (ZeroLanternSafety.IsExhausted(voyage) &&
                    !AllflameLootState.CommittedChestLootActive &&
                    !AllflameContext.LanternAuraActive)
                {
                    ZeroLanternSafety.AbortChestAndLootWork(
                        voyage,
                        "BottleDropWaitLostAura",
                        LokiPoe.Me.Position);
                    return;
                }
                BottleSafetyMovement.Move(reason);
                int delay = Math.Min(160, remaining);
                await LokiCoroutine.Sleep(delay);
                remaining -= delay;
            }
        }

        private static async Task<bool> WaitForChestOpenConfirmation(
            int chestId,
            int timeoutMilliseconds)
        {
            int remaining = Math.Max(0, timeoutMilliseconds);
            while (remaining > 0)
            {
                if (IsConfirmedOpen(chestId))
                {
                    return true;
                }

                int delay = Math.Min(50, remaining);
                await LokiCoroutine.Sleep(delay);
                remaining -= delay;
            }

            return IsConfirmedOpen(chestId);
        }

        private static bool IsConfirmedOpen(int chestId)
        {
            try
            {
                NetworkObject current =
                    LokiPoe.ObjectManager.Objects.FirstOrDefault(
                        obj => obj != null && obj.Id == chestId);
                Chest currentChest = current as Chest;
                return current == null ||
                    !current.IsValid ||
                    !current.IsTargetable ||
                    (currentChest != null && currentChest.IsOpened);
            }
            catch
            {
                return false;
            }
        }
    }

    internal static class AllflameItemFilter
    {
        public static bool ShouldPickup(
            Item item,
            AllflameSettings settings)
        {
            if (item == null || !item.IsValid)
            {
                return false;
            }

            if (settings.PickupEverything)
            {
                return true;
            }

            string metadata = item.Metadata ?? String.Empty;
            string itemClass = item.Class ?? String.Empty;
            string name = item.FullName ?? item.Name ?? String.Empty;

            // Voidborn Reliquary Keys use the VaultKey class rather than
            // MapFragment, so they must be accepted explicitly regardless of
            // the optional map/currency category toggles.
            if (IsVoidbornReliquaryKey(item))
            {
                return true;
            }
            if (settings.WalkOverGold && IsGold(item))
            {
                return true;
            }
            if (settings.PickupSeasonalRewards &&
                (Contains(metadata, "Deepwater") ||
                 Contains(metadata, "Allflame")))
            {
                return true;
            }
            if (settings.PickupCurrency &&
                (itemClass.EndsWith(
                     "Currency",
                     StringComparison.OrdinalIgnoreCase) ||
                 Contains(metadata, "/Currency/") ||
                 Contains(metadata, "Currency")))
            {
                return !settings.IgnoreScrollOfWisdom ||
                       !Contains(metadata, "CurrencyIdentification");
            }
            if (settings.PickupDivinationCards &&
                (Contains(itemClass, "Divination") ||
                 Contains(metadata, "Divination")))
            {
                return true;
            }
            if (settings.PickupScarabs &&
                (Contains(itemClass, "Scarab") ||
                 Contains(metadata, "Scarab") ||
                 name.EndsWith(
                     " Scarab",
                     StringComparison.OrdinalIgnoreCase)))
            {
                return true;
            }
            if (settings.PickupUniques &&
                String.Equals(
                    item.Rarity.ToString(),
                    "Unique",
                    StringComparison.OrdinalIgnoreCase))
            {
                return MeetsMinimumValue(
                    item,
                    settings.MinimumUniqueValueDivines,
                    "Unique");
            }
            if (settings.PickupMaps &&
                (item.MapTier >= settings.MinimumMapTier ||
                 Contains(itemClass, "MapFragment")))
            {
                return true;
            }
            if (settings.PickupQuestItems &&
                (Contains(itemClass, "Quest") ||
                 Contains(metadata, "/QuestItems/")))
            {
                return true;
            }
            if (settings.PickupGems &&
                item.Quality >= settings.MinimumGemQuality &&
                (Contains(itemClass, "Skill Gem") ||
                 Contains(metadata, "/Gems/")))
            {
                return MeetsMinimumValue(
                    item,
                    settings.MinimumGemValueDivines,
                    "Gem");
            }
            if (settings.PickupFlasks &&
                item.Quality >= settings.MinimumFlaskQuality &&
                (Contains(itemClass, "Flask") ||
                 Contains(metadata, "/Flasks/")))
            {
                return true;
            }
            if (settings.PickupRares &&
                String.Equals(
                    item.Rarity.ToString(),
                    "Rare",
                    StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
            if (settings.PickupSixSockets &&
                item.SocketCount >= settings.MinimumSockets)
            {
                return true;
            }
            if (settings.PickupLinkedItems &&
                item.MaxLinkCount >= settings.MinimumLinks)
            {
                return true;
            }

            AllflameLog.Throttled(
                "pickit_item_rejected",
                TimeSpan.FromSeconds(5),
                "PICKIT_FILTER|Result=Reject" +
                "|Name=" + name +
                "|Class=" + itemClass +
                "|Metadata=" + metadata);
            return false;
        }

        private static bool MeetsMinimumValue(
            Item item,
            double minimumDivines,
            string category)
        {
            if (minimumDivines <= 0d)
            {
                return true;
            }

            AllflamePriceQuote quote =
                AllflamePrices.Quote(item);
            bool uniqueCategory = String.Equals(
                category,
                "Unique",
                StringComparison.OrdinalIgnoreCase);
            bool accepted;
            if (uniqueCategory && quote.IsUnresolvedUnique)
            {
                accepted = true;
            }
            else if (uniqueCategory && quote.IsAmbiguousUnique)
            {
                accepted = quote.MaxCandidateDivines >=
                    minimumDivines;
            }
            else if (uniqueCategory && !quote.IsPriced)
            {
                accepted = true;
            }
            else
            {
                accepted =
                    quote.IsPriced &&
                    quote.TotalDivines >= minimumDivines;
            }
            AllflameLog.Throttled(
                "pickit_value_" + category + "_" + item.Id,
                TimeSpan.FromSeconds(5),
                "PICKIT_VALUE|Category=" + category +
                "|Result=" +
                (accepted ? "Accept" : "Reject") +
                "|Name=" + quote.Name +
                "|Priced=" + quote.IsPriced +
                "|Ambiguous=" + quote.IsAmbiguousUnique +
                "|Unresolved=" + quote.IsUnresolvedUnique +
                "|ValueDivines=" +
                quote.TotalDivines.ToString("0.###") +
                "|CandidateMinDivines=" +
                quote.MinCandidateDivines.ToString("0.###") +
                "|CandidateMaxDivines=" +
                quote.MaxCandidateDivines.ToString("0.###") +
                "|MinimumDivines=" +
                minimumDivines.ToString("0.###"));
            return accepted;
        }

        public static bool IsGold(Item item)
        {
            if (item == null)
            {
                return false;
            }
            string metadata = item.Metadata ?? String.Empty;
            string itemClass = item.Class ?? String.Empty;
            string name = item.FullName ?? item.Name ?? String.Empty;

            // Some seasonal rewards use metadata such as GoldAllflamePack.
            // They are regular clickable items, not auto-pickup ground gold.
            if (Contains(metadata, "Allflame") ||
                name.StartsWith(
                    "Allflame Ember",
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            return Contains(metadata, "/Gold") ||
                   Contains(metadata, "GoldCurrency") ||
                   String.Equals(
                       itemClass,
                       "Gold",
                       StringComparison.OrdinalIgnoreCase) ||
                   String.Equals(
                       name,
                       "Gold",
                       StringComparison.OrdinalIgnoreCase) ||
                   name.EndsWith(
                       " Gold",
                       StringComparison.OrdinalIgnoreCase);
        }

        public static bool IsVoidbornReliquaryKey(Item item)
        {
            if (item == null)
            {
                return false;
            }

            string metadata = item.Metadata ?? String.Empty;
            string name = item.FullName ?? item.Name ?? String.Empty;
            return Contains(metadata, "VoidbornVaultKey") ||
                   String.Equals(
                       name,
                       "Voidborn Reliquary Key",
                       StringComparison.OrdinalIgnoreCase);
        }

        private static bool Contains(string value, string fragment)
        {
            return (value ?? String.Empty).IndexOf(
                fragment,
                StringComparison.OrdinalIgnoreCase) >= 0;
        }
    }

    internal sealed class LootGroundItemsTask : ObserverTask
    {
        private const int MaxConsecutiveLootAttempts = 3;
        private const int UnlootableCooldownSeconds = 12;
        private readonly Dictionary<int, int> _attempts = new Dictionary<int, int>();
        private readonly Dictionary<int, DateTime> _retryAfter =
            new Dictionary<int, DateTime>();
        private readonly Dictionary<int, DateTime> _unlootableUntil =
            new Dictionary<int, DateTime>();
        private readonly HashSet<string> _completedDropSignatures =
            new HashSet<string>(StringComparer.Ordinal);
        private int _lootSessionRevision = -1;
        private bool _pendingPickupActive;
        private int _pendingWorldId;
        private uint _pendingAreaHash;
        private string _pendingItemName = String.Empty;
        private string _pendingDropSignature = String.Empty;
        private int _pendingInventoryBefore;
        private int _pendingAttempt;
        private int _pendingPriority;
        private bool _pendingInteractionAccepted;
        private DateTime _pendingPickupDeadlineUtc = DateTime.MinValue;

        public LootGroundItemsTask()
            : base("LootGroundItemsTask", "Picks evaluated ground loot after opening a reward chest.") { }

        public override async Task<bool> Run()
        {
            AllflameSettings settings = AllflameSettings.Instance;
            bool encounter =
                AllflameContext.IsChartMapArea ||
                (AllflameContext.IsVoyageMapArea &&
                 AllflameContext.Phase == AllflamePhase.Voyage);
            if (!encounter)
            {
                AllflameLootState.Clear();
                _attempts.Clear();
                _retryAfter.Clear();
                _unlootableUntil.Clear();
                _completedDropSignatures.Clear();
                _lootSessionRevision = -1;
                ClearPendingPickup();
                return false;
            }

            bool voyage =
                AllflameContext.IsVoyageMapArea &&
                AllflameContext.Phase == AllflamePhase.Voyage;
            bool committedChartLoot =
                !voyage && AllflameLootState.CommittedChestLootActive;
            if (ZeroLanternSafety.IsExhausted(voyage) &&
                !committedChartLoot)
            {
                ClearPendingPickup();
                ZeroLanternSafety.AbortChestAndLootWork(
                    voyage,
                    "LootTaskBlockedAtZeroLantern",
                    LokiPoe.Me == null
                        ? new Vector2i()
                        : LokiPoe.Me.Position);
                return false;
            }
            if (committedChartLoot)
            {
                AllflameLog.Throttled(
                    "chart_zero_lantern_committed_loot",
                    TimeSpan.FromSeconds(1),
                    "CHEST_ZERO_LANTERN_LOOT" +
                    "|State=Continue" +
                    "|Action=FinishCommittedChestLoot" +
                    "|Counter=" +
                    AllflameContext.LanternCounterCurrent + "/" +
                    AllflameContext.LanternCounterMaximum);
            }

            if (!settings.EnableGroundLoot || !AllflameLootState.IsActive)
            {
                return false;
            }

            if (_lootSessionRevision !=
                AllflameLootState.SessionRevision)
            {
                _lootSessionRevision =
                    AllflameLootState.SessionRevision;
                _attempts.Clear();
                _retryAfter.Clear();
                _unlootableUntil.Clear();
                _completedDropSignatures.Clear();
                ClearPendingPickup();
            }

            if (_pendingPickupActive)
            {
                return ConfirmPendingPickup(settings);
            }

            if (AllflameContext.InventoryFreeSquares == 0)
            {
                AllflameLog.Throttled(
                    "ground_loot_inventory_full",
                    TimeSpan.FromSeconds(3),
                    "GROUND_LOOT_WAIT|Reason=InventoryFull");
                return false;
            }

            if (settings.LootOnlyWhenSafe && HasNearbyMonster())
            {
                AllflameLog.Throttled(
                    "ground_loot_unsafe",
                    TimeSpan.FromSeconds(2),
                    "GROUND_LOOT_WAIT|Reason=NearbyMonster");
                return false;
            }

            AllflameLootState.RefreshChestDrops(settings.GroundLootRadius);
            WorldItem target = SelectBestLootTarget(settings);
            if (target == null)
            {
                if (BottleSafetyMovement.IsActive)
                {
                    BottleSafetyMovement.Move(
                        "WaitForBottleTargetOrRetry");
                }
                int pendingDrops =
                    AllflameLootState.CountRequiredTrackedDropsOnGround(
                        settings);
                if (pendingDrops > 0)
                {
                    AllflameLog.Throttled(
                        "ground_loot_pending_debt",
                        TimeSpan.FromMilliseconds(750),
                        "GROUND_LOOT_WAIT" +
                        "|Reason=RequiredChestDropsRemain" +
                        "|Pending=" + pendingDrops +
                        "|Action=DoNotLeaveChestArea");
                    return true;
                }

                if (AllflameLootState.EmptyWindowCanClose)
                {
                    int visibleWorldItems = 0;
                    try
                    {
                        visibleWorldItems =
                            LokiPoe.ObjectManager.Objects
                                .OfType<WorldItem>()
                                .Count(world =>
                                    world != null &&
                                    world.IsValid);
                    }
                    catch
                    {
                    }
                    AllflameLog.Info(
                        "GROUND_LOOT_DONE|Reason=NoEligibleItems" +
                        "|WorldItems=" + visibleWorldItems +
                        "|CommittedChestLoot=" +
                        AllflameLootState.CommittedChestLootActive);
                    AllflameLootState.Clear();
                    return false;
                }
                return true;
            }

            Item targetItem = SafeItem(target);
            if (settings.WalkOverGold &&
                AllflameItemFilter.IsGold(targetItem))
            {
                int goldAttempts;
                _attempts.TryGetValue(target.Id, out goldAttempts);
                bool nearGold = target.Distance <= 12f;
                int maxGoldAttempts =
                    Math.Max(1, settings.MaxLootAttempts);
                if (!nearGold || goldAttempts < maxGoldAttempts)
                {
                    if (nearGold)
                    {
                        _attempts[target.Id] = goldAttempts + 1;
                    }
                    _retryAfter[target.Id] =
                        DateTime.UtcNow.AddMilliseconds(
                            Math.Max(
                                30,
                                settings.LootActionDelayMilliseconds));

                    bool moving = AllflameMovementCoordinator.MoveTowards(
                        target.Position,
                        Name + " walk over gold");
                    AllflameLog.Throttled(
                        "ground_gold_walk_" + target.Id,
                        TimeSpan.FromMilliseconds(500),
                        "GROUND_LOOT_GOLD|Mode=WalkOver" +
                        "|WorldId=" + target.Id +
                        "|Name=" +
                        (targetItem == null
                            ? String.Empty
                            : targetItem.FullName) +
                        "|Distance=" + target.Distance.ToString("0.0") +
                        "|NearAttempts=" +
                        (nearGold
                            ? goldAttempts + 1
                            : goldAttempts) +
                        "|Moving=" + moving);
                    await LokiCoroutine.Sleep(
                        Math.Max(
                            30,
                            settings.LootActionDelayMilliseconds / 2));
                    return true;
                }

                AllflameLog.Info(
                    "GROUND_LOOT_GOLD_FALLBACK" +
                    "|WorldId=" + target.Id +
                    "|Name=" +
                    (targetItem == null
                        ? String.Empty
                        : targetItem.FullName) +
                    "|Distance=" + target.Distance.ToString("0.0") +
                    "|NearAttempts=" + goldAttempts +
                    "|Action=ClickPickup");
            }

            if (target.Distance > settings.InteractDistance)
            {
                return await MoveOrInteract(target, "Evaluated Ground Loot");
            }

            int attempts;
            _attempts.TryGetValue(target.Id, out attempts);
            _attempts[target.Id] = attempts + 1;
            int effectiveDelayMs =
                Math.Max(
                    30,
                    Math.Min(
                        500,
                        settings.LootActionDelayMilliseconds));
            _retryAfter[target.Id] = DateTime.UtcNow.AddMilliseconds(
                attempts == 0
                    ? effectiveDelayMs
                    : Math.Max(
                        100,
                        settings.LootRetryDelayMilliseconds));

            Item item = SafeItem(target);
            string dropSignature =
                BuildDropSignature(target, item);
            uint interactionAreaHash = AllflameContext.AreaHash;
            string inventoryItemName = item == null
                ? String.Empty
                : (!String.IsNullOrWhiteSpace(item.FullName)
                    ? item.FullName
                    : item.Name);
            int inventoryBefore =
                AllflameContext.GetInventoryQuantity(inventoryItemName);
            if (!target.IsValid ||
                !target.IsTargetable)
            {
                AllflameLog.Throttled(
                    "ground_loot_wait_targetable_" + target.Id,
                    TimeSpan.FromMilliseconds(750),
                    "GROUND_LOOT_WAIT|WorldId=" + target.Id +
                    "|Reason=NotTargetable" +
                    "|Action=KeepLootDebt");
                await LokiCoroutine.Sleep(100);
                return true;
            }

            await FinishMovementBeforeInteraction(
                "GroundLoot:" +
                (item == null
                    ? target.Id.ToString()
                    : item.FullName));
            bool interactionAccepted =
                await InteractWithRecovery(target);
            _pendingPickupActive = true;
            _pendingWorldId = target.Id;
            _pendingAreaHash = interactionAreaHash;
            _pendingItemName = inventoryItemName;
            _pendingDropSignature = dropSignature;
            _pendingInventoryBefore = inventoryBefore;
            _pendingAttempt = attempts + 1;
            _pendingPriority = LootPriority(target);
            _pendingInteractionAccepted = interactionAccepted;
            _pendingPickupDeadlineUtc = DateTime.UtcNow.AddSeconds(2);
            AllflameLog.Info(
                "GROUND_LOOT_PICKUP|WorldId=" + target.Id +
                "|ItemId=" + (item == null ? 0 : item.Id) +
                "|Name=" + (item == null ? String.Empty : item.FullName) +
                "|Metadata=" + (item == null ? String.Empty : item.Metadata) +
                "|Priority=" + LootPriority(target) +
                "|Attempt=" + (attempts + 1) +
                "|InteractionAccepted=" + interactionAccepted +
                "|ConfirmedRemoved=False" +
                "|Action=ConfirmOnNextCycle" +
                "|OneActionPerCycle=True");
            return true;
        }

        private WorldItem SelectBestLootTarget(
            AllflameSettings settings)
        {
            WorldItem best = null;
            int bestPriority = Int32.MinValue;
            float bestDistance = Single.MaxValue;
            try
            {
                foreach (NetworkObject obj in
                    LokiPoe.ObjectManager.Objects)
                {
                    WorldItem world = obj as WorldItem;
                    if (!ShouldPickup(world, settings))
                    {
                        continue;
                    }
                    Item item = SafeItem(world);
                    int priority = LootPriority(item);
                    float distance = world.Distance;
                    if (best == null ||
                        priority > bestPriority ||
                        priority == bestPriority &&
                        distance < bestDistance)
                    {
                        best = world;
                        bestPriority = priority;
                        bestDistance = distance;
                    }
                }
            }
            catch
            {
                return best;
            }
            return best;
        }

        private bool ConfirmPendingPickup(
            AllflameSettings settings)
        {
            bool inGame = LokiPoe.IsInGame;
            bool playerDead = LokiPoe.Me == null || LokiPoe.Me.IsDead;
            bool areaChanged =
                !inGame ||
                AllflameContext.AreaHash != _pendingAreaHash ||
                LokiPoe.LocalData.AreaHash != _pendingAreaHash;
            int inventoryAfter =
                AllflameContext.GetInventoryQuantity(_pendingItemName);
            bool pickupConfirmed =
                _pendingInventoryBefore >= 0 &&
                inventoryAfter > _pendingInventoryBefore;
            WorldItem live = FindWorldItem(_pendingWorldId);
            if (pickupConfirmed)
            {
                Item confirmedItem =
                    FindInventoryItem(_pendingItemName);
                _completedDropSignatures.Add(
                    _pendingDropSignature);
                AllflameLootState.MarkMessageBottleCollected(
                    confirmedItem);
                if (confirmedItem != null)
                {
                    AllflameSession.RecordLoot(
                        confirmedItem,
                        AllflameLootState.CurrentChestName,
                        inventoryAfter - _pendingInventoryBefore,
                        _pendingInventoryBefore,
                        inventoryAfter,
                        _pendingDropSignature);
                }
                AllflameLog.Info(
                    "GROUND_LOOT_PICKUP_CONFIRMED" +
                    "|WorldId=" + _pendingWorldId +
                    "|Item=" + _pendingItemName.Replace("|", "/") +
                    "|InventoryBefore=" + _pendingInventoryBefore +
                    "|InventoryAfter=" + inventoryAfter +
                    "|WorldItemGone=" + (live == null) +
                    "|OneActionPerCycle=True");
                ClearPendingPickup();
                return true;
            }

            if (!areaChanged && !playerDead &&
                DateTime.UtcNow < _pendingPickupDeadlineUtc)
            {
                return true;
            }

            string rejectReason = !inGame
                ? "NotInGame"
                : playerDead
                    ? "PlayerDead"
                    : areaChanged
                        ? "AreaChanged"
                        : "InventoryDeltaMissing";
            int worldId = _pendingWorldId;
            int attempt = _pendingAttempt;
            bool interactionAccepted =
                _pendingInteractionAccepted;
            AllflameSession.RecordRejectedPickup();
            AllflameLog.Info(
                "NOTIFICATION_PICKUP_REJECTED|Item=" +
                _pendingItemName.Replace("|", "/") +
                "|Reason=" + rejectReason +
                "|PlayerDead=" + playerDead +
                "|AreaChanged=" + areaChanged +
                "|InventoryConfirmed=False" +
                "|WorldItemGone=" + (live == null) +
                "|InteractSuccess=" + interactionAccepted);
            if (attempt >= MaxConsecutiveLootAttempts)
            {
                DateTime cooldownUntil = DateTime.UtcNow.AddSeconds(
                    UnlootableCooldownSeconds);
                _unlootableUntil[worldId] = cooldownUntil;
                _retryAfter[worldId] = cooldownUntil;
                AllflameLootState.MarkDropUnlootable(worldId);
                bool committedChartLoot =
                    !AllflameContext.IsVoyageMapArea &&
                    AllflameLootState.CommittedChestLootActive;
                bool returnToSafeZone = HasNearbyMonster() ||
                    (ZeroLanternSafety.IsExhausted(
                        AllflameContext.IsVoyageMapArea &&
                        AllflameContext.Phase == AllflamePhase.Voyage) &&
                     !AllflameContext.LanternAuraActive &&
                     !committedChartLoot);
                if (returnToSafeZone)
                {
                    AllflameLootState.Clear();
                }
                AllflameLog.Info(
                    "GROUND_LOOT_GIVE_UP" +
                    "|WorldId=" + worldId +
                    "|Attempts=" + attempt +
                    "|Reason=InteractionRejected" +
                    "|CooldownSeconds=" +
                    UnlootableCooldownSeconds +
                    "|Action=" +
                    (returnToSafeZone
                        ? "ReturnToSafeZone"
                        : "ResumeChestRoute"));
            }
            if (BottleSafetyMovement.IsActive)
            {
                BottleSafetyMovement.Move(
                    "BottlePickupNotConfirmed");
            }
            ClearPendingPickup();
            return true;
        }

        private static WorldItem FindWorldItem(int worldId)
        {
            try
            {
                foreach (NetworkObject obj in
                    LokiPoe.ObjectManager.Objects)
                {
                    WorldItem world = obj as WorldItem;
                    if (world != null && world.Id == worldId &&
                        world.IsValid)
                    {
                        return world;
                    }
                }
            }
            catch
            {
            }
            return null;
        }

        private static Item FindInventoryItem(string itemName)
        {
            try
            {
                InventoryControlWrapper control =
                    LokiPoe.InGameState.InventoryUi
                        .InventoryControl_Main;
                if (control == null || control.Inventory == null ||
                    control.Inventory.Items == null)
                {
                    return null;
                }
                return control.Inventory.Items.FirstOrDefault(item =>
                    item != null && item.IsValid &&
                    (String.Equals(
                         item.FullName,
                         itemName,
                         StringComparison.OrdinalIgnoreCase) ||
                     String.Equals(
                         item.Name,
                         itemName,
                         StringComparison.OrdinalIgnoreCase)));
            }
            catch
            {
                return null;
            }
        }

        private void ClearPendingPickup()
        {
            _pendingPickupActive = false;
            _pendingWorldId = 0;
            _pendingAreaHash = 0;
            _pendingItemName = String.Empty;
            _pendingDropSignature = String.Empty;
            _pendingInventoryBefore = -1;
            _pendingAttempt = 0;
            _pendingPriority = 0;
            _pendingInteractionAccepted = false;
            _pendingPickupDeadlineUtc = DateTime.MinValue;
        }

        private bool ShouldPickup(WorldItem worldItem, AllflameSettings settings)
        {
            try
            {
                if (worldItem == null ||
                    !worldItem.IsValid ||
                    worldItem.IsAllocatedToOther ||
                    !AllflameLootState.IsRequiredChestDrop(
                        worldItem,
                        settings.GroundLootRadius))
                {
                    return false;
                }

                Item item = SafeItem(worldItem);
                if (_completedDropSignatures.Contains(
                        BuildDropSignature(
                            worldItem,
                            item)))
                {
                    return false;
                }

                DateTime retry;
                if (_retryAfter.TryGetValue(worldItem.Id, out retry) &&
                    DateTime.UtcNow < retry)
                {
                    return false;
                }

                if (item == null || !item.IsValid)
                {
                    return false;
                }

                if (_unlootableUntil.ContainsKey(worldItem.Id))
                {
                    return false;
                }

                // Eligibility is sticky for the current chest session. A label
                // can briefly lose highlight after a click or when labels
                // overlap; that must not silently cancel an already accepted
                // filter-visible drop.
                return true;
            }
            catch
            {
                return false;
            }
        }

        private static string BuildDropSignature(
            WorldItem worldItem,
            Item item)
        {
            if (worldItem == null)
            {
                return String.Empty;
            }

            return worldItem.Id + "|" +
                worldItem.Position + "|" +
                (item == null ? String.Empty : item.Metadata) + "|" +
                (item == null ? String.Empty : item.FullName);
        }

        private static bool MatchesPickupEvaluator(Item item)
        {
            try
            {
                return ItemEvaluator.Match(item, EvaluationType.PickUp);
            }
            catch (Exception ex)
            {
                AllflameLog.Throttled(
                    "loot_evaluator_failed",
                    TimeSpan.FromSeconds(10),
                    "GROUND_LOOT_EVALUATOR_FAILED|" + ex.GetType().Name +
                    "|" + ex.Message);
                return false;
            }
        }

        private static bool IsSeasonalReward(Item item)
        {
            string metadata = item.Metadata ?? String.Empty;
            return
                metadata.IndexOf("Deepwater", StringComparison.OrdinalIgnoreCase) >= 0 ||
                metadata.IndexOf("Allflame", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static int LootPriority(WorldItem worldItem)
        {
            return LootPriority(SafeItem(worldItem));
        }

        private static int LootPriority(Item item)
        {
            if (item == null)
            {
                return 0;
            }

            string metadata = item.Metadata ?? String.Empty;
            if (AllflameItemFilter.IsGold(item)) return 110;
            if (AllflameItemFilter.IsVoidbornReliquaryKey(item)) return 105;
            if (IsSeasonalReward(item)) return 100;
            if (metadata.IndexOf("Currency", StringComparison.OrdinalIgnoreCase) >= 0) return 90;
            if (metadata.IndexOf("Divination", StringComparison.OrdinalIgnoreCase) >= 0) return 85;
            if (metadata.IndexOf("Scarab", StringComparison.OrdinalIgnoreCase) >= 0) return 80;
            if (metadata.IndexOf("Map", StringComparison.OrdinalIgnoreCase) >= 0) return 75;
            if (String.Equals(item.Rarity.ToString(), "Unique", StringComparison.OrdinalIgnoreCase)) return 70;
            return 10;
        }

        private static Item SafeItem(WorldItem worldItem)
        {
            try { return worldItem == null ? null : worldItem.Item; }
            catch { return null; }
        }

        private static bool HasNearbyMonster()
        {
            try
            {
                return LokiPoe.ObjectManager.Objects
                    .OfType<Monster>()
                    .Any(monster =>
                        monster != null &&
                        monster.IsValid &&
                        monster.IsTargetable &&
                        monster.Distance <= 25f);
            }
            catch
            {
                return false;
            }
        }
    }

