        public UseAllflameCapsuleTask()
            : base("UseAllflameCapsuleTask", "Sends loot and calls the Bathysphere from a Capsule.") { }

        public override void Start()
        {
            ClearPendingTransfer();
            _nativeSendAttempted = false;
            _nativeSendFallbackArmed = false;
            _nativeCallAttempted = false;
            _nativeCallFallbackArmed = false;
            ResetZeroLanternRescue("TaskStart");
            ResetCapsuleReturnChain("TaskStart");
        }

        public override void Stop()
        {
            ClearPendingTransfer();
            _nativeSendAttempted = false;
            _nativeSendFallbackArmed = false;
            _nativeCallAttempted = false;
            _nativeCallFallbackArmed = false;
            ResetZeroLanternRescue("TaskStop");
            ResetCapsuleReturnChain("TaskStop");
            AllflameProgressWatchdog.Clear();
        }

        public override async Task<bool> Run()
        {
            bool voyageOrRetryWait =
                AllflameContext.IsVoyageMapArea &&
                (AllflameContext.Phase == AllflamePhase.Voyage ||
                (AllflameContext.Phase ==
                    AllflamePhase.WaitingForBathysphere &&
                 !VoyageRunState.CallIssued));
            if (!voyageOrRetryWait ||
                (!AllflameSettings.Instance.EnableVoyageRunner &&
                 !AllflameVoyageDebug.SendToSurfaceRequested))
            {
                ResetRequest();
                return false;
            }

            // Once Call has been issued, this task must not create a second
            // surface-transfer request during the short frame in which the
            // context still reports Phase=Voyage. Waiting and extraction now
            // own the bot exclusively.
            if (VoyageRunState.CallIssued)
            {
                VoyageRunState.SurfaceTransferPending = false;
                ResetRequest();
                return false;
            }

            AllflameSettings settings = AllflameSettings.Instance;
            Item transferable = GetTransferableInventoryItem();
            bool hasTransferable = transferable != null;
            if (AllflameVoyageDebug.SendToSurfaceRequested &&
                !hasTransferable)
            {
                AllflameVoyageDebug.CompleteSendToSurface(
                    "NoTransferableItems");
                AllflameLog.Info(
                    "CAPSULE_TRANSFER_COMPLETE|Sent=False" +
                    "|Reason=DebugNoTransferableItems");
                ResetRequest();
                return false;
            }
            bool debugTransfer =
                AllflameVoyageDebug.SendToSurfaceRequested &&
                hasTransferable;
            bool inventoryThreshold =
                settings.SendLootToSurface &&
                hasTransferable &&
                DateTime.UtcNow >= _surfaceTransferBackoffUtc &&
                AllflameContext.InventoryFreeSquares >= 0 &&
                AllflameContext.InventoryFreeSquares <=
                    settings.SendToSurfaceFreeSlots;
            bool boundaryTransfer =
                settings.SendLootToSurface &&
                hasTransferable &&
                DateTime.UtcNow >= _surfaceTransferBackoffUtc &&
                settings.TransferAtVoyageSectorBoundaries &&
                VoyageRunState.SectorBoundaryReached;
            bool bottleTransfer =
                VoyageRunState.BottleSurfaceTransferPending &&
                hasTransferable &&
                DateTime.UtcNow >= _surfaceTransferBackoffUtc;
            bool extractionRequired =
                VoyageRunState.LanternsExhausted;
            bool cachedReturnUiReady = false;
            string extractionReason =
                String.IsNullOrWhiteSpace(VoyageRunState.ExtractionReason)
                    ? "LanternsExhausted"
                    : VoyageRunState.ExtractionReason;
            if (extractionRequired &&
                _rescueAreaHash != AllflameContext.AreaHash)
            {
                ResetZeroLanternRescue("AreaHashChanged");
                _rescueAreaHash = AllflameContext.AreaHash;
            }
            if (!debugTransfer &&
                !inventoryThreshold &&
                !boundaryTransfer &&
                !bottleTransfer &&
                !VoyageRunState.SurfaceTransferPending &&
                !extractionRequired)
            {
                ResetRequest();
                return false;
            }

            if (!_requestActive)
            {
                _requestActive = true;
                _capsuleSearchStartedUtc = DateTime.UtcNow;
                _forceLiveCapsule = false;
                _capsuleSearchHardFailsafeActive = false;
                _capsuleHardFailsafeStartedUtc = DateTime.MinValue;
                _capsuleHardFailsafeCycles = 0;
                ResetWatchedRouteAnchor();
                _batchHadItems = false;
                _surfaceSentForRequest = false;
                _transferFailures = 0;
                string reason = debugTransfer
                    ? "DebugButton"
                    : (extractionRequired
                    ? extractionReason
                    : (bottleTransfer
                        ? "BottleThreshold"
                        : (inventoryThreshold
                        ? "InventoryThreshold"
                        : "SectorBoundary")));
                AllflameLog.Info(
                    "VOYAGE_SURFACE_TRIGGER|Reason=" + reason +
                    "|InventoryFreeSquares=" +
                    AllflameContext.InventoryFreeSquares +
                    "|Threshold=" +
                    settings.SendToSurfaceFreeSlots +
                    "|TransferableItems=" +
                    Math.Max(
                        0,
                        AllflameContext.InventoryItemCount -
                        AllflameContext.InventoryChartCount) +
                    "|RegisteredCapsules=" +
                    VoyageRunState.CapsuleAnchorCount);
            }
            VoyageRunState.SurfaceTransferPending = true;

            if (extractionRequired &&
                !_zeroLanternCapsuleGuardLogged)
            {
                _zeroLanternCapsuleGuardLogged = true;
                AllflameLog.Info(
                    "CAPSULE_MANDATORY_EXTRACTION" +
                    "|Counter=" +
                    AllflameContext.LanternCounterCurrent + "/" +
                    AllflameContext.LanternCounterMaximum +
                    "|Action=CancelChestLootAndExplore");
                ZeroLanternSafety.AbortChestAndLootWork(
                    true,
                    Name,
                    _hasLockedExitAnchor
                        ? _lockedExitAnchor
                        : new Vector2i());
            }

            if (extractionRequired)
            {
                cachedReturnUiReady =
                    await RunCachedCapsuleReturn(settings);
                if (!cachedReturnUiReady)
                {
                    return true;
                }
            }

            if (extractionRequired &&
                !AllflameContext.LanternAuraActive &&
                _capsuleSearchHardFailsafeActive)
            {
                _capsuleSearchHardFailsafeActive = false;
                _capsuleHardFailsafeStartedUtc = DateTime.MinValue;
                _forceLiveCapsule = false;
            }
            if (_hasLockedExitAnchor &&
                _capsuleSearchHardFailsafeActive)
            {
                _capsuleSearchHardFailsafeActive = false;
                _capsuleHardFailsafeStartedUtc = DateTime.MinValue;
                _forceLiveCapsule = false;
            }

            if (extractionRequired && !_hasLockedExitAnchor)
            {
                Vector2i player = LokiPoe.Me == null
                    ? new Vector2i()
                    : LokiPoe.Me.Position;
                Vector2i nearbyProven;
                if (LokiPoe.Me != null &&
                    VoyageRunState.TryGetNearbyProvenCapsule(
                        player,
                        65f,
                        out nearbyProven))
                {
                    LockExitAnchor(
                        nearbyProven,
                        true,
                        "ProvenNearby",
                        true);
                }
                else if (TryGetNearbyLiveCapsule(out nearbyProven))
                {
                    LockExitAnchor(
                        nearbyProven,
                        VoyageRunState.IsCapsuleProven(nearbyProven),
                        "LiveNearby",
                        true);
                }
            }

            if (AllflameLootState.IsActive)
            {
                if (extractionRequired ||
                    VoyageRunState.BottleSurfaceTransferPending ||
                    AllflameContext.InventoryFreeSquares == 0)
                {
                    AllflameLootState.Clear();
                    BottleSafetyMovement.Reset();
                    AllflameLog.Info(
                        "CAPSULE_PRIORITY_OVERRIDE" +
                        "|Reason=" +
                        (extractionRequired
                            ? extractionReason
                            : (VoyageRunState.BottleSurfaceTransferPending
                                ? "TwoBottles"
                                : "InventoryFull")) +
                        "|Action=ReleaseGroundLootLock");
                }
                else
                {
                    // Finish the currently opened chest's drops before leaving
                    // for a Capsule while there is still inventory capacity.
                    return false;
                }
            }

            NetworkObject capsule = AllflameContext.CapsuleObject;
            bool capsuleUiVisible = cachedReturnUiReady;
            if (!cachedReturnUiReady)
            {
            if (_hasConfirmedCapsuleAnchor &&
                !_hasLockedExitAnchor &&
                !VoyageRunState.IsCapsuleUsable(
                    _confirmedCapsuleAnchor,
                    true))
            {
                _hasConfirmedCapsuleAnchor = false;
                _confirmedCapsuleAnchor = new Vector2i();
                ResetRoute();
            }

            Vector2i preferredCapsule = new Vector2i();
            float preferredLanternDistance =
                Single.MaxValue;
            bool mandatoryLiveOverride =
                extractionRequired &&
                LokiPoe.Me != null &&
                capsule != null &&
                capsule.IsValid &&
                capsule.IsTargetable &&
                LokiPoe.Me.Position.DistanceF(capsule.Position) <=
                    VoyageRunState.CapsuleNearbyExitDistance;
            if (mandatoryLiveOverride)
            {
                Vector2i previousAnchor = _hasLockedExitAnchor
                    ? _lockedExitAnchor
                    : new Vector2i();
                float liveDistance = LokiPoe.Me.Position.DistanceF(
                    capsule.Position);
                bool replaceLock = !_hasLockedExitAnchor ||
                    _lockedExitAnchor.DistanceF(capsule.Position) > 25f;
                if (replaceLock)
                {
                    VoyageRunState.RestoreLiveCapsuleForFailsafe(
                        capsule.Position,
                        "MandatoryExtractionWithin150");
                    LockExitAnchor(
                        capsule.Position,
                        VoyageRunState.IsCapsuleProven(capsule.Position),
                        "MandatoryLiveWithin150",
                        true,
                        true);
                    AllflameLog.Info(
                        "CAPSULE_LIVE_OVERRIDE" +
                        "|Live=" + capsule.Position +
                        "|Distance=" + liveDistance.ToString("0.0") +
                        "|PreviousRegistryAnchor=" + previousAnchor +
                        "|LockDistance=150");
                }
            }
            bool nearbyLivePreferred =
                extractionRequired &&
                !mandatoryLiveOverride &&
                !_hasLockedExitAnchor &&
                LokiPoe.Me != null &&
                capsule != null &&
                capsule.IsValid &&
                capsule.IsTargetable &&
                VoyageRunState.IsCapsuleTraversed(
                    capsule.Position) &&
                VoyageRunState.IsCapsuleUsable(
                    capsule.Position,
                    true) &&
                LokiPoe.Me.Position.DistanceF(
                    capsule.Position) <=
                    VoyageRunState.CapsuleNearbyExitDistance;
            bool hasPreferredCapsule =
                _hasLockedExitAnchor ||
                nearbyLivePreferred ||
                (LokiPoe.Me != null &&
                 VoyageRunState.TryGetBestCapsule(
                     LokiPoe.Me.Position,
                     out preferredCapsule,
                     out preferredLanternDistance));
            if (_hasLockedExitAnchor)
            {
                preferredCapsule = _lockedExitAnchor;
                preferredLanternDistance =
                    VoyageRunState.GetNearestLanternDistance(
                        preferredCapsule);
            }
            else if (nearbyLivePreferred)
            {
                preferredCapsule = capsule.Position;
                preferredLanternDistance =
                    VoyageRunState.GetNearestLanternDistance(
                        preferredCapsule);
                AllflameLog.Throttled(
                    "capsule_live_nearby_preferred",
                    TimeSpan.FromSeconds(2),
                    "CAPSULE_TARGET_PREFERRED" +
                    "|Source=LiveTraversedWithin150" +
                    "|Position=" + preferredCapsule +
                    "|PlayerDistance=" +
                    LokiPoe.Me.Position.DistanceF(
                        preferredCapsule).ToString("0.0") +
                    "|NearestLanternDistance=" +
                    preferredLanternDistance.ToString("0.0") +
                    "|ReservedPreserved=" +
                    VoyageRunState.HasReservedExitCapsule);
            }
            if (extractionRequired &&
                !_hasLockedExitAnchor &&
                hasPreferredCapsule &&
                LokiPoe.Me != null &&
                preferredCapsule != default(Vector2i) &&
                LokiPoe.Me.Position.DistanceF(preferredCapsule) <=
                    VoyageRunState.CapsuleNearbyExitDistance)
            {
                LockExitAnchor(
                    preferredCapsule,
                    VoyageRunState.IsCapsuleProven(preferredCapsule),
                    "NearestTraversedWithin150",
                    true);
                preferredCapsule = _lockedExitAnchor;
                preferredLanternDistance =
                    VoyageRunState.GetNearestLanternDistance(
                        preferredCapsule);
            }
            bool forceLiveCapsule =
                _forceLiveCapsule &&
                capsule != null &&
                capsule.IsValid &&
                capsule.IsTargetable &&
                VoyageRunState.IsCapsuleTraversed(
                    capsule.Position);
            if (forceLiveCapsule)
            {
                VoyageRunState.RestoreLiveCapsuleForFailsafe(
                    capsule.Position,
                    _capsuleSearchHardFailsafeActive
                        ? "TotalSearchHardFailsafe"
                        : "RouteFailsafe");
                AllflameLog.Throttled(
                    "capsule_route_failsafe_live_override",
                    TimeSpan.FromSeconds(2),
                    "CAPSULE_TARGET_OVERRIDE" +
                    "|Live=" + capsule.Position +
                    "|Reason=RouteFailsafe" +
                    "|Action=UseNearestLiveTargetableCapsule");
                _confirmedCapsuleAnchor = capsule.Position;
                _hasConfirmedCapsuleAnchor = true;
                ResetRoute();
                ResetWatchedRouteAnchor();
            }
            else if (_capsuleSearchHardFailsafeActive)
            {
                capsule = null;
                _hasConfirmedCapsuleAnchor = false;
                _confirmedCapsuleAnchor = new Vector2i();
                ResetRoute();
                ResetWatchedRouteAnchor();
            }
            else if (hasPreferredCapsule &&
                (capsule == null ||
                 !capsule.IsValid ||
                 capsule.Position.DistanceF(preferredCapsule) > 25f))
            {
                if (capsule != null && capsule.IsValid)
                {
                    AllflameLog.Throttled(
                        "capsule_live_object_not_preferred",
                        TimeSpan.FromSeconds(2),
                        "CAPSULE_TARGET_REJECTED" +
                        "|Live=" + capsule.Position +
                        "|Preferred=" + preferredCapsule +
                        "|PreferredLanternDistance=" +
                        preferredLanternDistance.ToString("0.0") +
                        "|Reason=SaferRegisteredCapsuleAvailable");
                }
                capsule = null;
                _confirmedCapsuleAnchor = preferredCapsule;
                _hasConfirmedCapsuleAnchor = true;
            }
            else if (capsule != null &&
                     capsule.IsValid &&
                     !VoyageRunState.IsCapsuleUsable(
                         capsule.Position,
                         true))
            {
                bool blacklisted =
                    !VoyageRunState.IsCapsuleUsable(
                        capsule.Position,
                        false);
                bool traversed =
                    VoyageRunState.IsCapsuleTraversed(
                        capsule.Position);
                AllflameLog.Throttled(
                    "capsule_live_object_outside_lanternlight",
                    TimeSpan.FromSeconds(2),
                    "CAPSULE_TARGET_REJECTED" +
                    "|Live=" + capsule.Position +
                    "|NearestLanternDistance=" +
                    VoyageRunState.GetNearestLanternDistance(
                        capsule.Position).ToString("0.0") +
                    "|Reason=" +
                    (blacklisted
                        ? "PreviouslyMarkedUnusable"
                        : (!traversed
                            ? "NotPreviouslyTraversed"
                            : "OutsideLanternCoverage")));
                capsule = null;
            }
            bool visualProbeAllowed = _visualCapsuleUiOpen;
            if (!visualProbeAllowed &&
                _openAttempts > 0 &&
                _hasLockedExitAnchor &&
                LokiPoe.Me != null)
            {
                float lockedDistance = LokiPoe.Me.Position.DistanceF(
                    _lockedExitAnchor);
                CapsuleSafetySnapshot probeSafety =
                    VoyageCapsuleSafety.Evaluate(
                        LokiPoe.Me.Position,
                        _lockedExitAnchor,
                        "VisualProbeEligibility");
                bool routeMovementActive =
                    _safeRouteStartedUtc != DateTime.MinValue &&
                    (lockedDistance > 65f ||
                     !probeSafety.DirectActionAllowed);
                visualProbeAllowed = !routeMovementActive &&
                    lockedDistance <= 65f &&
                    probeSafety.PlayerCovered &&
                    probeSafety.SegmentCovered;
                if (!visualProbeAllowed)
                {
                    AllflameLog.Throttled(
                        "capsule_visual_probe_suspended",
                        TimeSpan.FromSeconds(2),
                        "CAPSULE_VISUAL_PROBE_SUSPENDED" +
                        "|LockedDistance=" +
                        lockedDistance.ToString("0.0") +
                        "|PlayerCovered=" +
                        probeSafety.PlayerCovered +
                        "|SegmentCovered=" +
                        probeSafety.SegmentCovered +
                        "|RouteMovementActive=" +
                        routeMovementActive +
                        "|VisualAttempts=" +
                        _callVisualDetectionAttempts);
                }
            }
            VisualCallProbe visualProbe =
                visualProbeAllowed
                    ? await ProbeVisualCallButton()
                    : null;
            bool visualCapsuleUiVisible =
                visualProbe != null && visualProbe.Confirmed;
            capsuleUiVisible = visualCapsuleUiVisible;
            _visualCapsuleUiOpen = visualCapsuleUiVisible;
            if (visualCapsuleUiVisible)
            {
                if (extractionRequired)
                {
                    MarkRescueExplicitProgress("CapsuleUiObservedByRunProbe");
                }
                if (extractionRequired &&
                    _zeroLanternStage !=
                        ZeroLanternExtractionStage.CallBathysphere &&
                    _zeroLanternStage !=
                        ZeroLanternExtractionStage.ConfirmCall)
                {
                    CompleteRescueApproachOnUiConfirmed();
                    BeginRescueStage(
                        ZeroLanternExtractionStage.CallBathysphere,
                        "VisualUiConfirmedByRunProbe");
                }
                AllflameLog.Throttled(
                    "capsule_ui_visual_override",
                    TimeSpan.FromSeconds(2),
                    "CAPSULE_UI_VISUAL_OVERRIDE" +
                    "|ContextVisible=False" +
                    "|Detected=True" +
                    "|Client=" + visualProbe.Location +
                    "|Correlation=" +
                    visualProbe.Correlation.ToString("0.000") +
                    "|Required=" +
                    visualProbe.RequiredCorrelation.ToString("0.000") +
                    "|Action=TreatAsOpened");
            }
            }

            if (extractionRequired && !cachedReturnUiReady)
            {
                AllflameContext.Refresh(true);
                if (!AllflameContext.LanternAuraActive)
                {
                    AllflameLog.Info(
                        "CAPSULE_ACTION_ABORTED_AURA_LOSS" +
                        "|Action=" +
                        (capsuleUiVisible ? "UiRecovery" : "Move") +
                        "|Anchor=" +
                        (_hasLockedExitAnchor
                            ? _lockedExitAnchor.ToString()
                            : "None"));
                    if (capsuleUiVisible)
                    {
                        await Coroutines.CloseBlockingWindows();
                        _visualCapsuleUiOpen = false;
                    }
                    await RunZeroLanternCapsuleRescue(settings);
                    return true;
                }
            }

            if (!capsuleUiVisible)
            {
                if (extractionRequired)
                {
                    return await RunZeroLanternCapsuleRescue(settings);
                }
                if (capsule == null ||
                    !capsule.IsValid ||
                    !capsule.IsTargetable)
                {
                    if (_capsuleSearchHardFailsafeActive)
                    {
                        TimeSpan hardFailsafeElapsed =
                            _capsuleHardFailsafeStartedUtc == DateTime.MinValue
                                ? TimeSpan.Zero
                                : DateTime.UtcNow -
                                  _capsuleHardFailsafeStartedUtc;
                        if (hardFailsafeElapsed >= TimeSpan.FromSeconds(25))
                        {
                            bool allowAnotherLiveSearch =
                                _capsuleHardFailsafeCycles <
                                MaximumRecoveryCycles;
                            _capsuleSearchHardFailsafeActive = false;
                            _capsuleHardFailsafeStartedUtc =
                                DateTime.MinValue;
                            _forceLiveCapsule = false;
                            _capsuleSearchStartedUtc = allowAnotherLiveSearch
                                ? DateTime.UtcNow
                                : DateTime.MinValue;
                            ResetRoute();
                            ResetWatchedRouteAnchor();
                            AllflameProgressWatchdog.MarkProgress(
                                "CapsuleSearchCycleReleased");
                            AllflameLog.Info(
                                "CAPSULE_SEARCH_RECOVERY" +
                                "|Reason=LiveTargetTimeout" +
                                "|ElapsedSeconds=" +
                                (int)hardFailsafeElapsed.TotalSeconds +
                                "|Cycle=" +
                                _capsuleHardFailsafeCycles +
                                "/" + MaximumRecoveryCycles +
                                "|Action=ReleaseToFreshFrontier" +
                                "|Retry=" + allowAnotherLiveSearch);
                            return false;
                        }

                        AllflameLog.Throttled(
                            "capsule_hard_failsafe_live_search",
                            TimeSpan.FromSeconds(2),
                            "CAPSULE_SEARCH_HARD_FAILSAFE" +
                            "|State=WaitingForLiveTargetableCapsule" +
                            "|ElapsedSeconds=" +
                            (int)hardFailsafeElapsed.TotalSeconds +
                            "|Cycle=" + _capsuleHardFailsafeCycles +
                            "/" + MaximumRecoveryCycles +
                            "|Action=DelegateToVoyagePlanner");
                        return false;
                    }
                    Vector2i remembered;
                    if (_hasConfirmedCapsuleAnchor)
                    {
                        remembered = _confirmedCapsuleAnchor;
                        RouteToRememberedCapsule(
                            remembered,
                            true);
                        return true;
                    }
                    if (LokiPoe.Me != null &&
                        VoyageRunState.TryGetNearestCapsule(
                            LokiPoe.Me.Position,
                            out remembered))
                    {
                        RouteToRememberedCapsule(
                            remembered,
                            false);
                        return true;
                    }

                    if (extractionRequired)
                    {
                        MoveToSafeExitRoute(
                            _hasLockedExitAnchor
                                ? _lockedExitAnchor
                                : new Vector2i());
                        return true;
                    }

                    AllflameLog.Throttled(
                        "capsule_frontier_search",
                        TimeSpan.FromSeconds(2),
                        "CAPSULE_SEARCH|Mode=UnvisitedFrontier" +
                        "|Reason=" +
                        (extractionRequired
                            ? extractionReason
                            : "InventoryThreshold") +
                        "|Action=DelegateToVoyagePlanner");
                    return false;
                }

                ResetRoute();
                VoyageRunState.RememberCapsule(capsule.Position);
                _confirmedCapsuleAnchor = capsule.Position;
                _hasConfirmedCapsuleAnchor = true;
                if (capsule.Distance >
                    Math.Max(70, settings.InteractDistance + 10))
                {
                    if (extractionRequired)
                    {
                        MoveToSafeExitRoute(capsule.Position);
                        return true;
                    }
                    bool moving =
                        MoveTowardsInteraction(
                        capsule.Position,
                        Name);
                    AllflameLog.Throttled(
                        "capsule_live_object_approach",
                        TimeSpan.FromSeconds(1),
                        "CAPSULE_APPROACH" +
                        "|Source=LiveTargetableObject" +
                        "|ObjectId=" + capsule.Id +
                        "|Target=" + capsule.Position +
                        "|Distance=" +
                        capsule.Distance.ToString("0.0") +
                        "|Moving=" + moving +
                        "|UiConfirmed=False");
                    return true;
                }

                if (DateTime.UtcNow < _nextActionUtc)
                {
                    return true;
                }
                _nextActionUtc =
                    DateTime.UtcNow.AddMilliseconds(500);
                if (extractionRequired)
                {
                    LockExitAnchor(
                        capsule.Position,
                        VoyageRunState.IsCapsuleProven(
                            capsule.Position),
                        "BeforeInteraction");
                    AllflameContext.Refresh(true);
                    CapsuleSafetySnapshot interactionSafety =
                        VoyageCapsuleSafety.Evaluate(
                            LokiPoe.Me == null
                                ? new Vector2i()
                                : LokiPoe.Me.Position,
                            capsule.Position,
                            "Interact");
                    bool lockedTarget =
                        _hasLockedExitAnchor &&
                        _lockedExitAnchor.DistanceF(
                            capsule.Position) <= 25f;
                    if (!interactionSafety.DirectActionAllowed ||
                        !lockedTarget)
                    {
                        LogCapsuleActionSafetyRejection(
                            interactionSafety,
                            "Interact",
                            "BeforeInteraction",
                            lockedTarget);
                        MoveToSafeExitRoute(capsule.Position);
                        return true;
                    }
                }
                await FinishMovementBeforeInteraction(
                    "Allflame Capsule");
                if (extractionRequired)
                {
                    AllflameContext.Refresh(true);
                    NetworkObject currentCapsule =
                        AllflameContext.CapsuleObject;
                    float interactionRange = Math.Max(
                        35f,
                        settings.InteractDistance + 12f);
                    float currentDistance =
                        LokiPoe.Me == null || currentCapsule == null
                            ? Single.MaxValue
                            : LokiPoe.Me.Position.DistanceF(
                                currentCapsule.Position);
                    bool objectReady =
                        currentCapsule != null &&
                        currentCapsule.IsValid &&
                        currentCapsule.IsTargetable;
                    bool lockedObjectMatches =
                        objectReady &&
                        _hasLockedExitAnchor &&
                        _lockedExitAnchor.DistanceF(
                            currentCapsule.Position) <= 25f;
                    if (!objectReady ||
                        !lockedObjectMatches ||
                        currentDistance > interactionRange)
                    {
                        AllflameLog.Info(
                            "CAPSULE_INTERACTION_REVALIDATION_REJECTED" +
                            "|ObjectValid=" +
                            (currentCapsule != null &&
                             currentCapsule.IsValid) +
                            "|ObjectTargetable=" +
                            (currentCapsule != null &&
                             currentCapsule.IsTargetable) +
                            "|Distance=" +
                            (currentDistance == Single.MaxValue
                                ? "Unavailable"
                                : currentDistance.ToString("0.0")) +
                            "|InteractionRange=" +
                            interactionRange.ToString("0.0") +
                            "|LockedTarget=" +
                            lockedObjectMatches +
                            "|OpenAttempts=" + _openAttempts +
                            "|Action=ReacquireWithoutCountingInput");
                        ResetMoverApproachState();
                        MoveToSafeExitRoute(
                            _hasLockedExitAnchor
                                ? _lockedExitAnchor
                                : capsule.Position);
                        return true;
                    }
                    capsule = currentCapsule;
                    CapsuleSafetySnapshot finalInteractionSafety =
                        VoyageCapsuleSafety.Evaluate(
                            LokiPoe.Me.Position,
                            capsule.Position,
                            "InteractFinalRevalidation");
                    if (!finalInteractionSafety.DirectActionAllowed ||
                        !_hasLockedExitAnchor ||
                        _lockedExitAnchor.DistanceF(
                            capsule.Position) > 25f)
                    {
                        LogCapsuleActionSafetyRejection(
                            finalInteractionSafety,
                            "Interact",
                            "FinalRevalidation",
                            _hasLockedExitAnchor &&
                            _lockedExitAnchor.DistanceF(
                                capsule.Position) <= 25f);
                        MoveToSafeExitRoute(capsule.Position);
                        return true;
                    }
                }
                bool inputAccepted =
                    await InteractWithRecovery(capsule);
                _openAttempts++;
                await LokiCoroutine.Sleep(250);
                VisualCallProbe openProbe =
                    await ProbeVisualCallButton();
                bool uiConfirmed = openProbe.Confirmed;
                AllflameLog.Info(
                    "CAPSULE_OPEN_VISUAL_PROBE" +
                    "|Found=" + uiConfirmed +
                    "|InputAcceptedIgnored=" + inputAccepted +
                    "|Client=" +
                    (uiConfirmed
                        ? openProbe.Location.ToString()
                        : "n/a") +
                    "|Correlation=" +
                    openProbe.Correlation.ToString("0.000") +
                    "|Required=" +
                    openProbe.RequiredCorrelation.ToString("0.000") +
                    "|OpenAttempt=" + _openAttempts +
                    "|VisualAttempt=" + openProbe.Attempt);
                AllflameLog.Info(
                    "VOYAGE_STAGE|Stage=7-8|Action=OpenCapsule" +
                    "|InputAccepted=" + inputAccepted +
                    "|UiConfirmed=" + uiConfirmed +
                    "|Attempt=" + _openAttempts +
                    "|Position=" + capsule.Position);
                if (uiConfirmed)
                {
                    _visualCapsuleUiOpen = true;
                    _openAttempts = 0;
                    _openRecoveryCycles = 0;
                    _confirmedCapsuleAnchor = capsule.Position;
                    _hasConfirmedCapsuleAnchor = true;
                    VoyageRunState.MarkCapsuleProven(
                        capsule.Position);
                    if (extractionRequired)
                    {
                        LockExitAnchor(
                            capsule.Position,
                            true,
                            "CapsuleUiConfirmed");
                    }
                }
                else if (_openAttempts >= 3)
                {
                    _openAttempts = 0;
                    float lanternDistance =
                        VoyageRunState.GetNearestLanternDistance(
                            capsule.Position);
                    bool recoverInPlace =
                        extractionRequired &&
                        _hasLockedExitAnchor &&
                        _lockedExitAnchor.DistanceF(
                            capsule.Position) <= 25f;
                    if (recoverInPlace)
                    {
                        _openRecoveryCycles++;
                        AllflameLog.Info(
                            "CAPSULE_UI_RECOVERY_IN_PLACE" +
                            "|Attempt=3" +
                            "|Cycle=" + _openRecoveryCycles + "/" +
                            MaximumRecoveryCycles +
                            "|Anchor=" + _lockedExitAnchor);
                        if (_openRecoveryCycles >=
                            MaximumRecoveryCycles)
                        {
                            StopSafeExit(
                                "CapsuleOpenUnconfirmedAfterNineInputs");
                        }
                    }
                    else
                    {
                        VoyageRunState.MarkCapsuleUnusable(
                            capsule.Position,
                            "ThreeInputsWithoutStrongCapsuleUiEvidence");
                        _confirmedCapsuleAnchor = new Vector2i();
                        _hasConfirmedCapsuleAnchor = false;
                        _forceLiveCapsule = false;
                    }
                    ResetRoute();
                    await Coroutines.CloseBlockingWindows();
                    _nextActionUtc =
                        DateTime.UtcNow.AddMilliseconds(450);
                    AllflameLog.Info(
                        "CAPSULE_OPEN_RECOVERY" +
                        "|Reason=ThreeInputsWithoutStrongCapsuleUiEvidence" +
                        "|AnchorRejected=" +
                        capsule.Position +
                        "|NearestLanternDistance=" +
                        lanternDistance.ToString("0.0") +
                        "|Action=" +
                        (recoverInPlace
                            ? "ReopenLockedExitAnchor"
                            : "SelectAnotherTraversedCapsule"));
                }
                return true;
            }

            if (capsule != null &&
                capsule.IsValid)
            {
                _confirmedCapsuleAnchor = capsule.Position;
                _hasConfirmedCapsuleAnchor = true;
            }
            else if (!_hasConfirmedCapsuleAnchor &&
                     _hasRouteTarget)
            {
                _confirmedCapsuleAnchor = _routeTarget;
                _hasConfirmedCapsuleAnchor = true;
            }
            ResetRoute();

            if (DateTime.UtcNow < _nextActionUtc)
            {
                return true;
            }

            // At 0/x, returning alive is the absolute priority. Sending loot
            // is handled independently at the inventory/two-bottle triggers;
            // it must never block Call Bathysphere or stop the bot here.
            bool transferEnabled =
                !extractionRequired &&
                (AllflameVoyageDebug.SendToSurfaceRequested ||
                 settings.SendLootToSurface ||
                 VoyageRunState.BottleSurfaceTransferPending);
            if (extractionRequired &&
                (settings.AlwaysSendBeforeVoyageExtraction ||
                 VoyageRunState.BottleSurfaceTransferPending))
            {
                AllflameLog.Throttled(
                    "capsule_extraction_call_priority",
                    TimeSpan.FromSeconds(5),
                    "CAPSULE_EXTRACTION_PRIORITY" +
                    "|Action=SkipTransferAndCallBathysphere" +
                    "|Reason=" + extractionReason +
                    "|PendingBottleTransfer=" +
                    VoyageRunState.BottleSurfaceTransferPending +
                    "|InventoryFreeSquares=" +
                    AllflameContext.InventoryFreeSquares);
            }
            if (transferEnabled && _pendingTransferLocalId != 0)
            {
                Item remaining = FindInventoryItemByLocalId(
                    _pendingTransferLocalId);
                bool confirmed = remaining == null ||
                    Math.Max(1, remaining.StackCount) <
                        _pendingTransferBeforeStack;
                if (confirmed)
                {
                    _batchHadItems = true;
                    _surfaceSentForRequest = false;
                    _sendAttempts = 0;
                    _transferFailures = 0;
                    _transferRecoveryCycles = 0;
                    AllflameProgressWatchdog.MarkProgress(
                        "CapsuleInventoryItemTransferred");
                    AllflameLog.Info(
                        "CAPSULE_TRANSFER_CONFIRMED" +
                        "|LocalId=" + _pendingTransferLocalId +
                        "|BeforeStack=" +
                        _pendingTransferBeforeStack +
                        "|Remaining=" + (remaining == null
                            ? 0
                            : Math.Max(1, remaining.StackCount)) +
                        "|OneActionPerCycle=True");
                    ClearPendingTransfer();
                    return true;
                }
                if (DateTime.UtcNow - _pendingTransferIssuedUtc <
                    TimeSpan.FromMilliseconds(900))
                {
                    return true;
                }
                _transferFailures++;
                AllflameLog.Info(
                    "CAPSULE_TRANSFER_REJECTED" +
                    "|LocalId=" + _pendingTransferLocalId +
                    "|FailureCount=" + _transferFailures +
                    "|Reason=SourceItemUnchanged" +
                    "|Action=RetryFreshSnapshot");
                ClearPendingTransfer();
                return true;
            }

            transferable = transferEnabled
                ? GetTransferableInventoryItem()
                : null;
            if (transferEnabled &&
                transferable != null)
            {
                _nextActionUtc =
                    DateTime.UtcNow.AddMilliseconds(180);
                bool submitted =
                    await CtrlClickInventoryItem(transferable);
                if (submitted)
                {
                    _pendingTransferLocalId =
                        transferable.LocalId;
                    _pendingTransferBeforeStack = Math.Max(
                        1,
                        transferable.StackCount);
                    _pendingTransferIssuedUtc = DateTime.UtcNow;
                }
                else
                {
                    _transferFailures++;
                }
                AllflameLog.Info(
                    "CAPSULE_TRANSFER_ITEM|Id=" + transferable.Id +
                    "|Name=" +
                    (transferable.FullName ?? transferable.Name) +
                    "|Submitted=" + submitted +
                    "|FailureCount=" + _transferFailures +
                    "|Action=ReturnToTaskManager");
                if (!submitted && _transferFailures >= 3)
                {
                    _transferFailures = 0;
                    _transferRecoveryCycles++;
                    _nextActionUtc =
                        DateTime.UtcNow.AddMilliseconds(650);
                    await Coroutines.CloseBlockingWindows();
                    AllflameLog.Info(
                        "CAPSULE_TRANSFER_RECOVERY" +
                        "|Action=CloseAndReopenCapsule" +
                        "|Reason=ThreeFailedVerifiedTransfers" +
                        "|RecoveryCycle=" +
                        _transferRecoveryCycles + "/" +
                        MaximumRecoveryCycles);
                    if (_transferRecoveryCycles >=
                        MaximumRecoveryCycles)
                    {
                        bool mustStop =
                            extractionRequired ||
                            AllflameContext
                                .InventoryFreeSquares <= 0;
                        if (mustStop)
                        {
                            AllflameStopController.Stop(
                                "CapsuleTransferFailed",
                                "VerifiedCtrlClickFailures=9" +
                                "|LootWasNotSent" +
                                "|InventoryFreeSquares=" +
                                AllflameContext
                                    .InventoryFreeSquares +
                                "|ExtractionRequired=" +
                                extractionRequired +
                                "|Action=StopForManualRecovery");
                        }
                        else
                        {
                            _surfaceTransferBackoffUtc =
                                DateTime.UtcNow.AddSeconds(30);
                            VoyageRunState
                                .SurfaceTransferPending = false;
                            AllflameLog.Info(
                                "CAPSULE_TRANSFER_DEFERRED" +
                                "|Reason=VerifiedCtrlClickFailures9" +
                                "|InventoryFreeSquares=" +
                                AllflameContext
                                    .InventoryFreeSquares +
                                "|RetryAfterSeconds=30" +
                                "|Action=ResumeVoyageExploration");
                            ResetRequest();
                        }
                    }
                }
                return true;
            }

            if (transferEnabled &&
                transferable == null &&
                _transferFailures > 0)
            {
                // A DPB inventory snapshot can trail a successful Ctrl-click.
                // If the source item is gone on the next task pass, preserve
                // the send debt instead of incorrectly treating the Capsule
                // as empty and proceeding directly to Call Bathysphere.
                _batchHadItems = true;
                if (_surfaceSentForRequest)
                {
                    _surfaceSentForRequest = false;
                    _sendAttempts = 0;
                }
                _transferFailures = 0;
                AllflameLog.Info(
                    "CAPSULE_TRANSFER_ITEM" +
                    "|Success=True" +
                    "|Confirmation=DeferredSourceDisappearance");
            }

            bool sendRequired =
                transferEnabled &&
                _batchHadItems &&
                !_surfaceSentForRequest;
            if (sendRequired)
            {
                if (AllflameSettings.Instance.UseNativeCapsuleActions &&
                    !_nativeSendAttempted)
                {
                    _nativeSendAttempted = true;
                    DpbActionResult nativeSend =
                        DpbNativeApi.SendToSurface();
                    bool nativeAcknowledged = false;
                    string nativeConfirmation = "None";
                    if (nativeSend.InputSent)
                    {
                        await LokiCoroutine.Sleep(350);
                        AllflameContext.Refresh(true);
                        nativeAcknowledged =
                            TryConfirmNativeCapsuleSend(
                                out nativeConfirmation);
                        nativeSend.PostconditionVerified =
                            nativeAcknowledged;
                    }
                    AllflameLog.Info(
                        "CAPSULE_NATIVE_ACTION" +
                        "|Action=SendToSurface" +
                        "|InputSent=" + nativeSend.InputSent +
                        "|Postcondition=" + nativeAcknowledged +
                        "|Confirmation=" + nativeConfirmation +
                        "|Reason=" + nativeSend.Reason +
                        "|Exception=" + nativeSend.Exception);
                    if (nativeAcknowledged)
                    {
                        _surfaceSentForRequest = true;
                        _batchHadItems = false;
                        _sendRecoveryCycles = 0;
                        VoyageRunState.MarkSurfaceSent();
                        AllflameVoyageDebug.CompleteSendToSurface(
                            "NativeAcknowledged:" + nativeConfirmation);
                        if (!extractionRequired)
                        {
                            await Coroutines.CloseBlockingWindows();
                            ResetRequest();
                        }
                        return true;
                    }
                    if (nativeSend.InputSent)
                    {
                        _nativeSendFallbackArmed = true;
                        _nextActionUtc =
                            DateTime.UtcNow.AddMilliseconds(200);
                        AllflameLog.Info(
                            "UI_FALLBACK" +
                            "|Task=" + Name +
                            "|From=Native" +
                            "|To=Element" +
                            "|Reason=SendPostconditionUnverified" +
                            "|Action=RetryNextCycle");
                        return true;
                    }
                    AllflameLog.Info(
                        "UI_FALLBACK" +
                        "|Task=" + Name +
                        "|From=Native" +
                        "|To=Element" +
                        "|Reason=" + nativeSend.Reason);
                }
                if (_nativeSendFallbackArmed)
                {
                    _nativeSendFallbackArmed = false;
                    AllflameLog.Info(
                        "CAPSULE_NATIVE_FALLBACK" +
                        "|Action=SendToSurface" +
                        "|Mode=StableElement" +
                        "|InputSent=False" +
                        "|Postcondition=False" +
                        "|Reason=NativeAttemptAlreadyVerifiedUncertain");
                }
                Element sendButton;
                string sendDetectionMode;
                bool sendFound =
                    CapsuleDirectUi.TryGetButton(
                        CapsuleUiAction.SendToSurface,
                        true,
                        out sendButton,
                        out sendDetectionMode) &&
                    CapsuleDirectUi.IsEnabled(sendButton);
                if (!sendFound)
                {
                    if (_sendButtonMissingUtc == DateTime.MinValue)
                    {
                        _sendButtonMissingUtc = DateTime.UtcNow;
                    }
                    AllflameLog.Throttled(
                        "capsule_send_button_missing",
                        TimeSpan.FromSeconds(2),
                        "CAPSULE_UI_WAIT|Missing=SendToSurface" +
                        "|BatchHadItems=True");
                    if (DateTime.UtcNow - _sendButtonMissingUtc >=
                        TimeSpan.FromSeconds(3))
                    {
                        _sendButtonMissingUtc = DateTime.MinValue;
                        _sendRecoveryCycles++;
                        await Coroutines.CloseBlockingWindows();
                        _nextActionUtc =
                            DateTime.UtcNow.AddMilliseconds(650);
                        AllflameLog.Info(
                            "CAPSULE_UI_RECOVERY" +
                            "|Reason=SendButtonMissingFor3Seconds" +
                            "|Action=CloseAndReopen" +
                            "|RecoveryCycle=" +
                            _sendRecoveryCycles + "/" +
                            MaximumRecoveryCycles);
                        if (_sendRecoveryCycles >=
                            MaximumRecoveryCycles)
                        {
                            AllflameStopController.Stop(
                                "CapsuleSendUnavailable",
                                "SendButtonMissingAcrossThreeReopens" +
                                "|LootWasNotSent" +
                                "|Action=StopForManualRecovery");
                        }
                    }
                    return true;
                }
                _sendButtonMissingUtc = DateTime.MinValue;

                _nextActionUtc =
                    DateTime.UtcNow.AddMilliseconds(700);
                int beforeContainerCount;
                bool beforeCountKnown =
                    TryGetCapsuleContainerItemCount(
                        out beforeContainerCount) &&
                    beforeContainerCount > 0;
                Element confirmedSendButton;
                string confirmedSendMode;
                bool sendRevalidated =
                    CapsuleDirectUi.TryGetButton(
                        CapsuleUiAction.SendToSurface,
                        true,
                        out confirmedSendButton,
                        out confirmedSendMode) &&
                    CapsuleDirectUi.IsEnabled(
                        confirmedSendButton);
                bool inputSent =
                    sendRevalidated &&
                    VoyagePlanningUi.Click(confirmedSendButton);
                sendDetectionMode = sendRevalidated
                    ? confirmedSendMode
                    : sendDetectionMode;
                _sendAttempts++;
                int sendAttemptForLog = _sendAttempts;
                bool acknowledged = false;
                string confirmation = "None";
                if (inputSent)
                {
                    await LokiCoroutine.Sleep(350);
                    AllflameContext.Refresh(true);
                    int afterContainerCount;
                    bool afterCountKnown =
                        TryGetCapsuleContainerItemCount(
                            out afterContainerCount);
                    if (!AllflameContext.CapsuleUiVisible ||
                        !AllflameContext.SendToSurfaceVisible)
                    {
                        acknowledged = true;
                        confirmation = "UiTransition";
                    }
                    else if (beforeCountKnown &&
                             afterCountKnown &&
                             afterContainerCount == 0)
                    {
                        acknowledged = true;
                        confirmation = "ContainerEmptied";
                    }
                }
                if (acknowledged)
                {
                    _surfaceSentForRequest = true;
                    _batchHadItems = false;
                    _sendRecoveryCycles = 0;
                    VoyageRunState.MarkSurfaceSent();
                    AllflameVoyageDebug.CompleteSendToSurface(
                        "Acknowledged:" + confirmation);
                }
                AllflameLog.Info(
                    "CAPSULE_UI_ELEMENT_CLICK" +
                    "|Action=SendToSurface" +
                    "|Detection=" + sendDetectionMode +
                    "|InputSent=" + inputSent +
                    "|Acknowledged=" + acknowledged +
                    "|Confirmation=" + confirmation);
                AllflameLog.Info(
                    "VOYAGE_STAGE|Stage=7|Action=SendToSurface" +
                    "|InputSent=" + inputSent +
                    "|Acknowledged=" + acknowledged +
                    "|Confirmation=" + confirmation +
                    "|Detection=" + sendDetectionMode +
                    "|Attempt=" + sendAttemptForLog +
                    "|ExtractionPending=" + extractionRequired);
                if (acknowledged)
                {
                    _sendAttempts = 0;
                }
                if (!acknowledged && _sendAttempts >= 3)
                {
                    _sendAttempts = 0;
                    _sendRecoveryCycles++;
                    await Coroutines.CloseBlockingWindows();
                    _nextActionUtc =
                        DateTime.UtcNow.AddMilliseconds(650);
                    AllflameLog.Info(
                        "CAPSULE_UI_RECOVERY" +
                        "|Reason=SendNotAcknowledgedAfter3Attempts" +
                        "|Action=CloseAndReopen" +
                        "|ContainerCountKnown=" +
                        beforeCountKnown +
                        "|RecoveryCycle=" +
                        _sendRecoveryCycles + "/" +
                        MaximumRecoveryCycles);
                    if (_sendRecoveryCycles >=
                        MaximumRecoveryCycles)
                    {
                        AllflameStopController.Stop(
                            "CapsuleSendUnconfirmed",
                            "NineClicksWithoutSemanticAcknowledgement" +
                            "|LootWasNotConfirmedSent" +
                            "|Action=StopForManualRecovery");
                    }
                    return true;
                }
                if (acknowledged && !extractionRequired)
                {
                    await Coroutines.CloseBlockingWindows();
                    ResetRequest();
                }
                return true;
            }

            if (extractionRequired)
            {
                if (AllflameSettings.Instance.UseNativeCapsuleActions &&
                    !_nativeCallAttempted)
                {
                    _nativeCallAttempted = true;
                    DpbActionResult nativeCall =
                        DpbNativeApi.CallBathysphere();
                    bool nativeAcknowledged = false;
                    string nativeConfirmation = "None";
                    if (nativeCall.InputSent)
                    {
                        await LokiCoroutine.Sleep(500);
                        AllflameContext.Refresh(true);
                        nativeAcknowledged =
                            TryConfirmNativeCapsuleCall(
                                out nativeConfirmation);
                        nativeCall.PostconditionVerified =
                            nativeAcknowledged;
                    }
                    AllflameLog.Info(
                        "CAPSULE_NATIVE_ACTION" +
                        "|Action=CallBathysphere" +
                        "|InputSent=" + nativeCall.InputSent +
                        "|Postcondition=" + nativeAcknowledged +
                        "|Confirmation=" + nativeConfirmation +
                        "|Reason=" + nativeCall.Reason +
                        "|Exception=" + nativeCall.Exception);
                    if (nativeAcknowledged)
                    {
                        _visualCapsuleUiOpen = false;
                        await Coroutines.CloseBlockingWindows();
                        _callRecoveryCycles = 0;
                        VoyageRunState.SurfaceTransferPending = false;
                        VoyageRunState.MarkCallIssued();
                        MarkZeroLanternCallConfirmed();
                        ResetRequest();
                        return true;
                    }
                    if (nativeCall.InputSent)
                    {
                        _nativeCallFallbackArmed = true;
                        _nextActionUtc =
                            DateTime.UtcNow.AddMilliseconds(200);
                        AllflameLog.Info(
                            "UI_FALLBACK" +
                            "|Task=" + Name +
                            "|From=Native" +
                            "|To=ElementOrVisual" +
                            "|Reason=CallPostconditionUnverified" +
                            "|Action=RetryNextCycle");
                        return true;
                    }
                    AllflameLog.Info(
                        "UI_FALLBACK" +
                        "|Task=" + Name +
                        "|From=Native" +
                        "|To=ElementOrVisual" +
                        "|Reason=" + nativeCall.Reason);
                }
                if (_nativeCallFallbackArmed)
                {
                    _nativeCallFallbackArmed = false;
                    AllflameLog.Info(
                        "CAPSULE_NATIVE_FALLBACK" +
                        "|Action=CallBathysphere" +
                        "|Mode=ElementOrVisual" +
                        "|InputSent=False" +
                        "|Postcondition=False" +
                        "|Reason=NativeAttemptAlreadyVerifiedUncertain");
                }
                if (UseDirectDpbCallUi)
                {
                    Element firstDirectCall;
                    string firstDirectMode;
                    bool firstDirectFound =
                        CapsuleDirectUi.TryGetButton(
                            CapsuleUiAction.CallBathysphere,
                            true,
                            out firstDirectCall,
                            out firstDirectMode) &&
                        CapsuleDirectUi.IsEnabled(firstDirectCall);
                    if (firstDirectFound)
                    {
                        Vector2i firstDirectLocation;
                        try
                        {
                            firstDirectLocation =
                                firstDirectCall.CenterClickLocation();
                        }
                        catch
                        {
                            firstDirectFound = false;
                            firstDirectLocation = new Vector2i();
                        }

                        if (firstDirectFound)
                        {
                            await LokiCoroutine.Sleep(120);
                            Element secondDirectCall;
                            string secondDirectMode;
                            bool secondDirectFound =
                                CapsuleDirectUi.TryGetButton(
                                    CapsuleUiAction.CallBathysphere,
                                    true,
                                    out secondDirectCall,
                                    out secondDirectMode) &&
                                CapsuleDirectUi.IsEnabled(
                                    secondDirectCall);
                            Vector2i secondDirectLocation =
                                new Vector2i();
                            if (secondDirectFound)
                            {
                                try
                                {
                                    secondDirectLocation =
                                        secondDirectCall
                                            .CenterClickLocation();
                                }
                                catch
                                {
                                    secondDirectFound = false;
                                }
                            }

                            int directDrift =
                                secondDirectFound
                                    ? Math.Abs(
                                          secondDirectLocation.X -
                                          firstDirectLocation.X) +
                                      Math.Abs(
                                          secondDirectLocation.Y -
                                          firstDirectLocation.Y)
                                    : Int32.MaxValue;
                            bool directConfirmed =
                                secondDirectFound &&
                                directDrift <= 10;
                            AllflameLog.Info(
                                "CAPSULE_CALL_DPB_CONFIRM" +
                                "|Confirmed=" + directConfirmed +
                                "|FirstMode=" + firstDirectMode +
                                "|SecondMode=" +
                                (secondDirectFound
                                    ? secondDirectMode
                                    : "None") +
                                "|FirstClient=" +
                                firstDirectLocation +
                                "|SecondClient=" +
                                (secondDirectFound
                                    ? secondDirectLocation.ToString()
                                    : "n/a") +
                                "|Drift=" +
                                (secondDirectFound
                                    ? directDrift.ToString()
                                    : "n/a"));
                            if (directConfirmed)
                            {
                            _callButtonMissingUtc =
                                DateTime.MinValue;
                            _nextActionUtc =
                                DateTime.UtcNow
                                    .AddMilliseconds(900);
                            if (!CanUseLockedCapsuleUi(
                                "DirectCallFinalRevalidation"))
                            {
                                return true;
                            }
                            bool inputSent =
                                VoyagePlanningUi.Click(
                                    secondDirectCall);
                            _callAttempts++;
                            int callAttemptForLog =
                                _callAttempts;
                            bool acknowledged = false;
                            bool warningOkClicked = false;
                            string warningMode = "None";
                            double warningCorrelation = -1.0;
                            if (inputSent)
                            {
                                await LokiCoroutine.Sleep(350);
                                Vector2i warningOkLocation;
                                warningOkClicked =
                                    TryConfirmCapsuleWarning(
                                        out warningMode,
                                        out warningOkLocation,
                                        out warningCorrelation);
                                if (warningOkClicked)
                                {
                                    await LokiCoroutine.Sleep(500);
                                }

                                AllflameContext.Refresh(true);
                                acknowledged =
                                    AllflameContext
                                        .ExtractionAvailable ||
                                    AllflameContext
                                        .BathysphereCallObserved ||
                                    warningOkClicked;
                                if (acknowledged)
                                {
                                    _visualCapsuleUiOpen = false;
                                    await Coroutines
                                        .CloseBlockingWindows();
                                    _callRecoveryCycles = 0;
                                    VoyageRunState
                                        .SurfaceTransferPending =
                                        false;
                                    VoyageRunState.MarkCallIssued();
                                    MarkZeroLanternCallConfirmed();
                                }
                            }

                            AllflameLog.Info(
                                "CAPSULE_UI_ELEMENT_CLICK" +
                                "|Action=CallBathysphere" +
                                "|Detection=" +
                                secondDirectMode +
                                "|Client=" +
                                secondDirectLocation +
                                "|InputSent=" + inputSent +
                                "|Acknowledged=" + acknowledged +
                                "|WarningOkClicked=" +
                                warningOkClicked +
                                "|WarningMode=" + warningMode);
                            AllflameLog.Info(
                                "VOYAGE_STAGE" +
                                "|Stage=8" +
                                "|Action=CallBathysphere" +
                                "|InputSent=" + inputSent +
                                "|Acknowledged=" +
                                acknowledged +
                                "|Detection=" +
                                secondDirectMode +
                                "|Client=" +
                                secondDirectLocation +
                                "|WarningOkClicked=" +
                                warningOkClicked +
                                "|WarningMode=" + warningMode +
                                "|WarningCorrelation=" +
                                (warningCorrelation >= 0
                                    ? warningCorrelation
                                        .ToString("0.000")
                                    : "n/a") +
                                "|Attempt=" +
                                callAttemptForLog +
                                "|Anchor=" +
                                VoyageRunState.CapsuleAnchor);
                            if (acknowledged)
                            {
                                _callAttempts = 0;
                                ResetRequest();
                            }
                            else if (_callAttempts >= 3)
                            {
                                _callAttempts = 0;
                                _callRecoveryCycles++;
                                LogUiRecoveryInPlace();
                                if (!_capsuleReturnUiConfirmed)
                                {
                                    await Coroutines
                                        .CloseBlockingWindows();
                                }
                                _nextActionUtc =
                                    DateTime.UtcNow
                                        .AddMilliseconds(650);
                                AllflameLog.Info(
                                    "CAPSULE_UI_RECOVERY" +
                                    "|Reason=" +
                                    "DirectCallNotAcknowledgedAfter3Attempts" +
                                    "|Action=" +
                                    (_capsuleReturnUiConfirmed
                                        ? "KeepCachedCapsuleUiOpen"
                                        : "CloseAndReopen") +
                                    "|RecoveryCycle=" +
                                    _callRecoveryCycles + "/" +
                                    MaximumRecoveryCycles);
                                if (_callRecoveryCycles >=
                                    MaximumRecoveryCycles)
                                {
                                    HandleCapsuleUiFailure(
                                        "BathysphereCallUnconfirmed",
                                        "NineDirectClicksWithoutSemanticAcknowledgement" +
                                        "|Action=RotateRescueStrategy");
                                }
                            }
                                return true;
                            }
                        }
                    }
                }

                VisualCallProbe callVisualProbe =
                    await ProbeVisualCallButton();
                if (callVisualProbe.Confirmed)
                {
                    Vector2i callVisualLocation =
                        callVisualProbe.Location;
                    double callVisualCorrelation =
                        callVisualProbe.Correlation;
                    _callButtonMissingUtc = DateTime.MinValue;
                    _nextActionUtc =
                        DateTime.UtcNow.AddMilliseconds(900);
                    if (!CanUseLockedCapsuleUi(
                        "VisualCallFinalRevalidation"))
                    {
                        return true;
                    }
                    bool inputSent =
                        CapsuleVisualUi.ClickCall(
                            callVisualLocation,
                            _callAttempts + 1);
                    _callAttempts++;
                    int callAttemptForLog = _callAttempts;
                    bool acknowledged = false;
                    bool warningOkClicked = false;
                    string warningMode = "None";
                    double warningCorrelation = -1.0;
                    if (inputSent)
                    {
                        await LokiCoroutine.Sleep(350);
                        Vector2i warningOkLocation;
                        warningOkClicked =
                            TryConfirmCapsuleWarning(
                                out warningMode,
                                out warningOkLocation,
                                out warningCorrelation);
                        if (warningOkClicked)
                        {
                            await LokiCoroutine.Sleep(500);
                        }
                        Vector2i afterFirstLocation;
                        double afterFirstCorrelation;
                        bool afterFirstVisible =
                            CapsuleVisualUi.TryFindCallButton(
                                out afterFirstLocation,
                                out afterFirstCorrelation,
                                callVisualProbe.RequiredCorrelation);
                        await LokiCoroutine.Sleep(140);
                        Vector2i afterSecondLocation;
                        double afterSecondCorrelation;
                        bool afterSecondVisible =
                            CapsuleVisualUi.TryFindCallButton(
                                out afterSecondLocation,
                                out afterSecondCorrelation,
                                callVisualProbe.RequiredCorrelation);
                        bool visuallyDisappeared =
                            !afterFirstVisible &&
                            !afterSecondVisible;
                        acknowledged = visuallyDisappeared;
                        AllflameLog.Info(
                            "CAPSULE_CALL_VISUAL_ACK" +
                            "|Acknowledged=" + acknowledged +
                            "|WarningOkClicked=" +
                            warningOkClicked +
                            "|FirstVisible=" +
                            afterFirstVisible +
                            "|SecondVisible=" +
                            afterSecondVisible +
                            "|FirstCorrelation=" +
                            afterFirstCorrelation.ToString("0.000") +
                            "|SecondCorrelation=" +
                            afterSecondCorrelation.ToString("0.000") +
                            "|Required=" +
                            callVisualProbe.RequiredCorrelation
                                .ToString("0.000"));
                        if (!acknowledged)
                        {
                            AllflameLog.Info(
                                "CAPSULE_CALL_UNCONFIRMED" +
                                "|Reason=VisualButtonStillPresentOrUnstable" +
                                "|Action=DoNotAdvanceToExtraction" +
                                "|Attempt=" + _callAttempts);
                        }
                        if (acknowledged)
                        {
                            _visualCapsuleUiOpen = false;
                            await Coroutines.CloseBlockingWindows();
                            _callRecoveryCycles = 0;
                            VoyageRunState.SurfaceTransferPending =
                                false;
                            VoyageRunState.MarkCallIssued();
                            MarkZeroLanternCallConfirmed();
                        }
                    }
                    AllflameLog.Info(
                        "VOYAGE_STAGE|Stage=8|Action=CallBathysphere" +
                        "|InputSent=" + inputSent +
                        "|Acknowledged=" + acknowledged +
                        "|Detection=VisualTemplateOnly" +
                        "|VisualCorrelation=" +
                        callVisualCorrelation.ToString("0.000") +
                        "|Required=" +
                        callVisualProbe.RequiredCorrelation
                            .ToString("0.000") +
                        "|WarningOkClicked=" +
                        warningOkClicked +
                        "|WarningMode=" + warningMode +
                        "|WarningCorrelation=" +
                        (warningCorrelation >= 0
                            ? warningCorrelation.ToString("0.000")
                            : "n/a") +
                        "|Attempt=" + callAttemptForLog +
                        "|Anchor=" +
                        VoyageRunState.CapsuleAnchor);
                    if (acknowledged)
                    {
                        _callAttempts = 0;
                        ResetRequest();
                    }
                    else if (_callAttempts >= 3)
                    {
                        _callAttempts = 0;
                        _callRecoveryCycles++;
                        LogUiRecoveryInPlace();
                        if (!_capsuleReturnUiConfirmed)
                        {
                            await Coroutines.CloseBlockingWindows();
                        }
                        _nextActionUtc =
                            DateTime.UtcNow.AddMilliseconds(650);
                        AllflameLog.Info(
                            "CAPSULE_UI_RECOVERY" +
                            "|Reason=CallNotAcknowledgedAfter3Attempts" +
                            "|Action=" +
                            (_capsuleReturnUiConfirmed
                                ? "KeepCachedCapsuleUiOpen"
                                : "CloseAndReopen") +
                            "|RecoveryCycle=" +
                            _callRecoveryCycles + "/" +
                            MaximumRecoveryCycles);
                        if (_callRecoveryCycles >=
                            MaximumRecoveryCycles)
                        {
                            HandleCapsuleUiFailure(
                                "BathysphereCallUnconfirmed",
                                "NineClicksWithoutVisualAcknowledgement" +
                                "|Action=RotateRescueStrategy");
                        }
                    }
                    return true;
                }

                if (_callButtonMissingUtc == DateTime.MinValue)
                {
                    _callButtonMissingUtc = DateTime.UtcNow;
                }
                AllflameLog.Throttled(
                    "capsule_call_button_missing",
                    TimeSpan.FromSeconds(2),
                    "CAPSULE_UI_WAIT|Missing=CallBathysphere" +
                    "|LanternsExhausted=True" +
                    "|SurfaceSent=" +
                    _surfaceSentForRequest);
                if (DateTime.UtcNow - _callButtonMissingUtc >=
                    TimeSpan.FromSeconds(3))
                {
                    _callButtonMissingUtc = DateTime.MinValue;
                    _callAttempts = 0;
                    _callRecoveryCycles++;
                    LogUiRecoveryInPlace();
                    if (!_capsuleReturnUiConfirmed)
                    {
                        await Coroutines.CloseBlockingWindows();
                    }
                    _nextActionUtc =
                        DateTime.UtcNow.AddMilliseconds(650);
                    AllflameLog.Info(
                        "CAPSULE_UI_RECOVERY" +
                        "|Reason=CallButtonMissingFor3Seconds" +
                        "|Action=" +
                        (_capsuleReturnUiConfirmed
                            ? "KeepCachedCapsuleUiOpen"
                            : "CloseAndReopen") +
                        "|RecoveryCycle=" +
                        _callRecoveryCycles + "/" +
                        MaximumRecoveryCycles);
                    if (_callRecoveryCycles >=
                        MaximumRecoveryCycles)
                    {
                        HandleCapsuleUiFailure(
                            "BathysphereCallUnavailable",
                            "CallButtonMissingAcrossThreeReopens" +
                            "|Action=RotateRescueStrategy");
                    }
                }
                return true;
            }

            // The threshold can disappear if another task or the game moves
            // the last item while the Capsule is opening. Do not leave the
            // Voyage paused with a blocking Capsule window in that case.
            VoyageRunState.SurfaceTransferPending = false;
            VoyageRunState.SectorBoundaryReached = false;
            await Coroutines.CloseBlockingWindows();
            AllflameLog.Info(
                "CAPSULE_TRANSFER_COMPLETE|Sent=False" +
                "|Reason=NoTransferableItems");
            AllflameVoyageDebug.CompleteSendToSurface(
                "NoTransferableItems");
            ResetRequest();
            return true;
        }

        private async Task<bool> RunZeroLanternCapsuleRescue(
            AllflameSettings settings)
        {
            if (!VoyageRunState.LanternsExhausted ||
                AllflameStopController.StopRequested)
            {
                return false;
            }
            if (LokiPoe.Me == null)
            {
                AllflameLog.Throttled(
                    "capsule_rescue_runtime_unavailable",
                    TimeSpan.FromSeconds(2),
                    "CAPSULE_RESCUE_WAIT|Reason=PlayerUnavailable" +
                    "|AreaHash=" + AllflameContext.AreaHash);
                return true;
            }

            AllflameContext.Refresh(true);
            if (_rescueAreaHash != AllflameContext.AreaHash)
            {
                ResetZeroLanternRescue("AreaHashChangedDuringDecision");
                _rescueAreaHash = AllflameContext.AreaHash;
            }
            if (_rescueOverallStartedUtc == DateTime.MinValue)
            {
                _rescueOverallStartedUtc = DateTime.UtcNow;
                AllflameLog.Info(
                    "CAPSULE_MANDATORY_EXTRACTION" +
                    "|Task=" + Name +
                    "|AreaHash=" + AllflameContext.AreaHash +
                    "|Cycle=" + _rescueCycle +
                    "|Strategy=" + _rescueStrategy +
                    "|RoutePlan=" + _rescueRoutePlan +
                    "|ElapsedSeconds=0" +
                    "|NextAction=AcquireCapsule");
            }
            LogMandatoryExtractionStatus();

            NetworkObject nearbyLive = FindLiveRescueCapsule(
                new Vector2i(),
                CapsuleRescueSearchMode.AcquireNewTarget,
                true);
            if (nearbyLive != null &&
                LokiPoe.Me.Position.DistanceF(nearbyLive.Position) <=
                    VoyageRunState.CapsuleNearbyExitDistance)
            {
                ApplyMandatoryLiveRescueOverride(nearbyLive);
            }
            if (StopMandatoryFinalApproachOnTimeout(settings, nearbyLive))
            {
                return true;
            }
            if (!AllflameContext.LanternAuraActive &&
                !_mandatoryFinalApproachActive)
            {
                return RunZeroLanternSafetyOnly();
            }
            if (DateTime.UtcNow < _rescueCooldownUntilUtc)
            {
                return true;
            }
            if (_rescueStageStartedUtc == DateTime.MinValue)
            {
                BeginRescueStage(
                    ZeroLanternExtractionStage.AcquireCapsule,
                    "RequestStarted");
            }
            if (ObserveRescueWatchdog())
            {
                return true;
            }

            NetworkObject live = nearbyLive != null &&
                _rescueTargetAnchor != default(Vector2i) &&
                nearbyLive.Position.DistanceF(_rescueTargetAnchor) <= 25f
                    ? nearbyLive
                    : FindLiveRescueCapsule(
                        _rescueTargetAnchor,
                        _rescueTargetId == 0
                            ? CapsuleRescueSearchMode.AcquireNewTarget
                            : CapsuleRescueSearchMode.MaintainLockedTarget);
            if (live != null &&
                _rescueTargetId != 0 &&
                live.Id != _rescueTargetId)
            {
                live = FindLiveRescueCapsule(
                    _rescueTargetAnchor,
                    CapsuleRescueSearchMode.MaintainLockedTarget);
            }

            switch (_zeroLanternStage)
            {
                case ZeroLanternExtractionStage.AcquireCapsule:
                    if (TryAcquireRescueTarget(live))
                    {
                        BeginRescueStage(
                            ZeroLanternExtractionStage.PlanCoveredRoute,
                            "TargetAcquired");
                    }
                    else if (_rescueStrategy ==
                             CapsuleRescueStrategy.ReverseBreadcrumb)
                    {
                        await RunRescueBreadcrumbStep();
                    }
                    else
                    {
                        RotateZeroLanternRescue("NoLiveCapsuleForStrategy");
                    }
                    return true;

                case ZeroLanternExtractionStage.PlanCoveredRoute:
                    return RunRescueRoutePlan(settings, live);

                case ZeroLanternExtractionStage.ApproachInteractionRing:
                    if (_rescueTargetId == 0)
                    {
                        RejectRegistryAnchor("InteractionStageWithoutLiveTarget");
                        RotateRegistryReacquireTarget("RegistryAnchorCannotInteract");
                        return true;
                    }
                    return RunRescueApproach(settings, live);

                case ZeroLanternExtractionStage.Stabilize:
                    if (_rescueTargetId == 0)
                    {
                        RotateZeroLanternRescue("StabilizeWithoutLiveTarget");
                        return true;
                    }
                    return await StabilizeRescueInteraction(settings);

                case ZeroLanternExtractionStage.Interact:
                    if (_rescueTargetId == 0)
                    {
                        RotateZeroLanternRescue("InteractWithoutLiveTarget");
                        return true;
                    }
                    return await InteractRescueCapsule();

                case ZeroLanternExtractionStage.ConfirmUi:
                    return await ConfirmRescueCapsuleUi();

                case ZeroLanternExtractionStage.CallBathysphere:
                case ZeroLanternExtractionStage.ConfirmCall:
                    // The existing Call Bathysphere UI flow owns these stages.
                    return true;
            }
            return true;
        }

        private bool RunZeroLanternSafetyOnly()
        {
            Vector2i player = LokiPoe.Me.Position;
            if (_hasLockedExitAnchor &&
                _lockedExitAnchor != default(Vector2i))
            {
                AllflameLog.Throttled(
                    "capsule_zero_lantern_safety_route",
                    TimeSpan.FromSeconds(1),
                    "ZERO_LANTERN_SAFETY_ABORT" +
                    "|Action=SafeExitOnly" +
                    "|Anchor=" + _lockedExitAnchor +
                    "|AreaHash=" + AllflameContext.AreaHash);
                MoveToSafeExitRoute(_lockedExitAnchor);
                return true;
            }
            Vector2i waypoint;
            int step;
            if (VoyageRunState.TryGetReverseSafeBreadcrumb(
                    player, out waypoint, out step) ||
                VoyageRunState.TryGetRecoveryLanternWaypoint(
                    player, out waypoint, out step))
            {
                bool moving = MoveSafeWaypoint(
                    waypoint,
                    "ReverseBreadcrumb",
                    step,
                    false);
                AllflameLog.Throttled(
                    "capsule_zero_lantern_safety_breadcrumb",
                    TimeSpan.FromSeconds(1),
                    "ZERO_LANTERN_SAFETY_ABORT" +
                    "|Action=SafeExitOnly" +
                    "|Waypoint=" + waypoint +
                    "|Moving=" + moving +
                    "|AreaHash=" + AllflameContext.AreaHash);
                return true;
            }
            AllflameLog.Throttled(
                "capsule_zero_lantern_safety_wait",
                TimeSpan.FromSeconds(2),
                "ZERO_LANTERN_SAFETY_ABORT" +
                "|Action=SafeExitOnlyWait" +
                "|Reason=NoReverseBreadcrumb" +
                "|AreaHash=" + AllflameContext.AreaHash);
            if (_rescueAttemptStartedUtc == DateTime.MinValue)
            {
                _rescueAttemptStartedUtc = DateTime.UtcNow;
                _rescueRouteReloads = 0;
            }
            else if (DateTime.UtcNow - _rescueAttemptStartedUtc >=
                     TimeSpan.FromSeconds(4))
            {
                if (_rescueRouteReloads < 2)
                {
                    _rescueRouteReloads++;
                    try { ExilePather.Reload(true); } catch { }
                    AllflameContext.Refresh(true);
                    _rescueAttemptStartedUtc = DateTime.UtcNow;
                    AllflameLog.Info(
                        "CAPSULE_ROUTE_STRATEGY_CHANGED" +
                        "|AreaHash=" + AllflameContext.AreaHash +
                        "|RescueCycle=" + _rescueCycle +
                        "|Reloads=" + _rescueRouteReloads +
                        "|Previous=SafetyOnlyWait" +
                        "|Next=SafetyOnlyRefresh" +
                        "|Reason=NoReverseBreadcrumb");
                }
                else
                {
                    StartNewZeroLanternRescueCycle(
                        "SafetyOnlyBreadcrumbRefreshExhausted");
                }
            }
            return true;
        }

        private bool TryAcquireRescueTarget(NetworkObject live)
        {
            Vector2i player = LokiPoe.Me.Position;
            if (live != null &&
                IsRescueCapsuleUsable(live) &&
                (_rescueTargetAnchor == default(Vector2i) ||
                 live.Position.DistanceF(_rescueTargetAnchor) <= 25f ||
                 player.DistanceF(live.Position) <=
                    VoyageRunState.CapsuleNearbyExitDistance ||
                 _rescueStrategy == CapsuleRescueStrategy.LiveObservedCapsule))
            {
                VoyageRunState.RememberCapsule(live.Position);
                _rescueTargetAnchor = live.Position;
                _rescueTargetId = live.Id;
                _rescueTargetRegistryOnly = false;
                _rescueTargetLiveObserved = true;
                _rescueTargetProven =
                    VoyageRunState.IsCapsuleProven(live.Position);
                _rescueAnchorReacquireUtc = DateTime.MinValue;
                _rescueTargetsThisCycle.Add(RescueTargetKey(live.Position));
                LockExitAnchor(
                    live.Position,
                    VoyageRunState.IsCapsuleProven(live.Position),
                    "RescueAcquireLive",
                    true,
                    player.DistanceF(live.Position) <=
                        VoyageRunState.CapsuleNearbyExitDistance);
                MarkRescueExplicitProgress("LiveCapsuleAcquired");
                return true;
            }

            if (_rescueStrategy == CapsuleRescueStrategy.ReverseBreadcrumb)
            {
                return false;
            }
            if (_rescueStrategy == CapsuleRescueStrategy.LiveObservedCapsule)
            {
                return false;
            }

            List<Vector2i> candidates =
                VoyageRunState.GetCapsuleCandidatesNewestFirst(player);
            foreach (Vector2i candidate in candidates)
            {
                string candidateKey = RescueTargetKey(candidate);
                if (_rescueFailedAnchorsThisCycle.Contains(candidateKey))
                {
                    continue;
                }
                if (_rescueStrategy == CapsuleRescueStrategy.AlternateCapsule &&
                    candidate.DistanceF(_rescueTargetAnchor) <= 25f)
                {
                    continue;
                }
                if (_rescueStrategy != CapsuleRescueStrategy.SameCapsuleCandidate &&
                    _rescueTargetsThisCycle.Contains(
                        RescueTargetKey(candidate)))
                {
                    continue;
                }
                _rescueTargetAnchor = candidate;
                _rescueTargetId = 0;
                _rescueTargetRegistryOnly = true;
                _rescueTargetLiveObserved = false;
                _rescueTargetProven =
                    VoyageRunState.IsCapsuleProven(candidate);
                _rescueAnchorReacquireUtc = DateTime.MinValue;
                _rescueTargetsThisCycle.Add(candidateKey);
                LockExitAnchor(
                    candidate,
                    VoyageRunState.IsCapsuleProven(candidate),
                    "RescueAcquireRegistry");
                AllflameLog.Info(
                    "CAPSULE_TARGET_ROTATED" +
                    "|AreaHash=" + AllflameContext.AreaHash +
                    "|TargetId=0|Anchor=" + candidate +
                    "|RegistryOnly=True|LiveObserved=False|Proven=" +
                    _rescueTargetProven +
                    "|Strategy=" + _rescueStrategy +
                    "|RescueCycle=" + _rescueCycle);
                return true;
            }
            return false;
        }

        private void ApplyMandatoryLiveRescueOverride(NetworkObject live)
        {
            if (!IsRescueCapsuleUsable(live) || LokiPoe.Me == null)
            {
                return;
            }
            float distance = LokiPoe.Me.Position.DistanceF(live.Position);
            if (distance > VoyageRunState.CapsuleNearbyExitDistance)
            {
                return;
            }
            bool targetChanged = _rescueTargetId != live.Id ||
                _rescueTargetAnchor.DistanceF(live.Position) > 25f;
            bool lockChanged = !_hasLockedExitAnchor ||
                _lockedExitAnchor.DistanceF(live.Position) > 25f;
            bool approachChanged = !_mandatoryFinalApproachActive;
            if (!targetChanged && !lockChanged && !approachChanged)
            {
                return;
            }

            Vector2i previousAnchor = _hasLockedExitAnchor
                ? _lockedExitAnchor
                : new Vector2i();
            VoyageRunState.RestoreLiveCapsuleForFailsafe(
                live.Position,
                "MandatoryRescueWithin150");
            _rescueStrategy = CapsuleRescueStrategy.LiveObservedCapsule;
            _rescueTargetAnchor = live.Position;
            _rescueTargetId = live.Id;
            _rescueTargetRegistryOnly = false;
            _rescueTargetLiveObserved = true;
            _rescueTargetProven =
                VoyageRunState.IsCapsuleProven(live.Position);
            _mandatoryFinalApproachActive = true;
            if (_mandatoryFinalApproachStartedUtc == DateTime.MinValue)
            {
                _mandatoryFinalApproachStartedUtc = DateTime.UtcNow;
                _mandatoryFinalApproachReloads = 0;
            }
            _rescueAnchorReacquireUtc = DateTime.MinValue;
            _rescueTargetsThisCycle.Add(RescueTargetKey(live.Position));
            _rescueApproachCandidates.Clear();
            _rescueCandidateCursor = 0;
            _rescueCandidate = null;
            _rescueRouteReloads = 0;
            LockExitAnchor(
                live.Position,
                _rescueTargetProven,
                "MandatoryRescueLiveWithin150",
                true,
                true);
            BeginRescueStage(
                ZeroLanternExtractionStage.PlanCoveredRoute,
                "MandatoryLiveOverride");
            MarkRescueExplicitProgress("MandatoryLiveCapsuleObserved");
            AllflameLog.Info(
                "CAPSULE_LIVE_OVERRIDE" +
                "|Live=" + live.Position +
                "|Distance=" + distance.ToString("0.0") +
                "|PreviousRegistryAnchor=" + previousAnchor +
                "|LockDistance=150");
            AllflameLog.Info(
                "CAPSULE_FINAL_APPROACH_START" +
                "|TargetId=" + live.Id +
                "|Target=" + live.Position +
                "|Player=" + LokiPoe.Me.Position +
                "|Distance=" + distance.ToString("0.0") +
                "|CoverageOverride=True");
        }

        private bool RunRescueRoutePlan(
            AllflameSettings settings,
            NetworkObject live)
        {
            Vector2i player = LokiPoe.Me.Position;
            if (live != null && IsRescueCapsuleUsable(live) &&
                live.Position.DistanceF(_rescueTargetAnchor) <= 25f)
            {
                bool newlyAcquired = _rescueTargetId != live.Id;
                _rescueTargetId = live.Id;
                _rescueTargetRegistryOnly = false;
                _rescueTargetLiveObserved = true;
                _rescueTargetProven =
                    VoyageRunState.IsCapsuleProven(live.Position);
                _rescueAnchorReacquireUtc = DateTime.MinValue;
                if (newlyAcquired)
                {
                    MarkRescueExplicitProgress("LiveCapsuleReacquired");
                }
                if (player.DistanceF(live.Position) <=
                    RescueInteractionThreshold(settings))
                {
                    BeginRescueStage(
                        ZeroLanternExtractionStage.ApproachInteractionRing,
                        "AlreadyInsideInteractionRing");
                    return true;
                }
            }

            if (_rescueTargetAnchor == default(Vector2i))
            {
                BeginRescueStage(
                    ZeroLanternExtractionStage.AcquireCapsule,
                    "RouteTargetMissing");
                return true;
            }

            if (_rescueAttemptStartedUtc == DateTime.MinValue)
            {
                _rescueStageAttempt++;
                _rescueAttemptStartedUtc = DateTime.UtcNow;
                _rescueProgressUtc = _rescueAttemptStartedUtc;
                _rescueBestDistance = player.DistanceF(_rescueTargetAnchor);
                _rescueAttemptStartPlayer = player;
                _rescueRoutePlan++;
                _rescueRouteReloads = 0;
                _rescueRoutePreviousPlayer = player;
                _rescueRoutePreviousDistance = _rescueBestDistance;
                _rescueRoutePreviousWaypoint = new Vector2i();
                _rescueWaypointHistory.Clear();
                LogRescueStage("PlanCoveredRoute", "RoutePlanCreated");
            }
            float distance = player.DistanceF(_rescueTargetAnchor);
            LogRescueRouteDelta(player, distance);
            if (_rescueTargetRegistryOnly && _rescueTargetId == 0 &&
                distance <= RegistryAnchorReacquireDistance)
            {
                if (_rescueAnchorReacquireUtc == DateTime.MinValue)
                {
                    _rescueAnchorReacquireUtc = DateTime.UtcNow;
                    LogLiveScanWait("RegistryAnchorReacquireStarted");
                }
                if (DateTime.UtcNow - _rescueAnchorReacquireUtc >=
                    TimeSpan.FromSeconds(RegistryAnchorReacquireSeconds))
                {
                    RejectRegistryAnchor("NoLiveCapsuleWithinReacquireWindow");
                    RotateRegistryReacquireTarget("RegistryAnchorReacquireFailed");
                }
                return true;
            }
            if (distance <= RescueInteractionThreshold(settings))
            {
                if (_rescueStrategy ==
                    CapsuleRescueStrategy.ReverseBreadcrumb)
                {
                    float movementTowardWaypoint =
                        _rescueBreadcrumbStartDistance - distance;
                    _rescueBreadcrumbMovedTowardWaypoint =
                        movementTowardWaypoint >= 35f;
                    if (!_rescueBreadcrumbMovedTowardWaypoint)
                    {
                        AllflameLog.Info(
                            "CAPSULE_RESCUE_ANCHOR_REJECTED" +
                            "|Task=" + Name +
                            "|AreaHash=" + AllflameContext.AreaHash +
                            "|Cycle=" + _rescueCycle +
                            "|Strategy=" + _rescueStrategy +
                            "|RoutePlan=" + _rescueRoutePlan +
                            "|TargetId=0|Anchor=" + _rescueTargetAnchor +
                            "|RegistryOnly=False|Reason=BreadcrumbMovementBelow35" +
                            "|MovementToward=" + movementTowardWaypoint.ToString("0.0") +
                            "|NextAction=TryNextBreadcrumb");
                        BeginRescueStage(
                            ZeroLanternExtractionStage.AcquireCapsule,
                            "BreadcrumbMovementInsufficient");
                        return true;
                    }
                    CapsuleRescueStrategy previous = _rescueStrategy;
                    _rescueStrategy =
                        CapsuleRescueStrategy.LiveObservedCapsule;
                    _rescueTargetAnchor = new Vector2i();
                    _rescueTargetId = 0;
                    BeginRescueStage(
                        ZeroLanternExtractionStage.AcquireCapsule,
                        "ReverseBreadcrumbReached");
                    AllflameLog.Info(
                        "CAPSULE_ROUTE_STRATEGY_CHANGED" +
                        "|AreaHash=" + AllflameContext.AreaHash +
                        "|RescueCycle=" + _rescueCycle +
                        "|Previous=" + previous +
                        "|Next=" + _rescueStrategy +
                        "|Reason=BreadcrumbReachedAndRefreshLiveScan");
                    return true;
                }
                if (_rescueTargetId == 0)
                {
                    RejectRegistryAnchor("InteractionRingReachedWithoutLiveTarget");
                    RotateRegistryReacquireTarget("RegistryAnchorCannotEnterApproach");
                    return true;
                }
                BeginRescueStage(
                    ZeroLanternExtractionStage.ApproachInteractionRing,
                    "RouteReachedInteractionRing");
                return true;
            }
            if (distance <= _rescueBestDistance - 3f)
            {
                _rescueBestDistance = distance;
                _rescueProgressUtc = DateTime.UtcNow;
                LogRescueProgress("RouteDistanceImproved", distance);
            }
            if (DateTime.UtcNow - _rescueProgressUtc >=
                TimeSpan.FromSeconds(
                    MandatoryFinalApproachNoProgressSeconds))
            {
                bool waypointOscillation =
                    IsRescueWaypointOscillating();
                int completedReloads = _mandatoryFinalApproachActive
                    ? _mandatoryFinalApproachReloads
                    : _rescueRouteReloads;
                if (completedReloads <
                    MandatoryFinalApproachMaximumReloads)
                {
                    _rescueRouteReloads++;
                    if (_mandatoryFinalApproachActive)
                    {
                        _mandatoryFinalApproachReloads++;
                        AllflameLog.Info(
                            "CAPSULE_FINAL_APPROACH_RECOVERY" +
                            "|Attempt=" +
                            _mandatoryFinalApproachReloads +
                            "|Reason=TargetReacquire" +
                            "|Action=ReloadPather");
                    }
                    try { ExilePather.Reload(true); } catch { }
                    _rescueProgressUtc = DateTime.UtcNow;
                    _rescueBestDistance = distance;
                    _rescueWatchdogUtc = DateTime.UtcNow;
                    ResetMoverApproachState();
                    AllflameLog.Info(
                        "CAPSULE_ROUTE_STRATEGY_CHANGED" +
                        "|AreaHash=" + AllflameContext.AreaHash +
                        "|TargetId=" + _rescueTargetId +
                        "|Anchor=" + _rescueTargetAnchor +
                        "|RescueCycle=" + _rescueCycle +
                        "|RoutePlan=" + _rescueRoutePlan +
                        "|Reloads=" + _rescueRouteReloads +
                        "|Previous=CoveredRoute|Next=CoveredRouteReload" +
                        "|Reason=" + (waypointOscillation
                            ? "WaypointOscillation"
                            : "NoFinalAnchorConvergence") +
                        "|Action=ReloadPather");
                    if (_mandatoryFinalApproachActive)
                    {
                        AllflameLog.Info(
                            "CAPSULE_FINAL_APPROACH_RECOVERY" +
                            "|Attempt=" +
                            _mandatoryFinalApproachReloads +
                            "|Reason=" + (waypointOscillation
                                ? "Oscillation"
                                : "NoProgress") +
                            "|Distance=" + distance.ToString("0.0") +
                            "|Action=ReloadPather");
                    }
                    return true;
                }
                if (_rescueTargetRegistryOnly && _rescueTargetId == 0)
                {
                    string routeReason = waypointOscillation
                        ? "WaypointOscillationAfterTwoReloads"
                        : "RouteNoProgressAfterTwoReloads";
                    RejectRegistryAnchor(routeReason);
                    RotateRegistryReacquireTarget(routeReason);
                }
                else if (_mandatoryFinalApproachActive)
                {
                    StopMandatoryFinalApproach(
                        waypointOscillation
                            ? "OscillationAfterTwoReloads"
                            : "NoProgressAfterTwoReloads",
                        distance);
                }
                else
                {
                    RotateZeroLanternRescue(
                        waypointOscillation
                            ? "WaypointOscillationAfterTwoReloads"
                            : "RouteNoProgressAfterTwoReloads");
                }
                return true;
            }

            Vector2i waypoint;
            if (!TryGetRescueWaypoint(player, _rescueTargetAnchor, out waypoint))
            {
                if (_rescueTargetRegistryOnly && _rescueTargetId == 0)
                {
                    RejectRegistryAnchor("NoCoveredRouteWaypoint");
                    RotateRegistryReacquireTarget("NoCoveredRouteWaypoint");
                }
                else if (_mandatoryFinalApproachActive)
                {
                    HandleMandatoryFinalApproachFailure(
                        "NoPath", distance);
                }
                else
                {
                    RotateZeroLanternRescue("NoCoveredRouteWaypoint");
                }
                return true;
            }
            RecordRescueWaypoint(waypoint);
            if (DateTime.UtcNow < _rescueCooldownUntilUtc)
            {
                return true;
            }
            _rescueCooldownUntilUtc = DateTime.UtcNow.AddMilliseconds(325);
            bool moving = AllflameMovementCoordinator.MoveTowards(
                waypoint,
                Name + " zero-lantern rescue");
            _rescueRoutePreviousWaypoint = waypoint;
            if (_mandatoryFinalApproachActive)
            {
                AllflameLog.Info(
                    "CAPSULE_FINAL_APPROACH_STEP" +
                    "|From=" + player +
                    "|Waypoint=" + waypoint +
                    "|Target=" + _rescueTargetAnchor +
                    "|DistanceBefore=" + distance.ToString("0.0") +
                    "|StepLength=" + player.DistanceF(waypoint).ToString("0.0") +
                    "|Path=True" +
                    "|Moving=" + moving);
            }
            LogRescueProgress(
                moving ? "RouteMoveAccepted" : "RouteMoveRejected",
                distance);
            return true;
        }

        private bool RunRescueApproach(
            AllflameSettings settings,
            NetworkObject live)
        {
            Vector2i player = LokiPoe.Me.Position;
            if (!IsLockedRescueTargetUsable(live))
            {
                live = FindLiveRescueCapsule(
                    _rescueTargetAnchor,
                    CapsuleRescueSearchMode.MaintainLockedTarget);
            }
            if (!IsLockedRescueTargetUsable(live))
            {
                HandleLockedTargetUnavailable(
                    "ApproachInteractionRing",
                    "LiveTargetLost");
                return true;
            }
            _rescueAnchorReacquireUtc = DateTime.MinValue;
            _rescueTargetId = live.Id;
            float distance = player.DistanceF(live.Position);
            float threshold = RescueInteractionThreshold(settings);
            if (distance <= threshold)
            {
                BeginRescueStage(
                    ZeroLanternExtractionStage.Stabilize,
                    "InteractionRingReached");
                return true;
            }
            if (_rescueApproachCandidates.Count == 0 &&
                !BuildRescueApproachCandidates(player, live.Position))
            {
                if (_mandatoryFinalApproachActive)
                {
                    HandleMandatoryFinalApproachFailure(
                        "NoPath", distance);
                }
                else
                {
                    RotateZeroLanternRescue("ApproachCandidatesExhausted");
                }
                return true;
            }
            if (_rescueCandidate == null &&
                !SelectNextRescueApproachCandidate(player))
            {
                if (_mandatoryFinalApproachActive)
                {
                    HandleMandatoryFinalApproachFailure(
                        "NoPath", distance);
                }
                else
                {
                    RotateZeroLanternRescue("ApproachCandidatesExhausted");
                }
                return true;
            }
            if (DateTime.UtcNow - _rescueAttemptStartedUtc >=
                TimeSpan.FromSeconds(3))
            {
                LogApproachRejected("CandidateTimeout", distance);
                _rescueCandidate = null;
                _rescueAttemptStartedUtc = DateTime.UtcNow;
                return true;
            }
            if (distance <= _rescueBestDistance - 2f)
            {
                _rescueBestDistance = distance;
                _rescueProgressUtc = DateTime.UtcNow;
                LogRescueProgress("ApproachDistanceImproved", distance);
            }
            if (_mandatoryFinalApproachActive &&
                DateTime.UtcNow - _rescueProgressUtc >=
                    TimeSpan.FromSeconds(
                        MandatoryFinalApproachNoProgressSeconds))
            {
                HandleMandatoryFinalApproachFailure(
                    "NoProgress", distance);
                return true;
            }
            if (DateTime.UtcNow < _rescueCooldownUntilUtc)
            {
                return true;
            }
            _rescueCooldownUntilUtc = DateTime.UtcNow.AddMilliseconds(325);
            bool moving = MoveTowardsInteraction(
                _rescueCandidate.Position,
                Name + " capsule approach ring");
            AllflameLog.Info(
                "CAPSULE_APPROACH_PROGRESS" +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|TargetId=" + _rescueTargetId +
                "|Anchor=" + _rescueTargetAnchor +
                "|CandidateIndex=" + _rescueCandidate.Index +
                "|Candidate=" + _rescueCandidate.Position +
                "|CurrentDistance=" + distance.ToString("0.0") +
                "|BestDistance=" + _rescueBestDistance.ToString("0.0") +
                "|InteractionRange=" + _rescueInteractionRange.ToString("0.0") +
                "|Attempt=" + _rescueStageAttempt +
                "|RescueCycle=" + _rescueCycle +
                "|RoutePlan=" + _rescueRoutePlan +
                "|ActionResult=" + moving);
            return true;
        }

        private async Task<bool> StabilizeRescueInteraction(
            AllflameSettings settings)
        {
            Vector2i before = LokiPoe.Me.Position;
            _rescueStageAttempt++;
            await FinishMovementBeforeInteraction("Allflame Capsule rescue");
            ResetMoverApproachState();
            AllflameContext.Refresh(true);
            NetworkObject first = FindLiveRescueCapsule(
                _rescueTargetAnchor,
                CapsuleRescueSearchMode.InteractionSnapshot);
            Vector2i firstPlayer = LokiPoe.Me.Position;
            float threshold = RescueInteractionThreshold(settings);
            if (!IsRescueSnapshotValid(first, firstPlayer, threshold))
            {
                LogRescueSyncDrift(before, firstPlayer, first);
                ReturnToRescueApproach("SyncDriftBeforeSnapshot");
                return true;
            }
            await LokiCoroutine.Sleep(120);
            AllflameContext.Refresh(true);
            NetworkObject second = FindLiveRescueCapsule(
                _rescueTargetAnchor,
                CapsuleRescueSearchMode.InteractionSnapshot);
            Vector2i secondPlayer = LokiPoe.Me.Position;
            if (!IsRescueSnapshotValid(second, secondPlayer, threshold))
            {
                LogRescueSyncDrift(firstPlayer, secondPlayer, second);
                ReturnToRescueApproach("SyncDriftAfterSnapshot");
                return true;
            }
            AllflameLog.Info(
                "CAPSULE_INTERACTION_READY" +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|TargetId=" + second.Id +
                "|Anchor=" + _rescueTargetAnchor +
                "|PlayerBefore=" + before +
                "|PlayerAfter=" + secondPlayer +
                "|CurrentDistance=" + secondPlayer.DistanceF(second.Position).ToString("0.0") +
                "|InteractionRange=" + _rescueInteractionRange.ToString("0.0") +
                "|Attempt=" + _rescueStageAttempt +
                "|RescueCycle=" + _rescueCycle);
            BeginRescueStage(
                ZeroLanternExtractionStage.Interact,
                "TwoFreshSnapshotsInRange");
            return true;
        }

        private async Task<bool> InteractRescueCapsule()
        {
            NetworkObject live = FindLiveRescueCapsule(
                _rescueTargetAnchor,
                CapsuleRescueSearchMode.InteractionSnapshot);
            if (!IsLockedRescueTargetUsable(live))
            {
                ReturnToRescueApproach("InteractTargetSnapshotLost");
                return true;
            }
            _rescueStageAttempt++;
            bool accepted = await InteractWithRecovery(live);
            _openAttempts++;
            AllflameLog.Info(
                "CAPSULE_RESCUE_INTERACT" +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|TargetId=" + live.Id +
                "|Anchor=" + _rescueTargetAnchor +
                "|Attempt=" + _rescueStageAttempt +
                "|RescueCycle=" + _rescueCycle +
                "|ActionResult=" + accepted);
            BeginRescueStage(
                ZeroLanternExtractionStage.ConfirmUi,
                "InteractIssued");
            return true;
        }

        private async Task<bool> ConfirmRescueCapsuleUi()
        {
            await LokiCoroutine.Sleep(250);
            _rescueStageAttempt++;
            AllflameContext.Refresh(true);
            VisualCallProbe probe = await ProbeVisualCallButton();
            if (probe != null && probe.Confirmed)
            {
                _visualCapsuleUiOpen = true;
                MarkRescueExplicitProgress("CapsuleUiConfirmed");
                _openAttempts = 0;
                _openRecoveryCycles = 0;
                VoyageRunState.MarkCapsuleProven(_rescueTargetAnchor);
                LockExitAnchor(
                    _rescueTargetAnchor,
                    true,
                    "CapsuleUiConfirmed",
                    true);
                CompleteRescueApproachOnUiConfirmed();
                BeginRescueStage(
                    ZeroLanternExtractionStage.CallBathysphere,
                    "VisualUiConfirmed");
                AllflameLog.Info(
                    "CAPSULE_RESCUE_UI_CONFIRMED" +
                    "|AreaHash=" + AllflameContext.AreaHash +
                    "|TargetId=" + _rescueTargetId +
                    "|Anchor=" + _rescueTargetAnchor +
                    "|RescueCycle=" + _rescueCycle +
                    "|ActionResult=True");
                return true;
            }
            if (_openAttempts >= 3)
            {
                AllflameLog.Info(
                    "CAPSULE_APPROACH_REJECTED" +
                    "|AreaHash=" + AllflameContext.AreaHash +
                    "|TargetId=" + _rescueTargetId +
                    "|Anchor=" + _rescueTargetAnchor +
                    "|Reason=UiNotConfirmedAfterBoundedAttempts" +
                    "|Attempt=" + _openAttempts +
                    "|RescueCycle=" + _rescueCycle);
                await Coroutines.CloseBlockingWindows();
                if (_mandatoryFinalApproachActive)
                {
                    StopMandatoryFinalApproach(
                        "UiNotConfirmedAfterBoundedAttempts",
                        LokiPoe.Me == null
                            ? Single.MaxValue
                            : LokiPoe.Me.Position.DistanceF(
                                _rescueTargetAnchor));
                }
                else
                {
                    RotateZeroLanternRescue(
                        "UiNotConfirmedAfterBoundedAttempts");
                }
            }
            else
            {
                ReturnToRescueApproach("UiNotConfirmedRetry");
            }
            return true;
        }

        private bool BuildRescueApproachCandidates(
            Vector2i player,
            Vector2i anchor)
        {
            _rescueApproachCandidates.Clear();
            _rescueCandidateCursor = 0;
            _rescueCandidate = null;
            float[] radii = { 12f, 18f, 24f, 29f };
            double baseAngle = Math.Atan2(
                player.Y - anchor.Y,
                player.X - anchor.X);
            for (int index = 0; index < 16; index++)
            {
                    float radius = radii[index % radii.Length];
                    double angle = baseAngle +
                        index * Math.PI * 2.0 / 16.0;
                    Vector2i candidate = new Vector2i(
                        anchor.X + (int)Math.Round(Math.Cos(angle) * radius),
                        anchor.Y + (int)Math.Round(Math.Sin(angle) * radius));
                    string rejection = String.Empty;
                    bool coverage =
                        VoyageRunState.IsPositionWithinLanternCoverage(
                            candidate, 120f);
                    bool pathable = false;
                    bool raycastClear = false;
                    try
                    {
                        pathable = ExilePather.PathExistsBetween(
                            player, candidate, false);
                        Vector2i hit;
                        VoyageRunnerMetrics.RecordRaycastQuery();
                        raycastClear = ExilePather.Raycast(
                            candidate, anchor, out hit, false, false);
                    }
                    catch
                    {
                        pathable = false;
                    }
                    if (!coverage && !_mandatoryFinalApproachActive)
                        rejection = "OutsideLanternCoverage";
                    else if (!pathable) rejection = "NoPath";
                    else if (!raycastClear) rejection = "RaycastBlocked";
                    AllflameLog.Info(
                        "CAPSULE_APPROACH_CANDIDATE" +
                        "|AreaHash=" + AllflameContext.AreaHash +
                        "|TargetId=" + _rescueTargetId +
                        "|Anchor=" + anchor +
                        "|CandidateIndex=" + index +
                        "|Candidate=" + candidate +
                        "|Radius=" + radius.ToString("0.0") +
                        "|Path=" + pathable +
                        "|Raycast=" + raycastClear +
                        "|Coverage=" + coverage +
                        "|Policy=" + (_mandatoryFinalApproachActive
                            ? "MandatoryFinalApproach"
                            : "StrictCoverage") +
                        "|Result=" + (String.IsNullOrEmpty(rejection) ? "Accepted" : "Rejected") +
                        "|Reason=" + rejection +
                        "|RescueCycle=" + _rescueCycle);
                    if (String.IsNullOrEmpty(rejection))
                    {
                        _rescueApproachCandidates.Add(
                            new CapsuleApproachCandidate
                            {
                                Index = index,
                                Position = candidate,
                                Radius = radius
                            });
                    }
            }
            if (_rescueApproachCandidates.Count == 0)
            {
                return false;
            }
            LogRescueStage("ApproachInteractionRing", "CandidatesBuilt");
            return true;
        }

        private bool SelectNextRescueApproachCandidate(Vector2i player)
        {
            while (_rescueCandidateCursor <
                _rescueApproachCandidates.Count)
            {
                CapsuleApproachCandidate candidate =
                    _rescueApproachCandidates[_rescueCandidateCursor++];
                string actionKey = RescueActionKey(
                    _rescueTargetAnchor,
                    candidate.Index,
                    _rescueRoutePlan);
                if (!_rescueActionsThisCycle.Add(actionKey))
                {
                    continue;
                }
                _rescueCandidate = candidate;
                _rescueStageAttempt++;
                _rescueAttemptStartedUtc = DateTime.UtcNow;
                if (!_mandatoryFinalApproachActive)
                {
                    _rescueProgressUtc = _rescueAttemptStartedUtc;
                    _rescueBestDistance = player.DistanceF(
                        _rescueTargetAnchor);
                }
                else
                {
                    if (_rescueProgressUtc == DateTime.MinValue)
                    {
                        _rescueProgressUtc = _rescueAttemptStartedUtc;
                    }
                    if (_rescueBestDistance == Single.MaxValue)
                    {
                        _rescueBestDistance = player.DistanceF(
                            _rescueTargetAnchor);
                    }
                }
                _rescueWatchdogUtc = DateTime.UtcNow;
                _rescueWatchdogPlayer = player;
                _rescueLastAction =
                    "ApproachCandidate:" + candidate.Index;
                return true;
            }
            return false;
        }

        private async Task RunRescueBreadcrumbStep()
        {
            if (_rescueBreadcrumbs.Count == 0)
            {
                _rescueBreadcrumbs.AddRange(
                    VoyageRunState.GetSafeBreadcrumbsNewestFirst());
                _rescueBreadcrumbs.AddRange(
                    VoyageRunState.GetLanternAnchorsNewestFirst());
            }
            while (_rescueBreadcrumbCursor < _rescueBreadcrumbs.Count)
            {
                Vector2i waypoint =
                    _rescueBreadcrumbs[_rescueBreadcrumbCursor++];
                if (_rescueActionsThisCycle.Add(
                        "breadcrumb|" + waypoint))
                {
                    _rescueTargetAnchor = waypoint;
                    _rescueTargetId = 0;
                    _rescueTargetRegistryOnly = false;
                    _rescueTargetLiveObserved = false;
                    _rescueTargetProven = false;
                    _rescueBreadcrumbStartPlayer = LokiPoe.Me.Position;
                    _rescueBreadcrumbStartDistance =
                        _rescueBreadcrumbStartPlayer.DistanceF(waypoint);
                    _rescueBreadcrumbMovedTowardWaypoint = false;
                    BeginRescueStage(
                        ZeroLanternExtractionStage.PlanCoveredRoute,
                        "ReverseBreadcrumbSelected");
                    AllflameLog.Info(
                        "CAPSULE_ROUTE_STRATEGY_CHANGED" +
                        "|AreaHash=" + AllflameContext.AreaHash +
                        "|TargetId=0|Anchor=" + waypoint +
                        "|RescueCycle=" + _rescueCycle +
                        "|Previous=ReverseBreadcrumbScan|Next=LiveObservedCapsule");
                    return;
                }
            }
            RotateZeroLanternRescue("ReverseBreadcrumbsExhausted");
            await LokiCoroutine.Sleep(50);
        }

        private bool IsRescueSnapshotValid(
            NetworkObject capsule,
            Vector2i player,
            float threshold)
        {
            return capsule != null &&
                capsule.IsValid &&
                capsule.IsTargetable &&
                capsule.Id == _rescueTargetId &&
                capsule.Position.DistanceF(_rescueTargetAnchor) <= 25f &&
                player.DistanceF(capsule.Position) <= threshold &&
                AllflameContext.AreaHash == _rescueAreaHash;
        }

        private static float RescueInteractionThreshold(
            AllflameSettings settings)
        {
            return Math.Min(
                25f,
                Math.Max(20f, settings.InteractDistance));
        }

        private NetworkObject FindLiveRescueCapsule(
            Vector2i anchor,
            CapsuleRescueSearchMode searchMode =
                CapsuleRescueSearchMode.AcquireNewTarget,
            bool includeTried = false)
        {
            bool maintainLocked = searchMode !=
                CapsuleRescueSearchMode.AcquireNewTarget;
            bool filteredAsTried = false;
            NetworkObject found = null;
            NetworkObject rejectedLocked = null;
            float bestDistance = Single.MaxValue;
            int scanned = 0;
            var details = new StringBuilder();
            try
            {
                IEnumerable<NetworkObject> objects =
                    LokiPoe.ObjectManager.Objects;
                if (objects != null)
                {
                    foreach (NetworkObject obj in objects)
                    {
                        if (!IsRescueCapsuleObject(obj))
                        {
                            continue;
                        }
                        scanned++;
                        if (scanned <= 8)
                        {
                            if (details.Length > 0)
                            {
                                details.Append(',');
                            }
                            details.Append(obj.Id).Append(':')
                                .Append(obj.IsValid).Append(':')
                                .Append(obj.IsTargetable).Append(':')
                                .Append(obj.Position).Append(':')
                                .Append(anchor == default(Vector2i)
                                    ? "Any"
                                    : obj.Position.DistanceF(anchor)
                                        .ToString("0.0"));
                        }

                        if (maintainLocked)
                        {
                            if (obj.Id == _rescueTargetId)
                            {
                                rejectedLocked = obj;
                            }
                            if (!IsLockedRescueTargetUsable(obj))
                            {
                                continue;
                            }
                        }
                        else
                        {
                            if (!IsRescueCapsuleUsable(obj) ||
                                (anchor != default(Vector2i) &&
                                 obj.Position.DistanceF(anchor) > 25f))
                            {
                                continue;
                            }
                            bool tried =
                                _rescueStrategy ==
                                    CapsuleRescueStrategy
                                        .LiveObservedCapsule &&
                                _rescueTargetsThisCycle.Contains(
                                    RescueTargetKey(obj.Position));
                            if (!includeTried && tried)
                            {
                                filteredAsTried = true;
                                continue;
                            }
                        }

                        float distance = obj.Distance;
                        if (found == null || distance < bestDistance)
                        {
                            found = obj;
                            bestDistance = distance;
                        }
                    }
                }
            }
            catch
            {
            }

            if (found == null)
            {
                NetworkObject fallback = AllflameContext.CapsuleObject;
                if (maintainLocked)
                {
                    if (IsLockedRescueTargetUsable(fallback))
                    {
                        found = fallback;
                    }
                    else if (rejectedLocked == null && fallback != null)
                    {
                        rejectedLocked = fallback;
                    }
                }
                else if (IsRescueCapsuleUsable(fallback) &&
                    (anchor == default(Vector2i) ||
                     fallback.Position.DistanceF(anchor) <= 25f) &&
                    (includeTried ||
                     _rescueStrategy !=
                        CapsuleRescueStrategy.LiveObservedCapsule ||
                     !_rescueTargetsThisCycle.Contains(
                        RescueTargetKey(fallback.Position))))
                {
                    found = fallback;
                }
            }

            AllflameLog.Throttled(
                "capsule_rescue_live_scan_" + _rescueCycle + "_" +
                RescueTargetKey(anchor) + "_" + searchMode,
                TimeSpan.FromMilliseconds(500),
                "CAPSULE_RESCUE_LIVE_SCAN" +
                "|Task=" + Name +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|Cycle=" + _rescueCycle +
                "|Strategy=" + _rescueStrategy +
                "|RoutePlan=" + _rescueRoutePlan +
                "|SearchMode=" + searchMode +
                "|TargetId=" + _rescueTargetId +
                "|Anchor=" + anchor +
                "|RegistryOnly=" + _rescueTargetRegistryOnly +
                "|LiveObserved=" + (found != null) +
                "|FilteredAsTried=" + filteredAsTried +
                "|Proven=" + _rescueTargetProven +
                "|Scanned=" + scanned +
                "|Objects=" + details +
                "|ObjectScan=SinglePass" +
                "|UiVisible=" + RescueUiVisible() +
                "|NextAction=" +
                (found == null ? "ContinueReacquire" : "UseLiveTarget"));
            if (found != null)
            {
                if (maintainLocked)
                {
                    LogLockedTargetRetained(found, searchMode);
                }
                return found;
            }
            if (maintainLocked)
            {
                LogLockedTargetRejected(
                    rejectedLocked,
                    searchMode,
                    LockedTargetRejectionReason(rejectedLocked));
            }
            return null;
        }

        private bool IsLockedRescueTargetUsable(NetworkObject capsule)
        {
            return IsRescueCapsuleUsable(capsule) &&
                _rescueTargetId != 0 &&
                capsule.Id == _rescueTargetId &&
                _rescueTargetAnchor != default(Vector2i) &&
                capsule.Position.DistanceF(_rescueTargetAnchor) <= 25f &&
                AllflameContext.AreaHash == _rescueAreaHash;
        }

        private string LockedTargetRejectionReason(NetworkObject capsule)
        {
            if (AllflameContext.AreaHash != _rescueAreaHash)
            {
                return "AreaChanged";
            }
            if (capsule == null)
            {
                return "Missing";
            }
            try
            {
                if (!capsule.IsValid)
                {
                    return "Invalid";
                }
                if (!capsule.IsTargetable)
                {
                    return "NotTargetable";
                }
                if (_rescueTargetId == 0 || capsule.Id != _rescueTargetId)
                {
                    return "IdMismatch";
                }
                if (_rescueTargetAnchor == default(Vector2i) ||
                    capsule.Position.DistanceF(_rescueTargetAnchor) > 25f)
                {
                    return "AnchorDrift";
                }
            }
            catch
            {
                return "Invalid";
            }
            return "Rejected";
        }

        private void LogLockedTargetRetained(
            NetworkObject capsule,
            CapsuleRescueSearchMode searchMode)
        {
            AllflameLog.Throttled(
                "capsule_locked_target_retained_" + _rescueTargetId + "_" +
                searchMode,
                TimeSpan.FromMilliseconds(500),
                "CAPSULE_LOCKED_TARGET_RETAINED" +
                "|TargetId=" + capsule.Id +
                "|Anchor=" + _rescueTargetAnchor +
                "|Distance=" + capsule.Distance.ToString("0.0") +
                "|Stage=" + _zeroLanternStage +
                "|SearchMode=" + searchMode);
        }

        private void LogLockedTargetRejected(
            NetworkObject capsule,
            CapsuleRescueSearchMode searchMode,
            string reason)
        {
            AllflameLog.Throttled(
                "capsule_locked_target_rejected_" + _rescueTargetId + "_" +
                searchMode + "_" + reason,
                TimeSpan.FromMilliseconds(500),
                "CAPSULE_LOCKED_TARGET_REJECTED" +
                "|TargetId=" + _rescueTargetId +
                "|ObservedId=" + (capsule == null ? 0 : capsule.Id) +
                "|Anchor=" + _rescueTargetAnchor +
                "|Reason=" + reason +
                "|Stage=" + _zeroLanternStage +
                "|SearchMode=" + searchMode);
        }

        private void HandleLockedTargetUnavailable(
            string stage,
            string rotateReason)
        {
            if (_rescueAnchorReacquireUtc == DateTime.MinValue)
            {
                _rescueAnchorReacquireUtc = DateTime.UtcNow;
                AllflameLog.Info(
                    "CAPSULE_LOCKED_TARGET_REACQUIRE" +
                    "|TargetId=" + _rescueTargetId +
                    "|Anchor=" + _rescueTargetAnchor +
                    "|Stage=" + stage +
                    "|TimeoutMilliseconds=" +
                    LockedTargetReacquireMilliseconds +
                    "|Action=WaitForFreshSnapshot");
                return;
            }
            int elapsed = (int)(DateTime.UtcNow -
                _rescueAnchorReacquireUtc).TotalMilliseconds;
            if (elapsed < LockedTargetReacquireMilliseconds)
            {
                return;
            }
            AllflameLog.Info(
                "CAPSULE_APPROACH_REJECTED" +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|TargetId=" + _rescueTargetId +
                "|Anchor=" + _rescueTargetAnchor +
                "|Reason=" + rotateReason +
                "|ReacquireMilliseconds=" + elapsed +
                "|RescueCycle=" + _rescueCycle);
            RotateZeroLanternRescue(rotateReason);
        }

        private static bool IsRescueCapsuleObject(NetworkObject obj)
        {
            try
            {
                if (obj == null)
                {
                    return false;
                }
                string name = obj.Name ?? String.Empty;
                string metadata = obj.Metadata ?? String.Empty;
                return String.Equals(name, "Allflame Capsule", StringComparison.OrdinalIgnoreCase) ||
                    (name.IndexOf("Allflame", StringComparison.OrdinalIgnoreCase) >= 0 &&
                     name.IndexOf("Capsule", StringComparison.OrdinalIgnoreCase) >= 0) ||
                    metadata.IndexOf("AllflameCapsule", StringComparison.OrdinalIgnoreCase) >= 0 ||
                    metadata.IndexOf("DeepwaterCapsule", StringComparison.OrdinalIgnoreCase) >= 0 ||
                    metadata.IndexOf("SummonExtractionObject", StringComparison.OrdinalIgnoreCase) >= 0;
            }
            catch
            {
                return false;
            }
        }

        private static bool IsRescueCapsuleUsable(NetworkObject obj)
        {
            try
            {
                if (obj == null || !obj.IsValid || !obj.IsTargetable)
                {
                    return false;
                }
                return IsRescueCapsuleObject(obj);
            }
            catch
            {
                return false;
            }
        }

        private static string RescueTargetKey(Vector2i anchor)
        {
            return anchor.X + ":" + anchor.Y;
        }

        private static string RescueActionKey(
            Vector2i anchor,
            int candidate,
            int routePlan)
        {
            return RescueTargetKey(anchor) + "|candidate=" + candidate +
                "|route=" + routePlan;
        }

        private bool TryGetRescueWaypoint(
            Vector2i player,
            Vector2i anchor,
            out Vector2i waypoint)
        {
            waypoint = anchor;
            try
            {
                Vector2i lanternWaypoint;
                if (VoyageRunState.TryGetLanternRouteWaypoint(
                        player, anchor, out lanternWaypoint) &&
                    lanternWaypoint.DistanceF(player) > 24f &&
                    VoyageRunState.IsPositionWithinLanternCoverage(
                        lanternWaypoint, 120f))
                {
                    waypoint = lanternWaypoint;
                    return true;
                }
                CapsuleSafetySnapshot safety = VoyageCapsuleSafety.Evaluate(
                    player, anchor, "ZeroLanternRescueRoute");
                if (safety.DirectActionAllowed &&
                    ExilePather.PathExistsBetween(player, anchor, false))
                {
                    return true;
                }
                Vector2i breadcrumb;
                int ignored;
                if (VoyageRunState.TryGetReverseSafeBreadcrumb(
                        player, out breadcrumb, out ignored) &&
                    breadcrumb.DistanceF(player) > 24f &&
                    breadcrumb.DistanceF(anchor) <=
                        player.DistanceF(anchor) + 10f)
                {
                    waypoint = breadcrumb;
                    return true;
                }
                if (_mandatoryFinalApproachActive &&
                    TryGetMandatoryFinalApproachStep(
                        player, anchor, out waypoint))
                {
                    AllflameLog.Info(
                        "CAPSULE_SAFETY_CHECK" +
                        "|Action=ZeroLanternRescueRoute" +
                        "|Player=" + player +
                        "|Target=" + anchor +
                        "|Policy=MandatoryFinalApproach" +
                        "|Decision=Override");
                    return true;
                }
                return false;
            }
            catch
            {
                waypoint = anchor;
                return false;
            }
        }

        private void BeginRescueStage(
            ZeroLanternExtractionStage stage,
            string reason)
        {
            _zeroLanternStage = stage;
            _rescueStageStartedUtc = DateTime.UtcNow;
            _rescueStageAttempt = 0;
            _rescueAttemptStartedUtc = DateTime.MinValue;
            _rescueBestDistance = Single.MaxValue;
            if (stage == ZeroLanternExtractionStage.ApproachInteractionRing)
            {
                _rescueInteractionRange = RescueInteractionThreshold(
                    AllflameSettings.Instance);
                _rescueCandidate = null;
                _rescueApproachCandidates.Clear();
                _rescueCandidateCursor = 0;
            }
            _rescueWatchdogUtc = DateTime.UtcNow;
            _rescueWatchdogPlayer = LokiPoe.Me == null
                ? new Vector2i()
                : LokiPoe.Me.Position;
            _rescueWatchdogUiVisible = _visualCapsuleUiOpen;
            AllflameProgressWatchdog.BeginExplicitProgress(
                Name,
                _rescueTargetId,
                stage.ToString());
            LogRescueStage(stage.ToString(), reason);
        }

        private void ReturnToRescueApproach(string reason)
        {
            _zeroLanternStage =
                ZeroLanternExtractionStage.ApproachInteractionRing;
            _rescueStageStartedUtc = DateTime.UtcNow;
            _rescueStageAttempt = 0;
            _rescueAttemptStartedUtc = DateTime.MinValue;
            _rescueCandidate = null;
            _rescueBestDistance = Single.MaxValue;
            _rescueWatchdogUtc = DateTime.UtcNow;
            ResetMoverApproachState();
            LogRescueStage("ApproachInteractionRing", reason);
        }

        private bool ObserveRescueWatchdog()
        {
            Vector2i player = LokiPoe.Me.Position;
            bool uiVisible = _visualCapsuleUiOpen ||
                AllflameContext.CapsuleUiVisible;
            if (_rescueWatchdogUtc == DateTime.MinValue)
            {
                _rescueWatchdogUtc = DateTime.UtcNow;
                _rescueWatchdogPlayer = player;
                _rescueWatchdogUiVisible = uiVisible;
                return false;
            }
            if (uiVisible != _rescueWatchdogUiVisible)
            {
                _rescueWatchdogUiVisible = uiVisible;
                MarkRescueExplicitProgress("CapsuleUiStateChanged");
                return false;
            }
            if (_rescueTargetRegistryOnly &&
                _rescueAnchorReacquireUtc != DateTime.MinValue &&
                DateTime.UtcNow - _rescueAnchorReacquireUtc <
                    TimeSpan.FromSeconds(RegistryAnchorReacquireSeconds + 1))
            {
                return false;
            }
            if (DateTime.UtcNow - _rescueWatchdogUtc <
                TimeSpan.FromSeconds(6))
            {
                return false;
            }
            AllflameLog.Info(
                "CAPSULE_ROUTE_STRATEGY_CHANGED" +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|TargetId=" + _rescueTargetId +
                "|Anchor=" + _rescueTargetAnchor +
                "|RescueCycle=" + _rescueCycle +
                "|Previous=" + _rescueStrategy +
                "|Next=ForcedRotation" +
                "|Reason=WatchdogNoAnchorLiveOrUiProgress" +
                "|LastAction=" + _rescueLastAction);
            if (_mandatoryFinalApproachActive)
            {
                HandleMandatoryFinalApproachFailure(
                    "WatchdogNoProgress",
                    player.DistanceF(_rescueTargetAnchor));
                _rescueWatchdogUtc = DateTime.UtcNow;
                return true;
            }
            RotateZeroLanternRescue("WatchdogNoNovelProgress");
            return true;
        }

        private int RescueElapsedSeconds()
        {
            return _rescueOverallStartedUtc == DateTime.MinValue
                ? 0
                : Math.Max(0, (int)Math.Floor(
                    (DateTime.UtcNow - _rescueOverallStartedUtc)
                        .TotalSeconds));
        }

        private bool RescueUiVisible()
        {
            return _visualCapsuleUiOpen ||
                AllflameContext.CapsuleUiVisible ||
                AllflameContext.CallBathysphereVisible;
        }

        private void LogMandatoryExtractionStatus()
        {
            AllflameLog.Throttled(
                "capsule_mandatory_extraction_status",
                TimeSpan.FromSeconds(1),
                "CAPSULE_MANDATORY_EXTRACTION" +
                "|Task=" + Name +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|Cycle=" + _rescueCycle +
                "|Strategy=" + _rescueStrategy +
                "|RoutePlan=" + _rescueRoutePlan +
                "|TargetId=" + _rescueTargetId +
                "|Anchor=" + _rescueTargetAnchor +
                "|Reloads=" + (_mandatoryFinalApproachActive
                    ? _mandatoryFinalApproachReloads
                    : _rescueRouteReloads) +
                "|ElapsedSeconds=" + RescueElapsedSeconds() +
                "|UiVisible=" + RescueUiVisible() +
                "|NextAction=" + _zeroLanternStage);
        }

        private void MarkRescueExplicitProgress(string reason)
        {
            _rescueWatchdogUtc = DateTime.UtcNow;
            _rescueWatchdogPlayer = LokiPoe.Me == null
                ? new Vector2i()
                : LokiPoe.Me.Position;
            _rescueWatchdogUiVisible = RescueUiVisible();
            AllflameProgressWatchdog.MarkProgress(reason);
