            _rescueFailedAnchorsThisCycle.Add(
                RescueTargetKey(_rescueTargetAnchor));
            AllflameLog.Info(
                "CAPSULE_RESCUE_ANCHOR_REJECTED" +
                "|Task=" + Name +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|Cycle=" + _rescueCycle +
                "|Strategy=" + _rescueStrategy +
                "|RoutePlan=" + _rescueRoutePlan +
                "|TargetId=" + _rescueTargetId +
                "|Anchor=" + _rescueTargetAnchor +
                "|RegistryOnly=" + _rescueTargetRegistryOnly +
                "|LiveObserved=" + _rescueTargetLiveObserved +
                "|Proven=" + _rescueTargetProven +
                "|Reason=" + (reason ?? String.Empty) +
                "|ElapsedSeconds=" + RescueElapsedSeconds() +
                "|UiVisible=" + RescueUiVisible() +
                "|NextAction=RotateTarget");
        }

        private void LogLiveScanWait(string reason)
        {
            AllflameLog.Info(
