        private void LogRescueRouteDelta(Vector2i player, float distance)
        {
            if (_rescueRoutePreviousDistance == Single.MaxValue)
            {
                _rescueRoutePreviousPlayer = player;
                _rescueRoutePreviousDistance = distance;
                return;
            }
            float playerDelta = player.DistanceF(_rescueRoutePreviousPlayer);
            float anchorDelta = _rescueRoutePreviousDistance - distance;
            AllflameLog.Throttled(
                "capsule_rescue_route_delta_" + _rescueRoutePlan,
                TimeSpan.FromMilliseconds(350),
                "CAPSULE_RESCUE_ROUTE_DELTA" +
                "|Task=" + Name +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|Cycle=" + _rescueCycle +
                "|Strategy=" + _rescueStrategy +
                "|RoutePlan=" + _rescueRoutePlan +
                "|TargetId=" + _rescueTargetId +
                "|Anchor=" + _rescueTargetAnchor +
                "|Waypoint=" + _rescueRoutePreviousWaypoint +
                "|PlayerBefore=" + _rescueRoutePreviousPlayer +
                "|PlayerAfter=" + player +
                "|PlayerDelta=" + playerDelta.ToString("0.0") +
                "|AnchorDistanceBefore=" + _rescueRoutePreviousDistance.ToString("0.0") +
                "|AnchorDistanceAfter=" + distance.ToString("0.0") +
                "|DistanceDelta=" + anchorDelta.ToString("0.0") +
                "|WaypointHistory=" + _rescueWaypointHistory.Count +
                "|Reloads=" + _rescueRouteReloads +
                "|ElapsedSeconds=" + RescueElapsedSeconds() +
                "|UiVisible=" + RescueUiVisible() +
                "|NextAction=EvaluateConvergence");
            _rescueRoutePreviousPlayer = player;
            _rescueRoutePreviousDistance = distance;
        }

        private void RecordRescueWaypoint(Vector2i waypoint)
        {
            string key = RescueTargetKey(waypoint);
            _rescueWaypointHistory.Add(key);
            if (_rescueWaypointHistory.Count > 8)
            {
                _rescueWaypointHistory.RemoveAt(0);
            }
        }

        private bool IsRescueWaypointOscillating()
        {
            int count = _rescueWaypointHistory.Count;
            if (count < 4)
            {
                return false;
            }
            string a = _rescueWaypointHistory[count - 1];
            string b = _rescueWaypointHistory[count - 2];
            return !String.Equals(a, b, StringComparison.Ordinal) &&
                String.Equals(
                    a,
                    _rescueWaypointHistory[count - 3],
                    StringComparison.Ordinal) &&
                String.Equals(
                    b,
                    _rescueWaypointHistory[count - 4],
                    StringComparison.Ordinal);
        }

