        private void RotateRegistryReacquireTarget(string reason)
        {
            CapsuleRescueStrategy previous = _rescueStrategy;
            _rescueStrategy = CapsuleRescueStrategy.AlternateCapsule;
            _hasLockedExitAnchor = false;
            _lockedExitDirectApproach = false;
            _rescueTargetId = 0;
            _rescueTargetAnchor = new Vector2i();
            _rescueTargetRegistryOnly = false;
            _rescueTargetLiveObserved = false;
            _rescueTargetProven = false;
            _rescueAnchorReacquireUtc = DateTime.MinValue;
            _rescueAttemptStartedUtc = DateTime.MinValue;
            _rescueRouteReloads = 0;
            ResetMoverApproachState();
            BeginRescueStage(
                ZeroLanternExtractionStage.AcquireCapsule,
                "RegistryTargetRotation");
            AllflameLog.Info(
                "CAPSULE_ROUTE_STRATEGY_CHANGED" +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|RescueCycle=" + _rescueCycle +
                "|Previous=" + previous +
                "|Next=" + _rescueStrategy +
                "|Reason=" + reason +
                "|Action=TryNextRegistryAnchor");
        }

        private void RotateZeroLanternRescue(string reason)
        {
            CapsuleRescueStrategy previous = _rescueStrategy;
            if (_rescueStrategy == CapsuleRescueStrategy.SameCapsuleCandidate)
            {
                _rescueStrategy = CapsuleRescueStrategy.AlternateCapsule;
                _rescueCandidate = null;
            }
            else if (_rescueStrategy == CapsuleRescueStrategy.AlternateCapsule)
            {
                _rescueStrategy = CapsuleRescueStrategy.ReverseBreadcrumb;
                _rescueCandidate = null;
                if (!_rescueRegistryRefreshedThisCycle)
                {
                    if (_mandatoryFinalApproachActive &&
                        _mandatoryFinalApproachReloads >=
                            MandatoryFinalApproachMaximumReloads)
                    {
                        StopMandatoryFinalApproach(
                            "TargetReacquireAfterTwoReloads",
                            LokiPoe.Me == null
                                ? Single.MaxValue
                                : LokiPoe.Me.Position.DistanceF(
                                    _rescueTargetAnchor));
                        return;
                    }
                    _rescueRegistryRefreshedThisCycle = true;
                    if (_mandatoryFinalApproachActive)
                    {
                        _mandatoryFinalApproachReloads++;
                    }
                    try { ExilePather.Reload(true); } catch { }
                    AllflameContext.Refresh(true);
                }
            }
            else if (_rescueStrategy == CapsuleRescueStrategy.ReverseBreadcrumb)
            {
                _rescueStrategy = CapsuleRescueStrategy.LiveObservedCapsule;
                _rescueCandidate = null;
            }
            else
            {
                StartNewZeroLanternRescueCycle(reason);
                return;
            }
            _hasLockedExitAnchor = false;
            _lockedExitDirectApproach = false;
            _rescueTargetId = 0;
            _rescueTargetAnchor = new Vector2i();
            _rescueTargetRegistryOnly = false;
            _rescueTargetLiveObserved = false;
            _rescueTargetProven = false;
            _rescueAnchorReacquireUtc = DateTime.MinValue;
            _rescueApproachCandidates.Clear();
            _rescueCandidateCursor = 0;
            _rescueAttemptStartedUtc = DateTime.MinValue;
            _rescueRouteReloads = 0;
            _openAttempts = 0;
            _callAttempts = 0;
            _callRecoveryCycles = 0;
            _callButtonMissingUtc = DateTime.MinValue;
            _visualCapsuleUiOpen = false;
            ResetMoverApproachState();
            BeginRescueStage(
                ZeroLanternExtractionStage.AcquireCapsule,
                "StrategyRotation");
            AllflameLog.Info(
                "CAPSULE_ROUTE_STRATEGY_CHANGED" +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|RescueCycle=" + _rescueCycle +
                "|Previous=" + previous +
                "|Next=" + _rescueStrategy +
                "|Reason=" + reason);
        }

        private void StartNewZeroLanternRescueCycle(string reason)
        {
            if (_mandatoryFinalApproachActive &&
                _mandatoryFinalApproachReloads >=
                    MandatoryFinalApproachMaximumReloads)
            {
                StopMandatoryFinalApproach(
                    "RescueCycleAfterTwoReloads",
                    LokiPoe.Me == null ||
                    _rescueTargetAnchor == default(Vector2i)
                        ? Single.MaxValue
                        : LokiPoe.Me.Position.DistanceF(
                            _rescueTargetAnchor));
                return;
            }
            _rescueCycle = _rescueCycle >= Int32.MaxValue - 1
                ? 1
                : _rescueCycle + 1;
            _rescueStrategy = CapsuleRescueStrategy.SameCapsuleCandidate;
            _rescueActionsThisCycle.Clear();
            _rescueTargetsThisCycle.Clear();
            _rescueFailedAnchorsThisCycle.Clear();
            _rescueWaypointHistory.Clear();
            _rescueBreadcrumbs.Clear();
            _rescueBreadcrumbCursor = 0;
            _rescueTargetId = 0;
            _rescueTargetAnchor = new Vector2i();
            _rescueTargetRegistryOnly = false;
            _rescueTargetLiveObserved = false;
            _rescueTargetProven = false;
            _rescueRegistryRefreshedThisCycle = false;
            _rescueAnchorReacquireUtc = DateTime.MinValue;
            _rescueRoutePreviousPlayer = new Vector2i();
            _rescueRoutePreviousDistance = Single.MaxValue;
            _rescueRoutePreviousWaypoint = new Vector2i();
            _rescueBreadcrumbStartPlayer = new Vector2i();
            _rescueBreadcrumbStartDistance = Single.MaxValue;
            _rescueBreadcrumbMovedTowardWaypoint = false;
            _rescueRouteReloads = 0;
            _openAttempts = 0;
            _callAttempts = 0;
            _callRecoveryCycles = 0;
            _callButtonMissingUtc = DateTime.MinValue;
            _visualCapsuleUiOpen = false;
            _rescueCooldownUntilUtc = DateTime.UtcNow.AddMilliseconds(750);
            ResetMoverApproachState();
            if (_mandatoryFinalApproachActive)
            {
                _mandatoryFinalApproachReloads++;
                AllflameLog.Info(
                    "CAPSULE_FINAL_APPROACH_RECOVERY" +
                    "|Attempt=" + _mandatoryFinalApproachReloads +
                    "|Reason=RescueCycle" +
                    "|Action=ReloadPather");
            }
            try { ExilePather.Reload(true); } catch { }
            AllflameContext.Refresh(true);
            BeginRescueStage(
                ZeroLanternExtractionStage.AcquireCapsule,
                "NewRescueCycle:" + reason);
            AllflameLog.Info(
                "CAPSULE_RESCUE_CONTINUE" +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|TargetId=0|Anchor=None|RescueCycle=" + _rescueCycle +
                "|Previous=ExhaustedStrategies|Next=AcquireCapsule" +
                "|Reason=" + reason +
                "|Action=RotateWithoutStop" +
                "|CooldownMilliseconds=750");
        }

        private void ResetZeroLanternRescue(string reason)
        {
            _zeroLanternStage = ZeroLanternExtractionStage.AcquireCapsule;
            _rescueStrategy = CapsuleRescueStrategy.SameCapsuleCandidate;
            _rescueStageStartedUtc = DateTime.MinValue;
            _rescueProgressUtc = DateTime.MinValue;
            _rescueAttemptStartedUtc = DateTime.MinValue;
            _rescueCooldownUntilUtc = DateTime.MinValue;
            _rescueWatchdogUtc = DateTime.MinValue;
            _rescueOverallStartedUtc = DateTime.MinValue;
            _rescueAnchorReacquireUtc = DateTime.MinValue;
            _mandatoryFinalApproachStartedUtc = DateTime.MinValue;
            _mandatoryFinalApproachActive = false;
            _mandatoryFinalApproachReloads = 0;
            _rescueAreaHash = AllflameContext.AreaHash;
            _rescueCycle = 0;
            _rescueStageAttempt = 0;
            _rescueRoutePlan = 0;
            _rescueRouteReloads = 0;
            _rescueTargetId = 0;
            _rescueTargetAnchor = new Vector2i();
            _rescueInteractionRange = 0f;
            _rescueBestDistance = Single.MaxValue;
            _rescueAttemptStartPlayer = new Vector2i();
            _rescueWatchdogPlayer = new Vector2i();
            _rescueWatchdogUiVisible = false;
            _rescueTargetRegistryOnly = false;
            _rescueTargetLiveObserved = false;
            _rescueTargetProven = false;
            _rescueRegistryRefreshedThisCycle = false;
            _rescueRoutePreviousPlayer = new Vector2i();
            _rescueRoutePreviousDistance = Single.MaxValue;
            _rescueRoutePreviousWaypoint = new Vector2i();
            _rescueBreadcrumbStartPlayer = new Vector2i();
            _rescueBreadcrumbStartDistance = Single.MaxValue;
            _rescueBreadcrumbMovedTowardWaypoint = false;
            _rescueApproachCandidates.Clear();
            _rescueCandidateCursor = 0;
            _rescueCandidate = null;
            _rescueActionsThisCycle.Clear();
            _rescueTargetsThisCycle.Clear();
            _rescueFailedAnchorsThisCycle.Clear();
            _rescueWaypointHistory.Clear();
            _rescueBreadcrumbs.Clear();
            _rescueBreadcrumbCursor = 0;
            _rescueLastAction = reason ?? String.Empty;
        }

        private void MarkZeroLanternCallConfirmed()
        {
            if (!VoyageRunState.LanternsExhausted)
            {
                return;
            }
            BeginRescueStage(
                ZeroLanternExtractionStage.ConfirmCall,
                "CallObservedOrPhaseTransition");
            AllflameLog.Info(
                "CAPSULE_RESCUE_CALL_CONFIRMED" +
                "|AreaHash=" + AllflameContext.AreaHash +
                "|TargetId=" + _rescueTargetId +
                "|Anchor=" + _rescueTargetAnchor +
                "|RescueCycle=" + _rescueCycle +
                "|ActionResult=True");
            ResetZeroLanternRescue("CallBathysphereConfirmed");
        }

        private void CompleteRescueApproachOnUiConfirmed()
        {
            _rescueApproachCandidates.Clear();
            _rescueCandidateCursor = 0;
            _rescueCandidate = null;
            _rescueActionsThisCycle.Clear();
            _rescueRouteReloads = 0;
            _rescueAttemptStartedUtc = DateTime.MinValue;
            _rescueProgressUtc = DateTime.UtcNow;
            ResetMoverApproachState();
            AllflameProgressWatchdog.MarkProgress(
                "CapsuleUiConfirmed");
        }

        private void RouteToRememberedCapsule(
            Vector2i remembered,
            bool confirmed)
        {
            if (LokiPoe.Me == null)
            {
                return;
            }

            Vector2i player = LokiPoe.Me.Position;
            float distance = player.DistanceF(remembered);
            if (VoyageRunState.LanternsExhausted)
            {
                if (_hasLockedExitAnchor &&
                    _lockedExitAnchor.DistanceF(remembered) <= 25f &&
                    distance <= 65f &&
                    AllflameContext.LanternAuraActive)
                {
                    AllflameContext.Refresh(true);
                    CapsuleSafetySnapshot nearbySafety =
                        VoyageCapsuleSafety.Evaluate(
                            player,
                            remembered,
                            "NearbyAnchorRevalidation");
                    if (nearbySafety.DirectActionAllowed)
                    {
                        if (_safeRouteStartedUtc == DateTime.MinValue)
                        {
                            _safeRouteStartedUtc = DateTime.UtcNow;
                            _safeRouteProgressUtc =
                                _safeRouteStartedUtc;
                        }
                        if (DateTime.UtcNow - _safeRouteStartedUtc >=
                            TimeSpan.FromSeconds(30))
                        {
                            StopSafeExit(
                                "LockedAnchorObjectMissing30Seconds");
                            return;
                        }
                        AllflameLog.Info(
                            "CAPSULE_STATE_CHANGED" +
                            "|From=Proven" +
                            "|To=SafeForCurrentExit" +
                            "|Position=" + remembered +
                            "|Source=NearbyAnchorRevalidation");
                        ResetRoute();
                        return;
                    }
                }
                MoveToSafeExitRoute(remembered);
                return;
            }
            if (!_hasWatchedRouteAnchor ||
                _watchedRouteAnchor.DistanceF(remembered) > 10f)
            {
                _hasWatchedRouteAnchor = true;
                _watchedRouteAnchor = remembered;
                _watchedRouteBestDistance = distance;
                _watchedRouteProgressUtc = DateTime.UtcNow;
                _routeBlockedCount = 0;
            }
            if (distance <= _watchedRouteBestDistance - 8f)
            {
                _watchedRouteBestDistance = distance;
                _watchedRouteProgressUtc = DateTime.UtcNow;
                _routeBlockedCount = 0;
            }
            if (DateTime.UtcNow - _watchedRouteProgressUtc >=
                TimeSpan.FromSeconds(10))
            {
                RejectRememberedCapsule(
                    remembered,
                    "NoDistanceProgress10Seconds");
                return;
            }

            if (!_hasRouteTarget ||
                _routeTarget.DistanceF(remembered) > 10f)
            {
                _hasRouteTarget = true;
                _routeTarget = remembered;
                _bestRouteDistance = distance;
                _routeProgressUtc = DateTime.UtcNow;
                _anchorMissingUtc = DateTime.MinValue;
            }

            if (distance <= _bestRouteDistance - 8f)
            {
                _bestRouteDistance = distance;
                _routeProgressUtc = DateTime.UtcNow;
            }

            if (distance <= 65f)
            {
                if (_anchorMissingUtc == DateTime.MinValue)
                {
                    _anchorMissingUtc = DateTime.UtcNow;
                }
                if (DateTime.UtcNow - _anchorMissingUtc >=
                    TimeSpan.FromSeconds(2))
                {
                    AllflameLog.Info(
                        "CAPSULE_ROUTE_STALE|Target=" + remembered +
                        "|Distance=" + distance.ToString("0.0") +
                        "|Confirmed=" + confirmed +
                        "|Action=RefreshObjectScanWithoutDeletingAnchor");
                    AllflameContext.Refresh(true);
                    ResetRoute();
                    return;
                }
            }

            if (DateTime.UtcNow - _routeProgressUtc >=
                TimeSpan.FromSeconds(5))
            {
                _routeBlockedCount++;
                bool rejectAnchor = _routeBlockedCount >= 3;
                AllflameLog.Info(
                    "CAPSULE_ROUTE_BLOCKED|Target=" + remembered +
                    "|BestDistance=" +
                    _bestRouteDistance.ToString("0.0") +
                    "|CurrentDistance=" +
                    distance.ToString("0.0") +
                    "|Confirmed=" + confirmed +
                    "|BlockedCount=" + _routeBlockedCount + "/3" +
                    "|Action=" +
                    (rejectAnchor
                        ? "MarkUnusableAndSelectLive"
                        : "Repath"));
                if (rejectAnchor)
                {
                    RejectRememberedCapsule(
                        remembered,
                        "ThreeRouteBlockedEvents");
                    return;
                }
                ResetRoute();
                return;
            }

            Vector2i movementTarget;
            bool usingLanternRoute =
                VoyageRunState.TryGetLanternRouteWaypoint(
                    player,
                    remembered,
                    out movementTarget);
            string movementContext = Name + (usingLanternRoute
                ? " lantern route"
                : " remembered capsule");
            bool moving = usingLanternRoute
                ? AllflameMovementCoordinator.MoveTowards(
                    movementTarget,
                    movementContext)
                : MoveTowardsInteraction(
                    movementTarget,
                    movementContext);
            AllflameLog.Throttled(
                "capsule_registry_route",
                TimeSpan.FromSeconds(2),
                "CAPSULE_ROUTE|Source=Registry" +
                "|Target=" + remembered +
                "|MovementTarget=" + movementTarget +
                "|Mode=" +
                (usingLanternRoute
                    ? "LanternBreadcrumbs"
                    : "DirectFinalApproach") +
                "|Distance=" + distance.ToString("0.0") +
                "|Moving=" + moving);
        }

        private void RejectRememberedCapsule(
            Vector2i anchor,
            string reason)
        {
            if (VoyageRunState.LanternsExhausted &&
                _hasLockedExitAnchor &&
                _lockedExitAnchor.DistanceF(anchor) <= 25f)
            {
                _hasConfirmedCapsuleAnchor = true;
                _confirmedCapsuleAnchor = anchor;
                _forceLiveCapsule = false;
                ResetRoute();
                ResetWatchedRouteAnchor();
                AllflameLog.Info(
                    "CAPSULE_UI_RECOVERY_IN_PLACE" +
                    "|Attempt=0" +
                    "|Cycle=" + _openRecoveryCycles + "/" +
                    MaximumRecoveryCycles +
                    "|Anchor=" + anchor +
                    "|Reason=" + reason);
                return;
            }
            VoyageRunState.MarkCapsuleUnusable(
                anchor,
                reason);
            if (_hasConfirmedCapsuleAnchor &&
                _confirmedCapsuleAnchor.DistanceF(anchor) <= 25f)
            {
                _hasConfirmedCapsuleAnchor = false;
                _confirmedCapsuleAnchor = new Vector2i();
            }
            _forceLiveCapsule = true;
            ResetRoute();
            ResetWatchedRouteAnchor();
            AllflameLog.Info(
                "CAPSULE_ROUTE_FAILSAFE" +
                "|RejectedAnchor=" + anchor +
                "|Reason=" + reason +
                "|Action=ForceNearestLiveTargetableCapsule");
        }

        private bool TryGetNearbyLiveCapsule(out Vector2i position)
        {
            position = new Vector2i();
            NetworkObject capsule = AllflameContext.CapsuleObject;
            if (capsule == null ||
                !capsule.IsValid ||
                !capsule.IsTargetable ||
                capsule.Distance > 65f)
            {
                return false;
            }
            position = capsule.Position;
            return true;
        }

        private bool TryConfirmCapsuleWarning(
            out string warningMode,
            out Vector2i warningLocation,
            out double visualCorrelation)
        {
            warningMode = "None";
            warningLocation = new Vector2i();
            visualCorrelation = -1.0;

            // Keep the coverage/anchor guard ahead of every confirmation
            // input, including the new Element-based warning resolver.
            if (!CanUseLockedCapsuleUi("WarningConfirm"))
            {
                warningMode = "Blocked";
                return false;
            }

            if (CapsuleWarningUi.TryClick(
                    out warningMode,
                    out warningLocation))
            {
                return true;
            }

            if (!CapsuleVisualUi.TryFindWarningOk(
                    out warningLocation,
                    out visualCorrelation))
            {
                warningMode = "None";
                return false;
            }

            if (!CanUseLockedCapsuleUi("WarningConfirmVisual"))
            {
                warningMode = "Blocked";
                return false;
            }

            warningMode = "Visual";
            bool inputSent = CapsuleVisualUi.ClickCall(
                warningLocation,
                1);
            AllflameLog.Info(
                "CAPSULE_WARNING_CONFIRM" +
                "|Mode=Visual" +
                "|Action=ClickOk" +
                "|InputSent=" + inputSent +
                "|Correlation=" +
                visualCorrelation.ToString("0.000") +
                "|Client=" + warningLocation);
            return inputSent;
        }

        private bool CanUseLockedCapsuleUi(string action)
        {
            AllflameContext.Refresh(true);
            if (_capsuleReturnUiConfirmed &&
                _hasLockedExitAnchor &&
                _lockedExitAreaHash == AllflameContext.AreaHash)
            {
                return true;
            }
            if (!_hasLockedExitAnchor || LokiPoe.Me == null)
            {
                AllflameLog.Info(
                    "CAPSULE_ACTION_ABORTED_AURA_LOSS" +
                    "|Action=UiRecovery" +
                    "|Reason=ExitAnchorNotLocked" +
                    "|Stage=" + (action ?? String.Empty));
                StopSafeExit("CapsuleUiWithoutLockedExitAnchor");
                return false;
            }

            CapsuleSafetySnapshot safety =
                VoyageCapsuleSafety.Evaluate(
                    LokiPoe.Me.Position,
                    _lockedExitAnchor,
                    action);
            if (safety.DirectActionAllowed)
            {
                return true;
            }
            LogCapsuleActionSafetyRejection(
                safety,
                "UiRecovery",
                action,
                true);
            MoveToSafeExitRoute(_lockedExitAnchor);
            return false;
        }

        private void LogCapsuleActionSafetyRejection(
            CapsuleSafetySnapshot safety,
            string action,
            string stage,
            bool lockedTarget)
        {
            string marker = safety.AuraActive
                ? "CAPSULE_ACTION_ABORTED_COVERAGE_MODEL"
                : "CAPSULE_ACTION_ABORTED_AURA_LOSS";
            string reason = !safety.AuraActive
                ? "AuraInactive"
                : (!lockedTarget
                    ? "ExitAnchorMismatch"
                    : (!safety.PlayerCovered
                        ? "PlayerCoverageMismatch"
                        : (!safety.TargetCovered
                            ? "TargetCoverageRejected"
                            : "SegmentCoverageRejected")));
            AllflameLog.Info(
                marker +
                "|Action=" + (action ?? String.Empty) +
                "|Reason=" + reason +
                "|AuraActive=" + safety.AuraActive +
                "|PlayerCovered=" + safety.PlayerCovered +
                "|TargetCovered=" + safety.TargetCovered +
                "|SegmentCovered=" + safety.SegmentCovered +
                "|LockedTarget=" + lockedTarget +
                "|Stage=" + (stage ?? String.Empty) +
                "|Anchor=" + _lockedExitAnchor);
        }

        private void LockExitAnchor(
            Vector2i anchor,
            bool proven,
            string uiState,
            bool directApproach = false,
            bool forceReplace = false)
        {
            uint areaHash = AllflameContext.AreaHash;
            if (_hasLockedExitAnchor &&
                _lockedExitAreaHash == areaHash &&
                _lockedExitAnchor.DistanceF(anchor) > 25f &&
                !forceReplace)
            {
                return;
            }

            bool changed =
                !_hasLockedExitAnchor ||
                _lockedExitAreaHash != areaHash ||
                _lockedExitAnchor.DistanceF(anchor) > 10f;
            _hasLockedExitAnchor = true;
            _lockedExitAnchor = anchor;
            _lockedExitAreaHash = areaHash;
            if (changed)
            {
                _lockedExitDirectApproach = directApproach;
            }
            else if (directApproach)
            {
                _lockedExitDirectApproach = true;
            }
            _hasConfirmedCapsuleAnchor = true;
            _confirmedCapsuleAnchor = anchor;
            _forceLiveCapsule = false;
            if (changed)
            {
                ResetSafeRoute();
                ResetRoute();
                ResetWatchedRouteAnchor();
                ResetMoverApproachState();
                float distance = LokiPoe.Me == null
                    ? Single.MaxValue
                    : LokiPoe.Me.Position.DistanceF(anchor);
                AllflameLog.Info(
                    "CAPSULE_EXIT_ANCHOR_LOCKED" +
                    "|Position=" + anchor +
                    "|Proven=" + proven +
                    "|Distance=" +
                    (distance == Single.MaxValue
                        ? "Unavailable"
                        : distance.ToString("0.0")) +
                    "|UiState=" + (uiState ?? String.Empty) +
                    "|DirectApproach=" +
                    _lockedExitDirectApproach);
            }
        }

        private static void ResetMoverApproachState()
        {
            AllflameMover mover =
                PlayerMoverManager.Current as AllflameMover;
            if (mover != null)
            {
                mover.ResetApproachState();
            }
        }

        private bool MoveToSafeExitRoute(Vector2i anchor)
        {
            if (LokiPoe.Me == null ||
                AllflameStopController.StopRequested)
            {
                return false;
            }

            AllflameContext.Refresh(true);
            Vector2i player = LokiPoe.Me.Position;
            if (_safeRouteStartedUtc == DateTime.MinValue ||
                _lockedExitAreaHash != 0 &&
                _lockedExitAreaHash != AllflameContext.AreaHash)
            {
                ResetSafeRoute();
                _safeRouteStartedUtc = DateTime.UtcNow;
                _safeRouteProgressUtc = _safeRouteStartedUtc;
            }
            if (DateTime.UtcNow - _safeRouteStartedUtc >=
                TimeSpan.FromMinutes(1))
            {
                StopSafeExit("SafeRouteTotalTimeout60Seconds");
                return false;
            }

            bool lockedDirectApproach =
                _hasLockedExitAnchor &&
                _lockedExitDirectApproach &&
                _lockedExitAreaHash == AllflameContext.AreaHash &&
                _lockedExitAnchor.DistanceF(anchor) <= 25f;
            if (lockedDirectApproach)
            {
                ResetCoverageReentry();
                if (_safeRoutePlanActive)
                {
                    bool sameDirectPlan =
                        _safeRouteFinalAnchor.DistanceF(anchor) <= 10f &&
                        String.Equals(
                            _safeRouteMode,
                            "LockedNearbyDirect",
                            StringComparison.Ordinal);
                    if (sameDirectPlan)
                    {
                        return RunCommittedSafeRoute(player);
                    }
                    InvalidateSafeRoutePlan(
                        "LockedNearbyDirectSelected");
                }
                CommitSafeRoutePlan(
                    anchor,
                    anchor,
                    "LockedNearbyDirect",
                    0,
                    player);
                return RunCommittedSafeRoute(player);
            }

            if (!AllflameContext.LanternAuraActive)
            {
                Vector2i recoveryWaypoint;
                int recoveryOrder;
                bool hasRecoveryWaypoint =
                    VoyageRunState.TryGetReverseSafeBreadcrumb(
                        player,
                        out recoveryWaypoint,
                        out recoveryOrder) ||
                    VoyageRunState.TryGetRecoveryLanternWaypoint(
                        player,
                        out recoveryWaypoint,
                        out recoveryOrder);
                if (!hasRecoveryWaypoint)
                {
                    StopSafeExit("AuraInactiveAndNoLanternBreadcrumb");
                    return false;
                }
                return MoveSafeWaypoint(
                    recoveryWaypoint,
                    "ReverseBreadcrumb",
                    recoveryOrder,
                    false);
            }

            // Runtime aura can remain active while the geometric coverage
            // model temporarily places the player outside every lantern.
            // Re-enter coverage before evaluating any strict Capsule route.
            if (VoyageCapsuleSafety.DistanceToCoverage(player) > 0f)
            {
                return MoveCoverageReentry(player);
            }

            ResetCoverageReentry();

            if (anchor == default(Vector2i))
            {
                StopSafeExit("NoLockedOrRegisteredExitAnchor");
                return false;
            }

            if (_safeRoutePlanActive)
            {
                if (_safeRouteFinalAnchor.DistanceF(anchor) <= 10f)
                {
                    return RunCommittedSafeRoute(player);
                }
                InvalidateSafeRoutePlan("FinalAnchorChanged");
            }

            Vector2i lanternWaypoint;
            if (VoyageRunState.TryGetLanternRouteWaypoint(
                player,
                anchor,
                out lanternWaypoint))
            {
                CapsuleSafetySnapshot routeSafety =
                    VoyageCapsuleSafety.Evaluate(
                        player,
                        lanternWaypoint,
                        "MoveLanternBreadcrumb");
                if (routeSafety.DirectActionAllowed &&
                    player.DistanceF(lanternWaypoint) > 24f)
                {
                    CommitSafeRoutePlan(
                        anchor,
                        lanternWaypoint,
                        "LanternRoute",
                        0,
                        player);
                    return RunCommittedSafeRoute(player);
                }
            }

            CapsuleSafetySnapshot directSafety =
                VoyageCapsuleSafety.Evaluate(
                    player,
                    anchor,
                    "MoveDirectCapsule");
            if (directSafety.DirectActionAllowed)
            {
                CommitSafeRoutePlan(
                    anchor,
                    anchor,
                    "CoveredDirectSegment",
                    0,
                    player);
                return RunCommittedSafeRoute(player);
            }

            Vector2i safeBreadcrumb;
            int safeBreadcrumbStep;
            if (VoyageRunState.TryGetReverseSafeBreadcrumb(
                    player,
                    out safeBreadcrumb,
                    out safeBreadcrumbStep))
            {
                CapsuleSafetySnapshot breadcrumbSafety =
                    VoyageCapsuleSafety.Evaluate(
                        player,
                        safeBreadcrumb,
                        "MoveSafeBreadcrumb");
                bool convergesToAnchor =
                    safeBreadcrumb.DistanceF(anchor) <=
                    player.DistanceF(anchor) + 10f;
                if (breadcrumbSafety.DirectActionAllowed &&
                    convergesToAnchor)
                {
                    CommitSafeRoutePlan(
                        anchor,
                        safeBreadcrumb,
                        "ReverseBreadcrumb",
                        safeBreadcrumbStep,
                        player);
                    return RunCommittedSafeRoute(player);
                }
                if (!convergesToAnchor)
                {
                    AllflameLog.Info(
                        "CAPSULE_ROUTE_CANDIDATE_REJECTED" +
                        "|Mode=ReverseBreadcrumb" +
                        "|Waypoint=" + safeBreadcrumb +
                        "|FinalAnchor=" + anchor +
                        "|Reason=MovesAwayFromLockedAnchor");
                }
            }

            string rejectionReason = !directSafety.AuraActive
                ? "AuraInactive"
                : (!directSafety.PlayerCovered
                    ? "PlayerOutsideCoverage"
                    : (!directSafety.TargetCovered
                        ? "TargetOutsideCoverage"
                        : "SegmentOutsideCoverage"));
            AllflameLog.Info(
                "CAPSULE_DIRECT_ROUTE_REJECTED" +
                "|Reason=" + rejectionReason +
                "|Player=" + player +
                "|Target=" + anchor);
            StopSafeExit("NoCoveredRouteToExitAnchor:" + rejectionReason);
            return false;
        }

        private void CommitSafeRoutePlan(
            Vector2i finalAnchor,
            Vector2i waypoint,
            string mode,
            int waypointIndex,
            Vector2i player)
        {
            _safeRoutePlanSequence++;
            _safeRoutePlanActive = true;
            _safeRouteFinalAnchor = finalAnchor;
            _safeRouteTarget = waypoint;
            _safeRouteMode = mode ?? String.Empty;
            _safeRouteWaypointIndex = waypointIndex;
            _safeRouteSelectedUtc = DateTime.UtcNow;
            _safeRouteBestAnchorDistance =
                player.DistanceF(finalAnchor);
            _safeRouteBestDistance = player.DistanceF(waypoint);
            _safeRouteProgressUtc = _safeRouteSelectedUtc;
            _safeRouteMoveFailedUtc = DateTime.MinValue;
            AllflameLog.Info(
                "CAPSULE_ROUTE_PLAN_SELECTED" +
                "|RoutePlanId=" + _safeRoutePlanSequence +
                "|FinalAnchor=" + finalAnchor +
                "|Mode=" + _safeRouteMode +
                "|CurrentWaypoint=" + waypoint +
                "|WaypointIndex=" + waypointIndex +
                "|AnchorDistance=" +
                _safeRouteBestAnchorDistance.ToString("0.0") +
                "|WaypointDistance=" +
                _safeRouteBestDistance.ToString("0.0"));
        }

        private bool RunCommittedSafeRoute(Vector2i player)
        {
            float waypointDistance =
                player.DistanceF(_safeRouteTarget);
            float anchorDistance =
                player.DistanceF(_safeRouteFinalAnchor);
            if (waypointDistance <= 24f)
            {
                InvalidateSafeRoutePlan("WaypointReached");
                ResetMoverApproachState();
                return false;
            }

            CapsuleSafetySnapshot safety =
                VoyageCapsuleSafety.Evaluate(
                    player,
                    _safeRouteTarget,
                    "CommittedRoutePlan");
            bool directLockedApproach = String.Equals(
                _safeRouteMode,
                "LockedNearbyDirect",
                StringComparison.Ordinal);
            if (!directLockedApproach &&
                !safety.DirectActionAllowed)
            {
                InvalidateSafeRoutePlan("WaypointSafetyLost");
                ResetMoverApproachState();
                return false;
            }
            if (anchorDistance <= _safeRouteBestAnchorDistance - 3f)
            {
                _safeRouteBestAnchorDistance = anchorDistance;
                _safeRouteProgressUtc = DateTime.UtcNow;
            }
            return MoveSafeWaypoint(
                _safeRouteTarget,
                _safeRouteMode,
                _safeRouteWaypointIndex,
                !directLockedApproach);
        }

        private void InvalidateSafeRoutePlan(string reason)
        {
            if (_safeRoutePlanActive)
            {
                AllflameLog.Info(
                    "CAPSULE_ROUTE_PLAN_INVALIDATED" +
                    "|RoutePlanId=" + _safeRoutePlanSequence +
                    "|FinalAnchor=" + _safeRouteFinalAnchor +
                    "|Mode=" + _safeRouteMode +
                    "|CurrentWaypoint=" + _safeRouteTarget +
                    "|Reason=" + (reason ?? String.Empty) +
                    "|ElapsedMilliseconds=" +
                    (_safeRouteSelectedUtc == DateTime.MinValue
                        ? 0
                        : (int)(DateTime.UtcNow -
                            _safeRouteSelectedUtc).TotalMilliseconds));
            }
            _safeRoutePlanActive = false;
            _safeRouteFinalAnchor = new Vector2i();
            _safeRouteMode = String.Empty;
            _safeRouteWaypointIndex = 0;
            _safeRouteSelectedUtc = DateTime.MinValue;
            _safeRouteTarget = new Vector2i();
            _safeRouteBestDistance = Single.MaxValue;
            _safeRouteBestAnchorDistance = Single.MaxValue;
            _safeRouteMoveFailedUtc = DateTime.MinValue;
        }

        private bool MoveCoverageReentry(Vector2i player)
        {
            DateTime now = DateTime.UtcNow;
            if (_coverageReentryStartedUtc == DateTime.MinValue)
            {
                _coverageReentryStartedUtc = now;
                _coverageReentryProgressUtc = now;
                _coverageReentryBestDistance =
                    VoyageCapsuleSafety.DistanceToCoverage(player);
                _coverageReentryBreadcrumbs.AddRange(
                    VoyageRunState.GetSafeBreadcrumbsNewestFirst());
                _coverageReentryLanterns.AddRange(
                    VoyageRunState.GetLanternAnchorsNewestFirst());
                AllflameLog.Info(
                    "CAPSULE_REENTRY_START" +
                    "|Player=" + player +
                    "|DistanceToCoverage=" +
                    _coverageReentryBestDistance.ToString("0.0") +
                    "|AuraActive=" +
                    AllflameContext.LanternAuraActive);
            }

            float distanceToCoverage =
                VoyageCapsuleSafety.DistanceToCoverage(player);
            if (distanceToCoverage <= 0f)
            {
                AllflameLog.Info(
                    "CAPSULE_REENTRY_COMPLETE" +
                    "|PlayerCovered=True|Recoveries=" +
                    _safeRouteRecoveries);
                ResetCoverageReentry();
                return false;
            }
            if (distanceToCoverage <= _coverageReentryBestDistance - 3f)
            {
                float improvement =
                    _coverageReentryBestDistance - distanceToCoverage;
                _coverageReentryBestDistance = distanceToCoverage;
                _coverageReentryProgressUtc = now;
                AllflameLog.Info(
                    "CAPSULE_REENTRY_PROGRESS" +
                    "|From=" + player +
                    "|Target=" + _coverageReentryCandidate +
                    "|DistanceToCoverage=" +
                    distanceToCoverage.ToString("0.0") +
                    "|Improvement=" + improvement.ToString("0.0") +
                    "|AuraActive=True");
            }

            if (now - _coverageReentryStartedUtc >=
                TimeSpan.FromSeconds(30))
            {
                StopSafeExit("CoverageReentryTimeout30Seconds");
                return false;
            }

            if (now - _coverageReentryProgressUtc >=
                TimeSpan.FromSeconds(4))
            {
                if (_hasCoverageReentryCandidate)
                {
                    RejectCoverageReentryCandidate(
                        _coverageReentryCandidate,
                        "NoProgress");
                }
                if (_safeRouteRecoveries < 2)
                {
                    _safeRouteRecoveries++;
                    try
                    {
                        ExilePather.Reload(true);
                    }
                    catch
                    {
                    }
                    _coverageReentryProgressUtc = now;
                    _coverageReentryBestDistance = distanceToCoverage;
                    _safeRouteCooldownUntilUtc =
                        now.AddMilliseconds(250);
                    AllflameLog.Info(
                        "CAPSULE_REENTRY_RECOVERY" +
                        "|Attempt=" + _safeRouteRecoveries +
                        "|Reason=NoProgress|Action=ReloadPather" +
                        "|DistanceToCoverage=" +
                        distanceToCoverage.ToString("0.0"));
                }
                _coverageReentryProgressUtc = now;
                _coverageReentryBestDistance = distanceToCoverage;
            }

            if (now < _safeRouteCooldownUntilUtc)
            {
                return false;
            }
            if (!_hasCoverageReentryCandidate &&
                !TrySelectCoverageReentryCandidate(player))
            {
                if (!_coverageReentryScanComplete)
                {
                    return false;
                }
                AllflameLog.Info(
                    "CAPSULE_REENTRY_EXHAUSTED" +
                    "|BreadcrumbsTried=" +
                    _coverageReentryBreadcrumbsTried +
                    "|LanternsTried=" +
                    _coverageReentryLanternsTried +
                    "|Recoveries=" + _safeRouteRecoveries +
                    "|ElapsedMilliseconds=" +
                    (int)(now - _coverageReentryStartedUtc)
                        .TotalMilliseconds);
                StopSafeExit("CoverageReentryCandidatesExhausted");
                return false;
            }

            Vector2i movementTarget;
            string stepReason;
            if (!TryResolveCoverageReentryStep(
                player,
                _coverageReentryCandidate,
                out movementTarget,
                out stepReason))
            {
                RejectCoverageReentryCandidate(
                    _coverageReentryCandidate,
                    stepReason);
                return false;
            }
            bool moving = AllflameMovementCoordinator.MoveTowards(
                movementTarget,
                Name + " coverage re-entry");
            AllflameLog.Throttled(
                "capsule_reentry_route",
                TimeSpan.FromSeconds(1),
                "CAPSULE_REENTRY_PROGRESS" +
                "|From=" + player +
                "|Target=" + movementTarget +
                "|DistanceToCoverage=" +
                distanceToCoverage.ToString("0.0") +
                "|AuraActive=True" +
                "|Moving=" + moving);
            return moving;
        }

        private bool TrySelectCoverageReentryCandidate(Vector2i player)
        {
            DateTime deadline =
                DateTime.UtcNow.AddSeconds(2);
            while (_coverageReentryBreadcrumbCursor <
                _coverageReentryBreadcrumbs.Count)
            {
                if (DateTime.UtcNow > deadline)
                {
                    return false;
                }
                int i = _coverageReentryBreadcrumbCursor++;
                _coverageReentryBreadcrumbsTried++;
                if (TryAcceptCoverageReentryCandidate(
                    player,
                    _coverageReentryBreadcrumbs[i],
                    "SafeBreadcrumb",
                    i + 1))
                {
                    return true;
                }
            }

            while (_coverageReentryLanternCursor <
                _coverageReentryLanterns.Count)
            {
                if (DateTime.UtcNow > deadline)
                {
                    return false;
                }
                int i = _coverageReentryLanternCursor++;
                _coverageReentryLanternsTried++;
                if (TryAcceptCoverageReentryCandidate(
                    player,
                    _coverageReentryLanterns[i],
                    "LanternAnchor",
                    i + 1))
                {
                    return true;
                }
            }
            _coverageReentryScanComplete = true;
            return false;
        }

        private bool TryAcceptCoverageReentryCandidate(
            Vector2i player,
            Vector2i candidate,
            string source,
            int index)
        {
            if (_coverageReentryRejected.Any(
                position => position.DistanceF(candidate) <= 10f))
            {
                return false;
            }
            if (!VoyageRunState.IsPositionWithinLanternCoverage(
                candidate,
                120f))
            {
                LogCoverageReentryCandidate(
                    source, index, candidate, "TargetOutsideCoverage");
                return false;
            }

            bool pathable;
            try
            {
                pathable = ExilePather.PathExistsBetween(
                    player, candidate, false);
            }
            catch
            {
                pathable = false;
            }
            if (!pathable)
            {
                LogCoverageReentryCandidate(
                    source, index, candidate, "NoPath");
                return false;
            }

            Vector2i ignoredStep;
            string stepReason;
            if (!TryResolveCoverageReentryStep(
                player, candidate, out ignoredStep, out stepReason))
            {
                LogCoverageReentryCandidate(
                    source, index, candidate, stepReason);
                return false;
            }
            _hasCoverageReentryCandidate = true;
            _coverageReentryCandidate = candidate;
            _coverageReentrySource = source;
            _coverageReentryIndex = index;
            LogCoverageReentryCandidate(
                source, index, candidate, "Selected");
            return true;
        }

        private static bool TryResolveCoverageReentryStep(
            Vector2i player,
            Vector2i candidate,
            out Vector2i step,
            out string reason)
        {
            step = LimitCoverageReentryStep(
                player, candidate, 35f);
            reason = String.Empty;
            float currentDistance =
                VoyageCapsuleSafety.DistanceToCoverage(player);
            float stepDistance =
                VoyageCapsuleSafety.DistanceToCoverage(step);
            if (stepDistance > currentDistance + 2f)
            {
                reason = "RouteMovesDeeper";
                return false;
            }

            try
            {
                PathfindingCommand command =
                    new PathfindingCommand(player, step, 3f);
                if (!ExilePather.FindPath(ref command) ||
                    command.Path == null ||
                    command.Path.Count == 0)
                {
                    reason = "StepNotPathable";
                    return false;
                }
                if (command.Path.Any(point =>
                    VoyageCapsuleSafety.DistanceToCoverage(point) >
                        currentDistance + 2f))
                {
                    reason = "PathMovesDeeper";
                    return false;
                }
            }
            catch
            {
                reason = "StepPathException";
                return false;
            }
            return true;
        }

        private void LogCoverageReentryCandidate(
            string source,
            int index,
            Vector2i position,
            string result)
        {
            AllflameLog.Info(
                "CAPSULE_REENTRY_CANDIDATE" +
                "|Source=" + source +
                "|Index=" + index +
                "|Position=" + position +
                "|PlayerCovered=False" +
                "|TargetCovered=" +
                VoyageRunState.IsPositionWithinLanternCoverage(
                    position, 120f) +
                "|Result=" +
                (result == "Selected" ? "Selected" : "Rejected") +
                "|Reason=" + result);
        }

        private void RejectCoverageReentryCandidate(
            Vector2i candidate,
            string reason)
        {
            if (!_coverageReentryRejected.Any(
                position => position.DistanceF(candidate) <= 10f))
            {
                _coverageReentryRejected.Add(candidate);
            }
            _hasCoverageReentryCandidate = false;
            _coverageReentryCandidate = new Vector2i();
            LogCoverageReentryCandidate(
                _coverageReentrySource,
                _coverageReentryIndex,
                candidate,
                reason);
        }

        private static Vector2i LimitCoverageReentryStep(
            Vector2i player,
            Vector2i target,
            float maximumDistance)
        {
            float distance = player.DistanceF(target);
            if (distance <= maximumDistance)
            {
                return target;
            }
            double ratio = maximumDistance / distance;
            return new Vector2i(
                (int)Math.Round(player.X +
                    (target.X - player.X) * ratio),
                (int)Math.Round(player.Y +
                    (target.Y - player.Y) * ratio));
        }

        private bool MoveSafeWaypoint(
            Vector2i waypoint,
            string mode,
            int step,
            bool requireAura)
        {
            AllflameContext.Refresh(true);
            if (requireAura &&
                !AllflameContext.LanternAuraActive)
            {
                AllflameLog.Info(
                    "CAPSULE_ACTION_ABORTED_AURA_LOSS" +
                    "|Action=Move" +
                    "|Target=" + waypoint +
                    "|Mode=" + mode);
                Vector2i recoveryWaypoint;
                int recoveryOrder;
                if (LokiPoe.Me != null &&
                    (VoyageRunState.TryGetReverseSafeBreadcrumb(
                         LokiPoe.Me.Position,
                         out recoveryWaypoint,
                         out recoveryOrder) ||
                     VoyageRunState.TryGetRecoveryLanternWaypoint(
                         LokiPoe.Me.Position,
                         out recoveryWaypoint,
                         out recoveryOrder)))
                {
                    return MoveSafeWaypoint(
                        recoveryWaypoint,
                        "ReverseBreadcrumb",
                        recoveryOrder,
                        false);
                }
                StopSafeExit("AuraLostBeforeMoveAndNoBreadcrumb");
                return false;
            }

            if (LokiPoe.Me == null ||
                DateTime.UtcNow < _safeRouteCooldownUntilUtc)
            {
                return false;
            }

            Vector2i player = LokiPoe.Me.Position;
            float distance = player.DistanceF(waypoint);
            if (_safeRouteTarget.DistanceF(waypoint) > 10f ||
                _safeRouteBestDistance == Single.MaxValue)
            {
                _safeRouteTarget = waypoint;
                _safeRouteBestDistance = distance;
                _safeRouteProgressUtc = DateTime.UtcNow;
            }
            else if (distance <= _safeRouteBestDistance - 3f)
            {
                _safeRouteBestDistance = distance;
                _safeRouteProgressUtc = DateTime.UtcNow;
            }

            if (DateTime.UtcNow - _safeRouteProgressUtc >=
                TimeSpan.FromSeconds(4))
            {
                if (_safeRouteRecoveries >= 2)
                {
                    StopSafeExit("SafeRouteNoProgressAfterTwoReloads");
                    return false;
                }
                _safeRouteRecoveries++;
                try
                {
                    ExilePather.Reload(true);
                }
                catch
                {
                }
                _safeRouteProgressUtc = DateTime.UtcNow;
                _safeRouteBestDistance = distance;
                _safeRouteCooldownUntilUtc =
                    DateTime.UtcNow.AddMilliseconds(500);
                return false;
            }

            AllflameContext.Refresh(true);
            if (requireAura &&
                !AllflameContext.LanternAuraActive)
            {
                AllflameLog.Info(
                    "CAPSULE_ACTION_ABORTED_AURA_LOSS" +
                    "|Action=Move" +
                    "|Target=" + waypoint +
                    "|Mode=" + mode);
                return MoveToSafeExitRoute(
                    _hasLockedExitAnchor
                        ? _lockedExitAnchor
                        : new Vector2i());
            }

            bool preciseInteraction = String.Equals(
                mode,
                "LockedNearbyDirect",
                StringComparison.Ordinal);
            bool moving = preciseInteraction
                ? MoveTowardsInteraction(
                    waypoint,
                    Name + " " + mode)
                : AllflameMovementCoordinator.MoveTowards(
                    waypoint,
                    Name + " " + mode);
            if (moving)
            {
                _safeRouteMoveFailedUtc = DateTime.MinValue;
            }
            else if (_safeRouteMoveFailedUtc == DateTime.MinValue)
            {
                _safeRouteMoveFailedUtc = DateTime.UtcNow;
            }
            else if (DateTime.UtcNow - _safeRouteMoveFailedUtc >=
                TimeSpan.FromSeconds(2))
            {
                if (_safeRouteRecoveries >= 2)
                {
                    StopSafeExit("SafeRoutePathFailureAfterTwoReloads");
                    return false;
                }
                _safeRouteRecoveries++;
                try
                {
                    ExilePather.Reload(true);
                }
                catch
                {
                }
                AllflameLog.Info(
                    "CAPSULE_SAFE_ROUTE_RECOVERY" +
                    "|Attempt=" + _safeRouteRecoveries +
                    "|Reason=PathFailure" +
                    "|RoutePlanId=" + _safeRoutePlanSequence +
                    "|Waypoint=" + waypoint +
                    "|Action=ReloadPatherAndReselect");
                InvalidateSafeRoutePlan("PathFailureRecovery");
                ResetMoverApproachState();
                _safeRouteCooldownUntilUtc =
                    DateTime.UtcNow.AddMilliseconds(250);
                return false;
            }
            AllflameLog.Throttled(
                "capsule_safe_route",
                TimeSpan.FromSeconds(1),
                "CAPSULE_SAFE_ROUTE" +
                "|RoutePlanId=" +
                (_safeRoutePlanActive
                    ? _safeRoutePlanSequence.ToString()
                    : "None") +
                "|FinalAnchor=" +
                (_safeRoutePlanActive
                    ? _safeRouteFinalAnchor.ToString()
                    : "None") +
                "|Mode=" + mode +
                "|Waypoint=" + waypoint +
                "|Step=" + step +
                "|AuraActive=" +
                AllflameContext.LanternAuraActive +
                "|Distance=" + distance.ToString("0.0") +
                "|BestWaypointDistance=" +
                _safeRouteBestDistance.ToString("0.0") +
                "|BestAnchorDistance=" +
                (_safeRouteBestAnchorDistance == Single.MaxValue
                    ? "Unavailable"
                    : _safeRouteBestAnchorDistance.ToString("0.0")) +
                "|Moving=" + moving +
                "|Recoveries=" + _safeRouteRecoveries);
            return moving;
        }

        private void StopSafeExit(string reason)
        {
            string detail =
                "Reason=" + (reason ?? String.Empty) +
                "|Anchor=" +
                (_hasLockedExitAnchor
                    ? _lockedExitAnchor.ToString()
                    : "None") +
                "|AuraActive=" +
                AllflameContext.LanternAuraActive +
                "|Recoveries=" + _safeRouteRecoveries +
                "|ActiveTask=UseAllflameCapsuleTask";
            if (VoyageRunState.LanternsExhausted)
            {
                if (_capsuleReturnUiConfirmed)
                {
                    AllflameStopController.Stop(
                        reason,
                        (detail ?? String.Empty) +
                        "|ActiveTask=" + Name +
                        "|CachedCapsuleUi=True" +
                        "|Action=RecoveryStopWithoutCapsuleReinteraction");
                    return;
                }
                AllflameLog.Info(
                    "CAPSULE_SAFE_EXIT_UNAVAILABLE" +
                    "|" + detail +
                    "|Action=RotateRescueStrategy");
                RotateZeroLanternRescue(
                    "LegacySafeRouteRejected:" + reason);
                return;
            }
            AllflameLog.Info(
                "CAPSULE_SAFE_EXIT_UNAVAILABLE" +
                "|" + detail +
                "|Action=RecoveryStop");
            AllflameStopController.Stop(
                "ZeroLanternCapsuleSafeExitUnavailable",
                detail);
        }

        private void HandleCapsuleUiFailure(
            string reason,
            string detail)
        {
            if (VoyageRunState.LanternsExhausted)
            {
                AllflameLog.Info(
                    "CAPSULE_ROUTE_STRATEGY_CHANGED" +
                    "|AreaHash=" + AllflameContext.AreaHash +
                    "|TargetId=" + _rescueTargetId +
                    "|Anchor=" + _rescueTargetAnchor +
                    "|RescueCycle=" + _rescueCycle +
                    "|Previous=CapsuleUi|Next=AcquireCapsule" +
                    "|Reason=" + reason +
                    "|Detail=" + (detail ?? String.Empty));
                RotateZeroLanternRescue(reason);
                return;
            }
            AllflameStopController.Stop(reason, detail);
        }

        private void LogUiRecoveryInPlace()
        {
            if (!_hasLockedExitAnchor)
            {
                return;
            }
            AllflameLog.Info(
                "CAPSULE_UI_RECOVERY_IN_PLACE" +
                "|Attempt=3" +
                "|Cycle=" + _callRecoveryCycles + "/" +
                MaximumRecoveryCycles +
                "|Anchor=" + _lockedExitAnchor);
        }

        private void ResetSafeRoute()
        {
            InvalidateSafeRoutePlan("RouteReset");
            _safeRouteStartedUtc = DateTime.MinValue;
            _safeRouteProgressUtc = DateTime.MinValue;
            _safeRouteCooldownUntilUtc = DateTime.MinValue;
            _safeRouteTarget = new Vector2i();
            _safeRouteBestDistance = Single.MaxValue;
            _safeRouteRecoveries = 0;
            ResetCoverageReentry();
        }

        private void ResetCoverageReentry()
        {
            _coverageReentryStartedUtc = DateTime.MinValue;
            _coverageReentryProgressUtc = DateTime.MinValue;
            _coverageReentryBestDistance = Single.MaxValue;
            _hasCoverageReentryCandidate = false;
            _coverageReentryCandidate = new Vector2i();
            _coverageReentrySource = String.Empty;
            _coverageReentryIndex = 0;
            _coverageReentryBreadcrumbsTried = 0;
            _coverageReentryLanternsTried = 0;
            _coverageReentryRejected.Clear();
            _coverageReentryBreadcrumbs.Clear();
            _coverageReentryLanterns.Clear();
            _coverageReentryBreadcrumbCursor = 0;
            _coverageReentryLanternCursor = 0;
            _coverageReentryScanComplete = false;
        }

