        }

        private static Item GetTransferableInventoryItem()
        {
            try
            {
                Inventory inventory =
                    LokiPoe.InGameState.InventoryUi
                        .InventoryControl_Main.Inventory;
                return inventory.Items.FirstOrDefault(item =>
                    item != null &&
                    item.IsValid &&
                    !AllflameContext.IsChartItem(item));
            }
            catch
            {
                return null;
            }
        }

        private static bool TryGetCapsuleContainerItemCount(
            out int count)
        {
            count = 0;
            try
            {
                if (!AllflameContext.CapsuleUiVisible ||
                    !LokiPoe.InGameState.StashUi.IsOpened)
                {
                    return false;
                }

                List<Item> items =
                    LokiPoe.InGameState.StashUi.AllItems;
                if (items == null)
                {
                    return false;
                }

                count = items.Count(item =>
                    item != null &&
                    item.IsValid);
                return true;
            }
            catch
            {
                count = 0;
                return false;
            }
        }

        private static bool TryConfirmNativeCapsuleSend(
            out string confirmation)
        {
            confirmation = "None";
            DpbCapsuleSnapshot snapshot;
            string reason;
            if (!DpbNativeApi.TryCaptureCapsule(
                    out snapshot,
                    out reason))
            {
                confirmation = "SnapshotUnavailable:" + reason;
                return false;
            }
            if (!snapshot.IsOpened)
            {
                confirmation = "CapsuleClosed";
                return true;
            }
            if (!snapshot.SendToSurfaceEnabled)
            {
                confirmation = "SendDisabled";
                return true;
            }
            int remaining;
            if (TryCountInventoryItems(
                    snapshot.InventoryControl,
                    out remaining) &&
                remaining == 0)
            {
                confirmation = "NativeContainerEmpty";
                return true;
            }
            confirmation = "ContainerStillHasItems";
            return false;
        }

        private static bool TryConfirmNativeCapsuleCall(
            out string confirmation)
        {
            confirmation = "None";
            if (AllflameContext.ExtractionAvailable)
            {
                confirmation = "ExtractionAvailable";
                return true;
            }
            if (AllflameContext.BathysphereCallObserved)
            {
                confirmation = "BathysphereCallObserved";
                return true;
            }
            DpbCapsuleSnapshot snapshot;
            string reason;
            if (DpbNativeApi.TryCaptureCapsule(
                    out snapshot,
                    out reason) &&
                !snapshot.IsOpened)
            {
                confirmation = "CapsuleClosed";
                return true;
            }
            confirmation = "ExtractionNotObserved" +
                (String.IsNullOrEmpty(reason)
                    ? String.Empty
                    : ":" + reason);
            return false;
        }

        private static bool TryCountInventoryItems(
            InventoryControlWrapper control,
            out int count)
        {
            count = 0;
            try
            {
                if (control == null ||
                    control.Inventory == null ||
                    control.Inventory.Items == null)
                {
                    return false;
                }
                count = control.Inventory.Items.Count(item =>
                    item != null && item.IsValid);
                return true;
            }
            catch
            {
                count = 0;
                return false;
            }
        }

        private static async Task<bool> CtrlClickInventoryItem(
            Item item)
        {
            await Task.CompletedTask;
            if (item == null || item.LocalId <= 0)
            {
                return false;
            }
            try
            {
                InventoryControlWrapper control =
                    LokiPoe.InGameState.InventoryUi
                        .InventoryControl_Main;
                if (control == null ||
                    control.Inventory == null)
                {
                    return false;
                }
                FastMoveResult result =
                    control.FastMove(item.LocalId);
                AllflameLog.Info(
                    "CAPSULE_TRANSFER_INPUT" +
                    "|Strategy=InventoryFastMove" +
                    "|LocalId=" + item.LocalId +
                    "|Result=" + result +
                    "|Action=ReturnToTaskManager");
                return result == FastMoveResult.None;
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "CAPSULE_TRANSFER_INPUT" +
                    "|Strategy=InventoryFastMove" +
                    "|Result=Exception" +
                    "|Error=" + ex.GetType().Name +
                    ":" + ex.Message);
                return false;
            }
        }

        private bool TryGetMandatoryFinalApproachStep(
            Vector2i player,
            Vector2i anchor,
            out Vector2i waypoint)
        {
            waypoint = anchor;
            float distance = player.DistanceF(anchor);
            if (!_mandatoryFinalApproachActive ||
                distance <= 1f ||
                distance > VoyageRunState.CapsuleNearbyExitDistance + 10f)
            {
                return false;
            }

            double dx = anchor.X - player.X;
            double dy = anchor.Y - player.Y;
            double length = Math.Sqrt(dx * dx + dy * dy);
            foreach (float requestedLength in
                MandatoryFinalApproachStepLengths)
            {
                float stepLength = Math.Min(
                    requestedLength,
                    Math.Max(12f, distance - 24f));
                Vector2i candidate = new Vector2i(
                    player.X + (int)Math.Round(dx / length * stepLength),
                    player.Y + (int)Math.Round(dy / length * stepLength));
                bool pathable = false;
                try
                {
                    PathfindingCommand command =
                        new PathfindingCommand(player, candidate, 3f);
                    pathable = ExilePather.FindPath(ref command) &&
                        command.Path != null &&
                        command.Path.Count > 0 &&
                        candidate.DistanceF(anchor) < distance - 1f;
                }
                catch
                {
                    pathable = false;
                }
                AllflameLog.Info(
                    "CAPSULE_FINAL_APPROACH_STEP" +
                    "|From=" + player +
                    "|Waypoint=" + candidate +
                    "|Target=" + anchor +
                    "|DistanceBefore=" + distance.ToString("0.0") +
                    "|StepLength=" + player.DistanceF(candidate).ToString("0.0") +
                    "|Path=" + pathable +
                    "|Result=" + (pathable ? "Selected" : "Rejected"));
                if (pathable)
                {
                    waypoint = candidate;
                    return true;
                }
            }
            return false;
        }

        private void HandleMandatoryFinalApproachFailure(
            string reason,
            float distance)
        {
            AllflameLog.Throttled(
                "capsule_final_approach_no_path",
                TimeSpan.FromMilliseconds(750),
                "CAPSULE_FINAL_APPROACH_PROGRESS" +
                "|Distance=" + distance.ToString("0.0") +
                "|BestDistance=" + _rescueBestDistance.ToString("0.0") +
                "|NoProgressSeconds=" + Math.Max(
                    0,
                    (int)Math.Floor(
                        (DateTime.UtcNow - _rescueProgressUtc)
                            .TotalSeconds)) +
                "|Reloads=" + _mandatoryFinalApproachReloads +
                "|Result=" + reason);
            if (_rescueProgressUtc == DateTime.MinValue)
            {
                _rescueProgressUtc = DateTime.UtcNow;
                return;
            }
            if (DateTime.UtcNow - _rescueProgressUtc <
                TimeSpan.FromSeconds(
                    MandatoryFinalApproachNoProgressSeconds))
            {
                return;
            }
            if (_mandatoryFinalApproachReloads <
                MandatoryFinalApproachMaximumReloads)
            {
                _rescueRouteReloads++;
                _mandatoryFinalApproachReloads++;
                try { ExilePather.Reload(true); } catch { }
                _rescueProgressUtc = DateTime.UtcNow;
                _rescueBestDistance = distance;
                _rescueWatchdogUtc = DateTime.UtcNow;
                _rescueApproachCandidates.Clear();
                _rescueCandidate = null;
                _rescueCandidateCursor = 0;
                _rescueActionsThisCycle.Clear();
                ResetMoverApproachState();
                AllflameLog.Info(
                    "CAPSULE_FINAL_APPROACH_RECOVERY" +
                    "|Attempt=" + _mandatoryFinalApproachReloads +
                    "|Reason=" + reason +
                    "|Distance=" + distance.ToString("0.0") +
                    "|Action=ReloadPather");
                return;
            }
            StopMandatoryFinalApproach(
                reason + "AfterTwoReloads",
                distance);
        }

        private bool StopMandatoryFinalApproachOnTimeout(
            AllflameSettings settings,
            NetworkObject live)
        {
            if (!_mandatoryFinalApproachActive ||
                _mandatoryFinalApproachStartedUtc == DateTime.MinValue ||
                DateTime.UtcNow - _mandatoryFinalApproachStartedUtc <
                    TimeSpan.FromSeconds(
                        MandatoryFinalApproachTimeoutSeconds) ||
                _zeroLanternStage >= ZeroLanternExtractionStage.Stabilize)
            {
                return false;
            }

            float distance = LokiPoe.Me == null
                ? Single.MaxValue
                : LokiPoe.Me.Position.DistanceF(_rescueTargetAnchor);
            if (IsLockedRescueTargetUsable(live) &&
                distance <= RescueInteractionThreshold(settings))
            {
                BeginRescueStage(
                    ZeroLanternExtractionStage.Stabilize,
                    "MandatoryFinalApproachTimeoutInsideInteractionRing");
                return false;
            }
            StopMandatoryFinalApproach("HardTimeout30Seconds", distance);
            return true;
        }

        private void StopMandatoryFinalApproach(
            string reason,
            float distance)
        {
            int elapsed = _mandatoryFinalApproachStartedUtc ==
                DateTime.MinValue
                    ? 0
                    : Math.Max(
                        0,
                        (int)Math.Floor(
                            (DateTime.UtcNow -
                             _mandatoryFinalApproachStartedUtc)
                                .TotalSeconds));
            string detail =
                "Reason=" + reason +
                "|ElapsedSeconds=" + elapsed +
                "|TargetId=" + _rescueTargetId +
                "|Target=" + _rescueTargetAnchor +
                "|Distance=" + (distance == Single.MaxValue
                    ? "Unavailable"
                    : distance.ToString("0.0")) +
                "|Reloads=" + _mandatoryFinalApproachReloads +
                "|ActiveTask=UseAllflameCapsuleTask";
            AllflameLog.Info(
                "CAPSULE_FINAL_APPROACH_TIMEOUT|" + detail);
            AllflameStopController.Stop(
                "MandatoryCapsuleReturnTimeout",
                detail);
        }

        private static Item FindInventoryItemByLocalId(
            int localId)
        {
            if (localId <= 0)
            {
                return null;
            }
            try
            {
                List<Item> items = LokiPoe.InGameState.InventoryUi
                    .InventoryControl_Main.Inventory.Items;
                if (items == null)
                {
                    return null;
                }
                foreach (Item item in items)
                {
                    if (item != null &&
                        item.IsValid &&
                        item.LocalId == localId)
                    {
                        return item;
                    }
                }
            }
            catch
            {
            }
            return null;
        }

        private void ClearPendingTransfer()
        {
            _pendingTransferLocalId = 0;
            _pendingTransferBeforeStack = 0;
            _pendingTransferIssuedUtc = DateTime.MinValue;
        }

        private async Task<bool> RunCachedCapsuleReturn(
            AllflameSettings settings)
        {
            if (_capsuleReturnUiConfirmed)
            {
                return true;
            }
            if (LokiPoe.Me == null)
            {
                return false;
            }
            if (_capsuleReturnAreaHash != AllflameContext.AreaHash ||
                _capsuleReturnStartedUtc == DateTime.MinValue)
            {
                ResetCapsuleReturnChain("Initialize");
                _capsuleReturnAreaHash = AllflameContext.AreaHash;
                _capsuleReturnStartedUtc = DateTime.UtcNow;
                _capsuleReturnChain.AddRange(
                    VoyageRunState.BuildCapsuleReturnChain(
                        LokiPoe.Me.Position));
                AllflameLog.Info(
                    "CAPSULE_RETURN_CHAIN_START" +
                    "|AreaHash=" + _capsuleReturnAreaHash +
                    "|Player=" + LokiPoe.Me.Position +
                    "|ConfirmedCached=" +
                    VoyageRunState.TraversedCapsuleCount +
                    "|Targets=" + _capsuleReturnChain.Count +
                    "|Spawn=" +
                    (VoyageRunState.HasSpawn
                        ? VoyageRunState.Spawn.ToString()
                        : "Unavailable") +
                    "|CoverageChecks=False");
                if (_capsuleReturnChain.Count == 0)
                {
                    StopCapsuleReturn("NoConfirmedCachedCapsules");
                    return false;
                }
                BeginCapsuleReturnTarget();
            }

            if (DateTime.UtcNow - _capsuleReturnStartedUtc >=
                TimeSpan.FromSeconds(120))
            {
                StopCapsuleReturn("TotalTimeout120Seconds");
                return false;
            }
            if (_capsuleReturnIndex >= _capsuleReturnChain.Count)
            {
                StopCapsuleReturn("AllCachedCapsulesTried");
                return false;
            }

            Vector2i target = _capsuleReturnChain[_capsuleReturnIndex];
            if (_capsuleReturnInteractionIssued)
            {
                AllflameContext.Refresh(true);
                bool uiVisible = AllflameContext.CapsuleUiVisible;
                VisualCallProbe probe = uiVisible
                    ? null
                    : await ProbeVisualCallButton();
                uiVisible = uiVisible ||
                    (probe != null && probe.Confirmed);
                if (uiVisible)
                {
                    _capsuleReturnUiConfirmed = true;
                    _visualCapsuleUiOpen = true;
                    _confirmedCapsuleAnchor = target;
                    _hasConfirmedCapsuleAnchor = true;
                    LockExitAnchor(
                        target,
                        true,
                        "CachedReturnUiConfirmed",
                        true,
                        true);
                    VoyageRunState.MarkCapsuleProven(target);
                    AllflameLog.Info(
                        "CAPSULE_RETURN_SUCCESS" +
                        "|Index=" + (_capsuleReturnIndex + 1) +
                        "/" + _capsuleReturnChain.Count +
                        "|Position=" + target +
                        "|UiSource=" +
                        (AllflameContext.CapsuleUiVisible
                            ? "DpbUi"
                            : "VisualFallback") +
                        "|InteractionAttempts=1");
                    return true;
                }

                string chatMessage;
                if (TryReadCapsuleNotLitMessage(
                    _capsuleReturnChatCursor,
                    out chatMessage))
                {
                    AllflameLog.Info(
                        "CAPSULE_RETURN_CHAT" +
                        "|Index=" + (_capsuleReturnIndex + 1) +
                        "|Position=" + target +
                        "|Result=NotLit" +
                        "|Message=" + SanitizeLogValue(chatMessage));
                    AdvanceCapsuleReturnTarget("ChatNotLit");
                    return false;
                }
                if (DateTime.UtcNow - _capsuleReturnInteractedUtc <
                    TimeSpan.FromMilliseconds(2500))
                {
                    return false;
                }

                AllflameLog.Info(
                    "CAPSULE_RETURN_RESULT" +
                    "|Index=" + (_capsuleReturnIndex + 1) +
                    "|Position=" + target +
                    "|Result=NoUiOrChatOutcome" +
                    "|InteractionAttempts=1");
                AdvanceCapsuleReturnTarget("NoOutcome");
                return false;
            }

            Vector2i player = LokiPoe.Me.Position;
            float distance = player.DistanceF(target);
            if (_capsuleReturnBestDistance - distance >= 3f)
            {
                float improvement = _capsuleReturnBestDistance - distance;
                _capsuleReturnBestDistance = distance;
                _capsuleReturnProgressUtc = DateTime.UtcNow;
                AllflameProgressWatchdog.MarkProgress(
                    "CachedCapsuleReturnConvergence");
                AllflameLog.Info(
                    "CAPSULE_RETURN_PROGRESS" +
                    "|Index=" + (_capsuleReturnIndex + 1) +
                    "|Position=" + target +
                    "|Distance=" + distance.ToString("0.0") +
                    "|BestDistance=" +
                    _capsuleReturnBestDistance.ToString("0.0") +
                    "|Improvement=" + improvement.ToString("0.0"));
            }

            float interactionRange = Math.Max(
                35f,
                settings.InteractDistance + 12f);
            if (distance > interactionRange)
            {
                if (DateTime.UtcNow - _capsuleReturnProgressUtc >=
                    TimeSpan.FromSeconds(5))
                {
                    if (_capsuleReturnReloads < 2)
                    {
                        _capsuleReturnReloads++;
                        _capsuleReturnProgressUtc = DateTime.UtcNow;
                        ResetMoverApproachState();
                        try { ExilePather.Reload(true); } catch { }
                        AllflameLog.Info(
                            "CAPSULE_RETURN_RECOVERY" +
                            "|Index=" + (_capsuleReturnIndex + 1) +
                            "|Position=" + target +
                            "|Attempt=" + _capsuleReturnReloads + "/2" +
                            "|Reason=NoProgress5Seconds" +
                            "|Action=ReloadPather");
                        return false;
                    }
                    AdvanceCapsuleReturnTarget("ApproachNoProgress");
                    return false;
                }

                bool moving = MoveTowardsInteraction(target, Name);
                AllflameLog.Throttled(
                    "capsule_return_move_" + _capsuleReturnIndex,
                    TimeSpan.FromSeconds(1),
                    "CAPSULE_RETURN_PROGRESS" +
                    "|Index=" + (_capsuleReturnIndex + 1) +
                    "|Position=" + target +
                    "|Distance=" + distance.ToString("0.0") +
                    "|BestDistance=" +
                    _capsuleReturnBestDistance.ToString("0.0") +
                    "|Moving=" + moving +
                    "|CoverageChecks=False");
                return false;
            }

            NetworkObject live = FindLiveCapsuleAt(target);
            if (live == null || !live.IsValid || !live.IsTargetable)
            {
                if (_capsuleReturnReacquireUtc == DateTime.MinValue)
                {
                    _capsuleReturnReacquireUtc = DateTime.UtcNow;
                    AllflameContext.Refresh(true);
                }
                if (DateTime.UtcNow - _capsuleReturnReacquireUtc <
                    TimeSpan.FromMilliseconds(3500))
                {
                    return false;
                }
                AdvanceCapsuleReturnTarget("LiveObjectNotReacquired");
                return false;
            }

            string targetKey = CapsuleReturnKey(target);
            if (_capsuleReturnInteracted.Contains(targetKey))
            {
                AdvanceCapsuleReturnTarget("InteractionAlreadyIssued");
                return false;
            }
            await FinishMovementBeforeInteraction("Allflame Capsule");
            AllflameContext.Refresh(true);
            live = FindLiveCapsuleAt(target);
            if (live == null || !live.IsValid || !live.IsTargetable ||
                LokiPoe.Me == null ||
                LokiPoe.Me.Position.DistanceF(live.Position) >
                    interactionRange)
            {
                _capsuleReturnReacquireUtc = DateTime.UtcNow;
                return false;
            }

            _capsuleReturnChatCursor = GetChatMessageCount();
            _capsuleReturnInteracted.Add(targetKey);
            _capsuleReturnInteractionIssued = true;
            _capsuleReturnInteractedUtc = DateTime.UtcNow;
            bool accepted = await InteractWithRecovery(live);
            AllflameLog.Info(
                "CAPSULE_RETURN_INTERACT" +
                "|Index=" + (_capsuleReturnIndex + 1) +
                "/" + _capsuleReturnChain.Count +
                "|ObjectId=" + live.Id +
                "|Position=" + target +
                "|Attempt=1" +
                "|InputAccepted=" + accepted +
                "|ChatCursor=" + _capsuleReturnChatCursor);
            return false;
        }

        private void BeginCapsuleReturnTarget()
        {
            if (_capsuleReturnIndex >= _capsuleReturnChain.Count)
            {
                return;
            }
            Vector2i target = _capsuleReturnChain[_capsuleReturnIndex];
            _capsuleReturnTargetStartedUtc = DateTime.UtcNow;
            _capsuleReturnProgressUtc = DateTime.UtcNow;
            _capsuleReturnInteractedUtc = DateTime.MinValue;
            _capsuleReturnReacquireUtc = DateTime.MinValue;
            _capsuleReturnBestDistance = LokiPoe.Me == null
                ? Single.MaxValue
                : LokiPoe.Me.Position.DistanceF(target);
            _capsuleReturnReloads = 0;
            _capsuleReturnInteractionIssued = false;
            bool finalSpawnCapsule =
                _capsuleReturnIndex == _capsuleReturnChain.Count - 1;
            AllflameLog.Info(
                "CAPSULE_RETURN_TARGET" +
                "|Index=" + (_capsuleReturnIndex + 1) +
                "/" + _capsuleReturnChain.Count +
                "|Position=" + target +
                "|PlayerDistance=" +
                (_capsuleReturnBestDistance == Single.MaxValue
                    ? "Unavailable"
                    : _capsuleReturnBestDistance.ToString("0.0")) +
                "|FinalSpawnCapsule=" + finalSpawnCapsule +
                "|InteractionLimit=1");
        }

        private void AdvanceCapsuleReturnTarget(string reason)
        {
            Vector2i previous = _capsuleReturnIndex <
                _capsuleReturnChain.Count
                    ? _capsuleReturnChain[_capsuleReturnIndex]
                    : new Vector2i();
            AllflameLog.Info(
                "CAPSULE_RETURN_RESULT" +
                "|Index=" + (_capsuleReturnIndex + 1) +
                "|Position=" + previous +
                "|Result=Advance" +
                "|Reason=" + (reason ?? String.Empty));
            _capsuleReturnIndex++;
            ResetMoverApproachState();
            if (_capsuleReturnIndex >= _capsuleReturnChain.Count)
            {
                StopCapsuleReturn("AllCachedCapsulesTried:" + reason);
                return;
            }
            BeginCapsuleReturnTarget();
        }

        private void StopCapsuleReturn(string reason)
        {
            string detail =
                "ActiveTask=" + Name +
                "|Reason=" + (reason ?? String.Empty) +
                "|Targets=" + _capsuleReturnChain.Count +
                "|Tried=" + Math.Min(
                    _capsuleReturnIndex + 1,
                    _capsuleReturnChain.Count) +
                "|Interactions=" + _capsuleReturnInteracted.Count +
                "|ElapsedSeconds=" +
                (_capsuleReturnStartedUtc == DateTime.MinValue
                    ? 0
                    : (int)(DateTime.UtcNow -
                        _capsuleReturnStartedUtc).TotalSeconds);
            AllflameLog.Info(
                "CAPSULE_RETURN_EXHAUSTED|" + detail);
            AllflameStopController.Stop(
                "VoyageCapsuleReturnExhausted",
                detail);
        }

        private static NetworkObject FindLiveCapsuleAt(Vector2i target)
        {
            try
            {
                return LokiPoe.ObjectManager.Objects
                    .Where(obj =>
                    {
                        if (obj == null || !obj.IsValid ||
                            obj.Position.DistanceF(target) > 30f)
                        {
                            return false;
                        }
                        string name = obj.Name ?? String.Empty;
                        string metadata = obj.Metadata ?? String.Empty;
                        return name.IndexOf(
                                   "Allflame Capsule",
                                   StringComparison.OrdinalIgnoreCase) >= 0 ||
                               name.IndexOf(
                                   "Deepwater Capsule",
                                   StringComparison.OrdinalIgnoreCase) >= 0 ||
                               metadata.IndexOf(
                                   "AllflameCapsule",
                                   StringComparison.OrdinalIgnoreCase) >= 0 ||
                               metadata.IndexOf(
                                   "DeepwaterCapsule",
                                   StringComparison.OrdinalIgnoreCase) >= 0;
                    })
                    .OrderBy(obj => obj.Position.DistanceF(target))
                    .FirstOrDefault();
            }
            catch
            {
                return null;
            }
        }

        private static int GetChatMessageCount()
        {
            try
            {
                var messages = LokiPoe.InGameState.ChatPanel.Messages;
                return messages == null ? 0 : messages.Count;
            }
            catch
            {
                return 0;
            }
        }

        private static bool TryReadCapsuleNotLitMessage(
            int cursor,
            out string message)
        {
            message = String.Empty;
            try
            {
                var messages = LokiPoe.InGameState.ChatPanel.Messages;
                if (messages == null || messages.Count <= cursor)
                {
                    return false;
                }
                for (int i = Math.Max(0, cursor); i < messages.Count; i++)
                {
                    string text = messages[i].Message ?? String.Empty;
                    string normalized = Regex.Replace(
                        text.ToLowerInvariant(),
                        "[^a-z]+",
                        " ");
                    if (normalized.IndexOf("capsul", StringComparison.Ordinal) >= 0 &&
                        normalized.IndexOf("not lit", StringComparison.Ordinal) >= 0)
                    {
                        message = text;
                        return true;
                    }
                }
            }
            catch
            {
            }
            return false;
        }

        private static string SanitizeLogValue(string value)
        {
            return (value ?? String.Empty)
                .Replace("|", "/")
                .Replace("\r", " ")
                .Replace("\n", " ");
        }

        private static string CapsuleReturnKey(Vector2i position)
        {
            return position.X + ":" + position.Y;
        }

        private void ResetCapsuleReturnChain(string reason)
        {
            _capsuleReturnChain.Clear();
            _capsuleReturnInteracted.Clear();
            _capsuleReturnAreaHash = 0;
            _capsuleReturnIndex = 0;
            _capsuleReturnStartedUtc = DateTime.MinValue;
            _capsuleReturnTargetStartedUtc = DateTime.MinValue;
            _capsuleReturnProgressUtc = DateTime.MinValue;
            _capsuleReturnInteractedUtc = DateTime.MinValue;
            _capsuleReturnReacquireUtc = DateTime.MinValue;
            _capsuleReturnBestDistance = Single.MaxValue;
            _capsuleReturnReloads = 0;
            _capsuleReturnChatCursor = 0;
            _capsuleReturnInteractionIssued = false;
            _capsuleReturnUiConfirmed = false;
        }

