        private async Task<VisualCallProbe> ProbeVisualCallButton()
        {
            int attempt = ++_callVisualDetectionAttempts;
            double requiredCorrelation =
                attempt <= 5
                    ? 0.60
                    : (attempt <= 10 ? 0.50 : 0.40);
            var result = new VisualCallProbe
            {
                RequiredCorrelation = requiredCorrelation,
                Attempt = attempt
            };

            Vector2i firstLocation;
            double firstCorrelation;
            bool firstFound = CapsuleVisualUi.TryFindCallButton(
                out firstLocation,
                out firstCorrelation,
                requiredCorrelation);
            result.Location = firstLocation;
            result.Correlation = firstCorrelation;
            if (!firstFound)
            {
                AllflameLog.Info(
                    "CAPSULE_CALL_VISUAL_CONFIRM" +
                    "|Confirmed=False" +
                    "|Reason=FirstFrameBelowThreshold" +
                    "|Attempt=" + attempt +
                    "|Correlation=" +
                    firstCorrelation.ToString("0.000") +
                    "|Required=" +
                    requiredCorrelation.ToString("0.000"));
                return result;
            }

            await LokiCoroutine.Sleep(120);
            Vector2i secondLocation;
            double secondCorrelation;
            bool secondFound = CapsuleVisualUi.TryFindCallButton(
                out secondLocation,
                out secondCorrelation,
                requiredCorrelation);
            int drift = secondFound
                ? Math.Abs(secondLocation.X - firstLocation.X) +
                  Math.Abs(secondLocation.Y - firstLocation.Y)
                : Int32.MaxValue;
            result.Confirmed = secondFound && drift <= 10;
            result.Location = secondLocation;
            result.Correlation = Math.Min(
                firstCorrelation,
                secondCorrelation);
            AllflameLog.Info(
                "CAPSULE_CALL_VISUAL_CONFIRM" +
                "|Confirmed=" + result.Confirmed +
                "|Attempt=" + attempt +
                "|FirstClient=" + firstLocation +
                "|SecondClient=" +
                (secondFound
                    ? secondLocation.ToString()
                    : "n/a") +
                "|FirstCorrelation=" +
                firstCorrelation.ToString("0.000") +
                "|SecondCorrelation=" +
                secondCorrelation.ToString("0.000") +
                "|Required=" +
                requiredCorrelation.ToString("0.000") +
                "|Drift=" +
                (secondFound ? drift.ToString() : "n/a"));
            return result;
        }

        private void ResetRoute()
        {
            _hasRouteTarget = false;
            _routeTarget = new Vector2i();
            _bestRouteDistance = Single.MaxValue;
            _routeProgressUtc = DateTime.MinValue;
            _anchorMissingUtc = DateTime.MinValue;
        }
    }

    internal sealed class WaitForBathysphereTask : ObserverTask
    {
        private DateTime _nextMoveUtc = DateTime.MinValue;
        private int _orbitStep;

        public WaitForBathysphereTask()
            : base("WaitForBathysphereTask", "Would keep moving inside the lit area while waiting.") { }

        public override Task<bool> Run()
        {
            if (!AllflameContext.IsVoyageMapArea ||
                AllflameContext.Phase != AllflamePhase.WaitingForBathysphere ||
                AllflameContext.ExtractionAvailable)
            {
                return Task.FromResult(false);
            }

            int timeoutSeconds = Math.Max(
                15,
                AllflameSettings.Instance
                    .BathysphereWaitTimeoutSeconds);
            if (VoyageRunState.CallIssued &&
                VoyageRunState.CallIssuedUtc != DateTime.MinValue &&
                AllflameContext.CallBathysphereVisible &&
                DateTime.UtcNow - VoyageRunState.CallIssuedUtc >=
                    TimeSpan.FromSeconds(2))
            {
                VoyageRunState.AllowCallRetry();
                AllflameLog.Info(
                    "BATHYSPHERE_CALL_RETRY" +
                    "|Reason=CallButtonStillVisible" +
                    "|DelaySeconds=2");
                return Task.FromResult(false);
            }
            if (VoyageRunState.CallIssued &&
                VoyageRunState.CallIssuedUtc != DateTime.MinValue &&
                DateTime.UtcNow - VoyageRunState.CallIssuedUtc >=
                    TimeSpan.FromSeconds(timeoutSeconds))
            {
                VoyageRunState.AllowCallRetry();
                AllflameLog.Info(
                    "BATHYSPHERE_CALL_RETRY|Reason=WaitTimeout" +
                    "|TimeoutSeconds=" + timeoutSeconds);
                return Task.FromResult(false);
            }

            if (!VoyageRunState.CallIssued)
            {
                return Task.FromResult(false);
            }

            if (!AllflameSettings.Instance.KeepMovingWhileWaiting ||
                LokiPoe.Me == null ||
                DateTime.UtcNow < _nextMoveUtc)
            {
                return Task.FromResult(true);
            }

            _nextMoveUtc = DateTime.UtcNow.AddMilliseconds(850);
            Vector2i center = VoyageRunState.HasCapsuleAnchor
                ? VoyageRunState.CapsuleAnchor
                : LokiPoe.Me.Position;
            int radius = Math.Max(
                8,
                AllflameSettings.Instance.WaitMoveRadius);
            double angle = (_orbitStep++ % 12) * Math.PI / 6.0;
            Vector2i target = new Vector2i(
                center.X + (int)Math.Round(Math.Cos(angle) * radius),
                center.Y + (int)Math.Round(Math.Sin(angle) * radius));
            bool moving = AllflameMovementCoordinator.MoveTowards(
                target,
                Name);
            AllflameLog.Throttled(
                "bathysphere_active_wait",
                TimeSpan.FromSeconds(2),
                "VOYAGE_STAGE|Stage=8|State=Waiting" +
                "|OrbitTarget=" + target +
                "|Moving=" + moving);
            return Task.FromResult(true);
        }
    }

    internal sealed class ExtractTask : ObserverTask
    {
        private DateTime _nextInteractUtc = DateTime.MinValue;
        private DateTime _firstFailureUtc = DateTime.MinValue;
        private int _failedObjectId;
        private int _failedAttempts;
        private uint _failedAreaHash;

        public ExtractTask()
            : base("ExtractTask", "Would use the encounter Bathysphere extraction object.") { }

        public override void Start()
        {
            ResetInteractionState();
        }

        public override void Stop()
        {
            ResetInteractionState();
            AllflameProgressWatchdog.Clear();
        }

        public override async Task<bool> Run()
        {
            if (!AllflameContext.IsVoyageMapArea ||
                (AllflameContext.Phase !=
                    AllflamePhase.WaitingForBathysphere &&
                 AllflameContext.Phase != AllflamePhase.Voyage) ||
                !VoyageRunState.CallIssued ||
                !AllflameContext.ExtractionAvailable ||
                (AllflameContext.ExtractionObject == null &&
                 AllflameContext.BathysphereObject == null))
            {
                ResetInteractionState();
                AllflameProgressWatchdog.Clear();
                return false;
            }

            NetworkObject extraction =
                AllflameContext.ExtractionObject;
            if (!AllflameContext.IsActualExtractionObject(
                    extraction))
            {
                extraction = AllflameContext.BathysphereObject;
            }
            if (extraction == null ||
                !extraction.IsValid ||
                !AllflameContext.IsActualExtractionObject(
                    extraction))
            {
                int timeoutSeconds = Math.Max(
                    15,
                    AllflameSettings.Instance
                        .BathysphereWaitTimeoutSeconds);
                bool timedOut =
                    VoyageRunState.CallIssuedUtc !=
                        DateTime.MinValue &&
                    DateTime.UtcNow -
                        VoyageRunState.CallIssuedUtc >=
                    TimeSpan.FromSeconds(timeoutSeconds);
                AllflameLog.Throttled(
                    "voyage_extraction_false_target",
                    TimeSpan.FromSeconds(2),
                    "VOYAGE_EXTRACTION_TARGET_REJECTED" +
                    "|Reason=CapsuleOrSummonObject" +
                    "|ExtractionId=" +
                    (AllflameContext.ExtractionObject == null
                        ? 0
                        : AllflameContext.ExtractionObject.Id) +
                    "|BathysphereId=" +
                    (AllflameContext.BathysphereObject == null
                        ? 0
                        : AllflameContext.BathysphereObject.Id) +
                    "|TimedOut=" + timedOut);
                if (timedOut)
                {
                    VoyageRunState.AllowCallRetry();
                    AllflameLog.Info(
                        "BATHYSPHERE_CALL_RETRY" +
                        "|Reason=FalseExtractionTarget" +
                        "|TimeoutSeconds=" + timeoutSeconds);
                }
                return false;
            }

            AllflameProgressWatchdog.Begin(
                Name,
                extraction.Id,
                "Bathysphere");
            if (_failedObjectId != extraction.Id ||
                _failedAreaHash != AllflameContext.AreaHash)
            {
                _failedObjectId = extraction.Id;
                _failedAreaHash = AllflameContext.AreaHash;
                _failedAttempts = 0;
                _firstFailureUtc = DateTime.MinValue;
            }

            // Calling the Bathysphere commits the current Voyage exit.
            // Stale inventory/surface flags must never hand movement back to
            // chest, loot, lantern, or exploration tasks after it appears.
            VoyageRunState.SurfaceTransferPending = false;
            AllflameLootState.Clear();
            BottleSafetyMovement.Reset();

            if (extraction.Distance >=
                Math.Max(
                    70,
                    AllflameSettings.Instance.InteractDistance + 10))
            {
                if (AllflameProgressWatchdog.TryConsumeRecovery(
                        "ReloadPathAndReacquireBathysphere"))
                {
                    try
                    {
                        ExilePather.Reload(true);
                    }
                    catch
                    {
                    }
                    AllflameContext.Refresh(true);
                    AllflameProgressWatchdog.MarkProgress(
                        "ReacquireBathysphere");
                    return true;
                }
                bool moving = AllflameMovementCoordinator.MoveTowards(
                    extraction.Position,
                    Name);
                AllflameLog.Throttled(
                    "voyage_return_bathysphere_move",
                    TimeSpan.FromSeconds(1),
                    "VOYAGE_STAGE|Stage=9" +
                    "|Action=MoveToBathysphere" +
                    "|ObjectId=" + extraction.Id +
                    "|Name=" +
                    (String.IsNullOrEmpty(extraction.Name)
                        ? "Unknown"
                        : extraction.Name) +
                    "|Target=" + extraction.Position +
                    "|Distance=" +
                    extraction.Distance.ToString("0.0") +
                    "|Moving=" + moving);
                return true;
            }

            if (!extraction.IsTargetable)
            {
                int timeoutSeconds = Math.Max(
                    15,
                    AllflameSettings.Instance
                        .BathysphereWaitTimeoutSeconds);
                bool timedOut =
                    VoyageRunState.CallIssuedUtc !=
                        DateTime.MinValue &&
                    DateTime.UtcNow -
                        VoyageRunState.CallIssuedUtc >=
                    TimeSpan.FromSeconds(timeoutSeconds);
                if (timedOut)
                {
                    VoyageRunState.AllowCallRetry();
                    AllflameLog.Info(
                        "BATHYSPHERE_CALL_RETRY" +
                        "|Reason=ExtractionNotTargetable" +
                        "|ObjectId=" + extraction.Id +
                        "|Name=" +
                        (String.IsNullOrEmpty(extraction.Name)
                            ? "Unknown"
                            : extraction.Name) +
                        "|TimeoutSeconds=" + timeoutSeconds);
                    return false;
                }
                AllflameLog.Throttled(
                    "voyage_return_bathysphere_wait_targetable",
                    TimeSpan.FromSeconds(1),
                    "VOYAGE_STAGE|Stage=9" +
                    "|Action=WaitForBathysphereTargetable" +
                    "|ObjectId=" + extraction.Id +
                    "|Distance=" +
                    extraction.Distance.ToString("0.0"));
                if (AllflameProgressWatchdog.TryConsumeRecovery(
                        "ReacquireBathysphere"))
                {
                    AllflameContext.Refresh(true);
                    AllflameProgressWatchdog.MarkProgress(
                        "ReacquireBathysphere");
                    return true;
                }
                return true;
            }

            if (DateTime.UtcNow < _nextInteractUtc)
            {
                return true;
            }
            _nextInteractUtc =
                DateTime.UtcNow.AddMilliseconds(450);
            await FinishMovementBeforeInteraction(
                "Voyage Extraction Bathysphere");
            bool used = false;
            try
            {
                used = await InteractWithRecovery(extraction);
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "BATHYSPHERE_EXTRACT_INTERACT_EXCEPTION" +
                    "|Type=" + ex.GetType().Name +
                    "|Message=" +
                    (ex.Message ?? String.Empty).Replace("|", "/"));
            }
            AllflameLog.Info(
                "VOYAGE_STAGE|Stage=9|Action=Extract" +
                "|Success=" + used +
                "|ObjectId=" + extraction.Id +
                "|Name=" +
                (String.IsNullOrEmpty(extraction.Name)
                    ? "Unknown"
                    : extraction.Name) +
                "|Distance=" +
                extraction.Distance.ToString("0.0"));
            if (used)
            {
                AllflameProgressWatchdog.MarkProgress(
                    "ExtractAccepted");
                ResetInteractionState();
                AllflameProgressWatchdog.Clear();
            }
            else
            {
                if (_firstFailureUtc == DateTime.MinValue)
                {
                    _firstFailureUtc = DateTime.UtcNow;
                }
                if (_failedObjectId != extraction.Id ||
                    _failedAreaHash != AllflameContext.AreaHash)
                {
                    _failedObjectId = extraction.Id;
                    _failedAreaHash = AllflameContext.AreaHash;
                    _failedAttempts = 0;
                }
                _failedAttempts++;
                AllflameProgressWatchdog.SetRetry(_failedAttempts);
                int elapsedSeconds = Math.Max(
                    0,
                    (int)(DateTime.UtcNow - _firstFailureUtc)
                        .TotalSeconds);
                AllflameLog.Info(
                    "BATHYSPHERE_EXTRACT_RETRY" +
                    "|ObjectId=" + extraction.Id +
                    "|Attempt=" + _failedAttempts +
                    "|ElapsedSeconds=" + elapsedSeconds +
                    "|InteractionAccepted=False" +
                    "|NextAction=" +
                    (_failedAttempts >= 3
                        ? "BATHYSPHERE_EXTRACT_GIVE_UP"
                        : "ReacquireAndChangeApproach"));
                AllflameContext.Refresh(true);
                if (_failedAttempts == 2)
                {
                    try
                    {
                        ExilePather.Reload(true);
                    }
                    catch
                    {
                    }
                }
                if (_failedAttempts >= 3 || elapsedSeconds >= 18)
                {
                    AllflameLog.Info(
                        "BATHYSPHERE_EXTRACT_GIVE_UP" +
                        "|ObjectId=" + extraction.Id +
                        "|Attempts=" + _failedAttempts +
                        "|ElapsedSeconds=" + elapsedSeconds +
                        "|NextAction=ControlledStop");
                    AllflameStopController.Stop(
                        "BathysphereExtractGiveUp",
                        "ObjectId=" + extraction.Id +
                        "|AreaHash=" + AllflameContext.AreaHash +
                        "|Attempts=" + _failedAttempts +
                        "|ElapsedSeconds=" + elapsedSeconds);
                    return true;
                }
            }
            await LokiCoroutine.Sleep(350);
            return true;
        }

        private void ResetInteractionState()
        {
            _nextInteractUtc = DateTime.MinValue;
            _firstFailureUtc = DateTime.MinValue;
            _failedObjectId = 0;
            _failedAttempts = 0;
            _failedAreaHash = 0;
        }
    }

    internal sealed class CollectLootTask : ObserverTask
    {
        private const int DeepwaterCollectionInventoryId = 114;
        private const int MaximumCollectUiElements = 5000;
        private bool _opened;
        private bool _movedAnyItem;
        private DateTime _openedUtc = DateTime.MinValue;
        private DateTime _nextActionUtc = DateTime.MinValue;
        private int _emptyConfirmations;
        private int _uiResolveRetries;
        private int _failedTransferItemId;
        private int _failedTransferCount;
        private InventoryControlWrapper _cachedCollectionControl;
        private bool _rawTabsInitialized;
        private int _rawActiveTab;
        private bool _rawTabOneEmpty;
        private bool _rawTabTwoEmpty;
        private int _rawEmptyConfirmations;
        private RawCollectLootGrid _cachedRawCollectGrid;

        public CollectLootTask()
            : base("CollectLootTask", "Would collect voyage loot in The Sovereign.") { }

        public override void Start()
        {
            ResetLocalState();
        }

        public override void Stop()
        {
            ResetLocalState();
        }

        public override async Task<bool> Run()
        {
            bool inHub =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            bool debugCollect =
                AllflameVoyageDebug.CollectSurfaceLootRequested;
            if (inHub &&
                (debugCollect ||
                 (AllflameSettings.Instance.CollectSurfaceLoot &&
                  VoyageRunState.SurfaceLootPending)))
            {
                if (DateTime.UtcNow < _nextActionUtc)
                {
                    return true;
                }

                if (_opened)
                {
                    InventoryControlWrapper containerControl = null;
                    Inventory sourceInventory = null;
                    List<Item> items = null;
                    string source = "None";
                    List<InventoryControlWrapper> rewardControls = null;
                    bool rewardUiOpen = false;
                    bool nativeLootUiActive = false;
                    bool inventorySourceConfirmed = false;
                    try
                    {
                        bool nativeLootOpened;
                        InventoryControlWrapper nativeLootControl;
                        string nativeLootReason;
                        if (AllflameSettings.Instance.UseNativeLootUi &&
                            DpbNativeApi.TryCaptureLoot(
                                out nativeLootOpened,
                                out nativeLootControl,
                                out nativeLootReason) &&
                            nativeLootOpened &&
                            nativeLootControl != null)
                        {
                            nativeLootUiActive = true;
                            rewardUiOpen = true;
                            rewardControls =
                                new List<InventoryControlWrapper>
                                {
                                    nativeLootControl
                                };
                            AllflameLog.Throttled(
                                "collect_surface_native_loot_ui",
                                TimeSpan.FromSeconds(2),
                                "COLLECT_SURFACE_NATIVE_SNAPSHOT" +
                                "|Opened=True" +
                                "|Control=True" +
                                "|Reason=" + nativeLootReason);
                        }
                        else
                        {
                            rewardUiOpen =
                                LokiPoe.InGameState.RewardUi.IsOpened;
                            if (rewardUiOpen)
                            {
                                rewardControls =
                                    LokiPoe.InGameState.RewardUi
                                        .InventoryControls;
                            }
                        }
                    }
                    catch
                    {
                        rewardControls = null;
                    }

                    if (rewardControls != null)
                    {
                        containerControl =
                            rewardControls.FirstOrDefault(control =>
                                control != null &&
                                control.IsValid &&
                                control.Inventory != null &&
                                control.Inventory.IsValid &&
                                control.Inventory.Items != null &&
                                control.Inventory.Items.Any(rewardItem =>
                                    rewardItem != null &&
                                    rewardItem.IsValid));
                        if (containerControl != null)
                        {
                            sourceInventory =
                                containerControl.Inventory;
                            items = sourceInventory.Items;
                            source = nativeLootUiActive
                                ? "NativeLootUi"
                                : "RewardUi";
                            inventorySourceConfirmed = true;
                        }
                        else if (rewardControls.Any(control =>
                                     control != null &&
                                     control.IsValid &&
                                     control.Inventory != null &&
                                     control.Inventory.IsValid))
                        {
                            source = nativeLootUiActive
                                ? ("NativeLootUi" +
                                   (_movedAnyItem
                                       ? "VerifiedEmpty"
                                       : "UnconfirmedEmpty"))
                                : (_movedAnyItem
                                    ? "RewardUiVerifiedEmpty"
                                    : "RewardUiUnconfirmedEmpty");
                            items = new List<Item>();
                            inventorySourceConfirmed =
                                _movedAnyItem;
                        }

                        AllflameLog.Throttled(
                            "collect_surface_reward_ui",
                            TimeSpan.FromSeconds(2),
                            "COLLECT_SURFACE_UI" +
                            "|Found=" + inventorySourceConfirmed +
                            "|Source=" +
                            (nativeLootUiActive
                                ? "NativeLootUi"
                                : "RewardUi") +
                            "|Controls=" + rewardControls.Count +
                            "|ControlsWithItems=" +
                            rewardControls.Count(control =>
                                control != null &&
                                control.IsValid &&
                                control.Inventory != null &&
                                control.Inventory.IsValid &&
                                control.Inventory.Items != null &&
                                control.Inventory.Items.Any(rewardItem =>
                                    rewardItem != null &&
                                    rewardItem.IsValid)) +
                            "|Items=" +
                            rewardControls.Sum(control =>
                                control == null ||
                                !control.IsValid ||
                                control.Inventory == null ||
                                !control.Inventory.IsValid ||
                                control.Inventory.Items == null
                                    ? 0
                                    : control.Inventory.Items.Count(rewardItem =>
                                        rewardItem != null &&
                                        rewardItem.IsValid)));
                    }

                    if (!inventorySourceConfirmed)
                    {
                        Inventory collectionInventory =
                            GetDeepwaterCollectionInventory();
                        int visited = 0;
                        int candidates = 0;
                        if (collectionInventory != null &&
                            collectionInventory.IsValid &&
                            collectionInventory.Id ==
                                DeepwaterCollectionInventoryId &&
                            collectionInventory.IsRequested &&
                            IsCollectInventoryShape(
                                collectionInventory))
                        {
                            sourceInventory = collectionInventory;
                            items =
                                collectionInventory.Items ??
                                new List<Item>();
                            source = "DeepwaterCollection114";
                            inventorySourceConfirmed = true;

                            bool hasCollectionItems =
                                items.Any(candidate =>
                                    candidate != null &&
                                    candidate.IsValid);
                            bool collectionControlResolved =
                                !hasCollectionItems ||
                                TryUseCachedCollectionControl(
                                    collectionInventory,
                                    out containerControl);
                            if (hasCollectionItems &&
                                !collectionControlResolved)
                            {
                                collectionControlResolved =
                                    TryResolveCollectContainer(
                                        collectionInventory,
                                        out containerControl,
                                        out visited,
                                        out candidates);
                                if (collectionControlResolved)
                                {
                                    _cachedCollectionControl =
                                        containerControl;
                                }
                            }
                            if (hasCollectionItems &&
                                !collectionControlResolved)
                            {
                                AllflameLog.Throttled(
                                    "collect_surface_114_control_wait",
                                    TimeSpan.FromSeconds(2),
                                    "COLLECT_SURFACE_WAIT" +
                                    "|Reason=CollectionGridNotResolved" +
                                    "|InventoryId=" +
                                    collectionInventory.Id +
                                    "|Items=" + items.Count +
                                    "|Candidates=" + candidates +
                                    "|Visited=" + visited);
                                if (await RetryCollectUiIfTimedOut(
                                        "CollectionGridNotResolved"))
                                {
                                    return true;
                                }
                                _nextActionUtc =
                                    DateTime.UtcNow.AddMilliseconds(250);
                                return true;
                            }

                            AllflameLog.Throttled(
                                "collect_surface_inventory_114",
                                TimeSpan.FromSeconds(2),
                                "COLLECT_SURFACE_UI|Found=True" +
                                "|Source=DeepwaterCollection114" +
                                "|InventoryId=" +
                                collectionInventory.Id +
                                "|Rows=" + collectionInventory.Rows +
                                "|Columns=" +
                                collectionInventory.Columns +
                                "|Items=" + items.Count +
                                "|ControlResolved=" +
                                (containerControl != null));
                        }
                        else
                        {
                            RawCollectLootGrid rawGrid;
                            int rawVisited = 0;
                            int rawCandidates = 1;
                            if (TryUseCachedRawCollectGrid(
                                    out rawGrid) ||
                                TryResolveRawCollectLootGrid(
                                    out rawGrid,
                                    out rawVisited,
                                    out rawCandidates))
                            {
                                _cachedRawCollectGrid = rawGrid;
                                return await ProcessRawCollectLootGrid(
                                    rawGrid,
                                    rawVisited,
                                    rawCandidates);
                            }

                            if (TryResolveCollectContainer(
                                    null,
                                    out containerControl,
                                    out visited,
                                    out candidates))
                            {
                                sourceInventory =
                                    containerControl.Inventory;
                                items = sourceInventory.Items;
                                source = "ElementTree";
                                inventorySourceConfirmed =
                                    items != null &&
                                    items.Any(candidate =>
                                        candidate != null &&
                                        candidate.IsValid);
                                AllflameLog.Throttled(
                                    "collect_surface_element_control",
                                    TimeSpan.FromSeconds(2),
                                    "COLLECT_SURFACE_UI|Found=True" +
                                    "|Source=ElementTree" +
                                    "|Address=0x" +
                                    containerControl.Address.ToString("X") +
                                    "|Items=" +
                                    (items == null ? 0 : items.Count) +
                                    "|Candidates=" + candidates +
                                    "|Visited=" + visited);
                            }
                            else
                            {
                            AllflameLog.Throttled(
                                "collect_surface_wrapper_wait",
                                TimeSpan.FromSeconds(2),
                                "COLLECT_SURFACE_WAIT" +
                                "|Reason=ContainerInventoryNotResolved" +
                                "|RewardUiOpen=" + rewardUiOpen +
                                "|RewardControls=" +
                                (rewardControls == null
                                    ? -1
                                    : rewardControls.Count) +
                                "|CollectionInventory114=" +
                                (collectionInventory != null &&
                                 collectionInventory.IsValid) +
                                "|Candidates=" + candidates +
                                "|RawCandidates=" + rawCandidates +
                                "|Visited=" +
                                Math.Max(visited, rawVisited));
                            if (await RetryCollectUiIfTimedOut(
                                    "ContainerInventoryNotResolved"))
                            {
                                return true;
                            }
                            _nextActionUtc =
                                DateTime.UtcNow.AddMilliseconds(300);
                            return true;
                            }
                        }
                    }

                    Item item = items == null
                        ? null
                        : items.FirstOrDefault(candidate =>
                            candidate != null &&
                            candidate.IsValid);
                    if (item != null)
                    {
                        _emptyConfirmations = 0;
                        int itemKey =
                            item.LocalId != 0
                                ? item.LocalId
                                : item.Id;
                        int beforeStack =
                            Math.Max(1, item.StackCount);
                        string itemName =
                            item.FullName ?? item.Name ??
                            "Unknown";
                        bool inputAccepted = false;
                        bool transferred = false;
                        string transferMode;
                        FastMoveResult fastMoveResult =
                            FastMoveResult.Unsupported;
                        if (String.Equals(
                                source,
                                "RewardUi",
                                StringComparison.Ordinal))
                        {
                            try
                            {
                                fastMoveResult =
                                    containerControl.FastMoveReward(
                                        itemKey,
                                        true);
                            }
                            catch
                            {
                                fastMoveResult =
                                    FastMoveResult.Failed;
                            }
                            inputAccepted =
                                fastMoveResult ==
                                FastMoveResult.None;
                            transferMode = "FastMoveReward";
                        }
                        else
                        {
                            try
                            {
                                fastMoveResult =
                                    containerControl.FastMove(
                                        itemKey);
                            }
                            catch
                            {
                                fastMoveResult =
                                    FastMoveResult.Failed;
                            }
                            inputAccepted =
                                fastMoveResult ==
                                FastMoveResult.None;
                            transferMode = "FastMove";
                        }

                        if (inputAccepted)
                        {
                            transferred =
                                await WaitForSourceItemMoved(
                                    sourceInventory,
                                    itemKey,
                                    item,
                                    beforeStack,
                                    900);
                        }

                        bool ctrlFallbackSent = false;
                        if (!transferred &&
                            AllflameSettings.Instance
                                .CtrlClickCollectLoot)
                        {
                            Item fallbackItem =
                                FindSourceItem(
                                    sourceInventory,
                                    itemKey,
                                    item);
                            if (fallbackItem == null ||
                                !fallbackItem.IsValid)
                            {
                                transferred = true;
                                transferMode +=
                                    "VerifiedBeforeCtrlClick";
                            }
                            else
                            {
                                ctrlFallbackSent =
                                    await CtrlClickContainerItem(
                                        containerControl,
                                        fallbackItem);
                                transferMode += "ThenCtrlClick";
                                if (ctrlFallbackSent)
                                {
                                    transferred =
                                        await WaitForSourceItemMoved(
                                            sourceInventory,
                                            itemKey,
                                            fallbackItem,
                                            beforeStack,
                                            500);
                                }
                            }
                        }

                        if (transferred)
                        {
                            _movedAnyItem = true;
                            _failedTransferItemId = 0;
                            _failedTransferCount = 0;
                            _uiResolveRetries = 0;
                        }
                        _nextActionUtc =
                            DateTime.UtcNow.AddMilliseconds(
                                transferred ? 110 : 250);
                        AllflameLog.Info(
                            "COLLECT_SURFACE_ITEM|Id=" + itemKey +
                            "|Name=" + itemName +
                            "|Success=" + transferred +
                            "|Verified=" + transferred +
                            "|Source=" + source +
                            "|Mode=" + transferMode +
                            "|FastMoveResult=" + fastMoveResult +
                            "|CtrlFallbackSent=" +
                            ctrlFallbackSent +
                            "|BeforeStack=" + beforeStack);
                        if (!transferred)
                        {
                            if (_failedTransferItemId != itemKey)
                            {
                                _failedTransferItemId = itemKey;
                                _failedTransferCount = 0;
                            }
                            _failedTransferCount++;
                            if (_failedTransferCount >= 2)
                            {
                                int freeSquares =
                                    GetPlayerInventoryFreeSquares();
                                AllflameLog.Info(
                                    "COLLECT_SURFACE_REOPEN" +
                                    "|Reason=TwoUnverifiedTransfers" +
                                    "|ItemId=" + itemKey +
                                    "|Item=" + itemName +
                                    "|PlayerFreeSquares=" +
                                    freeSquares);
                                _opened = false;
                                _openedUtc = DateTime.MinValue;
                                _failedTransferCount = 0;
                                _cachedCollectionControl = null;
                                await Coroutines
                                    .CloseBlockingWindows();
                                _nextActionUtc =
                                    DateTime.UtcNow
                                        .AddMilliseconds(500);
                            }
                        }
                        return true;
                    }

                    bool allowEmptyConfirmation =
                        _movedAnyItem ||
                        (inventorySourceConfirmed &&
                         _openedUtc != DateTime.MinValue &&
                         DateTime.UtcNow - _openedUtc >=
                            TimeSpan.FromSeconds(3));
                    if (!allowEmptyConfirmation)
                    {
                        if (await RetryCollectUiIfTimedOut(
                                "InventoryNotReadyOrUnconfirmedEmpty"))
                        {
                            return true;
                        }
                        AllflameLog.Throttled(
                            "collect_surface_initial_load",
                            TimeSpan.FromSeconds(1),
                            "COLLECT_SURFACE_WAIT" +
                            "|Reason=RewardItemsLoading" +
                            "|Source=" + source +
                            "|OpenedMs=" +
                            Math.Max(
                                0,
                                (int)(DateTime.UtcNow -
                                    _openedUtc).TotalMilliseconds));
                        _nextActionUtc =
                            DateTime.UtcNow.AddMilliseconds(250);
                        return true;
                    }

                    _emptyConfirmations++;
                    if (_emptyConfirmations >= 2)
                    {
                        VoyageRunState.MarkSurfaceCollected();
                        AllflameVoyageDebug.CompleteCollectSurfaceLoot(
                            "ContainerEmpty");
                        ResetLocalState();
                        await Coroutines.CloseBlockingWindows();
                        AllflameLog.Info(
                            "VOYAGE_STAGE|Stage=10|State=Collected" +
                            "|Action=ContinueToStash");
                        return false;
                    }
                    _nextActionUtc =
                        DateTime.UtcNow.AddMilliseconds(250);
                    return true;
                }

                if (TryAdoptAlreadyOpenCollectUi())
                {
                    _opened = true;
                    _openedUtc = DateTime.UtcNow;
                    _emptyConfirmations = 0;
                    AllflameLog.Info(
                        "COLLECT_SURFACE_UI_ADOPTED" +
                        "|Reason=AlreadyOpenBeforeInteraction");
                    _nextActionUtc =
                        DateTime.UtcNow.AddMilliseconds(150);
                    return true;
                }

                if (!AllflameContext.CollectionChestAvailable ||
                    AllflameContext.CollectionChestObject == null)
                {
                    AllflameLog.Throttled(
                        "collect_surface_object_wait",
                        TimeSpan.FromSeconds(2),
                        "COLLECT_SURFACE_WAIT" +
                        "|Reason=CollectionChestNotAvailable");
                    return true;
                }

                NetworkObject chest =
                    AllflameContext.CollectionChestObject;
                if (chest.Distance >
                    Math.Max(
                        25,
                        AllflameSettings.Instance.InteractDistance + 6))
                {
                    AllflameMovementCoordinator.MoveTowards(
                        chest.Position,
                        Name);
                    return true;
                }

                bool opened = await InteractWithRecovery(chest);
                AllflameLog.Info(
                    "VOYAGE_STAGE|Stage=10|Action=OpenCollectLoot" +
                    "|Success=" + opened +
                    "|ObjectId=" + chest.Id);
                if (opened)
                {
                    _opened = true;
                    _movedAnyItem = false;
                    _openedUtc = DateTime.UtcNow;
                    _emptyConfirmations = 0;
                    _failedTransferItemId = 0;
                    _failedTransferCount = 0;
                }
                await LokiCoroutine.Sleep(300);
                return true;
            }
            ResetLocalState();
            return false;
        }

        private bool TryUseCachedCollectionControl(
            Inventory inventory,
            out InventoryControlWrapper control)
        {
            control = _cachedCollectionControl;
            if (control == null ||
                inventory == null ||
                !inventory.IsValid)
            {
                return false;
            }

            try
            {
                Element slot =
                    control.InventorySlotUiElement;
                if (slot == null ||
                    !slot.IsValid ||
                    !slot.IsVisible)
                {
                    _cachedCollectionControl = null;
                    control = null;
                    return false;
                }
                control.SetInventory(inventory);
                return true;
            }
            catch
            {
                _cachedCollectionControl = null;
                control = null;
                return false;
            }
        }

        private static bool TryAdoptAlreadyOpenCollectUi()
        {
            try
            {
                bool nativeOpened;
                InventoryControlWrapper nativeControl;
                string nativeReason;
                if (AllflameSettings.Instance.UseNativeLootUi &&
                    DpbNativeApi.TryCaptureLoot(
                        out nativeOpened,
                        out nativeControl,
                        out nativeReason) &&
                    nativeOpened &&
                    nativeControl != null)
                {
                    AllflameLog.Info(
                        "COLLECT_SURFACE_UI_ADOPT_PROBE" +
                        "|Source=NativeLootUi" +
                        "|Resolved=True" +
                        "|Reason=" + nativeReason);
                    return true;
                }
                if (LokiPoe.InGameState.RewardUi.IsOpened)
                {
                    return true;
                }
            }
            catch
            {
                // Continue with the seasonal inventory/grid probe.
            }

            Inventory inventory =
                GetDeepwaterCollectionInventory();
            if (inventory == null ||
                !inventory.IsValid ||
                inventory.Id !=
                    DeepwaterCollectionInventoryId ||
                !inventory.IsRequested ||
                !IsCollectInventoryShape(inventory))
            {
                RawCollectLootGrid rawGrid;
                int rawVisited;
                int rawCandidates;
                bool rawResolved =
                    TryResolveRawCollectLootGrid(
                        out rawGrid,
                        out rawVisited,
                        out rawCandidates);
                AllflameLog.Throttled(
                    "collect_surface_adopt_raw_probe",
                    TimeSpan.FromSeconds(2),
                    "COLLECT_SURFACE_UI_ADOPT_PROBE" +
                    "|Source=RawLootGrid" +
                    "|Resolved=" + rawResolved +
                    "|Candidates=" + rawCandidates +
                    "|Visited=" + rawVisited);
                return rawResolved;
            }

            InventoryControlWrapper control;
            int visited;
            int candidates;
            bool resolved =
                TryResolveCollectContainer(
                    inventory,
                    out control,
                    out visited,
                    out candidates);
            AllflameLog.Throttled(
                "collect_surface_adopt_probe",
                TimeSpan.FromSeconds(2),
                "COLLECT_SURFACE_UI_ADOPT_PROBE" +
                "|InventoryId=" + inventory.Id +
                "|Items=" +
                (inventory.Items == null
                    ? -1
                    : inventory.Items.Count) +
                "|ControlResolved=" + resolved +
                "|Candidates=" + candidates +
                "|Visited=" + visited);
            return resolved;
        }

        private static bool IsCollectInventoryShape(
            Inventory inventory)
        {
            return inventory != null &&
                ((inventory.Rows == 5 &&
                  inventory.Columns == 12) ||
                 (inventory.Rows >= 18 &&
                  inventory.Rows <= 24 &&
                  inventory.Columns == 12));
        }

        private void ResetLocalState()
        {
            _opened = false;
            _movedAnyItem = false;
            _openedUtc = DateTime.MinValue;
            _nextActionUtc = DateTime.MinValue;
            _emptyConfirmations = 0;
            _uiResolveRetries = 0;
            _failedTransferItemId = 0;
            _failedTransferCount = 0;
            _cachedCollectionControl = null;
            _rawTabsInitialized = false;
            _rawActiveTab = 0;
            _rawTabOneEmpty = false;
            _rawTabTwoEmpty = false;
            _rawEmptyConfirmations = 0;
            _cachedRawCollectGrid = null;
        }

        private async Task<bool> RetryCollectUiIfTimedOut(
            string reason)
        {
            if (_openedUtc == DateTime.MinValue ||
                DateTime.UtcNow - _openedUtc <
                    TimeSpan.FromSeconds(3))
            {
                return false;
            }

            _uiResolveRetries++;
            AllflameLog.Info(
                "COLLECT_SURFACE_REOPEN" +
                "|Reason=" + reason +
                "|Retry=" + _uiResolveRetries + "/3");
            _opened = false;
            _openedUtc = DateTime.MinValue;
            _emptyConfirmations = 0;
            _cachedCollectionControl = null;
            _rawTabsInitialized = false;
            _rawActiveTab = 0;
            _rawTabOneEmpty = false;
            _rawTabTwoEmpty = false;
            _rawEmptyConfirmations = 0;
            _cachedRawCollectGrid = null;
            await Coroutines.CloseBlockingWindows();
            _nextActionUtc =
                DateTime.UtcNow.AddMilliseconds(500);

            if (_uiResolveRetries < 3)
            {
                return true;
            }

            if (AllflameVoyageDebug.CollectSurfaceLootRequested)
            {
                AllflameVoyageDebug.CompleteCollectSurfaceLoot(
                    "Failed:" + reason);
            }
            _uiResolveRetries = 0;
            return true;
        }

        private static Inventory GetDeepwaterCollectionInventory()
        {
            try
            {
                Inventory inventory =
                    LokiPoe.InstanceInfo.GetPlayerInventoryById(
                        DeepwaterCollectionInventoryId);
                if (inventory != null)
                {
                    AllflameLog.Throttled(
                        "collect_surface_inventory_114_probe",
                        TimeSpan.FromSeconds(2),
                        "COLLECT_SURFACE_INVENTORY_PROBE" +
                        "|RequestedId=" +
                        DeepwaterCollectionInventoryId +
                        "|ResolvedId=" + inventory.Id +
                        "|IsValid=" + inventory.IsValid +
                        "|IsRequested=" +
                        inventory.IsRequested +
                        "|Rows=" + inventory.Rows +
                        "|Columns=" + inventory.Columns +
                        "|Items=" +
                        (inventory.Items == null
                            ? -1
                            : inventory.Items.Count));
                }
                return inventory;
            }
            catch (Exception ex)
            {
                AllflameLog.Throttled(
                    "collect_surface_inventory_114_failed",
                    TimeSpan.FromSeconds(3),
                    "COLLECT_SURFACE_INVENTORY_PROBE_FAILED|" +
                    ex.GetType().Name + "|" +
                    ex.Message.Replace("|", "/"));
                return null;
            }
        }

        private static async Task<bool> WaitForSourceItemMoved(
            Inventory sourceInventory,
            int itemKey,
            Item original,
            int beforeStack,
            int timeoutMilliseconds)
        {
            DateTime until =
                DateTime.UtcNow.AddMilliseconds(
                    Math.Max(100, timeoutMilliseconds));
            do
            {
                Item remaining =
                    FindSourceItem(
                        sourceInventory,
                        itemKey,
                        original);
                if (remaining == null ||
                    !remaining.IsValid ||
                    Math.Max(1, remaining.StackCount) <
                        beforeStack)
                {
                    return true;
                }
                await LokiCoroutine.Sleep(55);
            }
            while (DateTime.UtcNow < until);

            return false;
        }

        private static Item FindSourceItem(
            Inventory sourceInventory,
            int itemKey,
            Item original)
        {
            try
            {
                if (sourceInventory == null ||
                    !sourceInventory.IsValid ||
                    sourceInventory.Items == null)
                {
                    return original;
                }

                return sourceInventory.Items.FirstOrDefault(
                    candidate =>
                        candidate != null &&
                        candidate.IsValid &&
                        ((candidate.LocalId != 0 &&
                          candidate.LocalId == itemKey) ||
                         (candidate.LocalId == 0 &&
                          candidate.Id == itemKey) ||
                         (original != null &&
                          candidate.LocationTopLeft ==
                              original.LocationTopLeft &&
                          String.Equals(
                              candidate.Metadata,
                              original.Metadata,
                              StringComparison.Ordinal))));
            }
            catch
            {
                return original;
            }
        }

        private static int GetPlayerInventoryFreeSquares()
        {
            try
            {
                InventoryControlWrapper control =
                    LokiPoe.InGameState.InventoryUi
                        .InventoryControl_Main;
                return control == null ||
                    control.Inventory == null
                        ? -1
                        : control.Inventory
                            .AvailableInventorySquares;
            }
            catch
            {
                return -1;
            }
        }

        private static async Task<bool> CtrlClickContainerItem(
            InventoryControlWrapper control,
            Item item)
        {
            try
            {
                if (control == null ||
                    control.InventorySlotUiElement == null)
                {
                    return false;
                }

                var slotUi = control.InventorySlotUiElement;
                Element element = null;
                var elements = slotUi.DictionaryIdElements;
                if (elements != null &&
                    !elements.TryGetValue(item.LocalId, out element))
                {
                    elements.TryGetValue(item.Id, out element);
                }
                Vector2i location =
                    element != null &&
                    element.IsValid &&
                    element.IsVisible
                        ? element.CenterClickLocation()
                        : slotUi.SlotClickLocation(
                            new Vector2i(
                                item.LocationTopLeft.X + 1,
                                item.LocationTopLeft.Y + 1));
                bool controlDown = false;
                try
                {
                    LokiPoe.ProcessHookManager.ClearAllKeyStates();
                    DreamPoeBot.BotFramework.MouseManager
                        .SetMousePosition(location, true);
                    LokiPoe.ProcessHookManager.SetKeyState(
                        System.Windows.Forms.Keys.ControlKey,
                        short.MinValue,
                        System.Windows.Forms.Keys.None);
                    controlDown = true;
                    await LokiCoroutine.Sleep(25);
                    DreamPoeBot.BotFramework.MouseManager.ClickLMB(0, 0);
                    await LokiCoroutine.Sleep(90);
                    return true;
                }
                finally
                {
                    if (controlDown)
                    {
                        LokiPoe.ProcessHookManager.SetKeyState(
                            System.Windows.Forms.Keys.ControlKey,
                            (short)0,
                            System.Windows.Forms.Keys.None);
                    }
                }
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "COLLECT_SURFACE_ITEM_FAILED|" +
                    ex.GetType().Name + "|" + ex.Message);
                return false;
            }
        }

        private async Task<bool> ProcessRawCollectLootGrid(
            RawCollectLootGrid grid,
            int visited,
            int candidates)
        {
            if (grid == null ||
                grid.Slot == null)
            {
                return true;
            }

            List<KeyValuePair<int, Element>> itemElements =
                GetRawCollectItemElements(grid);
            AllflameLog.Throttled(
                "collect_raw_ui",
                TimeSpan.FromSeconds(2),
                "COLLECT_RAW_UI" +
                "|Title=True" +
                "|Root=0x" + grid.RootAddress.ToString("X") +
                "|Grid=0x" + grid.GridAddress.ToString("X") +
                "|Size=" + grid.Columns + "x" + grid.Rows +
                "|Items=" + itemElements.Count +
                "|Tabs=" + grid.Tabs.Count +
                "|ActiveTab=" + _rawActiveTab +
                "|Candidates=" + candidates +
                "|Visited=" + visited);

            if (!_rawTabsInitialized)
            {
                Element firstTab = GetRawCollectTab(grid, 1);
                bool clicked =
                    firstTab != null
                        ? await ClickRawElement(firstTab, false)
                        : await ClickDerivedRawGridTab(grid, 1);
                AllflameLog.Info(
                    "COLLECT_RAW_TAB|Tab=1|Action=Initialize" +
                    "|Mode=" +
                    (firstTab == null
                        ? "GridDerived"
                        : "Element") +
                    "|Success=" + clicked);
                if (clicked)
                {
                    _rawTabsInitialized = true;
                    _rawActiveTab = 1;
                    _rawEmptyConfirmations = 0;
                }
                _nextActionUtc =
                    DateTime.UtcNow.AddMilliseconds(220);
                return true;
            }

            if (itemElements.Count > 0)
            {
                _rawEmptyConfirmations = 0;
                KeyValuePair<int, Element> target =
                    itemElements
                        .OrderBy(pair =>
                            pair.Value.CenterClickLocation().Y)
                        .ThenBy(pair =>
                            pair.Value.CenterClickLocation().X)
                        .First();
                int beforeCount = itemElements.Count;
                long beforeAddress = target.Value.Address;
                bool clickSent =
                    await ClickRawElement(target.Value, true);
                bool transferred =
                    clickSent &&
                    await WaitForRawCollectItemMoved(
                        grid,
                        target.Key,
                        beforeAddress,
                        beforeCount,
                        650);
                AllflameLog.Info(
                    "COLLECT_RAW_ITEM|Key=" + target.Key +
                    "|Address=0x" +
                    beforeAddress.ToString("X") +
                    "|Tab=" + _rawActiveTab +
                    "|Before=" + beforeCount +
                    "|Success=" + transferred +
                    "|CtrlClickSent=" + clickSent);

                if (transferred)
                {
                    _movedAnyItem = true;
                    _failedTransferItemId = 0;
                    _failedTransferCount = 0;
                    _uiResolveRetries = 0;
                    _nextActionUtc =
                        DateTime.UtcNow.AddMilliseconds(105);
                }
                else
                {
                    if (_failedTransferItemId != target.Key)
                    {
                        _failedTransferItemId = target.Key;
                        _failedTransferCount = 0;
                    }
                    _failedTransferCount++;
                    _nextActionUtc =
                        DateTime.UtcNow.AddMilliseconds(230);
                    if (_failedTransferCount >= 2)
                    {
                        AllflameLog.Info(
                            "COLLECT_SURFACE_REOPEN" +
                            "|Reason=TwoRawUiTransferFailures" +
                            "|Key=" + target.Key);
                        _opened = false;
                        _openedUtc = DateTime.MinValue;
                        _failedTransferCount = 0;
                        _rawTabsInitialized = false;
                        _cachedRawCollectGrid = null;
                        await Coroutines.CloseBlockingWindows();
                        _nextActionUtc =
                            DateTime.UtcNow.AddMilliseconds(500);
                    }
                }
                return true;
            }

            _rawEmptyConfirmations++;
            if (_rawEmptyConfirmations < 2)
            {
                _nextActionUtc =
                    DateTime.UtcNow.AddMilliseconds(180);
                return true;
            }

            if (_rawActiveTab == 1)
            {
                _rawTabOneEmpty = true;
                Element secondTab = GetRawCollectTab(grid, 2);
                bool clicked =
                    secondTab != null
                        ? await ClickRawElement(secondTab, false)
                        : await ClickDerivedRawGridTab(grid, 2);
                AllflameLog.Info(
                    "COLLECT_RAW_TAB|Tab=2|Action=Switch" +
                    "|Mode=" +
                    (secondTab == null
                        ? "GridDerived"
                        : "Element") +
                    "|Success=" + clicked);
                if (clicked)
                {
                    _rawActiveTab = 2;
                    _rawEmptyConfirmations = 0;
                }
                _nextActionUtc =
                    DateTime.UtcNow.AddMilliseconds(220);
                return true;
            }

            if (_rawActiveTab == 2)
            {
                _rawTabTwoEmpty = true;
            }
            if (!_rawTabOneEmpty ||
                !_rawTabTwoEmpty)
            {
                _nextActionUtc =
                    DateTime.UtcNow.AddMilliseconds(200);
                return true;
            }

            VoyageRunState.MarkSurfaceCollected();
            AllflameVoyageDebug.CompleteCollectSurfaceLoot(
                "RawGridTabsEmpty");
            ResetLocalState();
            await Coroutines.CloseBlockingWindows();
            AllflameLog.Info(
                "VOYAGE_STAGE|Stage=10|State=Collected" +
                "|Source=RawLootGrid" +
                "|Action=ContinueToStash");
            return false;
        }

        private static async Task<bool> ClickDerivedRawGridTab(
            RawCollectLootGrid grid,
            int tab)
        {
            try
            {
                if (grid == null ||
                    grid.Slot == null ||
                    !grid.Slot.IsValid ||
                    !grid.Slot.IsVisible ||
                    (tab != 1 && tab != 2))
                {
                    return false;
                }

                Vector2i center =
                    grid.Slot.CenterClickLocation();
                float cell =
                    grid.Slot.Width /
                    Math.Max(1, grid.Columns);
                int x =
                    (int)(center.X +
                        (tab == 1 ? -0.9f : 0.9f) * cell);
                int y =
                    (int)(center.Y -
                        grid.Slot.Height / 2f -
                        0.85f * cell);
                LokiPoe.ProcessHookManager.ClearAllKeyStates();
                DreamPoeBot.BotFramework.MouseManager
                    .SetMousePosition(
                        new Vector2i(x, y),
                        true);
                DreamPoeBot.BotFramework.MouseManager
                    .ClickLMB(0, 0);
                await LokiCoroutine.Sleep(120);
                return true;
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "COLLECT_RAW_TAB_CLICK_FAILED|Tab=" + tab +
                    "|" + ex.GetType().Name +
                    "|" + ex.Message.Replace("|", "/"));
                return false;
            }
        }

        private static Element GetRawCollectTab(
            RawCollectLootGrid grid,
            int number)
        {
            if (grid == null ||
                grid.Tabs == null)
            {
                return null;
            }
            Element result;
            return grid.Tabs.TryGetValue(number, out result)
                ? result
                : null;
        }

        private static List<KeyValuePair<int, Element>>
            GetRawCollectItemElements(RawCollectLootGrid grid)
        {
            var output =
                new List<KeyValuePair<int, Element>>();
            try
            {
                if (grid == null ||
                    grid.Slot == null ||
                    !grid.Slot.IsValid ||
                    !grid.Slot.IsVisible)
                {
                    return output;
                }

                Dictionary<int, Element> elements =
                    grid.Slot.DictionaryIdElements;
                if (elements == null)
                {
                    return output;
                }

                Vector2i gridCenter =
                    grid.Slot.CenterClickLocation();
                float halfWidth =
                    Math.Max(1f, grid.Slot.Width / 2f);
                float halfHeight =
                    Math.Max(1f, grid.Slot.Height / 2f);
                foreach (KeyValuePair<int, Element> pair in elements)
                {
                    Element element = pair.Value;
                    if (element == null ||
                        !element.IsValid ||
                        !element.IsVisible)
                    {
                        continue;
                    }
                    Vector2i center =
                        element.CenterClickLocation();
                    if (center.X < gridCenter.X - halfWidth ||
                        center.X > gridCenter.X + halfWidth ||
                        center.Y < gridCenter.Y - halfHeight ||
                        center.Y > gridCenter.Y + halfHeight)
                    {
                        continue;
                    }
                    output.Add(pair);
                }
            }
            catch
            {
                output.Clear();
            }
            return output;
        }

        private static async Task<bool> WaitForRawCollectItemMoved(
            RawCollectLootGrid grid,
            int itemKey,
            long itemAddress,
            int beforeCount,
            int timeoutMilliseconds)
        {
            DateTime until =
                DateTime.UtcNow.AddMilliseconds(
                    Math.Max(100, timeoutMilliseconds));
            do
            {
                if (grid == null ||
                    grid.Slot == null ||
                    !grid.Slot.IsValid ||
                    !grid.Slot.IsVisible)
                {
                    return true;
                }
                List<KeyValuePair<int, Element>> remaining =
                    GetRawCollectItemElements(grid);
                bool originalStillPresent =
                    remaining.Any(pair =>
                        pair.Key == itemKey &&
                        pair.Value != null &&
                        pair.Value.IsValid &&
                        pair.Value.Address == itemAddress);
                if (remaining.Count < beforeCount ||
                    !originalStillPresent)
                {
                    return true;
                }
                await LokiCoroutine.Sleep(55);
            }
            while (DateTime.UtcNow < until);

            return false;
        }

        private static async Task<bool> ClickRawElement(
            Element element,
            bool controlClick)
        {
            try
            {
                if (element == null ||
                    !element.IsValid ||
                    !element.IsVisible)
                {
                    return false;
                }

                Vector2i location =
                    element.CenterClickLocation();
                bool controlDown = false;
                try
                {
                    LokiPoe.ProcessHookManager.ClearAllKeyStates();
                    DreamPoeBot.BotFramework.MouseManager
                        .SetMousePosition(location, true);
                    if (controlClick)
                    {
                        LokiPoe.ProcessHookManager.SetKeyState(
                            System.Windows.Forms.Keys.ControlKey,
                            short.MinValue,
                            System.Windows.Forms.Keys.None);
                        controlDown = true;
                        await LokiCoroutine.Sleep(25);
                    }
                    DreamPoeBot.BotFramework.MouseManager.ClickLMB(0, 0);
                    await LokiCoroutine.Sleep(controlClick ? 85 : 120);
                    return true;
                }
                finally
                {
                    if (controlDown)
                    {
                        LokiPoe.ProcessHookManager.SetKeyState(
                            System.Windows.Forms.Keys.ControlKey,
                            (short)0,
                            System.Windows.Forms.Keys.None);
                    }
                }
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "COLLECT_RAW_CLICK_FAILED|" +
                    ex.GetType().Name + "|" +
                    ex.Message.Replace("|", "/"));
                return false;
            }
        }

        private bool TryUseCachedRawCollectGrid(
            out RawCollectLootGrid grid)
        {
            grid = _cachedRawCollectGrid;
            try
            {
                if (grid == null ||
                    grid.Slot == null ||
                    !grid.Slot.IsValid ||
                    !grid.Slot.IsVisible ||
                    grid.Columns != 12 ||
                    grid.Rows < 18 ||
                    grid.Rows > 24)
                {
                    _cachedRawCollectGrid = null;
                    grid = null;
                    return false;
                }
                return true;
            }
            catch
            {
                _cachedRawCollectGrid = null;
                grid = null;
                return false;
            }
        }

        private static bool TryResolveRawCollectLootGrid(
            out RawCollectLootGrid result,
            out int visited,
            out int candidateCount)
        {
            result = null;
            visited = 0;
            candidateCount = 0;
            try
            {
                List<Element> roots = LokiPoe.GetGuiElements();
                if (roots == null)
                {
                    return false;
                }

                var queue =
                    new Queue<Tuple<Element, long>>();
                var seen = new HashSet<long>();
                var visible =
                    new List<Tuple<Element, long>>();
                foreach (Element root in roots)
                {
                    if (root == null)
                    {
                        continue;
                    }
                    queue.Enqueue(
                        Tuple.Create(root, root.Address));
                }

                while (queue.Count > 0 &&
                       visited < MaximumCollectUiElements)
                {
                    Tuple<Element, long> entry = queue.Dequeue();
                    Element element = entry.Item1;
                    if (element == null)
                    {
                        continue;
                    }
                    long address = element.Address;
                    if (address == 0 ||
                        !seen.Add(address))
                    {
                        continue;
                    }
                    visited++;
                    if (!element.IsValid ||
                        !element.IsVisible)
                    {
                        continue;
                    }
                    visible.Add(entry);
                    List<Element> children = element.Children;
                    if (children == null)
                    {
                        continue;
                    }
                    foreach (Element child in children)
                    {
                        if (child != null)
                        {
                            queue.Enqueue(
                                Tuple.Create(
                                    child,
                                    entry.Item2));
                        }
                    }
                }

                List<Tuple<Element, long>> titles =
                    visible.Where(entry =>
                    {
                        try
                        {
                            return String.Equals(
                                (entry.Item1.Text ??
                                 String.Empty).Trim(),
                                "LOOT",
                                StringComparison.OrdinalIgnoreCase);
                        }
                        catch
                        {
                            return false;
                        }
                    }).ToList();
                List<Tuple<Element, long>> tabLabels =
                    visible.Where(entry =>
                    {
                        try
                        {
                            string text =
                                (entry.Item1.Text ??
                                 String.Empty).Trim();
                            return text == "1" ||
                                text == "2";
                        }
                        catch
                        {
                            return false;
                        }
                    }).ToList();

                float playerGridLeft =
                    (LokiPoe.ClientWindowInfo.Client.Right -
                     LokiPoe.ClientWindowInfo.Client.Left) * 0.58f;
                try
                {
                    InventoryControlWrapper playerControl =
                        LokiPoe.InGameState.InventoryUi
                            .InventoryControl_Main;
                    InventorySlotUiElement playerSlot =
                        playerControl == null
                            ? null
                            : playerControl.InventorySlotUiElement;
                    if (playerSlot != null &&
                        playerSlot.IsValid &&
                        playerSlot.IsVisible)
                    {
                        playerGridLeft =
                            playerSlot.CenterClickLocation().X -
                            playerSlot.Width / 2f;
                    }
                }
                catch
                {
                    // Client-relative split is sufficient as fallback.
                }

                var grids =
                    new List<Tuple<int, RawCollectLootGrid>>();
                int geometricElements = 0;
                int validSlots = 0;
                int expectedSizeSlots = 0;
                int dictionarySlots = 0;
                var signatures = new List<string>();
                foreach (Tuple<Element, long> entry in visible)
                {
                    Element element = entry.Item1;
                    try
                    {
                        bool portraitGeometry =
                            element.Width >= 250f &&
                            element.Width <= 900f &&
                            element.Height >= 300f &&
                            element.Height <= 1050f;
                        bool possibleContainer =
                            portraitGeometry ||
                            element.ChildCount >= 4;
                        if (!possibleContainer)
                        {
                            continue;
                        }
                        if (portraitGeometry)
                        {
                            geometricElements++;
                        }

                        InventorySlotUiElement slot =
                            CreateRawCollectSlot(element);
                        if (slot == null ||
                            !slot.IsValid ||
                            !slot.IsVisible)
                        {
                            continue;
                        }
                        validSlots++;
                        Vector2i size = slot.Size;
                        int rawSizeX = size.X;
                        int rawSizeY = size.Y;
                        float slotAspect =
                            slot.Width /
                            Math.Max(1f, slot.Height);
                        bool expectedGridGeometry =
                            slot.Width >= 300f &&
                            slot.Width <= 1050f &&
                            slot.Height >= 450f &&
                            slot.Height <= 1500f &&
                            slotAspect >= 0.42f &&
                            slotAspect <= 0.92f;
                        if (expectedGridGeometry)
                        {
                            expectedSizeSlots++;
                        }
                        Dictionary<int, Element> itemDictionary =
                            slot.DictionaryIdElements;
                        int items =
                            itemDictionary == null
                                ? -1
                                : itemDictionary.Count;
                        if (itemDictionary != null)
                        {
                            dictionarySlots++;
                        }
                        Vector2i center =
                            slot.CenterClickLocation();
                        Tuple<Element, long> title =
                            titles
                                .Where(candidate =>
                                    candidate.Item2 == entry.Item2)
                                .OrderBy(candidate =>
                                {
                                    Vector2i titleCenter =
                                        candidate.Item1
                                            .CenterClickLocation();
                                    return Math.Abs(
                                        titleCenter.X - center.X) +
                                        Math.Abs(
                                            titleCenter.Y - center.Y);
                                })
                                .FirstOrDefault();
                        Vector2i titlePosition =
                            title == null
                                ? new Vector2i(
                                    center.X,
                                    (int)(center.Y -
                                        slot.Height / 2f - 70f))
                                : title.Item1.CenterClickLocation();
                        bool titleAligned =
                            title != null &&
                            Math.Abs(
                                titlePosition.X - center.X) <=
                                Math.Max(
                                    300,
                                    (int)(slot.Width * 0.85f)) &&
                            center.Y >= titlePosition.Y + 70 &&
                            center.Y <= titlePosition.Y + 850;
                        bool leftOfPlayer =
                            center.X + slot.Width / 2f <
                                playerGridLeft + 80f;
                        Dictionary<int, Element> resolvedTabs =
                            ResolveRawCollectTabs(
                                visible,
                                entry.Item2,
                                titlePosition,
                                slot);
                        bool bothTabs =
                            resolvedTabs.ContainsKey(1) &&
                            resolvedTabs.ContainsKey(2);
                        if (signatures.Count < 8)
                        {
                            signatures.Add(
                                "0x" +
                                element.Address.ToString("X") +
                                ":raw=" +
                                rawSizeX + "x" + rawSizeY +
                                ":px=" +
                                (int)slot.Width + "x" +
                                (int)slot.Height +
                                ":items=" + items +
                                ":left=" + leftOfPlayer +
                                ":title=" + titleAligned +
                                ":tabs=" + resolvedTabs.Count);
                        }
                        bool confidentStructure =
                            leftOfPlayer &&
                            expectedGridGeometry &&
                            itemDictionary != null &&
                            items > 0 &&
                            (titleAligned ||
                             bothTabs);
                        if (!confidentStructure)
                        {
                            continue;
                        }

                        var raw =
                            new RawCollectLootGrid
                            {
                                RootAddress = entry.Item2,
                                GridAddress = element.Address,
                                Slot = slot,
                                Columns = 12,
                                Rows = 20,
                                Tabs = resolvedTabs
                            };
                        int score =
                            (expectedGridGeometry ? 1000 : 0) +
                            (items > 0 ? 200 + items : 0) +
                            raw.Tabs.Count * 100 +
                            (titleAligned ? 250 : 0) -
                            (int)(Math.Abs(
                                slotAspect - 0.61f) * 200f);
                        grids.Add(Tuple.Create(score, raw));
                    }
                    catch
                    {
                        // Most visible UI elements are not inventory slots.
                    }
                }

                candidateCount = grids.Count;
                AllflameLog.Throttled(
                    "collect_raw_probe",
                    TimeSpan.FromSeconds(2),
                    "COLLECT_RAW_PROBE" +
                    "|Titles=" + titles.Count +
                    "|TabLabels=" + tabLabels.Count +
                    "|Visible=" + visible.Count +
                    "|Geometry=" + geometricElements +
                    "|ValidSlots=" + validSlots +
                    "|ExpectedGridGeometry=" +
                    expectedSizeSlots +
                    "|Dictionaries=" + dictionarySlots +
                    "|Accepted=" + candidateCount +
                    "|Signatures=" +
                    String.Join(",", signatures));
                Tuple<int, RawCollectLootGrid> best =
                    grids
                        .OrderByDescending(candidate =>
                            candidate.Item1)
                        .FirstOrDefault();
                if (best == null)
                {
                    return false;
                }
                result = best.Item2;
                return true;
            }
            catch (Exception ex)
            {
                AllflameLog.Throttled(
                    "collect_raw_ui_failed",
                    TimeSpan.FromSeconds(2),
                    "COLLECT_RAW_UI_FAILED|" +
                    ex.GetType().Name + "|" +
                    ex.Message.Replace("|", "/"));
                result = null;
                return false;
            }
        }

        private static InventorySlotUiElement CreateRawCollectSlot(
            Element element)
        {
            if (element == null)
            {
                return null;
            }
            try
            {
                var direct =
                    new InventorySlotUiElement(
                        element.Address,
                        StashType.NormalStash);
                if (direct.IsValid &&
                    direct.IsVisible)
                {
                    return direct;
                }
            }
            catch
            {
                // Some DPB builds expose the parent control instead.
            }

            try
            {
                var wrapper =
                    new InventoryControlWrapper(
                        element.Address);
                InventorySlotUiElement wrapped =
                    wrapper.InventorySlotUiElement;
                return wrapped != null &&
                    wrapped.IsValid &&
                    wrapped.IsVisible
                        ? wrapped
                        : null;
            }
            catch
            {
                return null;
            }
        }

        private static Dictionary<int, Element>
            ResolveRawCollectTabs(
                IList<Tuple<Element, long>> visible,
                long rootAddress,
                Vector2i titleCenter,
                InventorySlotUiElement slot)
        {
            var tabs = new Dictionary<int, Element>();
            Vector2i gridCenter = slot.CenterClickLocation();
            float gridTop =
                gridCenter.Y - slot.Height / 2f;
            foreach (Tuple<Element, long> entry in visible)
            {
                if (entry.Item2 != rootAddress)
                {
                    continue;
                }
                try
                {
                    string text =
                        (entry.Item1.Text ??
                         String.Empty).Trim();
                    int number;
                    if (!Int32.TryParse(text, out number) ||
                        number < 1 ||
                        number > 9)
                    {
                        continue;
                    }
                    Vector2i center =
                        entry.Item1.CenterClickLocation();
                    if (center.Y < titleCenter.Y + 20 ||
                        center.Y > gridTop + 35 ||
                        Math.Abs(center.X - gridCenter.X) >
                            slot.Width / 2f + 40f)
                    {
                        continue;
                    }
                    Element previous;
                    if (!tabs.TryGetValue(number, out previous) ||
                        entry.Item1.Width * entry.Item1.Height >
                        previous.Width * previous.Height)
                    {
                        tabs[number] = entry.Item1;
                    }
                }
                catch
                {
                    // Ignore transient label nodes.
                }
            }
            return tabs;
        }

        private sealed class RawCollectLootGrid
        {
            public long RootAddress { get; set; }
            public long GridAddress { get; set; }
            public InventorySlotUiElement Slot { get; set; }
            public int Columns { get; set; }
            public int Rows { get; set; }
            public Dictionary<int, Element> Tabs { get; set; }
        }

        private static bool TryResolveCollectContainer(
            Inventory knownInventory,
            out InventoryControlWrapper control,
            out int visited,
            out int candidateCount)
        {
            control = null;
            visited = 0;
            candidateCount = 0;
            try
            {
                InventoryControlWrapper playerControl =
                    LokiPoe.InGameState.InventoryUi
                        .InventoryControl_Main;
                Element playerSlot =
                    playerControl == null
                        ? null
                        : playerControl.InventorySlotUiElement;
                float playerGridLeft =
                    playerSlot != null &&
                    playerSlot.IsValid
                        ? playerSlot.CenterClickLocation().X -
                          playerSlot.Width / 2f
                        : (LokiPoe.ClientWindowInfo.Client.Right -
                           LokiPoe.ClientWindowInfo.Client.Left) *
                          0.58f;

                var candidates =
                    new List<Tuple<float, InventoryControlWrapper>>();
                var controlAddresses = new HashSet<long>();
                var elementAddresses = new HashSet<long>();
                var candidateElements =
                    new List<Tuple<Element, long>>();
                var collectTitleCenters =
                    new List<Tuple<Vector2i, long>>();
                List<Element> roots = LokiPoe.GetGuiElements();
                if (roots == null)
                {
                    return false;
                }

                var queue =
                    new Queue<Tuple<Element, long>>();
                foreach (Element root in roots)
                {
                    if (root != null)
                    {
                        long rootAddress;
                        try
                        {
                            rootAddress = root.Address;
                        }
                        catch
                        {
                            continue;
                        }
                        queue.Enqueue(
                            Tuple.Create(
                                root,
                                rootAddress));
                    }
                }

                while (queue.Count > 0 &&
                       visited < MaximumCollectUiElements)
                {
                    Tuple<Element, long> queued =
                        queue.Dequeue();
                    Element element = queued.Item1;
                    long rootAddress = queued.Item2;
                    if (element == null)
                    {
                        continue;
                    }

                    long elementAddress;
                    try
                    {
                        elementAddress = element.Address;
                    }
                    catch
                    {
                        continue;
                    }
                    if (elementAddress == 0 ||
                        !elementAddresses.Add(elementAddress))
                    {
                        continue;
                    }
                    visited++;

                    bool globallyVisible;
                    try
                    {
                        globallyVisible =
                            element.IsValid &&
                            element.IsVisible;
                        if (globallyVisible)
                        {
                            string text =
                                element.Text ??
                                String.Empty;
                            string normalizedText =
                                text.Trim();
                            if (String.Equals(
                                    normalizedText,
                                    "LOOT",
                                    StringComparison
                                        .OrdinalIgnoreCase) ||
                                normalizedText.IndexOf(
                                    "Collect Loot",
                                    StringComparison
                                        .OrdinalIgnoreCase) >= 0)
                            {
                                collectTitleCenters.Add(
                                    Tuple.Create(
                                        element
                                            .CenterClickLocation(),
                                        rootAddress));
                            }
                            if (element.Width >= 60f &&
                                element.Width <= 1100f &&
                                element.Height >= 60f &&
                                element.Height <= 980f)
                            {
                                candidateElements.Add(
                                    Tuple.Create(
                                        element,
                                        rootAddress));
                            }
                        }
                    }
                    catch
                    {
                        // The GUI tree can mutate during a snapshot.
                        globallyVisible = false;
                    }
                    if (!globallyVisible)
                    {
                        continue;
                    }

                    List<Element> children;
                    try
                    {
                        children = element.Children;
                    }
                    catch
                    {
                        children = null;
                    }
                    if (children == null)
                    {
                        continue;
                    }
                    foreach (Element child in children)
                    {
                        if (child != null)
                        {
                            queue.Enqueue(
                                Tuple.Create(
                                    child,
                                    rootAddress));
                        }
                    }
                }

                foreach (Tuple<Element, long> candidateElement in
                    candidateElements)
                {
                    TryAddCollectContainerControl(
                        candidateElement.Item1,
                        candidateElement.Item2,
                        knownInventory,
                        playerControl,
                        playerGridLeft,
                        collectTitleCenters,
                        candidates,
                        controlAddresses);
                    if (knownInventory != null &&
                        candidates.Count > 0)
                    {
                        break;
                    }
                }

                candidateCount = candidates.Count;
                Tuple<float, InventoryControlWrapper> best =
                    candidates
                        .OrderByDescending(candidate =>
                            candidate.Item2.Inventory == null ||
                            candidate.Item2.Inventory.Items == null
                                ? 0
                                : candidate.Item2.Inventory.Items.Count)
                        .ThenBy(candidate => candidate.Item1)
                        .FirstOrDefault();
                if (best == null)
                {
                    return false;
                }

                control = best.Item2;
                return true;
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "COLLECT_SURFACE_UI_FAILED|" +
                    ex.GetType().Name + "|" +
                    ex.Message.Replace("|", "/"));
                control = null;
                return false;
            }
        }

        private static void TryAddCollectContainerControl(
            Element element,
            long rootAddress,
            Inventory knownInventory,
            InventoryControlWrapper playerControl,
            float playerGridLeft,
            IList<Tuple<Vector2i, long>> collectTitleCenters,
            IList<Tuple<float, InventoryControlWrapper>> output,
            ISet<long> addresses)
        {
            if (element == null)
            {
                return;
            }

            try
            {
                if (element.IsValid &&
                    element.IsVisible)
                {
                    var candidate =
                        new InventoryControlWrapper(
                            element.Address);
                    Element slot =
                        candidate.InventorySlotUiElement;
                    Inventory nativeInventory =
                        candidate.Inventory;
                    bool nativeCollectionInventory =
                        nativeInventory != null &&
                        nativeInventory.IsValid &&
                        nativeInventory.Id ==
                            DeepwaterCollectionInventoryId;
                    bool nativeGenericInventory =
                        knownInventory == null &&
                        nativeInventory != null &&
                        nativeInventory.IsValid &&
                        IsCollectInventoryShape(
                            nativeInventory);
                    Element playerSlot =
                        playerControl == null
                            ? null
                            : playerControl
                                .InventorySlotUiElement;
                    bool gridShape =
                        slot != null &&
                        slot.IsValid &&
                        slot.IsVisible &&
                        slot.Width >= 300f &&
                        slot.Width <= 1400f &&
                        slot.Height >= 100f &&
                        slot.Height <= 980f &&
                        ((slot.Width / Math.Max(
                              1f,
                              slot.Height) >= 1.7f &&
                          slot.Width / Math.Max(
                              1f,
                              slot.Height) <= 3.4f) ||
                         (slot.Width / Math.Max(
                              1f,
                              slot.Height) >= 0.42f &&
                          slot.Width / Math.Max(
                              1f,
                              slot.Height) <= 1.15f));
                    bool sameControlType =
                        playerSlot == null ||
                        !playerSlot.IsValid ||
                        slot == null ||
                        slot.ControlType ==
                            playerSlot.ControlType;
                    Vector2i slotCenter =
                        slot == null
                            ? new Vector2i()
                            : slot.CenterClickLocation();
                    bool nearCollectTitle =
                        collectTitleCenters != null &&
                        collectTitleCenters.Any(title =>
                            title.Item2 == rootAddress &&
                            Math.Abs(
                                title.Item1.X -
                                slotCenter.X) <=
                                Math.Max(
                                    400,
                                    (int)(slot.Width * 0.75f)) &&
                            slotCenter.Y >=
                                title.Item1.Y + 40 &&
                            slotCenter.Y <=
                                title.Item1.Y + 900);
                    bool seasonalGridSignature =
                        knownInventory != null &&
                        gridShape &&
                        sameControlType &&
                        nearCollectTitle;
                    Inventory candidateInventory =
                        nativeCollectionInventory
                            ? nativeInventory
                            : (seasonalGridSignature
                                ? knownInventory
                                : nativeInventory);
                    if (slot != null &&
                        slot.IsValid &&
                        slot.IsVisible &&
                        candidateInventory != null &&
                        candidateInventory.IsValid &&
                        IsCollectInventoryShape(
                            candidateInventory) &&
                        (nativeCollectionInventory ||
                         nativeGenericInventory ||
                         seasonalGridSignature) &&
                        (playerControl == null ||
                         candidate.Address !=
                            playerControl.Address))
                    {
                        if (knownInventory != null &&
                            (nativeCollectionInventory ||
                             seasonalGridSignature))
                        {
                            candidate.SetInventory(
                                knownInventory);
                        }
                        float left =
                            slot.CenterClickLocation().X -
                            slot.Width / 2f;
                        bool leftOfPlayer =
                            left + 40f < playerGridLeft;
                        if (leftOfPlayer &&
                            addresses.Add(candidate.Address))
                        {
                            output.Add(
                                Tuple.Create(left, candidate));
                        }
                    }
                }
            }
            catch
            {
                // Most Element addresses are not inventory controls.
            }
        }
    }

