    internal static class AllflameTransferTiming
    {
        private static readonly Random Random = new Random();
        private static readonly object Sync = new object();

        public static int NextDelayMilliseconds(
            AllflameSettings settings)
        {
            int minimum = Math.Max(
                40,
                Math.Min(
                    1500,
                    settings.ItemTransferDelayMinMilliseconds));
            int maximum = Math.Max(
                minimum,
                Math.Min(
                    1500,
                    settings.ItemTransferDelayMaxMilliseconds));
            lock (Sync)
            {
                return Random.Next(
                    minimum,
                    maximum == Int32.MaxValue
                        ? maximum
                        : maximum + 1);
            }
        }
    }

    internal sealed class SecretBottleProcessingTask : ObserverTask
    {
        private const string BottleRevealIdLabel =
            "bottled_item_reveal_window";
        private const int MaximumRevealUiElements = 5000;
        private const int AcceptTemplateWidth = 78;
        private const int AcceptTemplateHeight = 19;
        private const double MinimumAcceptCorrelation = 0.60;
        private const string AcceptTemplateBase64 =
            "";
        private static readonly byte[] AcceptTemplate =
            Convert.FromBase64String(AcceptTemplateBase64);
        private static readonly double AcceptTemplateMean =
            AcceptTemplate.Average(value => (double)value);
        private static readonly double AcceptTemplateEnergy =
            AcceptTemplate.Sum(value =>
                (value - AcceptTemplateMean) *
                (value - AcceptTemplateMean));

        private enum ProcessingStage
        {
            Withdraw,
            Opening,
            FindVendor,
            Transfer,
            Accept
        }

        private enum BottleOpenStage
        {
            Idle,
            ConfirmConsumed,
            AwaitCursor,
            PlaceCursor,
            ConfirmPlacement,
            ResolvePlacedItem
        }

        private sealed class ItemSnapshot
        {
            public int LocalId { get; set; }
            public int StackCount { get; set; }
            public string Name { get; set; }
            public string Metadata { get; set; }
        }

        private sealed class RewardDecision
        {
            public bool Sell { get; set; }
            public bool ThresholdEligible { get; set; }
            public bool TrustedPrice { get; set; }
            public bool PriceFresh { get; set; }
            public bool FixedPrice { get; set; }
            public string Rarity { get; set; }
            public AllflamePriceQuote Quote { get; set; }
        }

        private sealed class RewardPlacementResult
        {
            public string Status { get; set; }
            public RewardDecision Decision { get; set; }
            public Item PlacedItem { get; set; }
            public int Column { get; set; }
            public int Row { get; set; }
        }

        private enum BottleTabState
        {
            Unknown,
            Available,
            Depleted,
            Failed
        }

        private sealed class BottleTabSnapshot
        {
            public string Name { get; set; }
            public int Remaining { get; set; }
            public BottleTabState State { get; set; }
        }

        private readonly HashSet<int> _sellLocalIds =
            new HashSet<int>();
        private readonly HashSet<int> _transferredLocalIds =
            new HashSet<int>();
        private readonly HashSet<int> _triedNpcIds =
            new HashSet<int>();
        private readonly Dictionary<int, int> _openAttempts =
            new Dictionary<int, int>();
        private readonly Dictionary<int, int> _transferAttempts =
            new Dictionary<int, int>();
        private readonly Dictionary<string, int> _withdrawAttempts =
            new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        private readonly Dictionary<string, int> _tabSwitchAttempts =
            new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        private readonly List<BottleTabSnapshot> _bottleTabs =
            new List<BottleTabSnapshot>();
        private bool _active;
        private bool _cycleComplete;
        private bool _cycleCompletionPending;
        private bool _scanComplete;
        private bool _waitingForInventorySpace;
        private ProcessingStage _stage;
        private int _scanIndex;
        private int _withdrawTarget;
        private int _opened;
        private int _kept;
        private int _sold;
        private int _failed;
        private int _vendorAcceptAttempts;
        private Npc _vendor;
        private DateTime _vendorStartedUtc = DateTime.MinValue;
        private DateTime _vendorAcceptDeadlineUtc = DateTime.MinValue;
        private DateTime _nextSessionUtc = DateTime.MinValue;
        private uint _sessionAreaHash;
        private string _cycleSettingsSignature = String.Empty;
        private string _snapshotCharacter = String.Empty;
        private BottleOpenStage _bottleOpenStage = BottleOpenStage.Idle;
        private int _activeBottleKey;
        private int _activeBottleBeforeStack;
        private string _activeBottleUseResult = String.Empty;
        private Dictionary<int, ItemSnapshot> _activeBottleBefore;
        private RewardPlacementResult _activePlacement;
        private DateTime _bottleStageDeadlineUtc = DateTime.MinValue;
        private DateTime _nextBottleAcceptClickUtc = DateTime.MinValue;
        private int _bottlePlacementAttempts;
        private bool _nativeBottleAcceptAttempted;
        private bool _nativeBottleFallbackArmed;

        public SecretBottleProcessingTask()
            : base(
                "SecretBottleProcessingTask",
                "Opens Message in a Bottle rewards and safely keeps or sells them by configured value.") { }

        public override void Start()
        {
            ResetSessionState(true);
            _cycleComplete = false;
            _nextSessionUtc = DateTime.MinValue;
            _cycleSettingsSignature = String.Empty;
            _snapshotCharacter = String.Empty;
        }

        public override void Stop()
        {
            if (_active)
            {
                AllflameLog.Info(
                    "SECRET_BOTTLE_PROCESS_DONE" +
                    "|Opened=" + _opened +
                    "|Kept=" + _kept +
                    "|Sold=" + _sold +
                    "|Failed=" + _failed +
                    "|Fallback=True" +
                    "|Reason=TaskStopped");
            }
            ResetSessionState(true);
            _cycleComplete = false;
            _snapshotCharacter = String.Empty;
        }

        public static bool IsBottleItem(Item item)
        {
            if (item == null)
            {
                return false;
            }
            string name = item.FullName ?? item.Name ?? String.Empty;
            string metadata = item.Metadata ?? String.Empty;
            return name.IndexOf(
                       "Message in a Bottle",
                       StringComparison.OrdinalIgnoreCase) >= 0 ||
                   metadata.IndexOf(
                       "DeepwaterBottledItem",
                       StringComparison.OrdinalIgnoreCase) >= 0 ||
                   metadata.IndexOf(
                       "MessageInABottle",
                       StringComparison.OrdinalIgnoreCase) >= 0;
        }

        public static bool ShouldReserveBottle(Item item)
        {
            return AllflameSettings.Instance.EnableSecretBottleProcessing &&
                   IsBottleItem(item);
        }

        public override async Task<bool> Run()
        {
            AllflameSettings settings = AllflameSettings.Instance;
            string settingsSignature = BottleCycleSettingsSignature(settings);
            string character = LokiPoe.Me == null
                ? String.Empty
                : LokiPoe.Me.Name ?? String.Empty;
            if (!String.Equals(
                    _cycleSettingsSignature,
                    settingsSignature,
                    StringComparison.Ordinal))
            {
                if (!_active)
                {
                    ResetBottleSessionSnapshot("SettingsChanged");
                    _cycleComplete = false;
                    _nextSessionUtc = DateTime.MinValue;
                    _cycleSettingsSignature = settingsSignature;
                }
            }
            if (!_active &&
                !String.IsNullOrWhiteSpace(_snapshotCharacter) &&
                !String.Equals(
                    _snapshotCharacter,
                    character,
                    StringComparison.Ordinal))
            {
                ResetBottleSessionSnapshot("CharacterChanged");
                _cycleComplete = false;
                _nextSessionUtc = DateTime.MinValue;
            }
            bool inHub =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            if (!settings.EnableSecretBottleProcessing ||
                !inHub ||
                !LokiPoe.IsInGame ||
                LokiPoe.Me == null ||
                LokiPoe.Me.IsDead)
            {
                if (_active)
                {
                    FinishSession("ContextChanged", true, 15);
                }
                if (!inHub)
                {
                    _cycleComplete = false;
                    _cycleCompletionPending = false;
                }
                return false;
            }
            if (IsChartDeviceCycleActive())
            {
                AllflameLog.Throttled(
                    "secret_bottle_chart_device_deferred",
                    TimeSpan.FromSeconds(2),
                    "SECRET_BOTTLE_DEFERRED" +
                    "|Reason=ChartDeviceCycleActive" +
                    "|ChartRequested=" +
                    AllflameRunState.ChartRequested +
                    "|NativeUi=" +
                    NativeDeepwaterChartDeviceUi.IsOpened +
                    "|StableUi=" +
                    DeepwaterChartDeviceUi.IsStableWindowOpen +
                    "|Active=" + _active);
                return false;
            }
            if (_cycleComplete)
            {
                return false;
            }
            if (_active &&
                _sessionAreaHash != 0 &&
                _sessionAreaHash != AllflameContext.AreaHash)
            {
                FinishSession("AreaHashChanged", true, 15);
                return false;
            }

            InventoryControlWrapper inventoryControl = MainInventory();
            if (inventoryControl == null)
            {
                return _active;
            }

            List<Item> items = InventoryItems(inventoryControl);
            int bottleCount = BottleQuantity(items);
            int threshold = Math.Max(1, settings.SecretBottlesToOpen);
            int cachedStashBottles = CachedStashBottleQuantity();
            if (!_active && _scanComplete)
            {
                int knownSupply = bottleCount + cachedStashBottles;
                AllflameLog.Info(
                    "SECRET_BOTTLE_SUPPLY" +
                    "|Inventory=" + bottleCount +
                    "|CachedStash=" + cachedStashBottles +
                    "|Combined=" + knownSupply +
                    "|Required=" + threshold +
                    "|SnapshotValid=True");
                if (knownSupply < threshold)
                {
                    _cycleComplete = true;
                    AllflameLog.Info(
                        "SECRET_BOTTLE_SCAN_SKIPPED" +
                        "|Reason=SessionSnapshotValid" +
                        "|CachedStash=" + cachedStashBottles +
                        "|Inventory=" + bottleCount +
                        "|Required=" + threshold +
                        "|Action=ProceedToMap");
                    return false;
                }
            }
            if (!_active)
            {
                if (DateTime.UtcNow < _nextSessionUtc)
                {
                    return false;
                }
                StartSession(bottleCount, threshold);
                LogReservedBottles(items);
                int maximum = Math.Max(
                    1,
                    settings.SecretMaxBottlesPerSession);
                if (!_scanComplete ||
                    (bottleCount < maximum &&
                     cachedStashBottles > 0))
                {
                    _stage = ProcessingStage.Withdraw;
                }
            }

            if (_stage == ProcessingStage.Withdraw)
            {
                if (_waitingForInventorySpace)
                {
                    if (AllflameContext.InventoryFreeSquares <= 0)
                    {
                        return false;
                    }
                    _waitingForInventorySpace = false;
                }
                return await WithdrawBottlesFromStash(
                    settings,
                    bottleCount,
                    threshold);
            }

            if (_stage == ProcessingStage.Opening)
            {
                if (AllflameContext.PlanVoyageVisible ||
                    LokiPoe.InGameState.StashUi.IsOpened ||
                    LokiPoe.InGameState.GuildStashUi.IsOpened ||
                    LokiPoe.InGameState.NpcDialogUi.IsOpened ||
                    LokiPoe.InGameState.SellUi.IsOpened)
                {
                    await Coroutines.CloseBlockingWindows();
                    AllflameLog.Info(
                        "SECRET_BOTTLE_WAIT" +
                        "|Reason=BlockingUiClosed" +
                        "|Action=RetryOpenNextTick");
                    return true;
                }
                int minimumFree = Math.Max(
                    2,
                    settings.SecretBottleMinimumFreeSquares);
                if (AllflameContext.InventoryFreeSquares >= 0 &&
                    AllflameContext.InventoryFreeSquares < minimumFree)
                {
                    AllflameLog.Throttled(
                        "secret_bottle_wait_space",
                        TimeSpan.FromSeconds(2),
                        "SECRET_BOTTLE_WAIT" +
                        "|Reason=InsufficientFreeSquares" +
                        "|Free=" + AllflameContext.InventoryFreeSquares +
                        "|Required=" + minimumFree +
                        "|Action=YieldToStashNonBottleItems");
                    return false;
                }

                if (_bottleOpenStage != BottleOpenStage.Idle)
                {
                    await ContinueBottleOpen(settings);
                    return true;
                }

                Item bottle = items.FirstOrDefault(IsBottleItem);
                int maximum = Math.Max(
                    1,
                    settings.SecretMaxBottlesPerSession);
                if (bottle == null || _opened >= maximum)
                {
                    _cycleCompletionPending = true;
                    _stage = ProcessingStage.FindVendor;
                    return true;
                }
                await BeginBottleOpen(inventoryControl, bottle);
                return true;
            }

            if (_sellLocalIds.Count == 0 &&
                _transferredLocalIds.Count == 0)
            {
                FinishSession("NoLowValueRewards", false, 2);
                return false;
            }

            if (_sellLocalIds.Count == 0 &&
                _transferredLocalIds.Count > 0 &&
                _stage != ProcessingStage.Accept)
            {
                BeginVendorAcceptWait();
            }

            if (_stage == ProcessingStage.FindVendor)
            {
                return await FindAndOpenVendor(settings);
            }
            if (_stage == ProcessingStage.Transfer)
            {
                return await TransferNextSellItem();
            }
            if (_stage == ProcessingStage.Accept)
            {
                return await AcceptVendorTrade();
            }
            return true;
        }

        private void StartSession(int bottleCount, int threshold)
        {
            _active = true;
            _stage = ProcessingStage.Opening;
            _opened = 0;
            _kept = 0;
            _sold = 0;
            _failed = 0;
            _vendorAcceptAttempts = 0;
            _vendor = null;
            _vendorStartedUtc = DateTime.MinValue;
            _vendorAcceptDeadlineUtc = DateTime.MinValue;
            _cycleCompletionPending = false;
            _waitingForInventorySpace = false;
            int maximum = Math.Max(
                1,
                AllflameSettings.Instance.SecretMaxBottlesPerSession);
            _withdrawTarget = _scanComplete
                ? Math.Min(maximum, bottleCount + CachedStashBottleQuantity())
                : 0;
            _sellLocalIds.Clear();
            _transferredLocalIds.Clear();
            _triedNpcIds.Clear();
            _openAttempts.Clear();
            _transferAttempts.Clear();
            _withdrawAttempts.Clear();
            _sessionAreaHash = AllflameContext.AreaHash;
            if (String.IsNullOrWhiteSpace(_snapshotCharacter))
            {
                _snapshotCharacter = LokiPoe.Me == null
                    ? String.Empty
                    : LokiPoe.Me.Name ?? String.Empty;
            }
            _cycleSettingsSignature =
                BottleCycleSettingsSignature(AllflameSettings.Instance);
            AllflameLog.Info(
                "SECRET_BOTTLE_SESSION_START" +
                "|InventoryBottles=" + bottleCount +
                "|Threshold=" + threshold +
                "|MaxOpen=" +
                maximum +
                "|SnapshotValid=" + _scanComplete +
                "|CachedStash=" + CachedStashBottleQuantity() +
                "|KeepMinDivines=" +
                AllflameSettings.Instance.SecretBottleKeepMinDivines
                    .ToString("0.####", System.Globalization.CultureInfo.InvariantCulture));
        }

        private async Task<bool> WithdrawBottlesFromStash(
            AllflameSettings settings,
            int inventoryBottleCount,
            int threshold)
        {
            bool useGuild = settings.SecretBottleUseGuildStash;
            int maximum = Math.Max(
                1,
                settings.SecretMaxBottlesPerSession);
            bool stashOpened = useGuild
                ? LokiPoe.InGameState.GuildStashUi.IsOpened
                : LokiPoe.InGameState.StashUi.IsOpened;
            if (!stashOpened)
            {
                if (AllflameContext.PlanVoyageVisible ||
                    LokiPoe.InGameState.NpcDialogUi.IsOpened ||
                    LokiPoe.InGameState.SellUi.IsOpened ||
                    (useGuild && LokiPoe.InGameState.StashUi.IsOpened) ||
                    (!useGuild && LokiPoe.InGameState.GuildStashUi.IsOpened))
                {
                    await Coroutines.CloseBlockingWindows();
                    return true;
                }
                NetworkObject stash = FindBottleStashObject(useGuild);
                if (stash == null || !stash.IsValid)
                {
                    if (inventoryBottleCount >= threshold)
                    {
                        _withdrawTarget = Math.Min(
                            maximum,
                            inventoryBottleCount);
                        _cycleCompletionPending = true;
                        _stage = ProcessingStage.Opening;
                        return true;
                    }
                    AllflameLog.Throttled(
                        "secret_bottle_stash_missing_" + useGuild,
                        TimeSpan.FromSeconds(3),
                        "SECRET_BOTTLE_STASH" +
                        "|State=Waiting" +
                        "|Reason=StashObjectMissing" +
                        "|Destination=" +
                        (useGuild ? "Guild" : "Personal"));
                    _cycleCompletionPending = true;
                    FinishSession("StashObjectMissing", true, 30);
                    return false;
                }
                await MoveOrInteract(
                    stash,
                    useGuild ? "Bottle Guild Stash" : "Bottle Personal Stash");
                return true;
            }

            if (_bottleTabs.Count == 0)
            {
                List<string> missing;
                List<string> resolved = ResolveBottleStashTabs(
                    settings.SecretBottleStashTab,
                    useGuild,
                    out missing);
                foreach (string tab in resolved)
                {
                    _bottleTabs.Add(new BottleTabSnapshot
                    {
                        Name = tab,
                        Remaining = -1,
                        State = BottleTabState.Unknown
                    });
                }
                AllflameLog.Info(
                    "SECRET_BOTTLE_TABS_RESOLVED" +
                    "|Configured=" +
                    (settings.SecretBottleStashTab ?? String.Empty)
                        .Replace("|", "/") +
                    "|Resolved=" + String.Join(",", resolved) +
                    "|Missing=" + String.Join(",", missing) +
                    "|Destination=" +
                    (useGuild ? "Guild" : "Personal"));
                AllflameLog.Info(
                    "SECRET_BOTTLE_SESSION_SCAN_START" +
                    "|Tabs=" + String.Join(",", resolved) +
                    "|Destination=" +
                    (useGuild ? "Guild" : "Personal") +
                    "|Character=" + _snapshotCharacter);
                if (_bottleTabs.Count == 0)
                {
                    if (inventoryBottleCount >= threshold)
                    {
                        await Coroutines.CloseBlockingWindows();
                        _withdrawTarget = Math.Min(
                            maximum,
                            inventoryBottleCount);
                        _cycleCompletionPending = true;
                        _stage = ProcessingStage.Opening;
                        return true;
                    }
                    await Coroutines.CloseBlockingWindows();
                    _cycleCompletionPending = true;
                    FinishSession("BottleStashTabMissing", true, 60);
                    return false;
                }
            }

            string currentTab = CurrentBottleStashTab(useGuild);
            if (!_scanComplete && _scanIndex < _bottleTabs.Count)
            {
                BottleTabSnapshot scanTab = _bottleTabs[_scanIndex];
                if (!String.Equals(
                        currentTab,
                        scanTab.Name,
                        StringComparison.OrdinalIgnoreCase))
                {
                    bool switched = TrySwitchBottleTab(
                        scanTab,
                        useGuild,
                        "Scan");
                    await LokiCoroutine.Sleep(600);
                    if (!switched &&
                        scanTab.State == BottleTabState.Failed)
                    {
                        _scanIndex++;
                    }
                    return true;
                }

                InventoryControlWrapper scanControl =
                    BottleStashInventoryControl(useGuild);
                int count = BottleQuantity(InventoryItems(scanControl));
                scanTab.Remaining = count;
                scanTab.State = count > 0
                    ? BottleTabState.Available
                    : BottleTabState.Depleted;
                _tabSwitchAttempts.Remove(scanTab.Name);
                AllflameLog.Info(
                    "SECRET_BOTTLE_TAB_SCAN" +
                    "|Tab=" + scanTab.Name +
                    "|Index=" + (_scanIndex + 1) + "/" +
                    _bottleTabs.Count +
                    "|Bottles=" + count +
                    "|State=" + scanTab.State);
                AllflameLog.Info(
                    "SECRET_BOTTLE_SESSION_SNAPSHOT" +
                    "|Tab=" + scanTab.Name +
                    "|Index=" + (_scanIndex + 1) + "/" +
                    _bottleTabs.Count +
                    "|Bottles=" + count +
                    "|State=" + scanTab.State);
                _scanIndex++;
                return true;
            }

            if (!_scanComplete)
            {
                _scanComplete = true;
                _snapshotCharacter = LokiPoe.Me == null
                    ? _snapshotCharacter
                    : LokiPoe.Me.Name ?? String.Empty;
                int stashTotal = _bottleTabs
                    .Where(tab => tab.State == BottleTabState.Available)
                    .Sum(tab => Math.Max(0, tab.Remaining));
                int combinedTotal = inventoryBottleCount + stashTotal;
                _withdrawTarget = Math.Min(maximum, combinedTotal);
                AllflameLog.Info(
                    "SECRET_BOTTLE_SCAN_COMPLETE" +
                    "|Tabs=" + String.Join(
                        ",",
                        _bottleTabs.Select(tab => tab.Name)) +
                    "|Inventory=" + inventoryBottleCount +
                    "|StashTotal=" + stashTotal +
                    "|Combined=" + combinedTotal +
                    "|Required=" + threshold +
                    "|Maximum=" + maximum +
                    "|WithdrawTarget=" + _withdrawTarget);
                if (combinedTotal < threshold)
                {
                    await Coroutines.CloseBlockingWindows();
                    _cycleCompletionPending = true;
                    FinishSession(
                        "CombinedBottleCountBelowThreshold",
                        false,
                        30);
                    return false;
                }
            }

            if (inventoryBottleCount >= _withdrawTarget)
            {
                await Coroutines.CloseBlockingWindows();
                _cycleCompletionPending = true;
                _stage = ProcessingStage.Opening;
                return true;
            }
            if (AllflameContext.InventoryFreeSquares <= 0)
            {
                await Coroutines.CloseBlockingWindows();
                _waitingForInventorySpace = true;
                AllflameLog.Info(
                    "SECRET_BOTTLE_WAIT" +
                    "|Reason=NeedInventorySpaceForBottleWithdrawal" +
                    "|Action=YieldToStashNonBottleItems");
                return false;
            }

            BottleTabSnapshot target = _bottleTabs.FirstOrDefault(tab =>
                tab.State == BottleTabState.Available &&
                tab.Remaining > 0);
            if (target == null)
            {
                await Coroutines.CloseBlockingWindows();
                if (inventoryBottleCount >= threshold)
                {
                    _cycleCompletionPending = true;
                    _stage = ProcessingStage.Opening;
                    return true;
                }
                _cycleCompletionPending = true;
                FinishSession("BottleTabsExhaustedOrFailed", true, 30);
                return false;
            }

            currentTab = CurrentBottleStashTab(useGuild);
            if (!String.Equals(
                    currentTab,
                    target.Name,
                    StringComparison.OrdinalIgnoreCase))
            {
                TrySwitchBottleTab(target, useGuild, "Withdraw");
                await LokiCoroutine.Sleep(600);
                return true;
            }
            _tabSwitchAttempts.Remove(target.Name);

            InventoryControlWrapper stashControl =
                BottleStashInventoryControl(useGuild);
            List<Item> stashItems = InventoryItems(stashControl);
            int stashBottleCount = BottleQuantity(stashItems);
            if (stashBottleCount <= 0)
            {
                UpdateBottleTabCache(
                    target,
                    0,
                    "ConfirmedEmpty");
                return true;
            }

            Item bottle = stashItems.FirstOrDefault(IsBottleItem);
            if (bottle == null)
            {
                UpdateBottleTabCache(
                    target,
                    0,
                    "BottleObjectMissing");
                return true;
            }
            int key = ItemKey(bottle);
            string attemptKey = target.Name + ":" + key;
            int beforeInventory = inventoryBottleCount;
            string fastMoveResult;
            try
            {
                fastMoveResult = stashControl
                    .FastMove(bottle.LocalId)
                    .ToString();
            }
            catch (Exception ex)
            {
                fastMoveResult = "Exception:" + ex.GetType().Name;
            }
            await LokiCoroutine.Sleep(300);
            int afterInventory = BottleQuantity(
                InventoryItems(MainInventory()));
            int remaining = BottleQuantity(
                InventoryItems(stashControl));
            bool moved = afterInventory > beforeInventory;
            int attempts;
            _withdrawAttempts.TryGetValue(attemptKey, out attempts);
            attempts++;
            AllflameLog.Info(
                "SECRET_BOTTLE_STASH_WITHDRAW" +
                "|Tab=" + target.Name +
                "|Attempt=" + attempts +
                "|Result=" + fastMoveResult +
                "|BeforeInventory=" + beforeInventory +
                "|AfterInventory=" + afterInventory +
                "|Remaining=" + remaining +
                "|Confirmed=" + moved);
            if (moved)
            {
                _withdrawAttempts.Remove(attemptKey);
                UpdateBottleTabCache(
                    target,
                    remaining,
                    "ConfirmedWithdraw");
                if (afterInventory >= _withdrawTarget)
                {
                    await Coroutines.CloseBlockingWindows();
                    _cycleCompletionPending = true;
                    _stage = ProcessingStage.Opening;
                }
                return true;
            }
            _withdrawAttempts[attemptKey] = attempts;
            if (attempts >= 3)
            {
                _withdrawAttempts.Remove(attemptKey);
                target.State = BottleTabState.Failed;
                AllflameLog.Info(
                    "SECRET_BOTTLE_TAB_CACHE" +
                    "|Tab=" + target.Name +
                    "|Previous=" + target.Remaining +
                    "|Remaining=" + remaining +
                    "|State=Failed" +
                    "|Source=WithdrawalRejectedThreeTimes" +
                    "|Action=TryNextTab");
            }
            return true;
        }

        private async Task BeginBottleOpen(
            InventoryControlWrapper inventoryControl,
            Item bottle)
        {
            _activeBottleKey = ItemKey(bottle);
            _activeBottleBeforeStack = Math.Max(1, bottle.StackCount);
            _activeBottleBefore = SnapshotInventory(
                InventoryItems(inventoryControl));
            _activeBottleUseResult = await RightClickBottle(
                inventoryControl,
                bottle);
            _bottleStageDeadlineUtc = DateTime.UtcNow.AddSeconds(3);
            _bottleOpenStage = BottleOpenStage.ConfirmConsumed;
            AllflameLog.Info(
                "SECRET_BOTTLE_OPEN_ISSUED" +
                "|BottleKey=" + _activeBottleKey +
                "|BeforeStack=" + _activeBottleBeforeStack +
                "|Result=" + _activeBottleUseResult +
                "|Action=ConfirmOnNextCycle" +
                "|OneActionPerCycle=True");
        }

        private async Task ContinueBottleOpen(
            AllflameSettings settings)
        {
            if (_bottleOpenStage == BottleOpenStage.ConfirmConsumed)
            {
                List<Item> items = InventoryItems(MainInventory());
                Item remainingBottle = items.FirstOrDefault(item =>
                    IsBottleItem(item) &&
                    ItemKey(item) == _activeBottleKey);
                bool consumed = remainingBottle == null ||
                    Math.Max(1, remainingBottle.StackCount) <
                    _activeBottleBeforeStack;
                if (!consumed &&
                    DateTime.UtcNow < _bottleStageDeadlineUtc)
                {
                    return;
                }
                if (!consumed)
                {
                    int attempts;
                    _openAttempts.TryGetValue(
                        _activeBottleKey,
                        out attempts);
                    attempts++;
                    _openAttempts[_activeBottleKey] = attempts;
                    AllflameLog.Info(
                        "SECRET_BOTTLE_OPEN" +
                        "|Attempt=" + attempts +
                        "|Consumed=False" +
                        "|Result=" + _activeBottleUseResult +
                        "|Action=" +
                        (attempts >= 3
                            ? "GiveUpSession"
                            : "Retry"));
                    ClearBottleOpenState();
                    if (attempts >= 3)
                    {
                        _failed++;
                        _cycleCompletionPending = true;
                        _stage = ProcessingStage.FindVendor;
                        _nextSessionUtc =
                            DateTime.UtcNow.AddSeconds(30);
                    }
                    return;
                }

                _openAttempts.Remove(_activeBottleKey);
                _opened++;
                _activePlacement = new RewardPlacementResult
                {
                    Status = "AcceptOrCursorNotDetected",
                    Column = -1,
                    Row = -1
                };
                _bottleStageDeadlineUtc = DateTime.UtcNow.AddSeconds(
                    Math.Max(
                        3,
                        Math.Min(
                            30,
                            settings.SecretBottleRevealTimeoutSeconds)));
                _nextBottleAcceptClickUtc = DateTime.MinValue;
                _bottleOpenStage = BottleOpenStage.AwaitCursor;
                AllflameLog.Info(
                    "SECRET_BOTTLE_OPEN" +
                    "|Consumed=True" +
                    "|Result=" + _activeBottleUseResult +
                    "|Action=AwaitRewardCursor" +
                    "|OneActionPerCycle=True");
                return;
            }

            if (_bottleOpenStage == BottleOpenStage.AwaitCursor)
            {
                Item cursorItem =
                    LokiPoe.InGameState.CursorItemOverlay.Item;
                Vector2i cursorSize =
                    LokiPoe.InGameState.CursorItemOverlay.ItemSize;
                bool cursorReady =
                    IsBottleRewardCursorOpen() &&
                    cursorItem != null &&
                    cursorSize.X > 0 && cursorSize.Y > 0;
                if (cursorReady)
                {
                    if (_nativeBottleFallbackArmed)
                    {
                        AllflameLog.Info(
                            "SECRET_BOTTLE_ACCEPT_NATIVE_ACK" +
                            "|Postcondition=True" +
                            "|Mode=CursorItemOverlay" +
                            "|CursorMode=OpenBottledItem");
                    }
                    _nativeBottleAcceptAttempted = false;
                    _nativeBottleFallbackArmed = false;
                    _activePlacement.Decision =
                        EvaluateReward(cursorItem, settings);
                    _bottlePlacementAttempts = 0;
                    _bottleOpenStage = BottleOpenStage.PlaceCursor;
                    return;
                }
                if (DateTime.UtcNow >= _bottleStageDeadlineUtc)
                {
                    AllflameLog.Info(
                        "SECRET_BOTTLE_TIMEOUT" +
                        "|Stage=RevealOrAccept" +
                        "|RewardUi=" + DescribeBottleRewardUi() +
                        "|NextAction=ControlledStop");
                    AllflameStopController.Stop(
                        "SecretBottleRevealStuck",
                        "Bottle consumed but reward cursor did not appear.");
                    ClearBottleOpenState();
                    return;
                }

                if (settings.UseNativeBottleReveal &&
                    !_nativeBottleAcceptAttempted)
                {
                    bool nativeRevealOpened;
                    InventoryControlWrapper nativeRevealControl;
                    string nativeRevealReason;
                    if (DpbNativeApi.TryCaptureBottleReveal(
                            out nativeRevealOpened,
                            out nativeRevealControl,
                            out nativeRevealReason) &&
                        nativeRevealOpened)
                    {
                        _nativeBottleAcceptAttempted = true;
                        DpbActionResult nativeAccept =
                            DpbNativeApi.AcceptBottleReveal();
                        AllflameLog.Info(
                            "SECRET_BOTTLE_ACCEPT_NATIVE" +
                            "|InputSent=" + nativeAccept.InputSent +
                            "|Postcondition=False" +
                            "|Reason=" + nativeAccept.Reason +
                            "|Snapshot=" + nativeRevealReason +
                            "|Control=" +
                            (nativeRevealControl != null));
                        if (nativeAccept.InputSent)
                        {
                            _nativeBottleFallbackArmed = true;
                            _nextBottleAcceptClickUtc =
                                DateTime.UtcNow.AddMilliseconds(600);
                            return;
                        }
                        AllflameLog.Info(
                            "UI_FALLBACK" +
                            "|Task=" + Name +
                            "|From=Native" +
                            "|To=ElementOrVisual" +
                            "|Reason=" + nativeAccept.Reason);
                    }
                }
                if (_nativeBottleFallbackArmed)
                {
                    _nativeBottleFallbackArmed = false;
                    AllflameLog.Info(
                        "UI_FALLBACK" +
                        "|Task=" + Name +
                        "|From=Native" +
                        "|To=ElementOrVisual" +
                        "|Reason=RewardCursorNotObservedAfterAccept");
                }

                Vector2i acceptLocation;
                long revealAddress;
                int visited;
                string topology;
                bool foundByElement =
                    TryFindBottleRevealAcceptButton(
                        out acceptLocation,
                        out revealAddress,
                        out visited,
                        out topology);
                double correlation = -1d;
                bool found = foundByElement;
                string source = foundByElement
                    ? "ElementTree"
                    : "None";
                if (!found)
                {
                    found = TryFindAcceptButton(
                        out acceptLocation,
                        out correlation);
                    source = found ? "ImageFallback" : "None";
                }
                AllflameLog.Throttled(
                    "secret_bottle_accept_incremental",
                    TimeSpan.FromSeconds(1),
                    "SECRET_BOTTLE_ACCEPT" +
                    "|Found=" + found +
                    "|Source=" + source +
                    "|Correlation=" + correlation.ToString("0.000") +
                    "|Visited=" + visited +
                    "|OneActionPerCycle=True");
                if (found &&
                    DateTime.UtcNow >= _nextBottleAcceptClickUtc)
                {
                    _nextBottleAcceptClickUtc =
                        DateTime.UtcNow.AddMilliseconds(600);
                    LokiPoe.ProcessHookManager.ClearAllKeyStates();
                    DreamPoeBot.BotFramework.MouseManager
                        .SetMousePosition(
                            acceptLocation,
                            foundByElement);
                    await LokiCoroutine.Sleep(25);
                    DreamPoeBot.BotFramework.MouseManager
                        .ClickLMB(0, 0);
                }
                return;
            }

            if (_bottleOpenStage == BottleOpenStage.PlaceCursor)
            {
                Item cursorItem =
                    LokiPoe.InGameState.CursorItemOverlay.Item;
                Vector2i cursorSize =
                    LokiPoe.InGameState.CursorItemOverlay.ItemSize;
                InventoryControlWrapper inventoryControl =
                    MainInventory();
                if (!IsBottleRewardCursorOpen() ||
                    cursorItem == null || cursorSize.X <= 0 ||
                    cursorSize.Y <= 0 || inventoryControl == null ||
                    inventoryControl.Inventory == null ||
                    inventoryControl.InventorySlotUiElement == null)
                {
                    return;
                }
                int maximumAttempts = Math.Max(
                    1,
                    Math.Min(
                        5,
                        settings.SecretBottleCursorPlacementRetries));
                if (_bottlePlacementAttempts >= maximumAttempts)
                {
                    AllflameStopController.Stop(
                        "SecretBottleCursorStuck",
                        "Could not place bottle reward after " +
                        maximumAttempts + " attempts.");
                    ClearBottleOpenState();
                    return;
                }
                int column;
                int row;
                if (!inventoryControl.Inventory.CanFitItem(
                        cursorSize,
                        out column,
                        out row))
                {
                    AllflameStopController.Stop(
                        "SecretBottleCursorStuck",
                        "No inventory space for bottle reward " +
                        cursorSize.X + "x" + cursorSize.Y + ".");
                    ClearBottleOpenState();
                    return;
                }
                Vector2i slotLocation =
                    inventoryControl.InventorySlotUiElement
                        .SlotClickLocation(
                            new Vector2i(column + 1, row + 1));
                _bottlePlacementAttempts++;
                _activePlacement.Column = column;
                _activePlacement.Row = row;
                LokiPoe.ProcessHookManager.ClearAllKeyStates();
                DreamPoeBot.BotFramework.MouseManager
                    .SetMousePosition(slotLocation, true);
                await LokiCoroutine.Sleep(25);
                DreamPoeBot.BotFramework.MouseManager.ClickLMB(0, 0);
                _bottleStageDeadlineUtc =
                    DateTime.UtcNow.AddSeconds(1);
                _bottleOpenStage =
                    BottleOpenStage.ConfirmPlacement;
                AllflameLog.Info(
                    "SECRET_BOTTLE_CURSOR_PLACE" +
                    "|Attempt=" + _bottlePlacementAttempts +
                    "|Maximum=" + maximumAttempts +
                    "|Slot=" + column + "," + row +
                    "|Confirmed=False" +
                    "|Action=ConfirmOnNextCycle" +
                    "|OneActionPerCycle=True");
                return;
            }

            if (_bottleOpenStage ==
                BottleOpenStage.ConfirmPlacement)
            {
                bool placed =
                    !IsBottleRewardCursorOpen();
                if (!placed &&
                    DateTime.UtcNow < _bottleStageDeadlineUtc)
                {
                    return;
                }
                if (!placed)
                {
                    _bottleOpenStage = BottleOpenStage.PlaceCursor;
                    return;
                }
                _activePlacement.Status =
                    "Placed:" + _activePlacement.Column + "," +
                    _activePlacement.Row;
                _bottleStageDeadlineUtc =
                    DateTime.UtcNow.AddSeconds(1);
                _bottleOpenStage =
                    BottleOpenStage.ResolvePlacedItem;
                return;
            }

            if (_bottleOpenStage ==
                BottleOpenStage.ResolvePlacedItem)
            {
                _activePlacement.PlacedItem = FindInventoryItemAt(
                    _activePlacement.Column,
                    _activePlacement.Row);
                if (_activePlacement.PlacedItem == null &&
                    DateTime.UtcNow < _bottleStageDeadlineUtc)
                {
                    return;
                }
                FinalizeBottleReward(settings);
                ClearBottleOpenState();
            }
        }

        private void FinalizeBottleReward(
            AllflameSettings settings)
        {
            RewardPlacementResult placement = _activePlacement ??
                new RewardPlacementResult
                {
                    Status = "PlacementUnavailable",
                    Column = -1,
                    Row = -1
                };
            Dictionary<int, ItemSnapshot> before =
                _activeBottleBefore ??
                new Dictionary<int, ItemSnapshot>();
            string rewardResult = placement.Status ?? String.Empty;
            List<Item> afterItems = InventoryItems(MainInventory());
            List<Item> newItems = afterItems
                .Where(item =>
                    item != null &&
                    item.IsValid &&
                    !IsBottleItem(item) &&
                    !before.ContainsKey(ItemKey(item)))
                .ToList();
            List<Item> increasedStacks = afterItems
                .Where(item =>
                {
                    ItemSnapshot old;
                    return item != null &&
                           item.IsValid &&
                           !IsBottleItem(item) &&
                           before.TryGetValue(ItemKey(item), out old) &&
                           Math.Max(1, item.StackCount) > old.StackCount;
                })
                .ToList();
            List<Item> replacedItems = afterItems
                .Where(item =>
                {
                    ItemSnapshot old;
                    if (item == null ||
                        !item.IsValid ||
                        IsBottleItem(item) ||
                        !before.TryGetValue(ItemKey(item), out old))
                    {
                        return false;
                    }
                    string name = item.FullName ?? item.Name ?? String.Empty;
                    string metadata = item.Metadata ?? String.Empty;
                    return !String.Equals(
                               name,
                               old.Name,
                               StringComparison.OrdinalIgnoreCase) ||
                           !String.Equals(
                               metadata,
                               old.Metadata,
                               StringComparison.OrdinalIgnoreCase);
                })
                .ToList();

            foreach (Item replaced in replacedItems)
            {
                if (!newItems.Any(item =>
                        ItemKey(item) == ItemKey(replaced)))
                {
                    newItems.Add(replaced);
                }
            }

            AllflameLog.Info(
                "SECRET_BOTTLE_OPEN" +
                "|Attempt=1" +
                "|Consumed=True" +
                "|Result=" + _activeBottleUseResult +
                "|Reward=" + rewardResult +
                "|NewItems=" + newItems.Count +
                "|MergedStacks=" + increasedStacks.Count +
                "|ReplacedItems=" + replacedItems.Count);

            if (!rewardResult.StartsWith(
                    "Placed:",
                    StringComparison.OrdinalIgnoreCase) &&
                newItems.Count == 0 &&
                increasedStacks.Count == 0)
            {
                _failed++;
                if (IsBottleRewardCursorOpen())
                {
                    AllflameStopController.Stop(
                        "SecretBottleCursorStuck",
                        "Reward remained on cursor after " + rewardResult);
                }
                _cycleCompletionPending = true;
                _stage = ProcessingStage.FindVendor;
                AllflameLog.Info(
                    "SECRET_BOTTLE_REWARD" +
                    "|Detection=Failed" +
                    "|Result=" + rewardResult +
                    "|Action=StopOpeningToProtectCursorItem");
                return;
            }

            Item decisionItem = placement.PlacedItem;
            int decisionKey = 0;
            if (decisionItem == null &&
                placement.Decision != null &&
                newItems.Count == 1)
            {
                decisionItem = newItems[0];
            }
            if (decisionItem != null && placement.Decision != null)
            {
                ApplyRewardDecision(
                    decisionItem,
                    placement.Decision,
                    "CursorBeforePlacement");
                decisionKey = ItemKey(decisionItem);
                newItems.RemoveAll(item => ItemKey(item) == decisionKey);
            }

            foreach (Item mergedReward in increasedStacks)
            {
                int mergedKey = ItemKey(mergedReward);
                if (mergedKey == decisionKey)
                {
                    continue;
                }
                ItemSnapshot old;
                int rewardQuantity =
                    before.TryGetValue(mergedKey, out old)
                        ? Math.Max(
                            1,
                            Math.Max(1, mergedReward.StackCount) -
                            old.StackCount)
                        : 1;
                AllflamePriceQuote mergedQuote =
                    AllflamePrices.Quote(mergedReward);
                mergedQuote.Quantity = rewardQuantity;
                AllflameNotifications.SendSecretBottleReward(
                    mergedQuote,
                    mergedReward.Rarity.ToString(),
                    "Keep",
                    "MergedExistingStack");
            }

            if (newItems.Count == 0 && decisionItem == null)
            {
                _kept += Math.Max(1, increasedStacks.Count);
                AllflameLog.Info(
                    "SECRET_BOTTLE_REWARD" +
                    "|Detection=AmbiguousOrMerged" +
                    "|Decision=Keep" +
                    "|Reason=NoUniqueNewLocalId");
                return;
            }

            if (placement.Decision != null && decisionItem == null)
            {
                _kept++;
                AllflameLog.Info(
                    "SECRET_BOTTLE_REWARD" +
                    "|Detection=CursorPricedButPlacementAmbiguous" +
                    "|Decision=Keep" +
                    "|Reason=PlacedLocalIdNotResolved");
            }

            foreach (Item reward in newItems)
            {
                ClassifyReward(reward, settings);
            }
            if (increasedStacks.Count > 0)
            {
                _kept += increasedStacks.Count;
                AllflameLog.Info(
                    "SECRET_BOTTLE_REWARD" +
                    "|Detection=MergedExistingStack" +
                    "|Count=" + increasedStacks.Count +
                    "|Decision=Keep" +
                    "|Reason=DoNotSellPreExistingStack");
            }
        }

