        private static bool TryFindBottleRevealAcceptButton(
            out Vector2i clientLocation,
            out long revealAddress,
            out int visited,
            out string topology)
        {
            clientLocation = new Vector2i();
            revealAddress = 0;
            visited = 0;
            topology = "None";
            try
            {
                List<Element> roots = LokiPoe.GetGuiElements();
                if (roots == null)
                {
                    return false;
                }

                var queue = new Queue<Element>(roots.Where(root => root != null));
                var addresses = new HashSet<long>();
                Element reveal = null;
                while (queue.Count > 0 &&
                       visited < MaximumRevealUiElements)
                {
                    Element element = queue.Dequeue();
                    long address;
                    try
                    {
                        address = element.Address;
                    }
                    catch
                    {
                        continue;
                    }
                    if (address == 0 || !addresses.Add(address))
                    {
                        continue;
                    }
                    visited++;
                    string idLabel;
                    try
                    {
                        idLabel = element.IdLabel ?? String.Empty;
                    }
                    catch
                    {
                        idLabel = String.Empty;
                    }
                    if (String.Equals(
                            idLabel,
                            BottleRevealIdLabel,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        reveal = element;
                        revealAddress = address;
                        break;
                    }

                    List<Element> children;
                    try
                    {
                        children = element.Children;
                    }
                    catch
                    {
                        children = null;
                    }
                    if (children == null)
                    {
                        continue;
                    }
                    foreach (Element child in children)
                    {
                        if (child != null)
                        {
                            queue.Enqueue(child);
                        }
                    }
                }

                if (reveal == null || !reveal.IsValid || !reveal.IsVisible)
                {
                    return false;
                }

                topology = DescribeRevealChildren(reveal);
                var revealQueue = new Queue<Element>();
                var revealAddresses = new HashSet<long>();
                revealQueue.Enqueue(reveal);
                while (revealQueue.Count > 0 &&
                       revealAddresses.Count < 256)
                {
                    Element element = revealQueue.Dequeue();
                    long address;
                    try
                    {
                        address = element.Address;
                    }
                    catch
                    {
                        continue;
                    }
                    if (address == 0 || !revealAddresses.Add(address))
                    {
                        continue;
                    }

                    string text = element.Text ?? String.Empty;
                    string idLabel = element.IdLabel ?? String.Empty;
                    bool acceptCandidate =
                        String.Equals(
                            text.Trim(),
                            "ACCEPT",
                            StringComparison.OrdinalIgnoreCase) ||
                        idLabel.IndexOf(
                            "accept",
                            StringComparison.OrdinalIgnoreCase) >= 0;
                    if (acceptCandidate)
                    {
                        Element clickable = ResolveClickableAcceptElement(
                            element,
                            revealAddress);
                        if (clickable != null)
                        {
                            clientLocation = clickable.CenterClickLocation();
                            return true;
                        }
                    }

                    List<Element> children;
                    try
                    {
                        children = element.Children;
                    }
                    catch
                    {
                        children = null;
                    }
                    if (children == null)
                    {
                        continue;
                    }
                    foreach (Element child in children)
                    {
                        if (child != null)
                        {
                            revealQueue.Enqueue(child);
                        }
                    }
                }
                return false;
            }
            catch (Exception ex)
            {
                topology = "Error:" + ex.GetType().Name;
                return false;
            }
        }

        private static Element ResolveClickableAcceptElement(
            Element candidate,
            long revealAddress)
        {
            Element current = candidate;
            for (int depth = 0; current != null && depth < 5; depth++)
            {
                try
                {
                    if (current.IsValid &&
                        current.IsVisible &&
                        current.IsEnable &&
                        current.Width >= 20f &&
                        current.Height >= 8f)
                    {
                        return current;
                    }
                    if (current.Address == revealAddress)
                    {
                        break;
                    }
                    current = current.Parent;
                }
                catch
                {
                    return null;
                }
            }
            return null;
        }

        private static string DescribeRevealChildren(Element reveal)
        {
            try
            {
                List<Element> children = reveal.Children;
                if (children == null || children.Count == 0)
                {
                    return "0";
                }
                return String.Join(
                    ";",
                    children.Take(12).Select((child, index) =>
                    {
                        if (child == null)
                        {
                            return index + ":null";
                        }
                        try
                        {
                            return index + ":" +
                                (child.IdLabel ?? String.Empty)
                                    .Replace("|", "/") + "," +
                                (child.Text ?? String.Empty)
                                    .Replace("|", "/") + "," +
                                child.ControlType + "," +
                                child.Width.ToString("0") + "x" +
                                child.Height.ToString("0") + "," +
                                child.IsVisible + "," + child.IsEnable;
                        }
                        catch
                        {
                            return index + ":Transient";
                        }
                    }).ToArray());
            }
            catch (Exception ex)
            {
                return "Error:" + ex.GetType().Name;
            }
        }

        private static string DescribeBottleRewardUi()
        {
            try
            {
                bool opened = LokiPoe.InGameState.RewardUi.IsOpened;
                List<InventoryControlWrapper> controls = opened
                    ? LokiPoe.InGameState.RewardUi.InventoryControls
                    : null;
                int itemCount = controls == null
                    ? 0
                    : controls.Sum(control =>
                        control == null ||
                        !control.IsValid ||
                        control.Inventory == null ||
                        control.Inventory.Items == null
                            ? 0
                            : control.Inventory.Items.Count(item =>
                                item != null && item.IsValid));
                return "Opened:" + opened +
                    ",Controls:" + (controls == null ? 0 : controls.Count) +
                    ",Items:" + itemCount;
            }
            catch (Exception ex)
            {
                return "Error:" + ex.GetType().Name;
            }
        }

        private static Item FindInventoryItemAt(int column, int row)
        {
            return InventoryItems(MainInventory()).FirstOrDefault(item =>
                item != null &&
                item.IsValid &&
                item.LocationTopLeft.X == column &&
                item.LocationTopLeft.Y == row);
        }

        private static bool TryFindAcceptButton(
            out Vector2i clientLocation,
            out double bestCorrelation)
        {
            clientLocation = new Vector2i();
            bestCorrelation = -1.0;
            try
            {
                var client = LokiPoe.ClientWindowInfo.Client;
                int width = client.Right - client.Left;
                int height = client.Bottom - client.Top;
                if (width < 700 || height < 500 ||
                    AcceptTemplate.Length !=
                        AcceptTemplateWidth * AcceptTemplateHeight)
                {
                    return false;
                }

                using (var screenshot = new System.Drawing.Bitmap(
                    width,
                    height,
                    System.Drawing.Imaging.PixelFormat.Format24bppRgb))
                {
                    using (System.Drawing.Graphics graphics =
                        System.Drawing.Graphics.FromImage(screenshot))
                    {
                        graphics.CopyFromScreen(
                            client.Left,
                            client.Top,
                            0,
                            0,
                            new System.Drawing.Size(width, height),
                            System.Drawing.CopyPixelOperation.SourceCopy);
                    }

                    var rectangle = new System.Drawing.Rectangle(
                        0,
                        0,
                        width,
                        height);
                    System.Drawing.Imaging.BitmapData data =
                        screenshot.LockBits(
                            rectangle,
                            System.Drawing.Imaging.ImageLockMode.ReadOnly,
                            System.Drawing.Imaging.PixelFormat.Format24bppRgb);
                    try
                    {
                        int stride = Math.Abs(data.Stride);
                        byte[] pixels = new byte[stride * height];
                        System.Runtime.InteropServices.Marshal.Copy(
                            data.Scan0,
                            pixels,
                            0,
                            pixels.Length);

                        double baseScale = Math.Max(
                            0.75,
                            Math.Min(1.60, height / 600.0));
                        double[] scales =
                        {
                            baseScale * 0.80,
                            baseScale * 0.90,
                            baseScale,
                            baseScale * 1.10,
                            baseScale * 1.20,
                            1.0
                        };
                        int searchLeft = (int)(width * 0.27);
                        int searchRight = (int)(width * 0.68);
                        int searchTop = (int)(height * 0.50);
                        int searchBottom = (int)(height * 0.82);
                        int bestX = 0;
                        int bestY = 0;
                        int bestWidth = 0;
                        int bestHeight = 0;

                        foreach (double rawScale in scales.Distinct())
                        {
                            double scale = Math.Max(
                                0.65,
                                Math.Min(1.85, rawScale));
                            int scaledWidth = Math.Max(
                                20,
                                (int)Math.Round(
                                    AcceptTemplateWidth * scale));
                            int scaledHeight = Math.Max(
                                8,
                                (int)Math.Round(
                                    AcceptTemplateHeight * scale));
                            int maxX = Math.Min(
                                width - scaledWidth,
                                searchRight);
                            int maxY = Math.Min(
                                height - scaledHeight,
                                searchBottom);
                            for (int y = searchTop; y <= maxY; y += 2)
                            {
                                for (int x = searchLeft; x <= maxX; x += 2)
                                {
                                    double correlation =
                                        AcceptCorrelation(
                                            pixels,
                                            stride,
                                            x,
                                            y,
                                            scaledWidth,
                                            scaledHeight);
                                    if (correlation > bestCorrelation)
                                    {
                                        bestCorrelation = correlation;
                                        bestX = x;
                                        bestY = y;
                                        bestWidth = scaledWidth;
                                        bestHeight = scaledHeight;
                                    }
                                }
                            }
                        }

                        if (bestCorrelation < MinimumAcceptCorrelation)
                        {
                            return false;
                        }
                        clientLocation = new Vector2i(
                            bestX + bestWidth / 2,
                            bestY + bestHeight / 2);
                        return true;
                    }
                    finally
                    {
                        screenshot.UnlockBits(data);
                    }
                }
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "SECRET_BOTTLE_ACCEPT" +
                    "|Found=False" +
                    "|Error=" + ex.GetType().Name);
                return false;
            }
        }

        private static double AcceptCorrelation(
            byte[] pixels,
            int stride,
            int left,
            int top,
            int scaledWidth,
            int scaledHeight)
        {
            double imageSum = 0d;
            double imageSquareSum = 0d;
            double cross = 0d;
            int count = AcceptTemplate.Length;
            for (int templateY = 0;
                 templateY < AcceptTemplateHeight;
                 templateY++)
            {
                int imageY = top +
                    templateY * (scaledHeight - 1) /
                    Math.Max(1, AcceptTemplateHeight - 1);
                for (int templateX = 0;
                     templateX < AcceptTemplateWidth;
                     templateX++)
                {
                    int imageX = left +
                        templateX * (scaledWidth - 1) /
                        Math.Max(1, AcceptTemplateWidth - 1);
                    int index = imageY * stride + imageX * 3;
                    double gray =
                        pixels[index] * 0.114 +
                        pixels[index + 1] * 0.587 +
                        pixels[index + 2] * 0.299;
                    double templateValue = AcceptTemplate[
                        templateY * AcceptTemplateWidth + templateX];
                    imageSum += gray;
                    imageSquareSum += gray * gray;
                    cross += gray *
                        (templateValue - AcceptTemplateMean);
                }
            }
            double imageEnergy = imageSquareSum -
                imageSum * imageSum / count;
            if (imageEnergy <= 0.001 || AcceptTemplateEnergy <= 0.001)
            {
                return -1.0;
            }
            return cross /
                Math.Sqrt(imageEnergy * AcceptTemplateEnergy);
        }

        private static async Task<string> RightClickBottle(
            InventoryControlWrapper inventoryControl,
            Item bottle)
        {
            if (inventoryControl == null || bottle == null)
            {
                return "MouseRightClick:InvalidInput";
            }

            try
            {
                var slotUi = inventoryControl.InventorySlotUiElement;
                if (slotUi == null)
                {
                    return "MouseRightClick:InventorySlotUiMissing";
                }

                Element itemElement = null;
                try
                {
                    var elements = slotUi.DictionaryIdElements;
                    if (elements != null &&
                        !elements.TryGetValue(
                            bottle.LocalId,
                            out itemElement))
                    {
                        elements.TryGetValue(
                            bottle.Id,
                            out itemElement);
                    }
                }
                catch
                {
                    itemElement = null;
                }
                if (itemElement == null ||
                    !itemElement.IsValid ||
                    !itemElement.IsVisible)
                {
                    LokiPoe.Input.SimulateKeyEvent('i');
                    await LokiCoroutine.Sleep(250);
                    inventoryControl = MainInventory();
                    slotUi = inventoryControl == null
                        ? null
                        : inventoryControl.InventorySlotUiElement;
                    itemElement = null;
                    try
                    {
                        var refreshedElements = slotUi == null
                            ? null
                            : slotUi.DictionaryIdElements;
                        if (refreshedElements != null &&
                            !refreshedElements.TryGetValue(
                                bottle.LocalId,
                                out itemElement))
                        {
                            refreshedElements.TryGetValue(
                                bottle.Id,
                                out itemElement);
                        }
                    }
                    catch
                    {
                        itemElement = null;
                    }
                }

                if (slotUi == null)
                {
                    return "MouseRightClick:InventoryOpenFailed";
                }

                Vector2i clickLocation =
                    itemElement != null &&
                    itemElement.IsValid &&
                    itemElement.IsVisible
                        ? itemElement.CenterClickLocation()
                        : slotUi.SlotClickLocation(
                            new Vector2i(
                                bottle.LocationTopLeft.X + 1,
                                bottle.LocationTopLeft.Y + 1));

                LokiPoe.ProcessHookManager.ClearAllKeyStates();
                DreamPoeBot.BotFramework.MouseManager.SetMousePosition(
                    clickLocation,
                    true);
                await LokiCoroutine.Sleep(25);
                DreamPoeBot.BotFramework.MouseManager.ClickRMB(0, 0);
                await LokiCoroutine.Sleep(100);
                return "MouseRightClick:Sent";
            }
            catch (Exception ex)
            {
                return "MouseRightClick:Exception:" + ex.GetType().Name;
            }
        }

        private void ClassifyReward(Item reward, AllflameSettings settings)
        {
            ApplyRewardDecision(
                reward,
                EvaluateReward(reward, settings),
                "InventoryDiff");
        }

        private static RewardDecision EvaluateReward(
            Item reward,
            AllflameSettings settings)
        {
            AllflamePriceQuote quote = AllflamePrices.Quote(reward);
            bool fixedPrice = HasFixedPrice(reward, settings.FixedPrices);
            bool priceFresh =
                AllflamePrices.UpdatedUtc != DateTime.MinValue &&
                DateTime.UtcNow - AllflamePrices.UpdatedUtc <=
                    TimeSpan.FromHours(
                        Math.Max(24, settings.PriceUpdateHours * 2));
            bool trustedPrice = quote.IsPriced && (fixedPrice || priceFresh);
            string rarity = reward == null
                ? String.Empty
                : reward.Rarity.ToString();
            bool thresholdEligible = String.Equals(
                rarity,
                "Unique",
                StringComparison.OrdinalIgnoreCase);
            bool sell =
                thresholdEligible &&
                settings.SecretBottleSellLowValue &&
                trustedPrice &&
                quote.TotalDivines <
                    Math.Max(0d, settings.SecretBottleKeepMinDivines);
            return new RewardDecision
            {
                Sell = sell,
                ThresholdEligible = thresholdEligible,
                TrustedPrice = trustedPrice,
                PriceFresh = priceFresh,
                FixedPrice = fixedPrice,
                Rarity = rarity,
                Quote = quote
            };
        }

        private void ApplyRewardDecision(
            Item reward,
            RewardDecision decision,
            string source)
        {
            if (reward == null || decision == null)
            {
                _kept++;
                AllflameLog.Info(
                    "SECRET_BOTTLE_PRICE" +
                    "|Source=" + source +
                    "|Decision=Keep" +
                    "|Reason=RewardOrDecisionMissing");
                return;
            }
            AllflamePriceQuote quote = decision.Quote ??
                new AllflamePriceQuote
                {
                    Name = reward.FullName ?? reward.Name ?? "Unknown",
                    Quantity = Math.Max(1, reward.StackCount)
                };
            int key = ItemKey(reward);
            bool sell = decision.Sell && key != 0;
            if (sell)
            {
                _sellLocalIds.Add(key);
            }
            else
            {
                _kept++;
            }
            AllflameLog.Info(
                "SECRET_BOTTLE_PRICE" +
                "|Source=" + source +
                "|LocalId=" + reward.LocalId +
                "|Name=" + (reward.FullName ?? reward.Name ?? String.Empty) +
                "|Rarity=" + decision.Rarity +
                "|ThresholdEligible=" + decision.ThresholdEligible +
                "|UnitDivines=" +
                quote.UnitDivines.ToString(
                    "0.####",
                    System.Globalization.CultureInfo.InvariantCulture) +
                "|TotalDivines=" +
                quote.TotalDivines.ToString(
                    "0.####",
                    System.Globalization.CultureInfo.InvariantCulture) +
                "|Priced=" + quote.IsPriced +
                "|PriceFresh=" + decision.PriceFresh +
                "|FixedOverride=" + decision.FixedPrice +
                "|Decision=" + (sell ? "Sell" : "Keep") +
                (!decision.ThresholdEligible
                    ? "|Reason=NonUniqueReward"
                    : (!decision.TrustedPrice
                    ? "|Reason=UnpricedOrStale"
                    : (decision.Sell && key == 0
                        ? "|Reason=MissingStableItemId"
                        : String.Empty))));

            AllflameNotifications.SendSecretBottleReward(
                quote,
                decision.Rarity,
                sell ? "Sell" : "Keep",
                source);
        }

        private async Task<bool> FindAndOpenVendor(
            AllflameSettings settings)
        {
            if (!settings.SecretBottleSellLowValue)
            {
                await FallbackToStash("SellingDisabled");
                return false;
            }
            if (LokiPoe.InGameState.SellUi.IsOpened)
            {
                _stage = ProcessingStage.Transfer;
                return true;
            }
            if (LokiPoe.InGameState.NpcDialogUi.IsOpened)
            {
                if (LokiPoe.InGameState.NpcDialogUi.CanConverse(
                        "Sell Items"))
                {
                    string result = LokiPoe.InGameState.NpcDialogUi
                        .SellItems()
                        .ToString();
                    await LokiCoroutine.Sleep(500);
                    bool opened = LokiPoe.InGameState.SellUi.IsOpened;
                    AllflameLog.Info(
                        "SECRET_BOTTLE_VENDOR" +
                        "|Action=OpenSellUi" +
                        "|Npc=" + (_vendor == null ? String.Empty : _vendor.Name) +
                        "|Result=" + result +
                        "|Opened=" + opened);
                    if (opened)
                    {
                        _stage = ProcessingStage.Transfer;
                        return true;
                    }
                }
                if (_vendor != null)
                {
                    _triedNpcIds.Add(_vendor.Id);
                }
                _vendor = null;
                _vendorStartedUtc = DateTime.MinValue;
                await Coroutines.CloseBlockingWindows();
                return true;
            }

            if (_vendor == null || !_vendor.IsValid || !_vendor.IsTargetable)
            {
                if (_triedNpcIds.Count >= 5)
                {
                    await FallbackToStash("VendorCandidateLimitReached");
                    return false;
                }
                _vendor = FindVendorCandidate(settings.SecretBottleVendorName);
                _vendorStartedUtc = DateTime.UtcNow;
                if (_vendor == null)
                {
                    await FallbackToStash("NoVendorWithSellUiFound");
                    return false;
                }
                AllflameLog.Info(
                    "SECRET_BOTTLE_VENDOR" +
                    "|Action=CandidateSelected" +
                    "|Npc=" + _vendor.Name +
                    "|Id=" + _vendor.Id +
                    "|Configured=" +
                    !String.IsNullOrWhiteSpace(settings.SecretBottleVendorName));
            }

            if (DateTime.UtcNow - _vendorStartedUtc >=
                TimeSpan.FromSeconds(12))
            {
                _triedNpcIds.Add(_vendor.Id);
                AllflameLog.Info(
                    "SECRET_BOTTLE_VENDOR" +
                    "|Action=CandidateRejected" +
                    "|Npc=" + _vendor.Name +
                    "|Reason=InteractionTimeout");
                _vendor = null;
                return true;
            }
            await MoveOrInteract(_vendor, "Bottle vendor", 45f);
            return true;
        }

        private async Task<bool> TransferNextSellItem()
        {
            if (!LokiPoe.InGameState.SellUi.IsOpened)
            {
                await FallbackToStash("SellUiClosedBeforeTransfer");
                return false;
            }
            InventoryControlWrapper inventoryControl = MainInventory();
            List<Item> items = InventoryItems(inventoryControl);
            Item item = items.FirstOrDefault(candidate =>
                candidate != null &&
                candidate.IsValid &&
                _sellLocalIds.Contains(ItemKey(candidate)));
            if (item == null)
            {
                BeginVendorAcceptWait();
                return true;
            }

            int key = ItemKey(item);
            int localId = item.LocalId;
            string itemName = item.FullName ?? item.Name ?? String.Empty;
            string result;
            try
            {
                result = inventoryControl.FastMove(localId).ToString();
            }
            catch (Exception ex)
            {
                result = "Exception:" + ex.GetType().Name;
            }
            await LokiCoroutine.Sleep(250);
            bool transferred = FindInventoryItem(key) == null;
            int attempts;
            _transferAttempts.TryGetValue(key, out attempts);
            attempts++;
            AllflameLog.Info(
                "SECRET_BOTTLE_VENDOR" +
                "|Action=Transfer" +
                "|LocalId=" + localId +
                "|Name=" + itemName +
                "|Attempt=" + attempts +
                "|Result=" + result +
                "|Confirmed=" + transferred);
            if (transferred)
            {
                _sellLocalIds.Remove(key);
                _transferredLocalIds.Add(key);
                _transferAttempts.Remove(key);
                if (_sellLocalIds.Count == 0)
                {
                    BeginVendorAcceptWait();
                }
                return true;
            }
            _transferAttempts[key] = attempts;
            if (attempts >= 3)
            {
                await FallbackToStash("TransferRejectedThreeTimes");
                return false;
            }
            return true;
        }

        private async Task<bool> AcceptVendorTrade()
        {
            if (!LokiPoe.InGameState.SellUi.IsOpened)
            {
                await FallbackToStash("SellUiClosedBeforeAccept");
                return false;
            }
            var tradeControl = LokiPoe.InGameState.SellUi.TradeControl;
            string acceptText;
            try
            {
                acceptText = tradeControl.AcceptButtonText ?? String.Empty;
            }
            catch (Exception ex)
            {
                acceptText = "Exception:" + ex.GetType().Name;
            }
            string normalizedAcceptText = acceptText.Trim();
            if (!String.Equals(
                    normalizedAcceptText,
                    "Accept",
                    StringComparison.OrdinalIgnoreCase))
            {
                if (DateTime.UtcNow < _vendorAcceptDeadlineUtc)
                {
                    AllflameLog.Throttled(
                        "secret_bottle_vendor_accept_wait",
                        TimeSpan.FromMilliseconds(500),
                        "SECRET_BOTTLE_VENDOR" +
                        "|Action=WaitForAccept" +
                        "|RawButtonText=" +
                        acceptText.Replace("|", "/") +
                        "|NormalizedButtonText=" +
                        normalizedAcceptText.Replace("|", "/") +
                        "|Items=" + _transferredLocalIds.Count +
                        "|RemainingMilliseconds=" +
                        Math.Max(
                            0,
                            (int)(_vendorAcceptDeadlineUtc - DateTime.UtcNow)
                                .TotalMilliseconds));
                    await LokiCoroutine.Sleep(200);
                    return true;
                }
                await FallbackToStash("VendorAcceptButtonTimeout");
                return false;
            }

            int offerBefore = InventoryItems(
                tradeControl.InventoryControl_YourOffer).Count;
            string result;
            try
            {
                result = tradeControl.Accept(true).ToString();
            }
            catch (Exception ex)
            {
                result = "Exception:" + ex.GetType().Name;
            }
            await LokiCoroutine.Sleep(600);
            _vendorAcceptAttempts++;
            bool sellUiOpened = LokiPoe.InGameState.SellUi.IsOpened;
            int offerAfter = sellUiOpened
                ? InventoryItems(
                    LokiPoe.InGameState.SellUi.TradeControl
                        .InventoryControl_YourOffer).Count
                : 0;
            bool accepted =
                String.Equals(
                    result,
                    "None",
                    StringComparison.OrdinalIgnoreCase) &&
                _transferredLocalIds.Count > 0 &&
                (!sellUiOpened || offerAfter == 0);
            AllflameLog.Info(
                "SECRET_BOTTLE_VENDOR" +
                "|Action=Accept" +
                "|RawButtonText=" +
                acceptText.Replace("|", "/") +
                "|NormalizedButtonText=" +
                normalizedAcceptText.Replace("|", "/") +
                "|Source=DpbTradeControl" +
                "|Attempt=" + _vendorAcceptAttempts +
                "|Maximum=3" +
                "|Items=" + _transferredLocalIds.Count +
                "|OfferBefore=" + offerBefore +
                "|OfferAfter=" + offerAfter +
                "|SellUiOpened=" + sellUiOpened +
                "|Result=" + result +
                "|Confirmed=" + accepted);
            if (!accepted)
            {
                if (_vendorAcceptAttempts < 3 &&
                    LokiPoe.InGameState.SellUi.IsOpened)
                {
                    _vendorAcceptDeadlineUtc =
                        DateTime.UtcNow.AddSeconds(6);
                    await LokiCoroutine.Sleep(400);
                    return true;
                }
                await FallbackToStash("VendorAcceptRejected");
                return false;
            }
            AllflameLog.Info(
                "SECRET_BOTTLE_VENDOR_ACCEPT_CONFIRMED" +
                "|OfferBefore=" + offerBefore +
                "|OfferAfter=" + offerAfter +
                "|SellUiOpened=" + sellUiOpened +
                "|Items=" + _transferredLocalIds.Count +
                "|Result=" + result);
            _sold += _transferredLocalIds.Count;
            await Coroutines.CloseBlockingWindows();
            FinishSession("Completed", false, 2);
            return false;
        }

        private async Task FallbackToStash(string reason)
        {
            try
            {
                if (LokiPoe.InGameState.SellUi.IsOpened)
                {
                    LokiPoe.InGameState.SellUi.TradeControl.Cancel(true);
                    await LokiCoroutine.Sleep(350);
                }
            }
            catch
            {
            }
            await Coroutines.CloseBlockingWindows();
            AllflameLog.Info(
                "SECRET_BOTTLE_FALLBACK" +
                "|Reason=" + reason +
                "|PendingSell=" +
                (_sellLocalIds.Count + _transferredLocalIds.Count) +
                "|Action=KeepAndYieldToNormalStash");
            _kept += _sellLocalIds.Count + _transferredLocalIds.Count;
            FinishSession(reason, true, 30);
        }

        private void FinishSession(
            string reason,
            bool fallback,
            int cooldownSeconds)
        {
            bool completedCycle = _cycleCompletionPending;
            int opened = _opened;
            AllflameLog.Info(
                "SECRET_BOTTLE_PROCESS_DONE" +
                "|Opened=" + _opened +
                "|Kept=" + _kept +
                "|Sold=" + _sold +
                "|Failed=" + _failed +
                "|Fallback=" + fallback +
                "|Reason=" + reason);
            ResetSessionState(false);
            if (completedCycle)
            {
                _cycleComplete = true;
                AllflameLog.Info(
                    "SECRET_BOTTLE_CYCLE_COMPLETE" +
                    "|Opened=" + opened +
                    "|Maximum=" +
                    Math.Max(
                        1,
                        AllflameSettings.Instance
                            .SecretMaxBottlesPerSession) +
                    "|Reason=" + reason +
                    "|Action=ProceedToMap");
            }
            _nextSessionUtc = DateTime.UtcNow.AddSeconds(
                Math.Max(1, cooldownSeconds));
        }

        private void ResetSessionState(bool resetSnapshot = false)
        {
            _active = false;
            ClearBottleOpenState();
            _stage = ProcessingStage.Opening;
            _vendor = null;
            _vendorStartedUtc = DateTime.MinValue;
            _vendorAcceptDeadlineUtc = DateTime.MinValue;
            _cycleCompletionPending = false;
            _waitingForInventorySpace = false;
            _withdrawTarget = 0;
            _sellLocalIds.Clear();
            _transferredLocalIds.Clear();
            _triedNpcIds.Clear();
            _openAttempts.Clear();
            _transferAttempts.Clear();
            _withdrawAttempts.Clear();
            _vendorAcceptAttempts = 0;
            _sessionAreaHash = 0;
            if (resetSnapshot)
            {
                _scanComplete = false;
                _scanIndex = 0;
                _bottleTabs.Clear();
                _tabSwitchAttempts.Clear();
                _snapshotCharacter = String.Empty;
            }
        }

        private void ResetBottleSessionSnapshot(string reason)
        {
            if (_scanComplete || _bottleTabs.Count > 0)
            {
                AllflameLog.Info(
                    "SECRET_BOTTLE_SESSION_SNAPSHOT_RESET" +
                    "|Reason=" + reason +
                    "|Tabs=" + _bottleTabs.Count +
                    "|CachedStash=" + CachedStashBottleQuantity());
            }
            _scanComplete = false;
            _scanIndex = 0;
            _bottleTabs.Clear();
            _tabSwitchAttempts.Clear();
            _snapshotCharacter = String.Empty;
        }

        private int CachedStashBottleQuantity()
        {
            if (!_scanComplete)
            {
                return 0;
            }
            return _bottleTabs
                .Where(tab => tab.State == BottleTabState.Available)
                .Sum(tab => Math.Max(0, tab.Remaining));
        }

        private static bool IsChartDeviceCycleActive()
        {
            if (AllflameRunState.ChartRequested)
            {
                return true;
            }
            try
            {
                return LokiPoe.InGameState.MapDeviceUi.IsOpened ||
                       NativeDeepwaterChartDeviceUi.IsOpened ||
                       DeepwaterChartDeviceUi.IsStableWindowOpen;
            }
            catch
            {
                return false;
            }
        }

        private void BeginVendorAcceptWait()
        {
            _stage = ProcessingStage.Accept;
            if (_vendorAcceptDeadlineUtc == DateTime.MinValue)
            {
                _vendorAcceptDeadlineUtc = DateTime.UtcNow.AddSeconds(6);
            }
        }

        private Npc FindVendorCandidate(string configuredName)
        {
            try
            {
                IEnumerable<Npc> candidates = LokiPoe.ObjectManager.Objects
                    .OfType<Npc>()
                    .Where(npc =>
                        npc != null &&
                        npc.IsValid &&
                        npc.IsTargetable &&
                        !_triedNpcIds.Contains(npc.Id));
                if (!String.IsNullOrWhiteSpace(configuredName))
                {
                    candidates = candidates.Where(npc =>
                        (npc.Name ?? String.Empty).IndexOf(
                            configuredName.Trim(),
                            StringComparison.OrdinalIgnoreCase) >= 0);
                }
                return candidates.OrderBy(npc => npc.Distance).FirstOrDefault();
            }
            catch
            {
                return null;
            }
        }

        private static bool HasFixedPrice(Item item, string source)
        {
            if (item == null || String.IsNullOrWhiteSpace(source))
            {
                return false;
            }
            Dictionary<string, double> fixedPrices =
                AllflamePrices.ParseFixedPrices(source);
            string fullName = item.FullName ?? String.Empty;
            string name = item.Name ?? String.Empty;
            return fixedPrices.Keys.Any(key =>
                String.Equals(
                    key,
                    fullName,
                    StringComparison.OrdinalIgnoreCase) ||
                String.Equals(
                    key,
                    name,
                    StringComparison.OrdinalIgnoreCase));
        }

        private static Dictionary<int, ItemSnapshot> SnapshotInventory(
            IEnumerable<Item> items)
        {
            var output = new Dictionary<int, ItemSnapshot>();
            foreach (Item item in items ?? Enumerable.Empty<Item>())
            {
                if (item == null || !item.IsValid)
                {
                    continue;
                }
                int key = ItemKey(item);
                output[key] = new ItemSnapshot
                {
                    LocalId = item.LocalId,
                    StackCount = Math.Max(1, item.StackCount),
                    Name = item.FullName ?? item.Name ?? String.Empty,
                    Metadata = item.Metadata ?? String.Empty
                };
            }
            return output;
        }

        private static InventoryControlWrapper MainInventory()
        {
            try
            {
                return LokiPoe.InGameState.InventoryUi.InventoryControl_Main;
            }
            catch
            {
                return null;
            }
        }

        private static List<Item> InventoryItems(
            InventoryControlWrapper control)
        {
            try
            {
                return control == null ||
                       control.Inventory == null ||
                       control.Inventory.Items == null
                    ? new List<Item>()
                    : control.Inventory.Items
                        .Where(item => item != null && item.IsValid)
                        .ToList();
            }
            catch
            {
                return new List<Item>();
            }
        }

        private static Item FindInventoryItem(int key)
        {
            return InventoryItems(MainInventory()).FirstOrDefault(item =>
                ItemKey(item) == key);
        }

        private static int BottleQuantity(IEnumerable<Item> items)
        {
            return (items ?? Enumerable.Empty<Item>())
                .Where(IsBottleItem)
                .Sum(item => Math.Max(1, item.StackCount));
        }

        private static NetworkObject FindBottleStashObject(bool guild)
        {
            try
            {
                if (!guild)
                {
                    return AllflameContext.StashObject;
                }
                return LokiPoe.ObjectManager.Objects
                    .Where(obj => obj != null && obj.IsValid)
                    .OrderBy(obj => obj.Distance)
                    .FirstOrDefault(obj =>
                    {
                        string name = obj.Name ?? String.Empty;
                        string metadata = obj.Metadata ?? String.Empty;
                        return name.IndexOf(
                                   "Guild Stash",
                                   StringComparison.OrdinalIgnoreCase) >= 0 ||
                               metadata.IndexOf(
                                   "GuildStash",
                                   StringComparison.OrdinalIgnoreCase) >= 0;
                    });
            }
            catch
            {
                return null;
            }
        }

        private static List<string> ResolveBottleStashTabs(
            string configured,
            bool guild,
            out List<string> missing)
        {
            missing = new List<string>();
            var resolved = new List<string>();
            try
            {
                List<string> available = guild
                    ? LokiPoe.InGameState.GuildStashUi.TabControl.TabNames
                    : LokiPoe.InGameState.StashUi.TabControl.TabNames;
                if (available == null || available.Count == 0)
                {
                    return resolved;
                }
                string[] tokens = (configured ?? String.Empty)
                    .Split(new[] { ',', ';' },
                        StringSplitOptions.RemoveEmptyEntries);
                foreach (string rawToken in tokens)
                {
                    string token = rawToken.Trim();
                    if (String.IsNullOrEmpty(token))
                    {
                        continue;
                    }
                    string exact = available.FirstOrDefault(name =>
                        String.Equals(
                            name,
                            token,
                            StringComparison.OrdinalIgnoreCase));
                    string result = exact;
                    if (String.IsNullOrEmpty(result))
                    {
                        int number;
                        if (Int32.TryParse(token, out number) &&
                            number >= 1 &&
                            number <= available.Count)
                        {
                            result = available[number - 1];
                        }
                    }
                    if (String.IsNullOrEmpty(result))
                    {
                        missing.Add(token);
                        continue;
                    }
                    if (!resolved.Any(tab =>
                            String.Equals(
                                tab,
                                result,
                                StringComparison.OrdinalIgnoreCase)))
                    {
                        resolved.Add(result);
                    }
                }
                return resolved;
            }
            catch
            {
                return resolved;
            }
        }

        private bool TrySwitchBottleTab(
            BottleTabSnapshot tab,
            bool guild,
            string purpose)
        {
            object result = SwitchBottleStashTab(tab.Name, guild);
            bool success;
            try
            {
                success = Convert.ToInt32(result) == 0;
            }
            catch
            {
                success = false;
            }
            int attempts;
            _tabSwitchAttempts.TryGetValue(tab.Name, out attempts);
            attempts++;
            _tabSwitchAttempts[tab.Name] = attempts;
            if (attempts >= 3)
            {
                tab.State = BottleTabState.Failed;
            }
            AllflameLog.Info(
                "SECRET_BOTTLE_STASH" +
                "|Action=SwitchTab" +
                "|Purpose=" + purpose +
                "|Tab=" + tab.Name +
                "|Attempt=" + attempts +
                "|Result=" + result +
                "|Success=" + success +
                "|State=" + tab.State);
            return success && tab.State != BottleTabState.Failed;
        }

        private static string CurrentBottleStashTab(bool guild)
        {
            return guild
                ? LokiPoe.InGameState.GuildStashUi.TabControl.CurrentTabName
                : LokiPoe.InGameState.StashUi.TabControl.CurrentTabName;
        }

        private static InventoryControlWrapper BottleStashInventoryControl(
            bool guild)
        {
            return guild
                ? LokiPoe.InGameState.GuildStashUi.InventoryControl
                : LokiPoe.InGameState.StashUi.InventoryControl;
        }

        private static void UpdateBottleTabCache(
            BottleTabSnapshot tab,
            int remaining,
            string source)
        {
            int previous = tab.Remaining;
            tab.Remaining = Math.Max(0, remaining);
            tab.State = tab.Remaining > 0
                ? BottleTabState.Available
                : BottleTabState.Depleted;
            AllflameLog.Info(
                "SECRET_BOTTLE_TAB_CACHE" +
                "|Tab=" + tab.Name +
                "|Previous=" + previous +
                "|Remaining=" + tab.Remaining +
                "|State=" + tab.State +
                "|Source=" + source);
            AllflameLog.Info(
                "SECRET_BOTTLE_CACHE_ADJUSTED" +
                "|Tab=" + tab.Name +
                "|Before=" + previous +
                "|Withdrawn=" + Math.Max(0, previous - tab.Remaining) +
                "|After=" + tab.Remaining +
                "|Source=" + source);
        }

        private static void LogReservedBottles(IEnumerable<Item> items)
        {
            foreach (Item item in
                (items ?? Enumerable.Empty<Item>()).Where(IsBottleItem))
            {
                AllflameLog.Info(
                    "SECRET_BOTTLE_RESERVED" +
                    "|LocalId=" + item.LocalId +
                    "|Quantity=" + Math.Max(1, item.StackCount) +
                    "|Reason=PendingBottleCycle");
            }
        }

        private static string BottleCycleSettingsSignature(
            AllflameSettings settings)
        {
            return settings.SecretBottleUseGuildStash + "|" +
                (settings.SecretBottleStashTab ?? String.Empty).Trim() + "|" +
                Math.Max(1, settings.SecretBottlesToOpen) + "|" +
                Math.Max(1, settings.SecretMaxBottlesPerSession);
        }

        private static object SwitchBottleStashTab(
            string tabName,
            bool guild)
        {
            if (guild)
            {
                var result = LokiPoe.InGameState.GuildStashUi.TabControl
                    .SwitchToTabMouse(tabName);
                if (Convert.ToInt32(result) != 0)
                {
                    result = LokiPoe.InGameState.GuildStashUi.TabControl
                        .SwitchToTabKeyboard(tabName);
                }
                return result;
            }
            var personalResult = LokiPoe.InGameState.StashUi.TabControl
                .SwitchToTabMouse(tabName);
            if (Convert.ToInt32(personalResult) != 0)
            {
                personalResult = LokiPoe.InGameState.StashUi.TabControl
                    .SwitchToTabKeyboard(tabName);
            }
            return personalResult;
        }

        private static int ItemKey(Item item)
        {
            return item == null
                ? 0
                : (item.LocalId != 0 ? item.LocalId : item.Id);
        }
    }

    internal sealed class StashLootTask : ObserverTask
    {
        private readonly Dictionary<int, int> _attempts =
            new Dictionary<int, int>();
        private List<string> _tabs = new List<string>();
        private bool _active;
        private bool _debug;
        private bool _useGuild;
        private int _tabIndex;
        private DateTime _retryAfterUtc = DateTime.MinValue;
        private DateTime _nextPolicySessionUtc = DateTime.MinValue;
        private string _reason = String.Empty;
        private bool _transferPending;
        private int _pendingItemKey;
        private int _pendingLocalId;
        private Vector2i _pendingLocation;
        private int _pendingBeforeStack;
        private int _pendingTransferDelayMs;
        private string _pendingItemName = String.Empty;
        private string _pendingTab = String.Empty;
        private string _pendingTransferMode = String.Empty;
        private DateTime _transferIssuedUtc = DateTime.MinValue;

        public StashLootTask()
            : base(
                "StashLootTask",
                "Stashes non-Chart inventory items across configured tabs.") { }

        public override async Task<bool> Run()
        {
            AllflameSettings settings = AllflameSettings.Instance;
            bool inHub =
                AllflameContext.Phase == AllflamePhase.SovereignHub ||
                AllflameContext.Phase == AllflamePhase.VoyagePlanning;
            if (!inHub)
            {
                if (_active)
                {
                    Finish(false, "LeftSovereign");
                }
                return false;
            }

            bool inventoryThresholdReached =
                AllflameContext.InventoryFreeSquares >= 0 &&
                AllflameContext.InventoryFreeSquares <= settings.StashWhenFreeSlotsAtOrBelow;
            bool afterCollectPolicy =
                settings.StashAfterCollectLoot &&
                VoyageRunState.SurfaceCollectionCompleted;
            bool preVoyagePolicy =
                settings.StashBeforeVoyage &&
                !AllflameRunState.VoyagePreStashCompleted;

            if (!_active)
            {
                bool debugRequested = AllflameStashDebug.IsRequested;
                if (preVoyagePolicy &&
                    CountNonChartInventoryItems() == 0)
                {
                    AllflameLog.Throttled(
                        "voyage_pre_stash_loot_complete",
                        TimeSpan.FromSeconds(2),
                        "VOYAGE_PRE_STASH|Stage=Loot|State=Complete" +
                        "|Next=ChartTransfer" +
                        "|InventoryCharts=" +
                        AllflameContext.InventoryChartCount);
                    return false;
                }
                if (!debugRequested &&
                    (!preVoyagePolicy &&
                     (!settings.EnableStashing ||
                     (!inventoryThresholdReached &&
                      !afterCollectPolicy) ||
                     DateTime.UtcNow < _nextPolicySessionUtc ||
                     CountNonChartInventoryItems() == 0)))
                {
                    return false;
                }

                _active = true;
                _debug = debugRequested;
                _useGuild = settings.UseGuildStash;
                _tabIndex = 0;
                _attempts.Clear();
                _tabs.Clear();
                ResetPendingTransfer();
                _reason = _debug
                    ? "DebugButton"
                    : (preVoyagePolicy
                        ? "BeforeVoyage"
                        : (afterCollectPolicy
                        ? "AfterCollectLoot"
                        : "InventoryThreshold"));
                AllflameLog.Info(
                    "STASH_SESSION_START|Reason=" + _reason +
                    "|Destination=" +
                    (_useGuild ? "Guild" : "Personal") +
                    "|ConfiguredTabs=" +
                    (_useGuild
                        ? settings.GuildLootTabs
                        : settings.PersonalLootTabs) +
                    "|InventoryItems=" +
                    AllflameContext.InventoryItemCount +
                    "|InventoryCharts=" +
                    AllflameContext.InventoryChartCount);
            }

            if (DateTime.UtcNow < _retryAfterUtc)
            {
                return true;
            }

            if (String.Equals(
                    _reason,
                    "BeforeVoyage",
                    StringComparison.Ordinal) &&
                AllflameContext.PlanVoyageVisible)
            {
                await Coroutines.CloseBlockingWindows();
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(350);
                AllflameLog.Info(
                    "VOYAGE_PRE_STASH|State=ClosePlanningUi" +
                    "|Action=OpenStashNext");
                return true;
            }

            if (!IsStashOpened())
            {
                NetworkObject stash = FindStashObject(_useGuild);
                if (stash == null || !stash.IsValid)
                {
                    AllflameLog.Throttled(
                        "stash_object_missing_" + _useGuild,
                        TimeSpan.FromSeconds(3),
                        "STASH_WAIT|Reason=StashObjectMissing" +
                        "|Destination=" +
                        (_useGuild ? "Guild" : "Personal"));
                    return true;
                }

                if (stash.Distance > settings.InteractDistance)
                {
                    await MoveOrInteract(
                        stash,
                        _useGuild ? "Guild Stash" : "Personal Stash");
                    return true;
                }

                bool opened = await InteractWithRecovery(stash);
                _retryAfterUtc = DateTime.UtcNow.AddMilliseconds(
                    opened ? 300 : 350);
                AllflameLog.Info(
                    "STASH_OPEN|Destination=" +
                    (_useGuild ? "Guild" : "Personal") +
                    "|Success=" + opened +
                    "|Object=" + stash.Name);
                return true;
            }

            if (_tabs.Count == 0)
            {
                _tabs = ResolveConfiguredTabs(
                    _useGuild
                        ? settings.GuildLootTabs
                        : settings.PersonalLootTabs);
                if (_tabs.Count == 0)
                {
                    bool beforeVoyage = String.Equals(
                        _reason,
                        "BeforeVoyage",
                        StringComparison.Ordinal);
                    Finish(false, "NoValidConfiguredTabs");
                    if (beforeVoyage)
                    {
                        AllflameStopController.Stop(
                            "PreVoyageLootStashUnavailable",
                            "NoValidConfiguredLootTabs=True");
                        return true;
                    }
                    return false;
                }
                AllflameLog.Info(
                    "STASH_TABS_RESOLVED|Destination=" +
                    (_useGuild ? "Guild" : "Personal") +
                    "|Tabs=" + String.Join(",", _tabs));
            }

            if (_tabIndex >= _tabs.Count)
            {
                bool policySession = !_debug;
                string configuredTabs = String.Join(",", _tabs);
                Finish(false, "AllTabsRejectedItem");
                await Coroutines.CloseBlockingWindows();
                if (policySession)
                {
                    AllflameStopController.Stop(
                        "LootStashFull",
                        "AllConfiguredTabsRejectedTransfer=" +
                        configuredTabs);
                    return true;
                }
                return false;
            }

            string targetTab = _tabs[_tabIndex];
            if (!String.Equals(
                    CurrentTabName(),
                    targetTab,
                    StringComparison.OrdinalIgnoreCase))
            {
                object result = SwitchToTab(targetTab);
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(250);
                AllflameLog.Info(
                    "STASH_TAB_SWITCH|Index=" + _tabIndex +
                    "|Tab=" + targetTab +
                    "|Result=" + result);
                return true;
            }

            InventoryControlWrapper inventoryControl =
                LokiPoe.InGameState.InventoryUi.InventoryControl_Main;
            List<Item> inventoryItems =
                inventoryControl == null ||
                inventoryControl.Inventory == null ||
                inventoryControl.Inventory.Items == null
                    ? new List<Item>()
                    : inventoryControl.Inventory.Items.ToList();

            if (_transferPending)
            {
                Item remaining = inventoryItems.FirstOrDefault(candidate =>
                    candidate != null &&
                    candidate.IsValid &&
                    ((candidate.LocalId != 0 &&
                      candidate.LocalId == _pendingItemKey) ||
                     (candidate.LocalId == 0 &&
                      candidate.Id == _pendingItemKey) ||
                     candidate.LocationTopLeft == _pendingLocation));
                bool moved =
                    remaining == null ||
                    Math.Max(1, remaining.StackCount) <
                        _pendingBeforeStack;
                if (moved)
                {
                    int movedKey = _pendingItemKey;
                    DateTime issuedUtc = _transferIssuedUtc;
                    int delayMs = _pendingTransferDelayMs;
                    _attempts.Remove(movedKey);
                    AllflameLog.Info(
                        "STASH_ITEM_MOVED|Tab=" + _pendingTab +
                        "|Name=" + _pendingItemName +
                        "|LocalId=" + _pendingLocalId +
                        "|BeforeStack=" + _pendingBeforeStack +
                        "|AfterStack=" +
                        (remaining == null
                            ? 0
                            : remaining.StackCount) +
                        "|Mode=" + _pendingTransferMode +
                        "|NextDelayMs=" + delayMs +
                        "|ConfirmedOnFreshCycle=True");
                    ResetPendingTransfer();
                    _retryAfterUtc =
                        issuedUtc.AddMilliseconds(delayMs);
                    if (_retryAfterUtc < DateTime.UtcNow)
                    {
                        _retryAfterUtc = DateTime.UtcNow;
                    }
                    return true;
                }

                if (DateTime.UtcNow - _transferIssuedUtc <
                    TimeSpan.FromMilliseconds(650))
                {
                    return true;
                }

                int pendingAttempts;
                _attempts.TryGetValue(
                    _pendingItemKey,
                    out pendingAttempts);
                pendingAttempts++;
                _attempts[_pendingItemKey] = pendingAttempts;
                string failedName = _pendingItemName;
                string failedTab = _pendingTab;
                int failedLocalId = _pendingLocalId;
                int failedKey = _pendingItemKey;
                string failedMode = _pendingTransferMode;
                ResetPendingTransfer();
                AllflameLog.Info(
                    "STASH_ITEM_RETRY|Tab=" + failedTab +
                    "|Name=" + failedName +
                    "|LocalId=" + failedLocalId +
                    "|Attempt=" + pendingAttempts +
                    "|Mode=" + failedMode +
                    "|InputSent=True" +
                    "|StillInInventory=True");
                if (pendingAttempts >= 2)
                {
                    _attempts[failedKey] = 0;
                    _tabIndex++;
                    AllflameLog.Info(
                        "STASH_TAB_FAILSAFE|FailedTab=" + failedTab +
                        "|NextTabIndex=" + _tabIndex +
                        "|Reason=TwoFailedTransfers" +
                        "|Item=" + failedName);
                }
                _retryAfterUtc =
                    DateTime.UtcNow.AddMilliseconds(120);
                return true;
            }

            Item item = inventoryItems.FirstOrDefault(candidate =>
                candidate != null &&
                candidate.IsValid &&
                !AllflameContext.IsChartItem(candidate) &&
                !SecretBottleProcessingTask.ShouldReserveBottle(candidate));
            if (item == null)
            {
                Finish(true, "NoNonChartItemsRemain");
                await Coroutines.CloseBlockingWindows();
                return false;
            }

            int itemKey = item.LocalId != 0
                ? item.LocalId
                : item.Id;
            int attempts;
            _attempts.TryGetValue(itemKey, out attempts);
            int beforeStack = Math.Max(1, item.StackCount);
            int transferDelayMs =
                AllflameTransferTiming.NextDelayMilliseconds(
                    settings);
            bool inputSent = false;
            string transferMode = "CtrlRightClick";
            string inputResult;
            inputSent = await CtrlRightClickInventoryItem(
                inventoryControl,
                item);
            inputResult = inputSent ? "Sent" : "Rejected";

            if (inputSent)
            {
                _transferPending = true;
                _pendingItemKey = itemKey;
                _pendingLocalId = item.LocalId;
                _pendingLocation = item.LocationTopLeft;
                _pendingBeforeStack = beforeStack;
                _pendingTransferDelayMs = transferDelayMs;
                _pendingItemName = item.FullName ?? item.Name ?? String.Empty;
                _pendingTab = targetTab;
                _pendingTransferMode = transferMode;
                _transferIssuedUtc = DateTime.UtcNow;
                AllflameLog.Info(
                    "STASH_ITEM_TRANSFER_ISSUED|Tab=" + targetTab +
                    "|Name=" + _pendingItemName +
                    "|LocalId=" + item.LocalId +
                    "|Mode=" + transferMode +
                    "|Result=" + inputResult +
                    "|Action=ConfirmOnNextCycle" +
                    "|OneActionPerCycle=True");
                return true;
            }

            attempts++;
            _attempts[itemKey] = attempts;
            AllflameLog.Info(
                "STASH_ITEM_RETRY|Tab=" + targetTab +
                "|Name=" + item.FullName +
                "|LocalId=" + item.LocalId +
                "|Attempt=" + attempts +
                "|Mode=" + transferMode +
                "|Result=" + inputResult +
                "|InputSent=False" +
                "|StillInInventory=True");
            if (attempts >= 2)
            {
                _attempts[itemKey] = 0;
                _tabIndex++;
                AllflameLog.Info(
                    "STASH_TAB_FAILSAFE|FailedTab=" + targetTab +
                    "|NextTabIndex=" + _tabIndex +
                    "|Reason=TwoFailedTransfers" +
                    "|Item=" + item.FullName);
            }
            _retryAfterUtc =
                DateTime.UtcNow.AddMilliseconds(120);
            return true;
        }

        private bool IsStashOpened()
        {
            return _useGuild
                ? LokiPoe.InGameState.GuildStashUi.IsOpened
                : LokiPoe.InGameState.StashUi.IsOpened;
        }

        private string CurrentTabName()
        {
            return _useGuild
                ? LokiPoe.InGameState.GuildStashUi.TabControl.CurrentTabName
                : LokiPoe.InGameState.StashUi.TabControl.CurrentTabName;
        }

        private object SwitchToTab(string tabName)
        {
            if (_useGuild)
            {
                var result =
                    LokiPoe.InGameState.GuildStashUi.TabControl
                        .SwitchToTabMouse(tabName);
                if (Convert.ToInt32(result) != 0)
                {
                    result =
                        LokiPoe.InGameState.GuildStashUi.TabControl
                            .SwitchToTabKeyboard(tabName);
                }
                return result;
            }

            var personalResult =
                LokiPoe.InGameState.StashUi.TabControl
                    .SwitchToTabMouse(tabName);
            if (Convert.ToInt32(personalResult) != 0)
            {
                personalResult =
                    LokiPoe.InGameState.StashUi.TabControl
                        .SwitchToTabKeyboard(tabName);
            }
            return personalResult;
        }

        private List<string> ResolveConfiguredTabs(string configured)
        {
            List<string> available = _useGuild
                ? LokiPoe.InGameState.GuildStashUi.TabControl.TabNames
                : LokiPoe.InGameState.StashUi.TabControl.TabNames;
            var resolved = new List<string>();
            if (available == null || available.Count == 0)
            {
                return resolved;
            }

            foreach (string raw in (configured ?? String.Empty)
                .Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries))
            {
                string token = raw.Trim();
                string exact = available.FirstOrDefault(name =>
                    String.Equals(
                        name,
                        token,
                        StringComparison.OrdinalIgnoreCase));
                if (String.IsNullOrEmpty(exact))
                {
                    int number;
                    if (Int32.TryParse(token, out number) &&
                        number >= 1 &&
                        number <= available.Count)
                    {
                        exact = available[number - 1];
                    }
                }
                if (!String.IsNullOrEmpty(exact) &&
                    !resolved.Contains(
                        exact,
                        StringComparer.OrdinalIgnoreCase))
                {
                    resolved.Add(exact);
                }
            }
            return resolved;
        }

        private static NetworkObject FindStashObject(bool guild)
        {
            try
            {
                if (!guild)
                {
                    return AllflameContext.StashObject;
                }

                return LokiPoe.ObjectManager.Objects
                    .Where(obj => obj != null && obj.IsValid)
                    .OrderBy(obj => obj.Distance)
                    .FirstOrDefault(obj =>
                    {
                        string name = obj.Name ?? String.Empty;
                        string metadata = obj.Metadata ?? String.Empty;
                        return name.IndexOf(
                                   "Guild Stash",
                                   StringComparison.OrdinalIgnoreCase) >= 0 ||
                               metadata.IndexOf(
                                   "GuildStash",
                                   StringComparison.OrdinalIgnoreCase) >= 0;
                    });
            }
            catch
            {
                return null;
            }
        }

        private static Item FindInventoryItem(
            int itemKey,
            Item original)
        {
            try
            {
                InventoryControlWrapper control =
                    LokiPoe.InGameState.InventoryUi.InventoryControl_Main;
                if (control == null ||
                    control.Inventory == null ||
                    control.Inventory.Items == null)
                {
                    return null;
                }

                return control.Inventory.Items.FirstOrDefault(item =>
                    item != null &&
                    ((item.LocalId != 0 &&
                      item.LocalId == itemKey) ||
                     (item.LocalId == 0 &&
                      item.Id == itemKey) ||
                     (original != null &&
                      item.LocationTopLeft ==
                          original.LocationTopLeft)));
            }
            catch
            {
                return original;
            }
        }

        private static int CountNonChartInventoryItems()
        {
            try
            {
                InventoryControlWrapper control =
                    LokiPoe.InGameState.InventoryUi.InventoryControl_Main;
                return control == null ||
                    control.Inventory == null ||
                    control.Inventory.Items == null
                        ? 0
                        : control.Inventory.Items.Count(item =>
                            item != null &&
                            item.IsValid &&
                            !AllflameContext.IsChartItem(item) &&
                            !SecretBottleProcessingTask.ShouldReserveBottle(item));
            }
            catch
            {
                return 0;
            }
        }

        private void ResetPendingTransfer()
        {
            _transferPending = false;
            _pendingItemKey = 0;
            _pendingLocalId = 0;
            _pendingLocation = default(Vector2i);
            _pendingBeforeStack = 0;
            _pendingTransferDelayMs = 0;
            _pendingItemName = String.Empty;
            _pendingTab = String.Empty;
            _pendingTransferMode = String.Empty;
            _transferIssuedUtc = DateTime.MinValue;
        }

        private static async Task<bool> CtrlRightClickInventoryItem(
            InventoryControlWrapper inventoryControl,
            Item item)
        {
            if (inventoryControl == null || item == null)
            {
                return false;
            }

            try
            {
                var slotUi = inventoryControl.InventorySlotUiElement;
                if (slotUi == null)
                {
                    return false;
                }

                Element itemElement = null;
                try
                {
                    var elements = slotUi.DictionaryIdElements;
                    if (elements != null)
                    {
                        if (!elements.TryGetValue(
                                item.LocalId,
                                out itemElement))
                        {
                            elements.TryGetValue(
                                item.Id,
                                out itemElement);
                        }
                    }
                }
                catch
                {
                    itemElement = null;
                }

                Vector2i clickLocation =
                    itemElement != null &&
                    itemElement.IsValid &&
                    itemElement.IsVisible
                        ? itemElement.CenterClickLocation()
                        : slotUi.SlotClickLocation(
                            new Vector2i(
                                item.LocationTopLeft.X + 1,
                                item.LocationTopLeft.Y + 1));
                bool controlDown = false;
                try
                {
                    LokiPoe.ProcessHookManager.ClearAllKeyStates();
                    DreamPoeBot.BotFramework.MouseManager.SetMousePosition(
                        clickLocation,
                        true);
                    await LokiCoroutine.Sleep(10);
                    LokiPoe.ProcessHookManager.SetKeyState(
                        System.Windows.Forms.Keys.ControlKey,
                        short.MinValue,
                        System.Windows.Forms.Keys.None);
                    controlDown = true;
                    await LokiCoroutine.Sleep(15);
                    DreamPoeBot.BotFramework.MouseManager.ClickRMB(0, 0);
                    await LokiCoroutine.Sleep(45);
                }
                finally
                {
                    if (controlDown)
                    {
                        LokiPoe.ProcessHookManager.SetKeyState(
                            System.Windows.Forms.Keys.ControlKey,
                            (short)0,
                            System.Windows.Forms.Keys.None);
                    }
                    LokiPoe.ProcessHookManager.ClearAllKeyStates();
                }
                return true;
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "STASH_CTRL_RIGHT_CLICK_FAILED|Name=" +
                    item.FullName +
                    "|LocalId=" + item.LocalId +
                    "|Error=" + ex.Message.Replace("|", "/"));
                return false;
            }
        }

        private void Finish(bool success, string reason)
        {
            AllflameLog.Info(
                "STASH_SESSION_DONE|Success=" + success +
                "|Reason=" + reason +
                "|Mode=" + (_debug ? "Debug" : "Policy") +
                "|LastTabIndex=" + _tabIndex);
            if (_debug)
            {
                AllflameStashDebug.Complete();
            }
            else
            {
                if (success &&
                    String.Equals(
                        _reason,
                        "AfterCollectLoot",
                        StringComparison.Ordinal))
                {
                    VoyageRunState.MarkSurfaceStashed();
                }
                _nextPolicySessionUtc = DateTime.UtcNow.AddSeconds(
                    success ? 3 : 10);
            }
            _active = false;
            _debug = false;
            _tabs.Clear();
            _attempts.Clear();
            ResetPendingTransfer();
            _tabIndex = 0;
            _retryAfterUtc = DateTime.MinValue;
            _reason = String.Empty;
        }
    }

    internal sealed class ReturnToHubTask : ObserverTask
    {
        private int _directMoveFailures;
        private int _extractionInteractFailures;
        private DateTime _nextExtractionInteractUtc =
            DateTime.MinValue;
        private DateTime _waitForAreaTransitionUntilUtc =
            DateTime.MinValue;
        private DateTime _outsideLanternAuraSinceUtc =
            DateTime.MinValue;
        private bool _emergencyBreadcrumbReturn;

        public ReturnToHubTask()
            : base("ReturnToHubTask", "Returns to The Sovereign when Chart exploration is complete.") { }

        public override async Task<bool> Run()
        {
            if (!AllflameContext.IsChartMapArea)
            {
                _directMoveFailures = 0;
                _extractionInteractFailures = 0;
                _nextExtractionInteractUtc =
                    DateTime.MinValue;
                _waitForAreaTransitionUntilUtc = DateTime.MinValue;
                _outsideLanternAuraSinceUtc = DateTime.MinValue;
                _emergencyBreadcrumbReturn = false;
                return false;
            }

            bool lanternsExhausted =
                AllflameRunState.LanternsExhausted;
            if (!AllflameRunState.ChartTimedOut &&
                !lanternsExhausted)
            {
                return false;
            }

            if (AllflameLootState.CommittedChestLootActive)
            {
                AllflameLog.Throttled(
                    "chart_return_wait_committed_loot",
                    TimeSpan.FromSeconds(1),
                    "CHART_RETURN_WAIT" +
                    "|Reason=CommittedChestLoot" +
                    "|Action=WaitForLootBeforeBathysphere" +
                    "|Counter=" +
                    AllflameContext.LanternCounterCurrent + "/" +
                    AllflameContext.LanternCounterMaximum);
                return false;
            }

            if (DateTime.UtcNow < _waitForAreaTransitionUntilUtc)
            {
                return true;
            }

            string reason = lanternsExhausted
                ? "LanternsExhausted"
                : (AllflameRunState.ChartTimedOut
                    ? "ChartTimeout"
                    : "ExplorationComplete");
            AllflameLog.Throttled(
                "chart_return",
                TimeSpan.FromSeconds(3),
                "ACTION|Task=" + Name + "|Action=ReturnToSovereign|Reason=" + reason +
                "|Explore=" + AllflameRunState.ExplorationPercent.ToString("0.0"));

            if (lanternsExhausted &&
                !AllflameContext.LanternAuraActive)
            {
                if (_outsideLanternAuraSinceUtc == DateTime.MinValue)
                {
                    _outsideLanternAuraSinceUtc = DateTime.UtcNow;
                }
                else if (!_emergencyBreadcrumbReturn &&
                         DateTime.UtcNow - _outsideLanternAuraSinceUtc >=
                             TimeSpan.FromSeconds(2))
                {
                    _emergencyBreadcrumbReturn = true;
                    AllflameLog.Info(
                        "EMERGENCY_BREADCRUMB_RETURN" +
                        "|Reason=OutsideLanternAuraFor2Seconds" +
                        "|CachedExtraction=" +
                        AllflameRunState.LastExtractionPosition +
                        "|LanternWaypoints=" +
                        AllflameContext.PlacedLanterns +
                        "|OutwardBreadcrumbs=" +
                        AllflameRunState.OutwardBreadcrumbCount +
                        "|Action=PreferReverseSafeRoute");
                }
            }
            else
            {
                _outsideLanternAuraSinceUtc = DateTime.MinValue;
            }

            // The return object has appeared under both ExtractionObject and
            // ChartPortal/Bathysphere metadata across DPB builds. Version
            // 0.15.0's reliable behavior was to accept either representation.
            NetworkObject extraction =
                AllflameContext.ExtractionObject ??
                AllflameContext.BathysphereObject;
            if (extraction != null)
            {
                _directMoveFailures = 0;
                if (extraction.Distance >
                    AllflameSettings.Instance.InteractDistance)
                {
                    bool moving =
                        AllflameMovementCoordinator.MoveTowards(
                            extraction.Position,
                            Name);
                    AllflameLog.Throttled(
                        "chart_return_move",
                        TimeSpan.FromSeconds(2),
                        "ACTION|Task=" + Name +
                        "|Action=MoveToBathysphere" +
                        "|Object=" +
                        (String.IsNullOrEmpty(extraction.Name)
                            ? "Unknown"
                            : extraction.Name) +
                        "|Distance=" +
                        extraction.Distance.ToString("0.0") +
                        "|Targetable=" +
                        extraction.IsTargetable +
                        "|Moving=" + moving);
                    return true;
                }

                if (!extraction.IsTargetable)
                {
                    AllflameLog.Throttled(
                        "chart_return_wait_targetable",
                        TimeSpan.FromSeconds(2),
                        "ACTION|Task=" + Name +
                        "|Action=WaitAtBathysphere" +
                        "|Targetable=False");
                    return true;
                }

                if (DateTime.UtcNow <
                    _nextExtractionInteractUtc)
                {
                    return true;
                }

                bool interacted =
                    await InteractWithRecovery(extraction);
                if (interacted)
                {
                    _extractionInteractFailures = 0;
                    _nextExtractionInteractUtc =
                        DateTime.MinValue;
                    AllflameRunState.MarkBathysphereExitRequested();
                    _waitForAreaTransitionUntilUtc =
                        DateTime.UtcNow.AddMilliseconds(650);
                }
                else
                {
                    _extractionInteractFailures++;
                    int retryDelayMs =
                        Math.Min(
                            2500,
                            800 +
                            _extractionInteractFailures * 350);
                    _nextExtractionInteractUtc =
                        DateTime.UtcNow.AddMilliseconds(
                            retryDelayMs);
                    AllflameMovementCoordinator.MoveTowards(
                        extraction.Position,
                        Name + " highlight recovery");
                    AllflameLog.Info(
                        "BATHYSPHERE_INTERACT_RECOVERY" +
                        "|Failure=" +
                        _extractionInteractFailures +
                        "|RetryDelayMs=" + retryDelayMs +
                        "|Action=Reposition");
                }
                AllflameLog.Info(
                    "ACTION|Task=" + Name +
                    "|Action=EnterBathysphere" +
                    "|Object=" +
                    (String.IsNullOrEmpty(extraction.Name)
                        ? "Unknown"
                        : extraction.Name) +
                    "|Success=" + interacted +
                    "|Reason=" + reason);
                return true;
            }

            if (lanternsExhausted &&
                _emergencyBreadcrumbReturn &&
                LokiPoe.Me != null)
            {
                Vector2i lanternWaypoint;
                int lanternOrder;
                if (AllflameRunState.TryGetReverseLanternWaypoint(
                    LokiPoe.Me.Position,
                    out lanternWaypoint,
                    out lanternOrder))
                {
                    bool emergencyMoving =
                        AllflameMovementCoordinator.MoveTowards(
                            lanternWaypoint,
                            Name + " emergency lantern return");
                    AllflameLog.Throttled(
                        "emergency_lantern_return",
                        TimeSpan.FromSeconds(1),
                        "EMERGENCY_BREADCRUMB_RETURN" +
                        "|Route=Lantern" +
                        "|Order=" + lanternOrder +
                        "|Position=" + lanternWaypoint +
                        "|Moving=" + emergencyMoving);
                    if (emergencyMoving)
                    {
                        return true;
                    }
                }

                Vector2i emergencyWaypoint;
                int emergencyStep;
                if (AllflameRunState.TryGetReverseOutwardWaypoint(
                    LokiPoe.Me.Position,
                    out emergencyWaypoint,
                    out emergencyStep))
                {
                    bool emergencyMoving =
                        AllflameMovementCoordinator.MoveTowards(
                            emergencyWaypoint,
                            Name + " emergency breadcrumb return");
                    AllflameLog.Throttled(
                        "emergency_outward_return",
                        TimeSpan.FromSeconds(1),
                        "EMERGENCY_BREADCRUMB_RETURN" +
                        "|Route=Outward" +
                        "|Step=" + emergencyStep +
                        "|Position=" + emergencyWaypoint +
                        "|Moving=" + emergencyMoving);
                    if (emergencyMoving)
                    {
                        return true;
                    }
                }
            }

            if (AllflameRunState.HasExtractionPosition)
            {
                bool moving =
                    AllflameMovementCoordinator.MoveTowards(
                        AllflameRunState.LastExtractionPosition,
                        Name);
                if (moving)
                {
                    _directMoveFailures = 0;
                    AllflameLog.Throttled(
                        "chart_return_cached",
                        TimeSpan.FromSeconds(2),
                        "ACTION|Task=" + Name +
                        "|Action=MoveDirectToCachedBathysphere" +
                        "|Position=" +
                        AllflameRunState.LastExtractionPosition +
                        "|Moving=True");
                    return true;
                }

                _directMoveFailures++;
                AllflameLog.Throttled(
                    "chart_return_cached",
                    TimeSpan.FromSeconds(2),
                    "ACTION|Task=" + Name +
                    "|Action=MoveDirectToCachedBathysphere" +
                    "|Position=" +
                    AllflameRunState.LastExtractionPosition +
                    "|Moving=False" +
                    "|Failures=" + _directMoveFailures);
                if (_directMoveFailures < 2)
                {
                    return true;
                }
            }

            // Only use the recorded route when the direct navmesh route fails.
            if (lanternsExhausted && LokiPoe.Me != null)
            {
                Vector2i outwardWaypoint;
                int outwardStep;
                if (AllflameRunState.TryGetReverseOutwardWaypoint(
                    LokiPoe.Me.Position,
                    out outwardWaypoint,
                    out outwardStep))
                {
                    bool routeMoving =
                        AllflameMovementCoordinator.MoveTowards(
                            outwardWaypoint,
                            Name);
                    AllflameLog.Throttled(
                        "outward_reverse_route",
                        TimeSpan.FromSeconds(2),
                        "OUTWARD_ROUTE_RETURN|Step=" +
                        outwardStep +
                        "|Position=" + outwardWaypoint +
                        "|Direction=FallbackReverse" +
                        "|Moving=" + routeMoving);
                    return true;
                }
            }

            AllflameLog.Throttled(
                "chart_return_missing",
                TimeSpan.FromSeconds(2),
                "ACTION|Task=" + Name +
                "|Action=SearchBathysphere" +
                "|Reason=NoKnownExtractionPosition");
            return false;
        }

    }

    internal sealed class StuckRecoveryTask : ObserverTask
    {
        private const int MaximumAttempts = 8;
        private static readonly Vector2i[] EscapeOffsets =
        {
            new Vector2i(110, 0),
            new Vector2i(78, 78),
            new Vector2i(0, 110),
            new Vector2i(-78, 78),
            new Vector2i(-110, 0),
            new Vector2i(-78, -78),
            new Vector2i(0, -110),
            new Vector2i(78, -78)
        };
        private DateTime _nextAttemptUtc = DateTime.MinValue;
        private Vector2i _recoveryOrigin;
        private int _attempt;

        public StuckRecoveryTask()
            : base("StuckRecoveryTask", "Recovers when task, target, position and UI make no progress.") { }

        public override Task<bool> Run()
        {
            if (AllflameProgressWatchdog.TryConsumeRecovery(
                    "ReloadPathAndRefreshState"))
            {
                try
                {
                    ExilePather.Reload(true);
                }
                catch
                {
                }
                AllflameContext.RequestRefresh(
                    "StuckRecovery");
                AllflameProgressWatchdog.MarkProgress(
                    "RecoveryStateRefresh");
                return Task.FromResult(true);
            }

            if (!AllflameContext.IsPotentiallyStuck ||
                !AllflameContext.IsVoyageMapArea ||
                LokiPoe.Me == null)
            {
                _attempt = 0;
                _nextAttemptUtc = DateTime.MinValue;
                return Task.FromResult(false);
            }

            Vector2i player = LokiPoe.Me.Position;
            if (_attempt > 0 &&
                player.DistanceF(_recoveryOrigin) >= 35f)
            {
                AllflameLog.Info(
                    "STUCK_RECOVERY_COMPLETE" +
                    "|Origin=" + _recoveryOrigin +
                    "|Player=" + player +
                    "|Distance=" +
                    player.DistanceF(_recoveryOrigin).ToString("0.0") +
                    "|Attempts=" + _attempt);
                _attempt = 0;
                _nextAttemptUtc = DateTime.MinValue;
                AllflameProgressWatchdog.MarkProgress(
                    "StationaryRecoveryMovement");
                return Task.FromResult(false);
            }

            if (DateTime.UtcNow < _nextAttemptUtc)
            {
                return Task.FromResult(false);
            }

            if (_attempt >= MaximumAttempts)
            {
                AllflameLog.Throttled(
                    "stuck_recovery_exhausted",
                    TimeSpan.FromSeconds(10),
                    "STUCK_RECOVERY_EXHAUSTED" +
                    "|Origin=" + _recoveryOrigin +
                    "|Attempts=" + _attempt +
                    "|Action=YieldWithoutStoppingBot");
                _attempt = 0;
                _nextAttemptUtc =
                    DateTime.UtcNow + TimeSpan.FromSeconds(10);
                return Task.FromResult(false);
            }

            if (_attempt == 0)
            {
                _recoveryOrigin = player;
                try
                {
                    ExilePather.Reload(true);
                }
                catch (Exception ex)
                {
                    AllflameLog.Throttled(
                        "stuck_recovery_reload_failed",
                        TimeSpan.FromSeconds(5),
                        "STUCK_RECOVERY_WARNING" +
                        "|Step=ReloadPath" +
                        "|Error=" + ex.GetType().Name +
                        ":" + ex.Message);
                }
            }

            int candidateIndex = _attempt % EscapeOffsets.Length;
            Vector2i offset = EscapeOffsets[candidateIndex];
            Vector2i requested = new Vector2i(
                player.X + offset.X,
                player.Y + offset.Y);
            Vector2i resolved;
            Vector2i hit;
            bool clipped;
            bool valid = VoyageRollingFrontierPlanner.TryResolveRaycastTarget(
                player,
                requested,
                out resolved,
                out hit,
                out clipped);
            _attempt++;
            _nextAttemptUtc =
                DateTime.UtcNow + TimeSpan.FromSeconds(2);

            if (!valid || player.DistanceF(resolved) < 24f)
            {
                AllflameLog.Info(
                    "STUCK_RECOVERY_CANDIDATE_REJECTED" +
                    "|Attempt=" + _attempt +
                    "|Requested=" + requested +
                    "|Hit=" + hit +
                    "|Reason=BlockedOrTooShort");
                return Task.FromResult(true);
            }

            bool moving;
            try
            {
                moving = AllflameMovementCoordinator.MoveTowards(resolved, Name);
            }
            catch (Exception ex)
            {
                AllflameLog.Info(
                    "STUCK_RECOVERY_MOVE_FAILED" +
                    "|Attempt=" + _attempt +
                    "|Target=" + resolved +
                    "|Error=" + ex.GetType().Name +
                    ":" + ex.Message);
                return Task.FromResult(true);
            }

            AllflameLog.Info(
                "STUCK_RECOVERY_MOVE" +
                "|Attempt=" + _attempt +
                "/" + MaximumAttempts +
                "|Origin=" + _recoveryOrigin +
                "|From=" + player +
                "|Target=" + resolved +
                "|Raycast=" + (clipped ? "Clipped" : "Clear") +
                "|Moving=" + moving);
            return Task.FromResult(true);
        }
    }

    internal sealed class ObservationFallbackTask : ObserverTask
    {
        public ObservationFallbackTask()
            : base("ObservationFallbackTask", "Handles the loop without sending game input.") { }

        public override Task<bool> Run()
        {
            AllflameLog.Throttled(
                Name,
                TimeSpan.FromSeconds(15),
                "OBSERVER_HEARTBEAT|" + AllflameContext.Describe());
            return Task.FromResult(true);
        }
    }

    internal static class AllflameLog
    {
        private static readonly object Sync = new object();
        private static readonly Dictionary<string, DateTime> NextMessages =
            new Dictionary<string, DateTime>(StringComparer.OrdinalIgnoreCase);
        private static string _path;

        public static void Initialize()
        {
            lock (Sync)
            {
                if (!String.IsNullOrEmpty(_path))
                {
                    return;
                }

                string directory = Path.Combine(
                    AppDomain.CurrentDomain.BaseDirectory,
                    "Logs",
                    "AllflameBot");
                Directory.CreateDirectory(directory);
                _path = Path.Combine(
                    directory,
                    "AllflameBot_" +
                    DateTime.Now.ToString("yyyy-MM-dd_HH-mm-ss") +
                    "_pid-" +
                    System.Diagnostics.Process.GetCurrentProcess().Id +
                    ".log");
                Info(
                    "LOG_INITIALIZED|Path=" + _path +
                    "|ProcessId=" +
                    System.Diagnostics.Process.GetCurrentProcess().Id +
                    "|DPBVersion=" +
                    typeof(LokiPoe).Assembly.GetName().Version);
            }
        }

        public static void Info(string message)
        {
            Append("INFO|" + message);
        }

        public static void Error(string label, Exception ex)
        {
            Append(
                "ERROR|" + label + "|" + ex.GetType().FullName + "|" +
                Sanitize(ex.Message) + "|" + Sanitize(ex.StackTrace));
        }

        public static void Throttled(string key, TimeSpan interval, string message)
        {
            lock (Sync)
            {
                DateTime now = DateTime.UtcNow;
                DateTime next;
                if (NextMessages.TryGetValue(key, out next) && now < next)
                {
                    return;
                }

                NextMessages[key] = now.Add(interval);
                Append(message);
            }
        }

        private static void Append(string message)
        {
            lock (Sync)
            {
                try
                {
                    if (String.IsNullOrEmpty(_path))
                    {
                        return;
                    }

                    File.AppendAllText(
                        _path,
                        DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss.fff") +
                        " " + Sanitize(message) + Environment.NewLine,
                        Encoding.UTF8);
                }
                catch
                {
                }
            }
        }

        private static string Sanitize(string value)
        {
            return String.IsNullOrEmpty(value)
                ? String.Empty
                : value.Replace("\r", "\\r").Replace("\n", "\\n");
        }
    }
}
